class _CPythonDequeHeader(ctypes.Structure):
    """Stable prefix of CPython's deque object through Python 3.12."""

    _fields_ = (
        ("ob_refcnt", ctypes.c_ssize_t),
        ("ob_type", ctypes.c_void_p),
        ("ob_size", ctypes.c_ssize_t),
        ("leftblock", ctypes.c_void_p),
        ("rightblock", ctypes.c_void_p),
        ("leftindex", ctypes.c_ssize_t),
        ("rightindex", ctypes.c_ssize_t),
        ("state", ctypes.c_size_t),
        ("maxlen", ctypes.c_ssize_t),
        ("numfreeblocks", ctypes.c_ssize_t),
        ("freeblocks", ctypes.c_void_p * 16),
        ("weakreflist", ctypes.c_void_p),
    )


class _CPythonDequeBlock(ctypes.Structure):
    """One CPython deque block through Python 3.12."""

    _fields_ = (
        ("leftlink", ctypes.c_void_p),
        ("data", ctypes.c_void_p * 64),
        ("rightlink", ctypes.c_void_p),
    )


def _read_cpython_dict_version(value: dict[Any, Any]) -> Optional[int]:
    """Return the mutation version without invoking Python mapping hooks."""

    if sys.implementation.name != "cpython":
        return None
    try:
        return int(_CPythonDictHeader.from_address(id(value)).ma_version_tag)
    except (TypeError, ValueError):
        return None


def _cpython_dict_version_layout_is_valid() -> bool:
    probe: dict[object, object] = {}
    key = object()
    first = _read_cpython_dict_version(probe)
    probe[key] = key
    second = _read_cpython_dict_version(probe)
    probe.pop(key)
    third = _read_cpython_dict_version(probe)
    return bool(
        type(first) is int
        and type(second) is int
        and type(third) is int
        and first != second
        and second != third
    )


_CPYTHON_DICT_VERSION_LAYOUT_VALID = _cpython_dict_version_layout_is_valid()


def _read_cpython_deque_state(
    value: collections.deque[Any],
) -> Optional[tuple[Any, ...]]:
    """Return mutation state and endpoint blocks without Python callbacks."""

    if (
        sys.implementation.name != "cpython"
        or tuple(sys.version_info[:2]) not in _ROLLBACK_CPYTHON_TABLE_LAYOUT_VERSIONS
    ):
        return None
    try:
        header = _CPythonDequeHeader.from_address(id(value))
        return (
            int(header.state),
            int(header.leftblock or 0),
            int(header.rightblock or 0),
            int(header.leftindex),
            int(header.rightindex),
            int(header.ob_size),
            int(header.maxlen),
            int(header.numfreeblocks),
            tuple(
                int(header.freeblocks[index] or 0)
                for index in range(int(header.numfreeblocks))
            ),
        )
    except (TypeError, ValueError):
        return None


def _cpython_deque_state_layout_is_valid() -> bool:
    probe = collections.deque((object(), object()))
    before = _read_cpython_deque_state(probe)
    collections.deque.rotate(probe, 1)
    after = _read_cpython_deque_state(probe)
    return bool(
        before is not None
        and after is not None
        and before[1:3] == after[1:3]
        and after[0] == before[0] + 1
    )


_CPYTHON_DEQUE_STATE_LAYOUT_VALID = _cpython_deque_state_layout_is_valid()


def _cpython_set_iterator_layout_is_valid() -> bool:
    first = object()
    second = object()
    values = {first, second}
    iterator = set.__iter__(values)
    next(iterator)
    try:
        header = _CPythonSetIteratorHeader.from_address(id(iterator))
        return bool(
            int(header.si_set or 0) == id(values)
            and int(header.si_used) == 2
            and int(header.length) == 1
            and int(header.si_pos) > 0
        )
    except (TypeError, ValueError):
        return False


_CPYTHON_SET_ITERATOR_LAYOUT_VALID = _cpython_set_iterator_layout_is_valid()


def _rollback_restore_deque_state(
    value: collections.deque[Any],
    saved_items: Sequence[Any],
    saved_state: int,
    saved_leftblock: int,
    saved_rightblock: int,
    saved_leftindex: int,
    saved_rightindex: int,
    saved_size: int,
    saved_maxlen: int,
    saved_numfreeblocks: int,
    _saved_freeblocks: tuple[int, ...],
) -> bool:
    """Restore iterator-visible state when the original blocks remain owned."""

    if not _CPYTHON_DEQUE_STATE_LAYOUT_VALID:
        return False
    current = _read_cpython_deque_state(value)
    if current is None:
        return False
    if current[1:3] == (saved_leftblock, saved_rightblock):
        try:
            if _CPYTHON_INCREF is None or _CPYTHON_DECREF is None:
                return False
            current_items = list(collections.deque.__iter__(value))
            if len(current_items) != saved_size or saved_size != len(saved_items):
                return False
            positions: List[tuple[_CPythonDequeBlock, int]] = []
            block_pointer = saved_leftblock
            index = saved_leftindex
            for _item in saved_items:
                if index == 64:
                    block = _CPythonDequeBlock.from_address(block_pointer)
                    block_pointer = int(block.rightlink or 0)
                    index = 0
                if not block_pointer:
                    return False
                positions.append(
                    (_CPythonDequeBlock.from_address(block_pointer), index)
                )
                index += 1
            if positions and block_pointer != saved_rightblock:
                return False
            for item in saved_items:
                _CPYTHON_INCREF(item)
            for (block, slot_index), item in zip(positions, saved_items):
                block.data[slot_index] = id(item)
            header = _CPythonDequeHeader.from_address(id(value))
            header.leftindex = saved_leftindex
            header.rightindex = saved_rightindex
            header.state = saved_state
            header.maxlen = saved_maxlen
            for item in current_items:
                _CPYTHON_DECREF(item)
            return True
        except (TypeError, ValueError):
            return False
    if (
        _CPYTHON_INCREF is None
        or saved_leftblock != saved_rightblock
        or saved_numfreeblocks != 0
        or saved_size != len(saved_items)
        or saved_size < 0
        or saved_size > 64
        or saved_leftindex < 0
        or saved_rightindex >= 64
        or saved_leftindex + saved_size - 1 != saved_rightindex
        or current[8].count(saved_leftblock) != 1
    ):
        return False
    try:
        header = _CPythonDequeHeader.from_address(id(value))
        holder = collections.deque()
        holder_header = _CPythonDequeHeader.from_address(id(holder))
        scalar_fields = (
            "ob_size",
            "leftblock",
            "rightblock",
            "leftindex",
            "rightindex",
            "state",
            "maxlen",
            "numfreeblocks",
        )
        for field_name in scalar_fields:
            current_value = getattr(header, field_name)
            setattr(header, field_name, getattr(holder_header, field_name))
            setattr(holder_header, field_name, current_value)
        current_freeblocks = tuple(header.freeblocks)
        holder_freeblocks = tuple(holder_header.freeblocks)
        for index in range(16):
            header.freeblocks[index] = holder_freeblocks[index]
            holder_header.freeblocks[index] = current_freeblocks[index]

        spare_block = int(header.leftblock or 0)
        retained_freeblocks = [
            int(holder_header.freeblocks[index] or 0)
            for index in range(int(holder_header.numfreeblocks))
            if int(holder_header.freeblocks[index] or 0) != saved_leftblock
        ]
        if len(retained_freeblocks) >= 16 or not spare_block:
            return False
        retained_freeblocks.append(spare_block)
        for index in range(16):
            holder_header.freeblocks[index] = (
                retained_freeblocks[index] if index < len(retained_freeblocks) else None
            )
            header.freeblocks[index] = None
        holder_header.numfreeblocks = len(retained_freeblocks)
        header.numfreeblocks = 0

        block = _CPythonDequeBlock.from_address(saved_leftblock)
        for item in saved_items:
            _CPYTHON_INCREF(item)
        for offset, item in enumerate(saved_items):
            block.data[saved_leftindex + offset] = id(item)
        header.ob_size = saved_size
        header.leftblock = saved_leftblock
        header.rightblock = saved_rightblock
        header.leftindex = saved_leftindex
        header.rightindex = saved_rightindex
        header.state = saved_state
        header.maxlen = saved_maxlen
        return True
    except (TypeError, ValueError):
        return False


try:
    _CPYTHON_DICT_NEXT = ctypes.pythonapi._PyDict_Next
    _CPYTHON_DICT_NEXT.argtypes = (
        ctypes.py_object,
        ctypes.POINTER(ctypes.c_ssize_t),
        ctypes.POINTER(ctypes.py_object),
        ctypes.POINTER(ctypes.py_object),
        ctypes.POINTER(ctypes.c_ssize_t),
    )
    _CPYTHON_DICT_NEXT.restype = ctypes.c_int
    _CPYTHON_DICT_SET_KNOWN_HASH = ctypes.pythonapi._PyDict_SetItem_KnownHash
    _CPYTHON_DICT_SET_KNOWN_HASH.argtypes = (
        ctypes.py_object,
        ctypes.py_object,
        ctypes.py_object,
        ctypes.c_ssize_t,
    )
    _CPYTHON_DICT_SET_KNOWN_HASH.restype = ctypes.c_int
    _CPYTHON_SET_NEXT = ctypes.pythonapi._PySet_NextEntry
    _CPYTHON_SET_NEXT.argtypes = (
        ctypes.py_object,
        ctypes.POINTER(ctypes.c_ssize_t),
        ctypes.POINTER(ctypes.py_object),
        ctypes.POINTER(ctypes.c_ssize_t),
    )
    _CPYTHON_SET_NEXT.restype = ctypes.c_int
    _CPYTHON_INCREF = ctypes.pythonapi.Py_IncRef
    _CPYTHON_INCREF.argtypes = (ctypes.py_object,)
    _CPYTHON_INCREF.restype = None
    _CPYTHON_DECREF = ctypes.pythonapi.Py_DecRef
    _CPYTHON_DECREF.argtypes = (ctypes.py_object,)
    _CPYTHON_DECREF.restype = None
except AttributeError:  # pragma: no cover - non-CPython fallback
    _CPYTHON_DICT_NEXT = None
    _CPYTHON_DICT_SET_KNOWN_HASH = None
    _CPYTHON_SET_NEXT = None
    _CPYTHON_INCREF = None
    _CPYTHON_DECREF = None


def _rollback_dict_version(value: dict[Any, Any]) -> Optional[int]:
    if not _CPYTHON_DICT_VERSION_LAYOUT_VALID:
        return None
    return _read_cpython_dict_version(value)


def _rollback_dict_entries_with_hashes(
    value: dict[Any, Any],
) -> Optional[List[tuple[Any, Any, int]]]:
    """Read exact dictionary entries with their already-computed hashes."""

    if _CPYTHON_DICT_NEXT is None:
        return None
    position = ctypes.c_ssize_t()
    key = ctypes.py_object()
    item = ctypes.py_object()
    key_hash = ctypes.c_ssize_t()
    entries: List[tuple[Any, Any, int]] = []
    while _CPYTHON_DICT_NEXT(
        value,
        ctypes.byref(position),
        ctypes.byref(key),
        ctypes.byref(item),
        ctypes.byref(key_hash),
    ):
        entries.append((key.value, item.value, int(key_hash.value)))
    return entries


def _rollback_dict_setitem_known_hash(
    value: dict[Any, Any],
    key: Any,
    item: Any,
    key_hash: int,
) -> bool:
    """Replace an existing value without evaluating its key again."""

    if _CPYTHON_DICT_SET_KNOWN_HASH is None:
        return False
    return _CPYTHON_DICT_SET_KNOWN_HASH(value, key, item, key_hash) == 0


def _rollback_dict_table_snapshot(value: dict[Any, Any]) -> Optional[tuple[Any, ...]]:
    """Capture the exact combined dictionary table, including dummy entries."""

    if not _rollback_cpython_table_layout_is_supported():
        return None
    try:
        header = _CPythonDictHeader.from_address(id(value))
        if not header.ma_keys or header.ma_values:
            return None
        keys_header = _CPythonDictKeysHeader.from_address(header.ma_keys)
        table_size = 1 << int(keys_header.dk_log2_size)
        indices_size = 1 << int(keys_header.dk_log2_index_bytes)
        kind = int(keys_header.dk_kind)
        entry_count = int(keys_header.dk_nentries)
        if table_size < 1 or entry_count < 0 or kind not in {0, 1, 2}:
            return None
        entries_address = (
            int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader) + indices_size
        )
        entries: List[tuple[int, Any, int, Any, int]] = []
        if kind == 0:
            table = (_CPythonDictKeyEntry * entry_count).from_address(entries_address)
            for entry in table:
                key_pointer = int(entry.key or 0)
                value_pointer = int(entry.value or 0)
                entries.append(
                    (
                        key_pointer,
                        ctypes.cast(key_pointer, ctypes.py_object).value
                        if key_pointer
                        else None,
                        value_pointer,
                        ctypes.cast(value_pointer, ctypes.py_object).value
                        if value_pointer
                        else None,
                        int(entry.hash),
                    )
                )
        else:
            table = (_CPythonDictUnicodeEntry * entry_count).from_address(
                entries_address
            )
            for entry in table:
                key_pointer = int(entry.key or 0)
                value_pointer = int(entry.value or 0)
                entries.append(
                    (
                        key_pointer,
                        ctypes.cast(key_pointer, ctypes.py_object).value
                        if key_pointer
                        else None,
                        value_pointer,
                        ctypes.cast(value_pointer, ctypes.py_object).value
                        if value_pointer
                        else None,
                        0,
                    )
                )
        return (
            int(header.ma_used),
            int(header.ma_version_tag),
            table_size,
            indices_size,
            kind,
            int(keys_header.dk_usable),
            entry_count,
            ctypes.string_at(
                int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader),
                indices_size,
            ),
            tuple(entries),
            int(keys_header.dk_version),
        )
    except (TypeError, ValueError):
        return None


def _rollback_dict_table_snapshots_match(
    current: Optional[tuple[Any, ...]],
    saved: Optional[tuple[Any, ...]],
) -> bool:
    if (
        current is None
        or saved is None
        or current[:8] != saved[:8]
        or current[9] != saved[9]
    ):
        return False
    return bool(
        len(current[8]) == len(saved[8])
        and all(
            current_key is saved_key
            and current_value is saved_value
            and current_hash == saved_hash
            for (
                _current_key_pointer,
                current_key,
                _current_value_pointer,
                current_value,
                current_hash,
            ), (
                _saved_key_pointer,
                saved_key,
                _saved_value_pointer,
                saved_value,
                saved_hash,
            ) in zip(current[8], saved[8])
        )
    )


def _rollback_restore_dict_table(
    value: dict[Any, Any],
    saved: Optional[tuple[Any, ...]],
) -> bool:
    """Restore an exact saved combined dictionary table in its current storage."""

    if (
        saved is None
        or not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
    ):
        return False
    current = _rollback_dict_table_snapshot(value)
    if (
        current is None
        or current[2] != saved[2]
        or current[3] != saved[3]
        or current[4] != saved[4]
        or current[6] > saved[2] * 2 // 3
    ):
        return False
    try:
        header = _CPythonDictHeader.from_address(id(value))
        if sys.version_info[:2] == (3, 12) and int(header.ma_version_tag) & 0xFF:
            return False
        keys_header = _CPythonDictKeysHeader.from_address(header.ma_keys)
        entries_address = (
            int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader) + saved[3]
        )
        for key_pointer, key, value_pointer, item, _key_hash in saved[8]:
            if key_pointer:
                _CPYTHON_INCREF(key)
            if value_pointer:
                _CPYTHON_INCREF(item)
        ctypes.memmove(
            int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader),
            saved[7],
            saved[3],
        )
        if saved[4] == 0:
            table = (_CPythonDictKeyEntry * saved[6]).from_address(entries_address)
            for index, (key_pointer, key, value_pointer, item, key_hash) in enumerate(
                saved[8]
            ):
                table[index].key = id(key) if key_pointer else None
                table[index].value = id(item) if value_pointer else None
                table[index].hash = key_hash
        else:
            table = (_CPythonDictUnicodeEntry * saved[6]).from_address(entries_address)
            for index, (key_pointer, key, value_pointer, item, _key_hash) in enumerate(
                saved[8]
            ):
                table[index].key = id(key) if key_pointer else None
                table[index].value = id(item) if value_pointer else None
        header.ma_used = saved[0]
        header.ma_version_tag = saved[1]
        keys_header.dk_usable = saved[5]
        keys_header.dk_nentries = saved[6]
        keys_header.dk_version = saved[9]
        for key_pointer, key, value_pointer, item, _key_hash in current[8]:
            if key_pointer:
                _CPYTHON_DECREF(key)
            if value_pointer:
                _CPYTHON_DECREF(item)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_set_entries_with_hashes(
    value: Any,
) -> Optional[List[tuple[Any, int]]]:
    """Read exact set entries with their already-computed hashes."""

    if _CPYTHON_SET_NEXT is None:
        return None
    position = ctypes.c_ssize_t()
    key = ctypes.py_object()
    key_hash = ctypes.c_ssize_t()
    entries: List[tuple[Any, int]] = []
    while _CPYTHON_SET_NEXT(
        value,
        ctypes.byref(position),
        ctypes.byref(key),
        ctypes.byref(key_hash),
    ):
        entries.append((key.value, int(key_hash.value)))
    return entries


def _rollback_set_table_snapshot(value: Any) -> Optional[tuple[Any, ...]]:
    """Capture every set slot, including empty and dummy positions."""

    if not _rollback_cpython_table_layout_is_supported():
        return None
    try:
        header = _CPythonSetHeader.from_address(id(value))
        table_size = int(header.mask) + 1
        if table_size < 8 or table_size & (table_size - 1):
            return None
        slots: List[tuple[int, int, Any, int]] = []
        for index in range(table_size):
            entry = header.table[index]
            key_pointer = int(entry.key or 0)
            key_hash = int(entry.hash)
            if not key_pointer:
                slots.append((0, 0, None, key_hash))
            elif key_hash == -1:
                slots.append((1, key_pointer, None, key_hash))
            else:
                slots.append(
                    (
                        2,
                        key_pointer,
                        ctypes.cast(key_pointer, ctypes.py_object).value,
                        key_hash,
                    )
                )
        return (
            int(header.fill),
            int(header.used),
            int(header.mask),
            int(header.hash),
            int(header.finger),
            tuple(slots),
        )
    except (TypeError, ValueError):
        return None


def _rollback_set_table_snapshots_match(
    current: Optional[tuple[Any, ...]],
    saved: Optional[tuple[Any, ...]],
) -> bool:
    if current is None or saved is None or current[:5] != saved[:5]:
        return False
    current_slots = current[5]
    saved_slots = saved[5]
    return bool(
        len(current_slots) == len(saved_slots)
        and all(
            current_kind == saved_kind
            and current_hash == saved_hash
            and (
                current_pointer == saved_pointer
                if current_kind != 2
                else current_item is saved_item
            )
            for (
                current_kind,
                current_pointer,
                current_item,
                current_hash,
            ), (
                saved_kind,
                saved_pointer,
                saved_item,
                saved_hash,
            ) in zip(current_slots, saved_slots)
        )
    )


def _rollback_restore_set_table(
    value: Any,
    saved: Optional[tuple[Any, ...]],
) -> bool:
    """Restore an exact saved set table while retaining member ownership."""

    if (
        saved is None
        or not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
    ):
        return False
    current = _rollback_set_table_snapshot(value)
    if current is None or current[2] != saved[2]:
        return False
    saved_slots = saved[5]
    current_slots = current[5]
    try:
        header = _CPythonSetHeader.from_address(id(value))
        for kind, _pointer, item, _item_hash in saved_slots:
            if kind == 2:
                _CPYTHON_INCREF(item)
        for index, (kind, pointer, item, item_hash) in enumerate(saved_slots):
            entry = header.table[index]
            entry.key = id(item) if kind == 2 else pointer or None
            entry.hash = item_hash
        header.fill = saved[0]
        header.used = saved[1]
        header.hash = saved[3]
        header.finger = saved[4]
        for kind, _pointer, item, _item_hash in current_slots:
            if kind == 2:
                _CPYTHON_DECREF(item)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_set_iterator_position(
    source: Any,
    remaining_entries: Sequence[tuple[Any, int]],
) -> Optional[int]:
    """Return a physical source cursor matching an iterator's saved suffix."""

    try:
        source_header = _CPythonSetHeader.from_address(id(source))
        table_size = int(source_header.mask) + 1
        remaining_ids = {id(item) for item, _item_hash in remaining_entries}
        remaining_positions: List[int] = []
        consumed_positions: List[int] = []
        for position in range(table_size):
            entry = source_header.table[position]
            if not entry.key or int(entry.hash) == -1:
                continue
            if int(entry.key) in remaining_ids:
                remaining_positions.append(position)
            else:
                consumed_positions.append(position)
        if len(remaining_positions) != len(remaining_ids):
            return None
        position = min(remaining_positions) if remaining_positions else table_size
        if any(item_position >= position for item_position in consumed_positions):
            return None
        return position
    except (TypeError, ValueError):
        return None


def _rollback_rebind_set_iterator(
    iterator: Any,
    source: Any,
    remaining_entries: Sequence[tuple[Any, int]],
) -> bool:
    """Retarget an exact set iterator to a valid position in its source."""

    if (
        not _CPYTHON_SET_ITERATOR_LAYOUT_VALID
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
        or type(iterator) is not type(iter(set()))
    ):
        return False
    position = _rollback_set_iterator_position(source, remaining_entries)
    if position is None:
        return False
    try:
        source_header = _CPythonSetHeader.from_address(id(source))
        header = _CPythonSetIteratorHeader.from_address(id(iterator))
        original_pointer = int(header.si_set or 0)
        if original_pointer != id(source):
            _CPYTHON_INCREF(source)
            header.si_set = id(source)
            if original_pointer:
                original = ctypes.cast(original_pointer, ctypes.py_object).value
                _CPYTHON_DECREF(original)
        header.si_used = int(source_header.used)
        header.si_pos = position
        header.length = len(remaining_entries)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_set_dict_item_iterator_result(
    iterator: Any, result: tuple[Any, Any]
) -> bool:
    """Restore the reusable item tuple held by an exact dictionary iterator."""

    if (
        tuple(sys.version_info[:2]) not in _ROLLBACK_CPYTHON_TABLE_LAYOUT_VERSIONS
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
        or type(iterator) is not type(iter({}.items()))
        or type(result) is not tuple
        or len(result) != 2
    ):
        return False
    try:
        header = _CPythonDictIteratorHeader.from_address(id(iterator))
        original_pointer = int(header.di_result or 0)
        _CPYTHON_INCREF(result)
        header.di_result = id(result)
        if original_pointer:
            original = ctypes.cast(original_pointer, ctypes.py_object).value
            _CPYTHON_DECREF(original)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_rebuild_dict_iterator(
    source: dict[Any, Any],
    template_type: type,
    remaining_values: Sequence[Any],
    hidden_item_result: Optional[tuple[Any, Any]] = None,
) -> Optional[Any]:
    """Build an exact dictionary iterator coupled to its recovered source."""

    snapshot = _rollback_dict_table_snapshot(source)
    if snapshot is None:
        return None
    active_entries = [
        (position, key, item)
        for position, (
            key_pointer,
            key,
            _value_pointer,
            item,
            _key_hash,
        ) in enumerate(snapshot[8])
        if key_pointer
    ]

    remaining_count = len(remaining_values)
    if remaining_count > len(active_entries):
        return None
    if remaining_count:
        suffix = active_entries[-remaining_count:]
        position = suffix[0][0]
    else:
        suffix = []
        position = snapshot[6]
    if template_type is type(iter({})):
        if not all(
            entry[1] is expected
            for entry, expected in zip(suffix, remaining_values)
        ):
            return None
        rebuilt = dict.__iter__(source)
    elif template_type is type(iter({}.values())):
        if not all(
            entry[2] is expected
            for entry, expected in zip(suffix, remaining_values)
        ):
            return None
        rebuilt = iter(dict.values(source))
    elif template_type is type(iter({}.items())):
        if not all(
            type(expected) is tuple
            and len(expected) == 2
            and entry[1] is expected[0]
            and entry[2] is expected[1]
            for entry, expected in zip(suffix, remaining_values)
        ):
            return None
        rebuilt = iter(dict.items(source))
    else:
        return None
    try:
        header = _CPythonDictIteratorHeader.from_address(id(rebuilt))
        header.di_used = snapshot[0]
        header.di_pos = position
        header.length = len(remaining_values)
        if hidden_item_result is not None:
            _rollback_set_dict_item_iterator_result(rebuilt, hidden_item_result)
        return rebuilt
    except (TypeError, ValueError):
        return None


def _rollback_rebuild_set_table(
    value: Any,
    entries: Sequence[tuple[Any, int]],
) -> bool:
    """Rebuild one CPython set table without revisiting unchanged members.

    The table is retained at its existing size.  Every active reference is
    transferred explicitly, and the built-in probe sequence is reproduced so
    ordinary membership operations remain valid after a member identity or
    hash changes.
    """

    if (
        not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
    ):
        return False
    try:
        header = _CPythonSetHeader.from_address(id(value))
        table_size = int(header.mask) + 1
        if (
            table_size < 8
            or table_size & (table_size - 1)
            or int(header.used) < len(entries)
            or not bool(header.table)
        ):
            return False
        old_entries = _rollback_set_entries_with_hashes(value)
        if old_entries is None or len(old_entries) != int(header.used):
            return False

        unique_entries: List[tuple[Any, int]] = []
        seen_ids: Set[int] = set()
        for item, item_hash in entries:
            item_id = id(item)
            if item_id in seen_ids:
                continue
            seen_ids.add(item_id)
            unique_entries.append((item, item_hash))

        for item, _item_hash in unique_entries:
            _CPYTHON_INCREF(item)
        for index in range(table_size):
            header.table[index].key = None
            header.table[index].hash = 0

        mask = table_size - 1
        for item, item_hash in unique_entries:
            unsigned_hash = ctypes.c_size_t(item_hash).value
            perturb = unsigned_hash
            index = unsigned_hash & mask
            while True:
                linear_probes = 9 if index + 9 <= mask else 0
                for offset in range(linear_probes + 1):
                    entry = header.table[index + offset]
                    if not entry.key:
                        entry.key = id(item)
                        entry.hash = item_hash
                        break
                else:
                    perturb >>= 5
                    index = (index * 5 + 1 + perturb) & mask
                    continue
                break

        header.fill = len(unique_entries)
        header.used = len(unique_entries)
        header.hash = -1
        header.finger = 0
        for item, _item_hash in old_entries:
            _CPYTHON_DECREF(item)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_build_set_layout_probe(
    source: Any,
    entries: Sequence[tuple[Any, int]],
) -> Optional[set[Any]]:
    """Build a disposable set with the source table size and candidate layout."""

    try:
        target_mask = int(_CPythonSetHeader.from_address(id(source)).mask)
        probe: set[Any] = set(range(max(len(entries), 1)))
        next_placeholder = len(probe)
        while int(_CPythonSetHeader.from_address(id(probe)).mask) < target_mask:
            set.add(probe, next_placeholder)
            next_placeholder += 1
        if int(_CPythonSetHeader.from_address(id(probe)).mask) != target_mask:
            return None
        if not _rollback_rebuild_set_table(probe, entries):
            return None
        return probe
    except (TypeError, ValueError):
        return None


def _rollback_replace_set_members_in_place(
    value: set[Any],
    original_entries: Sequence[tuple[Any, int]],
    rewritten_entries: Sequence[tuple[Any, int]],
) -> bool:
    """Replace same-hash set members without moving iterator-visible slots."""

    if (
        not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
        or len(original_entries) != len(rewritten_entries)
    ):
        return False
    replacements: Dict[int, tuple[Any, Any]] = {}
    for (original, original_hash), (rewritten, rewritten_hash) in zip(
        original_entries, rewritten_entries
    ):
        if original_hash != rewritten_hash:
            return False
        if original is not rewritten:
            replacements[id(original)] = (original, rewritten)
    if not replacements:
        return True
    try:
        header = _CPythonSetHeader.from_address(id(value))
        table_size = int(header.mask) + 1
        if int(header.used) != len(original_entries) or table_size < 8:
            return False
        slots: List[tuple[_CPythonSetEntry, Any, Any]] = []
        for index in range(table_size):
            entry = header.table[index]
            if not entry.key or int(entry.hash) == -1:
                continue
            replacement = replacements.get(int(entry.key))
            if replacement is None:
                continue
            original, rewritten = replacement
            slots.append((entry, original, rewritten))
        if {id(original) for _entry, original, _rewritten in slots} != set(
            replacements
        ):
            return False
        for _entry, _original, rewritten in slots:
            _CPYTHON_INCREF(rewritten)
        for entry, _original, rewritten in slots:
            entry.key = id(rewritten)
        for _entry, original, _rewritten in slots:
            _CPYTHON_DECREF(original)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_build_exact_dict(
    entries: Sequence[tuple[Any, Any, int]],
    _result_type: type = dict,
) -> Optional[dict[Any, Any]]:
    """Build a base dict temporary in saved order using cached key hashes."""

    if (
        not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
    ):
        return None
    placeholders = [_RollbackDictPlaceholder() for _entry in entries]
    try:
        rebuilt = dict.__new__(dict)
    except TypeError:
        return None
    if not entries:
        return rebuilt
    for placeholder, (_key, item, key_hash) in zip(placeholders, entries):
        if not _rollback_dict_setitem_known_hash(rebuilt, placeholder, item, key_hash):
            return None
    try:
        header = _CPythonDictHeader.from_address(id(rebuilt))
        if not header.ma_keys or header.ma_values:
            return None
        keys_header = _CPythonDictKeysHeader.from_address(header.ma_keys)
        if keys_header.dk_kind != 0 or keys_header.dk_nentries != len(entries):
            return None
        indices_size = 1 << int(keys_header.dk_log2_index_bytes)
        entries_address = (
            int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader) + indices_size
        )
        table = (_CPythonDictKeyEntry * len(entries)).from_address(entries_address)
        replacements = {
            id(placeholder): (key, key_hash)
            for placeholder, (key, _item, key_hash) in zip(placeholders, entries)
        }
        if any(
            not entry.key
            or entry.key not in replacements
            or int(entry.hash) != replacements[entry.key][1]
            for entry in table
        ):
            return None
        for entry in table:
            placeholder = ctypes.cast(entry.key, ctypes.py_object).value
            key, _key_hash = replacements[entry.key]
            _CPYTHON_INCREF(key)
            entry.key = id(key)
            _CPYTHON_DECREF(placeholder)
        return rebuilt
    except (TypeError, ValueError):
        return None


def _rollback_transplant_dict_table(
    target: dict[Any, Any],
    replacement: dict[Any, Any],
) -> bool:
    """Transfer a rebuilt CPython dict table into an existing mapping."""

    if not _rollback_cpython_table_layout_is_supported():
        return False
    try:
        target_header = _CPythonDictHeader.from_address(id(target))
        replacement_header = _CPythonDictHeader.from_address(id(replacement))
        if sys.version_info[:2] == (3, 12) and int(target_header.ma_version_tag) & 0xFF:
            return False
        for field_name in ("ma_used", "ma_version_tag", "ma_keys", "ma_values"):
            target_value = getattr(target_header, field_name)
            setattr(target_header, field_name, getattr(replacement_header, field_name))
            setattr(replacement_header, field_name, target_value)
        return True
    except (TypeError, ValueError):
        return False


def _rollback_transplant_ordered_dict_state(
    target: collections.OrderedDict[Any, Any],
    replacement: collections.OrderedDict[Any, Any],
) -> bool:
    """Transfer rebuilt logical order into an existing OrderedDict."""

    if not _rollback_cpython_table_layout_is_supported():
        return False
    try:
        target_header = _CPythonOrderedDictHeader.from_address(id(target))
        replacement_header = _CPythonOrderedDictHeader.from_address(id(replacement))
        if sys.version_info[:2] == (3, 12) and int(target_header.ma_version_tag) & 0xFF:
            return False
        for field_name in (
            "ma_used",
            "ma_version_tag",
            "ma_keys",
            "ma_values",
            "fast_nodes",
            "fast_nodes_size",
            "resize_sentinel",
            "state",
        ):
            target_value = getattr(target_header, field_name)
            setattr(target_header, field_name, getattr(replacement_header, field_name))
            setattr(replacement_header, field_name, target_value)
        for field_name in ("first", "last"):
            target_pointer = ctypes.cast(
                getattr(target_header, field_name), ctypes.c_void_p
            ).value
            replacement_pointer = ctypes.cast(
                getattr(replacement_header, field_name), ctypes.c_void_p
            ).value
            setattr(
                target_header,
                field_name,
                ctypes.cast(
                    ctypes.c_void_p(replacement_pointer),
                    ctypes.POINTER(_CPythonOrderedDictNode),
                ),
            )
            setattr(
                replacement_header,
                field_name,
                ctypes.cast(
                    ctypes.c_void_p(target_pointer),
                    ctypes.POINTER(_CPythonOrderedDictNode),
                ),
            )
        return True
    except (TypeError, ValueError):
        return False


def _rollback_build_ordered_dict(
    entries: Sequence[tuple[Any, Any, int]],
    _result_type: type,
) -> Optional[collections.OrderedDict[Any, Any]]:
    """Build a base OrderedDict temporary without re-evaluating saved keys."""

    if (
        not _rollback_cpython_table_layout_is_supported()
        or _CPYTHON_INCREF is None
        or _CPYTHON_DECREF is None
    ):
        return None
    try:
        rebuilt = collections.OrderedDict.__new__(collections.OrderedDict)
        collections.OrderedDict.__init__(rebuilt)
    except TypeError:
        return None
    if not entries:
        return rebuilt
    placeholders = [
        _RollbackOrderedDictPlaceholder(key_hash) for _key, _item, key_hash in entries
    ]
    for placeholder, (_key, item, _key_hash) in zip(placeholders, entries):
        collections.OrderedDict.__setitem__(rebuilt, placeholder, item)
    try:
        header = _CPythonOrderedDictHeader.from_address(id(rebuilt))
        if not header.ma_keys or header.ma_values or header.ma_used != len(entries):
            return None
        keys_header = _CPythonDictKeysHeader.from_address(header.ma_keys)
        if keys_header.dk_kind != 0 or keys_header.dk_nentries != len(entries):
            return None
        indices_size = 1 << int(keys_header.dk_log2_index_bytes)
        entries_address = (
            int(header.ma_keys) + ctypes.sizeof(_CPythonDictKeysHeader) + indices_size
        )
        table = (_CPythonDictKeyEntry * len(entries)).from_address(entries_address)
        replacements = {
            id(placeholder): (key, key_hash)
            for placeholder, (key, _item, key_hash) in zip(placeholders, entries)
        }
        node_pointers: List[ctypes.POINTER(_CPythonOrderedDictNode)] = []
        node = header.first
        while bool(node) and len(node_pointers) <= len(entries):
            node_pointers.append(node)
            node = node.contents.next
        if (
            len(node_pointers) != len(entries)
            or bool(node)
            or any(
                not entry.key
                or entry.key not in replacements
                or int(entry.hash) != replacements[entry.key][1]
                for entry in table
            )
            or any(
                not node_pointer.contents.key
                or node_pointer.contents.key not in replacements
                or int(node_pointer.contents.hash)
                != replacements[node_pointer.contents.key][1]
                for node_pointer in node_pointers
            )
        ):
            return None
        for entry in table:
            placeholder = ctypes.cast(entry.key, ctypes.py_object).value
            key, _key_hash = replacements[entry.key]
            _CPYTHON_INCREF(key)
            entry.key = id(key)
            _CPYTHON_DECREF(placeholder)
        for node_pointer in node_pointers:
            node = node_pointer.contents
            placeholder = ctypes.cast(node.key, ctypes.py_object).value
            key, _key_hash = replacements[node.key]
            _CPYTHON_INCREF(key)
            node.key = id(key)
            _CPYTHON_DECREF(placeholder)
        return rebuilt
    except (TypeError, ValueError):
        return None


def _rollback_ordered_dict_keys(
    value: collections.OrderedDict[Any, Any],
) -> Optional[tuple[Any, ...]]:
    """Read CPython OrderedDict logical order without key lookup."""

    if not _rollback_cpython_table_layout_is_supported():
        return None
    try:
        header = _CPythonOrderedDictHeader.from_address(id(value))
        keys: List[Any] = []
        node = header.first
        while bool(node) and len(keys) <= int(header.ma_used):
            keys.append(ctypes.cast(node.contents.key, ctypes.py_object).value)
            node = node.contents.next
        if len(keys) != int(header.ma_used) or bool(node):
            return None
        return tuple(keys)
    except (TypeError, ValueError):
        return None


def _rollback_ordered_dict_state(
    value: collections.OrderedDict[Any, Any],
) -> Optional[int]:
    """Read the logical-order mutation counter for iterator restoration."""

    if not _rollback_cpython_table_layout_is_supported():
        return None
    try:
        return int(_CPythonOrderedDictHeader.from_address(id(value)).state)
    except (TypeError, ValueError):
        return None


def _rollback_set_ordered_dict_state(
    value: collections.OrderedDict[Any, Any], state: int
) -> bool:
    """Restore a previously validated logical-order mutation counter."""

    if not _rollback_cpython_table_layout_is_supported():
        return False
    try:
        _CPythonOrderedDictHeader.from_address(id(value)).state = state
        return True
    except (TypeError, ValueError):
        return False


def _rollback_snapshot_function_is_authentic(function: Any) -> bool:
    """Validate snapshot helpers and every nested helper they depend on."""

    required_function_cells = {
        "capture_completion_snapshot",
        "completion_snapshot_is_current",
        "freeze_completion_snapshot",
        "frozen_completion_snapshots_match",
        "snapshot_completed_mutables",
    }
    pending = [function]
    seen: Set[int] = set()
    while pending:
        current = pending.pop()
        if not isinstance(current, types.FunctionType):
            return False
        current_id = id(current)
        if current_id in seen:
            continue
        seen.add(current_id)
        expected_code = _ROLLBACK_SNAPSHOT_HELPER_CODES.get(current.__code__.co_name)
        if (
            current.__globals__ is not globals()
            or expected_code is None
            or current.__code__ is not expected_code
        ):
            return False
        closure = current.__closure__ or ()
        if len(closure) != len(current.__code__.co_freevars):
            return False
        for freevar_name, cell in zip(current.__code__.co_freevars, closure):
            try:
                dependency = cell.cell_contents
            except ValueError:
                return False
            if freevar_name in required_function_cells:
                if not isinstance(dependency, types.FunctionType):
                    return False
                pending.append(dependency)
            elif isinstance(dependency, types.FunctionType):
                dependency_code = _ROLLBACK_SNAPSHOT_HELPER_CODES.get(
                    dependency.__code__.co_name
                )
                if dependency_code is not None:
                    pending.append(dependency)
            elif freevar_name == "rollback_iterator_types":
                expected_iterator_types = (
                    type(iter([])),
                    type(reversed([])),
                    type(iter(())),
                    type(iter(range(0))),
                    type(iter({})),
                    type(iter({}.values())),
                    type(iter({}.items())),
                    type(iter(set())),
                )
                if (
                    type(dependency) is not tuple
                    or len(dependency) != len(expected_iterator_types)
                    or any(
                        left is not right
                        for left, right in zip(dependency, expected_iterator_types)
                    )
                ):
                    return False
    return True


def _make_rollback_deepcopy_completion_registry():
    registry: Dict[
        int,
        tuple["weakref.ReferenceType[Any]", Mapping[int, Any], object],
    ] = {}
    mutable_states: Dict[int, Dict[int, Any]] = {}
    registry_lock = threading.RLock()

    def discard_state(memo_id: int, dead_ref: "weakref.ReferenceType[Any]") -> None:
        removed_entry = None
        removed_state = None
        with registry_lock:
            entry = registry.get(memo_id)
            if entry is not None and entry[0] is dead_ref:
                removed_entry = registry.pop(memo_id, None)
                removed_state = mutable_states.pop(memo_id, None)
        del removed_entry, removed_state

    def state_view(
        memo: Any, *, transaction_token: Optional[object] = None
    ) -> Mapping[int, Any]:
        displaced_entry = None
        displaced_state = None
        with registry_lock:
            memo_id = id(memo)
            entry = registry.get(memo_id)
            if entry is not None and entry[0]() is memo:
                return entry[1]
            displaced_entry = entry
            displaced_state = mutable_states.get(memo_id)
            raw_state: Dict[int, Any] = {}
            if transaction_token is None:
                transaction_token = object()
            memo_ref = weakref.ref(
                memo,
                functools.partial(discard_state, memo_id),
            )
            view = types.MappingProxyType(raw_state)
            registry[memo_id] = (memo_ref, view, transaction_token)
            mutable_states[memo_id] = raw_state
        del displaced_entry, displaced_state
        return view

    def mutable_state(memo: Any) -> Dict[int, Any]:
        try:
            caller_code = sys._getframe(1).f_code
        except ValueError as exc:
            raise TypeError("completion-state mutation is internal") from exc
        if caller_code not in _ROLLBACK_DEEPCOPY_COMPLETION_MUTATOR_CODES:
            raise TypeError("completion-state mutation is internal")
        with registry_lock:
            state_view(memo)
            return mutable_states[id(memo)]

    def transaction(memo: Any) -> object:
        with registry_lock:
            state_view(memo)
            return registry[id(memo)][2]

    def discard_transaction(transaction_token: object) -> None:
        transaction_memos = []
        removed_entries = []
        removed_states = []
        with registry_lock:
            registry_snapshot = tuple(registry.items())
            for memo_id, entry in registry_snapshot:
                if entry[2] is transaction_token:
                    memo = entry[0]()
                    if isinstance(memo, _RollbackDeepcopyMemo):
                        transaction_memos.append(memo)
                    removed_entry = registry.pop(memo_id, None)
                    removed_state = mutable_states.pop(memo_id, None)
                    if removed_entry is not None:
                        removed_entries.append(removed_entry)
                    if removed_state is not None:
                        removed_states.append(removed_state)
        for memo in transaction_memos:
            dict.pop(
                memo,
                id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                None,
            )
        removed_entries.clear()
        removed_states.clear()
        del registry_snapshot

    return (
        registry_lock,
        discard_state,
        state_view,
        mutable_state,
        transaction,
        discard_transaction,
    )


_ROLLBACK_DEEPCOPY_COMPLETION_STATES: Mapping[int, Any] = types.MappingProxyType({})
(
    _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK,
    _discard_rollback_deepcopy_completion_state,
    _rollback_deepcopy_completion_state,
    _mutable_rollback_deepcopy_completion_state,
    _rollback_deepcopy_completion_transaction,
    _discard_rollback_deepcopy_completion_transaction,
) = _make_rollback_deepcopy_completion_registry()


def _activate_rollback_deepcopy_transaction(
    transaction_token: object,
) -> None:
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS[transaction_token] = (
            _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS.get(transaction_token, 0) + 1
        )


def _deactivate_rollback_deepcopy_transaction(
    transaction_token: object,
) -> None:
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        active_count = _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS.get(transaction_token, 0)
        if active_count > 1:
            _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS[transaction_token] = active_count - 1
        else:
            _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS.pop(transaction_token, None)


def _rollback_deepcopy_transaction_is_active(
    transaction_token: Any,
) -> bool:
    if type(transaction_token) is not object:
        return False
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        return _ACTIVE_ROLLBACK_DEEPCOPY_TRANSACTIONS.get(transaction_token, 0) > 0


_CAPABILITY_GENERATION_NONCE_LOCK = threading.Lock()
_CAPABILITY_GENERATION_NONCES: "weakref.WeakKeyDictionary[Any, int]" = (
    weakref.WeakKeyDictionary()
)
_CAPABILITY_GENERATION_NONCE_NEXT = 1


class _CPythonBuffer(ctypes.Structure):
    """Stable ``Py_buffer`` layout used for a momentary address snapshot."""

    _fields_ = [
        ("buf", ctypes.c_void_p),
        ("obj", ctypes.c_void_p),
        ("len", ctypes.c_ssize_t),
        ("itemsize", ctypes.c_ssize_t),
        ("readonly", ctypes.c_int),
        ("ndim", ctypes.c_int),
        ("format", ctypes.c_char_p),
        ("shape", ctypes.POINTER(ctypes.c_ssize_t)),
        ("strides", ctypes.POINTER(ctypes.c_ssize_t)),
        ("suboffsets", ctypes.POINTER(ctypes.c_ssize_t)),
        ("internal", ctypes.c_void_p),
    ]


_PYBUF_FULL_RO = 0x011C
_PYOBJECT_GET_BUFFER = ctypes.pythonapi.PyObject_GetBuffer
_PYOBJECT_GET_BUFFER.argtypes = [
    ctypes.py_object,
    ctypes.POINTER(_CPythonBuffer),
    ctypes.c_int,
]
_PYOBJECT_GET_BUFFER.restype = ctypes.c_int
_PYBUFFER_RELEASE = ctypes.pythonapi.PyBuffer_Release
_PYBUFFER_RELEASE.argtypes = [ctypes.POINTER(_CPythonBuffer)]
_PYBUFFER_RELEASE.restype = None


def _memoryview_backing_offset(
    view: memoryview,
    backing: Any,
) -> Optional[int]:
    """Return the view's byte offset without retaining another export.

    Python exposes shape and strides but not the starting offset.  Holding a
    duplicate view across an action would change exporter behavior (notably a
    released ``BytesIO`` buffer could no longer be resized), so briefly query
    the CPython buffer API and release both temporary exports immediately.
    """

    view_buffer = _CPythonBuffer()
    backing_buffer = _CPythonBuffer()
    view_acquired = False
    backing_acquired = False
    try:
        _PYOBJECT_GET_BUFFER(
            view,
            ctypes.byref(view_buffer),
            _PYBUF_FULL_RO,
        )
        view_acquired = True
        _PYOBJECT_GET_BUFFER(
            backing,
            ctypes.byref(backing_buffer),
            _PYBUF_FULL_RO,
        )
        backing_acquired = True
        if view_buffer.buf is None or backing_buffer.buf is None:
            return None
        offset = int(view_buffer.buf) - int(backing_buffer.buf)
        if offset < 0 or offset > int(backing_buffer.len):
            return None
        return offset
    except (BufferError, TypeError, ValueError, OverflowError):
        return None
    finally:
        if backing_acquired:
            _PYBUFFER_RELEASE(ctypes.byref(backing_buffer))
        if view_acquired:
            _PYBUFFER_RELEASE(ctypes.byref(view_buffer))


def _buffer_address_and_length(value: Any) -> Optional[tuple[int, int]]:
    """Read a buffer's logical base address without retaining an export."""

    buffer = _CPythonBuffer()
    acquired = False
    try:
        _PYOBJECT_GET_BUFFER(
            value,
            ctypes.byref(buffer),
            _PYBUF_FULL_RO,
        )
        acquired = True
        if buffer.buf is None:
            return None
        return int(buffer.buf), int(buffer.len)
    except (BufferError, TypeError, ValueError, OverflowError):
        return None
    finally:
        if acquired:
            _PYBUFFER_RELEASE(ctypes.byref(buffer))


def _matching_process_fd(device: int, inode: int) -> Optional[int]:
    """Find an open descriptor for one mapped file without duplicating it."""

    try:
        entries = os.scandir("/proc/self/fd")
    except OSError:
        return None
    with entries:
        for entry in entries:
            try:
                descriptor = int(entry.name)
                status = os.stat(entry.path)
            except (OSError, ValueError):
                continue
            if status.st_dev == device and status.st_ino == inode:
                return descriptor
    return None


class _MmapFileReconstruction:
    """Immutable mapping identity plus a non-owned descriptor hint."""

    def __init__(
        self,
        *,
        device: int,
        inode: int,
        descriptor: int,
        file_offset: int,
        access: int,
        mapped_path: Optional[str],
    ) -> None:
        self.device = device
        self.inode = inode
        self.descriptor = descriptor
        self.file_offset = file_offset
        self.access = access
        self.mapped_path = mapped_path

    def _validated_duplicate(self, descriptor: int) -> Optional[int]:
        try:
            duplicate = os.dup(descriptor)
        except OSError:
            return None
        try:
            status = os.fstat(duplicate)
            if status.st_dev == self.device and status.st_ino == self.inode:
                return duplicate
        except OSError:
            pass
        try:
            os.close(duplicate)
        except OSError:
            pass
        return None

    def duplicate(self) -> Optional[int]:
        descriptor = self.descriptor
        if descriptor >= 0:
            duplicate = self._validated_duplicate(descriptor)
            if duplicate is not None:
                return duplicate
        replacement_descriptor = _matching_process_fd(
            self.device,
            self.inode,
        )
        if replacement_descriptor is not None:
            duplicate = self._validated_duplicate(replacement_descriptor)
            if duplicate is not None:
                return duplicate
        mapped_path = self.mapped_path
        if mapped_path is None:
            return None
        flags = os.O_RDWR if self.access == mmap.ACCESS_WRITE else os.O_RDONLY
        try:
            reopened = os.open(mapped_path, flags)
            status = os.fstat(reopened)
            if status.st_dev == self.device and status.st_ino == self.inode:
                return reopened
            os.close(reopened)
        except OSError:
            return None
        return None

    def close(self) -> None:
        # The descriptor is deliberately only a hint. Owning a raw descriptor
        # across arbitrary callbacks is unsafe: if it is externally closed and
        # reused for the same inode, no fd-level check can prove ownership and
        # cleanup could close the new owner's descriptor.
        self.descriptor = -1


def _mmap_file_reconstruction(
    mapping: mmap.mmap,
) -> Optional[_MmapFileReconstruction]:
    """Record validated identity metadata for a Linux file mapping."""

    buffer_location = _buffer_address_and_length(mapping)
    if buffer_location is None:
        return None
    address, _length = buffer_location
    try:
        maps_file = open("/proc/self/maps", encoding="utf-8")
    except OSError:
        return None
    with maps_file:
        for line in maps_file:
            fields = line.rstrip("\n").split(maxsplit=5)
            if len(fields) < 5:
                continue
            try:
                start_text, end_text = fields[0].split("-", 1)
                start = int(start_text, 16)
                end = int(end_text, 16)
                mapped_offset = int(fields[2], 16)
                major_text, minor_text = fields[3].split(":", 1)
                device = os.makedev(
                    int(major_text, 16),
                    int(minor_text, 16),
                )
                inode = int(fields[4])
            except (TypeError, ValueError):
                continue
            if not (start <= address < end) or inode <= 0:
                continue
            permissions = fields[1]
            if len(permissions) < 4:
                return None
            if permissions[3] == "s" and permissions[1] == "w":
                access = mmap.ACCESS_WRITE
            elif permissions[3] == "p" and permissions[1] == "w":
                access = mmap.ACCESS_COPY
            elif permissions[0] == "r" and permissions[1] != "w":
                access = mmap.ACCESS_READ
            else:
                return None
            mapped_path = fields[5] if len(fields) >= 6 else None
            if mapped_path is not None and (
                mapped_path.startswith("[") or mapped_path.endswith(" (deleted)")
            ):
                mapped_path = None
            descriptor = _matching_process_fd(device, inode)
            if mapped_path is not None:
                try:
                    path_status = os.stat(mapped_path)
                    if path_status.st_dev != device or path_status.st_ino != inode:
                        mapped_path = None
                except OSError:
                    mapped_path = None
            if descriptor is None and mapped_path is None:
                return None
            return _MmapFileReconstruction(
                device=device,
                inode=inode,
                descriptor=descriptor if descriptor is not None else -1,
                file_offset=mapped_offset + (address - start),
                access=access,
                mapped_path=mapped_path,
            )
    return None


def _reopen_mmap_file_descriptor(
    reconstruction: _MmapFileReconstruction,
) -> Optional[int]:
    """Duplicate still-valid journal authority for mmap construction."""

    return reconstruction.duplicate()


def _memoryview_layout_matches(
    view: memoryview,
    *,
    view_format: str,
    view_shape: tuple[int, ...],
    view_strides: tuple[int, ...],
    view_suboffsets: tuple[int, ...],
    view_nbytes: int,
    view_readonly: bool,
) -> bool:
    """Compare every public layout property that affects buffer semantics."""

    return (
        view.format == view_format
        and view.shape == view_shape
        and view.strides == view_strides
        and view.suboffsets == view_suboffsets
        and view.nbytes == view_nbytes
        and view.readonly is view_readonly
    )


def _slice_memoryview_first_axis(
    parent: memoryview,
    *,
    start: int,
    step: int,
    length: int,
) -> Optional[memoryview]:
    """Build an exact first-axis slice, handling Python's ``-1`` stop rule."""

    if step == 0 or length < 0:
        return None
    raw_stop = start + step * length
    stop: Optional[int] = None if step < 0 and raw_stop == -1 else raw_stop
    try:
        return parent[start:stop:step]
    except (IndexError, NotImplementedError, TypeError, ValueError):
        return None


def _rebuild_memoryview_from_layout(
    backing: Any,
    *,
    view_format: str,
    view_itemsize: int,
    view_shape: tuple[int, ...],
    view_strides: tuple[int, ...],
    view_suboffsets: tuple[int, ...],
    view_offset: Optional[int],
    view_nbytes: int,
    view_readonly: bool,
) -> Optional[memoryview]:
    """Recreate a released native slice while retaining its exporter alias."""

    try:
        base_view = memoryview(backing)
    except (BufferError, TypeError, ValueError):
        return None

    layout = {
        "view_format": view_format,
        "view_shape": view_shape,
        "view_strides": view_strides,
        "view_suboffsets": view_suboffsets,
        "view_nbytes": view_nbytes,
        "view_readonly": view_readonly,
    }
    if _memoryview_layout_matches(base_view, **layout):
        return base_view
    if (
        view_offset is None
        or not view_shape
        or len(view_shape) != len(view_strides)
        or view_shape[0] < 0
        or view_itemsize <= 0
    ):
        base_view.release()
        return None

    def accepted(candidate: Optional[memoryview]) -> Optional[memoryview]:
        if candidate is None:
            return None
        if _memoryview_layout_matches(candidate, **layout):
            return candidate
        candidate.release()
        return None

    # Preserve arbitrary exporter-provided inner layouts when the released
    # view was a first-axis slice of the exporter's natural memoryview.
    if (
        base_view.format == view_format
        and base_view.itemsize == view_itemsize
        and base_view.readonly is view_readonly
        and base_view.ndim == len(view_shape)
        and base_view.shape[1:] == view_shape[1:]
        and base_view.strides[1:] == view_strides[1:]
        and base_view.suboffsets == view_suboffsets
        and base_view.strides
        and base_view.strides[0] > 0
        and view_offset % base_view.strides[0] == 0
        and view_strides[0] % base_view.strides[0] == 0
    ):
        start = view_offset // base_view.strides[0]
        step = view_strides[0] // base_view.strides[0]
        candidate = accepted(
            _slice_memoryview_first_axis(
                base_view,
                start=start,
                step=step,
                length=view_shape[0],
            )
        )
        if candidate is not None:
            base_view.release()
            return candidate

    # Native multidimensional casts are C-contiguous inside each first-axis
    # row.  Infer the unsliced parent shape, then apply the recorded stride.
    row_nbytes = view_itemsize
    inner_contiguous = True
    for axis in range(len(view_shape) - 1, 0, -1):
        if view_strides[axis] != row_nbytes:
            inner_contiguous = False
            break
        row_nbytes *= view_shape[axis]
    if (
        not inner_contiguous
        or row_nbytes <= 0
        or base_view.nbytes % row_nbytes != 0
        or view_offset % row_nbytes != 0
        or view_strides[0] % row_nbytes != 0
    ):
        base_view.release()
        return None

    parent_shape = (base_view.nbytes // row_nbytes, *view_shape[1:])
    parent_view: Optional[memoryview] = None
    if (
        base_view.format == view_format
        and base_view.shape == parent_shape
        and base_view.itemsize == view_itemsize
    ):
        parent_view = base_view
    else:
        try:
            parent_view = base_view.cast(view_format, shape=parent_shape)
        except (TypeError, ValueError):
            byte_view: Optional[memoryview] = None
            try:
                byte_view = base_view.cast("B")
                parent_view = byte_view.cast(
                    view_format,
                    shape=parent_shape,
                )
            except (TypeError, ValueError):
                parent_view = None
            finally:
                if byte_view is not None:
                    byte_view.release()
        if parent_view is not None:
            base_view.release()
    if parent_view is None:
        base_view.release()
        return None

    candidate = accepted(
        _slice_memoryview_first_axis(
            parent_view,
            start=view_offset // row_nbytes,
            step=view_strides[0] // row_nbytes,
            length=view_shape[0],
        )
    )
    parent_view.release()
    return candidate


def _restore_memoryview_logical_contents(
    view: memoryview,
    raw_contents: bytes,
) -> bool:
    """Restore saved C-order elements through contiguous or strided layouts."""

    if view.readonly:
        return False
    if view.c_contiguous:
        byte_view = view.cast("B")
        try:
            if len(byte_view) != len(raw_contents):
                return False
            byte_view[:] = raw_contents
            return True
        finally:
            byte_view.release()
    if not raw_contents and view.nbytes == 0:
        return True

    source_base = memoryview(raw_contents)
    source_view = source_base
    try:
        if source_view.format != view.format or source_view.shape != view.shape:
            source_view = source_base.cast(view.format, shape=view.shape)
        if view.ndim == 0:
            view[()] = source_view[()]
        elif view.ndim == 1:
            view[:] = source_view
        else:
            for index in itertools.product(*(range(length) for length in view.shape)):
                view[index] = source_view[index]
        return True
    except (IndexError, NotImplementedError, TypeError, ValueError):
        return False
    finally:
        if source_view is not source_base:
            source_view.release()
        source_base.release()


class _RollbackKeepAliveList(list):
    """Record the exact memo value whose stdlib deepcopy just completed."""

    def __init__(
        self,
        memo: "_RollbackDeepcopyMemo",
        values: Iterable[Any] = (),
    ) -> None:
        self._memo = memo
        list.__init__(self, values)

    def append(self, original: Any) -> None:
        list.append(self, original)
        try:
            keep_alive_frame = sys._getframe(1)
        except ValueError:
            return
        deepcopy_frame = keep_alive_frame.f_back
        if (
            keep_alive_frame.f_code is not _STDLIB_KEEP_ALIVE_CODE
            or deepcopy_frame is None
            or deepcopy_frame.f_code is not _STDLIB_DEEPCOPY_CODE
            or keep_alive_frame.f_locals.get("x", _ROLLBACK_DEEPCOPY_MISSING)
            is not original
            or keep_alive_frame.f_locals.get("memo", _ROLLBACK_DEEPCOPY_MISSING)
            is not self._memo
            or deepcopy_frame.f_locals.get("x", _ROLLBACK_DEEPCOPY_MISSING)
            is not original
            or deepcopy_frame.f_locals.get("memo", _ROLLBACK_DEEPCOPY_MISSING)
            is not self._memo
        ):
            return
        copied_value = dict.get(self._memo, id(original), _ROLLBACK_DEEPCOPY_MISSING)
        if (
            copied_value is not _ROLLBACK_DEEPCOPY_MISSING
            and deepcopy_frame.f_locals.get("y", _ROLLBACK_DEEPCOPY_MISSING)
            is copied_value
        ):
            self._memo._record_keepalive_completion(original)


class _RollbackDeepcopyMemo(dict):
    """Deepcopy memo whose ordinary lineage retains rollback authority."""

    def __init__(
        self,
        initial: Optional[Mapping[int, Any]] = None,
        *,
        _transaction_token: Optional[object] = None,
    ) -> None:
        if isinstance(initial, _RollbackDeepcopyMemo):
            with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
                transaction_token = _rollback_deepcopy_completion_transaction(initial)
                initial_values = dict.copy(initial)
        else:
            initial_values = {} if initial is None else dict(initial)
            transaction_token = (
                _transaction_token if _transaction_token is not None else object()
            )
        initial_values[id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL)] = transaction_token
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            _rollback_deepcopy_completion_state(
                self, transaction_token=transaction_token
            )
            dict.__init__(self, initial_values)

    def _invalidate_completion_key(self, key: Any) -> None:
        removed_values = []
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            state = _mutable_rollback_deepcopy_completion_state(self)
            if type(key) is int:
                removed_value = state.pop(key, _ROLLBACK_DEEPCOPY_MISSING)
                if removed_value is not _ROLLBACK_DEEPCOPY_MISSING:
                    removed_values.append(removed_value)
            else:
                removed_values.extend(state.values())
                state.clear()
        removed_values.clear()
        self._invalidate_local_completion_evidence(key)

    def _invalidate_local_completion_evidence(self, key: Any) -> None:
        try:
            frame = sys._getframe(1)
        except ValueError:
            return
        while frame is not None:
            if frame.f_code is _copy_mapping_for_rollback_scoped.__code__:
                frame_locals = frame.f_locals
                transaction_token = frame_locals.get(
                    "completion_transaction",
                    _ROLLBACK_DEEPCOPY_MISSING,
                )
                memo_token = dict.get(
                    self,
                    id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                    _ROLLBACK_DEEPCOPY_MISSING,
                )
                if (
                    memo_token is transaction_token
                    and _rollback_deepcopy_transaction_is_active(transaction_token)
                ):
                    evidence = frame_locals.get("nested_completion_evidence")
                    memo_evidence = (
                        evidence.get(id(self)) if isinstance(evidence, dict) else None
                    )
                    if (
                        isinstance(memo_evidence, tuple)
                        and len(memo_evidence) == 2
                        and memo_evidence[0] is self
                        and isinstance(memo_evidence[1], list)
                    ):
                        if type(key) is not int:
                            memo_evidence[1].clear()
                            snapshot_indexes = frame_locals.get(
                                "completion_snapshot_records"
                            )
                            snapshot_entry = (
                                snapshot_indexes.get(id(self))
                                if isinstance(snapshot_indexes, dict)
                                else None
                            )
                            if (
                                isinstance(snapshot_entry, tuple)
                                and len(snapshot_entry) == 2
                                and snapshot_entry[0] is self
                                and isinstance(snapshot_entry[1], dict)
                            ):
                                snapshot_entry[1].clear()
                    break
            frame = frame.f_back

    def _record_local_memo_mutation(
        self,
        dict_version_before: Optional[int],
        dict_version_after: Optional[int],
    ) -> None:
        """Attach an exact normal-return memo mutation to local evidence."""

        try:
            caller = sys._getframe(1)
        except ValueError:
            return
        instrumentation_active = bool(
            sys.gettrace() is not None or sys.getprofile() is not None
        )
        if (
            caller.f_code not in _ROLLBACK_DEEPCOPY_MEMO_MUTATION_CODES
            or caller.f_locals.get("self") is not self
            or caller.f_locals.get("dict_version_before") is not dict_version_before
            or caller.f_locals.get("dict_version_after") is not dict_version_after
            or dict_version_before == dict_version_after
            or instrumentation_active
        ):
            return
        frame = caller
        while frame is not None:
            if frame.f_code is _copy_mapping_for_rollback_scoped.__code__:
                frame_locals = frame.f_locals
                transaction_token = frame_locals.get(
                    "completion_transaction",
                    _ROLLBACK_DEEPCOPY_MISSING,
                )
                if (
                    dict.get(
                        self,
                        id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    is not transaction_token
                    or not _rollback_deepcopy_transaction_is_active(transaction_token)
                ):
                    break
                mutation_journals = frame_locals.get("nested_completion_mutations")
                memo_mutations = (
                    mutation_journals.setdefault(id(self), (self, []))
                    if isinstance(mutation_journals, dict)
                    else None
                )
                if (
                    isinstance(memo_mutations, tuple)
                    and len(memo_mutations) == 2
                    and memo_mutations[0] is self
                    and isinstance(memo_mutations[1], list)
                ):
                    memo_mutations[1].append((caller, sys._getframe()))
                break
            frame = frame.f_back

    def _transfer_local_completion_evidence(
        self, source: "_RollbackDeepcopyMemo"
    ) -> None:
        try:
            caller = sys._getframe(1)
        except ValueError:
            return
        instrumentation_active = bool(
            sys.gettrace() is not None or sys.getprofile() is not None
        )
        called_from_update = bool(
            caller.f_code is _RollbackDeepcopyMemo.update.__code__
            and caller.f_locals.get("self") is self
            and caller.f_locals.get("other") is source
        )
        called_from_copy = bool(
            caller.f_code is _RollbackDeepcopyMemo.copy.__code__
            and caller.f_locals.get("self") is source
            and caller.f_locals.get("copied") is self
        )
        if not called_from_update and not called_from_copy:
            return
        if instrumentation_active:
            return
        source_dict_version = _rollback_dict_version(source)
        target_dict_version = _rollback_dict_version(self)
        if source_dict_version is None or target_dict_version is None:
            return
        frame = caller
        while frame is not None:
            if frame.f_code is _copy_mapping_for_rollback_scoped.__code__:
                frame_locals = frame.f_locals
                transaction_token = frame_locals.get(
                    "completion_transaction",
                    _ROLLBACK_DEEPCOPY_MISSING,
                )
                if (
                    dict.get(
                        self,
                        id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    is not transaction_token
                    or dict.get(
                        source,
                        id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    is not transaction_token
                    or not _rollback_deepcopy_transaction_is_active(transaction_token)
                ):
                    break
                evidence = frame_locals.get("nested_completion_evidence")
                mutation_journals = frame_locals.get("nested_completion_mutations")
                snapshot_indexes = frame_locals.get("completion_snapshot_records")
                if (
                    not isinstance(evidence, dict)
                    or not isinstance(mutation_journals, dict)
                    or not isinstance(snapshot_indexes, dict)
                ):
                    break
                source_mutations = mutation_journals.setdefault(
                    id(source), (source, [])
                )
                target_mutations = mutation_journals.setdefault(id(self), (self, []))
                source_snapshot_entry = snapshot_indexes.setdefault(
                    id(source), (source, {})
                )
                target_snapshot_entry = snapshot_indexes.setdefault(
                    id(self), (self, {})
                )
                if (
                    not isinstance(source_mutations, tuple)
                    or len(source_mutations) != 2
                    or source_mutations[0] is not source
                    or not isinstance(source_mutations[1], list)
                    or not isinstance(target_mutations, tuple)
                    or len(target_mutations) != 2
                    or target_mutations[0] is not self
                    or not isinstance(target_mutations[1], list)
                    or not isinstance(source_snapshot_entry, tuple)
                    or len(source_snapshot_entry) != 2
                    or source_snapshot_entry[0] is not source
                    or not isinstance(source_snapshot_entry[1], dict)
                    or not isinstance(target_snapshot_entry, tuple)
                    or len(target_snapshot_entry) != 2
                    or target_snapshot_entry[0] is not self
                    or not isinstance(target_snapshot_entry[1], dict)
                ):
                    break
                source_mutation_count = len(source_mutations[1])
                target_mutation_count = len(target_mutations[1])
                if source_mutation_count < 0 or target_mutation_count < 0:
                    break
                source_entry = evidence.get(id(source))
                if (
                    not isinstance(source_entry, tuple)
                    or len(source_entry) != 2
                    or source_entry[0] is not source
                    or not isinstance(source_entry[1], list)
                ):
                    break
                target_entry = evidence.setdefault(id(self), (self, []))
                if (
                    not isinstance(target_entry, tuple)
                    or len(target_entry) != 2
                    or target_entry[0] is not self
                    or not isinstance(target_entry[1], list)
                ):
                    break
                if self is source:
                    break
                for record in tuple(source_entry[1]):
                    if (
                        isinstance(record, tuple)
                        and len(record) == 3
                        and isinstance(record[0], types.FrameType)
                        and isinstance(record[1], types.FrameType)
                        and isinstance(record[2], tuple)
                    ):
                        original = record[0].f_locals.get(
                            "x", _ROLLBACK_DEEPCOPY_MISSING
                        )
                        copied_value = record[0].f_locals.get(
                            "y", _ROLLBACK_DEEPCOPY_MISSING
                        )
                    else:
                        continue
                    if (
                        original is not _ROLLBACK_DEEPCOPY_MISSING
                        and copied_value is not _ROLLBACK_DEEPCOPY_MISSING
                        and dict.get(
                            self,
                            id(original),
                            _ROLLBACK_DEEPCOPY_MISSING,
                        )
                        is copied_value
                    ):
                        transferred_record = (
                            record[0],
                            record[1],
                            (
                                *record[2],
                                (caller, sys._getframe()),
                            ),
                        )
                        target_entry[1].append(transferred_record)
                        target_snapshot_entry[1][id(copied_value)] = transferred_record
                break
            frame = frame.f_back

    def _clear_completion_values(self) -> List[Any]:
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            state = _mutable_rollback_deepcopy_completion_state(self)
            removed_values = list(state.values())
            state.clear()
        self._invalidate_local_completion_evidence(None)
        return removed_values

    def _record_keepalive_completion(self, original: Any) -> None:
        try:
            caller = sys._getframe(1)
        except ValueError:
            return
        instrumentation_active = bool(
            sys.gettrace() is not None or sys.getprofile() is not None
        )
        keepalive = caller.f_locals.get("self", _ROLLBACK_DEEPCOPY_MISSING)
        if (
            caller.f_code is not _RollbackKeepAliveList.append.__code__
            or type(keepalive) is not _RollbackKeepAliveList
            or keepalive._memo is not self
            or caller.f_locals.get("original", _ROLLBACK_DEEPCOPY_MISSING)
            is not original
        ):
            return
        keepalive_frame = caller.f_back
        deepcopy_frame = keepalive_frame.f_back if keepalive_frame is not None else None
        if (
            keepalive_frame is None
            or keepalive_frame.f_code is not _STDLIB_KEEP_ALIVE_CODE
            or deepcopy_frame is None
            or deepcopy_frame.f_code is not _STDLIB_DEEPCOPY_CODE
        ):
            return
        copied_value = dict.get(self, id(original), _ROLLBACK_DEEPCOPY_MISSING)
        completion_dict_version = _rollback_dict_version(self)
        completion_mutation_count = -1
        completion_snapshot = _ROLLBACK_DEEPCOPY_MISSING
        if copied_value is not _ROLLBACK_DEEPCOPY_MISSING:
            # The module-level registry supports memo lineage and cleanup, but
            # it is not completion authority: Python exposes closure cells to
            # arbitrary custom ``__deepcopy__`` hooks. Record successful
            # stdlib control flow directly in the active rollback frame's
            # private journal, which is the same authority used by our own
            # copier and is never exported through a module function closure.
            rollback_frame = deepcopy_frame.f_back
            while rollback_frame is not None:
                if rollback_frame.f_code is _copy_mapping_for_rollback_scoped.__code__:
                    rollback_locals = rollback_frame.f_locals
                    transaction_token = rollback_locals.get(
                        "completion_transaction",
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    memo_token = dict.get(
                        self,
                        id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    completion_evidence = rollback_locals.get(
                        "nested_completion_evidence"
                    )
                    mutation_journals = rollback_locals.get(
                        "nested_completion_mutations"
                    )
                    snapshot_capture = rollback_locals.get(
                        "capture_completion_snapshot"
                    )
                    snapshot_record_indexes = rollback_locals.get(
                        "completion_snapshot_records"
                    )
                    memo_mutations = (
                        mutation_journals.setdefault(id(self), (self, []))
                        if isinstance(mutation_journals, dict)
                        else None
                    )
                    snapshot_record_entry = (
                        snapshot_record_indexes.setdefault(id(self), (self, {}))
                        if isinstance(snapshot_record_indexes, dict)
                        else None
                    )
                    if (
                        memo_token is transaction_token
                        and _rollback_deepcopy_transaction_is_active(transaction_token)
                        and isinstance(completion_evidence, dict)
                        and isinstance(snapshot_capture, types.FunctionType)
                        and snapshot_capture.__code__
                        is _ROLLBACK_COMPLETION_SNAPSHOT_CODE
                        and isinstance(memo_mutations, tuple)
                        and len(memo_mutations) == 2
                        and memo_mutations[0] is self
                        and isinstance(memo_mutations[1], list)
                        and isinstance(snapshot_record_entry, tuple)
                        and len(snapshot_record_entry) == 2
                        and snapshot_record_entry[0] is self
                        and isinstance(snapshot_record_entry[1], dict)
                        and not instrumentation_active
                        and completion_dict_version is not None
                    ):
                        completion_mutation_count = len(memo_mutations[1])
                        if _rollback_snapshot_function_is_authentic(snapshot_capture):
                            try:
                                completion_snapshot = snapshot_capture(
                                    copied_value,
                                    snapshot_record_entry[1],
                                )
                            except Exception:
                                completion_snapshot = _ROLLBACK_DEEPCOPY_MISSING
                        memo_evidence = completion_evidence.setdefault(
                            id(self), (self, [])
                        )
                        if (
                            isinstance(memo_evidence, tuple)
                            and len(memo_evidence) == 2
                            and memo_evidence[0] is self
                            and isinstance(memo_evidence[1], list)
                            and completion_mutation_count >= 0
                        ):
                            completion_record = (
                                deepcopy_frame,
                                sys._getframe(),
                                (),
                            )
                            memo_evidence[1].append(completion_record)
                            if completion_snapshot is not _ROLLBACK_DEEPCOPY_MISSING:
                                snapshot_record_entry[1][id(copied_value)] = (
                                    completion_record
                                )
                        break
                rollback_frame = rollback_frame.f_back
            displaced_values = []
            original_id = id(original)
            with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
                state = _mutable_rollback_deepcopy_completion_state(self)
                displaced_value = state.get(original_id, _ROLLBACK_DEEPCOPY_MISSING)
                state[original_id] = copied_value
                if (
                    displaced_value is not _ROLLBACK_DEEPCOPY_MISSING
                    and displaced_value is not copied_value
                ):
                    displaced_values.append(displaced_value)
            displaced_values.clear()

    def keepalive_completion_is_current(
        self, original_id: int, copied_value: Any
    ) -> bool:
        if type(original_id) is not int:
            return False
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            return (
                _rollback_deepcopy_completion_state(self).get(
                    original_id, _ROLLBACK_DEEPCOPY_MISSING
                )
                is copied_value
            )

    def __getitem__(self, key: Any) -> Any:
        dict_version_before = _rollback_dict_version(self)
        try:
            value = dict.__getitem__(self, key)
        except KeyError:
            if type(key) is not int or key != id(self):
                raise
            value = _RollbackKeepAliveList(self)
            dict.__setitem__(self, key, value)
        if type(key) is int and key == id(self) and type(value) is list:
            value = _RollbackKeepAliveList(self, value)
            dict.__setitem__(self, key, value)
        dict_version_after = _rollback_dict_version(self)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)
        return value

    def __setitem__(self, key: Any, value: Any) -> None:
        dict_version_before = _rollback_dict_version(self)
        if type(key) is int and key == id(self) and type(value) is list:
            value = _RollbackKeepAliveList(self, value)
        dict.__setitem__(self, key, value)
        dict_version_after = _rollback_dict_version(self)
        self._invalidate_completion_key(key)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)

    def __delitem__(self, key: Any) -> None:
        dict_version_before = _rollback_dict_version(self)
        dict.__delitem__(self, key)
        dict_version_after = _rollback_dict_version(self)
        self._invalidate_completion_key(key)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)

    def pop(self, key: Any, *default: Any) -> Any:
        dict_version_before = _rollback_dict_version(self)
        existed = dict.__contains__(self, key)
        value = dict.pop(self, key, *default)
        dict_version_after = _rollback_dict_version(self)
        if existed:
            self._invalidate_completion_key(key)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)
        return value

    def popitem(self) -> tuple[Any, Any]:
        dict_version_before = _rollback_dict_version(self)
        key, value = dict.popitem(self)
        dict_version_after = _rollback_dict_version(self)
        self._invalidate_completion_key(key)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)
        return key, value

    def setdefault(self, key: Any, default: Any = None) -> Any:
        dict_version_before = _rollback_dict_version(self)
        existed = dict.__contains__(self, key)
        if type(key) is int and key == id(self) and type(default) is list:
            default = _RollbackKeepAliveList(self, default)
        value = dict.setdefault(self, key, default)
        if not existed:
            self._invalidate_completion_key(key)
        if type(key) is int and key == id(self) and type(value) is list:
            value = _RollbackKeepAliveList(self, value)
            dict.__setitem__(self, key, value)
        dict_version_after = _rollback_dict_version(self)
        self._record_local_memo_mutation(dict_version_before, dict_version_after)
        return value

    def update(self, other: Any = (), /, **values: Any) -> None:
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            source_completions = dict(
                _rollback_deepcopy_completion_state(other)
                if isinstance(other, _RollbackDeepcopyMemo)
                else {}
            )
            rollback_items = (
                ([] if other is self else list(dict.copy(other).items()))
                if isinstance(other, _RollbackDeepcopyMemo)
                else None
            )
        completion_updates: Dict[int, Any] = {}

        def assign(key: Any, value: Any) -> None:
            self[key] = value
            if type(key) is int:
                completed_value = source_completions.get(
                    key, _ROLLBACK_DEEPCOPY_MISSING
                )
                if completed_value is value:
                    completion_updates[key] = value

        try:
            if rollback_items is not None:
                for key, value in rollback_items:
                    assign(key, value)
            else:
                keys = getattr(other, "keys", None)
                if callable(keys):
                    for key in keys():
                        assign(key, other[key])
                else:
                    for key, value in other:
                        assign(key, value)
            for key, value in values.items():
                assign(key, value)
        finally:
            displaced_values = []
            with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
                state = _mutable_rollback_deepcopy_completion_state(self)
                for key, value in completion_updates.items():
                    displaced_value = state.get(key, _ROLLBACK_DEEPCOPY_MISSING)
                    state[key] = value
                    if (
                        displaced_value is not _ROLLBACK_DEEPCOPY_MISSING
                        and displaced_value is not value
                    ):
                        displaced_values.append(displaced_value)
            displaced_values.clear()
        if isinstance(other, _RollbackDeepcopyMemo):
            self._transfer_local_completion_evidence(other)

    def __ior__(self, other: Any) -> "_RollbackDeepcopyMemo":
        self.update(other)
        return self

    def __or__(self, other: Any) -> Any:
        if not isinstance(other, dict):
            return NotImplemented
        copied = self.copy()
        copied.update(other)
        return copied

    def __ror__(self, other: Any) -> Any:
        if not isinstance(other, dict):
            return NotImplemented
        copied = self.copy()
        copied.clear()
        copied.update(other)
        copied.update(self)
        return copied

    def _mark_transaction(self) -> None:
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            transaction_token = _rollback_deepcopy_completion_transaction(self)
        dict.__setitem__(
            self,
            id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
            transaction_token,
        )

    def clear(self) -> None:
        removed_completion_values = self._clear_completion_values()
        dict.clear(self)
        removed_completion_values.clear()
        self._mark_transaction()

    def copy(self) -> "_RollbackDeepcopyMemo":
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            initial_values = dict.copy(self)
            transaction_token = _rollback_deepcopy_completion_transaction(self)
            completions = dict(_rollback_deepcopy_completion_state(self))
        copied = _RollbackDeepcopyMemo(
            initial_values,
            _transaction_token=transaction_token,
        )
        current_completions = {
            key: value
            for key, value in completions.items()
            if dict.get(copied, key, _ROLLBACK_DEEPCOPY_MISSING) is value
        }
        displaced_values = []
        with _ROLLBACK_DEEPCOPY_COMPLETION_STATES_LOCK:
            state = _mutable_rollback_deepcopy_completion_state(copied)
            for key, value in current_completions.items():
                displaced_value = state.get(key, _ROLLBACK_DEEPCOPY_MISSING)
                state[key] = value
                if (
                    displaced_value is not _ROLLBACK_DEEPCOPY_MISSING
                    and displaced_value is not value
                ):
                    displaced_values.append(displaced_value)
        displaced_values.clear()
        copied._transfer_local_completion_evidence(self)
        return copied

    def __copy__(self) -> "_RollbackDeepcopyMemo":
        return self.copy()


_ROLLBACK_DEEPCOPY_COMPLETION_MUTATOR_CODES = frozenset(
    {
        _RollbackDeepcopyMemo._invalidate_completion_key.__code__,
        _RollbackDeepcopyMemo._clear_completion_values.__code__,
        _RollbackDeepcopyMemo._record_keepalive_completion.__code__,
        _RollbackDeepcopyMemo.update.__code__,
        _RollbackDeepcopyMemo.copy.__code__,
    }
)
_ROLLBACK_DEEPCOPY_MEMO_MUTATION_CODES = frozenset(
    {
        _RollbackDeepcopyMemo.__getitem__.__code__,
        _RollbackDeepcopyMemo.__setitem__.__code__,
        _RollbackDeepcopyMemo.__delitem__.__code__,
        _RollbackDeepcopyMemo.pop.__code__,
        _RollbackDeepcopyMemo.popitem.__code__,
        _RollbackDeepcopyMemo.setdefault.__code__,
    }
)


_RETRYABLE_FINAL_NO_TOOLS_FAILURE_KINDS = frozenset(
    {
        "final_no_tools_empty_output",
        "final_no_tools_forbidden_command",
        "final_no_tools_provider_ignored_tool_choice_none_budget_exhausted",
        "final_no_tools_token_exhausted",
        "final_no_tools_transcript_echo",
        "deepseek_tool_after_budget",
    }
)
_MAX_DURABLE_SEMANTIC_LEDGER_IDENTITIES = 4096
_GENERATED_SOLUTION_REF_ALIAS_RE = re.compile(r"\bsolution_ref_hidden_[A-Za-z0-9_]+\b")

# Route capability can change when another provider lane is available.
_PROVIDER_BLOCKED_FAILURE_REASONS = frozenset(
    {
        "provider_capability_conflict",
        "llm_required_prompt_context_overflow",
    }
)
_PROVIDER_BLOCKED_FAILURE_KINDS = frozenset(
    {
        "provider_capability_conflict",
        "llm_required_prompt_context_overflow",
    }
)
_PROVIDER_BLOCKED_REASON_BY_KIND = {
    "provider_capability_conflict": "provider_capability_conflict",
    "llm_required_prompt_context_overflow": ("llm_required_prompt_context_overflow"),
}
_LEAN_TOOL_INFRASTRUCTURE_RETRY_KINDS = frozenset(
    {
        "lean_tool_infrastructure_retry_pending",
        "lean_verifier_infrastructure_unavailable",
    }
)


def _nonnegative_metadata_int(
    metadata: Mapping[str, Any],
    key: str,
) -> int:
    try:
        return max(0, int(metadata.get(key, 0) or 0))
    except (TypeError, ValueError, OverflowError):
        return 0


def _normalize_provider_exposure_metadata(metadata: Dict[str, Any]) -> None:
    """Make concrete dispatch evidence dominate stale derived refund bits."""

    completed = _nonnegative_metadata_int(metadata, "provider_calls_completed")
    dispatched = _nonnegative_metadata_int(metadata, "provider_dispatches_started")
    try:
        provider_defer_ready_at = float(
            metadata.get("provider_defer_ready_at", 0.0) or 0.0
        )
    except (TypeError, ValueError, OverflowError):
        provider_defer_ready_at = 0.0
    pre_generation_capacity_receipt = bool(
        completed == 0
        and str(metadata.get("provider_defer_fingerprint") or "").strip()
        and math.isfinite(provider_defer_ready_at)
        and provider_defer_ready_at > 0.0
    )
    if "provider_calls_completed" in metadata:
        metadata["provider_calls_completed"] = completed
    if "provider_dispatches_started" in metadata:
        metadata["provider_dispatches_started"] = dispatched
    if completed > 0 or (dispatched > 0 and not pre_generation_capacity_receipt):
        metadata["zero_provider_failure"] = False
    elif pre_generation_capacity_receipt:
        # A typed 429 receipt proves that the HTTP boundary was crossed but
        # generation never began. Preserve mathematical action capacity while
        # still accounting for the physical dispatch above.
        metadata["zero_provider_failure"] = True


def _normalize_provider_blocked_failure_metadata(
    metadata: Dict[str, Any],
) -> None:
    """Convert recoverable provider blocks into in-process scheduler waits."""

    terminal_reason = str(metadata.get("terminal_failure_reason") or "").strip()
    scoped_reason = str(metadata.get("scoped_failure_reason") or "").strip()
    failure_kind = str(
        metadata.get("llm_failure_kind") or metadata.get("terminal_failure_kind") or ""
    ).strip()
    blocked_reason = ""
    if terminal_reason in _PROVIDER_BLOCKED_FAILURE_REASONS:
        blocked_reason = terminal_reason
    elif scoped_reason in _PROVIDER_BLOCKED_FAILURE_REASONS:
        blocked_reason = scoped_reason
    elif failure_kind in _PROVIDER_BLOCKED_FAILURE_KINDS:
        blocked_reason = _PROVIDER_BLOCKED_REASON_BY_KIND[failure_kind]
    if not blocked_reason:
        return
    metadata["terminal_failure"] = False
    metadata["terminal_failure_reason"] = ""
    metadata["scoped_failure_reason"] = blocked_reason
    metadata["llm_failure_scope"] = "scoped"
    metadata["llm_retryable"] = True
    metadata["preserve_frontier_work"] = True
    metadata["defer_selected_frontier_action"] = True
    _normalize_provider_exposure_metadata(metadata)
    provider_calls_completed = _nonnegative_metadata_int(
        metadata,
        "provider_calls_completed",
    )
    provider_dispatches_started = _nonnegative_metadata_int(
        metadata,
        "provider_dispatches_started",
    )
    metadata["provider_calls_completed"] = provider_calls_completed
    if provider_calls_completed == 0 and provider_dispatches_started == 0:
        metadata["zero_provider_failure"] = True


_OPERATION_CHILD_TASK_TRACKER: contextvars.ContextVar[
    Optional["_OperationChildTaskTracker"]
] = contextvars.ContextVar(
    "mini_session_operation_child_task_tracker",
    default=None,
)
_OPERATION_TASK_FACTORY_STATES: "weakref.WeakKeyDictionary[Any, Dict[str, Any]]" = (
    weakref.WeakKeyDictionary()
)
# Identity set of the loop routers we have installed.  Classification runs on
# foreign threads (CPython's waitpid thread delivers subprocess exit through
# ``call_soon_threadsafe``), so this must never be *iterated* -- iterating
# ``_OPERATION_TASK_FACTORY_STATES`` there raced its loop-thread mutation and
# raised "dictionary changed size during iteration" inside
# ``ThreadedChildWatcher._do_waitpid``, which has no exception handling: the
# waitpid thread would die and the child exit would be lost forever.  A set
# membership test is a single hash lookup with no iteration guard.
_INSTALLED_LOOP_ROUTERS: "set[Any]" = set()
# Process-local subscribers let an in-process Lean generation swap update
# every parallel MiniSession that directly owns the same runner.  Weak
# references avoid extending session lifetimes.
_LIVE_MINI_SESSION_REFS: List["weakref.ReferenceType[MiniSession]"] = []
# Scans temporarily hold the last strong reference to a session. Reassigning
# that local can run its weakref callback on the same thread, so this lock must
# remain reentrant.
_LIVE_MINI_SESSION_REFS_LOCK = threading.RLock()
_OPERATION_CHILD_SETTLEMENT_TIMEOUT_S = 5.0
_OPERATION_DAEMON_WORKER_SLOTS = threading.BoundedSemaphore(32)


def _deepcopy_after_dispatch_miss(value: Any, memo: Dict[int, Any]) -> Any:
    """Run the stdlib deepcopy fallback with no exact-type dispatcher."""

    value_type = type(value)
    if issubclass(value_type, type):
        copied_value = value
    else:
        copier = getattr(value, "__deepcopy__", None)
        if copier is not None:
            copied_value = copier(memo)
        else:
            reducer = copyreg.dispatch_table.get(value_type)
            if reducer is not None:
                reduction = reducer(value)
            else:
                reducer = getattr(value, "__reduce_ex__", None)
                if reducer is not None:
                    reduction = reducer(4)
                else:
                    reducer = getattr(value, "__reduce__", None)
                    if reducer is None:
                        raise copy.Error(
                            f"un(deep)copyable object of type {value_type!r}"
                        )
                    reduction = reducer()
            if type(reduction) is str:
                copied_value = value
            else:
                copied_value = copy._reconstruct(  # noqa: SLF001
                    value, memo, *reduction
                )
    if copied_value is not value:
        memo[id(value)] = copied_value
        copy._keep_alive(value, memo)  # noqa: SLF001
    return copied_value


def _runtime_deepcopy_dispatch(value: Any, memo: Dict[int, Any]) -> Any:
    """Share runtime authority only for the exact rollback memo."""

    transaction_authority = _rollback_deepcopy_transaction_is_active(
        memo.get(
            id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL),
            _ROLLBACK_DEEPCOPY_MISSING,
        )
    )
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        active_entry = _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS.get(id(memo))
        rollback_memo_active = bool(
            active_entry is not None and active_entry[0] is memo
        )
    if rollback_memo_active or transaction_authority:
        memo[id(value)] = value
        return value
    current = copy._deepcopy_dispatch  # noqa: SLF001
    if isinstance(current, _RuntimeAwareDeepcopyDispatch):
        original = dict.get(current, type(value), _ROLLBACK_DEEPCOPY_MISSING)
    else:
        original = current.get(type(value), _ROLLBACK_DEEPCOPY_MISSING)
    if original is not _ROLLBACK_DEEPCOPY_MISSING:
        return original(value, memo)
    return _deepcopy_after_dispatch_miss(value, memo)


class _RuntimeAwareDeepcopyDispatch(dict):
    """Stdlib dispatch table with rollback-memo subclass recognition."""

    def __init__(
        self,
        initial: Mapping[type, Any],
        runtime_types: Iterable[type],
    ) -> None:
        super().__init__(initial)
        self._runtime_type_ids = frozenset(id(item) for item in runtime_types)

    def add_runtime_types(self, runtime_types: Iterable[type]) -> None:
        self._runtime_type_ids = self._runtime_type_ids.union(
            id(item) for item in runtime_types
        )

    def get(self, key: Any, default: Any = None) -> Any:
        try:
            key_mro = type.__getattribute__(key, "__mro__")
        except (AttributeError, TypeError):
            key_mro = ()
        if any(owner is asyncio.AbstractEventLoop for owner in key_mro):
            # Event loops have no valid deepcopy representation. The stdlib
            # reducer allocates a partial loop and can invoke its destructor
            # before ``_closed`` exists, so loops are always external runtime
            # authority even when a hostile hook strips memo lineage.
            return copy._deepcopy_atomic  # noqa: SLF001
        if any(id(owner) in self._runtime_type_ids for owner in key_mro):
            return _runtime_deepcopy_dispatch
        return dict.get(self, key, default)


def _install_runtime_aware_deepcopy_dispatch(
    runtime_types: Iterable[type],
) -> None:
    """Install subclass-aware runtime sharing without changing other contexts.

    A user ``__deepcopy__`` hook can create a runtime object *after* rollback
    preflight, and a previously imported ``deepcopy`` alias still reads the
    copy module's dispatch mapping at call time. The handler then recognizes
    future subclasses but shares them only when its memo contains this
    rollback transaction's private sentinel.
    """

    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        current = copy._deepcopy_dispatch  # noqa: SLF001
        if isinstance(current, _RuntimeAwareDeepcopyDispatch):
            current.add_runtime_types(runtime_types)
            return
        copy._deepcopy_dispatch = _RuntimeAwareDeepcopyDispatch(  # noqa: SLF001
            current, runtime_types
        )


def _register_active_rollback_memo(memo: Dict[int, Any]) -> None:
    """Mark one memo identity as an active rollback transaction."""

    memo_id = id(memo)
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        active_entry = _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS.get(memo_id)
        if active_entry is not None and active_entry[0] is memo:
            _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS[memo_id] = (
                memo,
                active_entry[1] + 1,
            )
        else:
            _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS[memo_id] = (memo, 1)


def _unregister_active_rollback_memo(memo: Dict[int, Any]) -> None:
    """Release one reentrant registration of a rollback memo identity."""

    memo_id = id(memo)
    with _ROLLBACK_DEEPCOPY_DISPATCH_LOCK:
        active_entry = _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS.get(memo_id)
        if active_entry is None or active_entry[0] is not memo:
            return
        if active_entry[1] > 1:
            _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS[memo_id] = (
                memo,
                active_entry[1] - 1,
            )
        else:
            _ACTIVE_ROLLBACK_DEEPCOPY_MEMOS.pop(memo_id, None)


def _discard_live_mini_session_ref(
    dead_ref: "weakref.ReferenceType[MiniSession]",
) -> None:
    """Remove a finalized session's weakref wrapper from the subscriber list."""

    with _LIVE_MINI_SESSION_REFS_LOCK:
        for index, ref in enumerate(_LIVE_MINI_SESSION_REFS):
            if ref is dead_ref:
                del _LIVE_MINI_SESSION_REFS[index]
                break


def _copy_mapping_for_rollback(values: Mapping[str, Any]) -> Dict[str, Any]:
    """Copy rollback state using a transaction-marked deepcopy memo."""

    return _copy_mapping_for_rollback_scoped(values)


def _copy_mapping_for_rollback_scoped(
    values: Mapping[str, Any],
) -> Dict[str, Any]:
    """Copy rollback state without sacrificing copyable peers of capabilities.

    Runtime capability fields name externally owned authority: LLM clients,
    the Mathlib retrieval service, the Lean handle, the recorder.  A rolled
    back dispatch must be handed the *same* handle it had, never a private
    clone, so these are shared by reference rather than copied.  Cloning them
    is also ruinously expensive: ``searcher_override`` reaches the 214k-entry
    Mathlib index, and 887fa7f2 turned this helper from an O(1) dict return
    into a per-action deep copy, which put ~10s of cloning on every dispatch
    for each searcher-bearing action.  Only genuinely owned mutable state --
    cursors, attempted-key ledgers, counters -- needs a real copy.
    """

    def raw_class_mro(value_type: type) -> tuple[type, ...]:
        """Read a class MRO without invoking its metaclass hooks."""

        try:
            return type.__getattribute__(value_type, "__mro__")
        except (AttributeError, TypeError):
            return (value_type,)

    def raw_value_mro(value: Any) -> tuple[type, ...]:
        return raw_class_mro(type(value))

    def raw_inherits(value: Any, expected_type: type) -> bool:
        """Check an actual MRO without consulting a proxy's ``__class__``."""

        return any(owner is expected_type for owner in raw_value_mro(value))

    def raw_class_namespace(value_type: type) -> Mapping[str, Any]:
        """Read a class namespace without invoking its metaclass hooks."""

        try:
            return type.__getattribute__(value_type, "__dict__")
        except (AttributeError, TypeError):
            return {}

    def raw_class_name(value_type: type) -> str:
        try:
            return str(type.__getattribute__(value_type, "__name__"))
        except (AttributeError, TypeError):
            return ""

    shared: Dict[str, Any] = {}
    copyable: Dict[str, Any] = {}
    for key, value in values.items():
        if field_is_runtime_capability(key):
            shared[key] = value
        else:
            copyable[key] = value
    shared_identity_memo: Dict[int, Any] = {
        id(value): value for value in shared.values()
    }
    rollback_memo_seed = {
        id(_ROLLBACK_DEEPCOPY_MEMO_SENTINEL): _ROLLBACK_DEEPCOPY_MEMO_SENTINEL
    }

    class ReplayableReductionIterator:
        """Lazily consume a reducer iterator once and replay its prefix.

        Reducer callbacks and iterator advancement must remain interleaved.
        Caching yielded values permits reconstruction after a nested failure
        without either exhausting the iterator up front or invoking it twice.
        """

        def __init__(self, source: Iterable[Any]) -> None:
            self._source_value = source
            self._source: Any = None
            self._started = False
            self._items: List[Any] = []
            self._exhausted = False
            self._failure: Optional[Exception] = None

        def __iter__(self) -> Iterable[Any]:
            index = 0
            while True:
                if index < len(self._items):
                    item = self._items[index]
                    index += 1
                    yield item
                    continue
                if self._failure is not None:
                    raise self._failure
                if self._exhausted:
                    return
                if not self._started:
                    try:
                        self._source = iter(self._source_value)
                    except Exception as exc:
                        self._failure = exc
                        raise
                    self._started = True
                try:
                    item = next(self._source)
                except StopIteration:
                    self._exhausted = True
                    return
                except Exception as exc:
                    self._failure = exc
                    raise
                self._items.append(item)
                index += 1
                yield item

    runtime_leaf_types = (
        asyncio.AbstractEventLoop,
        asyncio.Future,
        asyncio.Lock,
        asyncio.Event,
        asyncio.Condition,
        asyncio.Semaphore,
        asyncio.BoundedSemaphore,
        asyncio.Queue,
        asyncio.PriorityQueue,
        asyncio.LifoQueue,
        type(threading.Lock()),
        type(threading.RLock()),
        threading.Condition,
        threading.Semaphore,
        threading.BoundedSemaphore,
        threading.Event,
        weakref.ProxyType,
        weakref.CallableProxyType,
    )
    runtime_leaf_type_ids = frozenset(id(item) for item in runtime_leaf_types)
    _install_runtime_aware_deepcopy_dispatch(runtime_leaf_types)
    rollback_iterator_types = (
        type(iter([])),
        type(reversed([])),
        type(iter(())),
        type(iter(range(0))),
        type(iter({})),
        type(iter({}.values())),
        type(iter({}.items())),
        type(iter(set())),
    )
    ordered_iterator_probe: collections.OrderedDict[Any, Any] = (
        collections.OrderedDict()
    )
    rollback_ordered_iterator_types = frozenset(
        {
            type(collections.OrderedDict.__iter__(ordered_iterator_probe)),
            type(collections.OrderedDict.__reversed__(ordered_iterator_probe)),
            type(iter(collections.OrderedDict.keys(ordered_iterator_probe))),
            type(iter(collections.OrderedDict.values(ordered_iterator_probe))),
            type(iter(collections.OrderedDict.items(ordered_iterator_probe))),
        }
    )
    rollback_gc_wrapper_types = (
        types.MappingProxyType,
        types.GeneratorType,
        types.CoroutineType,
        types.AsyncGeneratorType,
        types.MethodWrapperType,
        type({}.keys()),
        type({}.values()),
        type({}.items()),
        type(enumerate(())),
        type(zip()),
        type(map(bool, ())),
        type(filter(bool, ())),
    )
    rollback_builtin_iteration_wrapper_types = (
        type(enumerate(())),
        type(zip()),
        type(map(bool, ())),
        type(filter(bool, ())),
    )
    rollback_operator_wrapper_types = (
        operator.attrgetter,
        operator.itemgetter,
        operator.methodcaller,
    )

    def rollback_operator_wrapper_state(
        value: Any,
    ) -> tuple[tuple[Any, ...], Dict[str, Any]]:
        """Expose exact operator-wrapper constructor state without callbacks."""

        value_type = type(value)
        if value_type in {operator.attrgetter, operator.itemgetter}:
            _constructor, arguments = value_type.__reduce__(value)
            return tuple(arguments), {}
        constructor, arguments = operator.methodcaller.__reduce__(value)
        if not isinstance(constructor, functools.partial):
            return tuple(arguments), {}
        return (
            (*constructor.args, *tuple(arguments)),
            dict(constructor.keywords or {}),
        )

    def rollback_builtin_exception_descriptor_state(
        value: BaseException,
    ) -> List[tuple[str, Any, bool, Any]]:
        """Read built-in exception fields through their raw descriptors."""

        state: List[tuple[str, Any, bool, Any]] = []
        seen_descriptors: Set[int] = set()
        value_type = type(value)
        for owner in raw_value_mro(value):
            if id(
                owner
            ) not in _BUILTIN_TYPE_IDENTITY_IDS or BaseException not in raw_class_mro(
                owner
            ):
                continue
            for name, descriptor in raw_class_namespace(owner).items():
                if (
                    name == "__dict__"
                    or id(descriptor) in seen_descriptors
                    or not isinstance(
                        descriptor,
                        (
                            types.MemberDescriptorType,
                            types.GetSetDescriptorType,
                        ),
                    )
                ):
                    continue
                seen_descriptors.add(id(descriptor))
                try:
                    item = descriptor.__get__(value, value_type)
                except (AttributeError, TypeError):
                    state.append((name, descriptor, False, None))
                else:
                    state.append((name, descriptor, True, item))
        state.sort(key=lambda field: field[0] == "__suppress_context__")
        return state

    def rollback_descriptor_state_is_current(
        value: Any,
        descriptor: Any,
        existed: bool,
        expected: Any,
    ) -> bool:
        """Compare a raw descriptor field without user-defined equality."""

        try:
            current = descriptor.__get__(value, type(value))
        except (AttributeError, TypeError):
            return not existed
        if not existed:
            return False
        if current is expected:
            return True
        return (
            type(current) is type(expected)
            and type(current)
            in {
                bool,
                int,
                str,
                bytes,
            }
            and bool(current == expected)
        )

    def raw_super_state(value: super) -> tuple[Any, Any]:
        namespace = raw_class_namespace(super)
        value_type = type(value)
        return (
            namespace["__thisclass__"].__get__(value, value_type),
            namespace["__self__"].__get__(value, value_type),
        )

    def raw_generic_alias_state(
        value: types.GenericAlias,
    ) -> tuple[Any, tuple[Any, ...], bool]:
        namespace = raw_class_namespace(types.GenericAlias)
        value_type = type(value)
        return (
            namespace["__origin__"].__get__(value, value_type),
            namespace["__args__"].__get__(value, value_type),
            bool(namespace["__unpacked__"].__get__(value, value_type)),
        )

    def rebuild_generic_alias(
        template: types.GenericAlias,
        origin: Any,
        arguments: tuple[Any, ...],
        transform: Callable[[Any], Any] = lambda item: item,
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> types.GenericAlias:
        """Rebuild an alias without invoking subtype construction methods."""

        rebuilt = types.GenericAlias.__new__(type(template), origin, arguments)
        _old_origin, _old_arguments, unpacked = raw_generic_alias_state(template)
        if unpacked:
            return next(types.GenericAlias.__iter__(rebuilt))
        copy_raw_instance_attributes(template, rebuilt, transform, key_requires_rehash)
        for _slot_name, descriptor in declared_slot_descriptors(template):
            try:
                slot_value = descriptor.__get__(template, type(template))
            except (AttributeError, TypeError):
                continue
            try:
                descriptor.__set__(rebuilt, transform(slot_value))
            except (AttributeError, TypeError):
                pass
        return rebuilt

    def rebuild_super_wrapper(
        template: super,
        thisclass: type,
        receiver: Any,
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> super:
        """Rebuild a super wrapper without invoking subtype initialization."""

        rebuilt = super.__new__(type(template), thisclass, receiver)
        super.__init__(rebuilt, thisclass, receiver)
        copy_raw_instance_attributes(template, rebuilt, transform, key_requires_rehash)
        for _slot_name, descriptor in declared_slot_descriptors(template):
            try:
                slot_value = descriptor.__get__(template, type(template))
            except (AttributeError, TypeError):
                continue
            try:
                descriptor.__set__(rebuilt, transform(slot_value))
            except (AttributeError, TypeError):
                pass
        return rebuilt

    def raw_property_state(
        value: property,
    ) -> tuple[Any, Any, Any, Any]:
        namespace = raw_class_namespace(property)
        value_type = type(value)
        return (
            namespace["fget"].__get__(value, value_type),
            namespace["fset"].__get__(value, value_type),
            namespace["fdel"].__get__(value, value_type),
            namespace["__doc__"].__get__(value, value_type),
        )

    def raw_weakref_callback(value: weakref.ReferenceType[Any]) -> Any:
        return raw_class_namespace(weakref.ReferenceType)["__callback__"].__get__(
            value, type(value)
        )

    def raw_weakref_referent(value: weakref.ReferenceType[Any]) -> Any:
        """Dereference without invoking a subtype's overridden call method."""

        return weakref.ReferenceType.__call__(value)

    def raw_weakmethod_state(
        value: weakref.WeakMethod,
    ) -> tuple[Any, Any, type, bool]:
        """Read WeakMethod referents and slots without subtype hooks."""

        namespace = raw_class_namespace(weakref.WeakMethod)
        value_type = type(value)
        function_reference = namespace["_func_ref"].__get__(value, value_type)
        return (
            raw_weakref_referent(value),
            raw_weakref_referent(function_reference),
            namespace["_meth_type"].__get__(value, value_type),
            bool(namespace["_alive"].__get__(value, value_type)),
        )

    def raw_weakmethod_user_callback(value: weakref.WeakMethod) -> Any:
        internal_callback = raw_weakref_callback(value)
        if type(internal_callback) is not types.FunctionType:
            return None
        for name, cell in zip(
            internal_callback.__code__.co_freevars,
            internal_callback.__closure__ or (),
        ):
            if name != "callback":
                continue
            try:
                return cell.cell_contents
            except ValueError:
                return None
        return None

    def rebuild_weak_reference(
        template: weakref.ReferenceType[Any],
        referent: Any,
        callback: Any,
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> weakref.ReferenceType[Any]:
        rebuilt = weakref.ReferenceType.__new__(type(template), referent, callback)
        copy_raw_instance_attributes(template, rebuilt, transform, key_requires_rehash)
        for _slot_name, descriptor in declared_slot_descriptors(template):
            try:
                slot_value = descriptor.__get__(template, type(template))
            except (AttributeError, TypeError):
                continue
            try:
                descriptor.__set__(rebuilt, transform(slot_value))
            except (AttributeError, TypeError):
                pass
        return rebuilt

    def rebuild_weak_method(
        template: weakref.WeakMethod,
        receiver: Any,
        function: Any,
        callback: Any,
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> weakref.WeakMethod:
        namespace = raw_class_namespace(weakref.WeakMethod)
        function_descriptor = namespace["_func_ref"]
        method_type_descriptor = namespace["_meth_type"]
        alive_descriptor = namespace["_alive"]
        _old_receiver, _old_function, method_type, alive = raw_weakmethod_state(
            template
        )
        self_reference: Optional[weakref.ReferenceType[Any]] = None

        def internal_callback(_reference: weakref.ReferenceType[Any]) -> None:
            if self_reference is None:
                return
            rebuilt_self = raw_weakref_referent(self_reference)
            if rebuilt_self is None:
                return
            if bool(alive_descriptor.__get__(rebuilt_self, type(rebuilt_self))):
                alive_descriptor.__set__(rebuilt_self, False)
                if callback is not None:
                    callback(rebuilt_self)

        rebuilt = weakref.ReferenceType.__new__(
            type(template), receiver, internal_callback
        )
        function_reference = weakref.ref(function, internal_callback)
        function_descriptor.__set__(rebuilt, function_reference)
        method_type_descriptor.__set__(rebuilt, method_type)
        alive_descriptor.__set__(rebuilt, alive)
        self_reference = weakref.ref(rebuilt)
        copy_raw_instance_attributes(template, rebuilt, transform, key_requires_rehash)
        for _slot_name, descriptor in declared_slot_descriptors(template):
            if getattr(descriptor, "__objclass__", None) is weakref.WeakMethod:
                continue
            try:
                slot_value = descriptor.__get__(template, type(template))
            except (AttributeError, TypeError):
                continue
            try:
                descriptor.__set__(rebuilt, transform(slot_value))
            except (AttributeError, TypeError):
                pass
        return rebuilt

    def raw_descriptor_function(value: Any) -> Any:
        descriptor_type = (
            staticmethod if raw_inherits(value, staticmethod) else classmethod
        )
        return raw_class_namespace(descriptor_type)["__func__"].__get__(
            value, type(value)
        )

    def raw_partial_state(
        value: functools.partial[Any],
    ) -> tuple[Any, tuple[Any, ...], Dict[str, Any]]:
        namespace = raw_class_namespace(functools.partial)
        value_type = type(value)
        return (
            namespace["func"].__get__(value, value_type),
            namespace["args"].__get__(value, value_type),
            dict(namespace["keywords"].__get__(value, value_type) or {}),
        )

    def raw_defaultdict_factory(value: collections.defaultdict) -> Any:
        return raw_class_namespace(collections.defaultdict)["default_factory"].__get__(
            value, type(value)
        )

    def rebuild_iterator_wrapper(
        template: Any,
        transform: Callable[[Any], Any],
    ) -> Any:
        """Rebuild an exact built-in iterator from its base reduction state."""

        template_type = type(template)
        if template_type in rollback_iterator_types[4:]:
            reduction_descriptor = raw_class_namespace(template_type)["__reduce__"]
            _constructor, arguments, *_state_items = reduction_descriptor(template)
            template_referents = gc.get_referents(template)
            hidden_item_result = (
                next(
                    (
                        referent
                        for referent in template_referents
                        if type(referent) is tuple and len(referent) == 2
                    ),
                    None,
                )
                if template_type is rollback_iterator_types[6]
                else None
            )
            source = next(
                (
                    referent
                    for referent in template_referents
                    if raw_inherits(referent, dict)
                    or raw_inherits(referent, set)
                    or raw_inherits(referent, frozenset)
                ),
                None,
            )
            rewritten_source = transform(source) if source is not None else None
            rewritten_arguments = transform(arguments)
            remaining_values = rewritten_arguments[0]
            rewritten_hidden_item_result = (
                transform(hidden_item_result)
                if hidden_item_result is not None
                else None
            )
            if template_type in rollback_iterator_types[4:7]:
                if rewritten_source is None:
                    if remaining_values:
                        raise TypeError("exhausted dictionary iterator state invalid")
                    empty_source: dict[Any, Any] = {}
                    if template_type is rollback_iterator_types[4]:
                        rebuilt = dict.__iter__(empty_source)
                    elif template_type is rollback_iterator_types[5]:
                        rebuilt = iter(dict.values(empty_source))
                    else:
                        rebuilt = iter(dict.items(empty_source))
                    try:
                        next(rebuilt)
                    except StopIteration:
                        pass
                    if rewritten_hidden_item_result is not None and not (
                        _rollback_set_dict_item_iterator_result(
                            rebuilt, rewritten_hidden_item_result
                        )
                    ):
                        raise TypeError("dictionary item result restoration unavailable")
                    return rebuilt
                source_entries = (
                    _rollback_dict_entries_with_hashes(rewritten_source)
                    if raw_inherits(rewritten_source, dict)
                    else []
                )
                entries_by_identity = {
                    id(key): (key, item, key_hash)
                    for key, item, key_hash in source_entries or ()
                }

                def canonical_dictionary_entry(key: Any) -> tuple[Any, Any, int]:
                    direct = entries_by_identity.get(id(key))
                    if direct is not None:
                        return direct
                    for candidate in source_entries or ():
                        if candidate[0] == key:
                            return candidate
                    raise TypeError("canonical dictionary iterator key unavailable")

                if template_type is rollback_iterator_types[4]:
                    expected_remaining = []
                    seen_key_ids: Set[int] = set()
                    for key in remaining_values:
                        canonical = canonical_dictionary_entry(key)
                        if id(canonical[0]) in seen_key_ids:
                            continue
                        seen_key_ids.add(id(canonical[0]))
                        expected_remaining.append(canonical[0])
                elif template_type is rollback_iterator_types[5]:
                    expected_remaining = list(remaining_values)
                else:
                    expected_remaining = []
                    seen_key_ids = set()
                    for key, _item in remaining_values:
                        canonical = canonical_dictionary_entry(key)
                        if id(canonical[0]) in seen_key_ids:
                            continue
                        seen_key_ids.add(id(canonical[0]))
                        expected_remaining.append((canonical[0], canonical[1]))
                rebuilt = _rollback_rebuild_dict_iterator(
                    rewritten_source,
                    template_type,
                    expected_remaining,
                    rewritten_hidden_item_result,
                )
                if rebuilt is None:
                    raise TypeError("coupled dictionary iterator unavailable")
                return rebuilt
            source_entries = (
                _rollback_set_entries_with_hashes(rewritten_source)
                if raw_inherits(rewritten_source, set)
                or raw_inherits(rewritten_source, frozenset)
                else []
            )
            entries_by_identity = {
                id(item): (item, item_hash) for item, item_hash in source_entries or ()
            }
            remaining_entries = []
            seen_item_ids: Set[int] = set()
            for item in remaining_values:
                canonical = entries_by_identity.get(id(item))
                if canonical is None:
                    canonical = next(
                        (
                            candidate
                            for candidate in source_entries or ()
                            if candidate[0] == item
                        ),
                        None,
                    )
                if canonical is None:
                    raise TypeError("canonical set iterator member unavailable")
                if id(canonical[0]) in seen_item_ids:
                    continue
                seen_item_ids.add(id(canonical[0]))
                remaining_entries.append(canonical)
            if raw_inherits(rewritten_source, frozenset):
                rebuilt = frozenset.__iter__(rewritten_source)
            elif raw_inherits(rewritten_source, set):
                rebuilt = set.__iter__(rewritten_source)
            else:
                raise TypeError("coupled set iterator source unavailable")
            if not _rollback_rebind_set_iterator(
                rebuilt, rewritten_source, remaining_entries
            ):
                raise TypeError("coupled set iterator position unavailable")
            return rebuilt
        reduction_descriptor = raw_class_namespace(template_type)["__reduce__"]
        reduction = reduction_descriptor(template)
        constructor, arguments, *state_items = reduction
        rewritten_arguments = transform(arguments)
        rebuilt = constructor(*rewritten_arguments)
        if state_items:
            state = transform(state_items[0])
            state_descriptor = raw_class_namespace(type(rebuilt)).get("__setstate__")
            if state_descriptor is None:
                raise TypeError("iterator state restoration unavailable")
            state_descriptor(rebuilt, state)
        return rebuilt

    def rebuild_exact_exception_group(
        template: BaseException,
        exceptions: tuple[BaseException, ...],
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> BaseException:
        """Rebuild a built-in exception group without dynamic methods."""

        message_descriptor = raw_class_namespace(_BASE_EXCEPTION_GROUP_TYPE)["message"]
        message = message_descriptor.__get__(template, type(template))
        original_args = BaseException.args.__get__(template, type(template))
        original_exception_sequence = original_args[1] if len(original_args) > 1 else ()
        exception_sequence = (
            tuple(exceptions)
            if type(original_exception_sequence) is tuple
            else list(exceptions)
        )
        rebuilt = _BASE_EXCEPTION_GROUP_TYPE.__new__(
            type(template), message, exception_sequence
        )
        _BASE_EXCEPTION_GROUP_TYPE.__init__(rebuilt, message, exception_sequence)
        rewritten_args = tuple(transform(item) for item in original_args)
        BaseException.args.__set__(rebuilt, rewritten_args)
        for (
            name,
            descriptor,
            existed,
            item,
        ) in rollback_builtin_exception_descriptor_state(template):
            if not existed or name in {"args", "message", "exceptions"}:
                continue
            rewritten_item = item if name == "__traceback__" else transform(item)
            try:
                descriptor.__set__(rebuilt, rewritten_item)
            except (AttributeError, TypeError):
                pass
        copy_raw_instance_attributes(template, rebuilt, transform, key_requires_rehash)
        for _slot_name, descriptor in declared_slot_descriptors(template):
            try:
                slot_value = descriptor.__get__(template, type(template))
            except (AttributeError, TypeError):
                continue
            try:
                descriptor.__set__(rebuilt, transform(slot_value))
            except (AttributeError, TypeError):
                pass
        return rebuilt

    def is_runtime_leaf(value: Any) -> bool:
        return any(id(owner) in runtime_leaf_type_ids for owner in raw_value_mro(value))

    def is_rollback_leaf(value: Any) -> bool:
        """Stop every rollback graph walk at external runtime authority."""

        shared_value = shared_identity_memo.get(id(value))
        return shared_value is value or is_runtime_leaf(value)

    heap_runtime_identity_memo: Optional[Dict[int, Any]] = None

    def heap_runtime_authorities() -> Dict[int, Any]:
        """Find opaque runtime leaves without traversing their owner graphs.

        A copy hook may compute a key and then use ``globals()[key()]`` to
        reach an event loop nested in an otherwise ordinary container.  Its
        bytecode does not reveal that container name.  Recursively walking
        every global would revisit service graphs and the Mathlib index, so
        scan the GC registry once and retain only exact runtime leaves.
        """

        nonlocal heap_runtime_identity_memo
        if heap_runtime_identity_memo is None:
            heap_runtime_identity_memo = dict(shared_identity_memo)
            for candidate in gc.get_objects():
                try:
                    if is_rollback_leaf(candidate):
                        heap_runtime_identity_memo[id(candidate)] = candidate
                except (ReferenceError, TypeError):
                    continue
        return heap_runtime_identity_memo

    def raw_slot_storage_name(owner: type, slot: Any) -> str:
        slot_name = str(slot or "")
        if slot_name.startswith("__") and not slot_name.endswith("__"):
            class_name = raw_class_name(owner).lstrip("_")
            if class_name:
                return f"_{class_name}{slot_name}"
        return slot_name

    def declared_slot_storage_names(owner: type, slot: Any) -> tuple[str, ...]:
        """Resolve storage names fixed when slots were originally declared."""

        slot_name = str(slot or "")
        if not (slot_name.startswith("__") and not slot_name.endswith("__")):
            return (slot_name,)
        owner_namespace = raw_class_namespace(owner)
        candidates = tuple(
            name
            for name in owner_namespace
            if isinstance(name, str)
            and (name == slot_name or name.startswith("_"))
            and name.endswith(slot_name)
        )
        genuine_candidates = tuple(
            name
            for name in candidates
            if isinstance(owner_namespace.get(name), types.MemberDescriptorType)
            and owner_namespace[name].__objclass__ is owner
        )
        if genuine_candidates:
            return genuine_candidates
        if candidates:
            return candidates
        return (raw_slot_storage_name(owner, slot),)

    def declared_slot_descriptors(value: Any) -> Iterable[tuple[str, Any]]:
        """Yield raw declaring-class slots without dynamic attribute access."""

        for owner in raw_value_mro(value):
            owner_namespace = raw_class_namespace(owner)
            raw_slots = owner_namespace.get("__slots__", ())
            if isinstance(raw_slots, str):
                slots = (raw_slots,)
            elif isinstance(raw_slots, Mapping):
                slots = tuple(raw_slots)
            else:
                try:
                    slots = tuple(raw_slots or ())
                except TypeError:
                    slots = ()
            for slot in slots:
                for slot_name in declared_slot_storage_names(owner, slot):
                    if slot_name in {"", "__dict__", "__weakref__"}:
                        continue
                    descriptor = owner_namespace.get(slot_name)
                    if isinstance(descriptor, types.MemberDescriptorType):
                        yield slot_name, descriptor

    def raw_instance_dict(value: Any) -> tuple[Any, Optional[dict]]:
        """Read instance state without invoking overridden __getattribute__."""

        for owner in raw_value_mro(value):
            descriptor = raw_class_namespace(owner).get("__dict__")
            if descriptor is None or not inspect.isgetsetdescriptor(descriptor):
                continue
            try:
                state = descriptor.__get__(value, type(value))
            except (AttributeError, TypeError):
                return descriptor, None
            return descriptor, state if isinstance(state, dict) else None
        return None, None

    def copy_raw_instance_attributes(
        source: Any,
        destination: Any,
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
    ) -> None:
        """Copy wrapper attributes without dynamic instance lookup."""

        _source_descriptor, source_attributes = raw_instance_dict(source)
        _destination_descriptor, destination_attributes = raw_instance_dict(destination)
        if source_attributes is None or destination_attributes is None:
            return
        copied_attributes = dict.copy(source_attributes)
        rewrite_dictionary_edges(
            copied_attributes,
            transform,
            key_requires_rehash,
        )
        replacement = dict.copy(copied_attributes)
        if _rollback_transplant_dict_table(destination_attributes, replacement):
            return
        destination_attributes.clear()
        destination_attributes.update(copied_attributes)

    def rollback_graph_referents(value: Any) -> List[Any]:
        """Return callback-free edges for rollback-owned Python state."""

        referents: List[Any] = []
        value_type = type(value)
        if raw_inherits(value, weakref.ReferenceType) and not raw_inherits(
            value, weakref.WeakMethod
        ):
            referent = raw_weakref_referent(value)
            if referent is not None:
                referents.append(referent)
            callback = raw_weakref_callback(value)
            if callback is not None:
                referents.append(callback)
        elif raw_inherits(value, weakref.WeakMethod):
            receiver, function, _method_type, _alive = raw_weakmethod_state(value)
            referents.extend(item for item in (receiver, function) if item is not None)
            callback = raw_weakref_callback(value)
            if callback is not None:
                referents.append(callback)
        elif (
            value_type in rollback_iterator_types
            or value_type in rollback_gc_wrapper_types
            or value_type in rollback_operator_wrapper_types
        ):
            referents.extend(gc.get_referents(value))
        if value_type is types.BuiltinFunctionType:
            receiver = getattr(value, "__self__", None)
            if receiver is not None and not raw_inherits(receiver, types.ModuleType):
                referents.append(receiver)
        if raw_inherits(value, property):
            fget, fset, fdel, doc = raw_property_state(value)
            referents.extend(
                item for item in (fget, fset, fdel, doc) if item is not None
            )
        elif raw_inherits(value, staticmethod) or raw_inherits(value, classmethod):
            referents.append(raw_descriptor_function(value))
        elif value_type is slice:
            referents.extend((value.start, value.stop, value.step))
        elif raw_inherits(value, super):
            referents.extend(raw_super_state(value))
        elif raw_inherits(value, types.GenericAlias):
            alias_origin, alias_args, _unpacked = raw_generic_alias_state(value)
            referents.extend((alias_origin, *alias_args))
        if raw_inherits(value, BaseException):
            referents.extend(
                item
                for name, _descriptor, existed, item in (
                    rollback_builtin_exception_descriptor_state(value)
                )
                if existed and name != "__traceback__" and item is not None
            )
        if raw_inherits(value, functools.partial):
            partial_func, partial_args, partial_keywords = raw_partial_state(value)
            referents.append(partial_func)
            referents.extend(partial_args)
            referents.extend(partial_keywords.values())
        if raw_inherits(value, collections.deque):
            referents.extend(collections.deque.__iter__(value))
        if raw_inherits(value, collections.defaultdict):
            referents.append(raw_defaultdict_factory(value))
        if value_type is types.MethodType:
            referents.extend((value.__self__, value.__func__))
        if value_type is types.FunctionType:
            referents.extend(value.__defaults__ or ())
            referents.extend(dict(value.__kwdefaults__ or {}).values())
            referents.extend(dict(value.__annotations__).values())
            referents.extend(value.__closure__ or ())
            function_names = set(value.__code__.co_names)
            if function_names.intersection({"globals", "vars"}):
                referents.extend(rollback_function_global_referents(value))
            else:
                referents.extend(
                    global_value
                    for name in function_names
                    if type(global_value := value.__globals__.get(name))
                    is types.FunctionType
                    and set(global_value.__code__.co_names).intersection(
                        {"globals", "vars"}
                    )
                )
        if value_type is types.CellType:
            try:
                referents.append(value.cell_contents)
            except ValueError:
                pass
        if value_type is memoryview:
            try:
                referents.append(value.obj)
            except ValueError:
                pass
        if raw_inherits(value, dict):
            referents.extend(dict.keys(value))
            referents.extend(dict.values(value))
        if raw_inherits(value, list):
            referents.extend(list.__iter__(value))
        elif raw_inherits(value, tuple):
            referents.extend(tuple.__iter__(value))
        elif raw_inherits(value, set):
            referents.extend(set.__iter__(value))
        elif raw_inherits(value, frozenset):
            referents.extend(frozenset.__iter__(value))
        _dict_descriptor, attributes = raw_instance_dict(value)
        if attributes is not None:
            referents.extend(
                key for key in dict.keys(attributes) if type(key) is not str
            )
            referents.extend(dict.values(attributes))
        if attributes is None and any(
            "__dict__" in raw_class_namespace(owner)
            and not inspect.isgetsetdescriptor(raw_class_namespace(owner)["__dict__"])
            for owner in raw_value_mro(value)
        ):
            referents.extend(
                referent
                for referent in gc.get_referents(value)
                if not raw_inherits(referent, type)
            )
        if raw_inherits(value, type) and id(value) not in _BUILTIN_TYPE_IDENTITY_IDS:
            referents.extend(raw_class_namespace(value).values())
        for _slot_name, descriptor in declared_slot_descriptors(value):
            try:
                referents.append(descriptor.__get__(value, value_type))
            except (AttributeError, TypeError):
                continue
        return referents

    def rollback_function_global_referents(value: Any) -> List[Any]:
        """Return bounded named globals for a directly returned function."""

        if type(value) is not types.FunctionType:
            return []
        referents: List[Any] = []
        function_names = set(value.__code__.co_names)

        def include(candidate: Any) -> bool:
            return not any(
                raw_inherits(candidate, excluded_type)
                for excluded_type in (
                    types.ModuleType,
                    type,
                    types.CodeType,
                    types.FunctionType,
                    types.MethodType,
                    types.BuiltinFunctionType,
                )
            )

        for name in function_names:
            global_value = value.__globals__.get(name)
            if global_value is None:
                continue
            if raw_inherits(global_value, types.ModuleType):
                module_namespace = vars(global_value)
                referents.extend(
                    module_namespace[attribute_name]
                    for attribute_name in function_names
                    if attribute_name in module_namespace
                    and include(module_namespace[attribute_name])
                )
            elif include(global_value):
                referents.append(global_value)
        if function_names.intersection({"globals", "vars"}):
            referents.extend(
                global_value
                for constant in value.__code__.co_consts
                if type(constant) is str
                and (
                    global_value := value.__globals__.get(
                        constant, _ROLLBACK_DEEPCOPY_MISSING
                    )
                )
                is not _ROLLBACK_DEEPCOPY_MISSING
                and include(global_value)
            )
        return referents

    def rebind_builtin_callable(value: Any, receiver: Any) -> Any:
        """Rebind an exact built-in callable without dynamic lookup."""

        name = getattr(value, "__name__", None)
        if not isinstance(name, str):
            return _ROLLBACK_DEEPCOPY_MISSING
        for owner in raw_value_mro(receiver):
            descriptor = raw_class_namespace(owner).get(name)
            if isinstance(
                descriptor,
                (
                    types.MethodDescriptorType,
                    types.WrapperDescriptorType,
                    types.ClassMethodDescriptorType,
                ),
            ):
                try:
                    return descriptor.__get__(receiver, type(receiver))
                except (AttributeError, TypeError):
                    return _ROLLBACK_DEEPCOPY_MISSING
        return _ROLLBACK_DEEPCOPY_MISSING

    def runtime_memo(root: Any, *, receiver: Any = None) -> Dict[int, Any]:
        # ``deepcopy`` can reconstruct *any* nested event loop with ``__new__``
        # and then fail before BaseEventLoop.__init__ sets ``_closed``. Its
        # destructor consequently emits noisy unraisable exceptions. Looking
        # up only get_running_loop() misses inactive/alternate loops retained
        # by action state, so walk the state graph and memoize every runtime
        # leaf before deepcopy starts. Ordinary mutable peers remain copyable.
        memo: Dict[int, Any] = {}
        seen: Set[int] = set()
        referenced_attribute_names: Set[str] = set()
        dynamic_attribute_access = False
        root_receiver_id = (
            id(receiver)
            if receiver is not None
            else id(root.__self__)
            if type(root) is types.MethodType
            else None
        )
        stack = [root]

        def push_raw_binding(raw_binding: Any) -> None:
            stack.append(raw_binding)
            if raw_inherits(raw_binding, property):
                fget, fset, fdel, _doc = raw_property_state(raw_binding)
                stack.extend(
                    callback for callback in (fget, fset, fdel) if callback is not None
                )
            elif raw_inherits(raw_binding, staticmethod) or raw_inherits(
                raw_binding, classmethod
            ):
                stack.append(raw_descriptor_function(raw_binding))
            for binding_owner in raw_value_mro(raw_binding):
                raw_get = raw_class_namespace(binding_owner).get("__get__")
                if raw_get is not None:
                    stack.append(raw_get)
                    break

        while stack:
            value = stack.pop()
            value_id = id(value)
            if value_id in seen:
                continue
            seen.add(value_id)
            if is_rollback_leaf(value):
                memo[value_id] = value
                continue
            if type(value) in {weakref.ProxyType, weakref.CallableProxyType}:
                # Proxy referents are intentionally opaque: Python exposes no
                # callback-free way to inspect them, and deepcopy(proxy)
                # silently converts the proxy into a strong copied referent.
                # Preserve the weak external handle itself so an indirectly
                # held event loop can never be reconstructed.
                memo[value_id] = value
                continue
            if (
                type(value) is weakref.ReferenceType
                or type(value) is weakref.WeakMethod
            ):
                if type(value) is weakref.WeakMethod:
                    receiver, function, _method_type, _alive = raw_weakmethod_state(
                        value
                    )
                    if receiver is not None:
                        stack.append(receiver)
                    if function is not None:
                        stack.append(function)
                else:
                    referent = raw_weakref_referent(value)
                    if referent is not None:
                        stack.append(referent)
            if raw_inherits(value, functools.partial):
                partial_func, partial_args, partial_keywords = raw_partial_state(value)
                stack.extend(partial_keywords.values())
                stack.extend(partial_args)
                stack.append(partial_func)
            if raw_inherits(value, collections.deque):
                stack.extend(collections.deque.__iter__(value))
            if raw_inherits(value, collections.defaultdict):
                stack.append(raw_defaultdict_factory(value))
            if type(value) is types.MethodType:
                stack.append(value.__self__)
                stack.append(value.__func__)
            if type(value) is memoryview:
                try:
                    stack.append(value.obj)
                except ValueError:
                    pass
            if type(value) is types.FunctionType:
                # Pytest assertion rewriting adds the exact compiler-only
                # globals below. Walking them pulls the test runner's process
                # graph into every rollback preflight. Dynamically constructed
                # bytecode can address other names that ordinary source cannot,
                # so retain every other global plus all closures, defaults,
                # annotations, receivers, and heap fallbacks.
                function_names = {
                    name
                    for name in value.__code__.co_names
                    if name not in {"@pytest_ar", "@py_builtins"}
                }
                stack.extend(value.__defaults__ or ())
                stack.extend(dict(value.__kwdefaults__ or {}).values())
                stack.extend(dict(value.__annotations__).values())
                for cell in value.__closure__ or ():
                    try:
                        stack.append(cell.cell_contents)
                    except ValueError:
                        continue
                module_name = str(value.__module__ or "")
                module_root = module_name.partition(".")[0]
                owner_module = sys.modules.get(module_name)
                is_stdlib_function = bool(
                    module_root in sys.stdlib_module_names
                    and owner_module is not None
                    and value.__globals__ is vars(owner_module)
                )
                if not is_stdlib_function:
                    referenced_attribute_names.update(function_names)
                    if function_names.intersection(
                        {"getattr", "__getattribute__", "attrgetter"}
                    ):
                        dynamic_attribute_access = True
                    if function_names.intersection({"globals", "vars"}):
                        memo.update(heap_runtime_authorities())
                        for global_value in value.__globals__.values():
                            if is_rollback_leaf(global_value):
                                stack.append(global_value)
                        for constant in value.__code__.co_consts:
                            if isinstance(constant, str):
                                global_value = value.__globals__.get(constant)
                                if global_value is not None:
                                    stack.append(global_value)
                    for name in function_names:
                        referenced_global = value.__globals__.get(name)
                        if referenced_global is None:
                            continue
                        if raw_inherits(
                            referenced_global, types.ModuleType
                        ) or raw_inherits(referenced_global, type):
                            namespace = vars(referenced_global)
                            for attribute_name in function_names:
                                referenced_attribute = namespace.get(attribute_name)
                                if (
                                    referenced_attribute is not None
                                    and not raw_inherits(
                                        referenced_attribute, types.ModuleType
                                    )
                                    and not raw_inherits(referenced_attribute, type)
                                ):
                                    stack.append(referenced_attribute)
                            continue
                        stack.append(referenced_global)
            if raw_inherits(value, types.ModuleType) or raw_inherits(value, type):
                namespace = vars(value)
                for attribute_name in tuple(referenced_attribute_names):
                    referenced_attribute = namespace.get(attribute_name)
                    if (
                        referenced_attribute is not None
                        and not raw_inherits(referenced_attribute, types.ModuleType)
                        and not raw_inherits(referenced_attribute, type)
                    ):
                        stack.append(referenced_attribute)
                # A module/class namespace is not owned rollback state. The
                # referenced bindings above are the only callback-reachable
                # entries; falling through to its raw ``__dict__`` would walk
                # the whole stdlib and pytest module graph on every hook.
                continue
            if raw_inherits(value, dict):
                stack.extend(dict.keys(value))
                stack.extend(dict.values(value))
            if raw_inherits(value, list):
                stack.extend(list.__iter__(value))
            elif raw_inherits(value, tuple):
                stack.extend(tuple.__iter__(value))
            elif raw_inherits(value, set):
                stack.extend(set.__iter__(value))
            elif raw_inherits(value, frozenset):
                stack.extend(frozenset.__iter__(value))
            _dict_descriptor, attributes = raw_instance_dict(value)
            stack.extend(dict(attributes or {}).values())
            if attributes is None and any(
                "__dict__" in raw_class_namespace(owner)
                and not inspect.isgetsetdescriptor(
                    raw_class_namespace(owner)["__dict__"]
                )
                for owner in raw_value_mro(value)
            ):
                # A class may shadow its real instance dictionary with a
                # property or another descriptor. CPython's GC referents are
                # callback-free and still expose values in that hidden
                # storage, so runtime capabilities remain shareable without
                # abandoning isolation for the surrounding object.
                stack.extend(
                    referent
                    for referent in gc.get_referents(value)
                    if not isinstance(referent, type)
                )
            # Slotted state has no ``__dict__`` for ``vars`` to expose.  A
            # runtime loop hidden there must still be memoized before
            # ``deepcopy`` calls its reducer; otherwise deepcopy can allocate
            # a half-initialized BaseEventLoop whose destructor raises because
            # ``_closed`` was never installed.
            for _slot_name, descriptor in declared_slot_descriptors(value):
                try:
                    stack.append(descriptor.__get__(value, type(value)))
                except (AttributeError, TypeError):
                    continue
            # A copy hook can reach a runtime capability through a custom
            # descriptor (``self.loop``). Invoking that descriptor during
            # preflight would change callback counts and can have arbitrary
            # side effects, so traverse the raw binding and its getter graph
            # instead. Function names are processed before the bound receiver
            # (LIFO above), making the relevant attribute set available here.
            for owner in raw_value_mro(value):
                owner_namespace = raw_class_namespace(owner)
                for attribute_name in tuple(referenced_attribute_names):
                    if attribute_name not in owner_namespace:
                        continue
                    push_raw_binding(owner_namespace[attribute_name])
                if value_id == root_receiver_id:
                    binding_names = (
                        tuple(owner_namespace)
                        if dynamic_attribute_access
                        else ("__getattr__", "__getattribute__")
                    )
                    for binding_name in binding_names:
                        raw_binding = owner_namespace.get(binding_name)
                        if raw_binding is not None:
                            push_raw_binding(raw_binding)
        return memo

    completed_memo: Dict[int, Any] = {}
    completed_value_refcounts: Dict[int, int] = {}
    nested_completion_evidence: Dict[
        int,
        tuple[
            _RollbackDeepcopyMemo,
            List[
                tuple[
                    types.FrameType,
                    types.FrameType,
                    tuple[tuple[types.FrameType, types.FrameType], ...],
                ]
            ],
        ],
    ] = {}
    nested_completion_mutations: Dict[
        int,
        tuple[
            _RollbackDeepcopyMemo,
            List[tuple[types.FrameType, types.FrameType]],
        ],
    ] = {}
    completion_snapshot_records: Dict[
        int,
        tuple[_RollbackDeepcopyMemo, Dict[int, Any]],
    ] = {}
    active_memo: Dict[int, Any] = {}
    active_value_refcounts: Dict[int, int] = {}
    reduction_cache: Dict[int, Any] = {}
    original_by_id: Dict[int, Any] = {}
    snapshot_stop_stack: List[Mapping[int, Any]] = []
    snapshot_outer_restore_stack: List[Mapping[int, tuple[Any, ...]]] = []
    restored_snapshot_replacements: Dict[int, tuple[Any, Any]] = {}
    unrestorable_snapshot_objects: Dict[int, Any] = {}
    authoritative_fallback_memo: Dict[int, Any] = {}

    class UnrestorableActiveRollbackError(Exception):
        """Propagate contamination until its active owner can fall back."""

    def set_completed(original_id: int, value: Any) -> None:
        if original_id in completed_memo:
            prior = completed_memo[original_id]
            prior_id = id(prior)
            remaining = completed_value_refcounts.get(prior_id, 1) - 1
            if remaining > 0:
                completed_value_refcounts[prior_id] = remaining
            else:
                completed_value_refcounts.pop(prior_id, None)
        completed_memo[original_id] = value
        value_id = id(value)
        completed_value_refcounts[value_id] = (
            completed_value_refcounts.get(value_id, 0) + 1
        )

    def frame_returned_normally(frame: types.FrameType) -> bool:
        offset = frame.f_lasti
        code = frame.f_code.co_code
        return bool(0 <= offset < len(code) and code[offset] in _RETURN_OPCODES)

    mutation_journal_cache: Dict[
        int,
        tuple[
            _RollbackDeepcopyMemo,
            List[tuple[types.FrameType, types.FrameType]],
            tuple[int, ...],
            tuple[int, ...],
            tuple[int, ...],
            Dict[int, tuple[int, ...]],
        ],
    ] = {}

    def validated_mutation_journal(
        memo: _RollbackDeepcopyMemo,
    ) -> Optional[
        tuple[
            tuple[int, ...],
            tuple[int, ...],
            tuple[int, ...],
            Dict[int, tuple[int, ...]],
        ]
    ]:
        journal_entry = nested_completion_mutations.get(id(memo))
        if (
            not isinstance(journal_entry, tuple)
            or len(journal_entry) != 2
            or journal_entry[0] is not memo
            or not isinstance(journal_entry[1], list)
        ):
            return None
        records = journal_entry[1]
        cached = mutation_journal_cache.get(id(memo))
        if (
            cached is not None
            and cached[0] is memo
            and cached[1] is records
            and len(cached[2]) == len(records)
        ):
            return cached[2], cached[3], cached[4], cached[5]
        versions_before: List[int] = []
        versions_after: List[int] = []
        chain_break_prefix = [0]
        positions_by_key: Dict[int, List[int]] = {}
        for index, record in enumerate(tuple(records)):
            if (
                not isinstance(record, tuple)
                or len(record) != 2
                or not isinstance(record[0], types.FrameType)
                or not isinstance(record[1], types.FrameType)
            ):
                return None
            event_frame, recorder_frame = record
            if (
                event_frame.f_code not in _ROLLBACK_DEEPCOPY_MEMO_MUTATION_CODES
                or not frame_returned_normally(event_frame)
                or recorder_frame.f_code
                is not _RollbackDeepcopyMemo._record_local_memo_mutation.__code__
                or not frame_returned_normally(recorder_frame)
            ):
                return None
            event_locals = event_frame.f_locals
            recorder_locals = recorder_frame.f_locals
            version_before = event_locals.get("dict_version_before")
            version_after = event_locals.get("dict_version_after")
            if (
                event_locals.get("self") is not memo
                or recorder_locals.get("caller") is not event_frame
                or recorder_locals.get("self") is not memo
                or recorder_locals.get("dict_version_before") is not version_before
                or recorder_locals.get("dict_version_after") is not version_after
                or recorder_locals.get("instrumentation_active") is not False
                or type(version_before) is not int
                or type(version_after) is not int
                or version_before == version_after
            ):
                return None
            if versions_after:
                chain_break_prefix.append(
                    chain_break_prefix[-1] + int(version_before != versions_after[-1])
                )
            else:
                chain_break_prefix.append(0)
            versions_before.append(version_before)
            versions_after.append(version_after)
            key = event_locals.get("key", _ROLLBACK_DEEPCOPY_MISSING)
            if type(key) is int:
                positions_by_key.setdefault(key, []).append(index)
        frozen_positions = {
            key: tuple(positions) for key, positions in positions_by_key.items()
        }
        parsed = (
            tuple(versions_before),
            tuple(versions_after),
            tuple(chain_break_prefix),
            frozen_positions,
        )
        mutation_journal_cache[id(memo)] = (
            memo,
            records,
            parsed[0],
            parsed[1],
            parsed[2],
            parsed[3],
        )
        return parsed

    def validate_mutation_segment(
        memo: _RollbackDeepcopyMemo,
        start: int,
        stop: int,
        expected_version: int,
        original_id: int,
    ) -> Optional[tuple[bool, int]]:
        parsed = validated_mutation_journal(memo)
        if parsed is None:
            return None
        versions_before, versions_after, break_prefix, positions_by_key = parsed
        if (
            type(start) is not int
            or type(stop) is not int
            or not 0 <= start <= stop <= len(versions_before)
        ):
            return None
        if start == stop:
            return True, expected_version
        positions = positions_by_key.get(original_id, ())
        first_position = bisect.bisect_left(positions, start)
        if first_position < len(positions) and positions[first_position] < stop:
            return False, expected_version
        if versions_before[start] != expected_version:
            return False, expected_version
        if break_prefix[stop] != break_prefix[start + 1]:
            return False, expected_version
        return True, versions_after[stop - 1]

    snapshot_record_validation_cache: Dict[int, bool] = {}
    snapshot_dependency_match_cache: Dict[tuple[int, int], bool] = {}

    def snapshot_record_is_current(
        record: Any,
        active_records: Optional[Set[int]] = None,
    ) -> bool:
        if not isinstance(record, tuple) or len(record) != 3:
            return False
        cached = snapshot_record_validation_cache.get(id(record))
        if cached is not None:
            return cached
        completion_frame, recorder_frame, _transfers = record
        if (
            not isinstance(completion_frame, types.FrameType)
            or completion_frame.f_code is not _STDLIB_DEEPCOPY_CODE
            or not frame_returned_normally(completion_frame)
            or not isinstance(recorder_frame, types.FrameType)
            or recorder_frame.f_code
            is not _RollbackDeepcopyMemo._record_keepalive_completion.__code__
            or not frame_returned_normally(recorder_frame)
        ):
            return False
        copied_value = completion_frame.f_locals.get("y", _ROLLBACK_DEEPCOPY_MISSING)
        recorder_locals = recorder_frame.f_locals
        snapshot_bundle = recorder_locals.get("completion_snapshot")
        if (
            copied_value is _ROLLBACK_DEEPCOPY_MISSING
            or recorder_locals.get("copied_value") is not copied_value
            or recorder_locals.get("instrumentation_active") is not False
            or not isinstance(snapshot_bundle, tuple)
            or len(snapshot_bundle) != 2
            or not isinstance(snapshot_bundle[0], tuple)
            or not isinstance(snapshot_bundle[1], tuple)
        ):
            return False
        record_id = id(record)
        active = set() if active_records is None else active_records
        if record_id in active:
            return False
        active.add(record_id)
        snapshot, dependencies = snapshot_bundle
        current = (
            _rollback_snapshot_function_is_authentic(completion_snapshot_is_current)
            and completion_snapshot_is_current(
                copied_value,
                snapshot,
                dependencies,
            )
        ) and all(
            snapshot_record_is_current(dependency, active)
            for dependency in dependencies
        )
        active.remove(record_id)
        snapshot_record_validation_cache[record_id] = current
        return current

    def snapshot_dependencies_match_memo(
        record: Any,
        expected_memo: _RollbackDeepcopyMemo,
    ) -> bool:
        def dependencies_are_current(
            current_record: Any,
            active_records: Set[int],
        ) -> bool:
            cache_key = (id(current_record), id(expected_memo))
            cached = snapshot_dependency_match_cache.get(cache_key)
            if cached is not None:
                return cached
            current_id = id(current_record)
            if current_id in active_records:
                return False
            active_records.add(current_id)
            if (
                not isinstance(current_record, tuple)
                or len(current_record) != 3
                or not isinstance(current_record[1], types.FrameType)
            ):
                active_records.remove(current_id)
                return False
            snapshot_bundle = current_record[1].f_locals.get("completion_snapshot")
            if (
                not isinstance(snapshot_bundle, tuple)
                or len(snapshot_bundle) != 2
                or not isinstance(snapshot_bundle[1], tuple)
            ):
                active_records.remove(current_id)
                return False
            for dependency in snapshot_bundle[1]:
                if (
                    not isinstance(dependency, tuple)
                    or len(dependency) != 3
                    or not isinstance(dependency[0], types.FrameType)
                ):
                    active_records.remove(current_id)
                    return False
                dependency_locals = dependency[0].f_locals
                dependency_original = dependency_locals.get(
                    "x", _ROLLBACK_DEEPCOPY_MISSING
                )
                dependency_copy = dependency_locals.get("y", _ROLLBACK_DEEPCOPY_MISSING)
                if (
                    dependency_original is _ROLLBACK_DEEPCOPY_MISSING
                    or dependency_copy is _ROLLBACK_DEEPCOPY_MISSING
                    or dict.get(
                        expected_memo,
                        id(dependency_original),
                        _ROLLBACK_DEEPCOPY_MISSING,
                    )
                    is not dependency_copy
                ):
                    active_records.remove(current_id)
                    return False
                if not dependencies_are_current(dependency, active_records):
                    active_records.remove(current_id)
                    return False
            active_records.remove(current_id)
            snapshot_dependency_match_cache[cache_key] = True
            return True

        return dependencies_are_current(record, set())

    def completed_pair_from_evidence(
        record: Any,
        expected_memo: _RollbackDeepcopyMemo,
    ) -> Optional[tuple[Any, Any, bool]]:
        if (
            not isinstance(record, tuple)
            or len(record) != 3
            or not isinstance(record[0], types.FrameType)
            or not isinstance(record[1], types.FrameType)
            or not isinstance(record[2], tuple)
        ):
            return None
        completion_frame, recorder_frame, transfer_records = record
        if (
            completion_frame.f_code is not _STDLIB_DEEPCOPY_CODE
            or not frame_returned_normally(completion_frame)
            or recorder_frame.f_code
            is not _RollbackDeepcopyMemo._record_keepalive_completion.__code__
            or not frame_returned_normally(recorder_frame)
        ):
            return None
        completion_locals = completion_frame.f_locals
        original = completion_locals.get("x", _ROLLBACK_DEEPCOPY_MISSING)
        copied_value = completion_locals.get("y", _ROLLBACK_DEEPCOPY_MISSING)
        current_memo = completion_locals.get("memo", _ROLLBACK_DEEPCOPY_MISSING)
        if (
            original is _ROLLBACK_DEEPCOPY_MISSING
            or copied_value is _ROLLBACK_DEEPCOPY_MISSING
            or not isinstance(current_memo, _RollbackDeepcopyMemo)
            or completion_locals.get("d", _ROLLBACK_DEEPCOPY_MISSING) != id(original)
        ):
            return None
        recorder_locals = recorder_frame.f_locals
        completion_dict_version = recorder_locals.get("completion_dict_version")
        mutation_start = recorder_locals.get("completion_mutation_count")
        completion_snapshot = recorder_locals.get("completion_snapshot")
        keepalive_append_frame = recorder_locals.get("caller")
        keepalive_frame = recorder_locals.get("keepalive_frame")
        keepalive_list = (
            keepalive_append_frame.f_locals.get("self")
            if isinstance(keepalive_append_frame, types.FrameType)
            else None
        )
        if (
            recorder_locals.get("self") is not current_memo
            or recorder_locals.get("original") is not original
            or recorder_locals.get("copied_value") is not copied_value
            or recorder_locals.get("deepcopy_frame") is not completion_frame
            or recorder_locals.get("instrumentation_active") is not False
            or type(completion_dict_version) is not int
            or type(mutation_start) is not int
            or not isinstance(keepalive_append_frame, types.FrameType)
            or keepalive_append_frame.f_code
            is not _RollbackKeepAliveList.append.__code__
            or not frame_returned_normally(keepalive_append_frame)
            or type(keepalive_list) is not _RollbackKeepAliveList
            or keepalive_list._memo is not current_memo
            or keepalive_append_frame.f_locals.get("original") is not original
            or not isinstance(keepalive_frame, types.FrameType)
            or keepalive_frame.f_code is not _STDLIB_KEEP_ALIVE_CODE
            or not frame_returned_normally(keepalive_frame)
            or keepalive_frame.f_locals.get("x") is not original
            or keepalive_frame.f_locals.get("memo") is not current_memo
        ):
            return None
        if type(completion_snapshot) is not tuple or len(completion_snapshot) != 2:
            return original, copied_value, False
        expected_dict_version = completion_dict_version
        original_id = id(original)
        for transfer_record in transfer_records:
            if (
                not isinstance(transfer_record, tuple)
                or len(transfer_record) != 2
                or not isinstance(transfer_record[0], types.FrameType)
                or not isinstance(transfer_record[1], types.FrameType)
            ):
                return None
            transfer_frame, transfer_recorder_frame = transfer_record
            if (
                not frame_returned_normally(transfer_frame)
                or transfer_recorder_frame.f_code
                is not _RollbackDeepcopyMemo._transfer_local_completion_evidence.__code__
                or not frame_returned_normally(transfer_recorder_frame)
            ):
                return None
            transfer_locals = transfer_frame.f_locals
            transfer_recorder_locals = transfer_recorder_frame.f_locals
            if transfer_frame.f_code is _RollbackDeepcopyMemo.update.__code__:
                if transfer_locals.get("other") is not current_memo:
                    return None
                next_memo = transfer_locals.get("self", _ROLLBACK_DEEPCOPY_MISSING)
                expected_update = True
            elif transfer_frame.f_code is _RollbackDeepcopyMemo.copy.__code__:
                if transfer_locals.get("self") is not current_memo:
                    return None
                next_memo = transfer_locals.get("copied", _ROLLBACK_DEEPCOPY_MISSING)
                expected_update = False
            else:
                return None
            if (
                not isinstance(next_memo, _RollbackDeepcopyMemo)
                or transfer_recorder_locals.get("caller") is not transfer_frame
                or transfer_recorder_locals.get("self") is not next_memo
                or transfer_recorder_locals.get("source") is not current_memo
                or transfer_recorder_locals.get("instrumentation_active") is not False
                or transfer_recorder_locals.get("called_from_update")
                is not expected_update
                or transfer_recorder_locals.get("called_from_copy") is expected_update
                or type(transfer_recorder_locals.get("source_dict_version")) is not int
                or type(transfer_recorder_locals.get("target_dict_version")) is not int
                or type(transfer_recorder_locals.get("source_mutation_count"))
                is not int
                or type(transfer_recorder_locals.get("target_mutation_count"))
                is not int
            ):
                return None
            source_mutation_count = transfer_recorder_locals["source_mutation_count"]
            mutation_result = validate_mutation_segment(
                current_memo,
                mutation_start,
                source_mutation_count,
                expected_dict_version,
                original_id,
            )
            if mutation_result is None:
                return None
            mutation_is_current, expected_dict_version = mutation_result
            if not mutation_is_current:
                return original, copied_value, False
            if transfer_recorder_locals["source_dict_version"] != expected_dict_version:
                return original, copied_value, False
            current_memo = next_memo
            expected_dict_version = transfer_recorder_locals["target_dict_version"]
            mutation_start = transfer_recorder_locals["target_mutation_count"]
        if current_memo is not expected_memo:
            return None
        final_journal = nested_completion_mutations.get(id(current_memo))
        if (
            not isinstance(final_journal, tuple)
            or len(final_journal) != 2
            or final_journal[0] is not current_memo
            or not isinstance(final_journal[1], list)
        ):
            return None
        mutation_result = validate_mutation_segment(
            current_memo,
            mutation_start,
            len(final_journal[1]),
            expected_dict_version,
            original_id,
        )
        if mutation_result is None:
            return None
        mutation_is_current, expected_dict_version = mutation_result
        if not mutation_is_current:
            return original, copied_value, False
        if _rollback_dict_version(current_memo) != expected_dict_version:
            return original, copied_value, False
        if not snapshot_record_is_current(
            record
        ) or not snapshot_dependencies_match_memo(record, current_memo):
            return original, copied_value, False
        return original, copied_value, True

    def pop_completed(original_id: int) -> Any:
        existed = original_id in completed_memo
        prior = completed_memo.pop(original_id, None)
        if existed:
            prior_id = id(prior)
            remaining = completed_value_refcounts.get(prior_id, 1) - 1
            if remaining > 0:
                completed_value_refcounts[prior_id] = remaining
            else:
                completed_value_refcounts.pop(prior_id, None)
        return prior

    def set_authoritative_fallback(original_id: int, value: Any) -> None:
        """Memoize an original selected after exact rollback became impossible."""

        authoritative_fallback_memo[original_id] = value
        set_completed(original_id, value)

    def set_active(original_id: int, value: Any) -> None:
        if original_id in active_memo:
            prior_id = id(active_memo[original_id])
            remaining = active_value_refcounts.get(prior_id, 1) - 1
            if remaining > 0:
                active_value_refcounts[prior_id] = remaining
            else:
                active_value_refcounts.pop(prior_id, None)
        active_memo[original_id] = value
        value_id = id(value)
        active_value_refcounts[value_id] = active_value_refcounts.get(value_id, 0) + 1

    def pop_active(original_id: int) -> Any:
        existed = original_id in active_memo
        prior = active_memo.pop(original_id, None)
        if existed:
            prior_id = id(prior)
            remaining = active_value_refcounts.get(prior_id, 1) - 1
            if remaining > 0:
                active_value_refcounts[prior_id] = remaining
            else:
                active_value_refcounts.pop(prior_id, None)
        return prior

    def graph_contains_identity(root: Any, target: Any) -> bool:
        """Inspect copied state without invoking user-defined iterators."""

        seen: Set[int] = set()
        stack = [root]
        direct_function_id = id(root) if type(root) is types.FunctionType else None
        while stack:
            current = stack.pop()
            if current is target:
                return True
            current_id = id(current)
            if current_id in seen or is_rollback_leaf(current):
                continue
            seen.add(current_id)
            stack.extend(rollback_graph_referents(current))
            if current_id == direct_function_id:
                stack.extend(rollback_function_global_referents(current))
        return False

    def graph_identity_ids(root: Any) -> Set[int]:
        """Collect a copied graph's identities in one side-effect-free pass."""

        identities: Set[int] = set()
        stack = [root]
        direct_function_id = id(root) if type(root) is types.FunctionType else None
        while stack:
            current = stack.pop()
            current_id = id(current)
            if current_id in identities:
                continue
            identities.add(current_id)
            if is_rollback_leaf(current):
                continue
            stack.extend(rollback_graph_referents(current))
            if current_id == direct_function_id:
                stack.extend(rollback_function_global_referents(current))
        return identities

    def copy_graph_has_observing_hook(
        root: Any,
        memo: Mapping[int, Any],
        *,
        prior_memo_only: bool = False,
    ) -> bool:
        """Whether copying can observe prior reducer iterator callbacks."""

        observing_names = (
            "__deepcopy__",
            "__reduce__",
            "__reduce_ex__",
            "__getnewargs_ex__",
            "__getnewargs__",
            "__getstate__",
            "__setstate__",
            "__setattr__",
            "__delattr__",
            "__new__",
            "__getattr__",
            "__getattribute__",
            "__call__",
        )
        namedtuple_new_fingerprints: Dict[int, tuple[Any, ...]] = {}

        def inert_code_constant(value: Any) -> tuple[Any, ...]:
            value_type = type(value)
            if value is None or value is Ellipsis or value is NotImplemented:
                return ("singleton", id(value))
            if (
                value_type is bool
                or value_type is int
                or value_type is float
                or value_type is complex
                or value_type is str
                or value_type is bytes
            ):
                return ("primitive", id(value_type), value)
            if value_type is tuple:
                return (
                    "tuple",
                    *(inert_code_constant(item) for item in value),
                )
            return ("opaque", id(value_type), id(value))

        def function_semantics(function: Any) -> tuple[Any, ...]:
            code = function.__code__
            return (
                code.co_argcount,
                code.co_posonlyargcount,
                code.co_kwonlyargcount,
                code.co_nlocals,
                code.co_stacksize,
                code.co_flags,
                inert_code_constant(code.co_code),
                tuple(inert_code_constant(item) for item in code.co_consts),
                tuple(inert_code_constant(item) for item in code.co_names),
                tuple(inert_code_constant(item) for item in code.co_freevars),
                tuple(inert_code_constant(item) for item in code.co_cellvars),
                function.__closure__,
            )

        def generated_namedtuple_new_semantics(field_count: int) -> tuple[Any, ...]:
            fingerprint = namedtuple_new_fingerprints.get(field_count)
            if fingerprint is None:
                probe = _STDLIB_NAMEDTUPLE(
                    "_RollbackNamedTupleProbe",
                    [f"field_{index}" for index in range(field_count)],
                )
                raw_new = probe.__dict__["__new__"]
                fingerprint = function_semantics(raw_new.__func__)
                namedtuple_new_fingerprints[field_count] = fingerprint
            return fingerprint

        def is_generated_namedtuple_method(owner: type, name: str) -> bool:
            owner_namespace = raw_class_namespace(owner)
            fields = owner_namespace.get("_fields")
            if not (
                issubclass(owner, tuple)
                and type(fields) is tuple
                and all(type(field_name) is str for field_name in fields)
            ):
                return False
            if name == "__getnewargs__":
                getnewargs = owner_namespace.get(name)
                closure = (
                    getnewargs.__closure__
                    if type(getnewargs) is types.FunctionType
                    else None
                )
                closure_contains_tuple = False
                if closure is not None and len(closure) == 1:
                    try:
                        closure_contains_tuple = closure[0].cell_contents is tuple
                    except ValueError:
                        pass
                return bool(
                    type(getnewargs) is types.FunctionType
                    and getnewargs.__code__ is _NAMEDTUPLE_GETNEWARGS_CODE
                    and getnewargs.__defaults__ is None
                    and getnewargs.__kwdefaults__ is None
                    and closure_contains_tuple
                )
            if name != "__new__":
                return False
            raw_new = owner_namespace.get("__new__")
            new_function = (
                raw_new.__func__ if isinstance(raw_new, staticmethod) else None
            )
            return bool(
                type(new_function) is types.FunctionType
                and new_function.__globals__.get("_tuple_new") is tuple.__new__
                and function_semantics(new_function)
                == generated_namedtuple_new_semantics(
                    len(owner_namespace.get("_fields", ()))
                )
            )

        def protocol_method_can_observe_prior_copy(
            raw_method: Any,
            name: str,
            owner: Optional[type] = None,
        ) -> bool:
            """Conservatively classify callbacks without a memo argument."""

            if name == "__deepcopy__":
                return True
            function = (
                raw_method.__func__
                if isinstance(raw_method, (staticmethod, classmethod))
                else raw_method
            )
            if type(function) is not types.FunctionType:
                return True
            if function.__closure__ or function.__defaults__ or function.__kwdefaults__:
                return True
            referenced_attributes: Set[str] = set()
            for instruction in dis.get_instructions(function):
                if instruction.opname in {
                    "LOAD_GLOBAL",
                    "LOAD_NAME",
                    "LOAD_FROM_DICT_OR_GLOBALS",
                }:
                    return True
                if instruction.opname in {"LOAD_ATTR", "LOAD_METHOD"}:
                    referenced_attributes.add(str(instruction.argval))
            if "__class__" in referenced_attributes:
                return True
            if owner is not None:
                for attribute_name in referenced_attributes:
                    for binding_owner in raw_class_mro(owner):
                        binding_namespace = raw_class_namespace(binding_owner)
                        if attribute_name not in binding_namespace:
                            continue
                        binding = binding_namespace[attribute_name]
                        if (
                            isinstance(
                                binding,
                                (
                                    types.MemberDescriptorType,
                                    types.GetSetDescriptorType,
                                ),
                            )
                            or id(binding_owner) in _BUILTIN_TYPE_IDENTITY_IDS
                        ):
                            break
                        return True
            return False

        def has_replaced_slot_descriptor(current_type: type) -> bool:
            for declaring_owner in raw_class_mro(current_type):
                declaring_namespace = raw_class_namespace(declaring_owner)
                raw_slots = declaring_namespace.get("__slots__", ())
                if isinstance(raw_slots, str):
                    slots = (raw_slots,)
                elif isinstance(raw_slots, Mapping):
                    slots = tuple(raw_slots)
                else:
                    try:
                        slots = tuple(raw_slots or ())
                    except TypeError:
                        slots = ()
                for slot in slots:
                    for slot_name in declared_slot_storage_names(declaring_owner, slot):
                        if slot_name in {"", "__dict__", "__weakref__"}:
                            continue
                        effective_descriptor = None
                        for binding_owner in raw_class_mro(current_type):
                            binding_namespace = raw_class_namespace(binding_owner)
                            if slot_name in binding_namespace:
                                effective_descriptor = binding_namespace[slot_name]
                                break
                        if effective_descriptor is not None and not isinstance(
                            effective_descriptor, types.MemberDescriptorType
                        ):
                            return True
            return False

        prior_copy_ids = (
            {
                id(prior_copy)
                for prior_copy in (
                    *completed_memo.values(),
                    *active_memo.values(),
                )
            }
            if prior_memo_only
            else set()
        )
        seen: Set[int] = set()
        stack = [root]
        while stack:
            current = stack.pop()
            current_id = id(current)
            if prior_memo_only and current_id in prior_copy_ids:
                return True
            if current_id in seen or current_id in memo or is_rollback_leaf(current):
                continue
            seen.add(current_id)
            current_type = type(current)
            if any(
                registered_type is current_type
                for registered_type in copyreg.dispatch_table
            ):
                return True
            _dict_descriptor, raw_attributes = raw_instance_dict(current)
            if raw_attributes is not None and any(
                name in raw_attributes for name in observing_names
            ):
                return True
            if has_replaced_slot_descriptor(current_type):
                return True
            for owner in raw_class_mro(current_type):
                if owner is object:
                    continue
                owner_is_builtin = id(owner) in _BUILTIN_TYPE_IDENTITY_IDS
                if not owner_is_builtin:
                    owner_namespace = raw_class_namespace(owner)
                    for name in observing_names:
                        if name not in owner_namespace:
                            continue
                        if not is_generated_namedtuple_method(owner, name):
                            if (
                                not prior_memo_only
                                or protocol_method_can_observe_prior_copy(
                                    owner_namespace[name], name, owner
                                )
                            ):
                                return True
                    if prior_memo_only:
                        verified_namedtuple_owner = all(
                            is_generated_namedtuple_method(owner, method_name)
                            for method_name in ("__new__", "__getnewargs__")
                        )
                        namedtuple_fields = owner_namespace.get("_fields", ())
                        for descriptor_name, descriptor in owner_namespace.items():
                            if (
                                verified_namedtuple_owner
                                and descriptor_name in namedtuple_fields
                                and type(descriptor) is _STDLIB_TUPLEGETTER_TYPE
                            ):
                                continue
                            if raw_inherits(descriptor, property):
                                fget, fset, fdel, _doc = raw_property_state(descriptor)
                                if any(
                                    accessor is not None
                                    and protocol_method_can_observe_prior_copy(
                                        accessor,
                                        "__getattribute__",
                                        owner,
                                    )
                                    for accessor in (fget, fset, fdel)
                                ):
                                    return True
                                continue
                            if isinstance(
                                descriptor,
                                (
                                    staticmethod,
                                    classmethod,
                                    types.FunctionType,
                                    types.MemberDescriptorType,
                                    types.GetSetDescriptorType,
                                ),
                            ):
                                continue
                            descriptor_type = type(descriptor)
                            descriptor_get = raw_class_namespace(descriptor_type).get(
                                "__get__"
                            )
                            if (
                                descriptor_get is not None
                                and id(descriptor_type)
                                not in _BUILTIN_TYPE_IDENTITY_IDS
                                and protocol_method_can_observe_prior_copy(
                                    descriptor_get,
                                    "__getattribute__",
                                    descriptor_type,
                                )
                            ):
                                return True
            stack.extend(rollback_graph_referents(current))
        return False

    def snapshot_completed_mutables(
        roots: Optional[Sequence[Any]] = None,
        *,
        stop_ids: Optional[Mapping[int, Any]] = None,
        encountered_stop_ids: Optional[Set[int]] = None,
        require_complete: bool = False,
    ) -> List[tuple[Any, ...]]:
        """Capture rollback copies that user callbacks could mutate."""

        snapshots: List[tuple[Any, ...]] = []
        seen: Set[int] = set()
        candidates: List[Any] = []
        traversal_seen: Set[int] = set()
        memoryview_backing_ids: Set[int] = set()
        stack = list(
            roots
            if roots is not None
            else (
                *completed_memo.values(),
                *active_memo.values(),
            )
        )
        while stack:
            current = stack.pop()
            current_id = id(current)
            if current_id in traversal_seen or is_rollback_leaf(current):
                continue
            if (stop_ids is not None and current_id in stop_ids) or any(
                current_id in inherited_stop_ids
                for inherited_stop_ids in snapshot_stop_stack
            ):
                if (
                    encountered_stop_ids is not None
                    and stop_ids is not None
                    and current_id in stop_ids
                ):
                    encountered_stop_ids.add(current_id)
                continue
            traversal_seen.add(current_id)
            candidates.append(current)
            if type(current) is memoryview:
                try:
                    backing = current.obj
                except ValueError:
                    pass
                else:
                    memoryview_backing_ids.add(id(backing))
            stack.extend(rollback_graph_referents(current))
        for current in candidates:
            current_id = id(current)
            if current_id in seen or is_rollback_leaf(current):
                continue
            seen.add(current_id)
            container_kind = ""
            container_state: Any = None
            if raw_inherits(current, BaseException):
                container_kind = "exception"
                container_state = rollback_builtin_exception_descriptor_state(current)
            elif raw_inherits(current, collections.defaultdict):
                container_kind = "defaultdict"
                container_state = (
                    dict.copy(current),
                    collections.defaultdict.default_factory.__get__(
                        current, type(current)
                    ),
                    _rollback_dict_table_snapshot(current),
                )
            elif raw_inherits(current, collections.OrderedDict):
                container_kind = "ordered_dict"
                hashed_entries = _rollback_dict_entries_with_hashes(current)
                if hashed_entries is None:
                    ordered_entries = [
                        (key, item, 0)
                        for key, item in collections.OrderedDict.items(current)
                    ]
                else:
                    entries_by_identity = {
                        id(key): (key, item, key_hash)
                        for key, item, key_hash in hashed_entries
                    }
                    logical_keys = _rollback_ordered_dict_keys(current)
                    if (
                        logical_keys is None
                        or len(logical_keys) != len(entries_by_identity)
                        or any(
                            id(key) not in entries_by_identity for key in logical_keys
                        )
                    ):
                        continue
                    ordered_entries = [
                        entries_by_identity[id(key)] for key in logical_keys
                    ]
                ordered_state = _rollback_ordered_dict_state(current)
                if ordered_state is None:
                    continue
                container_state = (ordered_entries, ordered_state)
            elif raw_inherits(current, dict):
                container_kind = "dict"
                container_state = (
                    dict.copy(current),
                    _rollback_dict_table_snapshot(current),
                )
            elif raw_inherits(current, list):
                container_kind = "list"
                container_state = list(list.__iter__(current))
            elif raw_inherits(current, set):
                container_kind = "set"
                container_state = (
                    set.copy(current),
                    _rollback_set_table_snapshot(current),
                )
            elif raw_inherits(current, collections.deque):
                container_kind = "deque"
                container_state = (
                    list(collections.deque.__iter__(current)),
                    _read_cpython_deque_state(current),
                )
            elif type(current) is memoryview:
                try:
                    backing = current.obj
                    view_format = current.format
                    view_itemsize = current.itemsize
                    view_shape = current.shape
                    view_strides = current.strides
                    view_suboffsets = current.suboffsets
                    view_offset = _memoryview_backing_offset(current, backing)
                    view_nbytes = current.nbytes
                    view_readonly = current.readonly
                    raw_contents = current.tobytes()
                    container_kind = "memoryview"
                    container_state = (
                        backing,
                        view_format,
                        view_itemsize,
                        view_shape,
                        view_strides,
                        view_suboffsets,
                        view_offset,
                        view_nbytes,
                        view_readonly,
                        raw_contents,
                    )
                except (TypeError, ValueError):
                    continue
            elif raw_inherits(current, bytearray):
                container_kind = "bytearray"
                container_state = bytes(current)
            elif raw_inherits(current, array.array):
                container_kind = "array"
                container_state = array.array.__getitem__(current, slice(None))
            elif raw_inherits(current, mmap.mmap):
                mmap_view: Optional[memoryview] = None
                try:
                    mmap_view = memoryview(current)
                    file_reconstruction = _mmap_file_reconstruction(current)
                    container_kind = "mmap"
                    container_state = (
                        mmap.mmap.__getitem__(current, slice(None)),
                        mmap.mmap.tell(current),
                        mmap_view.readonly,
                        file_reconstruction,
                    )
                except (OSError, ValueError):
                    continue
                finally:
                    if mmap_view is not None:
                        mmap_view.release()
            elif current_id in memoryview_backing_ids:
                exported_view: Optional[memoryview] = None
                try:
                    exported_view = memoryview(current)
                    if not exported_view.readonly:
                        container_kind = "buffer_exporter"
                        container_state = exported_view.tobytes()
                except (BufferError, TypeError, ValueError):
                    pass
                finally:
                    if exported_view is not None:
                        exported_view.release()
            elif raw_inherits(current, random.Random):
                container_kind = "random"
                container_state = random.Random.getstate(current)
            elif raw_inherits(current, type(itertools.count())):
                container_kind = "count"
                container_state = (
                    type(current),
                    itertools.count.__reduce__(current)[1],
                )
            elif type(current) in rollback_iterator_types:
                container_kind = "iterator"
                container_state = copy.copy(current)
            elif raw_inherits(current, io.StringIO):
                if io.StringIO.closed.__get__(current, type(current)):
                    continue
                container_kind = "string_io"
                container_state = io.StringIO.__getstate__(current)
            elif raw_inherits(current, io.BytesIO):
                if io.BytesIO.closed.__get__(current, type(current)):
                    continue
                container_kind = "bytes_io"
                container_state = (
                    io.BytesIO.getvalue(current),
                    io.BytesIO.tell(current),
                )
            elif type(current) is types.FunctionType:
                container_kind = "function"
                closure_state: List[tuple[Any, bool, Any]] = []
                for cell in current.__closure__ or ():
                    try:
                        closure_state.append((cell, True, cell.cell_contents))
                    except ValueError:
                        closure_state.append((cell, False, None))
                container_state = (
                    current.__defaults__,
                    current.__kwdefaults__,
                    dict(current.__kwdefaults__ or {}),
                    current.__annotations__,
                    dict(current.__annotations__),
                    closure_state,
                    current.__code__,
                    current.__name__,
                    current.__qualname__,
                    current.__module__,
                    current.__doc__,
                )
            elif type(current) is types.CellType:
                container_kind = "cell"
                try:
                    container_state = (True, current.cell_contents)
                except ValueError:
                    container_state = (False, None)
            if not container_kind:
                exported_view = None
                try:
                    exported_view = memoryview(current)
                    if not exported_view.readonly:
                        container_kind = "buffer_exporter"
                        container_state = exported_view.tobytes()
                except (BufferError, TypeError, ValueError):
                    pass
                finally:
                    if exported_view is not None:
                        exported_view.release()
            attribute_descriptor, raw_attributes = raw_instance_dict(current)
            attribute_state = (
                dict(raw_attributes) if raw_attributes is not None else None
            )
            slot_state: List[tuple[Any, bool, Any]] = []
            for _slot_name, descriptor in declared_slot_descriptors(current):
                try:
                    slot_state.append(
                        (
                            descriptor,
                            True,
                            descriptor.__get__(current, type(current)),
                        )
                    )
                except (AttributeError, TypeError):
                    slot_state.append((descriptor, False, None))
            if container_kind or attribute_state is not None or slot_state:
                snapshots.append(
                    (
                        current,
                        container_kind,
                        container_state,
                        attribute_descriptor,
                        attribute_state,
                        slot_state,
                    )
                )
            elif require_complete:
                dispatcher = copy._deepcopy_dispatch.get(  # noqa: SLF001
                    type(current)
                )
                known_immutable_wrapper = bool(
                    dispatcher is copy._deepcopy_atomic  # noqa: SLF001
                    or raw_inherits(current, tuple)
                    or raw_inherits(current, frozenset)
                    or type(current) is types.MethodType
                )
                if not known_immutable_wrapper:
                    raise TypeError("completed value has unsupported mutable state")
        return snapshots

    def freeze_completion_snapshot(
        snapshots: List[tuple[Any, ...]],
    ) -> tuple[Any, ...]:
        """Freeze snapshot metadata without comparing user-defined objects."""

        snapshot_object_ids = frozenset(id(item[0]) for item in snapshots)

        def freeze(value: Any) -> tuple[Any, ...]:
            if id(value) in snapshot_object_ids:
                return ("identity", value)
            if value is None or type(value) in {bool, int, str, bytes}:
                return ("value", type(value), value)
            if type(value) is bytearray:
                return ("value", bytes, bytes(value))
            if isinstance(value, array.array):
                return ("array", value.typecode, value.tobytes())
            if type(value) is dict:
                return (
                    "dict",
                    tuple(
                        (freeze(key), freeze(item)) for key, item in dict.items(value)
                    ),
                )
            if type(value) is list:
                return (
                    "list",
                    tuple(freeze(item) for item in list.__iter__(value)),
                )
            if type(value) is tuple:
                return (
                    "tuple",
                    tuple(freeze(item) for item in tuple.__iter__(value)),
                )
            if type(value) is set:
                return (
                    "set",
                    tuple(freeze(item) for item in set.__iter__(value)),
                )
            if type(value) is frozenset:
                return (
                    "frozenset",
                    tuple(freeze(item) for item in frozenset.__iter__(value)),
                )
            if type(value) in rollback_iterator_types:
                try:
                    return ("iterator", freeze(value.__reduce__()))
                except (AttributeError, TypeError, ValueError):
                    return ("identity", value)
            return ("identity", value)

        return freeze(snapshots)

    def frozen_completion_snapshots_match(
        expected: tuple[Any, ...],
        current: tuple[Any, ...],
    ) -> bool:
        if (
            type(expected) is not tuple
            or type(current) is not tuple
            or not expected
            or not current
            or expected[0] != current[0]
            or len(expected) != len(current)
        ):
            return False
        tag = expected[0]
        if tag == "identity":
            return expected[1] is current[1]
        if tag in {"value", "array"}:
            return expected == current
        if tag == "iterator":
            return frozen_completion_snapshots_match(expected[1], current[1])
        if tag in {"list", "tuple", "set", "frozenset"}:
            expected_items = expected[1]
            current_items = current[1]
            return bool(
                type(expected_items) is tuple
                and type(current_items) is tuple
                and len(expected_items) == len(current_items)
                and all(
                    frozen_completion_snapshots_match(left, right)
                    for left, right in zip(expected_items, current_items)
                )
            )
        if tag == "dict":
            expected_items = expected[1]
            current_items = current[1]
            return bool(
                type(expected_items) is tuple
                and type(current_items) is tuple
                and len(expected_items) == len(current_items)
                and all(
                    frozen_completion_snapshots_match(expected_key, current_key)
                    and frozen_completion_snapshots_match(expected_value, current_value)
                    for (expected_key, expected_value), (
                        current_key,
                        current_value,
                    ) in zip(expected_items, current_items)
                )
            )
        return False

    def snapshot_before_observing_copy() -> List[tuple[Any, ...]]:
        """Reuse enclosing journals and capture only uncovered copy roots."""

        inherited: Dict[int, tuple[Any, ...]] = {}
        for journal in snapshot_outer_restore_stack:
            inherited.update(journal)
        uncovered_roots = tuple(
            current
            for current in completed_memo.values()
            if id(current) not in inherited
        )
        stop_ids = dict(inherited)
        stop_ids.update((id(current), current) for current in active_memo.values())
        for snapshot in snapshot_completed_mutables(
            uncovered_roots,
            stop_ids=stop_ids or None,
        ):
            inherited.setdefault(id(snapshot[0]), snapshot)
            for journal in snapshot_outer_restore_stack:
                if isinstance(journal, dict):
                    journal.setdefault(id(snapshot[0]), snapshot)
        return list(inherited.values())

    def refresh_observing_copy_journals(
        root: Any,
        reachable_ids: Set[int],
    ) -> None:
        """Advance active journal baselines for valid returned-graph changes."""

        mutable_journals = [
            journal
            for journal in snapshot_outer_restore_stack
            if isinstance(journal, dict)
        ]
        if not mutable_journals:
            return
        for journal in mutable_journals:
            for reachable_id in reachable_ids:
                journal.pop(reachable_id, None)
        inherited: Dict[int, tuple[Any, ...]] = {}
        for journal in mutable_journals:
            inherited.update(journal)
        refreshed = snapshot_completed_mutables(
            (root,),
            stop_ids=inherited or None,
        )
        for snapshot in refreshed:
            for journal in mutable_journals:
                journal[id(snapshot[0])] = snapshot

    def capture_completion_snapshot(
        value: Any,
        dependency_records: Mapping[int, Any],
    ) -> tuple[Any, ...]:
        encountered_dependencies: Set[int] = set()
        snapshots = snapshot_completed_mutables(
            (value,),
            stop_ids=dependency_records,
            encountered_stop_ids=encountered_dependencies,
            require_complete=True,
        )
        dependencies = tuple(
            dependency_records[dependency_id]
            for dependency_id in sorted(encountered_dependencies)
        )
        return freeze_completion_snapshot(snapshots), dependencies

    def completion_snapshot_is_current(
        value: Any,
        expected: tuple[Any, ...],
        dependencies: tuple[Any, ...],
    ) -> bool:
        dependency_records: Dict[int, Any] = {}
        for dependency in dependencies:
            if (
                not isinstance(dependency, tuple)
                or len(dependency) != 3
                or not isinstance(dependency[0], types.FrameType)
            ):
                return False
            dependency_value = dependency[0].f_locals.get(
                "y", _ROLLBACK_DEEPCOPY_MISSING
            )
            if dependency_value is _ROLLBACK_DEEPCOPY_MISSING:
                return False
            dependency_records[id(dependency_value)] = dependency
        encountered_dependencies: Set[int] = set()
        try:
            current = freeze_completion_snapshot(
                snapshot_completed_mutables(
                    (value,),
                    stop_ids=dependency_records,
                    encountered_stop_ids=encountered_dependencies,
                    require_complete=True,
                )
            )
        except Exception:
            return False
        if encountered_dependencies != set(dependency_records):
            return False
        return frozen_completion_snapshots_match(expected, current)

    def replace_mutable_identity_edges(
        root: Any,
        target: Any,
        replacement: Any,
    ) -> None:
        """Iteratively repair mutable edges before immutable reconstruction."""

        seen: Set[int] = set()
        stack = [root]
        while stack:
            current = stack.pop()
            current_id = id(current)
            if current_id in seen or is_rollback_leaf(current):
                continue
            seen.add(current_id)
            if raw_inherits(current, list):
                for index, item in enumerate(list(list.__iter__(current))):
                    if item is target:
                        current[index] = replacement
                    else:
                        stack.append(item)
            elif raw_inherits(current, dict):
                for _key, item in list(dict.items(current)):
                    stack.append(item)
            elif raw_inherits(current, collections.deque):
                original_values = list(collections.deque.__iter__(current))
                rewritten_values = [
                    replacement if item is target else item for item in original_values
                ]
                for index, (original, rewritten) in enumerate(
                    zip(original_values, rewritten_values)
                ):
                    if original is not rewritten:
                        collections.deque.__setitem__(current, index, rewritten)
                stack.extend(rewritten_values)
            _descriptor, attributes = raw_instance_dict(current)
            if attributes is not None:
                attribute_entries = _rollback_dict_entries_with_hashes(attributes)
                if attribute_entries is None:
                    attribute_entries = [
                        (name, item, hash(name))
                        for name, item in list(dict.items(attributes))
                    ]
                for name, item, name_hash in attribute_entries:
                    if item is target:
                        if not _rollback_dict_setitem_known_hash(
                            attributes, name, replacement, name_hash
                        ):
                            attributes[name] = replacement
                    else:
                        stack.append(item)
            for _slot_name, descriptor in declared_slot_descriptors(current):
                try:
                    item = descriptor.__get__(current, type(current))
                except (AttributeError, TypeError):
                    continue
                if item is target:
                    try:
                        descriptor.__set__(current, replacement)
                    except (AttributeError, TypeError):
                        pass
                else:
                    stack.append(item)

    def rewrite_dictionary_edges(
        value: dict[Any, Any],
        transform: Callable[[Any], Any],
        key_requires_rehash: Optional[Callable[[Any], bool]] = None,
        key_may_have_changed: Optional[Callable[[Any], bool]] = None,
    ) -> dict[Any, Any]:
        """Rewrite mapping edges while reusing hashes of unchanged keys."""

        hashed_entries = _rollback_dict_entries_with_hashes(value)
        if hashed_entries is None:
            hashed_entries = [(key, item, 0) for key, item in list(dict.items(value))]
            hashes_available = False
        else:
            hashes_available = True
            if raw_inherits(value, collections.OrderedDict):
                logical_keys = _rollback_ordered_dict_keys(value)
                entries_by_identity = {
                    id(key): (key, item, key_hash)
                    for key, item, key_hash in hashed_entries
                }
                if logical_keys is None or any(
                    id(key) not in entries_by_identity for key in logical_keys
                ):
                    hashes_available = False
                else:
                    hashed_entries = [
                        entries_by_identity[id(key)] for key in logical_keys
                    ]
        requires_rehash = [
            bool(key_requires_rehash is not None and key_requires_rehash(key))
            for key, _item, _key_hash in hashed_entries
        ]
        keys_may_have_changed = [
            bool(
                key_may_have_changed(key)
                if key_may_have_changed is not None
                else rehash
            )
            for (key, _item, _key_hash), rehash in zip(hashed_entries, requires_rehash)
        ]
        rewritten_entries = [
            (transform(key), transform(item), key_hash)
            for key, item, key_hash in hashed_entries
        ]
        if not any(
            original_key is not rewritten_key
            or original_item is not rewritten_item
            or may_have_changed
            for (original_key, original_item, _hash), may_have_changed, (
                rewritten_key,
                rewritten_item,
                _rewritten_hash,
            ) in zip(hashed_entries, keys_may_have_changed, rewritten_entries)
        ):
            return value
        if hashes_available:
            keys_are_unchanged = all(
                original_key is rewritten_key and not may_have_changed
                for (original_key, _item, _hash), may_have_changed, (
                    rewritten_key,
                    _rewritten_item,
                    _rewritten_hash,
                ) in zip(hashed_entries, keys_may_have_changed, rewritten_entries)
            )
            if keys_are_unchanged and all(
                original_item is rewritten_item
                or _rollback_dict_setitem_known_hash(
                    value,
                    original_key,
                    rewritten_item,
                    key_hash,
                )
                for (original_key, original_item, key_hash), (
                    _rewritten_key,
                    rewritten_item,
                    _rewritten_hash,
                ) in zip(hashed_entries, rewritten_entries)
            ):
                return value
            candidate_entries = [
                (
                    rewritten_key,
                    rewritten_item,
                    key_hash
                    if original_key is rewritten_key and not rehash
                    else hash(rewritten_key),
                    original_key is not rewritten_key or may_have_changed,
                )
                for (
                    original_key,
                    _original_item,
                    key_hash,
                ), rehash, may_have_changed, (
                    rewritten_key,
                    rewritten_item,
                    _rewritten_hash,
                ) in zip(
                    hashed_entries,
                    requires_rehash,
                    keys_may_have_changed,
                    rewritten_entries,
                )
            ]
            cached_entries: List[tuple[Any, Any, int, bool]] = []
            cached_by_identity: Dict[int, int] = {}
            cached_by_hash: Dict[int, List[int]] = {}
            for rewritten_key, rewritten_item, key_hash, changed in candidate_entries:
                matched_index = cached_by_identity.get(id(rewritten_key))
                if matched_index is None:
                    for index in cached_by_hash.get(key_hash, ()):
                        existing_key, _item, _hash, existing_changed = cached_entries[
                            index
                        ]
                        if (
                            changed or existing_changed
                        ) and existing_key == rewritten_key:
                            matched_index = index
                            break
                if matched_index is not None:
                    existing_key, _item, existing_hash, existing_changed = (
                        cached_entries[matched_index]
                    )
                    canonical_key = rewritten_key if changed else existing_key
                    canonical_hash = key_hash if changed else existing_hash
                    cached_entries[matched_index] = (
                        canonical_key,
                        rewritten_item,
                        canonical_hash,
                        changed or existing_changed,
                    )
                    if canonical_key is not existing_key:
                        if cached_by_identity.get(id(existing_key)) == matched_index:
                            cached_by_identity.pop(id(existing_key))
                        cached_by_identity[id(canonical_key)] = matched_index
                    if canonical_hash != existing_hash:
                        cached_by_hash[existing_hash].remove(matched_index)
                        cached_by_hash.setdefault(canonical_hash, []).append(
                            matched_index
                        )
                else:
                    matched_index = len(cached_entries)
                    cached_entries.append(
                        (rewritten_key, rewritten_item, key_hash, changed)
                    )
                    cached_by_identity[id(rewritten_key)] = matched_index
                    cached_by_hash.setdefault(key_hash, []).append(matched_index)
            normalized_entries = [
                (key, item, key_hash)
                for key, item, key_hash, _changed in cached_entries
            ]
            if len(normalized_entries) == len(hashed_entries) and all(
                original_key is rewritten_key and original_hash == rewritten_hash
                for (original_key, _original_item, original_hash), (
                    rewritten_key,
                    _rewritten_item,
                    rewritten_hash,
                ) in zip(hashed_entries, normalized_entries)
            ):
                if all(
                    original_item is rewritten_item
                    or _rollback_dict_setitem_known_hash(
                        value,
                        original_key,
                        rewritten_item,
                        original_hash,
                    )
                    for (
                        original_key,
                        original_item,
                        original_hash,
                    ), (
                        _rewritten_key,
                        rewritten_item,
                        _rewritten_hash,
                    ) in zip(hashed_entries, normalized_entries)
                ):
                    return value
            if raw_inherits(value, collections.OrderedDict):
                ordered_structure_changed = bool(
                    len(normalized_entries) != len(hashed_entries)
                    or any(
                        original_key is not rewritten_key
                        for (original_key, _item, _hash), (
                            rewritten_key,
                            _rewritten_item,
                            _rewritten_hash,
                        ) in zip(hashed_entries, normalized_entries)
                    )
                )
                if ordered_structure_changed and any(
                    type(referrer) in rollback_ordered_iterator_types
                    for referrer in gc.get_referrers(value)
                ):
                    raise TypeError(
                        "ordered dictionary iterator structure cannot be preserved"
                    )
                rebuilt_ordered = _rollback_build_ordered_dict(
                    normalized_entries, type(value)
                )
                if rebuilt_ordered is not None and (
                    _rollback_transplant_ordered_dict_state(value, rebuilt_ordered)
                ):
                    return value
            else:
                rebuilt = _rollback_build_exact_dict(
                    normalized_entries,
                    type(value),
                )
                if rebuilt is not None and _rollback_transplant_dict_table(
                    value, rebuilt
                ):
                    return value
        items = [
            (rewritten_key, rewritten_item)
            for rewritten_key, rewritten_item, _key_hash in rewritten_entries
        ]
        if raw_inherits(value, collections.OrderedDict):
            collections.OrderedDict.clear(value)
            collections.OrderedDict.update(value, items)
        else:
            dict.clear(value)
            dict.update(value, items)
        return value

    def hash_requires_recalculation(
        value: Any,
        contains_rewrite: Callable[[Any], bool],
    ) -> bool:
        """Avoid revisiting a proven constant hash during graph repair."""

        if not contains_rewrite(value):
            return False
        hash_function = None
        for owner in raw_value_mro(value):
            hash_function = raw_class_namespace(owner).get("__hash__")
            if hash_function is not None:
                break
        if type(hash_function) is types.FunctionType:
            try:
                syntax = ast.parse(textwrap.dedent(inspect.getsource(hash_function)))
            except (IndentationError, OSError, SyntaxError, TypeError):
                syntax = None
            if syntax is not None:
                return_values = [
                    node.value
                    for node in ast.walk(syntax)
                    if isinstance(node, ast.Return)
                ]
                return_values.extend(
                    node.body
                    for node in ast.walk(syntax)
                    if isinstance(node, ast.Lambda)
                )
                if (
                    return_values
                    and all(
                        isinstance(return_value, ast.Constant)
                        for return_value in return_values
                    )
                    and len(
                        {
                            (type(return_value.value), repr(return_value.value))
                            for return_value in return_values
                            if isinstance(return_value, ast.Constant)
                        }
                    )
                    == 1
                ):
                    return False
        return True

    def rewrite_hash_container_edges(
        value: Any,
        transform: Callable[[Any], Any],
        member_requires_rehash: Optional[Callable[[Any], bool]] = None,
        member_may_have_changed: Optional[Callable[[Any], bool]] = None,
    ) -> Any:
        """Rewrite only changed set members, retaining sibling hashes."""

        is_frozen = raw_inherits(value, frozenset)
        iterator_snapshots: List[tuple[Any, tuple[Any, ...]]] = []
        for referrer in gc.get_referrers(value):
            if type(referrer) is not rollback_iterator_types[7]:
                continue
            try:
                reduction_descriptor = raw_class_namespace(type(referrer))["__reduce__"]
                _constructor, arguments, *_state = reduction_descriptor(referrer)
                iterator_snapshots.append((referrer, tuple(arguments[0])))
            except (AttributeError, TypeError, ValueError):
                continue
        hashed_entries = _rollback_set_entries_with_hashes(value)
        original_values = (
            tuple(item for item, _key_hash in hashed_entries)
            if hashed_entries is not None
            else tuple(frozenset.__iter__(value) if is_frozen else set.__iter__(value))
        )
        requires_rehash = tuple(
            bool(member_requires_rehash is not None and member_requires_rehash(item))
            for item in original_values
        )
        members_may_have_changed = tuple(
            bool(
                member_may_have_changed(item)
                if member_may_have_changed is not None
                else rehash
            )
            for item, rehash in zip(original_values, requires_rehash)
        )
        rewritten_values = tuple(transform(item) for item in original_values)
        changed_pairs = tuple(
            (original, rewritten, rehash, may_have_changed)
            for original, rewritten, rehash, may_have_changed in zip(
                original_values,
                rewritten_values,
                requires_rehash,
                members_may_have_changed,
            )
            if original is not rewritten or may_have_changed
        )
        if not changed_pairs:
            return value
        if hashed_entries is not None:
            rewritten_by_identity = {
                id(original): (rewritten, rehash, may_have_changed)
                for original, rewritten, rehash, may_have_changed in changed_pairs
            }
            candidate_entries: List[tuple[Any, int, bool]] = []
            for original, key_hash in hashed_entries:
                rewritten, rehash, may_have_changed = rewritten_by_identity.get(
                    id(original), (original, False, False)
                )
                changed = rewritten is not original or may_have_changed
                rewritten_hash = (
                    key_hash
                    if rewritten is original and not rehash
                    else hash(rewritten)
                )
                candidate_entries.append((rewritten, rewritten_hash, changed))
            rewritten_entries: List[tuple[Any, int, bool]] = []
            rewritten_by_result_identity: Dict[int, int] = {}
            rewritten_by_hash: Dict[int, List[int]] = {}
            for rewritten, rewritten_hash, changed in candidate_entries:
                existing_index = rewritten_by_result_identity.get(id(rewritten))
                if existing_index is None:
                    for candidate_index in rewritten_by_hash.get(rewritten_hash, ()):
                        existing, _existing_hash, existing_changed = rewritten_entries[
                            candidate_index
                        ]
                        if (changed or existing_changed) and existing == rewritten:
                            existing_index = candidate_index
                            break
                if existing_index is None:
                    existing_index = len(rewritten_entries)
                    rewritten_entries.append((rewritten, rewritten_hash, changed))
                    rewritten_by_result_identity[id(rewritten)] = existing_index
                    rewritten_by_hash.setdefault(rewritten_hash, []).append(
                        existing_index
                    )
                else:
                    existing, existing_hash, existing_changed = rewritten_entries[
                        existing_index
                    ]
                    if changed and not existing_changed:
                        rewritten_entries[existing_index] = (
                            rewritten,
                            rewritten_hash,
                            True,
                        )
                        if (
                            rewritten_by_result_identity.get(id(existing))
                            == existing_index
                        ):
                            rewritten_by_result_identity.pop(id(existing))
                        rewritten_by_result_identity[id(rewritten)] = existing_index
                        if rewritten_hash != existing_hash:
                            rewritten_by_hash[existing_hash].remove(existing_index)
                            rewritten_by_hash.setdefault(rewritten_hash, []).append(
                                existing_index
                            )
            normalized_set_entries = [
                (item, item_hash) for item, item_hash, _changed in rewritten_entries
            ]
            normalized_by_identity = {
                id(item): (item, item_hash)
                for item, item_hash in normalized_set_entries
            }

            def rewritten_iterator_entries(
                remaining_items: Sequence[Any],
            ) -> tuple[tuple[Any, int], ...]:
                return tuple(
                    normalized_by_identity[
                        id(
                            rewritten_by_identity.get(
                                id(item), (item, False, False)
                            )[0]
                        )
                    ]
                    for item in remaining_items
                    if id(
                        rewritten_by_identity.get(
                            id(item), (item, False, False)
                        )[0]
                    )
                    in normalized_by_identity
                )

            def rebind_changed_iterators(iterator_source: Any) -> None:
                for iterator, remaining_items in iterator_snapshots:
                    rewritten_remaining = rewritten_iterator_entries(remaining_items)
                    if not _rollback_rebind_set_iterator(
                        iterator, iterator_source, rewritten_remaining
                    ):
                        raise TypeError("set iterator coupling unavailable")

            def iterator_positions_are_available(iterator_source: Any) -> bool:
                return all(
                    _rollback_set_iterator_position(
                        iterator_source,
                        rewritten_iterator_entries(remaining_items),
                    )
                    is not None
                    for _iterator, remaining_items in iterator_snapshots
                )

            if not is_frozen and _rollback_replace_set_members_in_place(
                value,
                hashed_entries,
                normalized_set_entries,
            ):
                return value
            rebuild_target = value
            if is_frozen:
                placeholder_values = range(len(hashed_entries))
                rebuild_target = frozenset.__new__(type(value), placeholder_values)
                layout_probe = rebuild_target
            else:
                layout_probe = _rollback_build_set_layout_probe(
                    value, normalized_set_entries
                )
            if iterator_snapshots and (
                layout_probe is None
                or not iterator_positions_are_available(layout_probe)
            ):
                raise TypeError("set iterator layout unavailable")
            if _rollback_rebuild_set_table(
                rebuild_target,
                normalized_set_entries,
            ):
                rebind_changed_iterators(rebuild_target)
                return rebuild_target
        if iterator_snapshots:
            raise TypeError("set iterator state cannot be preserved")
        if is_frozen:
            working: set[Any] = set()
            set.update(working, value)
        else:
            working = value
        for original, rewritten, _rehash, _may_have_changed in changed_pairs:
            set.remove(working, original)
            set.add(working, rewritten)
        fallback_rewrites = {
            id(original): rewritten
            for original, rewritten, _rehash, _may_have_changed in changed_pairs
        }
        iterator_source = (
            value if not is_frozen else frozenset.__new__(type(value), working)
        )
        for iterator, remaining_items in iterator_snapshots:
            rewritten_remaining = tuple(
                (
                    rewritten,
                    hash(rewritten),
                )
                for item in remaining_items
                for rewritten in (fallback_rewrites.get(id(item), item),)
            )
            if not _rollback_rebind_set_iterator(
                iterator, iterator_source, rewritten_remaining
            ):
                raise TypeError("set iterator coupling unavailable")
        if not is_frozen:
            return value
        return iterator_source

    def replace_exact_tuple_identity_edges(
        root: Any,
        target: Any,
        replacement: Any,
    ) -> Dict[int, Any]:
        """Rebuild arbitrarily deep exact tuples without Python recursion."""

        rewritten: Dict[int, Any] = {}
        scheduled: Set[int] = set()
        stack: List[tuple[Any, bool]] = [(root, False)]
        while stack:
            current, ready = stack.pop()
            if current is target:
                rewritten[id(current)] = replacement
                continue
            if type(current) is not tuple:
                continue
            current_id = id(current)
            if ready:
                original_values = tuple.__iter__(current)
                rewritten_values = tuple(
                    replacement if item is target else rewritten.get(id(item), item)
                    for item in original_values
                )
                original_values = tuple(tuple.__iter__(current))
                if any(
                    original is not rewritten_value
                    for original, rewritten_value in zip(
                        original_values, rewritten_values
                    )
                ):
                    rewritten[current_id] = rewritten_values
                continue
            if current_id in scheduled:
                continue
            scheduled.add(current_id)
            stack.append((current, True))
            stack.extend(
                (item, False)
                for item in reversed(tuple(tuple.__iter__(current)))
                if item is target or type(item) is tuple
            )
        return rewritten

    identity_rewrite_depth = 0
    identity_rewrite_snapshots: Dict[int, List[tuple[Any, ...]]] = {}

    def replace_visible_identity_unchecked(
        root: Any,
        target: Any,
        replacement: Any,
        rewrites: Dict[int, Any],
    ) -> Any:
        """Replace one non-resettable copied node in the visible state graph."""

        replace_visible_identity = replace_visible_identity_unchecked
        if root is target:
            return replacement
        (
            simple_handled,
            simple_found_target,
            simple_result,
        ) = replace_simple_mutable_value_graph(
            root,
            target,
            replacement,
            lambda item: replace_visible_identity(
                item, target, replacement, rewrites
            ),
            lambda container: rewrites.setdefault(id(container), container),
        )
        if simple_handled:
            if simple_found_target:
                rewrites[id(target)] = replacement
            return simple_result
        if not rewrites:
            replace_mutable_identity_edges(root, target, replacement)
            tuple_rewrites = replace_exact_tuple_identity_edges(
                root, target, replacement
            )
            if tuple_rewrites:
                rewrites.update(tuple_rewrites)
                root = tuple_rewrites.get(id(root), root)
            if not graph_contains_identity(root, target):
                return root
        root_id = id(root)
        if root_id in rewrites:
            return rewrites[root_id]
        if is_rollback_leaf(root):
            return root
        rewrites[root_id] = root
        root_type = type(root)
        if raw_inherits(root, weakref.ReferenceType) and not raw_inherits(
            root, weakref.WeakMethod
        ):
            referent = raw_weakref_referent(root)
            callback = raw_weakref_callback(root)
            rewritten_callback = (
                replace_visible_identity(callback, target, replacement, rewrites)
                if callback is not None
                else None
            )
            if referent is not None:
                rewritten_referent = replace_visible_identity(
                    referent, target, replacement, rewrites
                )
                if (
                    rewritten_referent is not referent
                    or rewritten_callback is not callback
                ):
                    try:
                        rewritten_reference = rebuild_weak_reference(
                            root,
                            rewritten_referent,
                            rewritten_callback,
                            lambda item: replace_visible_identity(
                                item, target, replacement, rewrites
                            ),
                            lambda key: graph_contains_identity(key, target),
                        )
                    except TypeError:
                        return root
                    rewrites[root_id] = rewritten_reference
                    return rewritten_reference
        elif raw_inherits(root, weakref.WeakMethod):
            receiver, function, _method_type, _alive = raw_weakmethod_state(root)
            if receiver is not None and function is not None:
                rewritten_self = replace_visible_identity(
                    receiver, target, replacement, rewrites
                )
                rewritten_function = replace_visible_identity(
                    function, target, replacement, rewrites
                )
                original_callback = raw_weakmethod_user_callback(root)
                rewritten_callback = (
                    replace_visible_identity(
                        original_callback, target, replacement, rewrites
                    )
                    if original_callback is not None
                    else None
                )
                if (
                    rewritten_self is not receiver
                    or rewritten_function is not function
                    or rewritten_callback is not original_callback
                ):
                    try:
                        rewritten_method_reference = rebuild_weak_method(
                            root,
                            rewritten_self,
                            rewritten_function,
                            rewritten_callback,
                            lambda item: replace_visible_identity(
                                item, target, replacement, rewrites
                            ),
                            lambda key: graph_contains_identity(key, target),
                        )
                    except TypeError:
                        return root
                    rewrites[root_id] = rewritten_method_reference
                    return rewritten_method_reference
        elif (
            root_type in rollback_iterator_types
            or root_type in rollback_builtin_iteration_wrapper_types
        ):
            try:
                rewritten_iterator = rebuild_iterator_wrapper(
                    root,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                )
            except (AttributeError, TypeError, ValueError):
                return root
            rewrites[root_id] = rewritten_iterator
            return rewritten_iterator
        elif root_type in {types.BuiltinFunctionType, types.MethodWrapperType}:
            receiver = getattr(root, "__self__", None)
            if receiver is not None:
                rewritten_receiver = replace_visible_identity(
                    receiver, target, replacement, rewrites
                )
                if rewritten_receiver is not receiver:
                    rebound = rebind_builtin_callable(root, rewritten_receiver)
                    if rebound is _ROLLBACK_DEEPCOPY_MISSING:
                        return root
                    rewrites[root_id] = rebound
                    return rebound
        elif root_type is types.MappingProxyType:
            mappings = [
                referent
                for referent in gc.get_referents(root)
                if raw_inherits(referent, dict) or raw_inherits(referent, Mapping)
            ]
            if len(mappings) == 1:
                mapping = mappings[0]
                rewritten_mapping = replace_visible_identity(
                    mapping, target, replacement, rewrites
                )
                if rewritten_mapping is not mapping:
                    rewritten_proxy = types.MappingProxyType(rewritten_mapping)
                    rewrites[root_id] = rewritten_proxy
                    return rewritten_proxy
        elif root_type in rollback_operator_wrapper_types:
            original_args, original_keywords = rollback_operator_wrapper_state(root)
            rewritten_args = tuple(
                replace_visible_identity(item, target, replacement, rewrites)
                for item in original_args
            )
            rewritten_keywords = {
                key: replace_visible_identity(item, target, replacement, rewrites)
                for key, item in original_keywords.items()
            }
            if any(
                original is not rewritten
                for original, rewritten in zip(original_args, rewritten_args)
            ) or any(
                rewritten_keywords[key] is not item
                for key, item in original_keywords.items()
            ):
                rewritten_wrapper = root_type(*rewritten_args, **rewritten_keywords)
                rewrites[root_id] = rewritten_wrapper
                return rewritten_wrapper
        elif raw_inherits(root, super):
            original_super_values = raw_super_state(root)
            rewritten_super_values = tuple(
                replace_visible_identity(item, target, replacement, rewrites)
                for item in original_super_values
            )
            if any(
                original is not rewritten
                for original, rewritten in zip(
                    original_super_values, rewritten_super_values
                )
            ):
                try:
                    rewritten_super = rebuild_super_wrapper(
                        root,
                        rewritten_super_values[0],
                        rewritten_super_values[1],
                        lambda item: replace_visible_identity(
                            item, target, replacement, rewrites
                        ),
                        lambda key: graph_contains_identity(key, target),
                    )
                except TypeError:
                    return root
                rewrites[root_id] = rewritten_super
                return rewritten_super
        elif raw_inherits(root, types.GenericAlias):
            alias_origin, alias_args, _unpacked = raw_generic_alias_state(root)
            original_alias_values = (alias_origin, *alias_args)
            rewritten_alias_values = tuple(
                replace_visible_identity(item, target, replacement, rewrites)
                for item in original_alias_values
            )
            if any(
                original is not rewritten
                for original, rewritten in zip(
                    original_alias_values, rewritten_alias_values
                )
            ):
                rewritten_alias = rebuild_generic_alias(
                    root,
                    rewritten_alias_values[0],
                    rewritten_alias_values[1:],
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                rewrites[root_id] = rewritten_alias
                return rewritten_alias
        elif _BASE_EXCEPTION_GROUP_TYPE is not None and raw_inherits(
            root, _BASE_EXCEPTION_GROUP_TYPE
        ):
            original_exceptions = raw_class_namespace(_BASE_EXCEPTION_GROUP_TYPE)[
                "exceptions"
            ].__get__(root, root_type)
            rewritten_exceptions = tuple(
                replace_visible_identity(item, target, replacement, rewrites)
                for item in original_exceptions
            )
            if any(
                original is not rewritten
                for original, rewritten in zip(
                    original_exceptions, rewritten_exceptions
                )
            ):
                rewritten_group = rebuild_exact_exception_group(
                    root,
                    rewritten_exceptions,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                rewrites[root_id] = rewritten_group
                return rewritten_group
        elif raw_inherits(root, property):
            original_fget, original_fset, original_fdel, original_doc = (
                raw_property_state(root)
            )
            original_accessors = (
                original_fget,
                original_fset,
                original_fdel,
            )
            rewritten_accessors = tuple(
                replace_visible_identity(accessor, target, replacement, rewrites)
                if accessor is not None
                else None
                for accessor in original_accessors
            )
            rewritten_doc = (
                replace_visible_identity(original_doc, target, replacement, rewrites)
                if original_doc is not None
                else None
            )
            if (
                any(
                    original is not rewritten
                    for original, rewritten in zip(
                        original_accessors,
                        rewritten_accessors,
                    )
                )
                or rewritten_doc is not original_doc
            ):
                rewritten_property = property.__new__(type(root))
                property.__init__(
                    rewritten_property,
                    *rewritten_accessors,
                    doc=rewritten_doc,
                )
                rewrites[root_id] = rewritten_property
                copy_raw_instance_attributes(
                    root,
                    rewritten_property,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                for _slot_name, descriptor in declared_slot_descriptors(root):
                    try:
                        slot_value = descriptor.__get__(root, type(root))
                    except (AttributeError, TypeError):
                        continue
                    rewritten_slot_value = replace_visible_identity(
                        slot_value, target, replacement, rewrites
                    )
                    try:
                        descriptor.__set__(rewritten_property, rewritten_slot_value)
                    except (AttributeError, TypeError):
                        pass
                return rewritten_property
        elif raw_inherits(root, staticmethod) or raw_inherits(root, classmethod):
            original_function = raw_descriptor_function(root)
            rewritten_function = replace_visible_identity(
                original_function, target, replacement, rewrites
            )
            if rewritten_function is not original_function:
                descriptor_base = (
                    staticmethod if raw_inherits(root, staticmethod) else classmethod
                )
                rewritten_descriptor = descriptor_base.__new__(type(root))
                descriptor_base.__init__(rewritten_descriptor, rewritten_function)
                rewrites[root_id] = rewritten_descriptor
                copy_raw_instance_attributes(
                    root,
                    rewritten_descriptor,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                for _slot_name, descriptor in declared_slot_descriptors(root):
                    try:
                        slot_value = descriptor.__get__(root, type(root))
                    except (AttributeError, TypeError):
                        continue
                    rewritten_slot_value = replace_visible_identity(
                        slot_value, target, replacement, rewrites
                    )
                    try:
                        descriptor.__set__(rewritten_descriptor, rewritten_slot_value)
                    except (AttributeError, TypeError):
                        pass
                return rewritten_descriptor
        elif root_type is slice:
            original_slice_values = (root.start, root.stop, root.step)
            rewritten_slice_values = tuple(
                replace_visible_identity(item, target, replacement, rewrites)
                for item in original_slice_values
            )
            if any(
                original is not rewritten
                for original, rewritten in zip(
                    original_slice_values, rewritten_slice_values
                )
            ):
                rewritten_slice = slice(*rewritten_slice_values)
                rewrites[root_id] = rewritten_slice
                return rewritten_slice
        if raw_inherits(root, BaseException):
            for (
                name,
                descriptor,
                existed,
                item,
            ) in rollback_builtin_exception_descriptor_state(root):
                if not existed or name == "__traceback__":
                    continue
                rewritten_item = replace_visible_identity(
                    item, target, replacement, rewrites
                )
                if rewritten_item is not item or name == "__suppress_context__":
                    try:
                        descriptor.__set__(root, rewritten_item)
                    except (AttributeError, TypeError):
                        pass
        if raw_inherits(root, functools.partial):
            original_func, original_args, original_keywords = raw_partial_state(root)
            rewritten_func = replace_visible_identity(
                original_func, target, replacement, rewrites
            )
            rewritten_args = tuple(
                replace_visible_identity(value, target, replacement, rewrites)
                for value in original_args
            )
            rewritten_keywords = {
                key: replace_visible_identity(value, target, replacement, rewrites)
                for key, value in original_keywords.items()
            }
            if (
                rewritten_func is not original_func
                or any(
                    left is not right
                    for left, right in zip(original_args, rewritten_args)
                )
                or any(
                    rewritten_keywords[key] is not value
                    for key, value in original_keywords.items()
                )
            ):
                rewritten_partial = functools.partial.__new__(
                    type(root),
                    rewritten_func,
                    *rewritten_args,
                    **rewritten_keywords,
                )
                rewrites[root_id] = rewritten_partial
                copy_raw_instance_attributes(
                    root,
                    rewritten_partial,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                for _slot_name, descriptor in declared_slot_descriptors(root):
                    try:
                        slot_value = descriptor.__get__(root, type(root))
                    except (AttributeError, TypeError):
                        continue
                    rewritten_slot_value = replace_visible_identity(
                        slot_value, target, replacement, rewrites
                    )
                    try:
                        descriptor.__set__(rewritten_partial, rewritten_slot_value)
                    except (AttributeError, TypeError):
                        pass
                return rewritten_partial
        if root_type is types.MethodType:
            rewritten_self = replace_visible_identity(
                root.__self__, target, replacement, rewrites
            )
            if rewritten_self is not root.__self__:
                rewritten_method = type(root)(root.__func__, rewritten_self)
                rewrites[root_id] = rewritten_method
                return rewritten_method
        if root_type is types.FunctionType:
            root.__defaults__ = (
                tuple(
                    replace_visible_identity(value, target, replacement, rewrites)
                    for value in (root.__defaults__ or ())
                )
                or None
            )
            rewritten_kwdefaults = {
                key: replace_visible_identity(value, target, replacement, rewrites)
                for key, value in dict(root.__kwdefaults__ or {}).items()
            }
            if root.__kwdefaults__ is not None:
                root.__kwdefaults__.clear()
                root.__kwdefaults__.update(rewritten_kwdefaults)
            rewritten_annotations = {
                key: replace_visible_identity(value, target, replacement, rewrites)
                for key, value in dict(root.__annotations__).items()
            }
            root.__annotations__.clear()
            root.__annotations__.update(rewritten_annotations)
            for cell in root.__closure__ or ():
                try:
                    cell_value = cell.cell_contents
                except ValueError:
                    continue
                rewritten_value = replace_visible_identity(
                    cell_value, target, replacement, rewrites
                )
                if rewritten_value is not cell_value:
                    cell.cell_contents = rewritten_value
        if root_type is types.CellType:
            try:
                cell_value = root.cell_contents
            except ValueError:
                cell_value = _ROLLBACK_DEEPCOPY_MISSING
            if cell_value is not _ROLLBACK_DEEPCOPY_MISSING:
                rewritten_value = replace_visible_identity(
                    cell_value, target, replacement, rewrites
                )
                if rewritten_value is not cell_value:
                    root.cell_contents = rewritten_value
        if raw_inherits(root, dict):
            rewritten_mapping = rewrite_dictionary_edges(
                root,
                lambda item: replace_visible_identity(
                    item, target, replacement, rewrites
                ),
                lambda key: hash_requires_recalculation(
                    key,
                    lambda item: graph_contains_identity(item, target),
                ),
                lambda key: graph_contains_identity(key, target),
            )
            if rewritten_mapping is not root:
                rewrites[root_id] = rewritten_mapping
                return rewritten_mapping
            if raw_inherits(root, collections.defaultdict):
                original_factory = raw_defaultdict_factory(root)
                rewritten_factory = replace_visible_identity(
                    original_factory, target, replacement, rewrites
                )
                if rewritten_factory is not original_factory:
                    collections.defaultdict.default_factory.__set__(
                        root, rewritten_factory
                    )
        elif raw_inherits(root, list):
            for index, value in enumerate(list(list.__iter__(root))):
                root[index] = replace_visible_identity(
                    value, target, replacement, rewrites
                )
        elif raw_inherits(root, tuple):
            values = tuple(
                replace_visible_identity(value, target, replacement, rewrites)
                for value in tuple.__iter__(root)
            )
            if any(left is not right for left, right in zip(root, values)):
                if type(root) is tuple:
                    rewritten_tuple = values
                else:
                    rewritten_tuple = tuple.__new__(type(root), values)
                    copy_raw_instance_attributes(
                        root,
                        rewritten_tuple,
                        lambda item: replace_visible_identity(
                            item, target, replacement, rewrites
                        ),
                        lambda key: graph_contains_identity(key, target),
                    )
                rewrites[root_id] = rewritten_tuple
                return rewritten_tuple
        elif raw_inherits(root, set):
            rewrite_hash_container_edges(
                root,
                lambda item: replace_visible_identity(
                    item, target, replacement, rewrites
                ),
                lambda item: hash_requires_recalculation(
                    item,
                    lambda candidate: graph_contains_identity(candidate, target),
                ),
                lambda item: graph_contains_identity(item, target),
            )
        elif raw_inherits(root, frozenset):
            rewritten_frozenset = rewrite_hash_container_edges(
                root,
                lambda item: replace_visible_identity(
                    item, target, replacement, rewrites
                ),
                lambda item: hash_requires_recalculation(
                    item,
                    lambda candidate: graph_contains_identity(candidate, target),
                ),
                lambda item: graph_contains_identity(item, target),
            )
            if rewritten_frozenset is not root:
                copy_raw_instance_attributes(
                    root,
                    rewritten_frozenset,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
                rewrites[root_id] = rewritten_frozenset
                return rewritten_frozenset
        elif raw_inherits(root, collections.deque):
            original_values = list(collections.deque.__iter__(root))
            rewritten_values = [
                replace_visible_identity(value, target, replacement, rewrites)
                for value in original_values
            ]
            for index, (original_value, rewritten_value) in enumerate(
                zip(original_values, rewritten_values)
            ):
                if original_value is not rewritten_value:
                    collections.deque.__setitem__(root, index, rewritten_value)
        _dict_descriptor, attributes = raw_instance_dict(root)
        if attributes is not None:
            rewrite_dictionary_edges(
                attributes,
                lambda item: replace_visible_identity(
                    item, target, replacement, rewrites
                ),
                lambda key: graph_contains_identity(key, target),
            )
        elif any(
            "__dict__" in raw_class_namespace(owner)
            and not inspect.isgetsetdescriptor(raw_class_namespace(owner)["__dict__"])
            for owner in raw_value_mro(root)
        ):
            for hidden_attributes in gc.get_referents(root):
                if type(hidden_attributes) is not dict:
                    continue
                rewrite_dictionary_edges(
                    hidden_attributes,
                    lambda item: replace_visible_identity(
                        item, target, replacement, rewrites
                    ),
                    lambda key: graph_contains_identity(key, target),
                )
        if raw_inherits(root, type) and id(root) not in _BUILTIN_TYPE_IDENTITY_IDS:
            for name, value in raw_class_namespace(root).items():
                rewritten_value = replace_visible_identity(
                    value, target, replacement, rewrites
                )
                if rewritten_value is not value:
                    try:
                        type.__setattr__(root, name, rewritten_value)
                    except (AttributeError, TypeError):
                        pass
        for _slot_name, descriptor in declared_slot_descriptors(root):
            try:
                value = descriptor.__get__(root, type(root))
            except (AttributeError, TypeError):
                continue
            rewritten = replace_visible_identity(value, target, replacement, rewrites)
            if rewritten is not value:
                try:
                    descriptor.__set__(root, rewritten)
                except (AttributeError, TypeError):
                    pass
        return root

    def is_simple_value_leaf(value: Any) -> bool:
        return value is None or type(value) in {
            bool,
            int,
            float,
            complex,
            str,
            bytes,
        }

    def replace_simple_mutable_value_graph(
        root: Any,
        target: Any,
        replacement: Any,
        transform_boundary: Optional[Callable[[Any], Any]] = None,
        register_container: Optional[Callable[[Any], None]] = None,
    ) -> tuple[bool, bool, Any]:
        """Replace one identity in deep exact dict/list value graphs iteratively."""

        if root is target:
            return True, True, replacement
        if type(root) not in {dict, list}:
            return False, False, root
        found_target = False
        seen: Set[int] = set()
        seen_containers: List[Any] = []
        stack: List[tuple[Any, Any, Any, Optional[int]]] = [
            (root, None, None, None)
        ]
        dictionary_updates: List[tuple[dict[Any, Any], Any, Any, int]] = []
        list_updates: List[tuple[list[Any], int, Any]] = []
        boundary_updates: List[tuple[Any, Any, Any, Optional[int]]] = []
        while stack:
            current, parent, parent_locator, parent_key_hash = stack.pop()
            current_id = id(current)
            if current_id in seen:
                continue
            seen.add(current_id)
            if type(current) is dict:
                entries = _rollback_dict_entries_with_hashes(current)
                if entries is None:
                    return False, False, root
                if any(
                    key is target or graph_contains_identity(key, target)
                    for key, _item, _key_hash in entries
                ):
                    if parent is None or transform_boundary is None:
                        return False, False, root
                    boundary_updates.append(
                        (parent, parent_locator, current, parent_key_hash)
                    )
                    continue
                seen_containers.append(current)
                for key, item, key_hash in entries:
                    if item is target:
                        found_target = True
                        dictionary_updates.append(
                            (current, key, replacement, key_hash)
                        )
                    elif type(item) in {dict, list}:
                        stack.append((item, current, key, key_hash))
                    elif graph_contains_identity(item, target):
                        if transform_boundary is None:
                            return False, False, root
                        boundary_updates.append((current, key, item, key_hash))
                    else:
                        continue
                continue
            if type(current) is list:
                seen_containers.append(current)
                for index, item in enumerate(list.__iter__(current)):
                    if item is target:
                        found_target = True
                        list_updates.append((current, index, replacement))
                    elif type(item) in {dict, list}:
                        stack.append((item, current, index, None))
                    elif graph_contains_identity(item, target):
                        if transform_boundary is None:
                            return False, False, root
                        boundary_updates.append((current, index, item, None))
                    else:
                        continue
                continue
        if register_container is not None:
            for container in seen_containers:
                register_container(container)
        for container, locator, item, key_hash in boundary_updates:
            rewritten_item = transform_boundary(item)  # type: ignore[misc]
            if rewritten_item is item and graph_contains_identity(item, target):
                return False, False, root
            found_target = True
            if type(container) is dict:
                dictionary_updates.append(
                    (container, locator, rewritten_item, int(key_hash))
                )
            else:
                list_updates.append((container, int(locator), rewritten_item))
        for mapping, key, rewritten_item, key_hash in dictionary_updates:
            if not _rollback_dict_setitem_known_hash(
                mapping, key, rewritten_item, key_hash
            ):
                raise TypeError("dictionary known-hash replacement unavailable")
        for values, index, rewritten_item in list_updates:
            list.__setitem__(values, index, rewritten_item)
        return True, found_target, root

    def replace_visible_identity(
        root: Any,
        target: Any,
        replacement: Any,
        rewrites: Dict[int, Any],
    ) -> Any:
        """Replace one identity under a single outer graph transaction."""

        nonlocal identity_rewrite_depth
        if root is target:
            return replacement
        outermost = identity_rewrite_depth == 0
        transaction_key = id(rewrites)
        if outermost:
            snapshots = snapshot_completed_mutables((root,))
            existing = identity_rewrite_snapshots.setdefault(transaction_key, [])
            existing_ids = {id(snapshot[0]) for snapshot in existing}
            existing.extend(
                snapshot
                for snapshot in snapshots
                if id(snapshot[0]) not in existing_ids
            )
            (
                simple_handled,
                simple_found_target,
                simple_result,
            ) = replace_simple_mutable_value_graph(root, target, replacement)
            if simple_handled:
                if simple_found_target:
                    rewrites[id(target)] = replacement
                return simple_result
        identity_rewrite_depth += 1
        try:
            return replace_visible_identity_unchecked(
                root, target, replacement, rewrites
            )
        except BaseException:
            if outermost:
                snapshots = identity_rewrite_snapshots.pop(transaction_key, ())
                restore_completed_mutables(snapshots, force_all=True)
            raise
        finally:
            identity_rewrite_depth -= 1

    def finalize_simple_mutable_value_graph(
        root: Any,
        rewrites: Mapping[int, Any],
        transform_boundary: Optional[Callable[[Any], Any]] = None,
        register_container: Optional[Callable[[Any], None]] = None,
    ) -> tuple[bool, Any]:
        """Resolve exact dict/list value edges without Python recursion."""

        resolved_root = rewrites.get(id(root), root)
        if type(resolved_root) not in {dict, list}:
            return False, resolved_root
        pending_rewrite_ids = {
            original_id
            for original_id, rewritten in rewrites.items()
            if original_id != id(rewritten)
        }
        seen: Set[int] = set()
        seen_containers: List[Any] = []
        stack: List[tuple[Any, Any, Any, Optional[int]]] = [
            (resolved_root, None, None, None)
        ]
        dictionary_updates: List[tuple[dict[Any, Any], Any, Any, int]] = []
        list_updates: List[tuple[list[Any], int, Any]] = []
        boundary_updates: List[tuple[Any, Any, Any, Optional[int]]] = []
        while stack:
            current, parent, parent_locator, parent_key_hash = stack.pop()
            current_id = id(current)
            if current_id in seen:
                continue
            seen.add(current_id)
            if type(current) is dict:
                entries = _rollback_dict_entries_with_hashes(current)
                if entries is None:
                    return False, resolved_root
                if any(
                    pending_rewrite_ids.intersection(graph_identity_ids(key))
                    for key, _item, _key_hash in entries
                ):
                    if parent is None or transform_boundary is None:
                        return False, resolved_root
                    boundary_updates.append(
                        (parent, parent_locator, current, parent_key_hash)
                    )
                    continue
                seen_containers.append(current)
                for key, item, key_hash in entries:
                    rewritten_item = rewrites.get(id(item), item)
                    if rewritten_item is not item:
                        dictionary_updates.append(
                            (current, key, rewritten_item, key_hash)
                        )
                    elif type(item) in {dict, list}:
                        stack.append((item, current, key, key_hash))
                    elif pending_rewrite_ids.intersection(
                        graph_identity_ids(item)
                    ):
                        if transform_boundary is None:
                            return False, resolved_root
                        boundary_updates.append((current, key, item, key_hash))
                    else:
                        continue
                continue
            if type(current) is list:
                seen_containers.append(current)
                for index, item in enumerate(list.__iter__(current)):
                    rewritten_item = rewrites.get(id(item), item)
                    if rewritten_item is not item:
                        list_updates.append((current, index, rewritten_item))
                    elif type(item) in {dict, list}:
                        stack.append((item, current, index, None))
                    elif pending_rewrite_ids.intersection(
                        graph_identity_ids(item)
                    ):
                        if transform_boundary is None:
                            return False, resolved_root
                        boundary_updates.append((current, index, item, None))
                    else:
                        continue
                continue
        if register_container is not None:
            for container in seen_containers:
                register_container(container)
        for container, locator, item, key_hash in boundary_updates:
            rewritten_item = transform_boundary(item)  # type: ignore[misc]
            if pending_rewrite_ids.intersection(graph_identity_ids(rewritten_item)):
                return False, resolved_root
            if type(container) is dict:
                dictionary_updates.append(
                    (container, locator, rewritten_item, int(key_hash))
                )
            else:
                list_updates.append((container, int(locator), rewritten_item))
        for mapping, key, rewritten_item, key_hash in dictionary_updates:
            if not _rollback_dict_setitem_known_hash(
                mapping, key, rewritten_item, key_hash
            ):
                raise TypeError("dictionary known-hash finalization unavailable")
        for values, index, rewritten_item in list_updates:
            list.__setitem__(values, index, rewritten_item)
        return True, resolved_root

    def finalize_visible_identity_rewrites_unchecked(
        root: Any,
        rewrites: Mapping[int, Any],
    ) -> Any:
        """Resolve immutable placeholders left by cyclic graph rewriting."""

        if not rewrites:
            return root
        resolved_root = rewrites.get(id(root), root)
        if not set(rewrites).intersection(graph_identity_ids(resolved_root)):
            return resolved_root
        finalized: Dict[int, Any] = {}
        pending_rewrite_ids = {
            original_id
            for original_id, rewritten in rewrites.items()
            if original_id != id(rewritten)
        }

        def key_contains_pending_rewrite(value: Any) -> bool:
            return bool(pending_rewrite_ids.intersection(graph_identity_ids(value)))

        def resolve(value: Any) -> Any:
            return rewrites.get(id(value), value)

        def finalize(value: Any) -> Any:
            current = resolve(value)
            simple_handled, simple_result = finalize_simple_mutable_value_graph(
                current,
                rewrites,
                finalize,
                lambda container: finalized.setdefault(id(container), container),
            )
            if simple_handled:
                return simple_result
            current_id = id(current)
            if current_id in finalized:
                return finalized[current_id]
            if is_rollback_leaf(current):
                return current
            finalized[current_id] = current

            current_type = type(current)
            if raw_inherits(current, weakref.ReferenceType) and not raw_inherits(
                current, weakref.WeakMethod
            ):
                referent = raw_weakref_referent(current)
                callback = raw_weakref_callback(current)
                rewritten_callback = (
                    finalize(callback) if callback is not None else None
                )
                if referent is not None:
                    rewritten_referent = finalize(referent)
                    if (
                        rewritten_referent is not referent
                        or rewritten_callback is not callback
                    ):
                        try:
                            rewritten_reference = rebuild_weak_reference(
                                current,
                                rewritten_referent,
                                rewritten_callback,
                                finalize,
                                key_contains_pending_rewrite,
                            )
                        except TypeError:
                            return current
                        finalized[current_id] = rewritten_reference
                        return rewritten_reference
            elif raw_inherits(current, weakref.WeakMethod):
                receiver, function, _method_type, _alive = raw_weakmethod_state(current)
                if receiver is not None and function is not None:
                    rewritten_self = finalize(receiver)
                    rewritten_function = finalize(function)
                    original_callback = raw_weakmethod_user_callback(current)
                    rewritten_callback = (
                        finalize(original_callback)
                        if original_callback is not None
                        else None
                    )
                    if (
                        rewritten_self is not receiver
                        or rewritten_function is not function
                        or rewritten_callback is not original_callback
                    ):
                        try:
                            rewritten_method_reference = rebuild_weak_method(
                                current,
                                rewritten_self,
                                rewritten_function,
                                rewritten_callback,
                                finalize,
                                key_contains_pending_rewrite,
                            )
                        except TypeError:
                            return current
                        finalized[current_id] = rewritten_method_reference
                        return rewritten_method_reference
            elif (
                current_type in rollback_iterator_types
                or current_type in rollback_builtin_iteration_wrapper_types
            ):
                try:
                    rewritten_iterator = rebuild_iterator_wrapper(current, finalize)
                except (AttributeError, TypeError, ValueError):
                    return current
                finalized[current_id] = rewritten_iterator
                return rewritten_iterator
            elif current_type in {
                types.BuiltinFunctionType,
                types.MethodWrapperType,
            }:
                receiver = getattr(current, "__self__", None)
                if receiver is not None:
                    rewritten_receiver = finalize(receiver)
                    if rewritten_receiver is not receiver:
                        rebound = rebind_builtin_callable(current, rewritten_receiver)
                        if rebound is _ROLLBACK_DEEPCOPY_MISSING:
                            return current
                        finalized[current_id] = rebound
                        return rebound
            elif current_type is types.MappingProxyType:
                mappings = [
                    referent
                    for referent in gc.get_referents(current)
                    if raw_inherits(referent, dict) or raw_inherits(referent, Mapping)
                ]
                if len(mappings) == 1:
                    mapping = mappings[0]
                    rewritten_mapping = finalize(mapping)
                    if rewritten_mapping is not mapping:
                        rewritten_proxy = types.MappingProxyType(rewritten_mapping)
                        finalized[current_id] = rewritten_proxy
                        return rewritten_proxy
            elif current_type in rollback_operator_wrapper_types:
                original_args, original_keywords = rollback_operator_wrapper_state(
                    current
                )
                rewritten_args = tuple(finalize(item) for item in original_args)
                rewritten_keywords = {
                    key: finalize(item) for key, item in original_keywords.items()
                }
                if any(
                    original is not rewritten
                    for original, rewritten in zip(original_args, rewritten_args)
                ) or any(
                    rewritten_keywords[key] is not item
                    for key, item in original_keywords.items()
                ):
                    rewritten_wrapper = current_type(
                        *rewritten_args, **rewritten_keywords
                    )
                    finalized[current_id] = rewritten_wrapper
                    return rewritten_wrapper
            elif raw_inherits(current, super):
                original_super_values = raw_super_state(current)
                rewritten_super_values = tuple(
                    finalize(item) for item in original_super_values
                )
                if any(
                    original is not rewritten
                    for original, rewritten in zip(
                        original_super_values, rewritten_super_values
                    )
                ):
                    try:
                        rewritten_super = rebuild_super_wrapper(
                            current,
                            rewritten_super_values[0],
                            rewritten_super_values[1],
                            finalize,
                            key_contains_pending_rewrite,
                        )
                    except TypeError:
                        return current
                    finalized[current_id] = rewritten_super
                    return rewritten_super
            elif raw_inherits(current, types.GenericAlias):
                alias_origin, alias_args, _unpacked = raw_generic_alias_state(current)
                original_alias_values = (alias_origin, *alias_args)
                rewritten_alias_values = tuple(
                    finalize(item) for item in original_alias_values
                )
                if any(
                    original is not rewritten
                    for original, rewritten in zip(
                        original_alias_values, rewritten_alias_values
                    )
                ):
                    rewritten_alias = rebuild_generic_alias(
                        current,
                        rewritten_alias_values[0],
                        rewritten_alias_values[1:],
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    finalized[current_id] = rewritten_alias
                    return rewritten_alias
            elif _BASE_EXCEPTION_GROUP_TYPE is not None and raw_inherits(
                current, _BASE_EXCEPTION_GROUP_TYPE
            ):
                original_exceptions = raw_class_namespace(_BASE_EXCEPTION_GROUP_TYPE)[
                    "exceptions"
                ].__get__(current, current_type)
                rewritten_exceptions = tuple(
                    finalize(item) for item in original_exceptions
                )
                if any(
                    original is not rewritten
                    for original, rewritten in zip(
                        original_exceptions, rewritten_exceptions
                    )
                ):
                    rewritten_group = rebuild_exact_exception_group(
                        current,
                        rewritten_exceptions,
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    finalized[current_id] = rewritten_group
                    return rewritten_group
            elif raw_inherits(current, property):
                original_fget, original_fset, original_fdel, original_doc = (
                    raw_property_state(current)
                )
                original_accessors = (
                    original_fget,
                    original_fset,
                    original_fdel,
                )
                rewritten_accessors = tuple(
                    finalize(accessor) if accessor is not None else None
                    for accessor in original_accessors
                )
                rewritten_doc = (
                    finalize(original_doc) if original_doc is not None else None
                )
                if (
                    any(
                        original is not rewritten
                        for original, rewritten in zip(
                            original_accessors, rewritten_accessors
                        )
                    )
                    or rewritten_doc is not original_doc
                ):
                    rewritten_property = property.__new__(type(current))
                    property.__init__(
                        rewritten_property,
                        *rewritten_accessors,
                        doc=rewritten_doc,
                    )
                    finalized[current_id] = rewritten_property
                    copy_raw_instance_attributes(
                        current,
                        rewritten_property,
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    for _slot_name, descriptor in declared_slot_descriptors(current):
                        try:
                            slot_value = descriptor.__get__(current, type(current))
                        except (AttributeError, TypeError):
                            continue
                        try:
                            descriptor.__set__(rewritten_property, finalize(slot_value))
                        except (AttributeError, TypeError):
                            pass
                    return rewritten_property
            elif raw_inherits(current, staticmethod) or raw_inherits(
                current, classmethod
            ):
                original_function = raw_descriptor_function(current)
                rewritten_function = finalize(original_function)
                if rewritten_function is not original_function:
                    descriptor_base = (
                        staticmethod
                        if raw_inherits(current, staticmethod)
                        else classmethod
                    )
                    rewritten_descriptor = descriptor_base.__new__(type(current))
                    descriptor_base.__init__(rewritten_descriptor, rewritten_function)
                    finalized[current_id] = rewritten_descriptor
                    copy_raw_instance_attributes(
                        current,
                        rewritten_descriptor,
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    for _slot_name, descriptor in declared_slot_descriptors(current):
                        try:
                            slot_value = descriptor.__get__(current, type(current))
                        except (AttributeError, TypeError):
                            continue
                        try:
                            descriptor.__set__(
                                rewritten_descriptor, finalize(slot_value)
                            )
                        except (AttributeError, TypeError):
                            pass
                    return rewritten_descriptor
            elif current_type is slice:
                original_slice_values = (
                    current.start,
                    current.stop,
                    current.step,
                )
                rewritten_slice_values = tuple(
                    finalize(item) for item in original_slice_values
                )
                if any(
                    original is not rewritten
                    for original, rewritten in zip(
                        original_slice_values, rewritten_slice_values
                    )
                ):
                    rewritten_slice = slice(*rewritten_slice_values)
                    finalized[current_id] = rewritten_slice
                    return rewritten_slice
            if raw_inherits(current, functools.partial):
                original_func, original_args, original_keywords = raw_partial_state(
                    current
                )
                rewritten_func = finalize(original_func)
                rewritten_args = tuple(finalize(item) for item in original_args)
                rewritten_keywords = {
                    key: finalize(item) for key, item in original_keywords.items()
                }
                if (
                    rewritten_func is not original_func
                    or any(
                        left is not right
                        for left, right in zip(original_args, rewritten_args)
                    )
                    or any(
                        rewritten_keywords[key] is not item
                        for key, item in original_keywords.items()
                    )
                ):
                    original_partial = current
                    rewritten_partial = functools.partial.__new__(
                        type(current),
                        rewritten_func,
                        *rewritten_args,
                        **rewritten_keywords,
                    )
                    finalized[current_id] = rewritten_partial
                    copy_raw_instance_attributes(
                        original_partial,
                        rewritten_partial,
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    for _slot_name, descriptor in declared_slot_descriptors(
                        original_partial
                    ):
                        try:
                            slot_value = descriptor.__get__(
                                original_partial, type(original_partial)
                            )
                        except (AttributeError, TypeError):
                            continue
                        try:
                            descriptor.__set__(rewritten_partial, finalize(slot_value))
                        except (AttributeError, TypeError):
                            pass
                    current = rewritten_partial
            elif current_type is types.MethodType:
                rewritten_self = finalize(current.__self__)
                if rewritten_self is not current.__self__:
                    rewritten_method = type(current)(current.__func__, rewritten_self)
                    finalized[current_id] = rewritten_method
                    return rewritten_method
            elif raw_inherits(current, tuple):
                original_values = tuple(tuple.__iter__(current))
                rewritten_values = tuple(finalize(item) for item in original_values)
                if any(
                    left is not right
                    for left, right in zip(original_values, rewritten_values)
                ):
                    if type(current) is tuple:
                        rewritten_tuple = rewritten_values
                    else:
                        rewritten_tuple = tuple.__new__(type(current), rewritten_values)
                        copy_raw_instance_attributes(
                            current,
                            rewritten_tuple,
                            finalize,
                            key_contains_pending_rewrite,
                        )
                    finalized[current_id] = rewritten_tuple
                    return rewritten_tuple
            elif raw_inherits(current, frozenset):
                rewritten_frozenset = rewrite_hash_container_edges(
                    current,
                    finalize,
                    lambda item: hash_requires_recalculation(
                        item, key_contains_pending_rewrite
                    ),
                    key_contains_pending_rewrite,
                )
                if rewritten_frozenset is not current:
                    copy_raw_instance_attributes(
                        current,
                        rewritten_frozenset,
                        finalize,
                        key_contains_pending_rewrite,
                    )
                    finalized[current_id] = rewritten_frozenset
                    return rewritten_frozenset
            if raw_inherits(current, BaseException):
                for (
                    name,
                    descriptor,
                    existed,
                    item,
                ) in rollback_builtin_exception_descriptor_state(current):
                    if not existed or name == "__traceback__":
                        continue
                    rewritten_item = finalize(item)
                    if rewritten_item is not item or name == "__suppress_context__":
                        try:
                            descriptor.__set__(current, rewritten_item)
                        except (AttributeError, TypeError):
                            pass

            if current_type is types.FunctionType:
                current.__defaults__ = (
                    tuple(finalize(item) for item in (current.__defaults__ or ()))
                    or None
                )
                if current.__kwdefaults__ is not None:
                    current.__kwdefaults__.update(
                        {
                            key: finalize(item)
                            for key, item in dict(current.__kwdefaults__).items()
                        }
                    )
                current.__annotations__.update(
                    {
                        key: finalize(item)
                        for key, item in dict(current.__annotations__).items()
                    }
                )
                for cell in current.__closure__ or ():
                    finalize(cell)
            if current_type is types.CellType:
                try:
                    cell_value = current.cell_contents
                except ValueError:
                    pass
                else:
                    rewritten_value = finalize(cell_value)
                    if rewritten_value is not cell_value:
                        current.cell_contents = rewritten_value
            if raw_inherits(current, dict):
                rewritten_mapping = rewrite_dictionary_edges(
                    current,
                    finalize,
                    lambda key: hash_requires_recalculation(
                        key, key_contains_pending_rewrite
                    ),
                    key_contains_pending_rewrite,
                )
                if rewritten_mapping is not current:
                    finalized[current_id] = rewritten_mapping
                    return rewritten_mapping
                if raw_inherits(current, collections.defaultdict):
                    original_factory = raw_defaultdict_factory(current)
                    rewritten_factory = finalize(original_factory)
                    if rewritten_factory is not original_factory:
                        collections.defaultdict.default_factory.__set__(
                            current, rewritten_factory
                        )
            elif raw_inherits(current, list):
                for index, item in enumerate(list(list.__iter__(current))):
                    current[index] = finalize(item)
            elif raw_inherits(current, set):
                rewrite_hash_container_edges(
                    current,
                    finalize,
                    lambda item: hash_requires_recalculation(
                        item, key_contains_pending_rewrite
                    ),
                    key_contains_pending_rewrite,
                )
            elif raw_inherits(current, collections.deque):
                original_values = list(collections.deque.__iter__(current))
                rewritten_values = [finalize(item) for item in original_values]
                for index, (original_value, rewritten_value) in enumerate(
                    zip(original_values, rewritten_values)
                ):
                    if original_value is not rewritten_value:
                        collections.deque.__setitem__(current, index, rewritten_value)

            _descriptor, attributes = raw_instance_dict(current)
            if attributes is not None:
                rewrite_dictionary_edges(
                    attributes,
                    finalize,
                    key_contains_pending_rewrite,
                )
            elif any(
                "__dict__" in raw_class_namespace(owner)
                and not inspect.isgetsetdescriptor(
                    raw_class_namespace(owner)["__dict__"]
                )
                for owner in raw_value_mro(current)
            ):
                for hidden_attributes in gc.get_referents(current):
                    if type(hidden_attributes) is not dict:
                        continue
                    rewrite_dictionary_edges(
                        hidden_attributes,
                        finalize,
                        key_contains_pending_rewrite,
                    )
            if (
                raw_inherits(current, type)
                and id(current) not in _BUILTIN_TYPE_IDENTITY_IDS
            ):
                for name, item in raw_class_namespace(current).items():
                    rewritten_item = finalize(item)
                    if rewritten_item is not item:
                        try:
                            type.__setattr__(current, name, rewritten_item)
                        except (AttributeError, TypeError):
                            pass
            for _slot_name, descriptor in declared_slot_descriptors(current):
                try:
                    item = descriptor.__get__(current, type(current))
                except (AttributeError, TypeError):
                    continue
                rewritten_item = finalize(item)
                if rewritten_item is not item:
                    try:
                        descriptor.__set__(current, rewritten_item)
                    except (AttributeError, TypeError):
                        pass
            return current

        return finalize(root)

    def finalize_visible_identity_rewrites(
        root: Any,
        rewrites: Mapping[int, Any],
    ) -> Any:
        """Finalize one identity rewrite and commit or restore its graph."""

        transaction_key = id(rewrites)
        root_snapshots = snapshot_completed_mutables((root,))
        snapshots = identity_rewrite_snapshots.pop(transaction_key, [])
        existing_ids = {id(snapshot[0]) for snapshot in snapshots}
        snapshots.extend(
            snapshot
            for snapshot in root_snapshots
            if id(snapshot[0]) not in existing_ids
        )
        try:
            return finalize_visible_identity_rewrites_unchecked(root, rewrites)
        except BaseException:
            restore_completed_mutables(snapshots, force_all=True)
            raise

    def restore_completed_mutables(
        snapshots: Sequence[tuple[Any, ...]], *, force_all: bool = False
    ) -> None:
        if not snapshots:
            return
        snapshot_by_id = {id(snapshot[0]): snapshot for snapshot in snapshots}
        retained_ids = set(snapshot_by_id) if force_all else set()
        if not force_all:
            visible_roots = (
                *completed_memo.values(),
                *active_memo.values(),
                *copied.values(),
            )
            visible_ids = graph_identity_ids(visible_roots)
            retained_ids.update(set(snapshot_by_id).intersection(visible_ids))
            pending_snapshots = [snapshot_by_id[item_id] for item_id in retained_ids]
            inspected_snapshot_ids: Set[int] = set()
            seen_dependency_values: Set[int] = set()
            while pending_snapshots:
                retained_snapshot = pending_snapshots.pop()
                retained_snapshot_id = id(retained_snapshot[0])
                if retained_snapshot_id in inspected_snapshot_ids:
                    continue
                inspected_snapshot_ids.add(retained_snapshot_id)
                pending_values = list(retained_snapshot[1:])
                while pending_values:
                    current = pending_values.pop()
                    current_id = id(current)
                    if current_id in seen_dependency_values:
                        continue
                    seen_dependency_values.add(current_id)
                    dependency = snapshot_by_id.get(current_id)
                    if dependency is not None and current_id not in retained_ids:
                        retained_ids.add(current_id)
                        pending_snapshots.append(dependency)
                    if not is_rollback_leaf(current):
                        pending_values.extend(rollback_graph_referents(current))
        snapshots = tuple(
            snapshot for snapshot in snapshots if id(snapshot[0]) in retained_ids
        )
        replacements: List[tuple[Any, Any]] = []
        # A failed hook may release a view and then resize its exporter. Restore
        # exporters first so exact view reconstruction sees the original
        # geometry; identity rewrites still happen only after every restore.
        ordered_snapshots = sorted(
            snapshots,
            key=lambda snapshot: snapshot[1] == "memoryview",
        )
        for (
            current,
            container_kind,
            container_state,
            attribute_descriptor,
            attribute_state,
            slot_state,
        ) in ordered_snapshots:
            attribute_restore_target = current
            prior_replacement = restored_snapshot_replacements.get(id(current))
            if prior_replacement is not None and prior_replacement[0] is current:
                replacement = prior_replacement[1]
                seen_replacements: Set[int] = set()
                while id(replacement) not in seen_replacements:
                    seen_replacements.add(id(replacement))
                    next_replacement = restored_snapshot_replacements.get(
                        id(replacement)
                    )
                    if (
                        next_replacement is None
                        or next_replacement[0] is not replacement
                    ):
                        break
                    replacement = next_replacement[1]
                replacements.append((current, replacement))
                continue
            try:
                if container_kind == "exception":
                    for (
                        _name,
                        descriptor,
                        existed,
                        field_value,
                    ) in container_state:
                        try:
                            if existed:
                                descriptor.__set__(current, field_value)
                            else:
                                descriptor.__delete__(current)
                        except (AttributeError, TypeError):
                            if not rollback_descriptor_state_is_current(
                                current,
                                descriptor,
                                existed,
                                field_value,
                            ):
                                raise
                elif container_kind == "dict":
                    saved_mapping, saved_table = container_state
                    current_entries = _rollback_dict_entries_with_hashes(current)
                    saved_entries = _rollback_dict_entries_with_hashes(saved_mapping)
                    state_matches = bool(
                        current_entries is not None
                        and saved_entries is not None
                        and len(current_entries) == len(saved_entries)
                        and all(
                            current_key is saved_key
                            and current_item is saved_item
                            and current_hash == saved_hash
                            for (
                                current_key,
                                current_item,
                                current_hash,
                            ), (
                                saved_key,
                                saved_item,
                                saved_hash,
                            ) in zip(current_entries, saved_entries)
                        )
                    )
                    state_matches = state_matches and (
                        _rollback_dict_table_snapshots_match(
                            _rollback_dict_table_snapshot(current), saved_table
                        )
                    )
                    if not state_matches and not _rollback_restore_dict_table(
                        current, saved_table
                    ):
                        replacement = dict.copy(saved_mapping)
                        if not _rollback_transplant_dict_table(current, replacement):
                            dict.clear(current)
                            dict.update(current, saved_mapping)
                elif container_kind == "defaultdict":
                    items, default_factory, saved_table = container_state
                    current_entries = _rollback_dict_entries_with_hashes(current)
                    saved_entries = _rollback_dict_entries_with_hashes(items)
                    state_matches = bool(
                        current_entries is not None
                        and saved_entries is not None
                        and len(current_entries) == len(saved_entries)
                        and all(
                            current_key is saved_key
                            and current_item is saved_item
                            and current_hash == saved_hash
                            for (
                                current_key,
                                current_item,
                                current_hash,
                            ), (
                                saved_key,
                                saved_item,
                                saved_hash,
                            ) in zip(current_entries, saved_entries)
                        )
                    )
                    state_matches = state_matches and (
                        _rollback_dict_table_snapshots_match(
                            _rollback_dict_table_snapshot(current), saved_table
                        )
                    )
                    if not state_matches and not _rollback_restore_dict_table(
                        current, saved_table
                    ):
                        replacement = dict.copy(items)
                        if not _rollback_transplant_dict_table(current, replacement):
                            dict.clear(current)
                            dict.update(current, items)
                    collections.defaultdict.default_factory.__set__(
                        current, default_factory
                    )
                elif container_kind == "ordered_dict":
                    saved_entries, saved_order_state = container_state
                    current_entries = _rollback_dict_entries_with_hashes(current)
                    if current_entries is None:
                        raise TypeError("ordered dictionary hash reuse unavailable")
                    current_keys = _rollback_ordered_dict_keys(current)
                    if current_keys is None:
                        raise TypeError("ordered dictionary logical order unavailable")
                    saved_keys = tuple(key for key, _item, _key_hash in saved_entries)
                    current_items_by_identity = {
                        id(key): item for key, item, _key_hash in current_entries
                    }
                    saved_items_by_identity = {
                        id(key): item for key, item, _key_hash in saved_entries
                    }
                    state_matches = (
                        len(current_keys) == len(saved_keys)
                        and all(
                            current_key is saved_key
                            for current_key, saved_key in zip(current_keys, saved_keys)
                        )
                        and all(
                            current_items_by_identity.get(
                                id(key), _ROLLBACK_DEEPCOPY_MISSING
                            )
                            is saved_items_by_identity[id(key)]
                            for key in saved_keys
                        )
                    )
                    if not state_matches:
                        replacement = _rollback_build_ordered_dict(
                            saved_entries, type(current)
                        )
                        if replacement is None:
                            raise TypeError(
                                "ordered dictionary restoration unavailable"
                            )
                        if not _rollback_transplant_ordered_dict_state(
                            current, replacement
                        ):
                            raise TypeError(
                                "ordered dictionary restoration unavailable"
                            )
                    if not _rollback_set_ordered_dict_state(current, saved_order_state):
                        raise TypeError("ordered dictionary restoration unavailable")
                elif container_kind == "list":
                    list.clear(current)
                    list.extend(current, container_state)
                elif container_kind == "set":
                    saved_set, saved_table = container_state
                    current_table = _rollback_set_table_snapshot(current)
                    state_matches = _rollback_set_table_snapshots_match(
                        current_table, saved_table
                    )
                    saved_entries = _rollback_set_entries_with_hashes(saved_set)
                    if (
                        not state_matches
                        and not _rollback_restore_set_table(current, saved_table)
                        and (
                            saved_entries is None
                            or not _rollback_rebuild_set_table(current, saved_entries)
                        )
                    ):
                        set.clear(current)
                        set.update(current, saved_set)
                elif container_kind == "deque":
                    saved_items, saved_deque_state = container_state
                    same_length = collections.deque.__len__(current) == len(saved_items)
                    if same_length:
                        for index, item in enumerate(saved_items):
                            if (
                                collections.deque.__getitem__(current, index)
                                is not item
                            ):
                                collections.deque.__setitem__(current, index, item)
                    else:
                        collections.deque.clear(current)
                        collections.deque.extend(current, saved_items)
                    if same_length and saved_deque_state is not None:
                        _rollback_restore_deque_state(
                            current, saved_items, *saved_deque_state
                        )
                elif container_kind == "memoryview":
                    (
                        backing,
                        view_format,
                        view_itemsize,
                        view_shape,
                        view_strides,
                        view_suboffsets,
                        view_offset,
                        view_nbytes,
                        view_readonly,
                        raw_contents,
                    ) = container_state
                    for replaced_backing, backing_replacement in reversed(replacements):
                        if backing is replaced_backing:
                            backing = backing_replacement
                            break
                    replacement = None
                    try:
                        current.obj
                        restore_view = current
                    except ValueError:
                        restore_view = _rebuild_memoryview_from_layout(
                            backing,
                            view_format=view_format,
                            view_itemsize=view_itemsize,
                            view_shape=view_shape,
                            view_strides=view_strides,
                            view_suboffsets=view_suboffsets,
                            view_offset=view_offset,
                            view_nbytes=view_nbytes,
                            view_readonly=view_readonly,
                        )
                        if restore_view is None:
                            storage = (
                                bytes(raw_contents)
                                if view_readonly
                                else bytearray(raw_contents)
                            )
                            replacement_base = memoryview(storage)
                            if (
                                replacement_base.format == view_format
                                and replacement_base.shape == view_shape
                            ):
                                restore_view = replacement_base
                            else:
                                try:
                                    restore_view = replacement_base.cast(
                                        view_format,
                                        shape=view_shape,
                                    )
                                finally:
                                    replacement_base.release()
                        replacement = restore_view
                    if not view_readonly:
                        _restore_memoryview_logical_contents(
                            restore_view,
                            raw_contents,
                        )
                    if replacement is not None:
                        replacements.append((current, replacement))
                elif container_kind == "bytearray":
                    bytearray.__setitem__(current, slice(None), container_state)
                elif container_kind == "array":
                    array.array.__setitem__(current, slice(None), container_state)
                elif container_kind == "mmap":
                    (
                        contents,
                        position,
                        readonly,
                        file_reconstruction,
                    ) = container_state
                    if current.closed:
                        replacement = None
                        if file_reconstruction is not None:
                            reopened_descriptor = _reopen_mmap_file_descriptor(
                                file_reconstruction
                            )
                            if reopened_descriptor is not None:
                                try:
                                    replacement = mmap.mmap(
                                        reopened_descriptor,
                                        len(contents),
                                        access=file_reconstruction.access,
                                        offset=file_reconstruction.file_offset,
                                    )
                                finally:
                                    os.close(reopened_descriptor)
                        if replacement is None:
                            unrestorable_snapshot_objects[id(current)] = current
                            continue
                        if not readonly:
                            replacement[:] = contents
                        replacement.seek(position)
                        replacements.append((current, replacement))
                    else:
                        if not readonly:
                            current[:] = contents
                        current.seek(position)
                elif container_kind == "buffer_exporter":
                    exported_view = memoryview(current)
                    try:
                        _restore_memoryview_logical_contents(
                            exported_view,
                            container_state,
                        )
                    finally:
                        exported_view.release()
                elif container_kind == "random":
                    random.Random.setstate(current, container_state)
                elif container_kind == "count":
                    count_type, count_args = container_state
                    replacement = itertools.count.__new__(count_type, *count_args)
                    replacement_descriptor, replacement_attributes = raw_instance_dict(
                        replacement
                    )
                    if (
                        attribute_state is not None
                        and replacement_descriptor is not None
                        and replacement_attributes is not None
                    ):
                        replacement_attributes.clear()
                        replacement_attributes.update(attribute_state)
                    for descriptor, existed, slot_value in slot_state:
                        try:
                            if existed:
                                descriptor.__set__(replacement, slot_value)
                            else:
                                descriptor.__delete__(replacement)
                        except (AttributeError, TypeError):
                            pass
                    replacements.append((current, replacement))
                elif container_kind == "iterator":
                    replacements.append((current, container_state))
                elif container_kind == "string_io":
                    if io.StringIO.closed.__get__(current, type(current)):
                        replacement = io.StringIO.__new__(type(current))
                        io.StringIO.__init__(replacement)
                        io.StringIO.__setstate__(replacement, container_state)
                        replacement_descriptor, replacement_attributes = (
                            raw_instance_dict(replacement)
                        )
                        if (
                            attribute_state is not None
                            and replacement_descriptor is not None
                            and replacement_attributes is not None
                        ):
                            replacement_attributes.clear()
                            replacement_attributes.update(attribute_state)
                        for descriptor, existed, slot_value in slot_state:
                            try:
                                if existed:
                                    descriptor.__set__(replacement, slot_value)
                                else:
                                    descriptor.__delete__(replacement)
                            except (AttributeError, TypeError):
                                pass
                        replacements.append((current, replacement))
                    else:
                        io.StringIO.__setstate__(current, container_state)
                elif container_kind == "bytes_io":
                    contents, position = container_state
                    if io.BytesIO.closed.__get__(current, type(current)):
                        replacement = io.BytesIO.__new__(type(current))
                        io.BytesIO.__init__(replacement, contents)
                        io.BytesIO.seek(replacement, position)
                        replacement_descriptor, replacement_attributes = (
                            raw_instance_dict(replacement)
                        )
                        if (
                            attribute_state is not None
                            and replacement_descriptor is not None
                            and replacement_attributes is not None
                        ):
                            replacement_attributes.clear()
                            replacement_attributes.update(attribute_state)
                        for descriptor, existed, slot_value in slot_state:
                            try:
                                if existed:
                                    descriptor.__set__(replacement, slot_value)
                                else:
                                    descriptor.__delete__(replacement)
                            except (AttributeError, TypeError):
                                pass
                        replacements.append((current, replacement))
                    else:
                        if len(io.BytesIO.getvalue(current)) == len(contents):
                            exported_view = io.BytesIO.getbuffer(current)
                            try:
                                exported_view[:] = contents
                            finally:
                                exported_view.release()
                        else:
                            io.BytesIO.seek(current, 0)
                            io.BytesIO.truncate(current, 0)
                            io.BytesIO.write(current, contents)
                        io.BytesIO.seek(current, position)
                elif container_kind == "function":
                    (
                        defaults,
                        kwdefaults_mapping,
                        kwdefaults_state,
                        annotations_mapping,
                        annotations_state,
                        closure_state,
                        code,
                        name,
                        qualname,
                        module,
                        doc,
                    ) = container_state
                    current.__defaults__ = defaults
                    if kwdefaults_mapping is None:
                        current.__kwdefaults__ = None
                    else:
                        kwdefaults_mapping.clear()
                        kwdefaults_mapping.update(kwdefaults_state)
                        current.__kwdefaults__ = kwdefaults_mapping
                    annotations_mapping.clear()
                    annotations_mapping.update(annotations_state)
                    current.__annotations__ = annotations_mapping
                    for cell, existed, cell_value in closure_state:
                        if existed:
                            cell.cell_contents = cell_value
                        else:
                            try:
                                del cell.cell_contents
                            except ValueError:
                                pass
                    current.__code__ = code
                    current.__name__ = name
                    current.__qualname__ = qualname
                    current.__module__ = module
                    current.__doc__ = doc
                elif container_kind == "cell":
                    existed, cell_value = container_state
                    if existed:
                        current.cell_contents = cell_value
                    else:
                        try:
                            del current.cell_contents
                        except ValueError:
                            pass
                if attribute_state is not None and attribute_descriptor is not None:
                    current_attributes = attribute_descriptor.__get__(
                        attribute_restore_target, type(attribute_restore_target)
                    )
                    current_attributes.clear()
                    current_attributes.update(attribute_state)
                for descriptor, existed, slot_value in slot_state:
                    if existed:
                        descriptor.__set__(attribute_restore_target, slot_value)
                    else:
                        try:
                            descriptor.__delete__(attribute_restore_target)
                        except (AttributeError, TypeError):
                            pass
            except BaseException:
                # Rollback is best-effort for opaque user types; graph
                # contamination below still prevents returning a known
                # reference to the abandoned partial parent.
                unrestorable_snapshot_objects[id(current)] = current
                continue
        for target, replacement in replacements:
            restored_snapshot_replacements[id(target)] = (
                target,
                replacement,
            )
            rewrite_memo: Dict[int, Any] = {}
            for original_id, current in list(completed_memo.items()):
                set_completed(
                    original_id,
                    replace_visible_identity(
                        current, target, replacement, rewrite_memo
                    ),
                )
            for original_id, current in list(active_memo.items()):
                set_active(
                    original_id,
                    replace_visible_identity(
                        current, target, replacement, rewrite_memo
                    ),
                )
            for key, current in list(copied.items()):
                copied[key] = replace_visible_identity(
                    current, target, replacement, rewrite_memo
                )
            for original_id, current in list(completed_memo.items()):
                set_completed(
                    original_id,
                    finalize_visible_identity_rewrites(current, rewrite_memo),
                )
            for original_id, current in list(active_memo.items()):
                set_active(
                    original_id,
                    finalize_visible_identity_rewrites(current, rewrite_memo),
                )
            for key, current in list(copied.items()):
                copied[key] = finalize_visible_identity_rewrites(current, rewrite_memo)

    def reject_unrestorable_completed_graphs() -> Set[int]:
        """Evict completed clones whose exact rollback became impossible."""

        targets = tuple(unrestorable_snapshot_objects.values())
        if not targets:
            return set()

        def contains_target(root: Any) -> bool:
            return any(graph_contains_identity(root, target) for target in targets)

        contaminated_ids = {
            original_id
            for original_id, copied_value in completed_memo.items()
            if original_id not in authoritative_fallback_memo
            if contains_target(copied_value)
        }
        for original_id in contaminated_ids:
            pop_completed(original_id)
            original = original_by_id.get(original_id)
            if original is not None and type(original) not in {
                dict,
                list,
                tuple,
                set,
                frozenset,
            }:
                set_completed(original_id, original)

        for key, copied_value in list(copied.items()):
            if not contains_target(copied_value):
                continue
            original = copyable[key]
            copied[key] = original
            set_authoritative_fallback(id(original), original)
        active_contaminated_ids = {
            original_id
            for original_id, active_value in active_memo.items()
            if contains_target(active_value)
        }
        if not active_contaminated_ids:
            unrestorable_snapshot_objects.clear()
        return active_contaminated_ids

    copy_frame_stack: List[int] = []

    def copy_or_share(value: Any, memo: Dict[int, Any]) -> Any:
        """Track every copy frame, including immutable and passive wrappers."""

        copy_frame_stack.append(id(value))
        try:
            return copy_or_share_frame(value, memo)
        finally:
            copy_frame_stack.pop()

    def copy_or_share_frame(value: Any, memo: Dict[int, Any]) -> Any:
        """Copy one graph edge, sharing only the precise failing leaf.

        Keeping this fallback at every edge prevents one opaque nested handle
        from sacrificing isolation for its otherwise-copyable parent.  The
        identity memo also ensures an alias cannot invoke a failed copy hook a
        second time.
        """

        try:
            return safe_deepcopy(value, memo)
        except Exception as error:
            for journal in reversed(snapshot_outer_restore_stack):
                restore_completed_mutables(list(journal.values()))
            had_unrestorable_snapshot = bool(unrestorable_snapshot_objects)
            reject_unrestorable_completed_graphs()
            if (
                isinstance(error, UnrestorableActiveRollbackError)
                or had_unrestorable_snapshot
            ):
                if id(value) in active_memo:
                    pop_active(id(value))
                set_authoritative_fallback(id(value), value)
                reject_unrestorable_completed_graphs()
                if len(copy_frame_stack) > 1:
                    raise UnrestorableActiveRollbackError from error
                for original_id in list(active_memo):
                    original = original_by_id.get(
                        original_id, _ROLLBACK_DEEPCOPY_MISSING
                    )
                    pop_active(original_id)
                    if original is not _ROLLBACK_DEEPCOPY_MISSING:
                        set_authoritative_fallback(original_id, original)
                reject_unrestorable_completed_graphs()
                memo.clear()
                memo.update(completed_memo)
                memo.update(shared_identity_memo)
                memo.update(rollback_memo_seed)
                memo.update(authoritative_fallback_memo)
                return value
            failed_partial = memo.get(id(value))
            if failed_partial is not None and failed_partial is not value:
                contaminated_ids = {
                    original_id
                    for original_id, copied_value in completed_memo.items()
                    if graph_contains_identity(copied_value, failed_partial)
                }
                for original_id in contaminated_ids:
                    pop_completed(original_id)
                    # A cached reduction can safely reconstruct this object
                    # without replaying its reducer. A successful custom copy
                    # hook has no replayable recipe, so share that exact
                    # contaminated object instead of invoking the hook again.
                    if original_id not in reduction_cache:
                        original = original_by_id.get(original_id)
                        if original is not None and type(original) not in {
                            dict,
                            list,
                            tuple,
                            set,
                            frozenset,
                        }:
                            set_completed(original_id, original)
            pop_active(id(value))
            memo.clear()
            # Descendants that completed before their parent failed remain
            # sound copies. Retaining them prevents a later alias from
            # replaying a stateful reducer or copy hook. Partially-built
            # objects never enter ``completed_memo``.
            memo.update(completed_memo)
            memo.update(active_memo)
            memo.update(shared_identity_memo)
            memo.update(rollback_memo_seed)
            memo[id(value)] = value
            return value
        except BaseException:
            for journal in reversed(snapshot_outer_restore_stack):
                restore_completed_mutables(list(journal.values()))
            reject_unrestorable_completed_graphs()
            raise

    def safe_reconstruct(
        original: Any,
        memo: Dict[int, Any],
        constructor: Any,
        args: Sequence[Any],
        state: Any = None,
        list_items: Any = None,
        dict_items: Any = None,
        state_setter: Any = None,
        *,
        journal_callbacks: bool = False,
    ) -> Any:
        def snapshots_for_callback(roots: Sequence[Any]) -> List[tuple[Any, ...]]:
            if journal_callbacks and not snapshot_outer_restore_stack:
                return snapshot_completed_mutables()
            outer_snapshot_ids = {
                snapshot_id
                for journal in snapshot_outer_restore_stack
                for snapshot_id in journal
            }
            return snapshot_completed_mutables(
                roots,
                stop_ids=outer_snapshot_ids or None,
            )

        copied_args = tuple(copy_or_share(item, memo) for item in args)
        constructor_snapshot = snapshots_for_callback(copied_args)
        try:
            rebuilt = constructor(*copied_args)
        except BaseException:
            restore_completed_mutables(constructor_snapshot)
            raise
        memo[id(original)] = rebuilt
        set_active(id(original), rebuilt)
        if state is not None:
            copied_state = copy_or_share(state, memo)
            if state_setter is not None:
                setter_snapshot = snapshots_for_callback((rebuilt, copied_state))
                try:
                    state_setter(rebuilt, copied_state)
                except BaseException:
                    restore_completed_mutables(setter_snapshot)
                    raise
            else:
                setstate = getattr(rebuilt, "__setstate__", None)
                if callable(setstate):
                    setter_snapshot = snapshots_for_callback((rebuilt, copied_state))
                    try:
                        setstate(copied_state)
                    except BaseException:
                        restore_completed_mutables(setter_snapshot)
                        raise
                else:
                    state_snapshot = snapshots_for_callback((rebuilt, copied_state))
                    try:
                        if isinstance(copied_state, tuple) and len(copied_state) == 2:
                            dict_state, slot_state = copied_state
                        else:
                            dict_state, slot_state = copied_state, None
                        if dict_state is not None:
                            dict_descriptor, rebuilt_attributes = raw_instance_dict(
                                rebuilt
                            )
                            if dict_descriptor is None or rebuilt_attributes is None:
                                raise TypeError(
                                    "reducer supplied dict state for an "
                                    "object without instance storage"
                                )
                            rebuilt_attributes.update(dict_state)
                        if slot_state is not None:
                            descriptors = dict(declared_slot_descriptors(rebuilt))
                            for slot_name, slot_value in slot_state.items():
                                descriptor = descriptors.get(slot_name)
                                if descriptor is not None and hasattr(
                                    descriptor, "__set__"
                                ):
                                    descriptor.__set__(rebuilt, slot_value)
                                else:
                                    setattr(rebuilt, slot_name, slot_value)
                    except BaseException:
                        restore_completed_mutables(state_snapshot)
                        raise
        if list_items is not None:
            list_snapshots: Dict[int, tuple[Any, ...]] = {
                id(snapshot[0]): snapshot
                for snapshot in snapshots_for_callback((rebuilt,))
            }
            try:
                for item in list_items:
                    observing_item = copy_graph_has_observing_hook(item, memo)
                    if observing_item:
                        current_journal = {
                            id(snapshot[0]): snapshot
                            for snapshot in snapshot_completed_mutables((rebuilt,))
                        }
                        snapshot_outer_restore_stack.append(current_journal)
                        snapshot_stop_stack.append(current_journal)
                    else:
                        snapshot_stop_stack.append(list_snapshots)
                    try:
                        copied_item = copy_or_share(item, memo)
                    finally:
                        snapshot_stop_stack.pop()
                        if observing_item:
                            snapshot_outer_restore_stack.pop()
                    list_snapshot = snapshot_completed_mutables(
                        (copied_item,),
                        stop_ids=None if observing_item else list_snapshots,
                    )
                    for snapshot in list_snapshot:
                        list_snapshots.setdefault(id(snapshot[0]), snapshot)
                    rebuilt.append(copied_item)
            except BaseException:
                restore_completed_mutables(list(list_snapshots.values()))
                raise
        if dict_items is not None:
            dict_snapshots: Dict[int, tuple[Any, ...]] = {
                id(snapshot[0]): snapshot
                for snapshot in snapshots_for_callback((rebuilt,))
            }
            try:
                for item_key, item_value in dict_items:
                    observing_item = copy_graph_has_observing_hook(
                        item_key, memo
                    ) or copy_graph_has_observing_hook(item_value, memo)
                    if observing_item:
                        current_journal = {
                            id(snapshot[0]): snapshot
                            for snapshot in snapshot_completed_mutables((rebuilt,))
                        }
                        snapshot_outer_restore_stack.append(current_journal)
                        snapshot_stop_stack.append(current_journal)
                    else:
                        snapshot_stop_stack.append(dict_snapshots)
                    try:
                        copied_key = copy_or_share(item_key, memo)
                        copied_value = copy_or_share(item_value, memo)
                    finally:
                        snapshot_stop_stack.pop()
                        if observing_item:
                            snapshot_outer_restore_stack.pop()
                    dict_snapshot = snapshot_completed_mutables(
                        (copied_key, copied_value),
                        stop_ids=None if observing_item else dict_snapshots,
                    )
                    for snapshot in dict_snapshot:
                        dict_snapshots.setdefault(id(snapshot[0]), snapshot)
                    rebuilt[copied_key] = copied_value
            except BaseException:
                restore_completed_mutables(list(dict_snapshots.values()))
                raise
        return rebuilt

    def safe_deepcopy(value: Any, memo: Dict[int, Any]) -> Any:
        """Deep-copy once while preserving every encountered runtime leaf."""

        value_id = id(value)
        original_by_id[value_id] = value
        authoritative_value = authoritative_fallback_memo.get(
            value_id, _ROLLBACK_DEEPCOPY_MISSING
        )
        if authoritative_value is value:
            return value
        if is_rollback_leaf(value):
            memo[value_id] = value
            set_completed(value_id, value)
            return value
        if value_id in memo:
            memo_value = memo[value_id]
            if (
                completed_memo.get(value_id, _ROLLBACK_DEEPCOPY_MISSING) is memo_value
                or active_memo.get(value_id, _ROLLBACK_DEEPCOPY_MISSING) is memo_value
            ):
                return memo_value
            # A custom hook may write arbitrary memo entries. Until trusted
            # copy control flow records one in the local completion/active
            # journal, it is only a partial candidate and cannot satisfy a
            # later alias.
            _RollbackDeepcopyMemo.pop(memo, value_id, None)
        value_type = type(value)
        dispatcher = copy._deepcopy_dispatch.get(value_type)  # noqa: SLF001
        if dispatcher is copy._deepcopy_atomic:  # noqa: SLF001
            copied_value = value
        elif value_type is list:
            copied_value = []
            memo[value_id] = copied_value
            set_active(value_id, copied_value)
            copied_value.extend(copy_or_share(item, memo) for item in value)
        elif value_type is dict:
            copied_value = {}
            memo[value_id] = copied_value
            set_active(value_id, copied_value)
            for item_key, item_value in value.items():
                copied_value[copy_or_share(item_key, memo)] = copy_or_share(
                    item_value, memo
                )
        elif value_type is tuple:
            copied_items = [copy_or_share(item, memo) for item in value]
            recursive_value = memo.get(value_id)
            if recursive_value is not None:
                return recursive_value
            copied_value = (
                value
                if all(
                    original is copied for original, copied in zip(value, copied_items)
                )
                else tuple(copied_items)
            )
        elif value_type is types.MethodType:
            copied_value = type(value)(
                value.__func__,
                copy_or_share(value.__self__, memo),
            )
        elif isinstance(value_type, type) and issubclass(value_type, type):
            copied_value = value
        else:
            observing_copy = copy_graph_has_observing_hook(value, memo)
            observes_prior_copy = copy_graph_has_observing_hook(
                value,
                memo,
                prior_memo_only=True,
            )
            protocol_snapshot = (
                snapshot_before_observing_copy() if observes_prior_copy else []
            )
            failure_snapshot = list(protocol_snapshot)
            if observes_prior_copy and active_memo:
                captured_ids = {id(snapshot[0]) for snapshot in failure_snapshot}
                failure_snapshot.extend(
                    snapshot
                    for snapshot in snapshot_completed_mutables(
                        tuple(active_memo.values()),
                        stop_ids={snapshot_id: True for snapshot_id in captured_ids}
                        or None,
                    )
                    if id(snapshot[0]) not in captured_ids
                )
            try:
                custom_deepcopy = getattr(value, "__deepcopy__", None)
            except BaseException:
                restore_completed_mutables(failure_snapshot)
                raise
            if callable(custom_deepcopy):
                callback_snapshot = failure_snapshot
                try:
                    memo.update(runtime_memo(custom_deepcopy, receiver=value))
                    callback_memo_before = dict(memo)
                    copied_value = custom_deepcopy(memo)
                except BaseException:
                    restore_completed_mutables(callback_snapshot)
                    raise
                returned_callback_graph_ids = graph_identity_ids(copied_value)
                restore_completed_mutables(
                    [
                        snapshot
                        for snapshot in callback_snapshot
                        if id(snapshot[0]) not in returned_callback_graph_ids
                    ]
                )
                refresh_observing_copy_journals(
                    copied_value,
                    returned_callback_graph_ids,
                )
                memo_evidence_entry = nested_completion_evidence.get(id(memo))
                memo_evidence = (
                    memo_evidence_entry[1]
                    if isinstance(memo_evidence_entry, tuple)
                    and len(memo_evidence_entry) == 2
                    and memo_evidence_entry[0] is memo
                    and isinstance(memo_evidence_entry[1], list)
                    else []
                )
                # A recovery can execute another copy callback.  That callback
                # may change values whose completion records were checked
                # earlier in this pass, so reconciliation must reach a fixed
                # point before any memo entries are published as completed.
                reconciliation_limit = max(
                    16,
                    4 * (len(memo_evidence) + 1),
                )
                reconciliation_actions = 0
                while True:
                    mutation_journal_cache.clear()
                    snapshot_record_validation_cache.clear()
                    snapshot_dependency_match_cache.clear()
                    validated_completion_pairs: Dict[int, tuple[Any, Any]] = {}
                    stale_completion_pairs: List[tuple[int, Any, Any]] = []
                    stale_pair_ids: Set[tuple[int, int]] = set()
                    for record in tuple(memo_evidence):
                        completed_pair = completed_pair_from_evidence(record, memo)
                        if completed_pair is None:
                            continue
                        original, nested_copy, lineage_is_current = completed_pair
                        memo_key = id(original)
                        if lineage_is_current:
                            validated_completion_pairs[memo_key] = (
                                original,
                                nested_copy,
                            )
                            continue
                        stale_pair_id = (memo_key, id(nested_copy))
                        if stale_pair_id not in stale_pair_ids:
                            stale_pair_ids.add(stale_pair_id)
                            stale_completion_pairs.append(
                                (memo_key, original, nested_copy)
                            )

                    returned_reconciliation_graph_ids = graph_identity_ids(copied_value)
                    reconciliation_changed = False
                    for memo_key, original, stale_copy in stale_completion_pairs:
                        memo_value = dict.get(
                            memo, memo_key, _ROLLBACK_DEEPCOPY_MISSING
                        )
                        current_pair = validated_completion_pairs.get(memo_key)
                        if current_pair is not None and current_pair[1] is memo_value:
                            if (
                                stale_copy is not memo_value
                                and id(stale_copy) in returned_reconciliation_graph_ids
                            ):
                                reconciliation_rewrites: Dict[int, Any] = {}
                                copied_value = replace_visible_identity(
                                    copied_value,
                                    stale_copy,
                                    memo_value,
                                    reconciliation_rewrites,
                                )
                                copied_value = finalize_visible_identity_rewrites(
                                    copied_value,
                                    reconciliation_rewrites,
                                )
                                if id(stale_copy) in graph_identity_ids(copied_value):
                                    copied_value = value
                                reconciliation_changed = True
                            continue
                        if (
                            memo_value is not stale_copy
                            and id(stale_copy) not in returned_reconciliation_graph_ids
                        ):
                            continue
                        reconciliation_actions += 1
                        if reconciliation_actions > reconciliation_limit:
                            raise RuntimeError(
                                "rollback copy reconciliation did not converge"
                            )
                        if memo_value is stale_copy:
                            _RollbackDeepcopyMemo.pop(memo, memo_key, None)
                        pop_completed(memo_key)
                        pop_active(memo_key)
                        original_by_id[memo_key] = original
                        recovery_may_observe = copy_graph_has_observing_hook(
                            original, memo
                        )
                        recovered_copy = copy_or_share(original, memo)
                        reconciliation_rewrites = {}
                        copied_value = replace_visible_identity(
                            copied_value,
                            stale_copy,
                            recovered_copy,
                            reconciliation_rewrites,
                        )
                        copied_value = finalize_visible_identity_rewrites(
                            copied_value,
                            reconciliation_rewrites,
                        )
                        if id(stale_copy) in graph_identity_ids(copied_value):
                            copied_value = value
                        reconciliation_changed = True
                        if recovery_may_observe:
                            break
                    if not reconciliation_changed:
                        break
                returned_graph_ids = graph_identity_ids(copied_value)
                for memo_key, memo_value in list(dict.items(memo)):
                    previous = callback_memo_before.get(
                        memo_key, _ROLLBACK_DEEPCOPY_MISSING
                    )
                    completed_pair = validated_completion_pairs.get(memo_key)
                    nested_copy_completed = bool(
                        completed_pair is not None and completed_pair[1] is memo_value
                    )
                    returned_graph_contains = id(memo_value) in returned_graph_ids
                    if nested_copy_completed:
                        original_by_id[memo_key] = completed_pair[0]
                        set_completed(memo_key, memo_value)
                    elif returned_graph_contains and type(memo_key) is int:
                        set_completed(memo_key, memo_value)
                    if (
                        previous is memo_value
                        or (type(memo_key) is int and memo_key == id(memo))
                        or completed_memo.get(memo_key, _ROLLBACK_DEEPCOPY_MISSING)
                        is memo_value
                        or nested_copy_completed
                        or returned_graph_contains
                    ):
                        continue
                    if previous is _ROLLBACK_DEEPCOPY_MISSING:
                        _RollbackDeepcopyMemo.pop(memo, memo_key, None)
                    else:
                        _RollbackDeepcopyMemo.__setitem__(memo, memo_key, previous)
            else:
                copy_protocol_names = {
                    "__getnewargs__",
                    "__getnewargs_ex__",
                    "__getstate__",
                    "__new__",
                    "__reduce__",
                    "__reduce_ex__",
                    "__setstate__",
                }
                custom_copy_protocol = any(
                    owner is not object
                    and bool(
                        copy_protocol_names.intersection(raw_class_namespace(owner))
                    )
                    for owner in raw_class_mro(value_type)
                )
                metaclass_getattribute = None
                for metaclass_owner in raw_class_mro(type(value_type)):
                    metaclass_namespace = raw_class_namespace(metaclass_owner)
                    if "__getattribute__" in metaclass_namespace:
                        metaclass_getattribute = metaclass_namespace["__getattribute__"]
                        break
                custom_metaclass_access = bool(
                    metaclass_getattribute is not None
                    and metaclass_getattribute is not type.__getattribute__
                )
                raw_copy = _ROLLBACK_DEEPCOPY_MISSING
                if not custom_copy_protocol and custom_metaclass_access:
                    try:
                        raw_copy = object.__new__(value_type)
                    except TypeError:
                        pass
                if raw_copy is not _ROLLBACK_DEEPCOPY_MISSING:
                    memo[value_id] = raw_copy
                    set_active(value_id, raw_copy)
                    _source_descriptor, source_attributes = raw_instance_dict(value)
                    _target_descriptor, target_attributes = raw_instance_dict(raw_copy)
                    if source_attributes is not None and target_attributes is not None:
                        for attribute_name, attribute_value in dict.items(
                            source_attributes
                        ):
                            target_attributes[copy_or_share(attribute_name, memo)] = (
                                copy_or_share(attribute_value, memo)
                            )
                    for _slot_name, descriptor in declared_slot_descriptors(value):
                        try:
                            slot_value = descriptor.__get__(value, value_type)
                        except (AttributeError, TypeError):
                            continue
                        descriptor.__set__(raw_copy, copy_or_share(slot_value, memo))
                    copied_value = raw_copy
                else:
                    if value_id in reduction_cache:
                        reduction = reduction_cache[value_id]
                    else:
                        try:
                            reducer = copyreg.dispatch_table.get(value_type)
                            if reducer is not None:
                                reduction = reducer(value)
                            else:
                                reduce_ex = getattr(value, "__reduce_ex__", None)
                                if callable(reduce_ex):
                                    reduction = reduce_ex(4)
                                else:
                                    reduce = getattr(value, "__reduce__", None)
                                    if not callable(reduce):
                                        raise copy.Error(
                                            "un(deep)copyable object of type "
                                            f"{value_type!r}"
                                        )
                                    reduction = reduce()
                            if type(reduction) is not str:
                                reduction_parts = list(reduction)
                                for iterator_index in (3, 4):
                                    if (
                                        len(reduction_parts) > iterator_index
                                        and reduction_parts[iterator_index] is not None
                                    ):
                                        reduction_parts[iterator_index] = (
                                            ReplayableReductionIterator(
                                                reduction_parts[iterator_index]
                                            )
                                        )
                                reduction = tuple(reduction_parts)
                        except BaseException:
                            restore_completed_mutables(failure_snapshot)
                            raise
                        reduction_cache[value_id] = reduction
                    if type(reduction) is str:
                        copied_value = value
                    else:
                        copied_value = safe_reconstruct(
                            value,
                            memo,
                            *reduction,
                            journal_callbacks=observing_copy,
                        )
                if observes_prior_copy:
                    returned_protocol_graph_ids = graph_identity_ids(copied_value)
                    restore_completed_mutables(
                        [
                            snapshot
                            for snapshot in protocol_snapshot
                            if id(snapshot[0]) not in returned_protocol_graph_ids
                        ]
                    )
                    refresh_observing_copy_journals(
                        copied_value,
                        returned_protocol_graph_ids,
                    )
        if copied_value is not value:
            memo[value_id] = copied_value
            try:
                copy._keep_alive(value, memo)  # noqa: SLF001
            except Exception:
                pass
        set_completed(value_id, copied_value)
        pop_active(value_id)
        return copied_value

    copied: Dict[str, Any] = {}
    # A capability may also be reachable through ordinary rollback-owned
    # state (for example a recursive callback cached in a small metadata
    # mapping).  Seed the graph memo with every explicit capability so all
    # aliases retain the same live authority instead of cloning the session,
    # client, Lean runner, or retrieval index behind it.
    memo: Dict[int, Any] = _RollbackDeepcopyMemo(shared_identity_memo)
    completion_transaction = _rollback_deepcopy_completion_transaction(memo)
    _activate_rollback_deepcopy_transaction(completion_transaction)
    _register_active_rollback_memo(memo)
    try:
        for key, value in copyable.items():
            top_level_journal = {
                id(snapshot[0]): snapshot
                for snapshot in snapshot_completed_mutables(tuple(copied.values()))
            }
            snapshot_outer_restore_stack.append(top_level_journal)
            try:
                copied[key] = copy_or_share(value, memo)
            finally:
                snapshot_outer_restore_stack.pop()
        copied.update(shared)
        return copied
    finally:
        nested_completion_evidence.clear()
        nested_completion_mutations.clear()
        completion_snapshot_records.clear()
        mutation_journal_cache.clear()
        snapshot_record_validation_cache.clear()
        snapshot_dependency_match_cache.clear()
        _deactivate_rollback_deepcopy_transaction(completion_transaction)
        _unregister_active_rollback_memo(memo)
        _discard_rollback_deepcopy_completion_transaction(completion_transaction)


def _collect_nested_code_objects(
    code: types.CodeType,
) -> Dict[str, types.CodeType]:
    collected: Dict[str, types.CodeType] = {}
    pending = [code]
    while pending:
        current = pending.pop()
        for constant in current.co_consts:
            if isinstance(constant, types.CodeType):
                collected.setdefault(constant.co_name, constant)
                pending.append(constant)
    return collected


_ROLLBACK_SNAPSHOT_HELPER_CODES = types.MappingProxyType(
    {
        name: code
        for name, code in _collect_nested_code_objects(
            _copy_mapping_for_rollback_scoped.__code__
        ).items()
        if name
        in {
            "capture_completion_snapshot",
            "completion_snapshot_is_current",
            "freeze_completion_snapshot",
            "frozen_completion_snapshots_match",
            "snapshot_completed_mutables",
        }
    }
)
_ROLLBACK_COMPLETION_SNAPSHOT_CODE = _ROLLBACK_SNAPSHOT_HELPER_CODES.get(
    "capture_completion_snapshot"
)


def _create_task_through_factory(
    factory: Any,
    loop: asyncio.AbstractEventLoop,
    coroutine: Any,
    context: Optional[contextvars.Context],
    task_kwargs: Optional[Mapping[str, Any]] = None,
) -> asyncio.Task[Any]:
    kwargs = dict(task_kwargs or {})
    if context is not None:
        kwargs["context"] = context
    if factory is not None:
        return factory(loop, coroutine, **kwargs)
    return asyncio.Task(coroutine, loop=loop, **kwargs)


def _dispatch_capability_identity(value: Any) -> Any:
    """Return the weak-referenceable object that owns one capability generation.

    Lock registries use weak keys.  Returning an immutable tuple here sends
    every ordinary Lean/provider generation through the per-loop fallback,
    causing a retired generation's poisoned lock and late-tail record to be
    inherited by every fresh generation in that loop.
    """

    if value is None:
        return None
    target = value
    seen: Set[int] = set()
    for _ in range(16):
        if id(target) in seen:
            break
        seen.add(id(target))
        resolver = getattr(target, "_dispatch_capability_identity_token", None)
        if not callable(resolver):
            break
        try:
            resolved = resolver()
        except BaseException:
            break
        if resolved is None or resolved is target:
            break
        target = resolved
    return target


def _dispatch_capability_generation_nonce(value: Any) -> int:
    """Return a monotonic nonce without relying on recyclable object ids."""

    global _CAPABILITY_GENERATION_NONCE_NEXT
    identity = _dispatch_capability_identity(value)
    if identity is None:
        return 0
    with _CAPABILITY_GENERATION_NONCE_LOCK:
        try:
            nonce = _CAPABILITY_GENERATION_NONCES.get(identity)
        except TypeError:
            # Compatibility fakes may not support weak references. Production
            # Lean generations do; retain legacy identity only for those
            # process-local adapters.
            return id(identity)
        if nonce is None:
            nonce = _CAPABILITY_GENERATION_NONCE_NEXT
            _CAPABILITY_GENERATION_NONCE_NEXT += 1
            _CAPABILITY_GENERATION_NONCES[identity] = nonce
        return nonce


def _is_installed_loop_router(callback: Any) -> bool:
    """True when the callback *is* one of our own installed loop routers.

    CPython delivers subprocess exit by scheduling ``loop.call_soon`` itself as
    the callback of ``call_soon_threadsafe``
    (``asyncio/unix_events.py``: ``_child_watcher_callback`` does
    ``self.call_soon_threadsafe(self.call_soon, transp._process_exited, rc)``).
    Once we replace ``loop.call_soon`` with a router, that *outer* callback is
    our own function -- pure event-loop plumbing that cannot itself run action
    code.  Classifying it as application work let the after-boundary rule
    rewrite it to a no-op, so ``_process_exited`` never ran, the subprocess
    transport returncode stayed ``None``, ``_try_finish`` never completed, and
    ``proc.wait()`` blocked forever on an already-reaped Lean child -- pinning
    the Lean lock and stalling the whole session at 0% CPU with no error and
    no log line.

    This does not weaken the ownership barrier: when the router runs it
    re-classifies the *inner* callback it forwards, so genuine action work
    still crosses the same commit barrier.
    """

    # Unwrap partials, matching ``_is_asyncio_internal_scheduled_callback``.
    # That function strips them before classifying, so a
    # ``partial(loop.call_soon, app_cb)`` reads as plumbing there; if this
    # check did not strip too, such a hop bypassed rejection *without*
    # picking up an owner, and the application callback inside it executed
    # past a closed commit barrier. Bounded unwrap, still no iteration of any
    # shared structure -- this runs on CPython's waitpid thread.
    target = callback
    for _ in range(8):
        if not isinstance(target, functools.partial):
            break
        target = target.func
    try:
        return target in _INSTALLED_LOOP_ROUTERS
    except TypeError:
        # Unhashable callables are never one of our routers.
        return False


def _forwarded_router_context(
    context: Optional[contextvars.Context],
    owner: Any,
) -> contextvars.Context:
    """Carry the resolved owner into a forwarded router hop.

    An installed router is exempt from *rejection* -- silencing it strands
    runtime plumbing such as subprocess exit delivery -- but it must not be
    exempt from *attribution*.  CPython's double hop
    (``call_soon_threadsafe(loop.call_soon, inner, ...)``) means the outer
    callback is our router while the real work is ``inner``.  Forwarding with
    an empty context left the inner router with no owner to judge against, so
    application work scheduled that way executed past a closed commit barrier
    with no late-callback record.  Attaching the owner here makes the inner
    router re-run the full ownership rule against ``inner``.

    Runtime plumbing is unaffected: an inner callback that is genuine asyncio
    internals still classifies as such and is forwarded, so subprocess exit is
    delivered exactly as before.
    """

    effective = context if context is not None else contextvars.copy_context()
    if owner is not None and effective.get(_OPERATION_CHILD_TASK_TRACKER) is None:
        effective = effective.copy()
        effective.run(_OPERATION_CHILD_TASK_TRACKER.set, owner)
    return effective


def _is_asyncio_internal_scheduled_callback(callback: Any) -> bool:
    """Exclude only event-loop plumbing that cannot run action code.

    Task stepping, future wakeups, and asyncio's sleep timer are joined by the
    task/future that owns them.  All other callbacks scheduled while an action
    owns the dispatch context are application work and must cross the same
    commit barrier, including callbacks given an explicitly empty context.
    """

    # asyncio uses ``functools.partial(_release_waiter, waiter)`` for the
    # completion edge of wait_for()/wait().  Inspect the callable being
    # scheduled rather than the partial wrapper; otherwise ordinary awaited
    # verifier work is falsely reported as an unjoined application callback.
    while isinstance(callback, functools.partial):
        callback = callback.func
    if is_runtime_owned_callback(callback):
        return True
    if _is_installed_loop_router(callback):
        return True
    owner = getattr(callback, "__self__", None)
    callback_type = type(callback)
    if (
        callback_type.__module__ in {"_asyncio", "builtins"}
        and callback_type.__name__
        in {"TaskStepMethWrapper", "builtin_function_or_method"}
        and isinstance(owner, (asyncio.Task, asyncio.Future))
    ):
        return True
    # Python-level asyncio plumbing is trusted only when the callable's code
    # actually belongs to its loaded asyncio module. ``__module__`` is a
    # writable attribute and cannot itself be an ownership boundary.
    module = inspect.getmodule(callback)
    module_name = str(getattr(module, "__name__", "") or "")
    if module_name == "asyncio" or module_name.startswith("asyncio."):
        try:
            return bool(
                inspect.getsourcefile(callback) == inspect.getsourcefile(module)
            )
        except (OSError, TypeError):
            return False
    return False


def _is_asyncio_subprocess_connector(coroutine: Any) -> bool:
    """Whether ``coroutine`` is asyncio's internally joined pipe connector.

    ``create_subprocess_exec`` creates this private task and waits for it via
    transport callbacks rather than the Task ``__await__``/``result`` API.
    It inherits the caller's context, but it is runtime-owned plumbing and
    cannot execute application/session code.  Keep tracking it for liveness
    and failures while exempting only its successful completion from the
    application-level unjoined-result test.
    """

    code = getattr(coroutine, "cr_code", None)
    if code is None:
        return False
    filename = str(getattr(code, "co_filename", "") or "").replace("\\", "/")
    qualname = str(getattr(code, "co_qualname", "") or "")
    return bool(
        filename.endswith("/asyncio/base_subprocess.py")
        and qualname == "BaseSubprocessTransport._connect_pipes"
    )


class _ObservedOperationTask(asyncio.Task[Any]):
    """Task that records whether its result joined the owning operation."""

    def __init__(
        self,
        coroutine: Any,
        *,
        loop: Any,
        context: Any = None,
        **task_kwargs: Any,
    ) -> None:
        self._mini_operation_observed = False
        if context is not None:
            task_kwargs["context"] = context
        super().__init__(coroutine, loop=loop, **task_kwargs)

    def __await__(self):
        self._mini_operation_observed = True
        return super().__await__()

    def result(self) -> Any:
        self._mini_operation_observed = True
        return super().result()

    def exception(self) -> Optional[BaseException]:
        self._mini_operation_observed = True
        return super().exception()


class _ObservedOperationFuture(asyncio.Task[Any]):
    """Full Task facade over a Task produced by an installed custom factory."""

    def __init__(
        self,
        source: asyncio.Future[Any],
        *,
        context: Optional[contextvars.Context] = None,
    ) -> None:
        self._mini_operation_observed = False
        self._mini_source_task = source

        async def join_source() -> Any:
            return await source

        if context is None:
            super().__init__(join_source(), loop=source.get_loop())
        else:
            super().__init__(
                join_source(),
                loop=source.get_loop(),
                context=context,
            )

    def __await__(self):
        self._mini_operation_observed = True
        return super().__await__()

    def result(self) -> Any:
        self._mini_operation_observed = True
        return super().result()

    def exception(self) -> Optional[BaseException]:
        self._mini_operation_observed = True
        return super().exception()

    def cancel(self, msg: Any = None) -> bool:
        # A Task may report that cancellation was requested and then suppress
        # ``CancelledError``.  Keep this proxy pending until the source really
        # settles so the transaction barrier cannot mistake request delivery
        # for mutation quiescence.
        return bool(self._mini_source_task.cancel(msg))

    def get_name(self) -> str:
        getter = getattr(self._mini_source_task, "get_name", None)
        return str(getter()) if callable(getter) else ""

    def set_name(self, value: str) -> None:
        setter = getattr(self._mini_source_task, "set_name", None)
        if callable(setter):
            setter(value)

    def get_coro(self) -> Any:
        getter = getattr(self._mini_source_task, "get_coro", None)
        return getter() if callable(getter) else None

    def cancelling(self) -> int:
        getter = getattr(self._mini_source_task, "cancelling", None)
        return int(getter()) if callable(getter) else 0

    def uncancel(self) -> int:
        method = getattr(self._mini_source_task, "uncancel", None)
        return int(method()) if callable(method) else 0

    def print_stack(self, *args: Any, **kwargs: Any) -> Any:
        method = getattr(self._mini_source_task, "print_stack", None)
        return method(*args, **kwargs) if callable(method) else None

    def get_stack(self, *args: Any, **kwargs: Any) -> Any:
        method = getattr(self._mini_source_task, "get_stack", None)
        return method(*args, **kwargs) if callable(method) else []

    def get_context(self) -> contextvars.Context:
        getter = getattr(self._mini_source_task, "get_context", None)
        if callable(getter):
            return getter()
        raise AttributeError("Task.get_context is unavailable on this runtime")


def _task_exception_without_observing(
    task: "asyncio.Future[Any]",
) -> Optional[BaseException]:
    """Inspect a tracked task at the barrier without marking it joined."""

    if isinstance(task, _ObservedOperationTask):
        return asyncio.Task.exception(task)
    if isinstance(task, _ObservedOperationFuture):
        return asyncio.Task.exception(task)
    return task.exception()


def _run_operation_sync_in_daemon(
    loop: asyncio.AbstractEventLoop,
    function: Callable[..., Any],
    args: Tuple[Any, ...],
) -> "asyncio.Future[Any]":
    """Run operation-owned blocking work without joining loop shutdown.

    Cancelling the Task returned by ``asyncio.to_thread`` cannot stop its
    underlying worker.  The default executor nevertheless remains owned by
    ``asyncio.run``, whose unconditional executor join can then turn a
    fail-closed settlement error into an unbounded shutdown wait.  A governed
    operation already has a capability-lease barrier that detects such live
    calls and poisons publication.  Use a daemon worker for its default-
    executor submissions so that barrier, rather than event-loop teardown,
    remains the lifecycle authority.
    """

    future: "asyncio.Future[Any]" = loop.create_future()
    if not _OPERATION_DAEMON_WORKER_SLOTS.acquire(blocking=False):
        future.set_exception(
            RuntimeError("operation-owned synchronous worker capacity exhausted")
        )
        return future

    def publish_result(ok: bool, value: Any) -> None:
        if future.done():
            return
        if ok:
            future.set_result(value)
        else:
            future.set_exception(value)

    publish_result = mark_runtime_owned_callback(publish_result)

    def worker() -> None:
        try:
            try:
                result = function(*args)
            except BaseException as exc:
                outcome = (False, exc)
            else:
                outcome = (True, result)
        finally:
            _OPERATION_DAEMON_WORKER_SLOTS.release()
        if loop.is_closed():
            return
        try:
            loop.call_soon_threadsafe(publish_result, *outcome)
        except RuntimeError:
            # The owning transaction may have closed its loop after revoking
            # this abandoned worker.  Its late result is intentionally lost.
            pass

    thread = threading.Thread(
        target=worker,
        name="mini-session-operation-sync",
        daemon=True,
    )
    try:
        thread.start()
    except BaseException:
        _OPERATION_DAEMON_WORKER_SLOTS.release()
        raise
    return future


class _OperationChildTaskTracker:
    """Track task descendants created by one governed operation.

    ``asyncio.all_tasks`` omits tasks that finish before a commit barrier and
    cannot distinguish a concurrent service task from an operation child.
    A short-lived task-factory router records only tasks whose inherited
    context names this tracker.  The per-operation baseline additionally
    guarantees that a pre-existing task is never cancelled by this barrier.
    Routers are reference counted per event loop so concurrent Mini sessions
    do not overwrite one another's task factories.
    """

    def __init__(self) -> None:
        self.loop = asyncio.get_running_loop()
        self.baseline = set(asyncio.all_tasks(self.loop))
        self.created: Set[asyncio.Future[Any]] = set()
        self.scheduled_callbacks: List[Dict[str, Any]] = []
        self.primary_task: Optional[asyncio.Future[Any]] = None
        self.boundary_live_children: Set[asyncio.Future[Any]] = set()
        self.boundary_pending_callback_records: List[Dict[str, Any]] = []
        self.boundary_late_callback_records: List[Dict[str, Any]] = []
        self._boundary_lock = threading.RLock()
        self._boundary_closed = False
        self._closed = False
        state = _OPERATION_TASK_FACTORY_STATES.get(self.loop)
        if state is None:
            previous_factory = self.loop.get_task_factory()
            previous_call_at = self.loop.call_at
            previous_call_soon = self.loop.call_soon
            previous_call_soon_threadsafe = self.loop.call_soon_threadsafe
            previous_run_in_executor = self.loop.run_in_executor

            def router(
                loop: asyncio.AbstractEventLoop,
                coroutine: Any,
                context: Optional[contextvars.Context] = None,
                **task_kwargs: Any,
            ) -> asyncio.Task[Any]:
                # Runtime receipt authority is granted only to an exact task
                # after construction. It never propagates through ContextVar
                # state, so a receipt observer's descendants remain owned by
                # the proof action.
                creator_owner = _OPERATION_CHILD_TASK_TRACKER.get()
                context_owner = (
                    None
                    if context is None
                    else context.get(_OPERATION_CHILD_TASK_TRACKER)
                )
                owner = context_owner or creator_owner
                effective_context = context
                if owner is not None and context is not None and context_owner is None:
                    effective_context = context.copy()
                    effective_context.run(
                        _OPERATION_CHILD_TASK_TRACKER.set,
                        owner,
                    )
                if (
                    previous_factory is None
                    and owner is not None
                    and not _is_asyncio_subprocess_connector(coroutine)
                ):
                    task = _ObservedOperationTask(
                        coroutine,
                        loop=loop,
                        context=effective_context,
                        **task_kwargs,
                    )
                else:
                    source_task = _create_task_through_factory(
                        previous_factory,
                        loop,
                        coroutine,
                        effective_context,
                        task_kwargs,
                    )
                    task = (
                        _ObservedOperationFuture(
                            source_task,
                            context=effective_context,
                        )
                        if owner is not None
                        and previous_factory is not None
                        and not _is_asyncio_subprocess_connector(coroutine)
                        else source_task
                    )
                if owner is not None:
                    result_only = register_inherited_result_only_deadline_task(task)
                    transport_owned = register_inherited_transport_request_task(task)
                    with owner._boundary_lock:
                        owner.created.add(task)
                        if (
                            owner._boundary_closed
                            and not result_only
                            and not transport_owned
                        ):
                            owner.boundary_live_children.add(task)
                            # Never cancel the subprocess pipe connector.
                            # CPython has ALREADY spawned the OS process by
                            # the time it creates this task, and cancelling
                            # it before its first timeslice throws into an
                            # unstarted coroutine -- so ``_connect_pipes``'
                            # own ``except BaseException: waiter.set_exception``
                            # never runs and ``await waiter`` in
                            # ``unix_events`` blocks forever, at 0% CPU, with
                            # no exception and no log line, leaving an
                            # orphaned child that is never reaped. The task is
                            # still recorded as a boundary-live child above;
                            # detection is the boundary's job, breaking the
                            # runtime is not.
                            if not _is_asyncio_subprocess_connector(coroutine):
                                task.cancel()
                return task

            state = {
                "previous_factory": previous_factory,
                "router": router,
                "previous_call_at": previous_call_at,
                "previous_call_soon": previous_call_soon,
                "previous_call_soon_threadsafe": previous_call_soon_threadsafe,
                "previous_run_in_executor": previous_run_in_executor,
                "owners": set(),
                "owners_snapshot": (),
                "owners_lock": threading.RLock(),
                "refcount": 0,
            }

            def run_in_executor_router(
                executor: Optional[concurrent.futures.Executor],
                function: Callable[..., Any],
                *args: Any,
            ) -> asyncio.Future[Any]:
                owner = (
                    None
                    if transport_receipt_observer_current_task_owned()
                    else _OPERATION_CHILD_TASK_TRACKER.get()
                )
                if owner is None:
                    return previous_run_in_executor(executor, function, *args)
                with owner._boundary_lock:
                    if owner._boundary_closed:
                        # Submit anyway and record the incident, rather than
                        # handing back a pre-cancelled future. asyncio routes
                        # its own plumbing through here -- getaddrinfo,
                        # getnameinfo, sock_sendfile, asyncio.to_thread -- so
                        # rejecting broke DNS for any detached tail still
                        # finishing an HTTP request, and the resulting
                        # CancelledError was scored as a clean join and
                        # reported as a deadline expiry, hiding the real
                        # cause. Detection is the boundary's job; breaking the
                        # runtime is not.
                        late_future = previous_run_in_executor(
                            executor, function, *args
                        )
                        owner.created.add(late_future)
                        owner.boundary_live_children.add(late_future)
                        return late_future
                    future = (
                        _run_operation_sync_in_daemon(
                            owner.loop,
                            function,
                            args,
                        )
                        if executor is None
                        else previous_run_in_executor(executor, function, *args)
                    )
                    owner.created.add(future)
                    return future

            def schedule_owned_callback(
                owner: "_OperationChildTaskTracker",
                scheduler: Any,
                callback: Any,
                args: Tuple[Any, ...],
                context: Optional[contextvars.Context],
                *,
                when: Optional[float] = None,
            ) -> asyncio.Handle:
                record: Dict[str, Any] = {
                    "handle": None,
                    "fired": False,
                    "failed": False,
                    "scheduled_after_boundary": False,
                    "callback_repr": repr(callback),
                }

                def tracked_callback(*callback_args: Any) -> Any:
                    record["fired"] = True
                    token = _OPERATION_CHILD_TASK_TRACKER.set(owner)
                    try:
                        return callback(*callback_args)
                    except BaseException:
                        record["failed"] = True
                        raise
                    finally:
                        _OPERATION_CHILD_TASK_TRACKER.reset(token)

                effective_context = context
                if (
                    context is not None
                    and context.get(_OPERATION_CHILD_TASK_TRACKER) is None
                ):
                    effective_context = context.copy()
                    effective_context.run(_OPERATION_CHILD_TASK_TRACKER.set, owner)
                with owner._boundary_lock:
                    after_boundary = bool(owner._boundary_closed)
                    record["scheduled_after_boundary"] = after_boundary

                    def rejected_after_boundary(*_ignored: Any) -> None:
                        record["fired"] = True

                    scheduled_callback = (
                        rejected_after_boundary if after_boundary else tracked_callback
                    )
                    if when is None:
                        handle = scheduler(
                            scheduled_callback,
                            *(() if after_boundary else args),
                            context=effective_context,
                        )
                    else:
                        handle = scheduler(
                            when,
                            scheduled_callback,
                            *(() if after_boundary else args),
                            context=effective_context,
                        )
                    record["handle"] = handle
                    owner.scheduled_callbacks.append(record)
                    if after_boundary:
                        owner.boundary_late_callback_records.append(record)
                return handle

            def call_at_router(
                when: float,
                callback: Any,
                *args: Any,
                context: Optional[contextvars.Context] = None,
            ) -> asyncio.TimerHandle:
                runtime_owned = transport_receipt_observer_current_task_owned()
                creator_owner = (
                    None if runtime_owned else _OPERATION_CHILD_TASK_TRACKER.get()
                )
                context_owner = (
                    context.get(_OPERATION_CHILD_TASK_TRACKER)
                    if context is not None and not runtime_owned
                    else None
                )
                owner = context_owner or creator_owner
                if owner is not None and _is_installed_loop_router(callback):
                    return previous_call_at(
                        when,
                        callback,
                        *args,
                        context=_forwarded_router_context(context, owner),
                    )
                if owner is None or _is_asyncio_internal_scheduled_callback(callback):
                    return previous_call_at(
                        when,
                        callback,
                        *args,
                        context=context,
                    )
                return schedule_owned_callback(
                    owner,
                    previous_call_at,
                    callback,
                    args,
                    context,
                    when=when,
                )

            def call_soon_router(
                callback: Any,
                *args: Any,
                context: Optional[contextvars.Context] = None,
            ) -> asyncio.Handle:
                runtime_owned = transport_receipt_observer_current_task_owned()
                creator_owner = (
                    None if runtime_owned else _OPERATION_CHILD_TASK_TRACKER.get()
                )
                context_owner = (
                    context.get(_OPERATION_CHILD_TASK_TRACKER)
                    if context is not None and not runtime_owned
                    else None
                )
                owner = context_owner or creator_owner
                if owner is not None and _is_installed_loop_router(callback):
                    return previous_call_soon(
                        callback,
                        *args,
                        context=_forwarded_router_context(context, owner),
                    )
                if owner is None or _is_asyncio_internal_scheduled_callback(callback):
                    return previous_call_soon(callback, *args, context=context)
                return schedule_owned_callback(
                    owner,
                    previous_call_soon,
                    callback,
                    args,
                    context,
                )

            def call_soon_threadsafe_router(
                callback: Any,
                *args: Any,
                context: Optional[contextvars.Context] = None,
            ) -> asyncio.Handle:
                runtime_owned = transport_receipt_observer_current_task_owned()
                installed_router = _is_installed_loop_router(callback)
                if runtime_owned:
                    return previous_call_soon_threadsafe(
                        callback,
                        *args,
                        context=context,
                    )
                creator_owner = (
                    None if runtime_owned else _OPERATION_CHILD_TASK_TRACKER.get()
                )
                context_owner = (
                    context.get(_OPERATION_CHILD_TASK_TRACKER)
                    if context is not None and not runtime_owned
                    else None
                )
                owner = context_owner or creator_owner
                active_owners: Tuple[_OperationChildTaskTracker, ...] = ()
                if owner is None and not runtime_owned:
                    # Foreign waitpid threads must never iterate the live set
                    # while the loop thread opens/closes trackers. The tuple
                    # is published atomically under the same lock as owner
                    # mutation and is immutable after publication.
                    with state["owners_lock"]:
                        active_owners = state.get("owners_snapshot") or ()
                    if len(active_owners) == 1:
                        owner = active_owners[0]
                if not runtime_owned and installed_router:
                    # Exempt from rejection, not from attribution: carry the
                    # owner we just resolved (including a sole-owner adoption)
                    # into the forwarded hop so the inner router judges the
                    # real callback. Without this the inner hop ran with an
                    # empty context, and this is the ONLY router that can
                    # manufacture an owner, so the barrier was lost entirely.
                    return previous_call_soon_threadsafe(
                        callback,
                        *args,
                        context=_forwarded_router_context(context, owner),
                    )
                if _is_asyncio_internal_scheduled_callback(callback):
                    return previous_call_soon_threadsafe(
                        callback,
                        *args,
                        context=context,
                    )
                if owner is None and len(active_owners) > 1:
                    # A contextless worker thread cannot identify which of
                    # several active transactions owns its callback. Never
                    # execute application code under ambiguous authority:
                    # attach one incident receipt to every possible owner and
                    # schedule only a bookkeeping no-op.
                    records: List[Dict[str, Any]] = [
                        {
                            "handle": None,
                            "fired": False,
                            "failed": False,
                            "scheduled_after_boundary": True,
                            "ambiguous_thread_owner": True,
                            "callback_repr": repr(callback),
                        }
                        for _ in active_owners
                    ]

                    def reject_ambiguous_callback() -> None:
                        for record in records:
                            record["fired"] = True

                    handle = previous_call_soon_threadsafe(
                        reject_ambiguous_callback,
                        context=context,
                    )
                    for possible_owner, record in zip(active_owners, records):
                        with possible_owner._boundary_lock:
                            record["handle"] = handle
                            possible_owner.scheduled_callbacks.append(record)
                            possible_owner.boundary_late_callback_records.append(record)
                    return handle
                if owner is None:
                    return previous_call_soon_threadsafe(
                        callback,
                        *args,
                        context=context,
                    )
                return schedule_owned_callback(
                    owner,
                    previous_call_soon_threadsafe,
                    callback,
                    args,
                    context,
                )

            # Authenticated by identity via _INSTALLED_LOOP_ROUTERS below,
            # not by the callback allowlist; the wrap here only sets the
            # runtime-lifecycle flag while the router runs.
            call_soon_router = mark_runtime_owned_callback(
                call_soon_router,
                expect_unauthenticated=True,
            )
            # Register by identity so ``_is_installed_loop_router`` can
            # recognise these as loop plumbing from any thread.  Must happen
            # after the ``mark_runtime_owned_callback`` rebind above, since
            # that returns a wrapper and it is the wrapper we install.
            #
            # ``run_in_executor_router`` is deliberately NOT registered:
            # nothing ever schedules it *as a callback*, so registering it
            # buys nothing and only widens the set of objects that skip
            # rejection.
            _INSTALLED_LOOP_ROUTERS.update(
                (
                    call_soon_router,
                    call_at_router,
                    call_soon_threadsafe_router,
                )
            )
            state["call_at_router"] = call_at_router
            state["call_soon_router"] = call_soon_router
            state["call_soon_threadsafe_router"] = call_soon_threadsafe_router
            state["run_in_executor_router"] = run_in_executor_router
            _OPERATION_TASK_FACTORY_STATES[self.loop] = state
            self.loop.set_task_factory(router)
            self.loop.call_at = call_at_router  # type: ignore[method-assign]
            self.loop.call_soon = call_soon_router  # type: ignore[method-assign]
            self.loop.call_soon_threadsafe = (  # type: ignore[method-assign]
                call_soon_threadsafe_router
            )
            self.loop.run_in_executor = (  # type: ignore[method-assign]
                run_in_executor_router
            )
        with state["owners_lock"]:
            owners = state.setdefault("owners", set())
            owners.add(self)
            state["owners_snapshot"] = tuple(owners)
            state["refcount"] = int(state.get("refcount", 0) or 0) + 1
        self._factory_state = state

    def create_primary_task(
        self,
        awaitable: Any,
    ) -> asyncio.Future[Any]:
        async def owned_primary() -> Any:
            try:
                return await awaitable
            finally:
                # Capture the exact action-return boundary synchronously. A
                # child or timer that was live here remains an incident even
                # if unrelated cleanup work lets it finish before settlement.
                with self._boundary_lock:
                    self._boundary_closed = True
                    self.boundary_live_children.update(
                        task for task in self.operation_children() if not task.done()
                    )
                    for record in self.owned_scheduled_callbacks():
                        handle = record.get("handle")
                        if (
                            not bool(record.get("fired"))
                            and isinstance(handle, asyncio.Handle)
                            and not handle.cancelled()
                        ):
                            self.boundary_pending_callback_records.append(record)
                            handle.cancel()

        token = _OPERATION_CHILD_TASK_TRACKER.set(self)
        try:
            task = asyncio.ensure_future(owned_primary())
        finally:
            _OPERATION_CHILD_TASK_TRACKER.reset(token)
        self.primary_task = task
        return task

    def operation_children(self) -> Set[asyncio.Future[Any]]:
        with self._boundary_lock:
            return {
                task
                for task in self.created
                if task is not self.primary_task
                and task not in self.baseline
                and not deadline_task_is_result_only(task)
                and not transport_receipt_observer_task_owned(task)
                and not transport_request_task_owned(task)
            }

    def boundary_live_mutation_children(self) -> Set[asyncio.Future[Any]]:
        """Return late boundary children that retain mutation authority."""

        with self._boundary_lock:
            return {
                task
                for task in self.boundary_live_children
                if not deadline_task_is_result_only(task)
                and not transport_receipt_observer_task_owned(task)
                and not transport_request_task_owned(task)
            }

    def owned_scheduled_callbacks(self) -> List[Dict[str, Any]]:
        with self._boundary_lock:
            return list(self.scheduled_callbacks)

    def pending_scheduled_callbacks(self) -> List[asyncio.Handle]:
        return [
            handle
            for record in list(self.scheduled_callbacks)
            if not bool(record.get("fired"))
            and isinstance(
                (handle := record.get("handle")),
                asyncio.Handle,
            )
            and not handle.cancelled()
        ]

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        state = self._factory_state
        with state["owners_lock"]:
            owners = state.setdefault("owners", set())
            owners.discard(self)
            state["owners_snapshot"] = tuple(owners)
            state["refcount"] = max(
                0,
                int(state.get("refcount", 0) or 0) - 1,
            )
            remaining_owners = int(state["refcount"])
        if remaining_owners > 0:
            return
        # Deregistration and state removal must survive a failed restore.
        # Without this, an exception part-way through rebinding the loop left
        # the routers registered forever -- a leak, and worse, stale
        # identities permanently classified as loop plumbing -- while
        # ``_closed`` was already True so no retry could clean up.
        try:
            if self.loop.get_task_factory() is state.get("router"):
                self.loop.set_task_factory(state.get("previous_factory"))
            if self.loop.call_at is state.get("call_at_router"):
                self.loop.call_at = state.get("previous_call_at")  # type: ignore[method-assign]
            if self.loop.call_soon is state.get("call_soon_router"):
                self.loop.call_soon = state.get("previous_call_soon")  # type: ignore[method-assign]
            if self.loop.call_soon_threadsafe is state.get(
                "call_soon_threadsafe_router"
            ):
                self.loop.call_soon_threadsafe = state.get(  # type: ignore[method-assign]
                    "previous_call_soon_threadsafe"
                )
            if self.loop.run_in_executor is state.get("run_in_executor_router"):
                self.loop.run_in_executor = state.get(  # type: ignore[method-assign]
                    "previous_run_in_executor"
                )
        finally:
            for router_key in (
                "call_soon_router",
                "call_at_router",
                "call_soon_threadsafe_router",
                "run_in_executor_router",
            ):
                router = state.get(router_key)
                if router is not None:
                    # Strong references: drop them with the state they own.
                    _INSTALLED_LOOP_ROUTERS.discard(router)
            _OPERATION_TASK_FACTORY_STATES.pop(self.loop, None)


def _detach_task_from_loop_shutdown(
    task: "asyncio.Task[Any]",
) -> bool:
    """Release one revoked optional writer from ``asyncio.run`` shutdown."""

    return detach_task_from_loop_shutdown(task)


def _observe_and_detach_operation_tail(
    future: "asyncio.Future[Any]",
) -> None:
    """Make a revoked, cancellation-resistant tail result-only.

    Operation workers run with a closed task tracker after publication
    authority has been revoked; their late result cannot be committed as an
    action outcome.  Removing only the task's shutdown ownership keeps
    ``asyncio.run`` bounded when a broken optional adapter suppresses
    cancellation indefinitely.
    """

    def observe(completed: "asyncio.Future[Any]") -> None:
        if completed.cancelled():
            return
        try:
            completed.exception()
        except BaseException:
            pass

    candidates = [future]
    source = getattr(future, "_mini_source_task", None)
    if isinstance(source, asyncio.Future) and source is not future:
        candidates.append(source)
    for candidate in candidates:
        try:
            candidate.add_done_callback(observe, context=contextvars.Context())
        except (AttributeError, RuntimeError):
            pass
        if isinstance(candidate, asyncio.Task):
            _detach_task_from_loop_shutdown(candidate)


def _isolated_dispatch_tail_blocks_scheduler(
    task: "asyncio.Future[Any]",
) -> bool:
    """Whether a detached tail may pause dispatch for a bounded grace period.

    Result-only Lean/HTTP adapter work keeps its resource lease and is fenced
    by occupancy, not by a global scheduler halt.  A never-settling transport
    descendant must not consume the run.
    """

    if deadline_task_is_result_only(task):
        return False
    if transport_request_task_owned(task):
        return False
    if transport_receipt_observer_task_owned(task):
        return False
    return True


@dataclass
class MiniSession:
    """Owner of cross-action state for one prove invocation.

    Construct via ``build_session_for_prove_problem`` (M2). M0 ships the
    skeleton with no factory yet — only direct instantiation in tests.

    The session is shared by all actions during one ``run()`` invocation.
    Child sessions (parallel samples, recursive subgoals) are separate
    ``MiniSession`` instances with ``parent`` pointing back; they share Lean,
    provider clients, and proof-cache backing stores when safe, but recursive
    children fork session-local retrieval visibility and receive fresh dossier
    and proof-state objects.

    M0 deliverables: skeleton compiles, run() with zero registered actions
    terminates returning (False, None), and per-iteration recorder records
    fire.
    """

    # Required core state. Most fields are typed Any to avoid pulling
    # the heavyweight imports (Conversation, ProofDossier, ProofSearchState,
    # etc.) into this module's import surface — the session is the
    # coordinator, not the canonical owner of those types' contracts.
    problem: Any = None  # TheoremProblem or a compatible recursive target
    dossier: Any = None  # ProofDossier
    proof_state: Optional[Any] = None  # ProofSearchState | None
    proof_cache: Optional[Any] = None  # MiniVerifiedLemmaCache | None
    conv: Optional[Any] = None  # Conversation | None — bound on first turn

    lean: Any = None  # LeanRunner
    prover_client: Any = None  # OpenAICompatClient
    refiner_client: Optional[Any] = None
    searcher: Optional[Any] = None  # MathlibApiSearcher | None
    recorder: Optional[Any] = None  # RunRecorder | None
    cost_controller: Optional[Any] = None  # CostBudgetController | None
    trace_prefix: str = ""

    # Action registry + per-id budget table. ``actions`` is scanned in
    # priority order by ``select_next_action`` after the frontier-first
    # pass yields nothing.
    actions: List[Action] = field(default_factory=list)
    budgets: Dict[str, ActionBudget] = field(default_factory=dict)

    def __post_init__(self) -> None:
        current_generation = getattr(self.lean, "current_generation", None)
        if callable(current_generation):
            try:
                self.lean = current_generation()
            except Exception:
                pass
        session_ref = weakref.ref(self, _discard_live_mini_session_ref)
        with _LIVE_MINI_SESSION_REFS_LOCK:
            _LIVE_MINI_SESSION_REFS.append(session_ref)

    def planner_job_broker(self, *, create: bool = True) -> Optional[PlannerJobBroker]:
        """Return the process-local broker shared by this recursive lane."""

        owner = getattr(self, "_recursive_lane_authority", None) or self
        broker = getattr(owner, "_mini_planner_job_broker", None)
        if broker is None and create:
            broker = PlannerJobBroker()
            setattr(owner, "_mini_planner_job_broker", broker)
        return broker

    def owns_planner_split_scheduler(self) -> bool:
        """Whether long planner I/O may outlive this action quantum."""

        if self.planner_split_scheduler_owner is not None:
            return bool(self.planner_split_scheduler_owner)
        return self.parent is None and str(self.scope or "problem") not in {
            "subgoal",
            "branch",
        }

    def _owned_planner_job_action(self, expected: str) -> Optional[Action]:
        """Return the local action owning a planner job in this state."""

        broker = self.planner_job_broker(create=False)
        if broker is None:
            return None
        for action in self.actions:
            driver_state = getattr(action, "_recursive_driver_state", None)
            if not isinstance(driver_state, Mapping):
                continue
            if str(driver_state.get("phase") or "") != "planner_job_pending":
                continue
            identity = driver_state.get("planner_job_identity")
            if not isinstance(identity, Mapping):
                continue
            job_id = str(identity.get("job_id") or "").strip()
            request_fingerprint = str(
                identity.get("request_fingerprint") or ""
            ).strip()
            if not job_id or not request_fingerprint:
                continue
            if broker.status(
                job_id,
                request_fingerprint,
            ) == expected:
                return action
        return None

    def _owned_planner_job_status(self, expected: str) -> bool:
        return self._owned_planner_job_action(expected) is not None

    def _planner_terminal_authority_reason(self) -> str:
        """Return durable authority that forbids planner publication."""

        if self._operator_cancelled_dispatch_reuse_fenced:
            return "operator_cancelled_dispatch_reuse_fenced"
        terminal_reason = str(self.terminal_failure_reason or "").strip()
        if terminal_reason:
            return f"terminal_failure:{terminal_reason}"
        if self.root_finalized and self._durable_final_proof():
            return "durable_root_finalized"
        return ""

    def _proof_root_waiting_for_finalization(self) -> bool:
        """Whether root closure must publish before a ready planner result."""

        return bool(
            not self._planner_terminal_authority_reason()
            and self.proof_state is not None
            and self._proof_state_root_solved()
        )

    def _retire_terminal_ready_planner_jobs(self) -> int:
        """Retire exact late receipts after durable search termination.

        The raw provider result has no authority to run proof-producing code
        once an explicit terminal condition or a durable final proof exists.
        Only broker/cursor bookkeeping is retired here; graph, helpers,
        frontier state, and proof budgets remain untouched.
        """

        authority_reason = self._planner_terminal_authority_reason()
        broker = self.planner_job_broker(create=False)
        if not authority_reason or broker is None:
            return 0
        permanently_finalized = authority_reason == "durable_root_finalized"
        retired = 0
        visited_action_ids: set[int] = set()
        while True:
            action = self._owned_planner_job_action("ready")
            if action is None or id(action) in visited_action_ids:
                break
            visited_action_ids.add(id(action))
            driver_state = getattr(action, "_recursive_driver_state", None)
            identity_record = (
                driver_state.get("planner_job_identity")
                if isinstance(driver_state, Mapping)
                else None
            )
            if not isinstance(identity_record, Mapping):
                break
            job_id = str(identity_record.get("job_id") or "").strip()
            request_fingerprint = str(
                identity_record.get("request_fingerprint") or ""
            ).strip()
            result = broker.peek(job_id, request_fingerprint)
            if result is None or not broker.acknowledge(result.identity):
                break

            receipt_identities = getattr(
                action,
                "_planner_job_receipt_identities",
                None,
            )
            if isinstance(receipt_identities, dict):
                receipt_identities.pop((job_id, request_fingerprint), None)
            if hasattr(action, "_pending_planner_job_launch"):
                action._pending_planner_job_launch = None
            if permanently_finalized:
                if hasattr(action, "_nested_execution_frame"):
                    action._nested_execution_frame = {}
                action._recursive_driver_state = {}
                reservations = self.recursive_inflight_reservations
                if isinstance(reservations, dict):
                    reservations.pop(
                        str(getattr(action, "id", "") or ""),
                        None,
                    )
            retired += 1
            self._record_event(
                {
                    "phase": "session_planner_job",
                    "action_id": str(getattr(action, "id", "") or ""),
                    "planner_job_id": job_id,
                    "authority_reason": authority_reason,
                    "durable_cursor_retained": not permanently_finalized,
                    "verdict": "terminal_ready_planner_receipt_retired",
                }
            )
        return retired

    def _owned_missing_planner_recovery_action(self) -> Optional[Action]:
        """Admit one lost-runtime reconstruction past ordinary headroom only."""

        action = self._owned_planner_job_action("missing")
        if action is None:
            return None
        # A durable pending cursor can outlive process-local broker state, but
        # it is never stronger than explicit terminal or proof authority.
        if str(self.terminal_failure_reason or "").strip():
            return None
        if self.root_finalized and self._durable_final_proof():
            return None
        if self._operator_cancelled_dispatch_reuse_fenced:
            return None
        action_id = str(getattr(action, "id", "") or "").strip()
        if (
            self._model_call_deferred_static_action_effective(action_id)
            and not self._clear_paired_model_call_deferred_static_guard(
                action_id,
                reason="missing_planner_runtime_reconstruction",
            )
        ):
            return None
        # Normal scheduler headroom already routes the action through ordinary
        # applicability and budget policy. This exceptional admission exists
        # only to reconstruct a job whose paid cursor survived that headroom.
        if int(self.iteration or 0) < int(self.max_iterations or 0):
            return None
        if self.proof_state is not None and self._proof_state_root_solved():
            return None
        if (
            self.last_giveup_cluster
            and not bool(
                getattr(
                    getattr(self, "conv", None),
                    "allow_helper_decomposition",
                    True,
                )
            )
            and int(self.local_repair_quota_remaining or 0) <= 0
        ):
            return None
        return action

    def _missing_planner_recovery_dispatch_ready(self, action: Action) -> bool:
        """Respect generation retry backoff before recreating a lost job."""

        action_id = str(getattr(action, "id", "") or "").strip()
        if action_id not in self._dispatch_generation_deferred_action_ids:
            return True
        ready_at = float(
            self._dispatch_generation_action_ready_monotonic.get(action_id, 0.0)
            or 0.0
        )
        if time.monotonic() < ready_at:
            return False
        self._release_ready_dispatch_generation_deferrals()
        return action_id not in self._dispatch_generation_deferred_action_ids

    async def _wait_for_owned_planner_change(
        self,
        broker: PlannerJobBroker,
    ) -> None:
        """Wait without bypassing an explicitly configured run governor."""

        remaining = self._run_governor_remaining_s()
        if remaining is None:
            await broker.wait_for_change()
            return
        if remaining <= 0.0:
            return
        try:
            await asyncio.wait_for(
                broker.wait_for_change(),
                timeout=max(0.001, remaining),
            )
        except asyncio.TimeoutError:
            return

    # Loop control.
    iteration: int = 0
    max_iterations: int = 30
    stagnation_counter: int = 0
    max_stagnation: int = 3
    last_proof_state_signature: Optional[str] = None
    fallback_actions_attempted: bool = False
    terminal_failure_reason: str = ""
    terminal_failure_kind: str = ""
    cost_budget_terminal_recorded: bool = False
    # Run-level governance is independent of provider cost.  Elapsed time is
    # accumulated at scheduler boundaries rather than storing an absolute
    # monotonic timestamp.
    # Zero explicitly disables either limit for intentionally unbounded runs.
    run_wall_clock_budget_s: float = 0.0
    no_strong_progress_budget_s: float = 0.0
    run_governor_elapsed_s: float = 0.0
    run_governor_last_strong_progress_elapsed_s: float = 0.0
    run_governor_actions_since_strong_progress: int = 0
    run_governor_terminal_recorded: bool = False
    _run_governor_last_tick_monotonic: float = 0.0
    # ``max_stagnation`` remains an early routing signal: three deterministic
    # misses must not kill a difficult theorem before a model turn runs.  The
    # controller still needs a terminal fixed point, however.  Count only
    # fully paid, non-neutral actions whose complete durable mathematical
    # state is byte-for-byte unchanged.  Any new proof/graph/helper state
    # resets the window.  Twenty-four identical actions is deliberately much
    # larger than the routing threshold while remaining finite for the
    # stopped-run class that accumulated stagnation 30/3 on the same state.
    max_identical_no_progress_actions: int = 24
    identical_no_progress_actions: int = 0
    identical_no_progress_search_signature: str = ""
    identical_no_progress_action_families_seen: Set[str] = field(default_factory=set)
    max_no_progress_semantic_signature_recurrences: int = 24
    max_no_progress_semantic_signatures: int = 256
    no_progress_semantic_signature_counts: Dict[str, int] = field(default_factory=dict)
    no_progress_semantic_signature_order: List[str] = field(default_factory=list)
    no_progress_semantic_signature_action_families: Dict[str, List[str]] = field(
        default_factory=dict
    )
    # ``proof_work`` scopes can reveal arbitrarily many independent child
    # contracts, so aggregate action invocations are not a correctness cap.
    # They must nevertheless bound retries of the *same* executable contract.
    # A changed Lean environment/helper context hashes to a fresh identity.
    max_proof_work_no_progress_attempts: int = 2
    max_proof_work_no_progress_identities: int = 4096
    proof_work_no_progress_attempt_counts: Dict[str, int] = field(default_factory=dict)
    # Monotone maximum repetition count per executable identity.  Recent
    # semantic signatures are intentionally bounded, so they cannot serve as
    # the durable authority that an identity has already exhausted.
    proof_work_no_progress_peak_attempt_counts: Dict[str, int] = field(
        default_factory=dict
    )
    # Conversation turns use the same executable-contract ledger, but count
    # only two identical tool-loop semantic walls.  A changed normalized
    # residual resets the count instead of treating diagnostic improvement as
    # repetition.
    proof_work_no_progress_last_signatures: Dict[str, str] = field(default_factory=dict)
    proof_work_no_progress_signature_history: Dict[str, List[str]] = field(
        default_factory=dict
    )
    proof_work_root_alias_identities_by_base: Dict[str, List[str]] = field(
        default_factory=dict
    )
    proof_work_closed_root_alias_identities: Dict[str, int] = field(
        default_factory=dict
    )
    proof_work_no_progress_attempt_order: List[str] = field(default_factory=list)
    # A permanently-live scoped frontier must not monopolize dispatch forever.
    # Keep every child candidate and its full proof budget, but after this many
    # completed scoped quanta without verified strong progress, interleave one
    # otherwise-applicable root-authoring quantum.  Verified progress resets
    # the streak; a granted root quantum rotates priority back to the child.
    max_scoped_frontier_quanta_before_root_authoring: int = 3
    scoped_frontier_quanta_since_root_authoring: int = 0
    # Cancellation-resistant action/hook tasks retain only a discarded staged
    # session. They stay detached/observed, but they never pause the
    # scheduler. Occupancy still fences overlapping Lean work. This
    # process-local set is never serialized.
    _pending_isolated_dispatch_tails: Set[asyncio.Future[Any]] = field(
        default_factory=set,
        init=False,
        repr=False,
    )
    # Fix 3 (2026-05-22): when ``strict_progress_accounting`` is True,
    # ``outcome.progress=True`` without ``metadata["strong_progress"]=True``
    # is "soft" progress (helper accepted but no root-impactful change).
    # Soft progress is tolerated up to ``max_soft_progress_streak`` before
    # it starts ticking stagnation. Targets the putnam_1978_b2 swamp where
    # bogus contradiction-route helpers kept resetting the counter for ~21
    # minutes before ``adaptive_recursive_fallback`` finally fired.
    # Feature-flagged: defaults False to preserve existing behavior; opt-in
    # via factory or runtime config.
    strict_progress_accounting: bool = False
    soft_progress_streak: int = 0
    max_soft_progress_streak: int = 4
    # H1 (2026-05-08): action ids treated as "fallback" — if stagnation
