    # ----- M0 surface --------------------------------------------------

    def acceptance_preamble(self) -> str:
        """Return the preamble allowed to certify root-level work.

        Delegates to ``_proof_state_acceptance_preamble`` so Putnam-style
        target-context markers cannot certify against a filled checker
        preamble when the prompt-visible body differs.
        """

        conv = self.conv
        if conv is None:
            return ""
        from ensemble_prover.proof_state_executor import (
            _proof_state_acceptance_preamble,
        )

        return _proof_state_acceptance_preamble(conv)

    def register(self, action: Action) -> None:
        """Add an action to the registry and ensure it has a budget entry.

        Default budget (max_invocations=1, max_total_seconds=0.0) is a
        placeholder; M1+ tests should set explicit budgets via
        ``register(action, budget=...)`` once that overload exists.
        """

        self.actions.append(action)
        declared_scope = self._declared_action_budget_scope(action)
        existing_budget = self.budgets.get(action.id)
        if existing_budget is not None:
            # ``set_budget`` is intentionally legal before ``register``.
            # Registration is the point where the action's semantic contract
            # becomes authoritative.
            existing_budget.scope = declared_scope
        else:
            self.budgets[action.id] = ActionBudget(
                max_invocations=1,
                max_total_seconds=0.0,
                scope=declared_scope,
            )

    def set_budget(self, action_id: str, budget: ActionBudget) -> None:
        """Set or replace the budget for an action id."""

        action = self.registered_action(action_id)
        if action is not None:
            budget.scope = self._declared_action_budget_scope(action)
        self.budgets[action_id] = budget

    @staticmethod
    def _declared_action_budget_scope(action: Action) -> str:
        """Return the scheduler-supported budget scope declared by an action."""

        scope = str(getattr(action, "BUDGET_SCOPE", "session") or "session")
        if scope not in {
            "session",
            "theory_need",
            "formal_context",
            "proof_work",
        }:
            raise ValueError(
                f"unsupported action budget scope for {action.id!r}: {scope!r}"
            )
        return scope

    def _reserve_semantic_budget_iteration_headroom(
        self,
        *,
        action_id: str,
        budget: ActionBudget,
        semantic_step_consumed: bool,
    ) -> None:
        """Keep the loop guard from becoming a cross-identity action cap.

        A non-session budget delegates exhaustion to the action's semantic
        identity (for example, one durable theory need). Its configured
        invocation maximum is useful initial sizing, but cannot predict how
        many independent identities a frontier will reveal. After an outcome
        explicitly confirms that it consumed one bounded semantic step,
        reserve exactly one subsequent dispatcher iteration. The action's
        declared semantic guard remains responsible for preventing repetition
        of the same identity; deferrals that consumed no step get no headroom.
        """

        if budget.scope == "session" or not semantic_step_consumed:
            return
        required_max_iterations = int(self.iteration or 0) + 2
        if int(self.max_iterations or 0) >= required_max_iterations:
            return
        old_max_iterations = int(self.max_iterations or 0)
        self.max_iterations = required_max_iterations
        self._record_event(
            {
                "phase": "session_semantic_budget_headroom",
                "iteration": int(self.iteration or 0),
                "action_id": str(action_id or ""),
                "budget_scope": str(budget.scope or ""),
                "old_max_iterations": old_max_iterations,
                "max_iterations": int(self.max_iterations or 0),
                "verdict": "next_semantic_identity_iteration_reserved",
            }
        )

    def configure_no_applicable_recovery(self, total_llm_turn_budget: int) -> None:
        """Configure one-step selector recovery from the real LLM budget.

        Recovery is a scheduler nudge, so each event grants one turn and the
        number of possible nudges is bounded by the caller's complete turn
        budget.  The former hard cap of two could terminate a run with live,
        affordable work remaining; large multi-family sessions reached that
        cap long before their configured provider/cost authority.
        """

        total_budget = max(0, int(total_llm_turn_budget or 0))
        self.max_no_applicable_recoveries = total_budget
        self.no_applicable_recovery_budget_increment = 1 if total_budget > 0 else 0
        if total_budget > 0:
            self.no_applicable_recovery_action_ids = tuple(
                dict.fromkeys(
                    (
                        *self.no_applicable_recovery_action_ids,
                        "conversation_turn_prove",
                        "conversation_turn_refine",
                    )
                )
            )

    def observe_premise_retrieval_record(
        self,
        record: Any,
    ) -> Dict[str, Any]:
        """Store typed premise retrieval telemetry and apply zero-hit policy."""

        if hasattr(record, "metadata") and callable(getattr(record, "metadata")):
            payload = dict(record.metadata() or {})
        elif isinstance(record, dict):
            payload = dict(record)
        else:
            payload = {}
        self.last_premise_retrieval_record = dict(payload)
        policy = str(self.premise_zero_hit_policy or "off").strip().lower()
        if policy not in {"off", "shadow", "enforce"}:
            policy = "off"
        eligible = bool(payload.get("premise_local_micro_theory_candidate"))
        failure_kind = str(payload.get("premise_retrieval_failure_kind") or "").strip()
        guard_reason = ""
        if not eligible:
            if not bool(payload.get("premise_retrieval_enabled", False)):
                guard_reason = "retrieval_disabled"
            elif not bool(payload.get("premise_retrieval_searcher_available", False)):
                guard_reason = "searcher_unavailable"
            elif not str(payload.get("premise_retrieval_query") or "").strip():
                guard_reason = "empty_query"
            elif failure_kind == "search_exception":
                guard_reason = "search_exception"
            elif int(payload.get("premise_retrieval_filtered_hit_count") or 0) > 0:
                guard_reason = "premise_hits_found"
            else:
                guard_reason = failure_kind or "not_eligible"
        metadata: Dict[str, Any] = {
            "premise_zero_hit_policy": policy,
            "premise_zero_hit_eligible": bool(eligible),
            "premise_zero_hit_guard_reason": guard_reason,
            "premise_zero_hit_shadow_recommendation": False,
            "local_micro_theory_activated": False,
            "local_micro_theory_reason": "",
        }
        if not eligible:
            if int(payload.get("premise_retrieval_filtered_hit_count") or 0) > 0:
                self.local_micro_theory_active = False
                self.local_micro_theory_reason = ""
            return metadata
        if policy == "shadow":
            metadata["premise_zero_hit_shadow_recommendation"] = True
            return metadata
        if policy != "enforce":
            return metadata

        self.local_micro_theory_active = True
        self.local_micro_theory_reason = "zero_premise_hits"
        self.local_micro_theory_turns_used = 0
        self.local_micro_theory_max_turns = max(
            0,
            int(self.premise_zero_hit_max_local_turns or 0),
        )
        self.local_micro_theory_library_suppression_exhausted = False
        self._local_micro_theory_prompt_injected = False
        self._local_micro_theory_suppressed_action_ids.clear()
        self.skipped_frontier_work_keys.clear()
        self.skipped_frontier_action_keys.clear()
        self.materialization_pending_frontier_action_keys.clear()
        self.materialization_pending_frontier_logical_keys.clear()
        self.materialization_pending_frontier_action_logical_keys.clear()
        self.materialization_pending_no_applicable_recovery_counts.clear()
        self.materialization_pending_no_applicable_recovery_logical_keys.clear()
        self.materialization_pending_no_applicable_recovery_counts.clear()
        metadata.update(
            {
                "local_micro_theory_activated": True,
                "local_micro_theory_reason": self.local_micro_theory_reason,
                "local_micro_theory_max_turns": self.local_micro_theory_max_turns,
            }
        )
        self._record_event(
            {
                "phase": "session_local_micro_theory",
                "iteration": self.iteration,
                "reason": self.local_micro_theory_reason,
                "premise_retrieval_failure_kind": failure_kind,
                "premise_retrieval_raw_hit_count": int(
                    payload.get("premise_retrieval_raw_hit_count") or 0
                ),
                "premise_retrieval_filtered_hit_count": int(
                    payload.get("premise_retrieval_filtered_hit_count") or 0
                ),
                "verdict": "activated",
            }
        )
        return metadata

    def local_micro_theory_library_suppression_active(self) -> bool:
        """Return whether broad library-first tools should be suppressed."""

        if not bool(self.local_micro_theory_active):
            return False
        if not bool(self.premise_zero_hit_suppress_library_first):
            return False
        max_turns = max(0, int(self.local_micro_theory_max_turns or 0))
        if max_turns <= 0:
            return False
        return int(self.local_micro_theory_turns_used or 0) < max_turns

    def install_theory_bundles(self, bundle_ids: Iterable[str]) -> bool:
        """Atomically install a verified theory snapshot into both preambles."""

        prepared = self.prepare_theory_bundles(bundle_ids)
        if prepared is None:
            return False
        return self.apply_prepared_theory_bundles(prepared)

    def prepare_theory_bundles(
        self,
        bundle_ids: Iterable[str],
    ) -> Optional[Tuple[Any, ...]]:
        """Resolve and snapshot a theory context without mutating the session."""

        library = self.theory_library
        conv = self.conv
        if library is None or conv is None:
            return None
        from ensemble_prover.mini_theory import TheoryContextPair

        pair = self.theory_context_pair
        if pair is None:
            pair = TheoryContextPair.from_preambles(
                llm_preamble=str(getattr(conv, "preamble", "") or ""),
                lean_preamble=str(getattr(conv, "lean_preamble", "") or ""),
            )
        requested = tuple(
            dict.fromkeys(
                str(item or "").strip()
                for item in bundle_ids
                if str(item or "").strip()
            )
        )
        prepare_context = getattr(library, "prepare_context", None)
        if callable(prepare_context):
            selected, snapshot = prepare_context(pair, bundle_ids=requested)
        else:
            selected = library.select_context(pair, bundle_ids=requested)
            snapshot = library.snapshot(selected.lean.bundle_ids)
        return requested, pair, selected, snapshot

    def apply_prepared_theory_bundles(
        self,
        prepared: Tuple[Any, ...],
    ) -> bool:
        """Commit a prepared context transactionally, without store I/O."""

        requested, pair, selected, snapshot = prepared
        conv = self.conv
        if conv is None:
            return False
        changed = selected.snapshot_hash != pair.snapshot_hash
        before = self._capture_theory_installation_state()
        try:
            self.theory_context_pair = selected
            self.theory_imported_bundle_ids = selected.lean.bundle_ids
            self.theory_snapshot = tuple(snapshot)
            conv.preamble = selected.llm.render()
            conv.lean_preamble = selected.lean.render()
            if self.dossier is not None:
                previous_environment_hash = str(
                    self.dossier.current_lean_environment_hash or ""
                )
                self.dossier.record_lean_environment(
                    text_hash(conv.lean_preamble),
                    extends_environment_hash=previous_environment_hash,
                    environment_source_text=conv.lean_preamble,
                )
            set_active_bundle_ids = getattr(
                self.searcher,
                "set_active_bundle_ids",
                None,
            )
            if callable(set_active_bundle_ids):
                set_active_bundle_ids(self.theory_imported_bundle_ids)
            if changed:
                self.skipped_frontier_work_keys.clear()
                self.skipped_frontier_action_keys.clear()
                self._increment_dossier_metric(
                    "mini_theory_bundle_imported", len(requested)
                )
                self._record_event(
                    {
                        "phase": "domain_theory",
                        "iteration": self.iteration,
                        "bundle_ids": list(requested),
                        "module_names": list(selected.lean.theory_imports),
                        "context_snapshot_hash": selected.snapshot_hash,
                        "verdict": "verified_theory_context_installed",
                    }
                )
        except BaseException as install_error:
            try:
                self._restore_theory_installation_state(before)
            except BaseException as rollback_exc:
                install_error.add_note(
                    "theory installation rollback was incomplete: "
                    f"{type(rollback_exc).__name__}: {rollback_exc}"
                )
                raise install_error from rollback_exc
            raise
        return changed

    def _capture_theory_installation_state(self) -> Dict[str, Any]:
        """Capture every parent-visible field changed by theory installation."""

        conv = self.conv
        dossier = self.dossier
        active_bundle_ids = tuple(self.theory_imported_bundle_ids or ())
        active_getter = getattr(self.searcher, "active_bundle_ids", None)
        if callable(active_getter):
            try:
                active_bundle_ids = tuple(active_getter() or ())
            except Exception:
                active_bundle_ids = tuple(self.theory_imported_bundle_ids or ())
        return {
            "theory_context_pair": self.theory_context_pair,
            "theory_imported_bundle_ids": tuple(self.theory_imported_bundle_ids or ()),
            "theory_snapshot": copy.deepcopy(tuple(self.theory_snapshot or ())),
            "conv_preamble": str(getattr(conv, "preamble", "") or ""),
            "conv_lean_preamble": str(getattr(conv, "lean_preamble", "") or ""),
            "dossier_current_lean_environment_hash": str(
                getattr(dossier, "current_lean_environment_hash", "") or ""
            ),
            "dossier_lean_environment_ancestor_hashes": copy.deepcopy(
                getattr(dossier, "lean_environment_ancestor_hashes", {}) or {}
            ),
            "dossier_mini_theory_context_hash": str(
                getattr(dossier, "mini_theory_context_hash", "") or ""
            ),
            "dossier_mini_theory_snapshot": copy.deepcopy(
                tuple(getattr(dossier, "mini_theory_snapshot", ()) or ())
            ),
            "dossier_tool_metrics": copy.deepcopy(
                dict(getattr(dossier, "tool_metrics", {}) or {})
            ),
            "skipped_frontier_work_keys": copy.deepcopy(
                self.skipped_frontier_work_keys
            ),
            "skipped_frontier_action_keys": copy.deepcopy(
                self.skipped_frontier_action_keys
            ),
            "searcher_active_bundle_ids": active_bundle_ids,
        }

    def _restore_theory_installation_state(
        self,
        state: Dict[str, Any],
    ) -> None:
        """Restore a prior theory view after a failed/aborted commit."""

        self.theory_context_pair = state.get("theory_context_pair")
        self.theory_imported_bundle_ids = tuple(
            state.get("theory_imported_bundle_ids") or ()
        )
        self.theory_snapshot = copy.deepcopy(tuple(state.get("theory_snapshot") or ()))
        if self.conv is not None:
            self.conv.preamble = str(state.get("conv_preamble") or "")
            self.conv.lean_preamble = str(state.get("conv_lean_preamble") or "")
        if self.dossier is not None:
            self.dossier.current_lean_environment_hash = str(
                state.get("dossier_current_lean_environment_hash") or ""
            )
            self.dossier.lean_environment_ancestor_hashes = copy.deepcopy(
                state.get("dossier_lean_environment_ancestor_hashes") or {}
            )
            self.dossier.mini_theory_context_hash = str(
                state.get("dossier_mini_theory_context_hash") or ""
            )
            self.dossier.mini_theory_snapshot = copy.deepcopy(
                tuple(state.get("dossier_mini_theory_snapshot") or ())
            )
            self.dossier.tool_metrics = copy.deepcopy(
                dict(state.get("dossier_tool_metrics") or {})
            )
        self.skipped_frontier_work_keys = copy.deepcopy(
            state.get("skipped_frontier_work_keys") or set()
        )
        self.skipped_frontier_action_keys = copy.deepcopy(
            state.get("skipped_frontier_action_keys") or set()
        )
        set_active_bundle_ids = getattr(
            self.searcher,
            "set_active_bundle_ids",
            None,
        )
        if callable(set_active_bundle_ids):
            set_active_bundle_ids(tuple(state.get("searcher_active_bundle_ids") or ()))

    def local_micro_theory_selected_ticket_requires_api_grounding(self) -> bool:
        """Return True when the selected repair ticket must use Mathlib lookup."""

        if not bool(self.premise_zero_hit_allow_api_grounding_after_lean_failure):
            return False
        ticket = self._active_repair_ticket()
        if ticket is None:
            return False
        metadata = dict(getattr(ticket, "metadata", {}) or {})
        return bool(
            metadata.get("requires_api_search_for_unknown_identifier")
            and str(metadata.get("unknown_identifier") or "").strip()
        )

    def consume_local_micro_theory_suppressed_turn(self) -> Dict[str, Any]:
        """Consume one bounded local-micro-theory suppression turn."""

        if not self.local_micro_theory_library_suppression_active():
            return {}
        self.local_micro_theory_turns_used = (
            int(self.local_micro_theory_turns_used or 0) + 1
        )
        max_turns = max(1, int(self.local_micro_theory_max_turns or 1))
        exhausted = self.local_micro_theory_turns_used >= max_turns
        if exhausted:
            self.local_micro_theory_library_suppression_exhausted = True
            self.skipped_frontier_work_keys.clear()
            self.skipped_frontier_action_keys.clear()
            self.materialization_pending_frontier_action_keys.clear()
            self.materialization_pending_frontier_logical_keys.clear()
            self.materialization_pending_frontier_action_logical_keys.clear()
            self.materialization_pending_no_applicable_recovery_logical_keys.clear()
            self.materialization_pending_no_applicable_recovery_counts.clear()
            self._local_micro_theory_suppressed_action_ids.clear()
        self._increment_dossier_metric(
            "mini_premise_zero_hit_library_search_suppressed",
            1,
        )
        self._record_event(
            {
                "phase": "session_local_micro_theory",
                "iteration": self.iteration,
                "turns_used": int(self.local_micro_theory_turns_used or 0),
                "max_turns": max_turns,
                "reason": self.local_micro_theory_reason,
                "verdict": (
                    "library_suppression_exhausted"
                    if exhausted
                    else "library_search_suppressed"
                ),
            }
        )
        return {
            "local_micro_theory_search_suppressed": True,
            "local_micro_theory_turns_used": int(
                self.local_micro_theory_turns_used or 0
            ),
            "local_micro_theory_max_turns": max_turns,
            "local_micro_theory_suppression_exhausted": bool(exhausted),
        }

    def local_micro_theory_prompt_text(self) -> str:
        """Return a one-shot prompt nudging construction of local math."""

        if not bool(self.local_micro_theory_active):
            return ""
        if bool(self._local_micro_theory_prompt_injected):
            return ""
        self._local_micro_theory_prompt_injected = True
        return (
            "Early typed Mathlib premise retrieval found no usable theorem or "
            "lemma candidates for this target. For this bounded attempt, build "
            "the missing local math directly: state small helper lemmas or "
            "`have`/`suffices` facts, prove them in Lean, and use `try_lean` "
            "to validate the construction. Avoid broad Mathlib citation "
            "search unless this turn is repairing a concrete unknown "
            "identifier."
        )

    def _local_micro_theory_action_would_skip(self, action_id: str) -> bool:
        """Return whether local construction mode suppresses this action."""

        action_key = str(action_id or "").strip()
        if action_key != "proof_state_retrieval":
            return False
        return self.local_micro_theory_library_suppression_active()

    def _local_micro_theory_should_skip_action(
        self,
        action_id: str,
        *,
        context: str,
    ) -> bool:
        """Skip library-only retrieval lanes during bounded local construction."""

        action_key = str(action_id or "").strip()
        if not self._local_micro_theory_action_would_skip(action_key):
            return False
        if action_key not in self._local_micro_theory_suppressed_action_ids:
            self._local_micro_theory_suppressed_action_ids.add(action_key)
            self._increment_dossier_metric(
                "mini_premise_zero_hit_proof_state_retrieval_suppressed",
                1,
            )
            self._record_event(
                {
                    "phase": "session_local_micro_theory",
                    "iteration": self.iteration,
                    "action_id": action_key,
                    "context": str(context or ""),
                    "reason": self.local_micro_theory_reason,
                    "verdict": "library_only_action_suppressed",
                }
            )
        return True

    def _update_local_micro_theory_after_outcome(
        self,
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
    ) -> None:
        """Release local-micro-theory suppression once it has produced value."""

        if not bool(self.local_micro_theory_active):
            return
        strong_progress = bool(metadata.get("strong_progress"))
        accepted_helper_progress = bool(outcome.helpers_added and strong_progress)
        if not (outcome.solved or accepted_helper_progress):
            return
        self.local_micro_theory_active = False
        self.local_micro_theory_reason = ""
        self.local_micro_theory_library_suppression_exhausted = False
        self.skipped_frontier_work_keys.clear()
        self.skipped_frontier_action_keys.clear()
        self.materialization_pending_frontier_action_keys.clear()
        self.materialization_pending_frontier_logical_keys.clear()
        self.materialization_pending_frontier_action_logical_keys.clear()
        self.materialization_pending_no_applicable_recovery_logical_keys.clear()
        self.materialization_pending_no_applicable_recovery_counts.clear()
        self._local_micro_theory_suppressed_action_ids.clear()
        self._increment_dossier_metric(
            "mini_premise_zero_hit_local_micro_theory_unlocked",
            1,
        )
        self._record_event(
            {
                "phase": "session_local_micro_theory",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "helpers_added_count": len(outcome.helpers_added),
                "solved": bool(outcome.solved),
                "verdict": "unlocked_by_progress",
            }
        )

    def registered_invocation_budget_total(self) -> int:
        """Return the finite invocation budget represented by registered actions."""

        total = 0
        seen: Set[str] = set()
        for action in self.actions:
            action_id = str(getattr(action, "id", "") or "")
            if not action_id or action_id in seen:
                continue
            seen.add(action_id)
            budget = self.budgets.get(action_id)
            if budget is None:
                continue
            try:
                max_invocations = int(budget.max_invocations)
            except Exception:
                continue
            if max_invocations > 0:
                total += max_invocations
        return total

    def expand_max_iterations_to_action_budgets(self, *, headroom: int = 5) -> int:
        """Align the loop guard with registered action invocation budgets.

        ``max_iterations`` remains a runaway guard; it should not be a smaller
        budget than the first-class action budgets that actually govern work.
        """

        target = self.registered_invocation_budget_total() + max(0, int(headroom or 0))
        if target > int(self.max_iterations or 0):
            self.max_iterations = target
        return int(self.max_iterations or 0)

    def _cost_budget_continuation_enabled(self) -> bool:
        """Whether local scheduler ceilings should yield to the dollar budget."""

        if not bool(self.conversation_budget_topups_enabled):
            return False
        controller = getattr(self, "cost_controller", None)
        if controller is None:
            return False
        budget_enabled = getattr(controller, "budget_enabled", False)
        try:
            if callable(budget_enabled):
                budget_enabled = budget_enabled()
        except Exception:
            return False
        return bool(budget_enabled)

    def _cost_budget_immediate_capacity_available(self) -> bool:
        """Return whether a cost-governed continuation can dispatch now."""

        controller = getattr(self, "cost_controller", None)
        if controller is None:
            return False
        remaining = getattr(controller, "remaining_usd", None)
        if not callable(remaining):
            return True
        try:
            value = remaining()
        except Exception:
            return True
        if value is None:
            return True
        try:
            return float(value) > 0.0
        except Exception:
            return True

    def _cost_governed_action_ids(
        self,
        action_ids: Optional[Sequence[str]] = None,
    ) -> Tuple[str, ...]:
        """Return registered actions that can receive cost-governed headroom."""

        explicit = tuple(
            clean
            for clean in (
                str(action_id or "").strip() for action_id in (action_ids or ())
            )
            if clean
        )
        if explicit:
            preferred = explicit
        else:
            preferred = (
                "root_exact_helper",
                "graph_route_assembly",
                "inter_turn_assembly",
                "helper_only_salvage",
                "proof_state_retrieval",
                "child_closure",
                "lemma_dag_decompose",
                "graph_recursive_decompose",
                "recursive_helper_prover",
                "recursive_controller",
                "adaptive_recursive_fallback",
                "conversation_turn_prove",
                "conversation_turn_refine",
            )
            preferred = preferred + tuple(action.id for action in self.actions)
        registered = {str(getattr(action, "id", "") or "") for action in self.actions}
        out: List[str] = []
        seen: Set[str] = set()
        for action_id in preferred:
            clean = str(action_id or "").strip()
            if not clean or clean in seen or clean not in registered:
                continue
            seen.add(clean)
            out.append(clean)
        return tuple(out)

    def _cost_governed_static_llm_action_ids(self) -> Tuple[str, ...]:
        preferred = (
            "conversation_turn_prove",
            "conversation_turn_refine",
            "conversation_turn",
        )
        registered = {str(getattr(action, "id", "") or "") for action in self.actions}
        out: List[str] = []
        seen: Set[str] = set()
        for action_id in preferred + tuple(action.id for action in self.actions):
            clean = str(action_id or "").strip()
            if not clean or clean in seen or clean not in registered:
                continue
            if not clean.startswith("conversation_turn"):
                continue
            seen.add(clean)
            out.append(clean)
        return tuple(out)

    def _select_cost_governed_forced_static_action(
        self,
        *,
        consume: bool,
        context: str,
        ignore_budget: bool = False,
    ) -> Optional[Action]:
        """Select an LLM/root-authoring lane after a cost-governed grant."""

        if self._has_static_suppressing_frontier_work():
            if consume:
                self._record_event(
                    {
                        "phase": "session_cost_governed_continuation",
                        "iteration": self.iteration,
                        "context": str(context or ""),
                        "verdict": "forced_static_yielded_to_scoped_frontier",
                    }
                )
            return None
        saved_target = self.selected_work_item
        saved_action_id = self.selected_work_item_action_id
        saved_record = dict(self.selected_work_item_record)
        for action_id in self._cost_governed_static_llm_action_ids():
            action = self.registered_action(action_id)
            if action is None:
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            budget = self.budgets.get(action.id)
            if not ignore_budget and budget is not None and budget.exhausted():
                continue
            self._clear_selected_work_item()
            if not self._safe_is_applicable(action, context=context):
                continue
            if consume:
                self.cost_governed_force_static_conversation_turns = max(
                    0,
                    int(self.cost_governed_force_static_conversation_turns or 0) - 1,
                )
                self._increment_dossier_metric(
                    "mini_session_cost_governed_forced_static_conversation",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_cost_governed_continuation",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "remaining_forced_static_conversation_turns": int(
                            self.cost_governed_force_static_conversation_turns or 0
                        ),
                        "verdict": "forced_static_conversation_selected",
                    }
                )
                return action
            self.selected_work_item = saved_target
            self.selected_work_item_action_id = saved_action_id
            self.selected_work_item_record = saved_record
            return action
        self.selected_work_item = saved_target
        self.selected_work_item_action_id = saved_action_id
        self.selected_work_item_record = saved_record
        return None

    def _cost_governed_static_dispatch_available(self) -> bool:
        return (
            self._select_cost_governed_forced_static_action(
                consume=False,
                context="cost_governed_dispatch_probe",
            )
            is not None
        )

    def _cost_governed_static_dispatch_lane_exists(self) -> bool:
        return (
            self._select_cost_governed_forced_static_action(
                consume=False,
                context="cost_governed_dispatch_lane_probe",
                ignore_budget=True,
            )
            is not None
        )

    @staticmethod
    def _cost_governed_reason_forces_static_dispatch(reason: str) -> bool:
        clean = str(reason or "").strip()
        if clean.startswith("no_applicable_action:"):
            return False
        return clean in {
            "all_action_budgets_exhausted",
            "lean_infra_error_cap",
            "max_iterations_reached",
            "root_solved_without_finalization",
        }

    def _cost_governed_requires_serviceable_frontier(
        self,
        *,
        reason: str,
        released_policy: bool,
    ) -> bool:
        clean = str(reason or "").strip()
        return bool(
            released_policy
            or clean
            in {
                "all_action_budgets_exhausted",
                "repair_policy_narrowing_no_applicable",
            }
        )

    def _has_static_suppressing_frontier_work(self) -> bool:
        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        frontier_offset = 0
        for _frontier_page in range(40):
            frontier_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=False,
            )
            if not frontier_items:
                break
            if any(
                self._frontier_work_suppresses_static_conversation(work_item)
                for work_item in frontier_items
            ):
                return True
            if not offset_supported:
                break
            frontier_offset += len(frontier_items)
        return False

    def _record_cost_governed_static_suppressed(
        self,
        *,
        reason: str,
        suppression_reason: str,
    ) -> None:
        self._increment_dossier_metric(
            "mini_session_cost_governed_static_no_serviceable_work_suppressed",
            1,
        )
        self._record_event(
            {
                "phase": "session_cost_governed_continuation",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "suppression_reason": str(suppression_reason or ""),
                "deferred_static_action_ids": sorted(
                    str(action_id)
                    for action_id in self.model_call_deferred_static_action_ids
                    if str(action_id or "").strip()
                ),
                "deferred_frontier_action_count": len(
                    self.model_call_deferred_frontier_action_keys
                ),
                "verdict": "static_dispatch_suppressed_no_serviceable_work",
            }
        )

    def _release_cost_governed_blocking_repair_policy(
        self,
        *,
        reason: str,
        emit: bool = True,
    ) -> bool:
        """Release a repair-narrowing gate that has no scoped way forward."""

        if not self.repair_policy_narrowing_required:
            return False
        if self._has_repair_policy_narrowing_candidate():
            return False
        if not self.repair_policy_narrowing_required:
            # The exact-scope reconciler already performed and recorded the
            # release.  Report no local release so a caller's rollback
            # snapshot cannot resurrect the stale gate.
            return False
        if self._repair_policy_child_adaptive_fallback_available():
            return False
        if self._materialize_repair_policy_narrowing_scope():
            return False
        old_reason = str(self.repair_policy_narrowing_reason or "")
        old_selected = dict(self.repair_policy_narrowing_selected_work_record)
        self.repair_policy_narrowing_required = False
        self.repair_policy_narrowing_reason = ""
        self.repair_policy_narrowing_selected_work_record = {}
        self.repair_policy_narrowing_scope_identity = {}
        self.fallback_actions_attempted = False
        if emit:
            self._increment_dossier_metric(
                "mini_session_cost_governed_repair_policy_released",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "released_repair_policy_reason": old_reason,
                    "selected_work_item": old_selected,
                    "verdict": "repair_policy_narrowing_released",
                }
            )
        return True

    def _grant_cost_governed_continuation_budget(
        self,
        *,
        reason: str,
        action_ids: Optional[Sequence[str]] = None,
        require_unresolved_work: bool = True,
    ) -> bool:
        """Top up local scheduler budgets while the cost budget is authoritative."""

        if not self._cost_budget_continuation_enabled():
            return False
        if not self._cost_budget_immediate_capacity_available():
            self._increment_dossier_metric(
                "mini_session_cost_governed_no_cost_capacity",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "verdict": "no_cost_budget_capacity",
                }
            )
            return False
        # Livelock backstops: refuse to keep granting when prior grants have
        # not produced a single dispatched action.  The signature gate is the
        # primary invariant: retry budgets are scheduling state and do not
        # count as mathematical/search progress.  The numeric bound remains a
        # numeric bound remains a secondary fail-safe.
        bound = max(0, int(self.max_cost_governed_continuations_without_action or 0))
        if bound and int(self.cost_governed_continuations_without_action or 0) >= bound:
            self._increment_dossier_metric(
                "mini_session_cost_governed_continuation_without_action_exhausted",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "grants_without_action": int(
                        self.cost_governed_continuations_without_action or 0
                    ),
                    "max_grants_without_action": bound,
                    "verdict": "cost_governed_continuation_without_action_exhausted",
                }
            )
            return False
        if require_unresolved_work and not self._has_unresolved_search_work():
            return False
        progress_signature = self._durable_search_progress_signature()
        if (
            int(self.cost_governed_continuations_without_action or 0) > 0
            and progress_signature
            and progress_signature
            == str(self.last_cost_governed_continuation_progress_signature or "")
        ):
            self._increment_dossier_metric(
                "mini_session_cost_governed_unchanged_progress_refused",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "progress_signature": progress_signature,
                    "grants_without_action": int(
                        self.cost_governed_continuations_without_action or 0
                    ),
                    "verdict": "unchanged_durable_progress_refused",
                }
            )
            return False

        policy_snapshot = (
            bool(self.repair_policy_narrowing_required),
            str(self.repair_policy_narrowing_reason or ""),
            dict(self.repair_policy_narrowing_selected_work_record),
            dict(self.repair_policy_narrowing_scope_identity),
            bool(self.fallback_actions_attempted),
        )

        def rollback_released_policy() -> None:
            (
                required,
                policy_reason,
                selected_record,
                scope_identity,
                fallback_attempted,
            ) = policy_snapshot
            self.repair_policy_narrowing_required = required
            self.repair_policy_narrowing_reason = policy_reason
            self.repair_policy_narrowing_selected_work_record = selected_record
            self.repair_policy_narrowing_scope_identity = scope_identity
            self.fallback_actions_attempted = fallback_attempted

        released_policy = self._release_cost_governed_blocking_repair_policy(
            reason=reason,
            emit=False,
        )
        target_action_ids = self._cost_governed_action_ids(action_ids)
        if not target_action_ids:
            if released_policy:
                rollback_released_policy()
            return False

        force_static_dispatch = self._cost_governed_reason_forces_static_dispatch(
            reason
        )
        if force_static_dispatch and self._has_static_suppressing_frontier_work():
            force_static_dispatch = False
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "verdict": "forced_static_yielded_to_scoped_frontier",
                }
            )
        if (
            force_static_dispatch
            and not self._cost_governed_static_dispatch_lane_exists()
        ):
            if released_policy:
                rollback_released_policy()
            self._increment_dossier_metric(
                "mini_session_cost_governed_no_dispatch_lane",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "verdict": "no_dispatchable_static_llm_lane",
                }
            )
            return False

        scoped_serviceability_record = (
            dict(policy_snapshot[2])
            if (
                released_policy
                or str(reason or "").strip() == "repair_policy_narrowing_no_applicable"
            )
            else None
        )
        if self._cost_governed_requires_serviceable_frontier(
            reason=reason,
            released_policy=released_policy,
        ) and not self._has_serviceable_no_applicable_recovery_work(
            target_action_ids,
            selected_work_record=scoped_serviceability_record,
        ):
            if released_policy:
                rollback_released_policy()
            suppression_reason = "no_serviceable_frontier_work"
            self.last_failure_reason = suppression_reason
            self._record_cost_governed_static_suppressed(
                reason=reason,
                suppression_reason=suppression_reason,
            )
            return False

        increment = max(
            4,
            int(self.no_applicable_recovery_budget_increment or 0),
            int(self.max_no_applicable_recoveries or 0),
        )
        budget_grants: Dict[str, Dict[str, Any]] = {}
        total_granted = 0
        budget_snapshots: Dict[str, Dict[str, Any]] = {}
        action_prompt_budget_snapshots: Dict[str, Dict[str, Any]] = {}
        pool_snapshots: Dict[str, int] = {}
        conv_turn_budget_snapshot: Optional[int] = None

        def snapshot_budget(action_id: str) -> None:
            if action_id in budget_snapshots:
                return
            budget = self.budgets.get(action_id)
            if budget is None:
                budget_snapshots[action_id] = {"exists": False}
                return
            budget_snapshots[action_id] = {
                "exists": True,
                "max_invocations": int(budget.max_invocations),
                "max_total_seconds": float(budget.max_total_seconds),
                "invocations": int(budget.invocations),
                "total_seconds": float(budget.total_seconds),
                "last_failure_reason": str(budget.last_failure_reason or ""),
                "scope": str(budget.scope or "session"),
            }

        def snapshot_prompt_budget(action_id: str, action: Action) -> None:
            if action_id in action_prompt_budget_snapshots:
                return
            if not hasattr(action, "max_turns_for_budget"):
                return
            action_prompt_budget_snapshots[action_id] = {
                "exists": True,
                "value": int(getattr(action, "max_turns_for_budget", 0) or 0),
            }

        def snapshot_pool_attr(attr: str) -> None:
            clean = str(attr or "").strip()
            if not clean or clean in pool_snapshots or not hasattr(self, clean):
                return
            pool_snapshots[clean] = int(getattr(self, clean, 0) or 0)

        def rollback_budget_grants() -> None:
            for action_id, snapshot in budget_snapshots.items():
                if not snapshot.get("exists"):
                    self.budgets.pop(action_id, None)
                    continue
                budget = self.budgets.get(action_id)
                if budget is None:
                    budget = ActionBudget(
                        max_invocations=0,
                        max_total_seconds=0.0,
                        scope=str(snapshot.get("scope") or "session"),
                    )
                    self.budgets[action_id] = budget
                budget.max_invocations = int(snapshot["max_invocations"])
                budget.max_total_seconds = float(snapshot["max_total_seconds"])
                budget.invocations = int(snapshot["invocations"])
                budget.total_seconds = float(snapshot["total_seconds"])
                budget.last_failure_reason = str(snapshot["last_failure_reason"])
                budget.scope = str(snapshot.get("scope") or "session")
            for action_id, snapshot in action_prompt_budget_snapshots.items():
                action = self.registered_action(action_id)
                if action is not None and snapshot.get("exists"):
                    setattr(action, "max_turns_for_budget", int(snapshot["value"]))
            conv = getattr(self, "conv", None)
            if conv is not None and conv_turn_budget_snapshot is not None:
                try:
                    conv.turn_budget = conv_turn_budget_snapshot
                except Exception:
                    pass
            for attr, value in pool_snapshots.items():
                setattr(self, attr, value)
            if released_policy:
                rollback_released_policy()

        conv = getattr(self, "conv", None)
        if conv is not None:
            try:
                conv_turn_budget_snapshot = int(getattr(conv, "turn_budget", 0) or 0)
            except Exception:
                conv_turn_budget_snapshot = None
        for action_id in target_action_ids:
            action = self.registered_action(action_id)
            if action is None:
                continue
            snapshot_budget(action_id)
            snapshot_prompt_budget(action_id, action)
            budget = self.budgets.get(action_id)
            if budget is None:
                budget = ActionBudget(
                    max_invocations=max(1, increment),
                    max_total_seconds=0.0,
                    scope=self._declared_action_budget_scope(action),
                )
                self.budgets[action_id] = budget
            old_max = int(budget.max_invocations)
            old_invocations = int(budget.invocations)
            granted = 0
            if budget.max_invocations >= 0:
                new_max = max(old_max + increment, old_invocations + increment)
                granted = max(0, new_max - max(old_max, old_invocations))
                budget.max_invocations = new_max

            seconds_granted = 0.0
            if (
                budget.max_total_seconds > 0
                and budget.total_seconds >= budget.max_total_seconds
            ):
                old_seconds = float(budget.max_total_seconds)
                estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
                seconds_granted = max(30.0, float(increment) * max(1.0, estimate))
                budget.max_total_seconds = float(budget.total_seconds) + seconds_granted
                seconds_granted = max(
                    0.0,
                    float(budget.max_total_seconds) - old_seconds,
                )

            prompt_turn_budget_granted = 0
            if action_id.startswith("conversation_turn") and hasattr(
                action,
                "max_turns_for_budget",
            ):
                old_prompt_budget = int(getattr(action, "max_turns_for_budget", 0) or 0)
                new_prompt_budget = max(
                    old_prompt_budget + increment,
                    old_invocations + increment,
                    int(budget.max_invocations if budget.max_invocations >= 0 else 0),
                )
                if new_prompt_budget > old_prompt_budget:
                    setattr(action, "max_turns_for_budget", new_prompt_budget)
                    prompt_turn_budget_granted = new_prompt_budget - old_prompt_budget
                    if conv is not None:
                        try:
                            conv.turn_budget = max(
                                int(getattr(conv, "turn_budget", 0) or 0),
                                new_prompt_budget,
                            )
                        except Exception:
                            pass

            pool_granted = 0
            if self._is_graph_recursive_action(action) and hasattr(
                self,
                "graph_recursive_decompose_remaining",
            ):
                old_remaining = int(
                    getattr(self, "graph_recursive_decompose_remaining", 0) or 0
                )
                if old_remaining <= 0:
                    snapshot_pool_attr("graph_recursive_decompose_remaining")
                    self.graph_recursive_decompose_remaining = old_remaining + increment
                    pool_granted += increment
            recursive_pool_attr = str(getattr(action, "budget_attr", "") or "").strip()
            if recursive_pool_attr and hasattr(self, recursive_pool_attr):
                old_remaining = int(getattr(self, recursive_pool_attr, 0) or 0)
                if old_remaining <= 0:
                    snapshot_pool_attr(recursive_pool_attr)
                    setattr(self, recursive_pool_attr, old_remaining + increment)
                    pool_granted += increment

            if (
                granted <= 0
                and seconds_granted <= 0
                and pool_granted <= 0
                and prompt_turn_budget_granted <= 0
            ):
                continue
            total_granted += int(max(granted, pool_granted, prompt_turn_budget_granted))
            budget_grants[action_id] = {
                "old_max_invocations": old_max,
                "new_max_invocations": int(budget.max_invocations),
                "invocations": old_invocations,
                "granted_invocations": int(granted),
                "granted_internal_pool": int(pool_granted),
                "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                "granted_seconds": round(seconds_granted, 4),
            }

        if not budget_grants and not released_policy:
            return False

        if force_static_dispatch:
            if not self._cost_governed_static_dispatch_available():
                rollback_budget_grants()
                self._increment_dossier_metric(
                    "mini_session_cost_governed_no_dispatch_lane",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_cost_governed_continuation",
                        "iteration": self.iteration,
                        "reason": str(reason or ""),
                        "verdict": "no_dispatchable_static_llm_lane",
                    }
                )
                return False
            self.cost_governed_force_static_conversation_turns = max(
                int(self.cost_governed_force_static_conversation_turns or 0),
                1,
            )
        if released_policy:
            self._increment_dossier_metric(
                "mini_session_cost_governed_repair_policy_released",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "released_repair_policy_reason": policy_snapshot[1],
                    "selected_work_item": dict(policy_snapshot[2]),
                    "verdict": "repair_policy_narrowing_released",
                }
            )
        self.fallback_actions_attempted = False
        self.stagnation_counter = 0
        self.soft_progress_streak = 0
        self.consumed_frontier_work_keys.clear()
        self.skipped_frontier_work_keys.clear()
        self.consumed_frontier_action_keys.clear()
        materialization_pending_action_keys = set(
            getattr(self, "materialization_pending_frontier_action_keys", set())
            or set()
        )
        materialization_pending_logical_keys = set(
            getattr(self, "materialization_pending_frontier_logical_keys", set())
            or set()
        )
        materialization_pending_action_logical_keys = dict(
            getattr(
                self,
                "materialization_pending_frontier_action_logical_keys",
                {},
            )
            or {}
        )
        self.skipped_frontier_action_keys.clear()
        self.materialization_pending_frontier_action_keys = (
            materialization_pending_action_keys
        )
        self.materialization_pending_frontier_logical_keys = (
            materialization_pending_logical_keys
        )
        self.materialization_pending_frontier_action_logical_keys = dict(
            materialization_pending_action_logical_keys
        )
        self._retain_materialization_pending_action_logical_keys()
        self.skipped_frontier_action_keys.update(materialization_pending_action_keys)
        recovery_units = max(1, int(total_granted or increment))
        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + recovery_units + 2,
        )
        self.expand_max_iterations_to_action_budgets(headroom=max(5, increment + 2))
        self._increment_dossier_metric(
            "mini_session_cost_governed_continuations",
            1,
        )
        self._increment_dossier_metric(
            "mini_session_cost_governed_budget_granted",
            total_granted,
        )
        # Consumed by the livelock backstop above; reset to 0 in the run loop
        # once any action actually dispatches.
        self.cost_governed_continuations_without_action = (
            int(self.cost_governed_continuations_without_action or 0) + 1
        )
        self.last_cost_governed_continuation_progress_signature = progress_signature
        self._record_event(
            {
                "phase": "session_cost_governed_continuation",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "budget_increment": increment,
                "budget_grants": budget_grants,
                "budget_granted_total": total_granted,
                "max_iterations": self.max_iterations,
                "grants_without_action": int(
                    self.cost_governed_continuations_without_action or 0
                ),
                "verdict": "continuation_budget_granted",
            }
        )
        return True

    def arm_local_repair_quota(
        self,
        *,
        action_id: str,
        reason: str,
        failure_signature: str = "",
        requested_turns: int = 1,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Reserve immediate LLM repair turns after a concrete Lean rejection."""

        if not bool(self.conversation_budget_topups_enabled):
            record = {
                "phase": "session_local_repair_quota",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "failure_signature": str(failure_signature or ""),
                "verdict": "bounded_conversation_budget",
            }
            self._record_event(record)
            return {"armed": False, **record}

        candidate_work_record = (
            dict(selected_work_record or {})
            if selected_work_record is not None
            else dict(self.selected_work_item_record or {})
        )
        if self._work_record_is_unscoped_root_level(candidate_work_record):
            self._increment_dossier_metric(
                "mini_session_local_root_repair_quota_suppressed",
                1,
            )
            materialized = self._materialize_unscoped_root_quota_suppression(
                action_id=action_id,
                reason=reason,
                failure_signature=failure_signature,
                selected_work_record=candidate_work_record,
            )
            record = {
                "phase": "session_local_repair_quota",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "failure_signature": str(failure_signature or ""),
                "selected_work_item": candidate_work_record,
                "materialized_selected_work_item": dict(materialized),
                "verdict": "unscoped_root_quota_suppressed",
            }
            self._record_event(record)
            return {"armed": False, **record}

        limit = max(0, int(self.local_repair_quota_limit or 0))
        signature_key = (
            str(failure_signature or reason or "unknown").strip() or "unknown"
        )
        used_by_signature = getattr(self, "local_repair_quota_used_by_signature", None)
        if not isinstance(used_by_signature, dict):
            used_by_signature = {}
            self.local_repair_quota_used_by_signature = used_by_signature
        used_for_signature = max(
            0,
            int(used_by_signature.get(signature_key, 0) or 0),
        )
        available = max(0, limit - used_for_signature)
        if available <= 0:
            self._increment_dossier_metric(
                "mini_session_local_repair_quota_exhausted",
                1,
            )
            record = {
                "phase": "session_local_repair_quota",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "failure_signature": str(failure_signature or ""),
                "failure_signature_key": signature_key,
                "quota_limit": limit,
                "quota_used": used_for_signature,
                "quota_used_total": int(self.local_repair_quota_used or 0),
                "quota_remaining": int(self.local_repair_quota_remaining or 0),
                "verdict": "quota_exhausted",
            }
            self._record_event(record)
            return {"armed": False, **record}

        requested = max(1, int(requested_turns or 1))
        grant = min(requested, available)
        self.local_repair_quota_remaining = max(
            int(self.local_repair_quota_remaining or 0),
            grant,
        )
        self.local_repair_quota_reason = str(reason or "")
        self.local_repair_quota_failure_signature = str(failure_signature or "")
        if selected_work_record is not None:
            self.local_repair_quota_selected_work_record = dict(
                selected_work_record or {}
            )
        elif self.selected_work_item_record:
            self.local_repair_quota_selected_work_record = dict(
                self.selected_work_item_record
            )
        if self.local_repair_quota_selected_work_record:
            self.local_repair_quota_selected_work_record.setdefault(
                "failure_signature",
                str(failure_signature or ""),
            )
            self.local_repair_quota_selected_work_record.setdefault(
                "local_repair_failure_signature",
                str(failure_signature or ""),
            )
            self.local_repair_quota_selected_work_record.setdefault(
                "local_repair_quota_context",
                True,
            )

        budget_grants: Dict[str, Dict[str, int]] = {}
        for candidate_id in self._conversation_action_ids_for_repair(action_id):
            budget = self.budgets.get(candidate_id)
            if budget is None or budget.max_invocations < 0:
                continue
            old_max = int(budget.max_invocations)
            # The current ConversationTurnAction invocation has not been
            # consumed yet; reserve enough headroom for it plus the repair turn.
            needed_max = (
                int(budget.invocations) + 1 + int(self.local_repair_quota_remaining)
            )
            if needed_max > old_max:
                budget.max_invocations = needed_max
                prompt_turn_budget_granted = self._sync_conversation_prompt_budget(
                    candidate_id,
                    min_turn_budget=needed_max,
                )
                budget_grants[candidate_id] = {
                    "old_max_invocations": old_max,
                    "new_max_invocations": int(budget.max_invocations),
                    "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                }

        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + int(self.local_repair_quota_remaining) + 2,
        )
        self._increment_dossier_metric("mini_session_local_repair_quota_armed", 1)
        record = {
            "phase": "session_local_repair_quota",
            "iteration": self.iteration,
            "reason": self.local_repair_quota_reason,
            "failure_signature": self.local_repair_quota_failure_signature,
            "failure_signature_key": signature_key,
            "granted_turns": grant,
            "quota_limit": limit,
            "quota_used": used_for_signature,
            "quota_used_total": int(self.local_repair_quota_used or 0),
            "quota_remaining": int(self.local_repair_quota_remaining or 0),
            "budget_grants": budget_grants,
            "selected_work_item": dict(self.local_repair_quota_selected_work_record),
            "verdict": "armed",
        }
        self._record_event(record)
        return {"armed": True, **record}

    def _conversation_action_ids_for_repair(
        self, preferred_action_id: str = ""
    ) -> Tuple[str, ...]:
        conv_role = str(getattr(getattr(self, "conv", None), "role", "") or "prove")
        preferred = str(preferred_action_id or "").strip()
        if preferred and not preferred.startswith("conversation_turn"):
            preferred = ""
        candidates = (
            preferred,
            f"conversation_turn_{conv_role}",
            "conversation_turn_prove",
            "conversation_turn_refine",
            "conversation_turn",
        )
        out: List[str] = []
        seen: Set[str] = set()
        for candidate in candidates:
            if not candidate or candidate in seen:
                continue
            seen.add(candidate)
            out.append(candidate)
        return tuple(out)

    @staticmethod
    def _repair_policy_scope_target_id(
        record: Dict[str, Any],
        ticket: Optional[RepairTicket] = None,
    ) -> str:
        work_type = str(record.get("work_type") or "").strip()
        work_type_key = {
            "prove_claim_variant": "variant_id",
            "formalize_claim": "obligation_id",
            "formalize_missing_obligation": "obligation_id",
            "mine_missing_obligation": "obligation_id",
            "route_replan": "replan_id",
            "assemble_route": "route_id",
            "assembly": "route_id",
        }.get(work_type, "")
        keys = [
            "graph_node_id",
            "node_id",
            work_type_key,
            "variant_id",
            "obligation_id",
            "replan_id",
            "claim_id",
            "route_id",
            "target_id",
        ]
        for key in keys:
            if not key:
                continue
            value = str(record.get(key) or "").strip()
            if value:
                return value
        if ticket is not None:
            for value in (
                getattr(ticket, "obligation_id", ""),
                getattr(ticket, "target_id", ""),
            ):
                clean = str(value or "").strip()
                if clean:
                    return clean
        return ""

    def _repair_policy_scope_statement_identity(
        self,
        record: Dict[str, Any],
        *,
        target_node_id: str,
        ticket: Optional[RepairTicket] = None,
    ) -> str:
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        node = (
            nodes.get(target_node_id)
            if target_node_id and isinstance(nodes, dict)
            else None
        )
        contract_identity = ""
        if node is not None:
            contract_identity = graph_node_bound_contract_identity(node)
        else:
            identity_candidates = (
                record.get("contract_identity"),
                record.get("statement_contract_identity"),
                record.get("structural_statement_identity"),
                (
                    getattr(ticket, "statement_identity", "")
                    if ticket is not None
                    else ""
                ),
            )
            # Legacy non-graph tickets have no Lean evidence receipt. Their
            # durable surface statement remains the safe identity fallback.
            if record.get("contract_identity_evidence_receipt"):
                for value in identity_candidates:
                    candidate = str(value or "").strip()
                    if has_lean_contract_identity(candidate):
                        contract_identity = candidate
                        break
        statement = str(
            getattr(node, "statement", "")
            or record.get("target_statement")
            or (getattr(ticket, "target_statement", "") if ticket is not None else "")
            or ""
        ).strip()
        if not statement and target_node_id == str(
            getattr(graph, "root_node_id", "root") or "root"
        ):
            statement = str(getattr(dossier, "root_statement", "") or "").strip()
        if node is None and contract_identity:
            statement_key = canonical_dossier_statement_key(statement)
            environment_hash = str(
                record.get("contract_identity_environment_hash") or ""
            ).strip()
            if str(
                record.get("contract_identity_statement_key") or ""
            ).strip() != statement_key or not lean_contract_evidence_receipt_matches(
                str(record.get("contract_identity_evidence_receipt") or ""),
                identity=contract_identity,
                statement_key=statement_key,
                environment_hash=environment_hash,
            ):
                contract_identity = ""
        return structural_statement_identity(
            statement,
            contract_identity=contract_identity,
            statement_key=canonical_dossier_statement_key(statement),
        )

    def _repair_policy_narrowing_executable_statement(
        self,
        record: Dict[str, Any],
        ticket: Optional[RepairTicket],
    ) -> str:
        """Return the exact proposition eligible for exclusive repair work.

        Materialization prompts and decomposition prose are planner inputs, not
        proof targets. They must never suppress executable sibling lanes by
        becoming an exclusive narrowing scope.
        """

        if bool(record.get("formalization_statement_pending")) or (
            bool(record.get("materialization_required"))
            and not str(record.get("target_statement") or "").strip()
        ):
            return ""
        statement = self._frontier_item_executable_statement(
            record,
            for_capability=True,
        )
        if statement:
            return statement
        if ticket is None:
            return ""
        candidate = str(getattr(ticket, "target_statement", "") or "").strip()
        if not candidate or not graph_statement_is_executable(candidate):
            return ""
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        target_id = self._repair_policy_scope_target_id(record, ticket)
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        node = nodes.get(target_id) if target_id and isinstance(nodes, dict) else None
        if node is not None:
            node_statement = str(getattr(node, "statement", "") or "").strip()
            if canonical_dossier_statement_key(candidate) == (
                canonical_dossier_statement_key(node_statement)
            ):
                return node_statement
            return ""
        root_id = str(getattr(graph, "root_node_id", "root") or "root").strip()
        root_statement = str(getattr(dossier, "root_statement", "") or "").strip()
        if (
            target_id in {"", "root", root_id}
            and root_statement
            and canonical_dossier_statement_key(candidate)
            == canonical_dossier_statement_key(root_statement)
        ):
            return root_statement
        return ""

    def _build_repair_policy_narrowing_scope_identity(
        self,
        record: Dict[str, Any],
        *,
        ticket: Optional[RepairTicket] = None,
        reason: str = "",
    ) -> Dict[str, str]:
        payload = dict(record or {})
        target_node_id = self._repair_policy_scope_target_id(payload, ticket)
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        node = (
            nodes.get(target_node_id)
            if target_node_id and isinstance(nodes, dict)
            else None
        )
        node_metadata = dict(getattr(node, "metadata", {}) or {}) if node else {}
        statement_identity = self._repair_policy_scope_statement_identity(
            payload,
            target_node_id=target_node_id,
            ticket=ticket,
        )
        failure_signature = str(
            payload.get("failure_signature")
            or (getattr(ticket, "failure_signature", "") if ticket is not None else "")
            or payload.get("target_failure_key")
            or reason
            or ""
        ).strip()
        environment_hash = str(
            getattr(dossier, "current_lean_environment_hash", "")
            or payload.get("statement_environment_hash")
            or payload.get("lean_environment_hash")
            or node_metadata.get("statement_environment_hash")
            or node_metadata.get("lean_environment_hash")
            or ""
        ).strip()
        target_bound_to_graph = bool(node is not None)
        if not target_node_id or not statement_identity or not failure_signature:
            return {}
        scope_id = stable_identity(
            "repair-policy-narrowing",
            target_node_id,
            statement_identity,
            failure_signature,
            environment_hash,
        )
        return {
            "schema_version": "1",
            "scope_id": scope_id,
            "target_node_id": target_node_id,
            "statement_identity": statement_identity,
            "failure_signature": failure_signature,
            "environment_hash": environment_hash,
            "target_bound_to_graph": ("true" if target_bound_to_graph else "false"),
        }

    def _refresh_repair_policy_narrowing_scope_identity(
        self,
        *,
        ticket: Optional[RepairTicket] = None,
        reason: str = "",
    ) -> Dict[str, str]:
        scope = self._build_repair_policy_narrowing_scope_identity(
            dict(self.repair_policy_narrowing_selected_work_record or {}),
            ticket=ticket,
            reason=reason or self.repair_policy_narrowing_reason,
        )
        self.repair_policy_narrowing_scope_identity = dict(scope)
        return scope

    def _clear_repair_policy_narrowing(
        self,
        *,
        trigger: str,
        verdict: str,
        liveness_status: Optional[Dict[str, Any]] = None,
    ) -> None:
        old_reason = str(self.repair_policy_narrowing_reason or "")
        old_selected = dict(self.repair_policy_narrowing_selected_work_record or {})
        old_scope = dict(self.repair_policy_narrowing_scope_identity or {})
        self.repair_policy_narrowing_required = False
        self.repair_policy_narrowing_reason = ""
        self.repair_policy_narrowing_selected_work_record = {}
        self.repair_policy_narrowing_scope_identity = {}
        self.fallback_actions_attempted = False
        if (
            str(getattr(self, "last_failure_reason", "") or "")
            == "repair_policy_narrowing_no_applicable"
        ):
            self.last_failure_reason = ""
        self._record_event(
            {
                "phase": "session_repair_policy_narrowing",
                "iteration": self.iteration,
                "trigger": str(trigger or ""),
                "reason": old_reason,
                "selected_work_item": old_selected,
                "scope_identity": old_scope,
                "liveness_status": dict(liveness_status or {}),
                "verdict": str(verdict or "narrowing_reconciled"),
            }
        )

    def _reconcile_repair_policy_narrowing(self, *, trigger: str) -> bool:
        """Release only a durably identified narrowing scope that is stale."""

        if not self.repair_policy_narrowing_required:
            return False
        scope = dict(self.repair_policy_narrowing_scope_identity or {})
        if not scope:
            scope = self._refresh_repair_policy_narrowing_scope_identity()
            if not scope:
                return False
        if (
            str(scope.get("schema_version") or "") != "1"
            or str(scope.get("target_bound_to_graph") or "") != "true"
        ):
            return False
        target_node_id = str(scope.get("target_node_id") or "").strip()
        statement_identity = str(scope.get("statement_identity") or "").strip()
        failure_signature = str(scope.get("failure_signature") or "").strip()
        if not target_node_id or not statement_identity or not failure_signature:
            return False
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return False
        node = nodes.get(target_node_id)
        if node is None:
            self._clear_repair_policy_narrowing(
                trigger=trigger,
                verdict="narrowing_reconciled_target_removed",
                liveness_status={
                    "live": False,
                    "reason": "target_node_removed",
                    "node_id": target_node_id,
                },
            )
            return True
        current_statement_identity = self._repair_policy_scope_statement_identity(
            dict(self.repair_policy_narrowing_selected_work_record or {}),
            target_node_id=target_node_id,
        )
        if (
            not current_statement_identity
            or current_statement_identity != statement_identity
        ):
            self._clear_repair_policy_narrowing(
                trigger=trigger,
                verdict="narrowing_reconciled_target_retargeted",
                liveness_status={
                    "live": False,
                    "reason": "statement_identity_changed",
                    "node_id": target_node_id,
                    "expected_statement_identity": statement_identity,
                    "current_statement_identity": current_statement_identity,
                },
            )
            return True
        expected_environment_hash = str(scope.get("environment_hash") or "").strip()
        current_environment_hash = str(
            getattr(dossier, "current_lean_environment_hash", "") or ""
        ).strip()
        if (
            expected_environment_hash
            and current_environment_hash
            and expected_environment_hash != current_environment_hash
        ):
            self._clear_repair_policy_narrowing(
                trigger=trigger,
                verdict="narrowing_reconciled_environment_changed",
                liveness_status={
                    "live": False,
                    "reason": "environment_generation_changed",
                    "node_id": target_node_id,
                    "expected_environment_hash": expected_environment_hash,
                    "current_environment_hash": current_environment_hash,
                },
            )
            return True
        narrowing_record = dict(self.repair_policy_narrowing_selected_work_record or {})
        node_metadata = dict(getattr(node, "metadata", {}) or {})
        if (
            str(narrowing_record.get("work_type") or "")
            == "formalize_missing_obligation"
            and node_metadata.get("formalization_required") is False
            and bool(node_metadata.get("formalization_bridge_support_recorded"))
            and bool(node_metadata.get("formalization_bridge_parent_work_materialized"))
        ):
            # The procedural formalization scope has completed its job.  The
            # obligation may remain open while its newly materialized parent
            # assembly/open-premise work proceeds, but retaining the old
            # formalization record would pin the scheduler to a stale phase.
            self._clear_repair_policy_narrowing(
                trigger=trigger,
                verdict="narrowing_reconciled_bridge_parent_work_materialized",
                liveness_status={
                    "live": False,
                    "reason": "formalization_scope_materialized",
                    "node_id": target_node_id,
                },
            )
            return True
        # Reconcile the exact scope node, not every provenance id carried by
        # its scheduler record.  A variant record also names its parent claim;
        # closing that parent must not silently discharge a still-open variant.
        liveness_status = self.selected_work_graph_liveness_status(
            self._repair_policy_narrowing_liveness_record(narrowing_record)
        )
        if bool(liveness_status.get("live", True)):
            return False
        self._clear_repair_policy_narrowing(
            trigger=trigger,
            verdict="narrowing_reconciled_target_terminal",
            liveness_status=liveness_status,
        )
        return True

    def _has_repair_policy_narrowing_candidate(self) -> bool:
        """Whether a non-broad action can receive a procedural repair miss."""

        if self._reconcile_repair_policy_narrowing(trigger="narrowing_candidate_probe"):
            return False
        narrowing_record = dict(self.repair_policy_narrowing_selected_work_record or {})
        for action in self.actions:
            action_id = str(getattr(action, "id", "") or "")
            if not action_id:
                continue
            if self._repair_policy_static_action_is_broad(
                action_id,
                narrowing_record,
            ):
                continue
            budget = self.budgets.get(action_id)
            if budget is not None and budget.exhausted():
                continue
            restored_work = self._restore_repair_policy_narrowing_selected_work(
                action_id
            )
            if narrowing_record and not restored_work:
                self._clear_selected_work_item()
                continue
            applicable = self._safe_is_applicable(
                action,
                context="repair_policy_narrowing_probe",
            )
            self._clear_selected_work_item()
            if applicable:
                return True
        return False

    def _repair_policy_selected_work_is_narrow(self, action_id: str) -> bool:
        action_text = str(action_id or "").strip()
        record = dict(getattr(self, "selected_work_item_record", {}) or {})
        work_type = str(record.get("work_type") or "").strip()
        if not work_type:
            return False
        if work_type == "root_repair":
            return False
        if self._is_unscoped_root_authoring_action(action_text):
            return False
        if action_text.startswith("conversation_turn") and work_type in {
            "",
            "root_repair",
        }:
            return False
        if work_type not in {
            "formalize_claim",
            "formalize_missing_obligation",
            "prove_claim_variant",
            "mine_missing_obligation",
            "route_replan",
            "target_integrity_adjudication",
            "assemble_route",
            "materialize_replay_source",
            "retrieval",
            "decl_probe",
            "tactic_swarm",
            "child_llm_prove",
            "lemma_dag_decomposition",
            "assembly",
        }:
            return False
        # Narrowing is an authorization boundary, not merely a statement that
        # *some* graph work is selected.  The saved record may only be rebound
        # to an action that owns this exact work kind/resource.  Previously a
        # procedural ``formalize_missing_obligation`` record was restored onto
        # ChildClosure and finite-reindexing actions; both silently treated the
        # foreign selection as absent and ran unrestricted root work.
        return self._selected_work_action_compatible(action_text, record)

    def _discharge_repair_policy_narrowing_after_action(
        self,
        outcome: MiniOutcome,
    ) -> None:
        if not self.repair_policy_narrowing_required:
            return
        if self._reconcile_repair_policy_narrowing(trigger="post_apply"):
            return
        if outcome.exception is not None:
            return
        if not self._repair_policy_selected_work_is_narrow(outcome.action_id):
            return
        selected_work = dict(self.selected_work_item_record)
        metadata = outcome.metadata or {}
        if self.repair_policy_narrowing_scope_identity:
            # Exact scopes are released only by the graph/environment
            # reconciler above. Generic action-level progress may be an
            # unrelated helper or residual and cannot prove that this target's
            # procedural repair obligation has been satisfied.
            self._record_event(
                {
                    "phase": "session_repair_policy_narrowing",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": self.repair_policy_narrowing_reason,
                    "selected_work_item": selected_work,
                    "scope_identity": dict(self.repair_policy_narrowing_scope_identity),
                    "progress": bool(outcome.progress),
                    "helpers_added_count": len(outcome.helpers_added),
                    "strong_progress": bool(metadata.get("strong_progress")),
                    "verdict": "narrowing_retained_for_live_exact_scope",
                }
            )
            return
        route_support_only_progress = bool(
            metadata.get("route_support_only_helper")
            or metadata.get("hidden_route_support_helper_names")
        )
        scoped_progress_discharges = (
            bool(outcome.progress) and not route_support_only_progress
        )
        if not (
            bool(outcome.solved)
            or bool(outcome.helpers_added)
            or scoped_progress_discharges
            or bool(metadata.get("strong_progress"))
        ):
            self._record_event(
                {
                    "phase": "session_repair_policy_narrowing",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": self.repair_policy_narrowing_reason,
                    "selected_work_item": selected_work,
                    "progress": bool(outcome.progress),
                    "helpers_added_count": len(outcome.helpers_added),
                    "strong_progress": bool(metadata.get("strong_progress")),
                    "verdict": "narrowing_retained_after_no_progress",
                }
            )
            return
        self._record_event(
            {
                "phase": "session_repair_policy_narrowing",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "reason": self.repair_policy_narrowing_reason,
                "selected_work_item": selected_work,
                "progress": bool(outcome.progress),
                "helpers_added_count": len(outcome.helpers_added),
                "strong_progress": bool(metadata.get("strong_progress")),
                "verdict": "narrowing_discharged_after_action",
            }
        )
        self.repair_policy_narrowing_required = False
        self.repair_policy_narrowing_reason = ""
        self.repair_policy_narrowing_selected_work_record = {}
        self.repair_policy_narrowing_scope_identity = {}

    def _restore_repair_policy_narrowing_selected_work(self, action_id: str) -> bool:
        record = dict(self.repair_policy_narrowing_selected_work_record or {})
        if not record:
            return False
        return self._restore_selected_work_record(
            record,
            action_id,
            context="repair_policy_narrowing",
            metric_key="mini_session_retired_graph_target_repair_policy_suppressed",
            liveness_record=self._repair_policy_narrowing_liveness_record(record),
        )

    def _repair_policy_narrowing_liveness_record(
        self,
        record: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Project narrowing provenance onto its exact dispatch scope."""

        payload = dict(
            record
            if record is not None
            else self.repair_policy_narrowing_selected_work_record or {}
        )
        scope = dict(self.repair_policy_narrowing_scope_identity or {})
        target_node_id = str(scope.get("target_node_id") or "").strip()
        if not target_node_id:
            _work_type, target_node_id = self._graph_repair_record_target_key(payload)
        projected = {
            "work_type": str(payload.get("work_type") or ""),
            "graph_node_id": target_node_id,
            "target_statement": str(payload.get("target_statement") or ""),
        }
        route_id = str(payload.get("route_id") or "").strip()
        if route_id and route_id != target_node_id:
            projected["route_id"] = route_id
        return projected

    def selected_work_graph_liveness_status(
        self,
        record: Optional[Dict[str, Any]] = None,
        *,
        mutate: bool = True,
    ) -> Dict[str, Any]:
        """Return whether a restored graph-native selected work record is live."""

        payload = (
            dict(record or {})
            if record is not None
            else dict(getattr(self, "selected_work_item_record", {}) or {})
        )
        if not payload:
            return {"live": True, "verdict": "no_selected_work"}
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return {"live": True, "verdict": "no_proof_graph"}
        work_type = str(payload.get("work_type") or "").strip()

        def replay_materialization_helper(node: Any) -> Any:
            helper_getter = getattr(graph, "_node_replay_materialization_helper", None)
            if not callable(helper_getter):
                return None
            try:
                return helper_getter(node, mutate=mutate)
            except Exception:
                return None

        def materialization_debt_target(node: Any) -> bool:
            if work_type != "materialize_replay_source" or node is None:
                return False
            return replay_materialization_helper(node) is not None

        def terminal_reason(node: Any) -> str:
            if node is None:
                return ""
            metadata = dict(getattr(node, "metadata", {}) or {})
            node_kind = str(getattr(node, "kind", "") or "")
            if work_type != "materialize_replay_source":
                if node_kind == "replan_queue_item":
                    replan_promoted = getattr(
                        graph,
                        "replan_queue_item_frontier_promoted_to_proof_state",
                        None,
                    )
                    if callable(replan_promoted):
                        try:
                            if bool(replan_promoted(node)):
                                return "promoted_to_proof_state"
                        except Exception:
                            pass
                if (
                    node_kind == "missing_obligation"
                    and graph_node_frontier_promoted_to_proof_state(node)
                ):
                    return "promoted_to_proof_state"
            for key in (
                "route_retired",
                "route_dependency_contradicted",
                "proposal_invalidated",
                "retired_by_repeated_repair_failure",
                "formalization_repeated_unrelated_bridge_suppressed",
                "route_assembly_contract_replan_obsolete",
                "superseded_by_source",
            ):
                if metadata.get(key):
                    return key
            if graph_node_frontier_quarantined(node):
                return "frontier_quarantined"
            if materialization_debt_target(node):
                return ""
            status = str(getattr(node, "status", "") or "").strip()
            if status == "blocked":
                blockers_resolved = getattr(graph, "blocked_by_resolved", None)
                if not callable(blockers_resolved):
                    return "blocked_by_unresolved"
                try:
                    if not bool(blockers_resolved(node.node_id)):
                        return "blocked_by_unresolved"
                except Exception:
                    return "blocked_by_unresolved"
                return ""
            if status in {"proved", "failed", "obsolete", "superseded"}:
                return f"status_{status}"
            if status == "rejected":
                has_new_evidence = getattr(
                    graph, "node_has_new_rejection_evidence", None
                )
                if callable(has_new_evidence):
                    try:
                        if bool(has_new_evidence(node)):
                            return ""
                    except Exception:
                        pass
                return "status_rejected"
            return ""

        def route_signature_block_reason(node: Any) -> str:
            if node is None:
                return ""
            if str(getattr(node, "kind", "") or "") != "strategy_route":
                return ""
            metadata = dict(getattr(node, "metadata", {}) or {})
            signature_getter = getattr(graph, "route_dependency_signature_hash", None)
            try:
                current_signature_hash = (
                    str(
                        signature_getter(str(getattr(node, "node_id", "") or "")) or ""
                    ).strip()
                    if callable(signature_getter)
                    else ""
                )
            except Exception:
                current_signature_hash = ""
            for key in (
                "route_root_assembly_author_failed_signature_hash",
                "route_missing_assembly_bridge_signature_hash",
                "route_root_tactic_failure_rescue_signature_hash",
                "route_root_tactic_failed_signature_hash",
            ):
                blocked_hash = str(metadata.get(key) or "").strip()
                if blocked_hash and (
                    not current_signature_hash or blocked_hash == current_signature_hash
                ):
                    return key
            return ""

        def current_route_missing_bridge_rescue(node: Any) -> bool:
            metadata = dict(getattr(node, "metadata", {}) or {}) if node else {}
            if not bool(metadata.get("route_missing_assembly_bridge_rescue")):
                return False
            current = getattr(
                graph, "_route_missing_assembly_bridge_rescue_current", None
            )
            if callable(current):
                try:
                    try:
                        return bool(current(node, mutate=mutate))
                    except TypeError:
                        if not mutate:
                            return False
                        return bool(current(node))
                except Exception:
                    return False
            return True

        rescue_parent_block_reasons = {
            "route_missing_assembly_bridge_signature_hash",
            "route_root_tactic_failure_rescue_signature_hash",
            "route_root_tactic_failed_signature_hash",
            "route_root_assembly_author_failed_signature_hash",
        }

        def explicit_route_ids(node: Any) -> Set[str]:
            route_ids: Set[str] = set()
            for key in ("route_id",):
                route_id = str(payload.get(key) or "").strip()
                if route_id:
                    route_ids.add(route_id)
            metadata = dict(getattr(node, "metadata", {}) or {}) if node else {}
            route_id = str(metadata.get("route_id") or "").strip()
            if route_id:
                route_ids.add(route_id)
            return route_ids

        def edge_route_status_payload(
            node: Any,
            *,
            dependent_node_id: str,
        ) -> Optional[Dict[str, Any]]:
            route_ids_getter = getattr(graph, "_node_route_ids", None)
            if not callable(route_ids_getter):
                return None
            try:
                route_ids = {
                    str(route_id or "").strip()
                    for route_id in (route_ids_getter(node) or set())
                    if str(route_id or "").strip()
                }
            except Exception:
                return None
            if explicit_route_ids(node):
                # A graph target may be shared by several strategies. When
                # the selected work names its route, only that route can make
                # the exact scope terminal; an unrelated dead route is not a
                # liveness verdict for the selected consumer.
                return None
            route_ids.difference_update(explicit_route_ids(node))
            terminal_route_statuses: List[Dict[str, Any]] = []
            for route_id in sorted(route_ids):
                route_status = node_status_payload(route_id, role="edge.route_id")
                if route_status is None:
                    # Edge-only work is shared by every consuming route. One
                    # live or unknown consumer is enough to keep the target
                    # live; a dead route cannot retire work still needed by a
                    # viable strategy.
                    return None
                if (
                    current_route_missing_bridge_rescue(node)
                    and str(route_status.get("reason") or "")
                    in rescue_parent_block_reasons
                ):
                    return None
                terminal_route_statuses.append(route_status)
            if terminal_route_statuses and len(terminal_route_statuses) == len(
                route_ids
            ):
                route_status = terminal_route_statuses[0]
                route_status["dependent_node_id"] = dependent_node_id
                route_status["terminal_route_ids"] = sorted(route_ids)
                return route_status
            return None

        def node_status_payload(node_id: str, *, role: str) -> Optional[Dict[str, Any]]:
            node = nodes.get(str(node_id or "").strip())
            if node is None:
                return None
            reason = terminal_reason(node) or route_signature_block_reason(node)
            if not reason:
                return None
            return {
                "live": False,
                "verdict": "terminal_graph_target",
                "reason": reason,
                "node_id": str(getattr(node, "node_id", "") or node_id),
                "node_kind": str(getattr(node, "kind", "") or ""),
                "node_status": str(getattr(node, "status", "") or ""),
                "node_role": role,
                "work_type": str(payload.get("work_type") or ""),
            }

        if work_type == "target_integrity_adjudication":
            # A failed claim is the producer trigger and provenance for an
            # adjudication obligation, not a dependency that can retire it.
            # Match the dispatch target contract used by conversation turns:
            # liveness belongs to the obligation itself and any explicit
            # route checked below.
            node_fields = (
                "obligation_id",
                "graph_node_id",
                "node_id",
                "target_id",
            )
        else:
            node_fields = (
                "claim_id",
                "variant_id",
                "obligation_id",
                "replan_id",
                "graph_node_id",
                "node_id",
                "target_id",
            )
        for node_field in node_fields:
            candidate = str(payload.get(node_field) or "").strip()
            if not candidate or candidate not in nodes:
                continue
            status = node_status_payload(candidate, role=node_field)
            if status is not None:
                return status
            edge_route_status = edge_route_status_payload(
                nodes[candidate],
                dependent_node_id=candidate,
            )
            if edge_route_status is not None:
                return edge_route_status
            node_metadata = dict(getattr(nodes[candidate], "metadata", {}) or {})
            route_id = str(node_metadata.get("route_id") or "").strip()
            payload_route_id = str(payload.get("route_id") or "").strip()
            if route_id and not payload_route_id:
                route_status = node_status_payload(route_id, role="metadata.route_id")
                if route_status is not None:
                    if (
                        current_route_missing_bridge_rescue(nodes[candidate])
                        and str(route_status.get("reason") or "")
                        in rescue_parent_block_reasons
                    ):
                        continue
                    route_status["dependent_node_id"] = candidate
                    return route_status

        for route_field in ("route_id",):
            route_id = str(payload.get(route_field) or "").strip()
            if not route_id:
                continue
            if route_id not in nodes:
                has_bound_target_node = any(
                    str(
                        getattr(
                            nodes.get(str(payload.get(field) or "").strip()),
                            "kind",
                            "",
                        )
                        or ""
                    )
                    in {
                        "proposed_claim",
                        "formal_variant",
                        "missing_obligation",
                        "replan_queue_item",
                    }
                    for field in (
                        "claim_id",
                        "variant_id",
                        "obligation_id",
                        "replan_id",
                        "graph_node_id",
                        "node_id",
                        "target_id",
                    )
                    if str(payload.get(field) or "").strip()
                )
                if not has_bound_target_node:
                    continue
                return {
                    "live": False,
                    "verdict": "terminal_graph_target",
                    "reason": "selected_route_node_removed",
                    "node_id": route_id,
                    "node_kind": "strategy_route",
                    "node_status": "removed",
                    "node_role": route_field,
                    "work_type": str(payload.get("work_type") or ""),
                }
            status = node_status_payload(route_id, role=route_field)
            if status is not None:
                payload_node_id = str(
                    payload.get("node_id")
                    or payload.get("graph_node_id")
                    or payload.get("obligation_id")
                    or payload.get("replan_id")
                    or ""
                ).strip()
                payload_node = nodes.get(payload_node_id) if payload_node_id else None
                if (
                    current_route_missing_bridge_rescue(payload_node)
                    and str(status.get("reason") or "") in rescue_parent_block_reasons
                ):
                    continue
                return status
        return {"live": True, "verdict": "graph_target_live"}

    def _selected_work_targets_terminal_graph_work(
        self,
        record: Dict[str, Any],
        *,
        context: str,
        metric_key: str = "",
    ) -> bool:
        status = self.selected_work_graph_liveness_status(record)
        if bool(status.get("live", True)):
            return False
        action_id = str(
            record.get("mapped_action_id") or record.get("action_id") or ""
        ).strip()
        work_type = str(record.get("work_type") or "").strip()
        if (
            work_type == "materialize_replay_source"
            and str(status.get("reason") or "") == "status_proved"
        ):
            dossier = getattr(self, "dossier", None)
            graph = (
                getattr(dossier, "proof_graph", None) if dossier is not None else None
            )
            nodes = getattr(graph, "nodes", {}) if graph is not None else {}
            node_id = str(
                status.get("node_id")
                or record.get("graph_node_id")
                or record.get("node_id")
                or ""
            ).strip()
            node = nodes.get(node_id) if isinstance(nodes, dict) else None
            helper_getter = getattr(graph, "_node_replay_materialization_helper", None)
            helper = None
            if callable(helper_getter) and node is not None:
                try:
                    helper = helper_getter(node)
                except Exception:
                    helper = None
            if helper is not None:
                self._record_event(
                    {
                        "phase": "session_selected_work_liveness",
                        "iteration": self.iteration,
                        "context": str(context or ""),
                        "selected_work_item": dict(record or {}),
                        "liveness_status": dict(status),
                        "verdict": "terminal_graph_target_materialization_bypassed",
                    }
                )
                return False
        if (
            self._is_graph_recursive_action(action_id)
            and work_type in {"mine_missing_obligation", "route_replan"}
            and str(status.get("reason") or "") == "frontier_quarantined"
            and str(status.get("node_kind") or "") == "missing_obligation"
        ):
            dossier = getattr(self, "dossier", None)
            graph = (
                getattr(dossier, "proof_graph", None) if dossier is not None else None
            )
            nodes = getattr(graph, "nodes", {}) if graph is not None else {}
            node = (
                nodes.get(str(status.get("node_id") or "").strip())
                if isinstance(nodes, dict)
                else None
            )
            metadata = dict(getattr(node, "metadata", {}) or {}) if node else {}
            recursive_untrusted_suppressed = bool(
                metadata.get("certified_fact") is False
                or str(metadata.get("obligation_trust") or "")
                == "untrusted_failed_proof_residual"
            )
        else:
            recursive_untrusted_suppressed = False
        recursive_poisoned_route_suppressed = bool(
            self._is_graph_recursive_action(action_id)
            and work_type in {"mine_missing_obligation", "route_replan"}
            and str(status.get("node_kind") or "") == "strategy_route"
            and str(status.get("reason") or "")
            in {
                "route_retired",
                "route_dependency_contradicted",
                "proposal_invalidated",
                "retired_by_repeated_repair_failure",
            }
        )
        bypass_reason = self._terminal_graph_repair_liveness_bypass_reason(
            record,
            status=status,
            context=context,
        )
        if bypass_reason:
            bypass_key = self._terminal_graph_repair_liveness_bypass_key(
                record,
                status=status,
                bypass_reason=bypass_reason,
            )
            context_text = str(context or "").strip()
            if bypass_key in self._selected_work_liveness_bypass_keys:
                self._increment_dossier_metric(
                    "mini_session_terminal_graph_target_repair_bypass_deduped",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_selected_work_liveness",
                        "iteration": self.iteration,
                        "context": context_text,
                        "selected_work_item": dict(record or {}),
                        "liveness_status": dict(status),
                        "bypass_reason": bypass_reason,
                        "bypass_key": list(bypass_key),
                        "verdict": "terminal_graph_target_repair_bypass_deduped",
                    }
                )
                return False
            self._selected_work_liveness_bypass_keys.add(bypass_key)
            self._increment_dossier_metric(
                "mini_session_terminal_graph_target_repair_bypassed",
                1,
            )
            if context_text in {"repair_ticket", "repair_ticket_register"}:
                self._increment_dossier_metric(
                    "mini_session_terminal_graph_target_repair_ticket_bypassed",
                    1,
                )
            elif context_text in {
                "local_repair_quota",
                "local_repair_quota_scoped_action",
            }:
                self._increment_dossier_metric(
                    "mini_session_terminal_graph_target_local_repair_bypassed",
                    1,
                )
            self._record_event(
                {
                    "phase": "session_selected_work_liveness",
                    "iteration": self.iteration,
                    "context": context_text,
                    "selected_work_item": dict(record or {}),
                    "liveness_status": dict(status),
                    "bypass_reason": bypass_reason,
                    "bypass_key": list(bypass_key),
                    "verdict": "terminal_graph_target_repair_bypassed",
                }
            )
            return False
        target_key = str(
            status.get("node_id")
            or record.get("obligation_id")
            or record.get("graph_node_id")
            or record.get("node_id")
            or record.get("target_id")
            or record.get("route_id")
            or ""
        ).strip()
        suppression_key = (
            str(int(getattr(self, "iteration", 0) or 0)),
            target_key,
            str(status.get("reason") or ""),
            str(status.get("node_role") or ""),
            str(status.get("work_type") or record.get("work_type") or ""),
        )
        if suppression_key in self._selected_work_liveness_suppression_keys:
            return True
        self._selected_work_liveness_suppression_keys.add(suppression_key)
        if recursive_untrusted_suppressed:
            self._increment_dossier_metric(
                "mini_session_graph_recursive_decompose_untrusted_obligation_skipped",
                1,
            )
        if recursive_poisoned_route_suppressed:
            self._increment_dossier_metric(
                "mini_session_graph_recursive_decompose_poisoned_route_work_skipped",
                1,
            )
        if str(status.get("reason") or "") == "promoted_to_proof_state":
            self._increment_dossier_metric(
                "mini_session_promoted_graph_target_restore_suppressed",
                1,
            )
        if metric_key:
            self._increment_dossier_metric(metric_key, 1)
        self._increment_dossier_metric(
            "mini_session_terminal_graph_target_suppressed_by_reason",
            1,
        )
        self._increment_dossier_metric(
            "mini_session_retired_graph_target_restore_suppressed",
            1,
        )
        self._record_event(
            {
                "phase": "session_selected_work_liveness",
                "iteration": self.iteration,
                "context": str(context or ""),
                "selected_work_item": dict(record or {}),
                "liveness_status": dict(status),
                "verdict": "terminal_graph_target_suppressed",
            }
        )
        return True

    def _selected_work_targets_terminal_graph_work_probe(
        self,
        record: Dict[str, Any],
    ) -> bool:
        """Read-only counterpart of the frontier liveness gate.

        Ordinary ranking must agree with dispatch without recording
        suppression.  Replay materialization is the one normal-frontier
        exception: a proved graph node remains serviceable when it owns a
        replayable helper source.
        """

        status = self.selected_work_graph_liveness_status(
            record,
            mutate=False,
        )
        if bool(status.get("live", True)):
            return False
        if (
            str(record.get("work_type") or "") == "materialize_replay_source"
            and str(status.get("reason") or "") == "status_proved"
        ):
            dossier = getattr(self, "dossier", None)
            graph = (
                getattr(dossier, "proof_graph", None) if dossier is not None else None
            )
            nodes = getattr(graph, "nodes", {}) if graph is not None else {}
            node_id = str(
                status.get("node_id")
                or record.get("graph_node_id")
                or record.get("node_id")
                or ""
            ).strip()
            node = nodes.get(node_id) if isinstance(nodes, dict) else None
            helper_getter = getattr(graph, "_node_replay_materialization_helper", None)
            if callable(helper_getter) and node is not None:
                try:
                    return helper_getter(node, mutate=False) is None
                except Exception:
                    return True
        return True

    def _selected_work_record_dispatch_block_reason(
        self,
        record: Dict[str, Any],
        action_id: str,
    ) -> str:
        """Return why a live selected-work record still cannot dispatch."""

        work_type = str(record.get("work_type") or "").strip()
        # A restored selection can predate the typed residual-goal admission
        # contract even when the current frontier correctly suppresses that
        # node.  Resolve every proof-state-shaped target field here so saved
        # selections, repair redirects, and in-flight action replay cannot
        # bypass the frontier gate and expose a lossy reconstructed goal to a
        # scheduler or provider.
        proof_state = getattr(self, "proof_state", None)
        proof_state_nodes = getattr(proof_state, "nodes", {}) or {}
        layers: List[Mapping[str, Any]] = [record]
        for nested_key in ("graph_record", "selected_work_item"):
            nested = record.get(nested_key)
            if isinstance(nested, Mapping):
                layers.append(nested)
        candidate_node_ids: List[str] = []
        for layer in layers:
            for key in (
                "node_id",
                "child_node_id",
                "proof_state_node_id",
                "target_id",
                "graph_node_id",
            ):
                node_id = str(layer.get(key) or "").strip()
                if node_id and node_id not in candidate_node_ids:
                    candidate_node_ids.append(node_id)
        status_getter = getattr(
            proof_state,
            "residual_goal_attestation_status",
            None,
        )
        try:
            from ensemble_prover.proof_state_executor import (
                proof_state_current_residual_route_context_hashes,
            )

            current_residual_context_hashes = (
                proof_state_current_residual_route_context_hashes(
                    conv=self.conv,
                    dossier=self.dossier,
                    lean=self.lean,
                    proof_state=proof_state,
                )
            )
        except Exception:
            current_residual_context_hashes = {}
        for node_id in candidate_node_ids:
            node = proof_state_nodes.get(node_id)
            if node is None or str(getattr(node, "kind", "") or "") != "child_goal":
                continue
            if callable(status_getter):
                try:
                    if self._residual_dispatch_cache_ready:
                        if node_id not in self._residual_dispatch_required_ids:
                            continue
                        if node_id in self._residual_dispatch_authorized_ids:
                            continue
                        if node_id in self._residual_dispatch_persisted_authorized_ids:
                            return "residual_elaboration_reattestation_required"
                        return "residual_elaboration_attestation_required"
                    persisted_status = str(status_getter(node) or "").strip()
                    if (
                        persisted_status == "attested"
                        and not current_residual_context_hashes
                    ):
                        return "residual_elaboration_reattestation_required"
                    status = str(
                        status_getter(
                            node,
                            route_elaboration_context_hashes=(
                                current_residual_context_hashes
                            ),
                        )
                        or ""
                    ).strip()
                except TypeError:
                    persisted_status = ""
                    status = str(status_getter(node) or "").strip()
                except Exception:
                    persisted_status = ""
                    status = ""
                if status == "residual_elaboration_attestation_required":
                    if persisted_status == "attested":
                        return "residual_elaboration_reattestation_required"
                    return status
                if status:
                    continue
            source = str(
                getattr(getattr(node, "goal", None), "source_failure", "") or ""
            ).strip()
            try:
                from ensemble_prover.proof_state import (
                    proof_state_source_requires_residual_goal_attestation,
                )

                if proof_state_source_requires_residual_goal_attestation(source):
                    return "residual_elaboration_attestation_required"
            except Exception:
                # A source-bearing child behind an unavailable production
                # validator is not safe to dispatch. Plain structural children
                # have an empty/non-residual source and retain legacy behavior.
                if source:
                    return "residual_elaboration_attestation_required"
        if (
            str(action_id or "").startswith("conversation_turn")
            and work_type == "target_integrity_adjudication"
            and self._frontier_item_targets_dossier_graph_node(record)
            and not self._frontier_item_executable_statement(record)
        ):
            return "target_integrity_nonexecutable"
        return ""

    def _selected_work_record_dispatch_blocked(
        self,
        record: Dict[str, Any],
        action_id: str,
        *,
        context: str,
    ) -> bool:
        reason = self._selected_work_record_dispatch_block_reason(record, action_id)
        if not reason:
            return False
        self._record_event(
            {
                "phase": "session_selected_work_dispatch",
                "iteration": self.iteration,
                "context": str(context or ""),
                "action_id": str(action_id or ""),
                "selected_work_item": dict(record or {}),
                "reason": reason,
                "verdict": "selected_work_dispatch_blocked",
            }
        )
        return True

    def _terminal_graph_repair_liveness_bypass_reason(
        self,
        record: Dict[str, Any],
        *,
        status: Dict[str, Any],
        context: str,
    ) -> str:
        """Allow proof-backed repairs for route-signature authoring failures.

        ``selected_work_graph_liveness_status`` deliberately suppresses stale
        route assembly from ordinary frontier selection after an authoring
        failure. A concrete Lean rejection, however, has already promised the
        scheduler a repair ticket/local quota. Those repair lanes must not be
        dropped by the same stale-frontier guard.
        """

        context_text = str(context or "").strip()
        if context_text not in {
            "repair_ticket",
            "repair_ticket_register",
            "local_repair_quota",
            "local_repair_quota_scoped_action",
        }:
            return ""
        reason = str(status.get("reason") or "").strip()
        if reason not in {
            "route_root_assembly_author_failed_signature_hash",
            "route_missing_assembly_bridge_signature_hash",
        }:
            return ""
        if str(status.get("node_kind") or "").strip() != "strategy_route":
            return ""
        work_type = str(
            record.get("work_type") or status.get("work_type") or ""
        ).strip()
        if work_type != "assemble_route":
            return ""
        failure_evidence = any(
            str(record.get(key) or "").strip()
            for key in (
                "proof_attempt_id",
                "failure_signature",
                "local_repair_failure_signature",
                "repair_ticket_id",
            )
        )
        if not failure_evidence and context_text in {
            "local_repair_quota",
            "local_repair_quota_scoped_action",
        }:
            failure_evidence = bool(
                str(
                    getattr(self, "local_repair_quota_failure_signature", "") or ""
                ).strip()
            )
        if not failure_evidence:
            return ""
        return f"proof_backed_{reason}"

    def _terminal_graph_repair_liveness_bypass_key(
        self,
        record: Dict[str, Any],
        *,
        status: Dict[str, Any],
        bypass_reason: str,
    ) -> Tuple[str, str, str, str]:
        target_key = str(
            status.get("node_id")
            or record.get("route_id")
            or record.get("graph_node_id")
            or record.get("node_id")
            or record.get("target_id")
            or ""
        ).strip()
        repair_identity = str(
            record.get("repair_ticket_id")
            or record.get("proof_attempt_id")
            or record.get("failure_signature")
            or record.get("local_repair_failure_signature")
            or getattr(self, "local_repair_quota_failure_signature", "")
            or "unknown"
        ).strip()
        return (
            target_key,
            str(status.get("reason") or bypass_reason or ""),
            str(record.get("work_type") or status.get("work_type") or ""),
            repair_identity or "unknown",
        )

    @staticmethod
    def _graph_repair_record_target_key(
        record: Dict[str, Any],
    ) -> Tuple[str, str]:
        payload = dict(record or {})
        work_type = str(payload.get("work_type") or "").strip()
        primary_fields = {
            "prove_claim_variant": ("variant_id",),
            "formalize_claim": ("claim_id",),
            "formalize_missing_obligation": ("obligation_id",),
            "mine_missing_obligation": ("obligation_id",),
            "target_integrity_adjudication": ("obligation_id",),
            "route_replan": ("replan_id",),
            "assemble_route": ("route_id",),
        }.get(work_type, ())
        for id_field in (
            *primary_fields,
            "graph_node_id",
            "node_id",
            "target_id",
        ):
            value = str(payload.get(id_field) or "").strip()
            if value and value != "root":
                return work_type, value
        return work_type, ""

    @staticmethod
    def _graph_node_allows_bounded_repair(graph: Any, node: Any) -> bool:
        if node is None:
            return False
        metadata = dict(getattr(node, "metadata", {}) or {})
        if any(
            metadata.get(key)
            for key in (
                "route_retired",
                "route_dependency_contradicted",
                "proposal_invalidated",
                "retired_by_repeated_repair_failure",
                "formalization_repeated_unrelated_bridge_suppressed",
                "route_assembly_contract_replan_obsolete",
                "superseded_by_source",
                "target_integrity_contaminated",
                "variant_falsified",
                "falsified",
                "contradicted",
                "candidate_contradicted",
            )
        ):
            return False
        if graph_node_frontier_quarantined(node):
            return False
        is_tombstone = getattr(graph, "is_superseded_tombstone", None)
        if callable(is_tombstone):
            try:
                if bool(is_tombstone(node)):
                    return False
            except Exception:
                return False
        return True

    def _retain_terminal_graph_target_for_bounded_repair(
        self,
        record: Dict[str, Any],
        *,
        repair_identity: str,
        context: str,
    ) -> bool:
        """Reopen only the exact failed/rejected target promised a repair.

        A Lean rejection is terminal evidence for an ordinary frontier scan,
        but it is not terminal while the scheduler owns a concrete, bounded
        repair attempt for that same target.  Retired/superseded work remains
        terminal; the bounded quota/ticket exhaustion path is what eventually
        closes repeat failures.
        """

        _work_type, exact_target_id = self._graph_repair_record_target_key(record)
        if not exact_target_id:
            return False
        status = self.selected_work_graph_liveness_status(record)
        reason = str(status.get("reason") or "").strip()
        if reason not in {"status_failed", "status_rejected"}:
            return False
        # Liveness is dependency-aware and reports the first terminal node it
        # encounters.  A failed parent claim or route must never be reopened
        # merely because a repair ticket targets one of its variants.
        reported_target_id = str(status.get("node_id") or "").strip()
        if reported_target_id != exact_target_id:
            return False
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        node = (
            getattr(graph, "nodes", {}).get(exact_target_id)
            if graph is not None
            else None
        )
        if node is None:
            return False
        if not self._graph_node_allows_bounded_repair(graph, node):
            return False
        reopen = getattr(graph, "reopen_node", None)
        if not callable(reopen):
            return False
        try:
            reopened = bool(
                reopen(
                    exact_target_id,
                    reason=f"bounded repair pending: {context}",
                )
            )
        except Exception:
            reopened = False
        if not reopened:
            return False
        node_metadata = getattr(node, "metadata", None)
        if isinstance(node_metadata, dict):
            node_metadata["repair_pending"] = True
            node_metadata["repair_pending_identity"] = str(repair_identity or "unknown")
            node_metadata["repair_pending_context"] = str(context or "")
            node_metadata["repair_pending_previous_status"] = str(
                status.get("node_status") or ""
            )
        self._increment_dossier_metric(
            "mini_session_terminal_graph_target_retained_for_bounded_repair",
            1,
        )
        self._record_event(
            {
                "phase": "session_graph_repair_pending",
                "iteration": self.iteration,
                "context": str(context or ""),
                "repair_identity": str(repair_identity or ""),
                "target_id": exact_target_id,
                "previous_status": str(status.get("node_status") or ""),
                "selected_work_item": dict(record or {}),
                "verdict": "terminal_graph_target_reopened_repair_pending",
            }
        )
        return True

    def _ensure_graph_target_repair_pending_authority(
        self,
        record: Dict[str, Any],
        *,
        repair_identity: str,
        context: str,
    ) -> bool:
        if self._retain_terminal_graph_target_for_bounded_repair(
            record,
            repair_identity=repair_identity,
            context=context,
        ):
            return True
        _work_type, target_id = self._graph_repair_record_target_key(record)
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        node = nodes.get(target_id) if target_id and isinstance(nodes, dict) else None
        metadata = getattr(node, "metadata", None)
        current_liveness = self.selected_work_graph_liveness_status(record)
        if (
            node is None
            or str(getattr(node, "status", "") or "") != "open"
            or not isinstance(metadata, dict)
            or not bool(metadata.get("repair_pending"))
            or not self._graph_node_allows_bounded_repair(graph, node)
            or not bool(current_liveness.get("live", True))
        ):
            return False
        metadata["repair_pending_identity"] = str(repair_identity or "unknown")
        metadata["repair_pending_context"] = str(context or "")
        return True

    def _bounded_repair_pending_for_graph_work(
        self,
        record: Dict[str, Any],
    ) -> Tuple[bool, str]:
        target_key = self._graph_repair_record_target_key(record)
        if not target_key[1]:
            return False, ""
        local_record = dict(self.local_repair_quota_selected_work_record or {})
        if int(
            self.local_repair_quota_remaining or 0
        ) > 0 and target_key == self._graph_repair_record_target_key(local_record):
            return (
                True,
                str(
                    self.local_repair_quota_failure_signature
                    or local_record.get("failure_signature")
                    or "local_repair_quota"
                ),
            )
        tickets = [
            self.pending_repair_ticket,
            *list(self.pending_repair_ticket_queue or []),
        ]
        for ticket in tickets:
            if (
                ticket is None
                or bool(getattr(ticket, "exhausted", False))
                or not str(getattr(ticket, "proof", "") or "").strip()
            ):
                continue
            ticket_record = self._selected_work_record_from_repair_ticket(
                ticket,
                action_id=str(getattr(ticket, "source_action_id", "") or ""),
            )
            if target_key == self._graph_repair_record_target_key(ticket_record):
                return (
                    True,
                    str(
                        getattr(ticket, "ticket_id", "")
                        or getattr(ticket, "failure_signature", "")
                        or "repair_ticket"
                    ),
                )
        return False, ""

    def _release_stale_graph_target_repair_pending_authority(
        self,
        record: Dict[str, Any],
    ) -> bool:
        """Fail closed when an exact target no longer owns bounded repair."""

        _work_type, target_id = self._graph_repair_record_target_key(record)
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        node = nodes.get(target_id) if target_id and isinstance(nodes, dict) else None
        metadata = getattr(node, "metadata", None)
        if node is None or not isinstance(metadata, dict):
            return False
        if not bool(metadata.get("repair_pending")):
            return False
        prior_status = str(
            metadata.pop("repair_pending_previous_status", "") or "failed"
        )
        metadata.pop("repair_pending", None)
        metadata.pop("repair_pending_identity", None)
        metadata.pop("repair_pending_context", None)
        if str(getattr(node, "status", "") or "") == "open":
            node.status = (
                prior_status if prior_status in {"failed", "rejected"} else "failed"
            )
        return True

    def _release_abandoned_local_repair_graph_authority(
        self,
        record: Dict[str, Any],
        *,
        reason: str,
    ) -> bool:
        """Close a reopened target when its local quota cannot dispatch.

        ``repair_pending`` is a bounded scheduling lease, not a new
        mathematical status. A local quota may reopen a rejected target, but a
        terminal dependency/quarantine or a missing action can invalidate that
        quota before its forced turn runs. Once the quota is zero, retain the
        open target only when an independent repair ticket still owns the same
        exact work identity.
        """

        payload = dict(record or {})
        if not payload:
            return False
        repair_pending, _repair_identity = self._bounded_repair_pending_for_graph_work(
            payload
        )
        if repair_pending:
            return False
        released = self._release_stale_graph_target_repair_pending_authority(payload)
        if not released:
            return False
        self._increment_dossier_metric(
            "mini_session_abandoned_local_repair_graph_authority_released",
            1,
        )
        self._record_event(
            {
                "phase": "session_graph_repair_pending",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "selected_work_item": payload,
                "verdict": "abandoned_local_repair_graph_authority_released",
            }
        )
        return True

    def register_repair_ticket(self, ticket: Optional[RepairTicket]) -> None:
        """Persist a Lean-rejection repair ticket as scheduler-owned work."""

        if ticket is None or not str(ticket.proof or "").strip():
            return
        retired_key = self._repair_ticket_retired_target_key(ticket)
        if retired_key:
            self._suppress_repeated_repair_ticket(
                ticket,
                target_key=retired_key,
                reason="target_retired_repeated_repair_failure",
            )
            return
        ticket_record = self._selected_work_record_from_repair_ticket(
            ticket,
            action_id=str(getattr(ticket, "source_action_id", "") or ""),
        )
        if not bool(getattr(ticket, "exhausted", False)):
            self._ensure_graph_target_repair_pending_authority(
                ticket_record,
                repair_identity=str(
                    getattr(ticket, "ticket_id", "")
                    or getattr(ticket, "failure_signature", "")
                    or "repair_ticket"
                ),
                context="repair_ticket_register",
            )
        if self._selected_work_targets_terminal_graph_work(
            ticket_record,
            context="repair_ticket_register",
            metric_key="mini_session_retired_graph_target_repair_ticket_suppressed",
        ):
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "target_id": str(getattr(ticket, "target_id", "") or ""),
                    "route_id": str(getattr(ticket, "route_id", "") or ""),
                    "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                    "work_type": str(getattr(ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(ticket, "proof_attempt_id", "") or ""
                    ),
                    "selected_work_item": dict(ticket_record),
                    "verdict": "terminal_graph_target_repair_ticket_suppressed",
                }
            )
            return
        if self.pending_repair_ticket is None and self.pending_repair_ticket_queue:
            self._promote_queued_repair_ticket()
        queued = False
        current = self.pending_repair_ticket
        if current is not None and not str(getattr(current, "proof", "") or "").strip():
            self.pending_repair_ticket = None
            current = None
        if current is not None and bool(getattr(current, "exhausted", False)):
            self._exhaust_repair_ticket(current, reason="attempt_budget_exhausted")
            current = self.pending_repair_ticket
        if (
            current is not None
            and str(getattr(current, "proof", "") or "").strip()
            and not bool(getattr(current, "exhausted", False))
        ):
            self.pending_repair_ticket_queue.append(ticket)
            queued = True
        else:
            self.pending_repair_ticket = ticket
        self.repair_ticket_history.append(
            {
                "ticket_id": ticket.ticket_id,
                "turn_index": int(ticket.turn_index or 0),
                "target_id": ticket.target_id,
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "error_type": ticket.error_type,
                "failure_signature": ticket.failure_signature,
                "source_action_id": ticket.source_action_id,
                "root_ticket_id": ticket.root_ticket_id or ticket.ticket_id,
                "repair_depth": int(ticket.repair_depth or 0),
                "max_chain_depth": int(ticket.max_chain_depth or 0),
                "policy_attempts_used": int(
                    getattr(ticket, "policy_attempts_used", 0) or 0
                ),
                "max_policy_attempts": int(
                    getattr(ticket, "max_policy_attempts", 0) or 0
                ),
                "formalization_failure_class": str(
                    (getattr(ticket, "metadata", {}) or {}).get(
                        "formalization_failure_class"
                    )
                    or ""
                ),
                "unknown_identifier": str(
                    (getattr(ticket, "metadata", {}) or {}).get("unknown_identifier")
                    or ""
                ),
                "unknown_identifier_is_target_binder": bool(
                    (getattr(ticket, "metadata", {}) or {}).get(
                        "unknown_identifier_is_target_binder"
                    )
                ),
                "verdict": "queued" if queued else "created",
            }
        )
        del self.repair_ticket_history[:-20]
        self._increment_dossier_metric("mini_session_repair_tickets_created", 1)
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": ticket.ticket_id,
                "target_id": ticket.target_id,
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "error_type": ticket.error_type,
                "failure_signature": ticket.failure_signature,
                "source_action_id": ticket.source_action_id,
                "max_attempts": int(ticket.max_attempts or 0),
                "max_policy_attempts": int(
                    getattr(ticket, "max_policy_attempts", 0) or 0
                ),
                "root_ticket_id": ticket.root_ticket_id or ticket.ticket_id,
                "repair_depth": int(ticket.repair_depth or 0),
                "max_chain_depth": int(ticket.max_chain_depth or 0),
                "formalization_failure_class": str(
                    (getattr(ticket, "metadata", {}) or {}).get(
                        "formalization_failure_class"
                    )
                    or ""
                ),
                "unknown_identifier": str(
                    (getattr(ticket, "metadata", {}) or {}).get("unknown_identifier")
                    or ""
                ),
                "unknown_identifier_is_target_binder": bool(
                    (getattr(ticket, "metadata", {}) or {}).get(
                        "unknown_identifier_is_target_binder"
                    )
                ),
                "requires_api_search_for_unknown_identifier": bool(
                    (getattr(ticket, "metadata", {}) or {}).get(
                        "requires_api_search_for_unknown_identifier"
                    )
                ),
                "queued": queued,
                "queue_depth": len(self.pending_repair_ticket_queue),
                "active_ticket_id": str(
                    getattr(self.pending_repair_ticket, "ticket_id", "") or ""
                ),
                "verdict": "created",
            }
        )
        if queued:
            self._increment_dossier_metric("mini_session_repair_tickets_queued", 1)
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": ticket.ticket_id,
                    "target_id": ticket.target_id,
                    "route_id": str(getattr(ticket, "route_id", "") or ""),
                    "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                    "work_type": str(getattr(ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(ticket, "proof_attempt_id", "") or ""
                    ),
                    "active_ticket_id": str(
                        getattr(self.pending_repair_ticket, "ticket_id", "") or ""
                    ),
                    "queue_depth": len(self.pending_repair_ticket_queue),
                    "verdict": "queued",
                }
            )
        if bool(
            (getattr(ticket, "metadata", {}) or {}).get(
                "requires_api_search_for_unknown_identifier"
            )
        ):
            self._increment_dossier_metric(
                "mini_session_unknown_identifier_api_search_required",
                1,
            )
        if bool(
            (getattr(ticket, "metadata", {}) or {}).get(
                "parse_error_code_generation_failure"
            )
        ):
            self._increment_dossier_metric(
                "mini_session_parse_errors_code_generation_failures",
                1,
            )
        lineage_recorder = getattr(
            getattr(self, "dossier", None),
            "record_proof_lineage_event",
            None,
        )
        if callable(lineage_recorder):
            lineage_recorder(
                event_type="repair_ticket_created",
                envelope=ProofLineageEnvelope.from_metadata(
                    getattr(ticket, "metadata", {}) or {}
                ),
                phase="session_repair_ticket",
                verdict="queued" if queued else "created",
                evidence_hash=str(ticket.failure_signature or ""),
                details={
                    "ticket_id": str(ticket.ticket_id or ""),
                    "target_id": str(ticket.target_id or ""),
                    "work_type": str(ticket.work_type or ""),
                },
            )

    def _sync_conversation_prompt_budget(
        self,
        action_id: str,
        *,
        min_turn_budget: int = 0,
    ) -> int:
        """Keep granted conversation headroom visible in model-facing footers."""

        clean_action_id = str(action_id or "").strip()
        if not clean_action_id.startswith("conversation_turn"):
            return 0
        if not bool(self.conversation_budget_topups_enabled):
            return 0
        action = self.registered_action(clean_action_id)
        if action is None or not hasattr(action, "max_turns_for_budget"):
            return 0
        try:
            old_prompt_budget = int(getattr(action, "max_turns_for_budget", 0) or 0)
        except Exception:
            old_prompt_budget = 0
        budget_floor = 0
        budget = self.budgets.get(clean_action_id)
        if budget is not None:
            try:
                if int(budget.max_invocations) >= 0:
                    budget_floor = max(
                        int(budget.max_invocations),
                        int(budget.invocations or 0),
                    )
            except Exception:
                budget_floor = 0
        new_prompt_budget = max(
            old_prompt_budget,
            int(min_turn_budget or 0),
            budget_floor,
        )
        if new_prompt_budget <= old_prompt_budget:
            return 0
        setattr(action, "max_turns_for_budget", new_prompt_budget)
        conv = getattr(self, "conv", None)
        if conv is not None:
            try:
                conv.turn_budget = max(
                    int(getattr(conv, "turn_budget", 0) or 0),
                    new_prompt_budget,
                )
            except Exception:
                pass
        return new_prompt_budget - old_prompt_budget

    def _promote_queued_repair_ticket(self) -> Optional[RepairTicket]:
        while self.pending_repair_ticket_queue:
            ticket = self.pending_repair_ticket_queue.pop(0)
            if not str(getattr(ticket, "proof", "") or "").strip():
                continue
            if bool(getattr(ticket, "exhausted", False)):
                continue
            self.pending_repair_ticket = ticket
            self._repair_ticket_selected_id = ""
            ticket_record = self._selected_work_record_from_repair_ticket(
                ticket,
                action_id=str(getattr(ticket, "source_action_id", "") or ""),
            )
            self._ensure_graph_target_repair_pending_authority(
                ticket_record,
                repair_identity=str(
                    getattr(ticket, "ticket_id", "")
                    or getattr(ticket, "failure_signature", "")
                    or "repair_ticket"
                ),
                context="repair_ticket_promote",
            )
            self._increment_dossier_metric("mini_session_repair_tickets_promoted", 1)
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": ticket.ticket_id,
                    "target_id": ticket.target_id,
                    "route_id": str(getattr(ticket, "route_id", "") or ""),
                    "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                    "work_type": str(getattr(ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(ticket, "proof_attempt_id", "") or ""
                    ),
                    "queue_depth": len(self.pending_repair_ticket_queue),
                    "verdict": "promoted",
                }
            )
            return ticket
        return None

    def _active_repair_ticket(self) -> Optional[RepairTicket]:
        while True:
            ticket = self.pending_repair_ticket
            if ticket is None:
                return self._promote_queued_repair_ticket()
            if not str(ticket.proof or "").strip():
                self.pending_repair_ticket = None
                continue
            if ticket.exhausted:
                self._exhaust_repair_ticket(ticket, reason="attempt_budget_exhausted")
                continue
            return ticket

    def _exhaust_repair_ticket(self, ticket: RepairTicket, *, reason: str) -> None:
        ticket.metadata["repair_ticket_explicitly_exhausted"] = True
        ticket.metadata["repair_ticket_exhausted_reason"] = str(reason or "")
        self._increment_dossier_metric("mini_session_repair_tickets_exhausted", 1)
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": ticket.ticket_id,
                "target_id": ticket.target_id,
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "attempts_used": int(ticket.attempts_used or 0),
                "max_attempts": int(ticket.max_attempts or 0),
                "policy_attempts_used": int(
                    getattr(ticket, "policy_attempts_used", 0) or 0
                ),
                "max_policy_attempts": int(
                    getattr(ticket, "max_policy_attempts", 0) or 0
                ),
                "reason": str(reason or ""),
                "verdict": "exhausted",
            }
        )
        if self.pending_repair_ticket is ticket:
            self.pending_repair_ticket = None
            self._repair_ticket_selected_id = ""
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        ticket_record = self._selected_work_record_from_repair_ticket(
            ticket,
            action_id=str(getattr(ticket, "source_action_id", "") or ""),
        )
        _work_type, target_id = self._graph_repair_record_target_key(ticket_record)
        if target_id:
            node = nodes.get(target_id) if isinstance(nodes, dict) else None
            metadata = getattr(node, "metadata", None)
            if (
                node is not None
                and isinstance(metadata, dict)
                and str(metadata.get("repair_pending_identity") or "")
                == str(getattr(ticket, "ticket_id", "") or "")
            ):
                target_key = self._graph_repair_record_target_key(ticket_record)
                replacement = next(
                    (
                        queued
                        for queued in list(self.pending_repair_ticket_queue or [])
                        if not bool(getattr(queued, "exhausted", False))
                        and str(getattr(queued, "proof", "") or "").strip()
                        and self._graph_repair_record_target_key(
                            self._selected_work_record_from_repair_ticket(
                                queued,
                                action_id=str(
                                    getattr(queued, "source_action_id", "") or ""
                                ),
                            )
                        )
                        == target_key
                    ),
                    None,
                )
                if replacement is not None:
                    metadata["repair_pending_identity"] = str(
                        getattr(replacement, "ticket_id", "")
                        or getattr(replacement, "failure_signature", "")
                        or "repair_ticket"
                    )
                    metadata["repair_pending_context"] = (
                        "repair_ticket_queued_successor"
                    )
                else:
                    prior_status = str(
                        metadata.pop("repair_pending_previous_status", "") or "failed"
                    )
                    metadata.pop("repair_pending", None)
                    metadata.pop("repair_pending_identity", None)
                    metadata.pop("repair_pending_context", None)
                    if str(getattr(node, "status", "") or "") == "open":
                        node.status = (
                            prior_status
                            if prior_status in {"failed", "rejected"}
                            else "failed"
                        )
        self._record_repair_failure_observation(ticket, reason=reason)

    @staticmethod
    def _repair_ticket_statement_hash(ticket: RepairTicket) -> str:
        statement = str(getattr(ticket, "target_statement", "") or "").strip()
        if not statement:
            return ""
        return hashlib.sha256(statement.encode("utf-8", errors="replace")).hexdigest()[
            :16
        ]

    def _repair_ticket_target_key(self, ticket: RepairTicket) -> str:
        """Stable target-granularity key for durable repair retirement."""

        target_id = str(getattr(ticket, "target_id", "") or "").strip()
        statement_hash = self._repair_ticket_statement_hash(ticket)
        if not target_id and not statement_hash:
            return ""
        metadata = dict(getattr(ticket, "metadata", {}) or {})
        selected_work_item = dict(metadata.get("selected_work_item") or {})
        environment_hash = str(
            metadata.get("statement_environment_hash")
            or metadata.get("lean_environment_hash")
            or selected_work_item.get("statement_environment_hash")
            or selected_work_item.get("lean_environment_hash")
            or getattr(self.dossier, "current_lean_environment_hash", "")
            or ""
        ).strip()
        parts = [
            target_id,
            str(getattr(ticket, "work_type", "") or "").strip(),
            str(getattr(ticket, "route_id", "") or "").strip(),
            str(getattr(ticket, "obligation_id", "") or "").strip(),
            statement_hash,
            environment_hash,
        ]
        return "|".join(parts)

    def _repair_ticket_exact_failure_key(self, ticket: RepairTicket) -> str:
        target_key = self._repair_ticket_target_key(ticket)
        if not target_key:
            return ""
        parts = [
            target_key,
            str(getattr(ticket, "proof_attempt_id", "") or "").strip(),
            str(getattr(ticket, "error_type", "") or "").strip(),
            str(getattr(ticket, "failure_signature", "") or "").strip(),
        ]
        return "|".join(parts)

    def _repair_ticket_retired_target_key(self, ticket: RepairTicket) -> str:
        target_key = self._repair_ticket_target_key(ticket)
        if not target_key:
            return ""
        return target_key if target_key in self.retired_repair_target_keys else ""

    def _suppress_repeated_repair_ticket(
        self,
        ticket: RepairTicket,
        *,
        target_key: str,
        reason: str,
    ) -> None:
        self._increment_dossier_metric(
            "mini_session_repair_tickets_suppressed_repeated_failure",
            1,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_id": str(getattr(ticket, "target_id", "") or ""),
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "failure_signature": str(
                    getattr(ticket, "failure_signature", "") or ""
                ),
                "target_failure_key": str(target_key or ""),
                "reason": str(reason or ""),
                "verdict": "suppressed_repeated_repair_failure",
            }
        )

    def _record_repair_failure_observation(
        self,
        ticket: RepairTicket,
        *,
        reason: str,
    ) -> None:
        observed_reasons = {
            "attempt_budget_exhausted",
            "graph_policy_rejected",
            "repair_turn_lean_rejected",
            "repair_turn_consumed",
        }
        reason_text = str(reason or "").strip()
        if not (
            reason_text in observed_reasons
            or reason_text.startswith("repair_self_check_")
        ):
            return
        ticket_metadata = getattr(ticket, "metadata", None)
        if not isinstance(ticket_metadata, dict):
            ticket_metadata = {}
            ticket.metadata = ticket_metadata
        if ticket_metadata.get("repair_failure_observed"):
            return
        ticket_metadata["repair_failure_observed"] = True
        target_key = self._repair_ticket_target_key(ticket)
        if not target_key:
            return
        exact_key = self._repair_ticket_exact_failure_key(ticket)
        target_count = (
            int(self.repair_failure_target_counts.get(target_key, 0) or 0) + 1
        )
        self.repair_failure_target_counts[target_key] = target_count
        exact_count = 0
        if exact_key:
            exact_count = (
                int(self.repair_failure_exact_counts.get(exact_key, 0) or 0) + 1
            )
            self.repair_failure_exact_counts[exact_key] = exact_count
        threshold = max(1, int(self.repeated_repair_retirement_threshold or 3))
        self._increment_dossier_metric(
            "mini_session_repair_failure_observations",
            1,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_id": str(getattr(ticket, "target_id", "") or ""),
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "error_type": str(getattr(ticket, "error_type", "") or ""),
                "failure_signature": str(
                    getattr(ticket, "failure_signature", "") or ""
                ),
                "exhaustion_reason": str(reason or ""),
                "target_failure_key": target_key,
                "target_failure_count": target_count,
                "exact_failure_count": exact_count,
                "retirement_threshold": threshold,
                "verdict": "repeated_repair_failure_observed",
            }
        )
        if target_count >= threshold:
            self._retire_repeated_repair_target(
                ticket,
                target_key=target_key,
                count=target_count,
                reason=reason,
            )

    def _record_graph_policy_failure_observation(
        self,
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
        *,
        reason: str,
    ) -> bool:
        """Feed repeated graph-native policy failures into durable retirement."""

        if str(getattr(self, "_repair_ticket_selected_id", "") or "").strip():
            return False
        reason_text = str(reason or "").strip()
        if reason_text not in {
            "reused_rejected_lean_fragment",
            "transient_goal_target_sorry_helper",
        }:
            return False
        selected = dict(getattr(self, "selected_work_item_record", {}) or {})
        if not selected:
            return False
        work_type = str(selected.get("work_type") or "").strip()
        if work_type not in {
            "formalize_claim",
            "formalize_missing_obligation",
            "mine_missing_obligation",
            "prove_claim_variant",
            "route_replan",
            "target_integrity_adjudication",
        }:
            return False
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return False
        target_id = ""
        for id_field in (
            "claim_id",
            "obligation_id",
            "variant_id",
            "replan_id",
            "route_id",
            "graph_node_id",
            "node_id",
        ):
            candidate = str(selected.get(id_field) or "").strip()
            if candidate and candidate in nodes:
                target_id = candidate
                break
        if not target_id:
            return False
        target_node = nodes.get(target_id)
        target_statement = str(selected.get("target_statement") or "").strip()
        if not target_statement and target_node is not None:
            target_statement = str(getattr(target_node, "statement", "") or "").strip()
        if target_statement and not graph_statement_is_executable(target_statement):
            target_statement = ""
        rejection_fragments = [
            str(item or "").strip()
            for item in list(metadata.get("rejection_fragments") or ())
            if str(item or "").strip()
        ]
        redirect_key = str(metadata.get("policy_repair_redirect_key") or "").strip()
        fragment_signature = redirect_key or graph_text_hash(
            "\n".join(rejection_fragments)
            or str(metadata.get("lean_error_type") or reason_text)
        )
        ticket = RepairTicket(
            ticket_id=f"graph-policy-{graph_text_hash(target_id + ':' + fragment_signature)}",
            proof="\n".join(rejection_fragments),
            lean_output=str(metadata.get("lean_output") or ""),
            feedback_text=str(metadata.get("feedback_text") or ""),
            feedback_source="graph_policy_failure",
            error_type=reason_text,
            failure_signature=f"{reason_text}:{fragment_signature}",
            target_id=target_id,
            target_statement=target_statement,
            route_id=str(selected.get("route_id") or ""),
            obligation_id=str(selected.get("obligation_id") or target_id),
            work_type=work_type,
            proof_attempt_id=fragment_signature,
            source_action_id=outcome.action_id,
            turn_index=int(self.iteration or 0),
            max_attempts=1,
            metadata={
                "graph_policy_failure_observation": True,
                "selected_work_item": selected,
                "rejection_reason": reason_text,
                "policy_repair_redirect_key": redirect_key,
            },
        )
        target_key = self._repair_ticket_target_key(ticket)
        if not target_key:
            return False
        already_retired = target_key in self.retired_repair_target_keys
        self._increment_dossier_metric(
            "mini_session_graph_policy_failures_observed",
            1,
        )
        self._record_repair_failure_observation(
            ticket,
            reason="graph_policy_rejected",
        )
        now_retired = target_key in self.retired_repair_target_keys
        if now_retired and not already_retired:
            self._increment_dossier_metric(
                "mini_session_graph_policy_targets_retired",
                1,
            )
        self._record_event(
            {
                "phase": "session_graph_policy_failure",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "target_id": target_id,
                "work_type": work_type,
                "reason": reason_text,
                "target_failure_key": target_key,
                "already_retired": already_retired,
                "retired": now_retired,
                "verdict": (
                    "graph_policy_target_retired"
                    if now_retired
                    else "graph_policy_failure_observed"
                ),
            }
        )
        return bool(now_retired)

    def _retire_repeated_repair_target(
        self,
        ticket: RepairTicket,
        *,
        target_key: str,
        count: int,
        reason: str,
    ) -> None:
        if not target_key or target_key in self.retired_repair_target_keys:
            return
        self.retired_repair_target_keys.add(target_key)
        self._increment_dossier_metric(
            "mini_session_repair_targets_retired_repeated_failure",
            1,
        )
        materialized = self._materialize_repeated_repair_target_decomposition(
            ticket,
            target_key=target_key,
            count=count,
            reason=reason,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_id": str(getattr(ticket, "target_id", "") or ""),
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "target_failure_key": target_key,
                "target_failure_count": int(count or 0),
                "reason": str(reason or ""),
                "materialized_decomposition": bool(materialized),
                "selected_work_item": dict(materialized or {}),
                "verdict": "repeated_repair_target_retired",
            }
        )

    def _materialize_repeated_repair_target_decomposition(
        self,
        ticket: RepairTicket,
        *,
        target_key: str,
        count: int,
        reason: str,
    ) -> Dict[str, Any]:
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return {}
        root_id = str(getattr(graph, "root_node_id", "") or "root").strip() or "root"
        target_id = str(getattr(ticket, "target_id", "") or "").strip()
        target_node = nodes.get(target_id) if target_id else None
        source_id = target_id if target_node is not None else root_id
        target_statement = str(getattr(ticket, "target_statement", "") or "").strip()
        if not target_statement and target_node is not None:
            target_statement = str(getattr(target_node, "statement", "") or "").strip()
        if not target_statement:
            target_statement = str(getattr(dossier, "root_statement", "") or "").strip()
        if (
            target_node is not None
            and str(getattr(target_node, "status", "") or "") != "proved"
        ):
            metadata = getattr(target_node, "metadata", None)
            if not isinstance(metadata, dict):
                metadata = {}
                target_node.metadata = metadata
            metadata["retired_by_repeated_repair_failure"] = True
            metadata["repair_failure_count"] = int(count or 0)
            metadata["repair_failure_key"] = str(target_key or "")
            metadata["repair_failure_reason"] = str(reason or "")
            metadata.pop("repair_pending", None)
            metadata.pop("repair_pending_identity", None)
            metadata.pop("repair_pending_context", None)
            metadata.pop("repair_pending_previous_status", None)
            try:
                graph.mark_node_failed(target_id, status="failed")
            except Exception:
                try:
                    target_node.status = "failed"
                except Exception:
                    pass
        route = graph.record_strategy_route(
            name=f"repeated_repair_decomposition_{int(self.iteration or 0)}",
            description=(
                "Decompose a graph target after repeated Lean repair failures; "
                "the previous target remains stale until smaller bridge claims "
                "or retrieval evidence change the route."
            ),
            route_key=f"repeated_repair_target:{target_key}",
            score=0.85,
            phase="session_repair_ticket",
            turn_index=int(self.iteration or 0),
            metadata={
                "route_scope": "partial_route",
                "source": "repeated_repair_target_retirement",
                "repair_ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_failure_key": str(target_key or ""),
                "target_failure_count": int(count or 0),
                "failure_signature": str(
                    getattr(ticket, "failure_signature", "") or ""
                ),
                "error_type": str(getattr(ticket, "error_type", "") or ""),
                "root_unlock_bottleneck": True,
                "priority": 0.85,
            },
        )
        obligation_reason = (
            "The previous graph target repeatedly failed Lean repair. Prove or "
            "formalize a strictly smaller bridge for that exact target before "
            "another direct repair attempt."
        )
        target_hash = (
            hashlib.sha256(
                target_statement.encode("utf-8", errors="replace")
            ).hexdigest()[:16]
            if target_statement
            else ""
        )
        decomposition_statement = (
            "Decompose retired Lean repair target "
            f"{target_hash or str(target_key or '')[:16]} into one or more "
            "strictly smaller Lean-checkable bridge lemmas needed for the "
            "retired target."
        )
        obligation = graph.record_missing_obligation(
            statement=decomposition_statement,
            reason=obligation_reason,
            source_node_id=source_id,
            route_id=route.node_id,
            phase="session_repair_ticket",
            turn_index=int(self.iteration or 0),
            error_type="repeated_repair_target_requires_decomposition",
            metadata={
                "source": "repeated_repair_target_retirement",
                "repair_ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_failure_key": str(target_key or ""),
                "target_failure_count": int(count or 0),
                "failure_signature": str(
                    getattr(ticket, "failure_signature", "") or ""
                ),
                "parent_repair_target_id": target_id,
                "parent_repair_target_statement": target_statement,
                "formalization_bridge_contract": "strict_decomposition_bridge",
                "formalization_bridge_parent_statement": target_statement,
                "decomposition_request_statement": decomposition_statement,
                "requires_strict_smaller_bridge": True,
                "forbid_repair_target_statement": target_statement,
                "retired_target_statement_hash": target_hash,
                "formalization_required": True,
                "materialization_required": True,
                "formalization_statement_pending": True,
                "root_unlock_bottleneck": True,
                **self.dossier.statement_environment_metadata(),
                "priority": 0.9,
                "identity_key": ":".join(
                    item
                    for item in [
                        "repeated_repair_target",
                        str(target_key or ""),
                        str(target_hash or ""),
                    ]
                    if item
                ),
            },
        )
        replan = graph.record_replan_item(
            source_node_id=source_id,
            route_id=route.node_id,
            obligation_id=obligation.node_id,
            reason=obligation_reason,
            phase="session_repair_ticket",
            turn_index=int(self.iteration or 0),
            priority=0.9,
            metadata={
                "source": "repeated_repair_target_retirement",
                "repair_ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_failure_key": str(target_key or ""),
                "target_failure_count": int(count or 0),
                "formalization_required": False,
                "root_unlock_bottleneck": True,
                "target_statement": decomposition_statement,
                "parent_repair_target_statement": target_statement,
                "formalization_bridge_contract": "strict_decomposition_bridge",
                "requires_strict_smaller_bridge": True,
                "materialization_required": True,
                "formalization_statement_pending": True,
            },
        )
        self._increment_dossier_metric(
            "mini_session_repair_retirement_decomposition_materialized",
            1,
        )
        self.fallback_actions_attempted = False
        return {
            "work_type": "mine_missing_obligation",
            "node_id": obligation.node_id,
            "graph_node_id": obligation.node_id,
            "obligation_id": obligation.node_id,
            "route_id": route.node_id,
            "replan_id": replan.node_id,
            "materialization_seed": decomposition_statement,
            "decomposition_request_statement": decomposition_statement,
            "parent_repair_target_statement": target_statement,
            "formalization_required": True,
            "materialization_required": True,
            "formalization_statement_pending": True,
            "source": "repeated_repair_target_retirement",
            "target_failure_key": str(target_key or ""),
            "root_unlock_bottleneck": True,
        }

    def _mark_repair_policy_narrowing_required(
        self,
        ticket: RepairTicket,
        *,
        reason: str,
        selected_work_override: Optional[Dict[str, Any]] = None,
    ) -> bool:
        """Escalate procedural repair misses away from another same-target turn."""

        old_quota_remaining = int(self.local_repair_quota_remaining or 0)
        old_repair_first_until = int(
            getattr(self, "repair_first_until_conversation_turn", 0) or 0
        )
        old_selected_work = dict(self.local_repair_quota_selected_work_record)
        selected_work = dict(selected_work_override or {})
        if not selected_work:
            selected_work = dict(getattr(self, "selected_work_item_record", {}) or {})
        if not selected_work:
            metadata = getattr(ticket, "metadata", None)
            if isinstance(metadata, dict):
                raw_selected = (
                    metadata.get("selected_work_item")
                    or metadata.get("selected_work_item_record")
                    or {}
                )
                if isinstance(raw_selected, dict):
                    selected_work = dict(raw_selected)
        if not selected_work:
            selected_work = dict(old_selected_work)
        if not selected_work:
            try:
                selected_work = self._selected_work_record_from_repair_ticket(
                    ticket,
                    action_id=str(getattr(ticket, "source_action_id", "") or ""),
                )
            except Exception:
                selected_work = {}
        executable_statement = self._repair_policy_narrowing_executable_statement(
            selected_work,
            ticket,
        )
        if not executable_statement:
            self._increment_dossier_metric(
                "mini_session_repair_policy_narrowing_skipped_no_executable_scope",
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "reason": str(reason or ""),
                    "selected_work_item": selected_work,
                    "verdict": ("repair_policy_narrowing_skipped_no_executable_scope"),
                }
            )
            return False
        selected_work.setdefault("target_statement", executable_statement)
        self.local_repair_quota_remaining = 0
        self.local_repair_quota_reason = ""
        self.local_repair_quota_failure_signature = ""
        self.local_repair_quota_selected_work_record = {}
        self.repair_first_until_conversation_turn = 0
        self.repair_first_reason = ""
        self._clear_policy_repair_redirect_selected_work()
        self.repair_policy_narrowing_required = True
        self.repair_policy_narrowing_reason = str(reason or "")
        self.repair_policy_narrowing_selected_work_record = selected_work
        scope_identity = self._refresh_repair_policy_narrowing_scope_identity(
            ticket=ticket,
            reason=reason,
        )
        self.fallback_actions_attempted = False
        self._increment_dossier_metric(
            "mini_session_repair_tickets_policy_narrowing_required",
            1,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": ticket.ticket_id,
                "target_id": ticket.target_id,
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "reason": str(reason or ""),
                "cleared_local_repair_quota": old_quota_remaining,
                "cleared_repair_first_until": old_repair_first_until,
                "selected_work_item": selected_work,
                "scope_identity": scope_identity,
                "verdict": "repair_policy_narrowing_required",
            }
        )
        return True

    def _repair_ticket_is_unscoped_root_level(
        self,
        ticket: Optional[RepairTicket],
    ) -> bool:
        if ticket is None:
            return False
        record = {
            "work_type": str(getattr(ticket, "work_type", "") or ""),
            "route_id": str(getattr(ticket, "route_id", "") or ""),
            "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
            "target_id": str(getattr(ticket, "target_id", "") or ""),
        }
        return self._work_record_is_unscoped_root_level(record)

    def _work_record_is_unscoped_root_level(
        self,
        record: Optional[Dict[str, Any]],
    ) -> bool:
        if not self._root_repair_redirect_required():
            return False
        payload = dict(record or {})
        work_type = str(payload.get("work_type") or "").strip()
        if work_type and work_type != "root_repair":
            return False
        if str(payload.get("route_id") or "").strip():
            return False
        if str(payload.get("obligation_id") or "").strip():
            return False
        root_node_id = str(
            getattr(getattr(self, "proof_state", None), "root_node_id", "root")
            or "root"
        ).strip()
        target_id = str(
            payload.get("target_id")
            or payload.get("node_id")
            or payload.get("graph_node_id")
            or ""
        ).strip()
        return target_id in {"", "root", root_node_id}

    def _stagnation_fallback_action_available(self) -> bool:
        if self.stagnation_counter < self.max_stagnation:
            return False
        if self.fallback_actions_attempted or not self.fallback_action_ids:
            return False
        for action in self.actions:
            if action.id not in self.fallback_action_ids:
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._safe_is_applicable(action, context="fallback_precheck"):
                return True
        return False

    def _arm_available_fallback_after_no_applicable(self) -> bool:
        """Let the parent loop own a last-resort action before quiescence.

        A scheduler can run out of ordinary dispatch lanes before the numeric
        stagnation threshold is reached.  The adaptive recursive fallback is
        still registered, budgeted, and applicable in that state, but the
        fallback selector is deliberately gated by the threshold.  Returning
        quiescent here used to make the factory run that same recursive driver
        after the session had already declared quiescence.

        Advance only the scheduling signal needed to enter the existing
        fallback selector. The fallback action remains the sole owner of its
        pass reservation, budget debit, and outcome application. The strict
        ``old < threshold`` guard also prevents an
        inapplicable/suppressed fallback from creating a no-action loop.
        """

        if self.fallback_actions_attempted or not self.fallback_action_ids:
            return False
        old_stagnation = int(self.stagnation_counter or 0)
        threshold = max(0, int(self.max_stagnation or 0))
        if old_stagnation >= threshold:
            return False
        available_ids: List[str] = []
        for action in self.actions:
            if action.id not in self.fallback_action_ids:
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._safe_is_applicable(action, context="no_applicable_fallback"):
                available_ids.append(str(action.id))
        if not available_ids:
            return False
        ordered_available = sorted(
            available_ids,
            key=lambda action_id: next(
                (
                    (
                        action.priority,
                        action.cost_estimate_s,
                        index,
                    )
                    for index, action in enumerate(self.actions)
                    if action.id == action_id
                ),
                (10**9, float("inf"), 10**9),
            ),
        )
        self.pending_fallback_action_id = ordered_available[0]
        self.stagnation_counter = threshold
        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + 2,
        )
        self.last_failure_reason = ""
        self._record_event(
            {
                "phase": "session_no_applicable_recovery",
                "iteration": self.iteration,
                "previous_stagnation_counter": old_stagnation,
                "stagnation_counter": self.stagnation_counter,
                "max_stagnation": threshold,
                "fallback_action_ids": available_ids,
                "reserved_fallback_action_id": self.pending_fallback_action_id,
                "verdict": "available_fallback_armed_before_quiescence",
            }
        )
        return True

    def _select_reserved_no_applicable_fallback(self) -> Optional[Action]:
        """Dispatch the fallback reserved by the preceding quiescence scan."""

        action_id = str(self.pending_fallback_action_id or "").strip()
        if not action_id:
            return None
        action = self.registered_action(action_id)
        if self._reserved_no_applicable_fallback_dispatchable(action_id):
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "action_id": action_id,
                    "stagnation_counter": int(self.stagnation_counter or 0),
                    "max_stagnation": int(self.max_stagnation or 0),
                    "verdict": "reserved_fallback_dispatched",
                }
            )
            return action
        self.pending_fallback_action_id = ""
        self._record_event(
            {
                "phase": "session_no_applicable_recovery",
                "iteration": self.iteration,
                "action_id": action_id,
                "verdict": "reserved_fallback_released_unavailable",
            }
        )
        return None

    def _reserved_no_applicable_fallback_dispatchable(
        self,
        action_id: str,
    ) -> bool:
        action_id = str(action_id or "").strip()
        action = self.registered_action(action_id)
        budget = self.budgets.get(action_id)
        pool_attr = str(getattr(action, "budget_attr", "") or "").strip()
        pool_available = not (
            pool_attr
            and hasattr(self, pool_attr)
            and int(getattr(self, pool_attr, 0) or 0) <= 0
        )
        runnable = bool(
            action is not None
            and action_id in self.fallback_action_ids
            and not self._model_call_deferred_static_action_effective(action_id)
            and not self.fallback_actions_attempted
            and (budget is None or not budget.exhausted())
            and pool_available
        )
        return runnable

    def _suppress_fresh_unscoped_root_repair_ticket(
        self,
        ticket: Optional[RepairTicket],
        *,
        reason: str,
        predecessor: Optional[RepairTicket] = None,
    ) -> bool:
        if not self._repair_ticket_is_unscoped_root_level(ticket):
            return False
        if (
            predecessor is not None
            and ticket is not None
            and self._repair_ticket_is_unscoped_root_level(predecessor)
        ):
            predecessor_root_id = str(
                getattr(predecessor, "root_ticket_id", "")
                or getattr(predecessor, "ticket_id", "")
                or ""
            ).strip()
            ticket_root_id = str(
                getattr(ticket, "root_ticket_id", "") or ""
            ).strip()
            predecessor_max_depth = int(
                getattr(predecessor, "max_chain_depth", 0) or 0
            )
            ticket_max_depth = int(getattr(ticket, "max_chain_depth", 0) or 0)
            predecessor_depth = int(getattr(predecessor, "repair_depth", 0) or 0)
            ticket_depth = int(getattr(ticket, "repair_depth", 0) or 0)
            if (
                predecessor_root_id
                and ticket_root_id == predecessor_root_id
                and predecessor_max_depth > 0
                and ticket_max_depth == predecessor_max_depth
                and predecessor_depth >= 0
                and ticket_depth == predecessor_depth + 1
                and ticket_depth < ticket_max_depth
            ):
                return False
        self._increment_dossier_metric(
            "mini_session_unscoped_root_repair_new_tickets_suppressed",
            1,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "target_id": str(getattr(ticket, "target_id", "") or ""),
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "reason": str(reason or ""),
                "verdict": "fresh_unscoped_root_repair_ticket_suppressed",
            }
        )
        return True

    def _redirect_unscoped_root_repair_ticket_to_scope(
        self,
        ticket: RepairTicket,
        *,
        reason: str,
    ) -> bool:
        if not self._repair_ticket_is_unscoped_root_level(ticket):
            return False
        materialized = self._record_unscoped_root_repair_replan(
            ticket,
            reason=reason,
        )
        if not materialized:
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "reason": str(reason or ""),
                    "verdict": "unscoped_root_repair_scope_redirect_failed",
                }
            )
            return False
        self._increment_dossier_metric(
            "mini_session_unscoped_root_repair_tickets_scope_redirected",
            1,
        )
        self._mark_repair_policy_narrowing_required(
            ticket,
            reason=reason,
            selected_work_override=materialized,
        )
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "selected_work_item": dict(materialized),
                "reason": str(reason or ""),
                "verdict": "unscoped_root_repair_redirected_to_scope",
            }
        )
        return True

    def _materialize_unselected_root_policy_miss(
        self,
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
        *,
        reason: str,
    ) -> bool:
        if not str(reason or "").startswith("repair_self_check_"):
            return False
        if not self._root_repair_redirect_required():
            return False
        dossier = getattr(self, "dossier", None)
        target_statement = str(
            getattr(dossier, "root_statement", "")
            or getattr(getattr(self, "conv", None), "goal_statement", "")
            or ""
        ).strip()
        seed = "\n".join(
            [
                str(outcome.action_id or ""),
                str(self.iteration or 0),
                str(reason or ""),
                target_statement,
                str(metadata.get("lean_failure_signature") or ""),
            ]
        )
        ticket_id = (
            "unselected-root-policy-"
            + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
        )
        ticket = RepairTicket(
            ticket_id=ticket_id,
            proof=str(outcome.proof or reason or "repair-self-check-policy-miss"),
            lean_output=str(metadata.get("lean_output") or ""),
            feedback_text=str(reason or ""),
            error_type=str(metadata.get("lean_error_type") or ""),
            failure_signature=str(
                metadata.get("lean_failure_signature") or reason or ticket_id
            ),
            target_id="root",
            target_statement=target_statement,
            work_type="root_repair",
            source_action_id=str(outcome.action_id or ""),
            turn_index=int(self.iteration or 0),
            metadata={
                "policy_rejection_reason": str(reason or ""),
                "unselected_root_policy_miss": True,
            },
        )
        redirected = self._redirect_unscoped_root_repair_ticket_to_scope(
            ticket,
            reason=str(reason or "repair_self_check_policy_miss"),
        )
        if redirected:
            self._increment_dossier_metric(
                "mini_session_unselected_root_policy_misses_scope_redirected",
                1,
            )
        return redirected

    def _materialize_unscoped_root_quota_suppression(
        self,
        *,
        action_id: str,
        reason: str,
        failure_signature: str,
        selected_work_record: Dict[str, Any],
    ) -> Dict[str, Any]:
        if not self._root_repair_redirect_required():
            return {}
        dossier = getattr(self, "dossier", None)
        target_statement = str(
            selected_work_record.get("target_statement")
            or getattr(dossier, "root_statement", "")
            or getattr(getattr(self, "conv", None), "goal_statement", "")
            or ""
        ).strip()
        seed = "\n".join(
            [
                str(action_id or ""),
                str(self.iteration or 0),
                str(reason or ""),
                str(failure_signature or ""),
                target_statement,
            ]
        )
        ticket_id = (
            "unscoped-root-quota-"
            + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
        )
        ticket = RepairTicket(
            ticket_id=ticket_id,
            proof=str(reason or "local-repair-quota-suppressed"),
            feedback_text=str(reason or ""),
            failure_signature=str(failure_signature or reason or ticket_id),
            target_id="root",
            target_statement=target_statement,
            work_type="root_repair",
            source_action_id=str(action_id or ""),
            turn_index=int(self.iteration or 0),
            metadata={
                "local_repair_quota_suppressed": True,
                "selected_work_item": dict(selected_work_record),
            },
        )
        materialized = self._record_unscoped_root_repair_replan(
            ticket,
            reason="unscoped_root_quota_suppressed",
        )
        if materialized:
            self._mark_repair_policy_narrowing_required(
                ticket,
                reason="unscoped_root_quota_suppressed",
                selected_work_override=materialized,
            )
        return materialized

    def _unscoped_root_repair_is_local_proof_failure(
        self,
        ticket: RepairTicket,
        *,
        selected_work_metadata: Dict[str, Any],
    ) -> bool:
        """Keep local proof-shape failures out of graph materialization."""

        work_type = str(selected_work_metadata.get("work_type") or "").strip()
        if work_type in {
            "formalize_claim",
            "formalize_missing_obligation",
            "mine_missing_obligation",
        }:
            return False
        if bool(
            selected_work_metadata.get("formalization_required")
            or selected_work_metadata.get("materialization_required")
        ):
            return False
        metadata = dict(getattr(ticket, "metadata", {}) or {})
        failure_analysis = dict(metadata.get("failure_analysis") or {})
        analysis_error_type = str(failure_analysis.get("error_type") or "").strip()
        raw_details = failure_analysis.get("details")
        details = dict(raw_details) if isinstance(raw_details, dict) else {}
        structured_missing_evidence = any(
            str(value or "").strip()
            for value in (
                details.get("unknown_identifier"),
                details.get("unknown_constant"),
                details.get("missing_instance"),
                metadata.get("unknown_identifier"),
                metadata.get("unknown_constant"),
                metadata.get("missing_instance"),
            )
        )
        if (
            analysis_error_type
            in {
                "unknown_identifier",
                "unknown_constant",
                "missing_instance",
            }
            or structured_missing_evidence
        ):
            return False
        error_type = str(
            getattr(ticket, "error_type", "") or analysis_error_type or ""
        ).strip()
        if error_type not in {
            "type_mismatch",
            "application_type_mismatch",
            "invalid_projection",
            "projection_error",
            "field_not_found",
            "binder_arity_mismatch",
            "parse_error",
            "unknown_universe",
            "unification_failed",
        }:
            return False
        evidence_text = "\n".join(
            str(item or "")
            for item in (
                details.get("unknown_identifier"),
                details.get("unknown_constant"),
                details.get("missing_instance"),
                metadata.get("unknown_identifier"),
                metadata.get("unknown_constant"),
                metadata.get("missing_instance"),
                failure_analysis.get("diagnostic_search_text"),
                getattr(ticket, "lean_output", ""),
                getattr(ticket, "feedback_text", ""),
            )
        )
        raw_evidence_type = fallback_error_type_from_text(evidence_text)
        try:
            parsed_evidence = parse_lean_output(evidence_text, 1)
        except Exception:
            parsed_evidence = None
        if (
            raw_evidence_type in {"unknown_identifier", "missing_instance"}
            or bool(getattr(parsed_evidence, "unknown_identifier", False))
            or bool(str(getattr(parsed_evidence, "missing_instance", "") or "").strip())
        ):
            return False
        return True

    def _record_unscoped_root_repair_replan(
        self,
        ticket: RepairTicket,
        *,
        reason: str,
    ) -> Dict[str, Any]:
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        if graph is None:
            return {}
        try:
            root_id = str(getattr(graph, "root_node_id", "") or "root").strip()
            signature = str(
                getattr(ticket, "failure_signature", "") or ticket.ticket_id
            ).strip()
            obligation_reason = (
                "Formalize the smallest local theorem or bridge obligation "
                "needed to replace the rejected unscoped root repair; do not "
                "attempt root assembly until the route obligations are proved."
            )
            ticket_metadata = dict(getattr(ticket, "metadata", {}) or {})
            selected_work_metadata = dict(
                ticket_metadata.get("selected_work_item") or {}
            )
            if self._unscoped_root_repair_is_local_proof_failure(
                ticket,
                selected_work_metadata=selected_work_metadata,
            ):
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                        "error_type": str(getattr(ticket, "error_type", "") or ""),
                        "reason": "unscoped_root_repair_local_proof_failure",
                        "verdict": "unscoped_root_repair_replan_rejected",
                    }
                )
                return {}
            explicit_parent_target = (
                selected_work_metadata.get("materialization_parent_statement")
                or selected_work_metadata.get("formalization_bridge_parent_statement")
                or selected_work_metadata.get("parent_repair_target_statement")
                or ticket_metadata.get("original_root_statement")
            )
            parent_target_statement = str(
                explicit_parent_target
                or getattr(ticket, "target_statement", "")
                or getattr(getattr(self, "dossier", None), "root_statement", "")
                or getattr(getattr(self, "conv", None), "goal_statement", "")
                or ""
            ).strip()
            if not parent_target_statement:
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                        "reason": "unscoped_root_repair_missing_parent_target",
                        "verdict": "unscoped_root_repair_replan_rejected",
                    }
                )
                return {}
            route = graph.record_strategy_route(
                name=f"unscoped_root_repair_{int(self.iteration or 0)}",
                description=(
                    "Replan after an unscoped root Lean rejection; mine explicit "
                    "route obligations before another root proof repair."
                ),
                route_key=(
                    "unscoped_root_repair:"
                    + str(getattr(ticket, "target_id", "") or "root")
                    + ":"
                    + signature
                ),
                score=0.35,
                phase="session_repair_ticket",
                turn_index=int(self.iteration or 0),
                metadata={
                    "route_scope": "partial_route",
                    "source": "unscoped_root_repair_ticket",
                    "repair_ticket_id": str(ticket.ticket_id or ""),
                    "failure_signature": signature,
                    "error_type": str(getattr(ticket, "error_type", "") or ""),
                },
            )
            parent_target_hash = (
                hashlib.sha256(parent_target_statement.encode("utf-8")).hexdigest()[:16]
                if parent_target_statement
                else ""
            )
            forbidden_fragments: List[str] = []

            def add_forbidden_fragment(fragment: object) -> None:
                text = " ".join(str(fragment or "").split()).strip()
                if text and text not in forbidden_fragments:
                    forbidden_fragments.append(text[:240])

            for fragment in list(ticket_metadata.get("rejection_fragments") or ()):
                add_forbidden_fragment(fragment)
            failure_analysis = dict(ticket_metadata.get("failure_analysis") or {})
            add_forbidden_fragment(failure_analysis.get("diagnostic_search_text"))
            raw_unknown_identifier = ""
            raw_missing_instance = ""
            for raw_evidence_text in (
                getattr(ticket, "lean_output", ""),
                getattr(ticket, "feedback_text", ""),
                failure_analysis.get("diagnostic_search_text"),
            ):
                fragment_text = str(raw_evidence_text or "")
                if not fragment_text.strip():
                    continue
                try:
                    parsed_raw_evidence = parse_lean_output(fragment_text, 1)
                except Exception:
                    parsed_raw_evidence = None
                if not raw_unknown_identifier:
                    raw_unknown_identifier = str(
                        getattr(
                            parsed_raw_evidence,
                            "unknown_identifier_name",
                            "",
                        )
                        or ""
                    ).strip()
                if not raw_missing_instance:
                    parsed_missing_instance = str(
                        getattr(parsed_raw_evidence, "missing_instance", "") or ""
                    ).strip()
                    if parsed_missing_instance:
                        raw_missing_instance = parsed_missing_instance
                if (
                    not raw_missing_instance
                    and fallback_error_type_from_text(fragment_text)
                    == "missing_instance"
                ):
                    raw_missing_instance = next(
                        (
                            line.strip()
                            for line in fragment_text.splitlines()
                            if fallback_error_type_from_text(line) == "missing_instance"
                        ),
                        "",
                    )
            details = failure_analysis.get("details")
            if isinstance(details, dict):
                unknown_identifier = str(
                    ticket_metadata.get("unknown_identifier")
                    or ticket_metadata.get("unknown_constant")
                    or details.get("unknown_identifier")
                    or details.get("unknown_constant")
                    or raw_unknown_identifier
                    or ""
                ).strip()
                missing_instance = str(
                    ticket_metadata.get("missing_instance")
                    or details.get("missing_instance")
                    or raw_missing_instance
                    or ""
                ).strip()
                add_forbidden_fragment(unknown_identifier)
                add_forbidden_fragment(missing_instance)
                for key in ("message", "first_line", "term", "expected"):
                    add_forbidden_fragment(details.get(key))
            else:
                unknown_identifier = str(
                    ticket_metadata.get("unknown_identifier")
                    or ticket_metadata.get("unknown_constant")
                    or raw_unknown_identifier
                    or ""
                ).strip()
                missing_instance = str(
                    ticket_metadata.get("missing_instance")
                    or raw_missing_instance
                    or ""
                ).strip()
                add_forbidden_fragment(unknown_identifier)
                add_forbidden_fragment(missing_instance)
            for diagnostic in list(failure_analysis.get("diagnostics") or ())[:4]:
                if isinstance(diagnostic, dict):
                    add_forbidden_fragment(
                        diagnostic.get("summary") or diagnostic.get("message")
                    )
            failure_analysis_payload = dict(failure_analysis)
            failure_analyses_payload = (
                [failure_analysis_payload] if failure_analysis_payload else []
            )
            first_failure_analysis_payload = dict(failure_analysis_payload)
            latest_failure_analysis_payload = dict(failure_analysis_payload)
            for line in str(getattr(ticket, "lean_output", "") or "").splitlines()[:8]:
                add_forbidden_fragment(line)
            obligation_identity_key = ":".join(
                item
                for item in [
                    "unscoped_root_repair",
                    str(getattr(ticket, "ticket_id", "") or ""),
                    signature,
                    parent_target_hash,
                ]
                if item
            )
            obligation_statement = (
                "Formalize a parent-anchored auxiliary bridge for unscoped root "
                "repair "
                f"{parent_target_hash or hashlib.sha256(signature.encode('utf-8', errors='replace')).hexdigest()[:16]}; "
                "the bridge must share mathematical content with the parent "
                "target and contribute to later parent assembly, not merely "
                "repair a rejected identifier or generic library fact."
            )
            bridge_metadata = {
                "source": "unscoped_root_repair_ticket",
                "repair_ticket_id": str(ticket.ticket_id or ""),
                "failure_signature": signature,
                "formalization_required": True,
                "materialization_required": True,
                "formalization_statement_pending": True,
                "materialization_seed": obligation_statement,
                "identity_key": obligation_identity_key,
                "parent_repair_target_statement": parent_target_statement,
                "materialization_parent_statement": parent_target_statement,
                "formalization_bridge_contract": "auxiliary_bridge_support",
                "formalization_bridge_parent_statement": parent_target_statement,
                "auxiliary_bridge_parent_assembly_required": True,
                "unscoped_root_repair_structured_obligation": True,
                "bridge_relevance_required": True,
                "forbidden_materialization_fragments": forbidden_fragments[:8],
                "rejected_root_failure_analysis": failure_analysis_payload,
                "rejected_root_first_failure_analysis": first_failure_analysis_payload,
                "rejected_root_latest_failure_analysis": latest_failure_analysis_payload,
                "rejected_root_failure_analyses": failure_analyses_payload,
                "rejected_root_lean_output": str(
                    getattr(ticket, "lean_output", "") or ""
                )[:1600],
                "rejected_root_tool_call_log": list(
                    ticket_metadata.get("tool_call_log") or ()
                )[:12],
                "rejected_root_error_type": str(
                    getattr(ticket, "error_type", "") or ""
                ),
                "rejected_root_unknown_identifier": unknown_identifier,
                "rejected_root_unknown_identifiers": (
                    [unknown_identifier] if unknown_identifier else []
                ),
                "rejected_root_missing_instance": missing_instance,
                "rejected_root_missing_instances": (
                    [missing_instance] if missing_instance else []
                ),
                **self.dossier.statement_environment_metadata(),
            }
            obligation = graph.record_missing_obligation(
                statement=obligation_statement,
                reason=obligation_reason,
                source_node_id=root_id,
                route_id=route.node_id,
                phase="session_repair_ticket",
                turn_index=int(self.iteration or 0),
                error_type="unscoped_root_repair_requires_obligation",
                metadata=bridge_metadata,
            )
            formalization_obligation_key = str(
                obligation.metadata.get("formalization_obligation_key") or ""
            ).strip()
            duplicate_obligation_reused = bool(
                obligation.metadata.pop("formalization_duplicate_reused_last", False)
            )
            bridge_metadata["formalization_obligation_key"] = (
                formalization_obligation_key
            )
            replan = None
            if not duplicate_obligation_reused:
                replan = graph.record_replan_item(
                    source_node_id=root_id,
                    route_id=route.node_id,
                    obligation_id=obligation.node_id,
                    reason=obligation_reason,
                    phase="session_repair_ticket",
                    turn_index=int(self.iteration or 0),
                    priority=0.7,
                    metadata={
                        **bridge_metadata,
                        "target_statement": str(
                            getattr(ticket, "target_statement", "") or ""
                        ),
                        "route_replan_requires_obligation": True,
                    },
                )
                replan.metadata["schedulable"] = False
        except Exception as exc:
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "exception_type": type(exc).__name__,
                    "verdict": "unscoped_root_repair_replan_failed",
                }
            )
            return {}
        self._increment_dossier_metric(
            "mini_session_unscoped_root_repair_replans",
            1,
        )
        if duplicate_obligation_reused:
            self._increment_dossier_metric(
                "mini_session_graph_formalization_duplicate_obligations_suppressed",
                1,
            )
        else:
            self._increment_dossier_metric(
                "mini_session_unscoped_root_repair_structured_obligations",
                1,
            )
        obligation_metadata = dict(getattr(obligation, "metadata", {}) or {})
        retained_forbidden_fragments = list(
            obligation_metadata.get("forbidden_materialization_fragments")
            or forbidden_fragments[:8]
        )
        retained_unknown_identifier = str(
            obligation_metadata.get("rejected_root_unknown_identifier")
            or unknown_identifier
            or ""
        )
        retained_missing_instance = str(
            obligation_metadata.get("rejected_root_missing_instance")
            or missing_instance
            or ""
        )
        retained_unknown_identifiers = list(
            obligation_metadata.get("rejected_root_unknown_identifiers")
            or ([retained_unknown_identifier] if retained_unknown_identifier else [])
        )
        retained_missing_instances = list(
            obligation_metadata.get("rejected_root_missing_instances")
            or ([retained_missing_instance] if retained_missing_instance else [])
        )
        retained_failure_analysis = dict(
            obligation_metadata.get("rejected_root_failure_analysis") or {}
        )
        retained_first_failure_analysis = dict(
            obligation_metadata.get("rejected_root_first_failure_analysis")
            or retained_failure_analysis
            or {}
        )
        retained_latest_failure_analysis = dict(
            obligation_metadata.get("rejected_root_latest_failure_analysis")
            or retained_failure_analysis
            or {}
        )
        raw_retained_failure_analyses = (
            obligation_metadata.get("rejected_root_failure_analyses") or ()
        )
        retained_failure_analyses = (
            list(raw_retained_failure_analyses)
            if isinstance(raw_retained_failure_analyses, (list, tuple))
            else [raw_retained_failure_analyses]
            if raw_retained_failure_analyses
            else []
        )
        if retained_failure_analysis and not retained_failure_analyses:
            retained_failure_analyses = [retained_failure_analysis]
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                "route_id": route.node_id,
                "obligation_id": obligation.node_id,
                "replan_id": str(getattr(replan, "node_id", "") or ""),
                "replan_status": str(getattr(replan, "status", "") or ""),
                "schedulable": False,
                "structured_obligation": not duplicate_obligation_reused,
                "formalization_duplicate_obligation_reused": (
                    duplicate_obligation_reused
                ),
                "formalization_obligation_key": formalization_obligation_key,
                "reason": str(reason or ""),
                "verdict": "unscoped_root_repair_replanned",
            }
        )
        return {
            "work_type": "formalize_missing_obligation",
            "node_id": obligation.node_id,
            "graph_node_id": obligation.node_id,
            "obligation_id": obligation.node_id,
            "route_id": route.node_id,
            "replan_id": str(getattr(replan, "node_id", "") or ""),
            "formalization_required": True,
            "materialization_required": True,
            "formalization_statement_pending": True,
            "materialization_seed": str(getattr(obligation, "statement", "") or ""),
            "formalization_obligation_key": formalization_obligation_key,
            "materialization_parent_statement": parent_target_statement,
            "formalization_bridge_contract": "auxiliary_bridge_support",
            "formalization_bridge_parent_statement": parent_target_statement,
            "parent_repair_target_statement": parent_target_statement,
            "auxiliary_bridge_parent_assembly_required": True,
            "bridge_relevance_required": True,
            "forbidden_materialization_fragments": retained_forbidden_fragments,
            "rejected_root_error_type": str(getattr(ticket, "error_type", "") or ""),
            "rejected_root_unknown_identifier": retained_unknown_identifier,
            "rejected_root_unknown_identifiers": retained_unknown_identifiers,
            "rejected_root_missing_instance": retained_missing_instance,
            "rejected_root_missing_instances": retained_missing_instances,
            "rejected_root_failure_analysis": retained_failure_analysis,
            "rejected_root_first_failure_analysis": retained_first_failure_analysis,
            "rejected_root_latest_failure_analysis": retained_latest_failure_analysis,
            "rejected_root_failure_analyses": retained_failure_analyses,
            "obligation_reason": obligation_reason,
            "source": "unscoped_root_repair_ticket",
            "repair_ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
            "failure_signature": signature,
        }

    def _repair_policy_narrowing_scope_is_root_level(
        self,
        record: Dict[str, Any],
    ) -> bool:
        work_type = str(record.get("work_type") or "").strip()
        if work_type and work_type != "root_repair":
            return False
        if str(record.get("route_id") or "").strip():
            return False
        if str(record.get("obligation_id") or "").strip():
            return False
        root_node_id = str(
            getattr(getattr(self, "proof_state", None), "root_node_id", "root")
            or "root"
        ).strip()
        target_id = str(
            record.get("target_id")
            or record.get("node_id")
            or record.get("graph_node_id")
            or ""
        ).strip()
        if target_id and target_id not in {"root", root_node_id}:
            return False
        return True

    def _repair_policy_no_candidate_allows_adaptive_fallback(self) -> bool:
        record = dict(self.repair_policy_narrowing_selected_work_record or {})
        work_type = str(record.get("work_type") or "").strip()
        if work_type != "formalize_claim":
            return False
        if not bool(record.get("formalization_required")):
            return False
        if not (
            str(record.get("route_id") or "").strip()
            or str(record.get("obligation_id") or "").strip()
        ):
            return False
        return True

    def _materialize_repair_policy_narrowing_scope(self) -> bool:
        """Convert a root-level narrowing dead end into scoped graph work."""

        if not self.repair_policy_narrowing_required:
            return False
        record = dict(self.repair_policy_narrowing_selected_work_record or {})
        if not self._repair_policy_narrowing_scope_is_root_level(record):
            return False
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        if graph is None:
            return False
        key_payload = {
            "reason": str(self.repair_policy_narrowing_reason or ""),
            "selected_work_item": record,
        }
        try:
            materialization_key = hashlib.sha256(
                json.dumps(key_payload, sort_keys=True, default=str).encode("utf-8")
            ).hexdigest()[:16]
        except Exception:
            materialization_key = hashlib.sha256(
                repr(key_payload).encode("utf-8")
            ).hexdigest()[:16]
        if materialization_key in self.repair_policy_scope_materialization_keys:
            return False
        self.repair_policy_scope_materialization_keys.add(materialization_key)

        root_statement = str(getattr(dossier, "root_statement", "") or "").strip()
        target_statement = str(record.get("target_statement") or root_statement)
        ticket = RepairTicket(
            ticket_id=str(
                record.get("ticket_id")
                or record.get("repair_ticket_id")
                or f"repair-policy-scope-{materialization_key}"
            ),
            proof=str(record.get("proof") or "repair-policy-scope-materialization"),
            lean_output=str(record.get("lean_output") or ""),
            feedback_text=str(self.repair_policy_narrowing_reason or ""),
            error_type=str(record.get("error_type") or ""),
            failure_signature=str(
                record.get("failure_signature")
                or self.repair_policy_narrowing_reason
                or materialization_key
            ),
            target_id=str(record.get("target_id") or record.get("node_id") or "root"),
            target_statement=target_statement,
            work_type="root_repair",
            source_action_id=str(record.get("mapped_action_id") or ""),
            turn_index=int(self.iteration or 0),
            metadata={
                "selected_work_item": record,
                "repair_policy_narrowing_reason": str(
                    self.repair_policy_narrowing_reason or ""
                ),
                "scope_materialization_key": materialization_key,
            },
        )
        materialized = self._record_unscoped_root_repair_replan(
            ticket,
            reason=(
                "repair_policy_narrowing_requires_scoped_obligation:"
                + str(self.repair_policy_narrowing_reason or "")
            ),
        )
        if not materialized:
            return False
        materialized["scope_materialization_key"] = materialization_key
        materialized["mapped_from_work_type"] = str(record.get("work_type") or "")
        self.repair_policy_narrowing_selected_work_record = dict(materialized)
        self._refresh_repair_policy_narrowing_scope_identity(
            ticket=ticket,
            reason=self.repair_policy_narrowing_reason,
        )
        self._increment_dossier_metric(
            "mini_session_repair_policy_scope_materializations",
            1,
        )
        self._record_event(
            {
                "phase": "session_repair_policy_narrowing",
                "iteration": self.iteration,
                "reason": self.repair_policy_narrowing_reason,
                "previous_selected_work_item": record,
                "selected_work_item": dict(materialized),
                "verdict": "scope_materialized",
            }
        )
        return True

    def _resolve_repair_ticket(self, ticket: RepairTicket, *, verdict: str) -> None:
        self._increment_dossier_metric("mini_session_repair_tickets_resolved", 1)
        self._record_event(
            {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": ticket.ticket_id,
                "target_id": ticket.target_id,
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
                "attempts_used": int(ticket.attempts_used or 0),
                "verdict": str(verdict or "resolved"),
            }
        )
        lineage_recorder = getattr(
            getattr(self, "dossier", None),
            "record_proof_lineage_event",
            None,
        )
        if callable(lineage_recorder):
            lineage_recorder(
                event_type="repair_ticket_resolved",
                envelope=ProofLineageEnvelope.from_metadata(
                    getattr(ticket, "metadata", {}) or {}
                ),
                phase="session_repair_ticket",
                verdict=str(verdict or "resolved"),
                evidence_hash=str(ticket.failure_signature or ""),
                details={
                    "ticket_id": str(ticket.ticket_id or ""),
                    "attempts_used": int(ticket.attempts_used or 0),
                },
            )
        dossier = getattr(self, "dossier", None)
        idea_recorder = getattr(dossier, "record_proof_idea_observation", None)
        try:
            ticket_lineage = ProofLineageEnvelope.from_metadata(
                getattr(ticket, "metadata", {}) or {}
            )
        except (TypeError, ValueError):
            ticket_lineage = ProofLineageEnvelope()
        ideas = dict(getattr(dossier, "proof_ideas", {}) or {})
        idea = ideas.get(ticket_lineage.proof_idea_id)
        if callable(idea_recorder) and idea is not None:
            exact_output = str(getattr(ticket, "lean_output", "") or "").strip()
            attempted_code = str(getattr(ticket, "proof", "") or "").strip()
            evidence_hash = str(
                getattr(ticket, "failure_signature", "")
                or text_hash(exact_output or attempted_code or verdict)
            ).strip()
            idea_recorder(
                ticket_lineage.proof_idea_id,
                ProofIdeaObservation.create(
                    proof_idea_id=ticket_lineage.proof_idea_id,
                    occurrence_key=str(ticket.ticket_id or ""),
                    kind="repair",
                    summary=(
                        "repair ticket resolved: "
                        + str(verdict or "resolved")
                        + (
                            f"/{str(ticket.error_type)}"
                            if str(ticket.error_type or "").strip()
                            else ""
                        )
                    ),
                    claim_id=ticket_lineage.claim_id,
                    route_id=ticket_lineage.route_id,
                    attempt_id=str(ticket.proof_attempt_id or ""),
                    proof_candidate_id=ticket_lineage.proof_candidate_id,
                    lean_residual_id=ticket_lineage.lean_residual_id,
                    exact_lean_output=exact_output,
                    attempted_lean_code=attempted_code,
                    evidence_hash=evidence_hash,
                    result_sha256=(
                        hashlib.sha256(exact_output.encode("utf-8")).hexdigest()
                        if exact_output
                        else ""
                    ),
                    result_length=len(exact_output),
                    branch_id=(
                        idea.branch_provenance[0].branch_id
                        if idea.branch_provenance
                        else ""
                    ),
                    turn_index=max(0, int(self.iteration or 0)),
                ),
                branch_source="mini_session_repair_resolution",
            )
        if self.pending_repair_ticket is ticket:
            self.pending_repair_ticket = None
            self._repair_ticket_selected_id = ""
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        ticket_record = self._selected_work_record_from_repair_ticket(
            ticket,
            action_id=str(getattr(ticket, "source_action_id", "") or ""),
        )
        _work_type, target_id = self._graph_repair_record_target_key(ticket_record)
        node = nodes.get(target_id) if target_id and isinstance(nodes, dict) else None
        metadata = getattr(node, "metadata", None)
        if isinstance(metadata, dict) and str(
            metadata.get("repair_pending_identity") or ""
        ) == str(getattr(ticket, "ticket_id", "") or ""):
            metadata.pop("repair_pending", None)
            metadata.pop("repair_pending_identity", None)
            metadata.pop("repair_pending_context", None)
            metadata.pop("repair_pending_previous_status", None)

    def _grant_repair_ticket_action_budget(
        self,
        action: Action,
        ticket: RepairTicket,
    ) -> None:
        if not bool(self.conversation_budget_topups_enabled):
            return
        budget = self.budgets.get(action.id)
        needed = 0
        if budget is not None and budget.max_invocations >= 0:
            needed = int(budget.invocations or 0) + 1
            if int(budget.max_invocations or 0) < needed:
                budget.max_invocations = needed
        prompt_turn_budget_granted = self._sync_conversation_prompt_budget(
            action.id,
            min_turn_budget=needed,
        )
        if prompt_turn_budget_granted > 0:
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "action_id": action.id,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                    "verdict": "prompt_turn_budget_granted",
                }
            )
        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + 2,
        )

    @staticmethod
    def _no_progress_action_family(action: Any) -> str:
        return str(
            getattr(action, "FRONTIER_ACTION_FAMILY", "")
            or getattr(action, "id", "")
            or ""
        ).strip()

    def _eligible_no_progress_action_families(self) -> Set[str]:
        """Return currently funded/applicable mathematical action families."""

        families: Set[str] = set()
        for action in tuple(self.actions or ()):
            action_id = str(getattr(action, "id", "") or "").strip()
            if not action_id:
                continue
            budget = self.budgets.get(action_id)
            if budget is not None and budget.exhausted():
                continue
            if self._model_call_deferred_static_action_effective(action_id):
                continue
            if not self._safe_is_applicable(
                action,
                context="identical_no_progress_fixed_point_probe",
            ):
                continue
            family = self._no_progress_action_family(action)
            if family:
                families.add(family)
        return families

    @staticmethod
    def _bounded_semantic_signature(signature: str) -> str:
        clean = str(signature or "").strip()
        if len(clean) <= 64:
            return clean
        return hashlib.sha256(clean.encode("utf-8", errors="replace")).hexdigest()

    def _prune_no_progress_semantic_signature_ledger(self) -> None:
        limit = min(
            _MAX_DURABLE_SEMANTIC_LEDGER_IDENTITIES,
            max(1, int(self.max_no_progress_semantic_signatures or 0)),
        )
        counts = self.no_progress_semantic_signature_counts
        order = [
            self._bounded_semantic_signature(item)
            for item in list(self.no_progress_semantic_signature_order or ())
            if self._bounded_semantic_signature(item) in counts
        ]
        order = list(dict.fromkeys(order))
        for signature in counts:
            if signature not in order:
                order.append(signature)
        while len(order) > limit:
            evicted = order.pop(0)
            counts.pop(evicted, None)
            self.no_progress_semantic_signature_action_families.pop(
                evicted,
                None,
            )
        live_signatures = set(order)
        self.no_progress_semantic_signature_action_families = {
            signature: sorted(
                {
                    str(family or "").strip()
                    for family in list(families or ())
                    if str(family or "").strip()
                }
            )
            for signature, families in (
                self.no_progress_semantic_signature_action_families.items()
            )
            if signature in live_signatures
        }
        self.no_progress_semantic_signature_order = order

    def record_no_progress_semantic_signature(self, signature: str) -> int:
        """Record one paid visit to a durable state, including A/B cycles."""

        bounded = self._bounded_semantic_signature(signature)
        if not bounded:
            return 0
        counts = self.no_progress_semantic_signature_counts
        cardinality = min(
            _MAX_DURABLE_SEMANTIC_LEDGER_IDENTITIES,
            max(1, int(self.max_no_progress_semantic_signatures or 0)),
        )
        if bounded not in counts:
            self._prune_no_progress_semantic_signature_ledger()
            while len(counts) >= cardinality:
                if self.no_progress_semantic_signature_order:
                    evicted = self.no_progress_semantic_signature_order.pop(0)
                else:
                    evicted = next(iter(counts))
                counts.pop(evicted, None)
                self.no_progress_semantic_signature_action_families.pop(
                    evicted,
                    None,
                )
            self.no_progress_semantic_signature_order.append(bounded)
        else:
            # LRU order keeps genuinely recurring cycle states resident while
            # one-off exploratory states are the first bounded entries pruned.
            self.no_progress_semantic_signature_order = [
                item
                for item in self.no_progress_semantic_signature_order
                if item != bounded
            ]
            self.no_progress_semantic_signature_order.append(bounded)
        count = max(0, int(counts.get(bounded, 0) or 0)) + 1
        counts[bounded] = count
        self.identical_no_progress_search_signature = bounded
        self.identical_no_progress_actions = count
        return count

    def _semantic_signature_action_families(self, signature: str) -> Set[str]:
        bounded = self._bounded_semantic_signature(signature)
        return {
            str(family or "").strip()
            for family in list(
                self.no_progress_semantic_signature_action_families.get(
                    bounded,
                    (),
                )
                or ()
            )
            if str(family or "").strip()
        }

    def _record_semantic_signature_action_family(
        self,
        signature: str,
        family: str,
    ) -> None:
        bounded = self._bounded_semantic_signature(signature)
        clean_family = str(family or "").strip()
        if not bounded or not clean_family:
            return
        families = self._semantic_signature_action_families(bounded)
        families.add(clean_family)
        self.no_progress_semantic_signature_action_families[bounded] = sorted(families)

    def no_progress_semantic_signature_exhausted(self, signature: str) -> bool:
        bounded = self._bounded_semantic_signature(signature)
        limit = max(
            0,
            int(self.max_no_progress_semantic_signature_recurrences or 0),
        )
        return bool(
            bounded
            and limit > 0
            and int(self.no_progress_semantic_signature_counts.get(bounded, 0) or 0)
            >= limit
        )

    def _applicable_session_action_has_advertised_budget(self) -> bool:
        """Protect configured provider/math turns from the fixed-point cap."""

        for action in tuple(self.actions or ()):
            action_id = str(getattr(action, "id", "") or "").strip()
            budget = self.budgets.get(action_id)
            if not action_id or budget is None:
                continue
            finite_invocations_remaining = bool(
                budget.max_invocations >= 0
                and budget.invocations < budget.max_invocations
            )
            finite_seconds_remaining = bool(
                budget.max_total_seconds > 0.0
                and budget.total_seconds < budget.max_total_seconds
            )
            if (
                budget.scope != "session"
                or budget.exhausted()
                or self._model_call_deferred_static_action_effective(action_id)
                or not (finite_invocations_remaining or finite_seconds_remaining)
            ):
                continue
            if self._safe_is_applicable(
                action,
                context="identical_no_progress_advertised_budget_probe",
            ):
                return True
        return False

    def _identical_no_progress_evidence_is_current(self) -> bool:
        """Bind fixed-point evidence to the live durable search state."""

        stored = self._bounded_semantic_signature(
            self.identical_no_progress_search_signature
        )
        if not stored:
            return True
        current = self._bounded_semantic_signature(
            self._durable_search_progress_signature()
        )
        if current == stored:
            return True
        self.identical_no_progress_search_signature = current
        self.identical_no_progress_actions = max(
            0,
            int(self.no_progress_semantic_signature_counts.get(current, 0) or 0),
        )
        self.identical_no_progress_action_families_seen = (
            self._semantic_signature_action_families(current)
        )
        self._record_event(
            {
                "phase": "session_identical_no_progress_fixed_point",
                "iteration": int(self.iteration or 0),
                "stale_search_signature": stored,
                "search_signature": current,
                "verdict": "stale_fixed_point_evidence_invalidated",
            }
        )
        return False

    def _identical_no_progress_fixed_point_exhausted(self) -> bool:
        """Terminate only after a complete unchanged-state action-family pass."""

        if not self._identical_no_progress_evidence_is_current():
            return False

        limit = max(0, int(self.max_identical_no_progress_actions or 0))
        recurrence_exhausted = self.no_progress_semantic_signature_exhausted(
            self.identical_no_progress_search_signature
        )
        legacy_exhausted = bool(
            not self.no_progress_semantic_signature_counts
            and int(self.identical_no_progress_actions or 0) >= limit
        )
        if (
            limit <= 0
            or not (recurrence_exhausted or legacy_exhausted)
            or int(self.stagnation_counter or 0) < max(0, int(self.max_stagnation or 0))
        ):
            return False
        if self._applicable_session_action_has_advertised_budget():
            return False
        if self._has_funded_retryable_model_call_defer():
            return False
        eligible = self._eligible_no_progress_action_families()
        seen = (
            self._semantic_signature_action_families(
                self.identical_no_progress_search_signature
            )
            if self.no_progress_semantic_signature_counts
            else set(self.identical_no_progress_action_families_seen or ())
        )
        if eligible - seen:
            return False
        self.pending_fallback_action_id = ""
        self.terminal_failure_reason = "semantic_search_fixed_point_exhausted"
        self.terminal_failure_kind = "search_fixed_point"
        self._record_event(
            {
                "phase": "session_identical_no_progress_fixed_point",
                "iteration": int(self.iteration or 0),
                "identical_no_progress_actions": int(
                    self.identical_no_progress_actions or 0
                ),
                "max_identical_no_progress_actions": limit,
                "search_signature": str(
                    self.identical_no_progress_search_signature or ""
                ),
                "eligible_action_families": sorted(eligible),
                "action_families_seen": sorted(seen),
                "terminal_failure_reason": self.terminal_failure_reason,
                "terminal_failure_kind": self.terminal_failure_kind,
                "restartable_from_checkpoint": False,
                "verdict": "terminal_semantic_search_fixed_point",
            }
        )
        return True

    def should_continue(self) -> bool:
        self._cleanup_settled_quarantined_lean_generations()
        if self._run_governor_exhausted():
            return False
        if self._maybe_recycle_persistent_falsification_backend_timeout():
            return True
        lean_health = self._shared_lean_capability_health()
        quarantine_due = bool(lean_health.get("quarantine_due"))
        recycle_blocked_lean_tool = bool(
            not quarantine_due
            and lean_health.get("late_tail")
            and self._has_waiting_lean_tool_retry_requiring_recycle()
        )
        if quarantine_due or recycle_blocked_lean_tool:
            # A cancellation-resistant tail already received its watchdog.
            # Reusing that adapter is unsafe. Recycle immediately when a
            # parked Lean tool is waiting on it; otherwise wait the
            # quarantine grace in case the tail still settles.
            recycle_health = dict(lean_health)
            recycle_health["recycle_reason"] = (
                "lean_tool_retry_blocked_by_late_tail"
                if recycle_blocked_lean_tool
                else "quarantine_due"
            )
            if self._recycle_quarantined_lean_capability(recycle_health):
                # Exact frontier/tool/verifier frames remain untouched. The
                # next scheduler pass retries them against the fresh runner;
                # no action, iteration, provider, or mathematical budget was
                # consumed by generation recycling.
                if recycle_blocked_lean_tool:
                    self._record_lean_tool_retry_recycle()
                return True
            if recycle_blocked_lean_tool and not quarantine_due:
                # Compatibility adapters may expose the shared lock without
                # supporting in-process LeanRunner generation replacement.
                # Keep the paid replay parked and let the one-second
                # scheduler wake observe lock settlement. Do not hot-loop
                # dispatch-generation rotation before quarantine is due.
                if self.terminal_failure_reason:
                    return False
                return True
            if self._dispatch_generation_recycle_required:
                # The in-process Lean recycle allowance is a containment
                # epoch, not mathematical terminal authority. ``run`` will
                # restore the scheduler cutpoint and open a fresh dispatch
                # generation before selecting more work.
                return True
            if self.terminal_failure_reason:
                return False
            self._request_dispatch_generation_recycle(
                "lean_capability_quarantined_nonsettling_tail"
            )
            self._record_event(
                {
                    "phase": "session_lean_capability_quarantine",
                    "iteration": int(self.iteration or 0),
                    "operation_label": str(lean_health.get("operation_label") or ""),
                    "late_tail_age_s": round(
                        float(lean_health.get("age_s", 0.0) or 0.0),
                        3,
                    ),
                    "retryable_infrastructure": True,
                    "worker_restart_required": False,
                    "verdict": "lean_capability_generation_rotation_requested",
                }
            )
            return True
        controller = getattr(self, "cost_controller", None)
        if controller is not None and callable(getattr(controller, "exhausted", None)):
            try:
                exhausted = bool(controller.exhausted())
            except Exception:
                exhausted = False
            if exhausted:
                reason = str(
                    getattr(controller, "terminal_reason", "")
                    or "llm_cost_budget_exhausted"
                )
                self.terminal_failure_reason = reason
                self.terminal_failure_kind = "cost_budget"
                self.pending_fallback_action_id = ""
                if not self.cost_budget_terminal_recorded:
                    self.cost_budget_terminal_recorded = True
                    summary = (
                        controller.summary()
                        if callable(getattr(controller, "summary", None))
                        else {}
                    )
                    if not isinstance(summary, dict):
                        summary = {}
                    self._record_event(
                        {
                            "phase": "session_cost_budget",
                            "iteration": self.iteration,
                            "verdict": (
                                "terminal_cost_budget_unknown_pricing"
                                if reason == "llm_cost_budget_unknown_pricing"
                                else "terminal_cost_budget_exhausted"
                            ),
                            "terminal_failure_reason": reason,
                            **summary,
                        }
                    )
                return False
        if str(self.terminal_failure_reason or "").strip():
            self.pending_fallback_action_id = ""
            return False
        if self.root_finalized and self._durable_final_proof():
            self.pending_fallback_action_id = ""
            return False
        if self._identical_no_progress_fixed_point_exhausted():
            return False
        if self._active_repair_ticket() is not None:
            self.max_iterations = max(
                int(self.max_iterations or 0),
                int(self.iteration or 0) + 1,
            )
            return True
        if self.proof_state is not None and self._proof_state_root_solved():
            # A proved proof-state root is not, by itself, a completed session.
            # Root closure must pass the canonical finalization gate; otherwise
            # an internal helper/assembly path can mutate root state before the
            # route contract has been checked.
            if self.root_finalized and self._durable_final_proof():
                self.pending_fallback_action_id = ""
                return False
            reconciler = getattr(self.proof_state, "reconcile_with_dossier", None)
            if callable(reconciler):
                try:
                    reconciler(self.dossier)
                except Exception:
                    pass
                if not self._proof_state_root_solved():
                    return self.iteration < self.max_iterations
            if self._grant_ready_root_route_drain_headroom(
                reason="root_solved_without_finalization",
            ):
                return True
            if self._grant_cost_governed_continuation_budget(
                reason="root_solved_without_finalization",
                require_unresolved_work=False,
            ):
                return True
            if self._has_funded_persistent_infrastructure_retry():
                # A one-shot ready-route drain may already have funded this
                # exact action before it discovered a transient provider or
                # verifier outage.  Root closure is still unfinalized, so the
                # durable wake receipt remains authoritative even though the
                # route-drain grant itself cannot be issued twice.
                self.max_iterations = max(
                    int(self.max_iterations or 0),
                    int(self.iteration or 0) + 1,
                )
                return True
            return False
        if self.iteration >= self.max_iterations:
            if self._grant_ready_root_route_drain_headroom(
                reason="max_iterations_reached",
            ):
                return True
            if self._grant_cost_governed_continuation_budget(
                reason="max_iterations_reached",
            ):
                return True
            return False
        # Persistent Lean infrastructure failure is a scheduler condition,
        # not a proof verdict. ConversationTurnAction installs a durable timed
        # defer for the affected action at the cap. Clear only this streak so
        # healthy deterministic/alternate actions can continue. With no
        # explicitly enabled cost-governed continuation, no action, iteration,
        # provider, or cost budget is manufactured here.
        if self.consecutive_lean_infra_errors >= self.max_consecutive_lean_infra_errors:
            old_errors = int(self.consecutive_lean_infra_errors or 0)
            cost_governed_grant = self._grant_cost_governed_continuation_budget(
                reason="lean_infra_error_cap",
            )
            self.consecutive_lean_infra_errors = 0
            self._record_event(
                {
                    "phase": (
                        "session_cost_governed_continuation"
                        if cost_governed_grant
                        else "session_infrastructure_retry"
                    ),
                    "iteration": self.iteration,
                    "previous_consecutive_lean_infra_errors": old_errors,
                    "max_consecutive_lean_infra_errors": int(
                        self.max_consecutive_lean_infra_errors or 0
                    ),
                    "verdict": "lean_infra_error_cap_deferred",
                }
            )
            return True
        if self.repair_policy_narrowing_required:
            return True
        if self.last_giveup_cluster and not bool(
            getattr(getattr(self, "conv", None), "allow_helper_decomposition", True)
        ):
            if int(self.local_repair_quota_remaining or 0) > 0:
                self._record_event(
                    {
                        "phase": "session_direct_proof_giveup_terminal",
                        "iteration": self.iteration,
                        "giveup_cluster": self.last_giveup_cluster,
                        "giveup_match": self.last_giveup_match,
                        "local_repair_quota_remaining": int(
                            self.local_repair_quota_remaining or 0
                        ),
                        "verdict": "deferred_by_local_repair_quota",
                    }
                )
                return True
            self._record_event(
                {
                    "phase": "session_direct_proof_giveup_terminal",
                    "iteration": self.iteration,
                    "giveup_cluster": self.last_giveup_cluster,
                    "giveup_match": self.last_giveup_match,
                    "verdict": "terminal_direct_proof_giveup",
                }
            )
            return False
        if self.actions and all(self.budgets[a.id].exhausted() for a in self.actions):
            if self._has_unresolved_search_work():
                if self._grant_ready_root_route_drain_headroom(
                    reason="all_action_budgets_exhausted",
                ):
                    return True
                if self._cost_budget_continuation_enabled():
                    return self._grant_cost_governed_continuation_budget(
                        reason="all_action_budgets_exhausted",
                    )
                return True
            return False
        # The prior code
        # unconditionally terminated when ``stagnation_counter >=
        # max_stagnation`` because ``fallback_actions_attempted`` was
        # never written. That killed real runs at iter=3, BEFORE
        # the LLM ever ran (deterministic prepass actions take 3
        # iterations without adding proof_state nodes; signature stays
        # constant; stagnation hits cap; loop dies).
        #
        # New behavior: stagnation cap is INFORMATIVE, not terminal.
        # max_iterations and all-budgets-exhausted remain the hard
        # terminators. When fallback actions ARE registered and the
        # cap is hit, the next ``select_next_action`` should prefer
        # them (caller wires this); ``fallback_actions_attempted``
        # flips once any of them runs. When no fallbacks are
        # registered, the loop simply continues — letting other
        # actions (e.g. ``conversation_turn_prove``) get their
        # budgeted shots.
        return True

    def _accrue_run_governor_elapsed(self) -> float:
        """Accumulate active session time without persisting process clocks."""

        now = time.monotonic()
        previous = float(self._run_governor_last_tick_monotonic or 0.0)
        self._run_governor_last_tick_monotonic = now
        if previous > 0.0:
            delta = max(0.0, now - previous)
            self.run_governor_elapsed_s = max(
                0.0,
                float(self.run_governor_elapsed_s or 0.0) + delta,
            )
        return float(self.run_governor_elapsed_s or 0.0)

    def _run_governor_exhausted(self) -> bool:
        """Apply wall-clock and strong-progress budgets."""

        elapsed = self._accrue_run_governor_elapsed()
        existing_reason = str(self.terminal_failure_reason or "").strip()
        governor_reasons = {
            "mini_run_wall_clock_budget_exhausted",
            "mini_no_strong_progress_budget_exhausted",
        }
        # Once the controller has crossed and published its deadline, no
        # cancellation-cleanup mutation may turn that terminal decision back
        # into a solved run.  A proof finalized before the deadline still wins
        # because no governor reason exists yet.
        if existing_reason in governor_reasons:
            self._publish_run_governor_terminal_authority()
            return True
        if self.root_finalized and self._durable_final_proof():
            return False
        if existing_reason and existing_reason not in {
            "mini_run_wall_clock_budget_exhausted",
            "mini_no_strong_progress_budget_exhausted",
        }:
            return False
        wall_budget = max(0.0, float(self.run_wall_clock_budget_s or 0.0))
        progress_budget = max(
            0.0,
            float(self.no_strong_progress_budget_s or 0.0),
        )
        since_progress = max(
            0.0,
            elapsed - float(self.run_governor_last_strong_progress_elapsed_s or 0.0),
        )
        reason = ""
        kind = ""
        if wall_budget > 0.0 and elapsed >= wall_budget:
            reason = "mini_run_wall_clock_budget_exhausted"
            kind = "wall_clock_budget"
        elif progress_budget > 0.0 and since_progress >= progress_budget:
            reason = "mini_no_strong_progress_budget_exhausted"
            kind = "progress_rate_budget"
        if not reason:
            return False
        self.terminal_failure_reason = reason
        self.terminal_failure_kind = kind
        self.pending_fallback_action_id = ""
        self._publish_run_governor_terminal_authority()
        if not self.run_governor_terminal_recorded:
            self.run_governor_terminal_recorded = True
            self._record_event(
                {
                    "phase": "session_run_governor",
                    "iteration": int(self.iteration or 0),
                    "elapsed_s": elapsed,
                    "wall_clock_budget_s": wall_budget,
                    "seconds_since_strong_progress": since_progress,
                    "no_strong_progress_budget_s": progress_budget,
                    "actions_since_strong_progress": int(
                        self.run_governor_actions_since_strong_progress or 0
                    ),
                    "terminal_failure_reason": reason,
                    "terminal_failure_kind": kind,
                    "verdict": "terminal_run_governor_exhausted",
                }
            )
        return True

    def _publish_run_governor_terminal_authority(self) -> None:
        """Publish one governor terminal verdict on every caller-facing surface."""

        reason = str(self.terminal_failure_reason or "").strip()
        if reason not in {
            "mini_run_wall_clock_budget_exhausted",
            "mini_no_strong_progress_budget_exhausted",
        }:
            return
        self.last_failure_reason = reason
        dossier = getattr(self, "dossier", None)
        if dossier is not None:
            setattr(dossier, "session_failure_reason", reason)
            if self.terminal_failure_kind:
                setattr(
                    dossier,
                    "session_failure_kind",
                    str(self.terminal_failure_kind or ""),
                )
        conv = getattr(self, "conv", None)
        if conv is not None:
            setattr(conv, "_last_llm_failure_reason", reason)
            if self.terminal_failure_kind:
                setattr(
                    conv,
                    "_last_llm_failure_kind",
                    str(self.terminal_failure_kind or ""),
                )

    def _run_governor_remaining_s(self) -> Optional[float]:
        """Return the earliest active run-governor deadline, if enabled."""

        elapsed = self._accrue_run_governor_elapsed()
        remaining: List[float] = []
        wall_budget = max(0.0, float(self.run_wall_clock_budget_s or 0.0))
        if wall_budget > 0.0:
            remaining.append(max(0.0, wall_budget - elapsed))
        progress_budget = max(
            0.0,
            float(self.no_strong_progress_budget_s or 0.0),
        )
        if progress_budget > 0.0:
            since_progress = max(
                0.0,
                elapsed
                - float(self.run_governor_last_strong_progress_elapsed_s or 0.0),
            )
            remaining.append(max(0.0, progress_budget - since_progress))
        return min(remaining) if remaining else None

    def _reap_isolated_dispatch_tails(self) -> Set[asyncio.Future[Any]]:
        """Drop finished or non-blocking tails from the dispatch set."""

        loop = asyncio.get_running_loop()
        live_tails: Set[asyncio.Future[Any]] = set()
        for tail in tuple(self._pending_isolated_dispatch_tails):
            if tail.done():
                try:
                    tail.exception()
                except BaseException:
                    pass
                continue
            if not _isolated_dispatch_tail_blocks_scheduler(tail):
                continue
            try:
                tail_loop = tail.get_loop()
            except (AttributeError, RuntimeError):
                tail_loop = None
            if tail_loop is loop:
                live_tails.add(tail)
        self._pending_isolated_dispatch_tails = live_tails
        return live_tails

    def _park_isolated_dispatch_tails(
        self,
        tasks: Iterable[asyncio.Future[Any]],
    ) -> None:
        """Remember revoked tails without giving them scheduler control."""

        for task in tasks:
            if not _isolated_dispatch_tail_blocks_scheduler(task):
                continue
            self._pending_isolated_dispatch_tails.add(task)

    def _release_isolated_dispatch_tail_barrier(self, *, reason: str) -> None:
        """Drop isolated tails from the scheduler without waiting on them."""

        pending = tuple(self._pending_isolated_dispatch_tails)
        self._pending_isolated_dispatch_tails = set()
        for task in pending:
            _observe_and_detach_operation_tail(task)
        # Recycle already restored authority. Do not keep a snapshot that a
        # later HTTP/anyio close can apply hours after independent work ran.
        self._dispatch_generation_late_rollback_snapshot = {}
        self._record_event(
            {
                "phase": "session_dispatch_quiescence_barrier",
                "iteration": int(self.iteration or 0),
                "detached_tail_count": len(pending),
                "reason": reason,
                "verdict": "isolated_tail_quiescence_detached_continue",
            }
        )

    async def _drain_abandoned_actions_before_terminal(
        self,
        *,
        scope_ids: Sequence[str],
    ) -> None:
        """Observe remaining deadline tails once, then publish terminal state.

        Strict deadlines detach cancellation-resistant coroutines to keep the
        controller responsive. Recycle already restored the pre-dispatch
        checkpoint, so this barrier must not replay that snapshot after
        independent work has run. One bounded drain is enough; never-settling
        HTTP/Lean tails cannot hold the worker in shutdown.
        """

        owned_scope_ids = tuple(
            dict.fromkeys(
                str(item or "").strip() for item in scope_ids if str(item or "").strip()
            )
        )
        if not owned_scope_ids:
            self._dispatch_generation_late_rollback_snapshot = {}
            for task in tuple(self._pending_isolated_dispatch_tails):
                _observe_and_detach_operation_tail(task)
            self._pending_isolated_dispatch_tails = set()
            return
        aggregate = {"drained": 0, "still_pending": 0}
        for scope_id in owned_scope_ids:
            report = await drain_abandoned_deadline_tasks(
                timeout_s=_OPERATION_CHILD_SETTLEMENT_TIMEOUT_S,
                scope_id=scope_id,
            )
            aggregate["drained"] += int(report.get("drained") or 0)
            aggregate["still_pending"] += int(report.get("still_pending") or 0)
        still_pending = aggregate["still_pending"]
        for task in tuple(self._pending_isolated_dispatch_tails):
            _observe_and_detach_operation_tail(task)
        self._pending_isolated_dispatch_tails = set()
        # Recycle already restored the pre-dispatch checkpoint. A later
        # HTTP close must not replay that snapshot over independent work.
        self._dispatch_generation_late_rollback_snapshot = {}
        if still_pending > 0:
            self._record_event(
                {
                    "phase": "session_terminal_cancellation_barrier",
                    "iteration": int(self.iteration or 0),
                    "drained": aggregate["drained"],
                    "still_pending": still_pending,
                    "verdict": "terminal_quiescence_detached_continue",
                }
            )

    def _prepare_live_dispatch_stage(
        self,
        snapshot: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Bind an action directly to the live session."""

        action_attribute_states: List[
            Tuple[Any, Dict[str, Any], FrozenSet[str]]
        ] = []
        for action in tuple(self.actions):
            raw_state = getattr(action, "__dict__", None)
            if not isinstance(raw_state, dict):
                continue
            rollback_field_names = frozenset(
                str(name or "").strip()
                for name in (
                    getattr(
                        action,
                        "FAILED_DISPATCH_ROLLBACK_STATE_FIELDS",
                        (),
                    )
                    or ()
                )
                if str(name or "").strip()
            )
            saved_state = _copy_mapping_for_rollback(
                {
                    name: raw_state[name]
                    for name in rollback_field_names
                    if name in raw_state
                }
            )
            missing_fields = frozenset(rollback_field_names - raw_state.keys())
            action_attribute_states.append(
                (action, saved_state, missing_fields)
            )
        # Narrow identity image instead of a whole-__dict__ deepcopy of the
        # dossier/proof_state/conv. 887fa7f2 added the wide revert so a
        # mutation-boundary failure stayed retryable, and it is genuinely
        # load-bearing: without it a half-applied dispatch is retried against
        # its own leftovers forever. But reverting everything also destroyed
        # helpers, graph nodes and lineage the dispatch had verified before it
        # failed. Capture only what a torn dispatch must not be allowed to
        # redefine -- the identity of the theorem being proved and the provider
        # transcript -- and leave the mathematics alone.
        identity_image: Dict[str, Any] = {}
        dossier = self.dossier
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        root_node = None
        if graph is not None:
            root_node = (getattr(graph, "nodes", {}) or {}).get(
                getattr(graph, "root_node_id", "")
            )
        if dossier is not None:
            identity_image["dossier"] = (
                dossier,
                "root_statement",
                getattr(dossier, "root_statement", None),
            )
        if graph is not None:
            identity_image["graph"] = (
                graph,
                "root_statement",
                getattr(graph, "root_statement", None),
            )
        if root_node is not None:
            identity_image["graph_root_node"] = (
                root_node,
                "statement",
                getattr(root_node, "statement", None),
            )
        rollback_snapshot = dict(snapshot)
        rollback_snapshot["_live_session_attribute_keys"] = set(vars(self))
        rollback_snapshot["_live_action_attribute_states"] = action_attribute_states
        rollback_snapshot["_live_identity_image"] = identity_image

        return {
            "session": self,
            "actions": {str(action.id): action for action in tuple(self.actions)},
            "rollback_snapshot": rollback_snapshot,
        }

    def _restore_primitive_rollback_fields(
        self,
        snapshot: Mapping[str, Any],
    ) -> None:
        """Restore the two terminal-authority fields from a dispatch snapshot."""
        snapshot_state = dict(snapshot.get("session_state") or {})
        self.root_finalized = bool(snapshot_state.get("root_finalized", False))
        self.final_proof = snapshot_state.get("final_proof")

    def _degrade_impossible_rollback(
        self,
        error: BaseException,
        snapshot: Mapping[str, Any],
    ) -> None:
        """Restore terminal authority after a failed live dispatch."""

        self._restore_primitive_rollback_fields(snapshot)
        try:
            self._record_event(
                {
                    "phase": "session_action_mutation_transaction",
                    "verdict": "terminal_fields_restored_math_continues",
                    "error": str(error),
                }
            )
        except Exception:
            pass

    def _restore_failed_dispatch_authority(
        self,
        *,
        snapshot: Mapping[str, Any],
    ) -> bool:
        """Restore terminal authority after a failed live dispatch."""

        self._restore_primitive_rollback_fields(snapshot)
        original_keys = snapshot.get("_live_session_attribute_keys")
        if isinstance(original_keys, set):
            declared_fields = set(getattr(self, "__dataclass_fields__", {}))
            for key in tuple(vars(self)):
                if key not in original_keys and key not in declared_fields:
                    try:
                        delattr(self, key)
                    except (AttributeError, TypeError):
                        pass
        action_states = snapshot.get("_live_action_attribute_states")
        if isinstance(action_states, list):
            for action_state in action_states:
                if not isinstance(action_state, tuple) or len(action_state) != 3:
                    continue
                action, saved_state, saved_missing_fields = action_state
                missing_fields = frozenset(saved_missing_fields)
                raw_state = getattr(action, "__dict__", None)
                if not isinstance(raw_state, dict) or not isinstance(saved_state, dict):
                    continue
                export_durable_state = getattr(
                    action,
                    "failed_dispatch_durable_state",
                    None,
                )
                try:
                    durable_projection = (
                        export_durable_state()
                        if callable(export_durable_state)
                        else None
                    )
                except Exception:
                    durable_projection = None
                # A dispatch recycle skips ``apply()``. Runtime continuation
                # state outside the declared rollback fields remains
                # authoritative. Within a declared field, preserve only an
                # action's validated provider-free/completed projection; a
                # live child or provider quantum cannot be shared by the old
                # detached generation and its retry.
                raw_state.update(_copy_mapping_for_rollback(saved_state))
                for name in missing_fields:
                    raw_state.pop(name, None)
                merge_durable_state = getattr(
                    action,
                    "merge_failed_dispatch_durable_state",
                    None,
                )
                if durable_projection is not None and callable(merge_durable_state):
                    try:
                        merge_durable_state(durable_projection)
                    except Exception:
                        pass
        # Restore identity, not mathematics. A torn dispatch must not be able
        # to redefine the theorem being proved -- a retry then runs against its
        # own leftovers and fails identically forever -- but the helpers, graph
        # nodes and lineage it verified before failing are valid and stay.
        identity_image = snapshot.get("_live_identity_image")
        if isinstance(identity_image, dict):
            for owner, attribute, value in identity_image.values():
                try:
                    setattr(owner, attribute, value)
                except Exception:
                    continue
        # The transcript is a provider protocol artifact, not mathematics. A
        # dispatch detached mid tool-loop leaves an assistant tool_calls
        # message whose tool_call_ids have no matching tool results, and every
        # later provider call on that transcript 400s. Rewinding to a
        # pre-dispatch history image is NOT a valid repair: the image was a
        # shallow list copy while the graph-selected-work anchor message is
        # mutated in place across dispatches, so the "restored" transcript
        # could still carry the torn dispatch's edits -- and on the settlement
        # path a rewind erased completed turns whose outcome was then applied.
        # Repair the protocol and keep the work instead: synthesize results
        # for orphan tool_calls, exactly as child and subgoal transcripts
        # already do before replay.
        sanitize = getattr(self.conv, "sanitize_orphan_tool_calls", None)
        if callable(sanitize):
            try:
                sanitize()
            except Exception as exc:
                # The restore path must not raise, but a failed transcript
                # repair leaves the 400 hazard live -- say so instead of
                # failing closed silently (the 0f4246ba lesson).
                try:
                    self._record_event(
                        {
                            "phase": "session_action_mutation_transaction",
                            "verdict": "transcript_sanitize_failed_math_continues",
                            "error": str(exc),
                        }
                    )
                except Exception:
                    pass
        return False

    def _request_dispatch_generation_recycle(self, reason: str) -> None:
        """Fence this worker and publish a nonterminal resume checkpoint."""

        clean_reason = str(reason or "").strip() or (
            "mini_dispatch_mutation_boundary_violation"
        )
        self._dispatch_generation_recycle_required = True
        self._dispatch_generation_recycle_reason = clean_reason
        self._dispatch_worker_poisoned = False
        self._dispatch_worker_poison_reason = ""
        # Infrastructure has no mathematical terminal authority. Clear any
        # legacy integrity terminal written earlier in the same boundary.
        if str(self.terminal_failure_kind or "") == "infrastructure_integrity":
            self.terminal_failure_reason = ""
            self.terminal_failure_kind = ""
        if str(getattr(self, "last_failure_reason", "") or "") in {
            "mini_dispatch_primary_failure",
            "mini_dispatch_mutation_boundary_violation",
            "mini_apply_transaction_failure",
        }:
            self.last_failure_reason = ""
        self._dispatch_generation_resume_snapshot = copy.deepcopy(
            self._latest_pre_select_snapshot
        )

    def _fence_vanished_dispatch_skip_keys(
        self,
        snapshot: Mapping[str, Any],
    ) -> int:
        """Remove restored skip entries whose live node no longer exists.

        Dispatch checkpoints intentionally contain scheduler state plus only a
        compact proof-state summary.  Actions mutate the live proof state and
        proof graph directly, so a pre-dispatch skip entry may outlive its
        target node.  Keep malformed rows unchanged so the normal replay
        validator rejects them instead of turning a broken checkpoint into an
        apparently valid one.
        """

        live_node_ids: set[str] = set()
        node_authority_found = False
        proof_graph = getattr(getattr(self, "dossier", None), "proof_graph", None)
        for owner in (getattr(self, "proof_state", None), proof_graph):
            nodes = getattr(owner, "nodes", None)
            if not isinstance(nodes, Mapping):
                continue
            node_authority_found = True
            live_node_ids.update(str(node_id) for node_id in nodes)
            root_node_id = str(getattr(owner, "root_node_id", "") or "").strip()
            if root_node_id:
                live_node_ids.add(root_node_id)
        if not node_authority_found:
            return 0

        state = snapshot.get("session_state")
        if not isinstance(state, dict):
            return 0
        fenced = 0
        for state_key, valid_arities in (
            ("skipped_frontier_work_keys", frozenset({3, 5})),
            ("skipped_frontier_action_keys", frozenset({3, 6})),
        ):
            rows = state.get(state_key)
            if not isinstance(rows, list):
                continue
            retained: list[Any] = []
            for row in rows:
                if not isinstance(row, (list, tuple)) or len(row) not in valid_arities:
                    retained.append(row)
                    continue
                node_id = row[0]
                if not isinstance(node_id, str):
                    retained.append(row)
                    continue
                clean_node_id = node_id.strip()
                if clean_node_id and clean_node_id not in live_node_ids:
                    fenced += 1
                    continue
                retained.append(row)
            state[state_key] = retained
        return fenced

    def _resume_dispatch_generation(
        self,
        *,
        failed_action_id: str = "",
    ) -> None:
        """Restore the pre-dispatch scheduler cutpoint and open a new epoch.

        Runtime capability leases have already been revoked by the settlement
        barrier.  Restoring the scheduler checkpoint prevents partial action
        accounting from publishing, while deferring the offending action for
        one scheduler rotation lets independent mathematical work continue.
        """

        self._durabilize_inflight_provider_exposure()
        reason = str(self._dispatch_generation_recycle_reason or "").strip()
        snapshot = copy.deepcopy(self._dispatch_generation_resume_snapshot)
        charged_governor_elapsed = float(self.run_governor_elapsed_s or 0.0)
        charged_governor_actions = int(
            self.run_governor_actions_since_strong_progress or 0
        )
        charged_provider_calls = _nonnegative_metadata_int(
            vars(self),
            "provider_calls_completed_total",
        )
        charged_provider_dispatches = _nonnegative_metadata_int(
            vars(self),
            "provider_dispatches_started_total",
        )
        vanished_skip_keys_fenced = 0
        if snapshot:
            try:
                from .replay import apply_scheduler_snapshot

                vanished_skip_keys_fenced = self._fence_vanished_dispatch_skip_keys(
                    snapshot
                )
                apply_scheduler_snapshot(self, snapshot)
            except Exception as exc:
                try:
                    self._record_event(
                        {
                            "phase": "session_action_mutation_transaction",
                            "reason": reason,
                            "error": f"{type(exc).__name__}: {exc}",
                            "verdict": "dispatch_generation_checkpoint_restore_failed",
                        }
                    )
                except Exception:
                    pass
                raise
        self.run_governor_elapsed_s = max(
            float(self.run_governor_elapsed_s or 0.0),
            charged_governor_elapsed,
        )
        self.run_governor_actions_since_strong_progress = max(
            int(self.run_governor_actions_since_strong_progress or 0),
            charged_governor_actions,
        )
        self.provider_calls_completed_total = max(
            _nonnegative_metadata_int(
                vars(self),
                "provider_calls_completed_total",
            ),
            charged_provider_calls,
        )
        self.provider_dispatches_started_total = max(
            _nonnegative_metadata_int(
                vars(self),
                "provider_dispatches_started_total",
            ),
            charged_provider_dispatches,
        )
        self._run_governor_last_tick_monotonic = time.monotonic()
        action_id = str(failed_action_id or "").strip()
        if action_id:
            self._dispatch_generation_deferred_action_ids.add(action_id)
            failure_count = (
                int(
                    self._dispatch_generation_action_failure_counts.get(action_id, 0)
                    or 0
                )
                + 1
            )
            self._dispatch_generation_action_failure_counts[action_id] = failure_count
            backoff_s = min(30.0, 0.05 * (2 ** min(10, failure_count - 1)))
            self._dispatch_generation_action_ready_monotonic[action_id] = (
                time.monotonic() + backoff_s
            )
        self._dispatch_generation_index += 1
        self._dispatch_generation_recycle_required = False
        self._dispatch_generation_recycle_reason = ""
        self._dispatch_worker_poisoned = False
        self._dispatch_worker_poison_reason = ""
        self._inflight_action_dispatch_id = ""
        self._record_event(
            {
                "phase": "session_action_mutation_transaction",
                "reason": reason,
                "failed_action_id": action_id,
                "dispatch_generation": self._dispatch_generation_index,
                "checkpoint_restored": bool(snapshot),
                "vanished_skip_keys_fenced": vanished_skip_keys_fenced,
                "verdict": "dispatch_generation_recycled_and_resumed",
            }
        )

    def _release_ready_dispatch_generation_deferrals(self) -> List[str]:
        """Clear expired generation deferrals so the selector can probe them.

        ``select_next_action`` only drops a deferral inside ``_safe_is_applicable``.
        Route-static conversation suppression skips those lanes before the
        probe, so an already-due deferral would otherwise keep
        ``generation_rotation_wait`` on ``delay_s=0`` forever.
        """

        now = time.monotonic()
        released: List[str] = []
        for action_id in sorted(self._dispatch_generation_deferred_action_ids):
            ready_at = float(
                self._dispatch_generation_action_ready_monotonic.get(action_id, 0.0)
                or 0.0
            )
            if now < ready_at:
                continue
            self._dispatch_generation_deferred_action_ids.discard(action_id)
            self._dispatch_generation_action_ready_monotonic.pop(action_id, None)
            released.append(action_id)
            if str(action_id).startswith("conversation_turn") or (
                self._is_unscoped_root_authoring_action(action_id)
            ):
                self._dispatch_generation_release_suppressed_action_ids.add(action_id)
        return released

    def _terminalize_primary_dispatch_failure(
        self,
        *,
        action: Action,
        action_dispatch_id: str,
        error: BaseException,
        deadline_detached: bool,
    ) -> None:
        """Fence a failed live dispatch and request an isolated generation."""

        try:
            error_type = type(error).__name__
        except BaseException:
            error_type = "BaseException"
        try:
            error_message = str(error)
        except BaseException:
            error_message = "<message unavailable>"
        self._request_dispatch_generation_recycle("mini_dispatch_primary_failure")
        self._record_event(
            {
                "phase": "session_action_mutation_transaction",
                "iteration": int(self.iteration or 0),
                "action_id": str(getattr(action, "id", "") or ""),
                "action_dispatch_id": str(action_dispatch_id or ""),
                "error_type": error_type,
                "error": error_message,
                "dispatch_deadline_detached": bool(deadline_detached),
                "arbitrary_live_mutation_may_remain": True,
                "full_rollback_performed": False,
                "outcome_applied": False,
                "generation_recycle_required": True,
                "verdict": "dispatch_primary_failure_generation_recycle",
            }
        )

    async def _run_outcome_applied_hook(
        self,
        *,
        action: Action,
        outcome: MiniOutcome,
        scope_id: str,
    ) -> int:
        """Run the synchronous action hook without admitting child work.

        Production hooks retire action-local receipt/cursor state after the
        central outcome apply.  They are deliberately synchronous.  Returning
        an awaitable or spawning a task would move mutation beyond the action
        transaction and terminal barrier, so reject and reap either shape.
        """

        hook = getattr(action, "on_outcome_applied", None)
        if not callable(hook):
            return 0
        current = asyncio.current_task()
        tasks_before = set(asyncio.all_tasks())
        result: Any = None
        hook_error: Optional[BaseException] = None
        try:
            with bind_deadline_operation_scope(scope_id):
                result = hook(self, outcome)
        except BaseException as exc:
            hook_error = exc
        tasks_after = set(asyncio.all_tasks())
        spawned = {
            task
            for task in tasks_after - tasks_before
            if task is not current and not task.done()
        }
        returned_awaitable = inspect.isawaitable(result)
        if hook_error is None and not returned_awaitable and not spawned:
            return 0
        if inspect.iscoroutine(result):
            result.close()
        elif isinstance(result, asyncio.Future) and not result.done():
            result.cancel()
            spawned.add(result)
        for task in spawned:
            task.cancel()
        if spawned:
            done, pending = await asyncio.wait(
                spawned,
                timeout=_OPERATION_CHILD_SETTLEMENT_TIMEOUT_S,
            )
            for task in done:
                try:
                    task.exception()
                except BaseException:
                    pass
            revoked, detail = True, "live action scope revoked"
            if revoked:
                for task in pending:
                    _observe_and_detach_operation_tail(task)
                self._park_isolated_dispatch_tails(pending)
            self._request_dispatch_generation_recycle(
                "mini_dispatch_mutation_boundary_violation"
            )
            self._record_event(
                {
                    "phase": "session_action_mutation_transaction",
                    "action_dispatch_id": str(scope_id or ""),
                    "detached_task_count": len(spawned),
                    "late_publication_authority_revoked": bool(revoked),
                    "late_publication_revocation_detail": detail,
                    "generation_recycle_required": True,
                    "verdict": "dispatch_mutation_boundary_generation_recycle",
                }
            )
            return len(spawned)
        if hook_error is not None:
            if not isinstance(hook_error, Exception):
                # Operator cancellation and interpreter control flow retain
                # precedence over cleanup policy.
                raise hook_error
            self._record_event(
                {
                    "phase": "session_action_outcome_hook",
                    "action_dispatch_id": str(scope_id or ""),
                    "action_id": str(getattr(action, "id", "") or ""),
                    "error_type": type(hook_error).__name__,
                    "error": str(hook_error),
                    "verdict": "hook_cleanup_deferred_nonterminal",
                }
            )
            return 0
        if returned_awaitable:
            raise RuntimeError("on_outcome_applied hooks must be synchronous")
        raise RuntimeError("on_outcome_applied hooks may not spawn child tasks")

    async def _settle_dispatch_scope_before_commit(
        self,
        *,
        scope_id: str,
        snapshot: Mapping[str, Any],
        task_tracker: Optional[_OperationChildTaskTracker] = None,
        allow_preapply_root_state_change: bool = False,
        operator_cancellation: bool = False,
    ) -> int:
        """Settle outstanding operation children before accepting state.

        Completed, joined children are part of the primary operation and are
        permitted.  Children still live at the commit boundary are cancelled
        and reaped, while protected root fields are checked independently so a
        completed child cannot finalize the theorem outside outcome handling.
        """

        report = await drain_abandoned_deadline_tasks(
            timeout_s=_OPERATION_CHILD_SETTLEMENT_TIMEOUT_S,
            scope_id=scope_id,
        )
        deadline_pending = int(report.get("still_pending") or 0)
        detachments = max(
            deadline_pending,
            abandoned_deadline_scope_count(scope_id, consume=True),
        )
        raw_children: Set[asyncio.Future[Any]] = set()
        failed_unjoined_children: Set[asyncio.Future[Any]] = set()
        completed_unobserved_children: Set[asyncio.Future[Any]] = set()
        resistant_operation_tails: Set[asyncio.Future[Any]] = set()
        deadline_primary_pending = False
        owned_scheduled_callbacks: List[Dict[str, Any]] = []
        completed_scheduled_callbacks: List[Dict[str, Any]] = []
        pending_scheduled_callbacks: List[asyncio.Handle] = []
        if task_tracker is not None:
            # The outer strict deadline owns the primary action task itself.
            # ``operation_children()`` deliberately excludes that task, so a
            # cancellation-resistant primary used to disappear from the
            # mutation incident set even while the deadline registry reported
            # it as live. Retain and observe that exact tail before returning
            # a poisoned session to the caller.
            deadline_primary_pending = bool(
                deadline_pending > 0
                and task_tracker.primary_task is not None
                and not task_tracker.primary_task.done()
            )
            if deadline_primary_pending and task_tracker.primary_task is not None:
                resistant_operation_tails.add(task_tracker.primary_task)
            raw_children.update(task_tracker.boundary_live_mutation_children())
            child_deadline = (
                asyncio.get_running_loop().time()
                + _OPERATION_CHILD_SETTLEMENT_TIMEOUT_S
            )
            stable_passes = 0
            while stable_passes < 2:
                operation_children = task_tracker.operation_children()
                # A descendant created after the primary boundary is an
                # incident even when the router cancels it quickly enough that
                # it is already done by this pass.
                raw_children.update(task_tracker.boundary_live_mutation_children())
                live_children = {task for task in operation_children if not task.done()}
                new_live_children = live_children - raw_children
                raw_children.update(new_live_children)
                for task in operation_children - live_children:
                    if task.cancelled():
                        continue
                    # Before retrieval, this is asyncio's own durable marker
                    # that the exception was never joined/observed.  A
                    # completed fire-and-forget child is as detached from the
                    # action transaction as a child still live at the barrier.
                    unobserved_failure = bool(getattr(task, "_log_traceback", False))
                    try:
                        exception = _task_exception_without_observing(task)
                    except BaseException:
                        exception = None
                    if unobserved_failure and exception is not None:
                        failed_unjoined_children.add(task)
                    elif (
                        exception is None
                        and getattr(task, "_mini_operation_observed", None) is False
                    ):
                        completed_unobserved_children.add(task)
                if not new_live_children and not live_children:
                    stable_passes += 1
                    await asyncio.sleep(0)
                    continue
                stable_passes = 0
                if not live_children:
                    await asyncio.sleep(0)
                    continue
                for task in live_children:
                    task.cancel()
                remaining = child_deadline - asyncio.get_running_loop().time()
                if remaining <= 0.0:
                    pending = live_children
                    done: Set[asyncio.Future[Any]] = set()
                else:
                    done, pending = await asyncio.wait(
                        live_children,
                        timeout=remaining,
                    )
                for task in done:
                    if task.cancelled():
                        continue
                    unobserved_failure = bool(getattr(task, "_log_traceback", False))
                    try:
                        exception = _task_exception_without_observing(task)
                    except BaseException:
                        exception = None
                    if unobserved_failure and exception is not None:
                        failed_unjoined_children.add(task)
                    elif (
                        exception is None
                        and getattr(task, "_mini_operation_observed", None) is False
                    ):
                        completed_unobserved_children.add(task)
                if pending:
                    resistant_operation_tails.update(pending)
                    break
            # A child that was still live when settlement began crossed the
            # transaction boundary even if cancellation later completed it.
            # An unobserved failed child is likewise an integrity incident.
            # A successful child already complete before the boundary is part
            # of the quiescent staged image: structured runtimes such as AnyIO
            # join TaskGroup children through completion callbacks rather than
            # by calling Task.result()/__await__ on each child, so an
            # observation bit cannot distinguish joined work portably.
            detachments += len(raw_children | failed_unjoined_children)
            all_scheduled_callbacks = task_tracker.owned_scheduled_callbacks()
            pending_scheduled_callbacks = task_tracker.pending_scheduled_callbacks()
            for record in task_tracker.boundary_pending_callback_records:
                handle = record.get("handle")
                if (
                    isinstance(handle, asyncio.Handle)
                    and handle not in pending_scheduled_callbacks
                ):
                    pending_scheduled_callbacks.append(handle)
            for handle in pending_scheduled_callbacks:
                handle.cancel()
            failed_scheduled_callbacks = [
                record
                for record in all_scheduled_callbacks
                if bool(record.get("fired")) and bool(record.get("failed"))
            ]
            boundary_pending_record_ids = {
                id(record)
                for record in (
                    *task_tracker.boundary_pending_callback_records,
                    *task_tracker.boundary_late_callback_records,
                )
            }
            pending_handles = set(pending_scheduled_callbacks)
            pending_scheduled_records = [
                record
                for record in all_scheduled_callbacks
                if id(record) in boundary_pending_record_ids
                or record.get("handle") in pending_handles
            ]
            owned_scheduled_callbacks = [
                *failed_scheduled_callbacks,
                *pending_scheduled_records,
            ]
            completed_scheduled_callbacks = [
                record
                for record in all_scheduled_callbacks
                if bool(record.get("fired")) and not bool(record.get("failed"))
            ]
            detachments += len(owned_scheduled_callbacks)
        snapshot_state = dict(snapshot.get("session_state") or {})
        snapshot_root_finalized = bool(snapshot_state.get("root_finalized", False))
        snapshot_final_proof = snapshot_state.get("final_proof")
        premature_root_state_changed = bool(
            not allow_preapply_root_state_change
            and (
                bool(self.root_finalized) != snapshot_root_finalized
                or self.final_proof != snapshot_final_proof
            )
        )
        transaction_incidents = detachments + int(
            premature_root_state_changed and detachments == 0
        )
        if transaction_incidents > 0:
            self._dispatch_generation_late_rollback_snapshot = dict(snapshot)
            for task in resistant_operation_tails:
                _observe_and_detach_operation_tail(task)
            self._park_isolated_dispatch_tails(resistant_operation_tails)
            self._accrue_run_governor_elapsed()
            self._restore_failed_dispatch_authority(
                snapshot=snapshot,
            )
            mutation_boundary_violation = bool(
                not operator_cancellation
                and (
                    deadline_primary_pending
                    or raw_children
                    or failed_unjoined_children
                    or resistant_operation_tails
                    or premature_root_state_changed
                )
            )
            operator_cancelled_tail_fenced = bool(
                operator_cancellation and resistant_operation_tails
            )
            if operator_cancelled_tail_fenced:
                self._operator_cancelled_dispatch_reuse_fenced = True
                self._operator_cancelled_dispatch_reuse_reason = (
                    "operator-cancelled primary action retained live mutation "
                    "authority beyond its cancellation barrier"
                )
            if mutation_boundary_violation:
                self._request_dispatch_generation_recycle(
                    "mini_dispatch_mutation_boundary_violation"
                )
            self._record_event(
                {
                    "phase": "session_action_mutation_transaction",
                    "iteration": int(self.iteration or 0),
                    "action_dispatch_id": str(scope_id or ""),
                    "task_ownership_domain": "proof_action",
                    "detached_task_count": detachments,
                    "deadline_pending_task_count": deadline_pending,
                    "deadline_primary_task_pending": deadline_primary_pending,
                    "raw_child_task_count": len(raw_children),
                    "raw_child_task_names": [
                        str(getattr(task, "get_name", lambda: "")() or "")
                        for task in raw_children
                    ],
                    "raw_child_coroutine_qualnames": [
                        str(
                            getattr(
                                getattr(task, "get_coro", lambda: None)(),
                                "__qualname__",
                                "",
                            )
                            or ""
                        )
                        for task in raw_children
                    ],
                    "unjoined_failed_child_task_count": len(failed_unjoined_children),
                    # Retained for event-schema compatibility. Successful
                    # already-complete children are no longer classified as
                    # unjoined mutation incidents.
                    "unjoined_successful_child_task_count": 0,
                    "completed_unobserved_child_task_count": len(
                        completed_unobserved_children
                    ),
                    "pending_scheduled_callback_count": len(
                        pending_scheduled_callbacks
                    ),
                    "boundary_active_capability_operation_count": 0,
                    "owned_scheduled_callback_count": len(owned_scheduled_callbacks),
                    "completed_scheduled_callback_count": len(
                        completed_scheduled_callbacks
                    ),
                    "owned_scheduled_callback_reprs": [
                        str(record.get("callback_repr") or "")
                        for record in owned_scheduled_callbacks
                    ],
                    "premature_root_state_changed": bool(premature_root_state_changed),
                    "late_publication_revoked": bool(
                        mutation_boundary_violation or operator_cancelled_tail_fenced
                    ),
                    "verdict": (
                        "dispatch_mutation_boundary_generation_recycle"
                        if mutation_boundary_violation
                        else "operator_cancelled_dispatch_tail_fenced"
                        if operator_cancelled_tail_fenced
                        else "action_boundary_work_cancelled_before_commit"
                    ),
                    "generation_recycle_required": bool(mutation_boundary_violation),
                }
            )
        return transaction_incidents

    async def _await_startup_under_run_governor(
        self,
        awaitable: Any,
        *,
        operation_label: str,
    ) -> Any:
        """Run startup/recovery work inside the same durable wall allowance."""

        remaining = self._run_governor_remaining_s()
        snapshot = {
            "unhardened_live_dispatch": True,
            "session_state": {
                "root_finalized": bool(self.root_finalized),
                "final_proof": self.final_proof,
            },
        }
        scope_id = f"startup-{uuid.uuid4().hex}"
        task_tracker = _OperationChildTaskTracker()
        try:
            operation_task = task_tracker.create_primary_task(awaitable)
            try:
                with bind_deadline_operation_scope(
                    scope_id,
                    abort_on_detach=True,
                ):
                    result = await await_with_strict_deadline(
                        operation_task,
                        timeout_s=(
                            None if remaining is None else max(0.001, remaining)
                        ),
                        operation_label=operation_label,
                    )
            except BaseException as exc:
                detachments = await self._settle_dispatch_scope_before_commit(
                    scope_id=scope_id,
                    snapshot=snapshot,
                    task_tracker=task_tracker,
                )
                self._accrue_run_governor_elapsed()
                if detachments == 0:
                    self._restore_failed_dispatch_authority(
                        snapshot=snapshot,
                    )
                self._run_governor_exhausted()
                if isinstance(exc, DispatchScopeDetached) and detachments > 0:
                    self._record_event(
                        {
                            "phase": "session_action_mutation_transaction",
                            "operation_label": operation_label,
                            "detached_task_count": detachments,
                            "verdict": "startup_tail_revoked_math_continues",
                        }
                    )
                    return None
                raise
            detachments = await self._settle_dispatch_scope_before_commit(
                scope_id=scope_id,
                snapshot=snapshot,
                task_tracker=task_tracker,
            )
            if detachments > 0:
                self._run_governor_exhausted()
                self._record_event(
                    {
                        "phase": "session_action_mutation_transaction",
                        "operation_label": operation_label,
                        "detached_task_count": detachments,
                        "verdict": "startup_tail_revoked_math_continues",
                    }
                )
                return None
            self._accrue_run_governor_elapsed()
            if self._run_governor_exhausted():
                raise asyncio.TimeoutError(
                    f"startup operation exhausted run governor: {operation_label}"
                )
            return result
        finally:
            task_tracker.close()

    def _session_target_root_equivalent(self) -> bool:
        """Whether this session's active target is the parent/root theorem."""

        dossier = getattr(self, "dossier", None)
        root_statement = str(getattr(dossier, "root_statement", "") or "").strip()
        if not root_statement:
            return False
        active_targets = self._active_root_target_statements_for_equivalence()
        candidates = [
            getattr(getattr(self, "problem", None), "statement_type", ""),
            getattr(getattr(self, "conv", None), "goal_statement", ""),
        ]
        for candidate in candidates:
            text = str(candidate or "").strip()
            if not text:
                continue
            if self._answer_visible_solution_statement_allowed(text):
                continue
            if graph_statement_root_equivalent(
                text,
                root_statement,
                active_target_statements=active_targets,
            ):
                return True
        return False

    def _root_authoring_contract_required(self) -> bool:
        """Whether unscoped root authoring must be backed by a route contract."""

        if self.dossier is None:
            return False
        scope = str(getattr(self, "scope", "") or "problem")
        if scope in {"problem", "sample"}:
            return True
        if getattr(self.dossier, "proof_graph", None) is None:
            return False
        if scope in {"subgoal", "branch"}:
            return False
        return False

    def _root_repair_redirect_required(self) -> bool:
        """Whether same-target repair must be redirected into scoped work."""

        if self.dossier is None:
            return False
        scope = str(getattr(self, "scope", "") or "problem")
        if scope in {"problem", "sample"}:
            return True
        if getattr(self.dossier, "proof_graph", None) is None:
            return False
        if scope in {"subgoal", "branch"}:
            if self.proof_state is None:
                return False
            return self._session_target_root_equivalent()
        return False

    def _ready_root_authoring_contract_status(
        self,
        *,
        mutate: bool = True,
    ) -> Dict[str, Any]:
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        getter = getattr(graph, "ready_root_assembly_contract_status", None)
        if not callable(getter):
            return {
                "ready": False,
                "verdict": "ready_root_assembly_contract_status_api_missing",
            }
        problem = getattr(self, "problem", None)
        active_targets = self._active_root_target_statements_for_equivalence()
        active_target = active_targets[0] if len(active_targets) == 1 else ""
        target_statement = str(
            active_target
            or getattr(dossier, "root_statement", "")
            or getattr(problem, "statement_type", "")
            or ""
        ).strip()
        try:
            try:
                return dict(
                    getter(
                        target_statement=target_statement,
                        mutate=mutate,
                    )
                    or {}
                )
            except TypeError:
                # Older graph implementations cannot promise an
                # observational contract and therefore are not safe to query
                # during scheduler quotation.
                if not mutate:
                    return {
                        "ready": False,
                        "verdict": "read_only_route_contract_status_unavailable",
                    }
                return dict(getter(target_statement=target_statement) or {})
        except Exception as exc:
            return {
                "ready": False,
                "verdict": "ready_root_assembly_contract_status_exception",
                "exception_type": type(exc).__name__,
            }

    @staticmethod
    def _root_assembly_route_context_exists(
        contract_status: Dict[str, Any],
    ) -> bool:
        """Whether the graph has an explicit root-assembly route context."""

        if bool(contract_status.get("ready")):
            return True
        if str(contract_status.get("route_id") or "").strip():
            return True
        verdict = str(contract_status.get("verdict") or "").strip()
        if verdict == "missing_ready_root_assembly_contract":
            return False
        # If the status API failed or returned an unfamiliar shape, fail closed:
        # route-aware callers should not silently bypass a possibly existing
        # contract.
        return bool(verdict)

    def _unscoped_root_authoring_allowed(
        self,
        *,
        mutate: bool = True,
    ) -> Tuple[bool, Dict[str, Any]]:
        if not self._root_authoring_contract_required():
            return True, {}
        status = self._ready_root_authoring_contract_status(mutate=mutate)
        if not self._root_assembly_route_context_exists(status):
            return True, {
                "ready": False,
                "verdict": "unscoped_root_authoring_allowed_without_route_context",
                "ready_root_assembly_contract_status": dict(status),
            }
        return False, {
            "ready": bool(status.get("ready")),
            "verdict": "unscoped_root_authoring_requires_selected_route",
            "ready_root_assembly_contract_status": dict(status),
        }

    def _suppress_unscoped_root_authoring(
        self,
        action_id: str,
        *,
        context: str,
    ) -> bool:
        allowed, contract_status = self._unscoped_root_authoring_allowed()
        if allowed:
            return False
        self._increment_dossier_metric(
            "mini_session_unscoped_root_authoring_suppressed",
            1,
        )
        self._record_event(
            {
                "phase": "session_root_authoring_gate",
                "iteration": self.iteration,
                "action_id": str(action_id or ""),
                "context": str(context or ""),
                "route_contract_status": dict(contract_status),
                "verdict": "unscoped_root_authoring_suppressed",
            }
        )
        return True

    def _ready_root_route_assembly_work_items(
        self,
        *,
        mutate: bool = True,
    ) -> List[Dict[str, Any]]:
        """Synthesize selectable assemble-route work for all ready root routes.

        The proof graph is the source of truth for root-route readiness.  The
        proof-state frontier usually materializes that as ``assemble_route``
        work, but child/adaptive graph mutations can leave the graph ready
        before the frontier exposes a first-class item.  This record mirrors
        the frontier shape so the normal ``GraphRouteAssemblyAction`` path,
        liveness checks, budgets, and suppression keys still apply.
        """

        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return []
        target_statement = str(
            getattr(dossier, "root_statement", "")
            or getattr(getattr(self, "problem", None), "statement_type", "")
            or ""
        ).strip()
        status_getter = getattr(graph, "route_assembly_contract_status", None)
        if not callable(status_getter):
            return []
        items: List[Dict[str, Any]] = []
        for route in list(nodes.values()):
            if str(getattr(route, "kind", "") or "") != "strategy_route":
                continue
            route_id = str(getattr(route, "node_id", "") or "").strip()
            if not route_id:
                continue
            try:
                status = dict(
                    status_getter(
                        route_id,
                        target_statement=target_statement,
                        mutate=mutate,
                    )
                    or {}
                )
            except TypeError:
                if not mutate:
                    # A legacy graph API cannot prove that this liveness
                    # projection is observational, so fail closed.
                    continue
                try:
                    status = dict(
                        status_getter(
                            route_id,
                            target_statement=target_statement,
                        )
                        or {}
                    )
                except Exception:
                    continue
            except Exception:
                continue
            work_item = self._ready_root_route_assembly_work_item_from_status(
                status,
                target_statement=target_statement,
                mutate=mutate,
            )
            if work_item is not None:
                items.append(work_item)
        return items

    def _ready_root_route_assembly_work_item_from_status(
        self,
        status: Dict[str, Any],
        *,
        target_statement: str = "",
        mutate: bool = True,
    ) -> Optional[Dict[str, Any]]:
        if not bool(status.get("ready")):
            return None
        route_id = str(status.get("route_id") or "").strip()
        if not route_id:
            return None
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        route = nodes.get(route_id) if isinstance(nodes, dict) else None
        if route is None or str(getattr(route, "kind", "") or "") != "strategy_route":
            return None
        route_status = str(getattr(route, "status", "") or "").strip()
        route_metadata = getattr(route, "metadata", None)
        metadata = (
            route_metadata
            if mutate and isinstance(route_metadata, dict)
            else dict(route_metadata or {})
        )
        signature_hash = ""
        signature_getter = getattr(graph, "route_dependency_signature_hash", None)
        if callable(signature_getter):
            try:
                signature_hash = str(signature_getter(route_id) or "").strip()
            except Exception:
                signature_hash = ""
        missing_bridge_hash = str(
            metadata.get("route_missing_assembly_bridge_signature_hash") or ""
        ).strip()
        if missing_bridge_hash:
            if signature_hash and signature_hash == missing_bridge_hash:
                return None
            metadata.pop("route_missing_assembly_bridge_signature_hash", None)
        author_failed_hash = str(
            metadata.get("route_root_assembly_author_failed_signature_hash") or ""
        ).strip()
        if author_failed_hash:
            if signature_hash and signature_hash == author_failed_hash:
                return None
            metadata.pop("route_root_assembly_author_failed_hash", None)
            metadata.pop("route_root_assembly_author_failed_signature_hash", None)
            metadata.pop("route_root_tactic_authoring_ready_hash", None)
            metadata.pop("route_root_tactic_authoring_ready_signature_hash", None)
        failed_hash = str(
            metadata.get("route_root_tactic_failed_signature_hash") or ""
        ).strip()
        if failed_hash:
            if signature_hash and signature_hash == failed_hash:
                return None
            metadata.pop("route_root_tactic_failed_hash", None)
            metadata.pop("route_root_tactic_failed_signature_hash", None)
            metadata.pop("route_root_tactic_deferred_hash", None)
            metadata.pop("route_root_tactic_continued_hash", None)
            metadata.pop("route_root_tactic_continuation_hash", None)
            metadata.pop("route_root_tactic_suppressed_proofs", None)
            metadata.pop("route_root_tactic_suppressed_proof_records", None)
            metadata.pop("route_root_tactic_suppressed_count", None)
            metadata.pop("route_root_tactic_last_attempt_count", None)
            metadata.pop("route_root_tactic_last_candidate_count", None)
            metadata.pop("route_root_tactic_timeout_continuation_hash", None)
        if route_status == "failed" or metadata.get("assembled_route_proof_hash"):
            return None
        if metadata.get("route_retired") or metadata.get(
            "route_dependency_contradicted"
        ):
            return None
        dependency_node_ids = [
            str(node_id or "").strip()
            for node_id in list(status.get("dependency_node_ids") or [])
            if str(node_id or "").strip()
        ]
        if not dependency_node_ids:
            return None
        effective_target_statement = str(
            status.get("target_statement")
            or target_statement
            or getattr(dossier, "root_statement", "")
            or getattr(getattr(self, "problem", None), "statement_type", "")
            or ""
        ).strip()
        graph_record = {
            "node_id": route_id,
            "graph_node_id": route_id,
            "route_id": route_id,
            "work_type": "assemble_route",
            "action": "assemble_route",
            "source": "ready_root_route_drain",
            "source_phase": "mini_session_ready_root_route_drain",
            "target_statement": effective_target_statement,
            "target_hash": (
                text_hash(effective_target_statement)
                if effective_target_statement
                else ""
            ),
            "dependencies": dependency_node_ids,
            "formalization_required": False,
            "route_contract_verdict": str(status.get("verdict") or ""),
            "route_dependency_signature_hash": signature_hash,
            "unblocked_by_graph": True,
        }
        return {
            **graph_record,
            "graph_record": dict(graph_record),
            "route_assembly_contract_status": dict(status),
        }

    def _ready_root_route_assembly_work_item(self) -> Optional[Dict[str, Any]]:
        for work_item in self._ready_root_route_assembly_work_items():
            return work_item
        return None

    def _select_ready_root_route_assembly_action(self) -> Optional[Action]:
        """Select graph-route assembly when the graph is ready but frontier is not."""

        if self.repair_policy_narrowing_required:
            return None
        for work_item in self._ready_root_route_assembly_work_items():
            action = self._map_work_item_to_action(work_item)
            if action is None:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                self._increment_dossier_metric(
                    "mini_session_ready_root_route_drain_budget_blocked",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_ready_root_route_drain",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "selected_work_item": self._work_item_to_record(work_item),
                        "verdict": "ready_root_route_drain_budget_exhausted",
                    }
                )
                continue
            if not self._set_selected_work_item(work_item, action.id):
                continue
            self._activate_selected_graph_ready_work_item(work_item)
            if not self._safe_is_applicable(
                action,
                context="ready_root_route_drain",
            ):
                self._increment_dossier_metric(
                    "mini_session_ready_root_route_drain_not_applicable",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_ready_root_route_drain",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "selected_work_item": dict(self.selected_work_item_record),
                        "verdict": "ready_root_route_drain_not_applicable",
                    }
                )
                self._clear_selected_work_item()
                continue
            self._increment_dossier_metric(
                "mini_session_ready_root_route_drain_selected",
                1,
            )
            self._record_event(
                {
                    "phase": "session_ready_root_route_drain",
                    "iteration": self.iteration,
                    "action_id": action.id,
                    "selected_work_item": dict(self.selected_work_item_record),
                    "verdict": "ready_root_route_drain_selected",
                }
            )
            return action
        return None

    def _ready_root_route_drain_candidate_ids(
        self,
        work_item: Any,
        *,
        ignore_budget: bool = False,
        ignore_consumed: bool = False,
    ) -> List[str]:
        """Return route-scoped candidate actions for synthetic root-route work."""

        candidates: List[str] = []
        for candidate_id in self._frontier_candidate_ids_for_work_item(work_item):
            action_id = str(candidate_id or "").strip()
            if not action_id:
                continue
            action = self.registered_action(action_id)
            if action is None:
                continue
            action_key = self._frontier_action_key(work_item, action_id)
            if action_key in self.model_call_deferred_frontier_action_keys:
                continue
            if not ignore_consumed and action_key in self.consumed_frontier_action_keys:
                continue
            if not ignore_consumed and action_key in self.skipped_frontier_action_keys:
                continue
            if not self._frontier_candidate_available_for_work_item(
                work_item,
                action_id,
                ignore_budget=ignore_budget,
            ):
                continue
            if action_id not in candidates:
                candidates.append(action_id)
        return candidates

    def _grant_ready_root_route_drain_headroom(self, *, reason: str) -> bool:
        """Grant one bounded route-scoped tail step before loop termination."""

        selected_work_item: Optional[Any] = None
        action_id = ""
        for work_item in self._ready_root_route_assembly_work_items():
            candidate_ids = self._ready_root_route_drain_candidate_ids(
                work_item,
                ignore_budget=True,
            )
            if not candidate_ids:
                candidate_ids = self._ready_root_route_drain_candidate_ids(
                    work_item,
                    ignore_budget=True,
                    ignore_consumed=True,
                )
            if not candidate_ids:
                continue
            for candidate_id in candidate_ids:
                candidate_key = self._frontier_action_key(
                    work_item,
                    candidate_id,
                )
                if candidate_key in self.ready_root_route_drain_granted_action_keys:
                    continue
                selected_work_item = work_item
                action_id = candidate_id
                break
            if selected_work_item is not None:
                break
        if selected_work_item is None or not action_id:
            return False
        action = self.registered_action(action_id)
        if action is None:
            return False
        if action_id.startswith("conversation_turn") and not bool(
            self.conversation_budget_topups_enabled
        ):
            return False
        selected_work_key = self._frontier_work_key(selected_work_item)
        selected_action_key = self._frontier_action_key(selected_work_item, action_id)
        if selected_action_key in self.ready_root_route_drain_granted_action_keys:
            return False
        self.ready_root_route_drain_granted_action_keys.add(selected_action_key)
        released_consumed_action = (
            selected_action_key in self.consumed_frontier_action_keys
        )
        released_skipped_action = (
            selected_action_key in self.skipped_frontier_action_keys
        )
        released_consumed_work = selected_work_key in self.consumed_frontier_work_keys
        released_skipped_work = selected_work_key in self.skipped_frontier_work_keys
        self.consumed_frontier_action_keys.discard(selected_action_key)
        self.skipped_frontier_action_keys.discard(selected_action_key)
        self.consumed_frontier_work_keys.discard(selected_work_key)
        self.skipped_frontier_work_keys.discard(selected_work_key)
        budget = self.budgets.get(action_id)
        if budget is None:
            budget = ActionBudget(
                max_invocations=1,
                max_total_seconds=0.0,
                scope=self._declared_action_budget_scope(action),
            )
            self.budgets[action_id] = budget
        old_max = int(budget.max_invocations)
        old_invocations = int(budget.invocations)
        granted_invocations = 0
        if budget.max_invocations >= 0:
            needed = old_invocations + 1
            if budget.max_invocations < needed:
                budget.max_invocations = needed
                granted_invocations = max(0, int(budget.max_invocations) - old_max)
        seconds_granted = 0.0
        if (
            budget.max_total_seconds > 0
            and budget.total_seconds >= budget.max_total_seconds
        ):
            old_seconds = float(budget.max_total_seconds)
            estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
            seconds_granted = max(30.0, max(1.0, estimate))
            budget.max_total_seconds = float(budget.total_seconds) + seconds_granted
            seconds_granted = max(0.0, float(budget.max_total_seconds) - old_seconds)
        prompt_turn_budget_granted = 0
        if action_id.startswith("conversation_turn") and hasattr(
            action,
            "max_turns_for_budget",
        ):
            old_prompt_budget = int(getattr(action, "max_turns_for_budget", 0) or 0)
            new_prompt_budget = max(old_prompt_budget, old_invocations + 1)
            if new_prompt_budget > old_prompt_budget:
                setattr(action, "max_turns_for_budget", new_prompt_budget)
                prompt_turn_budget_granted = new_prompt_budget - old_prompt_budget
            conv = getattr(self, "conv", None)
            if conv is not None:
                try:
                    conv.turn_budget = max(
                        int(getattr(conv, "turn_budget", 0) or 0),
                        new_prompt_budget,
                    )
                except Exception:
                    pass
        old_max_iterations = int(self.max_iterations or 0)
        self.max_iterations = max(
            old_max_iterations,
            int(self.iteration or 0) + 2,
        )
        self.fallback_actions_attempted = False
        self.stagnation_counter = 0
        self._increment_dossier_metric(
            "mini_session_ready_root_route_drain_headroom_granted",
            1,
        )
        self._record_event(
            {
                "phase": "session_ready_root_route_drain",
                "iteration": self.iteration,
                "reason": str(reason or ""),
                "action_id": action_id,
                "selected_work_item": self._work_item_to_record(selected_work_item),
                "budget_grant": {
                    "old_max_invocations": old_max,
                    "new_max_invocations": int(budget.max_invocations),
                    "invocations": old_invocations,
                    "granted_invocations": int(granted_invocations),
                    "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                    "granted_seconds": round(seconds_granted, 4),
                },
                "released_frontier_suppressors": {
                    "consumed_action": bool(released_consumed_action),
                    "skipped_action": bool(released_skipped_action),
                    "consumed_work": bool(released_consumed_work),
                    "skipped_work": bool(released_skipped_work),
                },
                "old_max_iterations": old_max_iterations,
                "max_iterations": int(self.max_iterations or 0),
                "verdict": "ready_root_route_drain_headroom_granted",
            }
        )
        return True

    @staticmethod
    def _is_unscoped_root_authoring_action(action_id: str) -> bool:
        clean = str(action_id or "")
        return (
            clean == "tactic_close"
            or clean == "recursive_controller"
            or clean == "adaptive_recursive_fallback"
        )

    @classmethod
    def _is_root_authoring_fairness_action(cls, action_id: str) -> bool:
        clean = str(action_id or "").strip()
        return bool(
            cls._is_unscoped_root_authoring_action(clean)
            or clean
            in {
                "conversation_turn_prove",
                "conversation_turn_refine",
            }
        )

    def _root_fairness_frontier_item_is_route_bound(self, work_item: Any) -> bool:
        record = self._work_item_to_record(work_item)
        work_type = str(record.get("work_type") or "").strip()
        if work_type == "assemble_route":
            return bool(str(record.get("route_id") or "").strip())
        if work_type != "root_repair":
            return False
        return bool(
            str(record.get("route_id") or "").strip()
            or str(record.get("obligation_id") or "").strip()
        )

    def _select_route_bound_root_fairness_action(self) -> Optional[Action]:
        """Select root work through its exact graph binding before unscoped work."""

        ready_route = self._select_ready_root_route_assembly_action()
        if ready_route is not None:
            return ready_route
        for work_item in self._all_work_frontier_items(mutate=True, page_limit=40):
            if not self._root_fairness_frontier_item_is_route_bound(work_item):
                continue
            work_key = self._frontier_work_key(work_item)
            if (
                work_key in self.skipped_frontier_work_keys
                or work_key in self.consumed_frontier_work_keys
            ):
                continue
            work_type = str(
                self._work_item_field(work_item, "work_type", "") or ""
            ).strip()
            if work_type == "root_repair":
                self._root_repair_frontier_allowed = True
            action = self._map_work_item_to_action(work_item)
            if action is None:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if not self._set_selected_work_item(work_item, action.id):
                continue
            self._activate_selected_graph_ready_work_item(work_item)
            if not self._safe_is_applicable(
                action,
                context="scoped_frontier_route_bound_root_fairness",
            ):
                self._clear_selected_work_item()
                continue
            self.selected_frontier_action_key = self._frontier_action_key(
                work_item,
                action.id,
            )
            return action
        return None

    def _scoped_frontier_root_authoring_fairness_due(self) -> bool:
        """Whether stalled scoped work owes the root one dispatch quantum."""

        limit = int(self.max_scoped_frontier_quanta_before_root_authoring or 0)
        if limit <= 0:
            return False
        return bool(
            int(self.scoped_frontier_quanta_since_root_authoring or 0) >= limit
            and self._has_meaningful_non_root_frontier_work()
        )

    def _select_scoped_frontier_root_authoring_fairness_action(
        self,
    ) -> Optional[Action]:
        """Interleave one safe root quantum without retiring scoped work.

        This lane is deliberately an ordering change only.  It neither grants
        budget nor marks a frontier key consumed/skipped.  Existing repair
        narrowing and root-route contracts remain authoritative.
        """

        if not self._scoped_frontier_root_authoring_fairness_due():
            return None
        if self.repair_policy_narrowing_required:
            return None
        route_bound_action = self._select_route_bound_root_fairness_action()
        if route_bound_action is not None:
            self._increment_dossier_metric(
                "mini_session_scoped_frontier_root_fairness_dispatches",
                1,
            )
            self._record_event(
                {
                    "phase": "session_frontier_fairness",
                    "iteration": self.iteration,
                    "action_id": route_bound_action.id,
                    "scoped_quanta_since_root_authoring": int(
                        self.scoped_frontier_quanta_since_root_authoring or 0
                    ),
                    "selected_work_item": dict(self.selected_work_item_record),
                    "verdict": "route_bound_root_quantum_interleaved",
                }
            )
            return route_bound_action
        root_allowed, contract_status = self._unscoped_root_authoring_allowed()
        if not root_allowed:
            self._record_event(
                {
                    "phase": "session_frontier_fairness",
                    "iteration": self.iteration,
                    "route_contract_status": dict(contract_status),
                    "verdict": "root_authoring_quantum_blocked_by_route_contract",
                }
            )
            return None

        ordered = sorted(
            enumerate(self.actions),
            key=lambda pair: (
                pair[1].priority,
                pair[1].cost_estimate_s,
                pair[0],
            ),
        )
        for _index, action in ordered:
            if not self._is_root_authoring_fairness_action(action.id):
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            if (
                action.id in self.fallback_action_ids
                and self.stagnation_counter < self.max_stagnation
                and not self.fallback_actions_attempted
            ):
                # Fairness must not silently weaken the action's explicit
                # fallback eligibility policy.
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._local_micro_theory_should_skip_action(
                action.id,
                context="scoped_frontier_root_fairness",
            ):
                continue
            self._clear_selected_work_item()
            if not self._safe_is_applicable(
                action,
                context="scoped_frontier_root_fairness",
            ):
                continue
            self._increment_dossier_metric(
                "mini_session_scoped_frontier_root_fairness_dispatches",
                1,
            )
            self._record_event(
                {
                    "phase": "session_frontier_fairness",
                    "iteration": self.iteration,
                    "action_id": action.id,
                    "scoped_quanta_since_root_authoring": int(
                        self.scoped_frontier_quanta_since_root_authoring or 0
                    ),
                    "verdict": "root_authoring_quantum_interleaved",
                }
            )
            return action
        return None

    def _select_unseen_fixed_point_action_family(self) -> Optional[Action]:
        """Give each eligible family one shot before declaring a fixed point."""

        if not self._identical_no_progress_evidence_is_current():
            return None

        limit = max(0, int(self.max_identical_no_progress_actions or 0))
        recurrence_exhausted = self.no_progress_semantic_signature_exhausted(
            self.identical_no_progress_search_signature
        )
        legacy_exhausted = bool(
            not self.no_progress_semantic_signature_counts
            and int(self.identical_no_progress_actions or 0) >= limit
        )
        if (
            limit <= 0
            or not (recurrence_exhausted or legacy_exhausted)
            or self.repair_policy_narrowing_required
        ):
            return None
        seen = (
            self._semantic_signature_action_families(
                self.identical_no_progress_search_signature
            )
            if self.no_progress_semantic_signature_counts
            else set(self.identical_no_progress_action_families_seen or ())
        )
        ordered = sorted(
            enumerate(self.actions),
            key=lambda pair: (
                pair[1].priority,
                pair[1].cost_estimate_s,
                pair[0],
            ),
        )
        for _index, action in ordered:
            family = self._no_progress_action_family(action)
            if not family or family in seen:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            self._clear_selected_work_item()
            if not self._safe_is_applicable(
                action,
                context="identical_no_progress_family_fairness",
            ):
                continue
            self._record_event(
                {
                    "phase": "session_identical_no_progress_fixed_point",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(action.id or ""),
                    "action_family": family,
                    "identical_no_progress_actions": int(
                        self.identical_no_progress_actions or 0
                    ),
                    "verdict": "unseen_action_family_fairness_dispatch",
                }
            )
            return action
        return None

    def _repair_policy_static_action_is_broad(
        self,
        action_id: str,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> bool:
        clean = str(action_id or "").strip()
        if self._is_unscoped_root_authoring_action(clean):
            return True
        record = dict(selected_work_record or {})
        if record and not self._selected_work_action_compatible(clean, record):
            return True
        if not clean.startswith("conversation_turn"):
            return False
        work_type, target_id = self._graph_repair_record_target_key(record)
        if not work_type or work_type == "root_repair" or not target_id:
            return True
        scope = dict(self.repair_policy_narrowing_scope_identity or {})
        scope_binds_target = bool(
            str(scope.get("target_bound_to_graph") or "") == "true"
            and str(scope.get("target_node_id") or "").strip() == target_id
        )
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        graph_binds_target = isinstance(nodes, dict) and target_id in nodes
        return not bool(scope_binds_target or graph_binds_target)

    def _repair_policy_allows_child_adaptive_fallback(self, action_id: str) -> bool:
        return str(action_id or "").strip() == "adaptive_recursive_fallback" and str(
            getattr(self, "scope", "") or "problem"
        ) in {"subgoal", "branch"}

    def _repair_policy_child_adaptive_fallback_available(self) -> bool:
        if not self.repair_policy_narrowing_required or not self.fallback_action_ids:
            return False
        for action in self.actions:
            if action.id not in self.fallback_action_ids:
                continue
            if not self._repair_policy_allows_child_adaptive_fallback(action.id):
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            saved_target = self.selected_work_item
            saved_action_id = self.selected_work_item_action_id
            saved_record = dict(self.selected_work_item_record)
            try:
                if self.repair_policy_narrowing_selected_work_record:
                    restored = self._restore_repair_policy_narrowing_selected_work(
                        action.id
                    )
                    if not restored:
                        continue
                if self._safe_is_applicable(
                    action,
                    context="repair_policy_child_adaptive_fallback_precheck",
                ):
                    return True
            finally:
                self.selected_work_item = saved_target
                self.selected_work_item_action_id = saved_action_id
                self.selected_work_item_record = saved_record
        return False

    def _active_root_target_statements_for_equivalence(self) -> Tuple[str, ...]:
        dossier = getattr(self, "dossier", None)
        current_frame = getattr(
            dossier,
            "active_root_equivalence_statements_for_current_frame",
            None,
        )
        if callable(current_frame):
            try:
                return tuple(dict.fromkeys(current_frame()))
            except Exception:
                return ()
        return ()

    def _answer_visible_solution_statement_allowed(self, statement: str) -> bool:
        if "_solution" not in str(statement or ""):
            return False
        return self._effective_official_answer_visibility()

    def _effective_official_answer_visibility(self) -> bool:
        """Return the exact capability-backed LLM answer-visibility policy."""

        conv = getattr(self, "conv", None)
        dossier = getattr(self, "dossier", None)
        return _conversation_official_answer_visible(conv, dossier)

    def _has_meaningful_non_root_frontier_work(self) -> bool:
        if self.proof_state is None:
            return False
        return any(
            str(self._work_item_field(item, "work_type", "") or "").strip()
            != "root_repair"
            and self._frontier_item_has_available_candidate(item)
            for item in self._all_work_frontier_items(mutate=False)
        )

    def _shared_lean_capability_occupied(self) -> bool:
        """Whether a live owner currently fences this loop's Lean adapter."""

        lean = getattr(self, "lean", None)
        if lean is None:
            return False
        try:
            from ..mini_formal_state_search import _lean_late_tail_status

            return bool(_lean_late_tail_status(lean).get("occupied"))
        except RuntimeError:
            # Scheduler quotation outside an event loop is advisory; actual
            # async admission remains authoritative.
            return False
        except Exception:
            # An unexpected health-probe failure cannot safely authorize
            # overlapping use of a stateful Lean capability.
            _LOGGER.debug("Lean occupancy probe failed", exc_info=True)
            return True

    def _shared_lean_capability_health(self) -> Dict[str, Any]:
        lean = getattr(self, "lean", None)
        if lean is None:
            return {}
        current_generation = getattr(lean, "current_generation", None)
        if callable(current_generation):
            try:
                replacement = current_generation()
            except Exception:
                replacement = lean
            if replacement is not None and replacement is not lean:
                self.lean = replacement
                lean = replacement
        try:
            from ..mini_formal_state_search import _lean_late_tail_status

            return dict(_lean_late_tail_status(lean))
        except RuntimeError:
            return {}
        except Exception:
            _LOGGER.debug("Lean capability health probe failed", exc_info=True)
            return {
                "occupied": True,
                "late_tail": False,
                "quarantine_due": False,
                "age_s": 0.0,
                "operation_label": "",
                "health_probe_failed": True,
            }

    def _recycle_quarantined_lean_capability(
        self,
        health: Mapping[str, Any],
    ) -> bool:
        """Fence a poisoned runner generation and install a fresh one.

        Root sessions can continue their exact durable frontier immediately.
        Recursive children share a revocable facade, so the fresh generation
        is installed on the nearest owning ancestor and the child exits
        retryably; the parent then resumes/replays the preserved child frame.
        """

        from ..lean_runner import LeanRunner

        capability_identity = _dispatch_capability_identity(self.lean)
        owner: Optional["MiniSession"] = self
        while owner.parent is not None:
            parent_identity = _dispatch_capability_identity(owner.parent.lean)
            if parent_identity != capability_identity:
                break
            owner = owner.parent
        old_runner = getattr(owner, "lean", None)
        if not isinstance(old_runner, LeanRunner):
            return False
        recycle_count = int(
            getattr(owner, "lean_capability_generation_recycles", 0) or 0
        )
        oracle_max_concurrent = int(
            getattr(old_runner, "_oracle_max_concurrent", 2) or 2
        )
        try:
            fresh_runner = LeanRunner(
                old_runner.cfg,
                oracle_max_concurrent=oracle_max_concurrent,
            )
        except Exception:
            _LOGGER.exception("Failed to construct fresh LeanRunner generation")
            return False
        for attribute in ("default_max_heartbeats",):
            if hasattr(old_runner, attribute):
                try:
                    setattr(fresh_runner, attribute, getattr(old_runner, attribute))
                except Exception:
                    pass
        # Resolve every live direct subscriber before publication. Recursive
        # capability facades deliberately stay fenced and make their child
        # yield; only sessions that directly own this exact runner migrate.
        subscribers: List["MiniSession"] = []
        with _LIVE_MINI_SESSION_REFS_LOCK:
            dead_ref_ids: Set[int] = set()
            for ref in list(_LIVE_MINI_SESSION_REFS):
                candidate = ref()
                if candidate is None:
                    dead_ref_ids.add(id(ref))
                    continue
                if getattr(candidate, "lean", None) is old_runner:
                    subscribers.append(candidate)
            if dead_ref_ids:
                _LIVE_MINI_SESSION_REFS[:] = [
                    ref
                    for ref in _LIVE_MINI_SESSION_REFS
                    if id(ref) not in dead_ref_ids
                ]
        if not any(candidate is owner for candidate in subscribers):
            subscribers.append(owner)

        # Theory-library activation is the transactional prepare phase.  If
        # any consumer rejects the fresh runner, restore every library to the
        # old generation and close the unpublished fresh object.  The old
        # runner remains service-fenced only by its retained late-tail lease.
        libraries: List[Any] = []
        seen_library_ids: Set[int] = set()
        for subscriber in subscribers:
            library = getattr(subscriber, "theory_library", None)
            if library is None or id(library) in seen_library_ids:
                continue
            seen_library_ids.add(id(library))
            libraries.append(library)
        activated: List[Any] = []
        try:
            for library in libraries:
                activate = getattr(library, "activate_lean_runner", None)
                if callable(activate):
                    activated.append(library)
                    activate(fresh_runner)
        except Exception:
            _LOGGER.exception(
                "Failed to activate recycled LeanRunner in theory library"
            )
            for library in reversed(activated):
                try:
                    rollback = getattr(library, "activate_lean_runner", None)
                    if callable(rollback):
                        rollback(old_runner)
                except Exception:
                    _LOGGER.exception(
                        "Failed to roll back LeanRunner theory activation"
                    )
            try:
                fresh_runner.close()
            except Exception:
                pass
            return False

        # Commit the swap atomically on the event-loop thread. The late tail
        # retains only the quiesced old object. Future sessions normalize an
        # old captured factory reference through ``current_generation``.
        old_runner._quiesced = True  # noqa: SLF001
        generation_ref = old_runner._generation_ref  # noqa: SLF001
        fresh_runner._generation_ref = generation_ref  # noqa: SLF001
        generation_ref.current = fresh_runner
        old_runner._replacement_runner = None  # noqa: SLF001
        for subscriber in subscribers:
            subscriber.lean = fresh_runner
        owner.lean_capability_generation_recycles = recycle_count + 1
        from ..mini_formal_state_search import _abandon_quarantined_lean_tail

        shutdown_tail_detached = _abandon_quarantined_lean_tail(old_runner)
        old_generation_closed = False
        try:
            old_runner.close_generation_only()
            old_generation_closed = True
        except Exception:
            _LOGGER.exception("Failed to force-close revoked Lean generation")
        # No live runner object is retained after publication authority and
        # shutdown ownership are revoked. The old lock/task may remain as an
        # inert loop-local tombstone, but it cannot retain Lean processes,
        # pools, or scratch resources through this session.
        owner._quarantined_lean_runners = []
        owner._record_event(
            {
                "phase": "session_lean_capability_quarantine",
                "iteration": int(owner.iteration or 0),
                "operation_label": str(health.get("operation_label") or ""),
                "late_tail_age_s": round(
                    float(health.get("age_s", 0.0) or 0.0),
                    3,
                ),
                "old_runner_generation": id(old_runner),
                "fresh_runner_generation": id(fresh_runner),
                "migrated_session_count": len(subscribers),
                "oracle_max_concurrent": oracle_max_concurrent,
                "recursive_child_must_yield": bool(owner is not self),
                "shutdown_tail_detached": shutdown_tail_detached,
                "old_generation_closed": old_generation_closed,
                "reason": str(
                    health.get("recycle_reason")
                    or health.get("operation_label")
                    or "lean_capability_recycle"
                ),
                "verdict": "lean_capability_generation_recycled",
            }
        )
        if owner is self:
            self.lean = fresh_runner
            return True
        self._request_dispatch_generation_recycle(
            "lean_capability_recycled_in_parent_retry_child"
        )
        return False

    def _shared_lean_capability_owner(self) -> "MiniSession":
        """Return the nearest ancestor that owns this exact Lean generation."""

        capability_identity = _dispatch_capability_identity(self.lean)
        owner = self
        while owner.parent is not None:
            if _dispatch_capability_identity(owner.parent.lean) != capability_identity:
                break
            owner = owner.parent
        return owner

    def lean_capability_generation_identity(self) -> Any:
        """Return a stable process nonce for this Lean generation."""

        return _dispatch_capability_generation_nonce(self.lean)

    @staticmethod
    def _static_action_receipt_key(action_id: str, context_key: str) -> str:
        return f"{str(action_id or '').strip()}\0{str(context_key or '').strip()}"

    def _static_action_receipt_registry_owner(self) -> Any:
        explicit = getattr(self, "_static_action_receipt_authority", None)
        if explicit is not None:
            with _STATIC_ACTION_RECEIPT_LOCK:
                if not hasattr(explicit, "_static_action_context_receipts"):
                    explicit._static_action_context_receipts = {}
            return explicit
        return self._shared_lean_capability_owner()

    def static_action_context_exhausted(
        self,
        action_id: str,
        context_key: str,
    ) -> bool:
        """Whether an exact static lane has a shared terminal receipt."""

        owner = self._static_action_receipt_registry_owner()
        key = self._static_action_receipt_key(action_id, context_key)
        with _STATIC_ACTION_RECEIPT_LOCK:
            registry = owner._static_action_context_receipts
            receipt = dict(registry.pop(key, {}) or {})
            if receipt:
                registry[key] = receipt
            return bool(receipt.get("consumed", False))

    def claim_static_action_attempt(
        self,
        action_id: str,
        context_key: str,
        *,
        max_attempts: int,
    ) -> tuple[int, bool]:
        """Reserve one exact static dispatch before any external work."""

        owner = self._static_action_receipt_registry_owner()
        key = self._static_action_receipt_key(action_id, context_key)
        with _STATIC_ACTION_RECEIPT_LOCK:
            registry = owner._static_action_context_receipts
            receipt = dict(registry.get(key) or {})
            committed = max(
                0,
                int(
                    receipt.get(
                        "attempts_committed",
                        receipt.get("attempts_claimed", 0),
                    )
                    or 0
                ),
            )
            limit = max(1, int(max_attempts or 1))
            reserved_attempt = max(
                0,
                int(receipt.get("reservation_attempt", 0) or 0),
            )
            if (
                bool(receipt.get("consumed", False))
                or committed >= limit
                or reserved_attempt > 0
            ):
                return max(committed, reserved_attempt), False
            reserved_attempt = committed + 1
            receipt.update(
                {
                    "action_id": str(action_id or ""),
                    "context_key": str(context_key or ""),
                    "attempts_committed": committed,
                    "attempts_claimed": max(
                        max(0, int(receipt.get("attempts_claimed", 0) or 0)),
                        reserved_attempt,
                    ),
                    "attempt_limit": limit,
                    "reservation_attempt": reserved_attempt,
                    "reservation_token": uuid.uuid4().hex,
                    "consumed": False,
                }
            )
            registry.pop(key, None)
            registry[key] = receipt
            while len(registry) > 4096:
                registry.pop(next(iter(registry)))
            return reserved_attempt, True

    def mark_static_action_attempt_dispatched(
        self,
        action_id: str,
        context_key: str,
    ) -> int:
        """Commit the current reservation at the authenticated launch seam."""

        owner = self._static_action_receipt_registry_owner()
        key = self._static_action_receipt_key(action_id, context_key)
        with _STATIC_ACTION_RECEIPT_LOCK:
            registry = owner._static_action_context_receipts
            receipt = dict(registry.get(key) or {})
            committed = max(
                0,
                int(receipt.get("attempts_committed", 0) or 0),
            )
            reserved_attempt = max(
                0,
                int(receipt.get("reservation_attempt", 0) or 0),
            )
            if reserved_attempt > 0:
                committed = max(committed, reserved_attempt)
                receipt["attempts_committed"] = committed
                receipt["reservation_attempt"] = 0
                receipt["reservation_token"] = ""
            limit = max(1, int(receipt.get("attempt_limit", 1) or 1))
            receipt["consumed"] = bool(
                receipt.get("consumed", False) or committed >= limit
            )
            registry.pop(key, None)
            registry[key] = receipt
            while len(registry) > 4096:
                registry.pop(next(iter(registry)))
            return committed

    def release_static_action_attempt(
        self,
        action_id: str,
        context_key: str,
    ) -> None:
        """Release a reservation cancelled before authenticated dispatch."""

        owner = self._static_action_receipt_registry_owner()
        key = self._static_action_receipt_key(action_id, context_key)
        with _STATIC_ACTION_RECEIPT_LOCK:
            registry = owner._static_action_context_receipts
            receipt = dict(registry.get(key) or {})
            if max(0, int(receipt.get("reservation_attempt", 0) or 0)) <= 0:
                return
            receipt["reservation_attempt"] = 0
            receipt["reservation_token"] = ""
            registry.pop(key, None)
            if max(0, int(receipt.get("attempts_committed", 0) or 0)) <= 0 and not bool(
                receipt.get("consumed", False)
            ):
                return
            registry[key] = receipt
            while len(registry) > 4096:
                registry.pop(next(iter(registry)))

    def consume_static_action_context(
        self,
        action_id: str,
        context_key: str,
    ) -> None:
        """Persist a completed exact-context rejection across child sessions."""

        owner = self._static_action_receipt_registry_owner()
        key = self._static_action_receipt_key(action_id, context_key)
        with _STATIC_ACTION_RECEIPT_LOCK:
            registry = owner._static_action_context_receipts
            receipt = dict(registry.get(key) or {})
            receipt.update(
                {
                    "action_id": str(action_id or ""),
                    "context_key": str(context_key or ""),
                    "consumed": True,
                    "reservation_attempt": 0,
                    "reservation_token": "",
                }
            )
            registry.pop(key, None)
            registry[key] = receipt
            while len(registry) > 4096:
                registry.pop(next(iter(registry)))

    @staticmethod
    def _is_exact_falsification_backend_timeout_receipt(
        outcome: MiniOutcome,
    ) -> bool:
        if str(outcome.action_id or "") != "falsify_coverage":
            return False
        raw_report = (outcome.metadata or {}).get("falsification_report")
        if not isinstance(raw_report, Mapping):
            return False
        report = dict(raw_report)
        if report.get("outcome") != "transient_failure":
            return False
        exact_reason = "Lean timeout while waiting for Lean backend execution"
        matched = False
        raw_findings = report.get("findings")
        if not isinstance(raw_findings, (list, tuple)):
            return False
        for raw_finding in raw_findings:
            if not isinstance(raw_finding, Mapping):
                return False
            finding = dict(raw_finding)
            if finding.get("outcome") != "transient_failure":
                continue
            exact = bool(
                finding.get("error_kind") == "infrastructure"
                and finding.get("reason") == exact_reason
            )
            if not exact:
                return False
            matched = True
        return matched

    def _observe_applied_falsification_backend_timeout(
        self,
        outcome: MiniOutcome,
    ) -> None:
        """Record one unique, centrally applied coverage health receipt."""

        if str(outcome.action_id or "") != "falsify_coverage":
            return
        owner = self._shared_lean_capability_owner()
        generation = _dispatch_capability_identity(owner.lean)
        try:
            current_ref = weakref.ref(generation)
        except TypeError:
            # Compatibility adapters without a weak-referenceable generation
            # token cannot safely participate in owner-scoped recycling.
            owner._falsification_backend_timeout_generation_ref = None
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0
            return
        generation_ref = owner._falsification_backend_timeout_generation_ref
        observed_generation = (
            generation_ref()
            if isinstance(generation_ref, weakref.ReferenceType)
            else None
        )
        if observed_generation is not generation:
            owner._falsification_backend_timeout_generation_ref = current_ref
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0
        if self._is_exact_falsification_backend_timeout_receipt(outcome):
            owner._falsification_backend_timeout_streak += 1
            if owner._falsification_backend_timeout_streak >= 3:
                owner._falsification_backend_timeout_recycle_pending = True
        else:
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0

    def _maybe_recycle_persistent_falsification_backend_timeout(self) -> bool:
        """Fence a repeatedly timed-out generation between action dispatches."""

        owner = self._shared_lean_capability_owner()
        if not owner._falsification_backend_timeout_recycle_pending:
            return False
        generation = _dispatch_capability_identity(owner.lean)
        try:
            current_ref = weakref.ref(generation)
        except TypeError:
            owner._falsification_backend_timeout_generation_ref = None
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0
            return False
        generation_ref = owner._falsification_backend_timeout_generation_ref
        observed_generation = (
            generation_ref()
            if isinstance(generation_ref, weakref.ReferenceType)
            else None
        )
        if observed_generation is not generation:
            owner._falsification_backend_timeout_generation_ref = current_ref
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0
            return False
        now = time.monotonic()
        if now < owner._falsification_backend_timeout_recycle_retry_monotonic:
            return False
        before = generation
        recycled = self._recycle_quarantined_lean_capability(
            {
                "operation_label": "falsify_coverage",
                "recycle_reason": ("persistent_falsification_lean_backend_timeout"),
                "age_s": 0.0,
            }
        )
        after = _dispatch_capability_identity(owner.lean)
        if recycled or after is not before:
            try:
                owner._falsification_backend_timeout_generation_ref = weakref.ref(after)
            except TypeError:
                owner._falsification_backend_timeout_generation_ref = None
            owner._falsification_backend_timeout_streak = 0
            owner._falsification_backend_timeout_recycle_pending = False
            owner._falsification_backend_timeout_recycle_retry_monotonic = 0.0
            owner._falsification_backend_timeout_recycle_failures = 0
            return True
        # Compatibility/factory failures are retryable infrastructure. Other
        # mathematical actions may continue during this short operational
        # cooldown; the exact coverage frontier and cursors remain preserved.
        failures = owner._falsification_backend_timeout_recycle_failures + 1
        owner._falsification_backend_timeout_recycle_failures = failures
        retry_delays = (1.0, 4.0, 16.0, 32.0)
        owner._falsification_backend_timeout_recycle_retry_monotonic = (
            now + retry_delays[min(failures - 1, len(retry_delays) - 1)]
        )
        return bool(self._dispatch_generation_recycle_required)

    def _cleanup_settled_quarantined_lean_generations(self) -> None:
        """Reclaim retired runners only after their owned tails settle."""

        quarantined = list(getattr(self, "_quarantined_lean_runners", ()) or ())
        if not quarantined:
            return
        from ..mini_formal_state_search import _lean_late_tail_status

        pending: List[Any] = []
        for runner in quarantined:
            health = _lean_late_tail_status(runner)
            if bool(health.get("late_tail") or health.get("occupied")):
                pending.append(runner)
                continue
            close_generation = getattr(runner, "close_generation_only", None)
            if callable(close_generation):
                try:
                    close_generation()
                except Exception:
                    _LOGGER.exception(
                        "Failed to close settled quarantined Lean generation"
                    )
                    pending.append(runner)
        self._quarantined_lean_runners = pending

    def _work_item_waits_for_shared_lean(self, work_item: Any) -> bool:
        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        return bool(
            work_type
            in {
                "decl_probe",
                "tactic_swarm",
                "residual_goal_extraction",
                "helper_acceptance",
            }
            and "child_closure" in self._frontier_candidate_ids_for_work_item(work_item)
            and self._shared_lean_capability_occupied()
        )

    def _root_repair_allowed_by_global_frontier(self) -> bool:
        if self.proof_state is None:
            return False
        if self._static_action_available_before_root_repair():
            return False
        return not any(
            self._frontier_item_blocks_root_repair(item)
            for item in self._all_work_frontier_items(mutate=False)
        )

    def _frontier_item_has_available_candidate(self, work_item: Any) -> bool:
        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        if not work_type:
            return False
        if not bool(
            self.selected_work_graph_liveness_status(
                self._work_item_to_record(work_item),
                mutate=False,
            ).get("live", True)
        ):
            return False
        return any(
            self._frontier_candidate_available_for_work_item(
                work_item,
                candidate_id,
                mutate=False,
            )
            for candidate_id in self._frontier_candidate_ids_for_work_item(work_item)
        )

    def _frontier_item_blocks_root_repair(self, work_item: Any) -> bool:
        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        if work_type == "root_repair":
            return False
        return self._frontier_item_has_available_candidate(work_item)

    def _static_action_should_precede_root_repair(self, action: Action) -> bool:
        action_id = str(getattr(action, "id", "") or "")
        return action_id in {
            "premise_retrieval",
            "proof_state_retrieval",
            "recursive_controller",
            "formal_state_search",
            "tactic_close",
            "finset_reindexing",
            "cast_normalization",
        }

    def _static_action_available_before_root_repair(self) -> bool:
        for action in self.actions:
            if not self._static_action_should_precede_root_repair(action):
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._local_micro_theory_action_would_skip(action.id):
                continue
            applicability_probe = getattr(
                action,
                "frontier_is_applicable_probe",
                None,
            )
            # Static preselection is quotation, not dispatch. Actions that do
            # not explicitly implement the observational protocol cannot be
            # queried safely here.
            if not callable(applicability_probe):
                continue
            if self._safe_is_applicable(
                action,
                context="root_repair_precheck_probe",
                predicate=applicability_probe,
            ):
                return True
        return False

    def _route_replan_serviceability_status(
        self,
        record: Dict[str, Any],
    ) -> Tuple[bool, Dict[str, Any]]:
        """Return whether a route-replan record is executable proof work.

        ``route_replan`` means "repair/prove the route's materialized
        obligation", not "ask the LLM to talk about a route reason".  If the
        record only carries a route id plus a natural-language reason, the
        scheduler must leave it in obligation-mining/formalization mode rather
        than falling through to a targetless conversation turn.
        """

        merged: Dict[str, Any] = {}
        graph_record = record.get("graph_record")
        if isinstance(graph_record, dict):
            merged.update(graph_record)
        selected = record.get("selected_work_item")
        if isinstance(selected, dict):
            nested_graph_record = selected.get("graph_record")
            if isinstance(nested_graph_record, dict):
                merged.update(nested_graph_record)
            merged.update(selected)
        merged.update(dict(record or {}))

        work_type = str(merged.get("work_type") or "").strip()
        if work_type != "route_replan":
            return True, {"verdict": "not_route_replan"}

        formalization_required = bool(merged.get("formalization_required"))

        def root_equivalent(statement: str) -> bool:
            if self._answer_visible_solution_statement_allowed(statement):
                return False
            active_targets = self._active_root_target_statements_for_equivalence()
            dossier = getattr(self, "dossier", None)
            root_statement = str(getattr(dossier, "root_statement", "") or "").strip()
            return bool(
                root_statement
                and graph_statement_root_equivalent(
                    statement,
                    root_statement,
                    active_target_statements=active_targets,
                )
            )

        def statement_is_serviceable(statement: str) -> bool:
            text = str(statement or "").strip()
            if not text:
                return False
            try:
                from ensemble_prover.proof_graph import graph_statement_is_executable
                from ensemble_prover.proof_dossier import (
                    is_answer_unsafe_statement_text,
                )
            except Exception:
                return False
            if is_answer_unsafe_statement_text(
                text,
                suppress_solution_placeholders=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "suppress_solution_placeholders",
                        True,
                    )
                ),
                opaque_mode=bool(
                    getattr(getattr(self, "conv", None), "opaque_mode", True)
                ),
                allow_official_answer_visibility=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "allow_official_answer_visibility",
                        False,
                    )
                ),
                official_answer_payload_present=getattr(
                    getattr(self, "conv", None),
                    "official_answer_payload_present",
                    getattr(
                        getattr(self, "dossier", None),
                        "official_answer_payload_present",
                        None,
                    ),
                ),
            ):
                return False
            if root_equivalent(text):
                return False
            return bool(graph_statement_is_executable(text))

        target_statement = str(merged.get("target_statement") or "").strip()
        if target_statement and not formalization_required:
            if root_equivalent(target_statement):
                return False, {
                    "verdict": "route_replan_root_equivalent_requires_root_or_assemble_route",
                }
            if statement_is_serviceable(target_statement):
                return True, {
                    "verdict": "route_replan_has_executable_target_statement",
                }

        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None:
            if str(merged.get("obligation_id") or "").strip():
                return True, {"verdict": "route_replan_has_obligation_id"}
            return False, {"verdict": "route_replan_missing_graph_context"}
        if not isinstance(nodes, dict):
            if str(merged.get("obligation_id") or "").strip():
                return True, {"verdict": "route_replan_has_obligation_id"}
            return False, {"verdict": "route_replan_missing_graph_context"}

        obligation_id = str(merged.get("obligation_id") or "").strip()
        replan_id = str(
            merged.get("replan_id")
            or merged.get("graph_node_id")
            or merged.get("node_id")
            or merged.get("target_id")
            or ""
        ).strip()
        if not obligation_id and replan_id:
            replan_node = nodes.get(replan_id)
            if replan_node is not None:
                metadata = dict(getattr(replan_node, "metadata", {}) or {})
                obligation_id = str(metadata.get("obligation_id") or "").strip()
            if not obligation_id:
                incoming = getattr(graph, "incoming", None)
                if callable(incoming):
                    try:
                        for edge in incoming(replan_id, kind="obligation_replan"):
                            source = str(getattr(edge, "source", "") or "").strip()
                            if source:
                                obligation_id = source
                                break
                    except Exception:
                        obligation_id = ""

        if not obligation_id:
            return False, {
                "verdict": "route_replan_requires_materialized_obligation",
                "replan_id": replan_id,
            }

        obligation = nodes.get(obligation_id)
        if obligation is None:
            return False, {
                "verdict": "route_replan_obligation_missing",
                "obligation_id": obligation_id,
                "replan_id": replan_id,
            }
        is_tombstone = getattr(graph, "is_superseded_tombstone", None)
        if callable(is_tombstone):
            try:
                if bool(is_tombstone(obligation)):
                    return False, {
                        "verdict": "route_replan_obligation_tombstoned",
                        "obligation_id": obligation_id,
                        "replan_id": replan_id,
                    }
            except Exception:
                pass
        obligation_metadata = dict(getattr(obligation, "metadata", {}) or {})
        if obligation_metadata.get("formalization_required"):
            return False, {
                "verdict": "route_replan_obligation_needs_formalization",
                "obligation_id": obligation_id,
                "replan_id": replan_id,
            }
        obligation_statement = str(getattr(obligation, "statement", "") or "").strip()
        if root_equivalent(obligation_statement):
            return False, {
                "verdict": "route_replan_root_equivalent_requires_root_or_assemble_route",
                "obligation_id": obligation_id,
                "replan_id": replan_id,
            }
        if statement_is_serviceable(obligation_statement):
            return True, {
                "verdict": "route_replan_has_executable_obligation",
                "obligation_id": obligation_id,
                "replan_id": replan_id,
            }
        return False, {
            "verdict": "route_replan_obligation_not_executable",
            "obligation_id": obligation_id,
            "replan_id": replan_id,
        }

    def _frontier_work_suppresses_static_conversation(self, work_item: Any) -> bool:
        work_type = str(
            self._work_item_field(work_item, "work_type", work_item) or ""
        ).strip()
        if work_type in {"assemble_route", "route_replan"}:
            return True
        if work_type in {
            "formalize_claim",
            "formalize_missing_obligation",
            "mine_missing_obligation",
        }:
            record = self._work_item_to_record(work_item)
            graph_record = record.get("graph_record")
            node_id = str(
                record.get("graph_node_id")
                or record.get("node_id")
                or record.get("claim_id")
                or record.get("obligation_id")
                or ""
            ).strip()
            graph = (
                getattr(self.dossier, "proof_graph", None)
                if self.dossier is not None
                else None
            )
            node = (
                getattr(graph, "nodes", {}).get(node_id)
                if graph is not None and node_id
                else None
            )
            node_metadata = (
                dict(getattr(node, "metadata", {}) or {}) if node is not None else {}
            )
            merged = {
                **node_metadata,
                **(graph_record if isinstance(graph_record, dict) else {}),
                **record,
            }
            formalization_required = bool(
                merged.get("formalization_required")
                or merged.get("materialization_required")
                or merged.get("formalization_statement_pending")
            )
            target_statement = str(
                merged.get("target_statement") or getattr(node, "statement", "") or ""
            ).strip()
            if formalization_required and (
                not target_statement
                or not graph_statement_is_executable(target_statement)
            ):
                logical_key = self._frontier_materialization_logical_key(work_item)
                recovery_count = int(
                    self.materialization_pending_no_applicable_recovery_counts.get(
                        logical_key,
                        0,
                    )
                    or 0
                )
                max_recoveries = max(
                    1,
                    int(self.max_materialization_pending_no_applicable_recoveries or 1),
                )
                if any(logical_key) and recovery_count >= max_recoveries:
                    # This exact materialization contract has already received
                    # every bounded no-applicable recovery.  It cannot execute
                    # as-is, so it must no longer suppress independent static
                    # conversation work.  Fresh materialization progress clears
                    # the logical counter and restores normal suppression.
                    return False
                return True
        if work_type != "root_repair":
            return False
        unscoped_allowed, _status = self._unscoped_root_authoring_allowed()
        if not unscoped_allowed:
            return True
        if not bool(getattr(self, "_root_repair_frontier_allowed", False)):
            return False
        return any(
            self._frontier_candidate_available_for_work_item(work_item, candidate_id)
            for candidate_id in self._frontier_candidate_ids_for_work_item(work_item)
        )

    def _repair_scope_allows_forced_conversation(
        self,
        *,
        ticket: Optional[RepairTicket] = None,
    ) -> Tuple[bool, Dict[str, Any]]:
        """Whether an immediate repair turn is scoped below/inside a route.

        Top-level mini-session repair is only universal if the next LLM turn is
        repairing a known route/obligation/local target. A generic rejected root
        proof should fall back to obligation mining or route replanning instead
        of re-opening uncontracted root authoring.
        """

        if not self._root_repair_redirect_required():
            return True, {"verdict": "root_contract_not_required"}

        record: Dict[str, Any] = {}
        if ticket is not None:
            record = self._selected_work_record_from_repair_ticket(
                ticket,
                action_id=str(getattr(ticket, "source_action_id", "") or ""),
            )
            record["ticket_id"] = str(ticket.ticket_id or "")
            for key, value in {
                "target_id": str(ticket.target_id or ""),
                "route_id": str(getattr(ticket, "route_id", "") or ""),
                "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                "work_type": str(getattr(ticket, "work_type", "") or ""),
                "proof_attempt_id": str(getattr(ticket, "proof_attempt_id", "") or ""),
            }.items():
                if value:
                    record[key] = value
        else:
            record = dict(getattr(self, "selected_work_item_record", {}) or {})

        work_type = str(record.get("work_type") or "").strip()
        route_id = str(
            record.get("route_id")
            or (record.get("graph_node_id") if work_type == "assemble_route" else "")
            or (record.get("node_id") if work_type == "assemble_route" else "")
            or ""
        ).strip()
        obligation_id = str(
            record.get("obligation_id")
            or (
                record.get("graph_node_id")
                if work_type
                in {
                    "formalize_claim",
                    "prove_claim_variant",
                    "mine_missing_obligation",
                    "route_replan",
                    "materialize_replay_source",
                    "child_llm_prove",
                }
                else ""
            )
            or ""
        ).strip()
        root_node_id = str(
            getattr(getattr(self, "proof_state", None), "root_node_id", "root")
            or "root"
        )
        target_id = str(record.get("target_id") or record.get("node_id") or "").strip()

        scoped_work_types = {
            "assembly",
            "lemma_dag_decomposition",
            "child_llm_prove",
            "retrieval",
            "decl_probe",
            "tactic_swarm",
            "formalize_claim",
            "prove_claim_variant",
            "mine_missing_obligation",
            "route_replan",
            "materialize_replay_source",
        }
        if work_type == "route_replan":
            serviceable, serviceability_status = (
                self._route_replan_serviceability_status(record)
            )
            if not serviceable:
                return False, {
                    "verdict": "route_replan_requires_materialized_obligation",
                    "repair_scope": record,
                    "route_replan_status": dict(serviceability_status),
                }
        if route_id or obligation_id:
            return True, {
                "verdict": "repair_scope_has_route_or_obligation",
                "repair_scope": record,
            }
        if work_type in scoped_work_types:
            return True, {
                "verdict": "repair_scope_is_local_work",
                "repair_scope": record,
            }
        if target_id and target_id != root_node_id and target_id != "root":
            return True, {
                "verdict": "repair_scope_targets_non_root",
                "repair_scope": record,
            }
        if self._has_meaningful_non_root_frontier_work():
            return False, {
                "verdict": "unscoped_root_repair_yields_to_scoped_frontier",
                "repair_scope": record,
            }
        allowed, authoring_status = self._unscoped_root_authoring_allowed()
        if allowed:
            return True, {
                "verdict": "unscoped_root_repair_allowed_without_route_context",
                "repair_scope": record,
                "root_authoring_status": dict(authoring_status),
            }
        return False, {
            "verdict": "unscoped_root_repair_requires_selected_route",
            "repair_scope": record,
        }

    def _selected_work_record_from_repair_ticket(
        self,
        ticket: RepairTicket,
        *,
        action_id: str,
    ) -> Dict[str, Any]:
        metadata = dict(getattr(ticket, "metadata", None) or {})
        record = dict(metadata.get("selected_work_item") or {})
        work_type = str(getattr(ticket, "work_type", "") or "").strip()
        route_id = str(getattr(ticket, "route_id", "") or "").strip()
        obligation_id = str(getattr(ticket, "obligation_id", "") or "").strip()
        target_id = str(getattr(ticket, "target_id", "") or "").strip()
        root_node_id = str(
            getattr(getattr(self, "proof_state", None), "root_node_id", "root")
            or "root"
        ).strip()
        if (
            not work_type
            and not route_id
            and not obligation_id
            and target_id in {"", "root", root_node_id}
        ):
            # A legacy/root Lean-repair ticket predates typed frontier work,
            # but it still carries an unambiguous root resource.  Materialize
            # that capability explicitly instead of letting an empty work
            # type either bypass or fail the action/work authorization gate.
            work_type = "root_repair"
        if work_type:
            record.setdefault("work_type", work_type)
        if route_id:
            record.setdefault("route_id", route_id)
        if obligation_id:
            record.setdefault("obligation_id", obligation_id)
        if target_id:
            record.setdefault("node_id", target_id)
        target_statement = str(getattr(ticket, "target_statement", "") or "").strip()
        if target_statement:
            record.setdefault("target_statement", target_statement)
        proof_attempt_id = str(getattr(ticket, "proof_attempt_id", "") or "").strip()
        if proof_attempt_id:
            record.setdefault("proof_attempt_id", proof_attempt_id)
        failure_signature = str(getattr(ticket, "failure_signature", "") or "").strip()
        if failure_signature:
            record.setdefault("failure_signature", failure_signature)
        ticket_id = str(getattr(ticket, "ticket_id", "") or "").strip()
        if ticket_id:
            record.setdefault("repair_ticket_id", ticket_id)
            record.setdefault("repair_ticket_context", True)
        record["mapped_action_id"] = str(action_id or "")
        return record

    def _restore_repair_ticket_selected_work(
        self,
        ticket: RepairTicket,
        *,
        action_id: str,
    ) -> bool:
        record = self._selected_work_record_from_repair_ticket(
            ticket,
            action_id=action_id,
        )
        if not record:
            self._clear_selected_work_item()
            return False
        return self._restore_selected_work_record(
            record,
            action_id,
            context="repair_ticket",
            metric_key="mini_session_retired_graph_target_repair_ticket_suppressed",
        )

    def _select_answer_safe_recheck_action(self) -> Optional[Action]:
        """Restore exact graph work that already owns a paid proof candidate."""

        def legacy_live_frontier_record(
            binding: Mapping[str, Any],
            action_id: str,
        ) -> Dict[str, Any]:
            """Resolve one old checkpoint binding to one authentic live item."""

            wanted_node = str(binding.get("selected_node_id") or "").strip()
            wanted_variant = str(
                binding.get("selected_variant_id") or ""
            ).strip()
            wanted_work_type = str(
                binding.get("selected_work_type")
                or binding.get("graph_work_type")
                or ""
            ).strip()
            wanted_statement = str(
                binding.get("graph_statement") or ""
            ).strip()
            if not wanted_node or not wanted_work_type:
                return {}

            def layer_values(record: Mapping[str, Any], key: str) -> Set[str]:
                return {
                    str(layer.get(key) or "").strip()
                    for layer in selected_work_mapping_layers(record)
                    if str(layer.get(key) or "").strip()
                }

            matches: List[Dict[str, Any]] = []
            for work_item in self._all_work_frontier_items(
                mutate=False,
                page_limit=40,
            ):
                candidate = self._work_item_to_record(work_item)
                candidate_work_types = layer_values(candidate, "work_type")
                if wanted_work_type not in candidate_work_types:
                    continue
                candidate_nodes = (
                    layer_values(candidate, "node_id")
                    | layer_values(candidate, "graph_node_id")
                )
                if wanted_node not in candidate_nodes:
                    continue
                candidate_variants = layer_values(candidate, "variant_id")
                if wanted_variant and wanted_variant not in candidate_variants:
                    continue
                if not wanted_variant and candidate_variants:
                    continue
                if wanted_statement:
                    candidate_statements = (
                        layer_values(candidate, "exact_target_statement")
                        | layer_values(candidate, "target_statement")
                    )
                    if not any(
                        canonical_dossier_statement_key(statement)
                        == canonical_dossier_statement_key(wanted_statement)
                        for statement in candidate_statements
                    ):
                        continue
                if not self._selected_work_action_compatible(
                    action_id,
                    candidate,
                ):
                    continue
                candidate["mapped_action_id"] = action_id
                matches.append(candidate)
            if len(matches) == 1:
                return matches[0]
            if not matches:
                return {}
            expected_context_digest = str(
                binding.get("selected_context_digest") or ""
            ).strip()
            resolver = getattr(
                getattr(self, "dossier", None),
                "resolve_proof_idea_context",
                None,
            )
            if expected_context_digest and callable(resolver):
                context_matches: List[Dict[str, Any]] = []
                for candidate in matches:
                    try:
                        resolution = resolver(
                            candidate,
                            policy="exact_selected",
                        )
                    except Exception:
                        continue
                    if (
                        str(getattr(resolution, "status", "") or "")
                        == "resolved"
                        and str(
                            getattr(resolution, "context_digest", "") or ""
                        ).strip()
                        == expected_context_digest
                    ):
                        context_matches.append(candidate)
                if len(context_matches) == 1:
                    return context_matches[0]
            # A legacy packet with ambiguous live cognition has no authority
            # to pick a consumer. Keep the paid candidate owned and wait for
            # graph maintenance to restore a unique exact projection.
            return {}

        ordered_actions = sorted(
            enumerate(self.actions),
            key=lambda pair: (
                pair[1].priority,
                pair[1].cost_estimate_s,
                pair[0],
            ),
        )
        for _index, action in ordered_actions:
            action_id = str(getattr(action, "id", "") or "").strip()
            deferred_metadata = dict(
                self.model_call_deferred_static_action_metadata.get(action_id)
                or {}
            )
            verifier_cooldown = bool(
                self._model_call_deferred_static_action_effective(action_id)
                and str(deferred_metadata.get("llm_failure_kind") or "")
                == "lean_verifier_infrastructure_unavailable"
                and not self._persistent_infrastructure_retry_is_ready(
                    deferred_metadata
                )
            )
            if verifier_cooldown:
                # Provider-free ownership bypasses provider backoff, but not
                # the verifier's own bounded cooldown. Let unrelated formal
                # work run until this Lean lane is ready again.
                continue
            records_getter = getattr(
                action,
                "answer_safe_recheck_work_records",
                None,
            )
            if not callable(records_getter):
                continue
            try:
                records = list(records_getter() or [])
            except Exception:
                # Runtime-state validation owns the diagnostic. Never replace
                # uninspectable paid work with a fresh provider dispatch.
                return None
            for raw_record in records:
                record = dict(raw_record or {})
                identity = str(
                    record.pop("_answer_safe_recheck_identity", "") or ""
                ).strip()
                if not identity or not record:
                    continue
                legacy_binding = record.pop(
                    "_answer_safe_recheck_legacy_binding",
                    None,
                )
                unscoped = bool(
                    record.pop("_answer_safe_recheck_unscoped", False)
                )
                if isinstance(legacy_binding, Mapping) and not unscoped:
                    record = legacy_live_frontier_record(
                        legacy_binding,
                        action_id,
                    )
                    if not record:
                        legacy_liveness_record = {
                            "node_id": str(
                                legacy_binding.get("selected_node_id") or ""
                            ).strip(),
                            "graph_node_id": str(
                                legacy_binding.get("graph_node_id") or ""
                            ).strip(),
                            "variant_id": str(
                                legacy_binding.get("selected_variant_id") or ""
                            ).strip(),
                            "work_type": str(
                                legacy_binding.get("selected_work_type")
                                or legacy_binding.get("graph_work_type")
                                or ""
                            ).strip(),
                            "target_statement": str(
                                legacy_binding.get("graph_statement") or ""
                            ).strip(),
                        }
                        if self._selected_work_targets_terminal_graph_work_probe(
                            legacy_liveness_record
                        ):
                            discard = getattr(
                                action,
                                "discard_answer_safe_recheck_work",
                                None,
                            )
                            if callable(discard):
                                discard(identity)
                        continue
                verifier_applicable = getattr(
                    action,
                    "answer_safe_recheck_is_applicable",
                    None,
                )

                def paid_verifier_is_applicable(context: str) -> bool:
                    if callable(verifier_applicable):
                        return self._safe_is_applicable(
                            action,
                            context=context,
                            predicate=lambda _session: verifier_applicable(
                                _session,
                                identity=identity,
                            ),
                        )
                    return self._safe_is_applicable(action, context=context)

                if unscoped:
                    self._clear_selected_work_item()
                    if isinstance(legacy_binding, Mapping):
                        rebind_legacy = getattr(
                            action,
                            "rebind_legacy_answer_safe_recheck",
                            None,
                        )
                        if not callable(rebind_legacy):
                            continue
                        identity = str(
                            rebind_legacy(self, identity=identity) or ""
                        ).strip()
                        if not identity:
                            continue
                    if paid_verifier_is_applicable(
                        "answer_safe_recheck_unscoped"
                    ):
                        self._activate_answer_safe_recheck_repair_ticket_binding(
                            action_id=action_id,
                            recheck_identity=identity,
                        )
                        self._record_event(
                            {
                                "phase": "session_answer_safe_recheck",
                                "iteration": self.iteration,
                                "action_id": action_id,
                                "answer_safe_recheck_identity": identity,
                                "verdict": "unscoped_verifier_work_selected",
                            }
                        )
                        return action
                    continue
                if self._selected_work_targets_terminal_graph_work_probe(record):
                    discard = getattr(
                        action,
                        "discard_answer_safe_recheck_work",
                        None,
                    )
                    if callable(discard):
                        discard(identity)
                    continue
                if not self._restore_selected_work_record(
                    record,
                    str(getattr(action, "id", "") or ""),
                    context="answer_safe_recheck",
                    metric_key=(
                        "mini_session_answer_safe_recheck_terminal_target_suppressed"
                    ),
                    bypass_dispatch_blocked=True,
                ):
                    continue
                rebind_selected = getattr(
                    action,
                    "rebind_legacy_answer_safe_recheck",
                    None,
                )
                if callable(rebind_selected):
                    identity = str(
                        rebind_selected(self, identity=identity) or ""
                    ).strip()
                    if not identity:
                        self._clear_selected_work_item()
                        continue
                if not paid_verifier_is_applicable("answer_safe_recheck"):
                    self._clear_selected_work_item()
                    continue
                self._activate_answer_safe_recheck_repair_ticket_binding(
                    action_id=action_id,
                    recheck_identity=identity,
                )
                self._record_event(
                    {
                        "phase": "session_answer_safe_recheck",
                        "iteration": self.iteration,
                        "action_id": str(getattr(action, "id", "") or ""),
                        "selected_work_item": dict(self.selected_work_item_record),
                        "answer_safe_recheck_identity": identity,
                        "verdict": "exact_verifier_work_selected",
                    }
                )
                return action
        return None

    def _activate_drained_answer_safe_terminal_provider_failure(self) -> bool:
        """Publish held terminal authority once no formal action can proceed."""

        if self.root_finalized and self._durable_final_proof():
            return False
        for action in self.actions:
            has_work = getattr(action, "has_answer_safe_recheck_work", None)
            if not callable(has_work):
                continue
            try:
                if has_work():
                    return False
            except Exception:
                # An uninspectable paid continuation is still stronger than
                # a held provider stop.  Validation/restore owns diagnosis.
                return False
        for action in self.actions:
            has_terminal = getattr(
                action,
                "has_answer_safe_terminal_provider_failure",
                None,
            )
            has_work = getattr(action, "has_answer_safe_recheck_work", None)
            take_terminal = getattr(
                action,
                "take_answer_safe_terminal_provider_failure",
                None,
            )
            if not all(
                callable(method)
                for method in (has_terminal, has_work, take_terminal)
            ):
                continue
            try:
                if not has_terminal():
                    continue
                terminal = dict(take_terminal() or {})
            except Exception:
                continue
            reason = str(terminal.get("terminal_failure_reason") or "").strip()
            if not reason:
                continue
            kind = str(terminal.get("llm_failure_kind") or "").strip()
            self.terminal_failure_reason = reason
            self.terminal_failure_kind = kind
            self.last_failure_reason = reason
            try:
                setattr(self.dossier, "session_failure_reason", reason)
                if kind:
                    setattr(self.dossier, "session_failure_kind", kind)
            except Exception:
                pass
            self._record_event(
                {
                    "phase": "session_answer_safe_recheck",
                    "iteration": self.iteration,
                    "action_id": str(getattr(action, "id", "") or ""),
                    "reason": reason,
                    "kind": kind,
                    "verdict": "held_provider_terminal_activated_after_drain",
                }
            )
            return True
        return False

    def select_next_action(self) -> Optional[Action]:
        """Frontier-first then static priority fallback.

        M0 returns the first action whose ``is_applicable(session)`` is
        True and whose budget is not exhausted, scanning in priority
        order. The frontier-first pre-pass (see ``_map_work_item_to_action``)
        is implemented in M2 once the action mapping table is populated.
        """

        reconcile_facts = getattr(
            self.dossier,
            "reconcile_verified_facts",
            None,
        )
        if callable(reconcile_facts):
            try:
                reconciliation = reconcile_facts(trigger="session_pre_select")
            except Exception as exc:
                self._defer_selector_infrastructure(
                    action_ids=tuple(
                        str(getattr(item, "id", "") or "") for item in self.actions
                    ),
                    context="reconcile_verified_facts",
                    error=exc,
                )
                return None
            resolved_node_ids = list(
                (reconciliation or {}).get("resolved_node_ids") or []
            )
            newly_ready_route_ids = list(
                (reconciliation or {}).get("newly_ready_route_ids") or []
            )
            if resolved_node_ids or newly_ready_route_ids:
                self._record_event(
                    {
                        "phase": "session_semantic_fact_reconciliation",
                        "iteration": self.iteration,
                        "resolved_node_ids": resolved_node_ids,
                        "newly_ready_route_ids": newly_ready_route_ids,
                        "verdict": "accepted_facts_reconciled",
                    }
                )
        reconcile_invalidations = getattr(
            self.dossier,
            "reconcile_invalidated_graph_targets",
            None,
        )
        if callable(reconcile_invalidations):
            try:
                invalidation_closure = reconcile_invalidations() or {}
            except Exception as exc:
                self._defer_selector_infrastructure(
                    action_ids=tuple(
                        str(getattr(item, "id", "") or "")
                        for item in self.actions
                        if not (
                            self.budgets.get(str(getattr(item, "id", "") or ""))
                            and self.budgets[
                                str(getattr(item, "id", "") or "")
                            ].exhausted()
                        )
                    ),
                    context="reconcile_invalidated_graph_targets",
                    error=exc,
                )
                return None
            terminalized_node_ids = list(
                invalidation_closure.get("terminalized_node_ids") or []
            )
            retired_route_ids = list(
                invalidation_closure.get("retired_route_ids") or []
            )
            if terminalized_node_ids or retired_route_ids:
                self._record_event(
                    {
                        "phase": "session_authoritative_invalidation_reconciliation",
                        "iteration": self.iteration,
                        "terminalized_node_ids": terminalized_node_ids,
                        "retired_route_ids": retired_route_ids,
                        "verdict": "authoritative_invalidations_reconciled",
                    }
                )
        # Proof-state aliases can also be projected after the original
        # certificate. Reapply only the already-active, typed certificate
        # provenance; the immutable ledger alone is deliberately insufficient
        # until fresh replay recreates this authority.
        late_falsified_child_ids: List[str] = []
        for authority in dict(
            getattr(self.dossier, "mini_authoritative_negations", {}) or {}
        ).values():
            if not isinstance(authority, dict):
                continue
            statement = str(authority.get("statement") or "").strip()
            certificate_hash = str(authority.get("certificate_hash") or "").strip()
            target_environment_hash = str(
                authority.get("target_environment_hash") or ""
            ).strip()
            if not statement or not certificate_hash or not target_environment_hash:
                continue
            try:
                from .child_goal_falsification import (
                    terminalize_exact_proof_state_aliases,
                )

                late_falsified_child_ids.extend(
                    terminalize_exact_proof_state_aliases(
                        parent_session=self,
                        dossier=self.dossier,
                        statement=statement,
                        certificate_hash=certificate_hash,
                        target_environment_hash=target_environment_hash,
                        reason=("active Lean negation terminalized late exact goal"),
                    )
                )
            except Exception:
                continue
        if late_falsified_child_ids:
            self._record_event(
                {
                    "phase": "session_authoritative_invalidation_reconciliation",
                    "iteration": self.iteration,
                    "terminalized_proof_state_aliases": list(
                        dict.fromkeys(late_falsified_child_ids)
                    ),
                    "verdict": "authoritative_proof_state_aliases_reconciled",
                }
            )
        reconcile_attempts = getattr(
            self.dossier,
            "reconcile_proof_attempt_lineage",
            None,
        )
        if callable(reconcile_attempts):
            try:
                reconcile_attempts()
            except Exception as exc:
                self._defer_selector_infrastructure(
                    action_ids=tuple(
                        str(getattr(item, "id", "") or "")
                        for item in self.actions
                        if not (
                            self.budgets.get(str(getattr(item, "id", "") or ""))
                            and self.budgets[
                                str(getattr(item, "id", "") or "")
                            ].exhausted()
                        )
                    ),
                    context="reconcile_proof_attempt_lineage",
                    error=exc,
                )
                return None
        reconcile_proof_state = getattr(
            self.proof_state,
            "record_verified_helper_matches",
            None,
        )
        if callable(reconcile_proof_state):
            visible_helper_names = [
                name
                for name, helper in dict(
                    getattr(self.dossier, "verified_helpers", {}) or {}
                ).items()
                if bool(
                    getattr(
                        self.dossier,
                        "is_verified_helper_context_visible",
                        lambda _helper: True,
                    )(helper)
                )
            ]
            try:
                reconcile_proof_state(
                    dossier=self.dossier,
                    helper_names=visible_helper_names,
                    source="session_pre_select",
                    phase="semantic_fact_reconciliation",
                    turn_index=int(self.iteration or 0),
                )
            except Exception as exc:
                self._defer_selector_infrastructure(
                    action_ids=tuple(
                        str(getattr(item, "id", "") or "") for item in self.actions
                    ),
                    context="record_verified_helper_matches",
                    error=exc,
                )
                return None
        self._reconcile_repair_policy_narrowing(trigger="session_pre_select")
        durable_tool_continuation = (
            self._select_durable_progress_tool_continuation_action()
        )
        if durable_tool_continuation is not None:
            return durable_tool_continuation
        self._clear_selected_work_item()
        answer_safe_recheck_action = self._select_answer_safe_recheck_action()
        if answer_safe_recheck_action is not None:
            return answer_safe_recheck_action
        self._release_matured_model_call_deferred_after_static_quantum()
        self._selected_work_liveness_suppression_keys.clear()
        self._repair_first_selected_local_forced = False
        self._repair_first_selected_signature_key = ""
        self._repair_first_deferred_action_ids.clear()
        self._root_repair_frontier_allowed = False
        suppress_static_conversation_after_route_work = False
        root_repair_static_prepass_deferred = False
        root_repair_static_prepass_work_keys: Set[Tuple[str, str, str, str, str]] = (
            set()
        )
        route_static_suppression_recorded = False
        root_repair_gate_computed = False
        force_cost_static_conversation = (
            int(self.cost_governed_force_static_conversation_turns or 0) > 0
        )

        def suppress_route_static_conversation(reason: str, work_item: Any) -> None:
            nonlocal suppress_static_conversation_after_route_work
            nonlocal route_static_suppression_recorded
            suppress_static_conversation_after_route_work = True
            if route_static_suppression_recorded:
                return
            route_static_suppression_recorded = True
            self._increment_dossier_metric(
                "mini_session_assemble_route_static_conversation_suppressed",
                1,
            )
            self._record_event(
                {
                    "phase": "session_assemble_route_static_fallback",
                    "iteration": self.iteration,
                    "reason": str(reason or ""),
                    "selected_work_item": self._work_item_to_record(work_item),
                    "verdict": "conversation_suppressed",
                }
            )

        # A concrete Lean rejection should feed the same proof and diagnostics
        # back to the model before fallback/replan machinery changes the shape
        # of the task.
        self._repair_first_scheduler_blocked = False
        repair_first_yielded_to_competitor = False
        forced_conversation = self._repair_first_conversation_action()
        if forced_conversation is not None:
            should_yield = getattr(
                forced_conversation,
                "should_yield_static_dispatch",
                None,
            )
            if callable(should_yield) and should_yield(self):
                # A completed provider/tool quantum is a safe cutpoint. Let
                # the ordinary frontier/static scheduler try one independent
                # lane, while its existing yielded-action fallback guarantees
                # that a lone repair owner continues immediately.
                repair_first_yielded_to_competitor = True
                self._record_event(
                    {
                        "phase": "session_provider_quantum_fairness",
                        "iteration": self.iteration,
                        "action_id": forced_conversation.id,
                        "verdict": "repair_owner_yielded_to_competitor",
                    }
                )
                self._clear_selected_work_item()
            else:
                return forced_conversation
        if self._repair_first_scheduler_blocked:
            return None
        if (
            self._active_repair_ticket() is not None
            and not self._repair_first_deferred_action_ids
            and not repair_first_yielded_to_competitor
        ):
            ticket = self._active_repair_ticket()
            self._increment_dossier_metric(
                "mini_session_repair_tickets_scheduler_blocked",
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": str(getattr(ticket, "ticket_id", "") or ""),
                    "target_id": str(getattr(ticket, "target_id", "") or ""),
                    "route_id": str(getattr(ticket, "route_id", "") or ""),
                    "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                    "work_type": str(getattr(ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(ticket, "proof_attempt_id", "") or ""
                    ),
                    "verdict": "scheduler_blocked_until_repair",
                }
            )
            return None
        reserved_fallback = self._select_reserved_no_applicable_fallback()
        if reserved_fallback is not None:
            return reserved_fallback

        if force_cost_static_conversation and not self.repair_policy_narrowing_required:
            forced_static = self._select_cost_governed_forced_static_action(
                consume=True,
                context="cost_governed_forced_static",
            )
            if forced_static is not None:
                return forced_static
            self._increment_dossier_metric(
                "mini_session_cost_governed_no_dispatch_lane",
                1,
            )
            self._record_event(
                {
                    "phase": "session_cost_governed_continuation",
                    "iteration": self.iteration,
                    "verdict": "forced_static_conversation_unavailable",
                }
            )
            self.cost_governed_force_static_conversation_turns = 0

        repair_policy_has_narrowing_candidate = bool(
            self.repair_policy_narrowing_required
            and self._has_repair_policy_narrowing_candidate()
        )
        if (
            self.repair_policy_narrowing_required
            and not repair_policy_has_narrowing_candidate
        ):
            self._record_event(
                {
                    "phase": "session_repair_policy_narrowing",
                    "iteration": self.iteration,
                    "reason": self.repair_policy_narrowing_reason,
                    "selected_work_item": dict(
                        self.repair_policy_narrowing_selected_work_record
                    ),
                    "verdict": "no_static_narrowing_candidate_frontier_probe",
                }
            )
        repair_policy_forces_fallback = bool(
            repair_policy_has_narrowing_candidate and self.fallback_action_ids
        )
        repair_policy_needs_adaptive_fallback = bool(
            self.repair_policy_narrowing_required
            and not repair_policy_has_narrowing_candidate
            and self.fallback_action_ids
            and self._repair_policy_no_candidate_allows_adaptive_fallback()
        )
        repair_policy_child_adaptive_fallback = bool(
            self.repair_policy_narrowing_required
            and self._repair_policy_child_adaptive_fallback_available()
        )
        if (
            (
                self.stagnation_counter >= self.max_stagnation
                or repair_policy_forces_fallback
                or repair_policy_needs_adaptive_fallback
                or repair_policy_child_adaptive_fallback
            )
            and not self.fallback_actions_attempted
            and self.fallback_action_ids
        ):
            ordered_fallbacks = sorted(
                enumerate(self.actions),
                key=lambda pair: (
                    pair[1].priority,
                    pair[1].cost_estimate_s,
                    pair[0],
                ),
            )
            for _index, fallback_action in ordered_fallbacks:
                if fallback_action.id not in self.fallback_action_ids:
                    continue
                # A fallback may share its provider/planner dependency with a
                # primary action.  A scoped failure defers the entire family;
                # the fallback must not bypass that guard merely because this
                # selection block runs before the ordinary static scan.
                if (
                    self._model_call_deferred_static_action_effective(
                        fallback_action.id
                    )
                ):
                    continue
                budget = self.budgets.get(fallback_action.id)
                if budget is not None and budget.exhausted():
                    continue
                if (
                    (
                        repair_policy_forces_fallback
                        or repair_policy_needs_adaptive_fallback
                        or repair_policy_child_adaptive_fallback
                    )
                    and self._repair_policy_static_action_is_broad(
                        fallback_action.id,
                        self.repair_policy_narrowing_selected_work_record,
                    )
                    and not self._repair_policy_allows_child_adaptive_fallback(
                        fallback_action.id
                    )
                ):
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": fallback_action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "verdict": "broad_fallback_action_skipped",
                        }
                    )
                    continue
                if (
                    not (
                        repair_policy_needs_adaptive_fallback
                        or repair_policy_child_adaptive_fallback
                    )
                    and self._is_unscoped_root_authoring_action(fallback_action.id)
                    and self._has_meaningful_non_root_frontier_work()
                ):
                    self._record_event(
                        {
                            "phase": "session_root_authoring_gate",
                            "iteration": self.iteration,
                            "action_id": fallback_action.id,
                            "context": "fallback",
                            "verdict": "root_authoring_yielded_to_scoped_frontier",
                        }
                    )
                    continue
                if (
                    not (
                        repair_policy_needs_adaptive_fallback
                        or repair_policy_child_adaptive_fallback
                    )
                    and self._is_unscoped_root_authoring_action(fallback_action.id)
                    and self._suppress_unscoped_root_authoring(
                        fallback_action.id,
                        context="fallback",
                    )
                ):
                    continue
                self._clear_selected_work_item()
                restore_failed = False
                if (
                    repair_policy_forces_fallback
                    or repair_policy_needs_adaptive_fallback
                    or repair_policy_child_adaptive_fallback
                ):
                    restored_narrowing_work = (
                        self._restore_repair_policy_narrowing_selected_work(
                            fallback_action.id
                        )
                    )
                    if (
                        self.repair_policy_narrowing_selected_work_record
                        and not restored_narrowing_work
                    ):
                        self._record_event(
                            {
                                "phase": "session_repair_policy_narrowing",
                                "iteration": self.iteration,
                                "action_id": fallback_action.id,
                                "reason": self.repair_policy_narrowing_reason,
                                "selected_work_item": dict(
                                    self.repair_policy_narrowing_selected_work_record
                                ),
                                "verdict": "fallback_selected_work_restore_failed",
                            }
                        )
                        self._clear_selected_work_item()
                        restore_failed = True
                        continue
                if restore_failed:
                    continue
                if not self._safe_is_applicable(fallback_action, context="fallback"):
                    self._clear_selected_work_item()
                    continue
                if repair_policy_forces_fallback:
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": fallback_action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "selected_work_item": dict(self.selected_work_item_record),
                            "verdict": "fallback_selected",
                        }
                    )
                elif repair_policy_needs_adaptive_fallback:
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": fallback_action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "verdict": "fallback_selected_no_scoped_candidate",
                        }
                    )
                elif repair_policy_child_adaptive_fallback:
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": fallback_action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "selected_work_item": dict(self.selected_work_item_record),
                            "verdict": "child_adaptive_fallback_selected",
                        }
                    )
                return fallback_action

        fairness_root_action = (
            self._select_scoped_frontier_root_authoring_fairness_action()
        )
        if fairness_root_action is not None:
            return fairness_root_action

        fixed_point_family_action = self._select_unseen_fixed_point_action_family()
        if fixed_point_family_action is not None:
            return fixed_point_family_action

        # 1. Frontier-first (placeholder until M2 populates the mapping).
        #
        # A persistent scoped action may explicitly request one fair static
        # dispatch after making progress.  Preserve its exact frontier
        # selection as a fallback while giving the normal static scheduler one
        # chance to select a real competitor.  Without this bridge, the
        # frontier's early return bypasses ``should_yield_static_dispatch`` and
        # indefinitely starves resumable static work such as falsification.
        yielded_frontier_action: Optional[Action] = None
        yielded_frontier_work_item: Any = None
        yielded_frontier_action_key: Optional[Tuple[str, str, str, str, str, str]] = (
            None
        )
        yield_frontier_to_static = False
        if self.proof_state is not None:
            # Rank across the bounded global lookahead, not independently
            # inside each pagination window. Otherwise the legacy work-type
            # ordering of page zero can still hide a much higher-value root
            # bottleneck on page one.
            for _frontier_page in range(1):
                skipped_before = len(self.skipped_frontier_work_keys)
                consumed_before = len(self.consumed_frontier_work_keys)
                skipped_action_before = len(self.skipped_frontier_action_keys)
                consumed_action_before = len(self.consumed_frontier_action_keys)
                saw_frontier_item = False
                frontier_items = self._all_work_frontier_items(
                    mutate=True,
                    page_limit=40,
                )
                original_frontier_items = list(frontier_items)
                frontier_items = self._rank_frontier_items_for_dispatch(frontier_items)
                if frontier_items and str(
                    self._work_item_field(
                        frontier_items[0],
                        "work_type",
                        "",
                    )
                    or ""
                ).strip() in {"assembly", "assemble_route"}:
                    self._retire_unserviceable_frontier_prefix(
                        original_frontier_items,
                        winner=frontier_items[0],
                    )
                for work_item in frontier_items:
                    saw_frontier_item = True
                    work_key = self._frontier_work_key(work_item)
                    work_type = str(
                        self._work_item_field(work_item, "work_type", "") or ""
                    ).strip()
                    if work_type == "root_repair" and not root_repair_gate_computed:
                        self._root_repair_frontier_allowed = (
                            self._root_repair_allowed_by_global_frontier()
                        )
                        root_repair_gate_computed = True
                    if work_key in self.skipped_frontier_work_keys:
                        if self._frontier_work_suppresses_static_conversation(
                            work_item
                        ):
                            suppress_route_static_conversation(
                                "route_frontier_already_skipped",
                                work_item,
                            )
                        continue
                    tried_frontier_action = False
                    while True:
                        action = self._map_work_item_to_action(work_item)
                        if action is None:
                            temporarily_model_deferred = any(
                                self._frontier_action_key(
                                    work_item,
                                    candidate_id,
                                )
                                in self.model_call_deferred_frontier_action_keys
                                or self._model_call_deferred_static_action_blocks_work_item(
                                    candidate_id,
                                    work_item,
                                )
                                for candidate_id in (
                                    self._frontier_candidate_ids_for_work_item(
                                        work_item
                                    )
                                )
                            )
                            temporarily_lean_deferred = (
                                self._work_item_waits_for_shared_lean(work_item)
                            )
                            root_repair_deferred_to_static_prepass = (
                                work_type == "root_repair"
                                and self._static_action_available_before_root_repair()
                            )
                            if root_repair_deferred_to_static_prepass:
                                root_repair_static_prepass_deferred = True
                                if any(work_key):
                                    root_repair_static_prepass_work_keys.add(work_key)
                            if (
                                any(work_key)
                                and not tried_frontier_action
                                and not root_repair_deferred_to_static_prepass
                                and not temporarily_model_deferred
                                and not temporarily_lean_deferred
                            ):
                                self.skipped_frontier_work_keys.add(work_key)
                            if self._frontier_work_suppresses_static_conversation(
                                work_item
                            ):
                                suppress_route_static_conversation(
                                    "route_action_unavailable",
                                    work_item,
                                )
                            break
                        budget = self.budgets.get(action.id)
                        if budget is not None and budget.exhausted():
                            if any(work_key):
                                self.skipped_frontier_work_keys.add(work_key)
                            if self._frontier_work_suppresses_static_conversation(
                                work_item
                            ):
                                suppress_route_static_conversation(
                                    "route_action_budget_exhausted",
                                    work_item,
                                )
                            break
                        if self._local_micro_theory_should_skip_action(
                            action.id,
                            context="frontier",
                        ):
                            if any(work_key):
                                self.skipped_frontier_action_keys.add(
                                    self._frontier_action_key(work_item, action.id)
                                )
                            self._clear_selected_work_item()
                            continue
                        if not self._set_selected_work_item(work_item, action.id):
                            if any(work_key):
                                self.skipped_frontier_work_keys.add(work_key)
                                self.skipped_frontier_action_keys.add(
                                    self._frontier_action_key(work_item, action.id)
                                )
                            break
                        self._activate_selected_graph_ready_work_item(work_item)
                        if not self._safe_is_applicable(action, context="frontier"):
                            tried_frontier_action = True
                            if any(work_key):
                                self.skipped_frontier_action_keys.add(
                                    self._frontier_action_key(work_item, action.id)
                                )
                            if self._frontier_work_suppresses_static_conversation(
                                work_item
                            ):
                                suppress_route_static_conversation(
                                    "route_action_not_applicable",
                                    work_item,
                                )
                            self._clear_selected_work_item()
                            continue
                        if self.repair_policy_narrowing_required:
                            if not self._repair_policy_selected_work_is_narrow(
                                action.id
                            ):
                                self._record_event(
                                    {
                                        "phase": "session_repair_policy_narrowing",
                                        "iteration": self.iteration,
                                        "action_id": action.id,
                                        "reason": self.repair_policy_narrowing_reason,
                                        "selected_work_item": dict(
                                            self.selected_work_item_record
                                        ),
                                        "verdict": "broad_frontier_action_skipped",
                                    }
                                )
                                if any(work_key):
                                    self.skipped_frontier_action_keys.add(
                                        self._frontier_action_key(work_item, action.id)
                                    )
                                self._clear_selected_work_item()
                                continue
                            self._record_event(
                                {
                                    "phase": "session_repair_policy_narrowing",
                                    "iteration": self.iteration,
                                    "action_id": action.id,
                                    "reason": self.repair_policy_narrowing_reason,
                                    "selected_work_item": dict(
                                        self.selected_work_item_record
                                    ),
                                    "verdict": "frontier_action_selected",
                                }
                            )
                        frontier_action_key = self._frontier_action_key(
                            work_item, action.id
                        )
                        if repair_first_yielded_to_competitor:
                            # The repair owner already spent the sole fairness
                            # yield for this scheduler scan.  This independent
                            # frontier action is the competitor; allowing it
                            # to yield again can cascade into a sibling
                            # conversation role that shares and can overwrite
                            # the parked owner's transcript.
                            if str(action.id or "").startswith("conversation_turn"):
                                # A prove/refine sibling is the same mutable
                                # conversation lane, not an independent
                                # competitor. Skip it for this scan without a
                                # durable skip-set entry; it remains eligible
                                # after the exact owner settles.
                                self._clear_selected_work_item()
                                break
                            self.selected_frontier_action_key = frontier_action_key
                            return action
                        should_yield = getattr(
                            action, "should_yield_static_dispatch", None
                        )
                        if callable(should_yield) and should_yield(self):
                            yielded_frontier_action = action
                            yielded_frontier_work_item = work_item
                            yielded_frontier_action_key = frontier_action_key
                            yield_frontier_to_static = True
                            self._record_event(
                                {
                                    "phase": "session_frontier_fairness",
                                    "iteration": self.iteration,
                                    "action_id": action.id,
                                    "selected_work_item": dict(
                                        self.selected_work_item_record
                                    ),
                                    "verdict": "yielded_to_static_competitor",
                                }
                            )
                            self._clear_selected_work_item()
                            break
                        self.selected_frontier_action_key = frontier_action_key
                        return action
                    if yield_frontier_to_static:
                        break
                if yield_frontier_to_static:
                    break
                if not saw_frontier_item:
                    break
                if (
                    len(self.skipped_frontier_work_keys) == skipped_before
                    and len(self.consumed_frontier_work_keys) == consumed_before
                    and len(self.skipped_frontier_action_keys) == skipped_action_before
                    and len(self.consumed_frontier_action_keys)
                    == consumed_action_before
                ):
                    break

        if not yield_frontier_to_static:
            route_drain_action = self._select_ready_root_route_assembly_action()
            if route_drain_action is not None:
                return route_drain_action

        # 2. Static priority fallback. Sort registered actions by
        # ``priority`` ascending; tie-break by ``cost_estimate_s`` ascending,
        # then by registration order.
        release_suppressed_conversation_ids = set(
            self._dispatch_generation_release_suppressed_action_ids
        )
        ordered = sorted(
            enumerate(self.actions),
            key=lambda pair: (
                pair[1].priority,
                pair[1].cost_estimate_s,
                pair[0],
            ),
        )
        yielded_static_action: Optional[Action] = (
            forced_conversation
            if repair_first_yielded_to_competitor
            else None
        )
        for _index, action in ordered:
            conversation_quantum_owner = next(
                (
                    owner
                    for owner in (yielded_static_action, yielded_frontier_action)
                    if owner is not None
                    and str(owner.id or "").startswith("conversation_turn")
                ),
                None,
            )
            if (
                conversation_quantum_owner is not None
                and str(action.id or "").startswith("conversation_turn")
            ):
                # Prove/refine share one live conversation transcript and
                # provider continuation. A sibling role is not independent
                # work and must not replace the exact owner at this cutpoint.
                continue
            if action is yielded_frontier_action:
                # The frontier owner already spent its one-shot yield token
                # in this scan. Keep it only as the exact fallback below so a
                # lower-priority independent action can actually interleave.
                continue
            if (
                repair_first_yielded_to_competitor
                and action is forced_conversation
            ):
                continue
            if str(action.id or "") in self._repair_first_deferred_action_ids:
                continue
            if self._model_call_deferred_static_action_effective(action.id):
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if self._local_micro_theory_should_skip_action(
                action.id,
                context="static",
            ):
                continue
            if (
                self.repair_policy_narrowing_required
                and self._repair_policy_static_action_is_broad(
                    action.id,
                    self.repair_policy_narrowing_selected_work_record,
                )
            ):
                self._record_event(
                    {
                        "phase": "session_repair_policy_narrowing",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "reason": self.repair_policy_narrowing_reason,
                        "verdict": "broad_repair_turn_skipped",
                    }
                )
                continue
            if (
                root_repair_static_prepass_deferred
                and not force_cost_static_conversation
                and str(action.id or "") not in release_suppressed_conversation_ids
                and not self._static_action_should_precede_root_repair(action)
            ):
                continue
            if (
                suppress_static_conversation_after_route_work
                and not force_cost_static_conversation
                and str(action.id or "") not in release_suppressed_conversation_ids
                and (
                    self._is_unscoped_root_authoring_action(action.id)
                    or str(action.id or "").startswith("conversation_turn")
                )
                and not (
                    root_repair_static_prepass_deferred
                    and self._static_action_should_precede_root_repair(action)
                )
            ):
                continue
            if (
                self._is_unscoped_root_authoring_action(action.id)
                and not force_cost_static_conversation
                and self._suppress_unscoped_root_authoring(
                    action.id,
                    context="static",
                )
            ):
                continue
            self._clear_selected_work_item()
            if self.repair_policy_narrowing_required:
                restored_narrowing_work = (
                    self._restore_repair_policy_narrowing_selected_work(action.id)
                )
                if (
                    self.repair_policy_narrowing_selected_work_record
                    and not restored_narrowing_work
                ):
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "selected_work_item": dict(
                                self.repair_policy_narrowing_selected_work_record
                            ),
                            "verdict": "static_selected_work_restore_failed",
                        }
                    )
                    self._clear_selected_work_item()
                    continue
            if not self._safe_is_applicable(action, context="static"):
                self._clear_selected_work_item()
                continue
            if self.repair_policy_narrowing_required:
                if not self._repair_policy_selected_work_is_narrow(action.id):
                    self._record_event(
                        {
                            "phase": "session_repair_policy_narrowing",
                            "iteration": self.iteration,
                            "action_id": action.id,
                            "reason": self.repair_policy_narrowing_reason,
                            "selected_work_item": dict(self.selected_work_item_record),
                            "verdict": "broad_static_action_skipped",
                        }
                    )
                    self._clear_selected_work_item()
                    continue
                self._record_event(
                    {
                        "phase": "session_repair_policy_narrowing",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "reason": self.repair_policy_narrowing_reason,
                        "selected_work_item": dict(self.selected_work_item_record),
                        "verdict": "narrowing_action_selected",
                    }
                )
            if (
                root_repair_static_prepass_deferred
                and self._static_action_should_precede_root_repair(action)
            ):
                prepass_payload = {
                    "action_id": str(action.id or ""),
                    "root_work_keys": sorted(
                        [list(key) for key in root_repair_static_prepass_work_keys]
                    ),
                    "planner_frontier": self._recursive_planner_frontier_signature(),
                }
                prepass_signature = hashlib.sha256(
                    json.dumps(
                        prepass_payload,
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=True,
                    ).encode("utf-8")
                ).hexdigest()
                # The one-shot ledger must be spent on a grant that actually
                # moves the ceiling.  ``expand_max_iterations_to_action_budgets``
                # sets max_iterations from the registered invocation budgets
                # (413 root / 170 subgoal on putnam_1977_a2 2026-08-19), so
                # ``iteration + 2`` is a no-op for almost the whole session.
                # Recording those no-ops as "granted" both mis-reported the
                # ceiling and burned the signature, so the one grant it was
                # entitled to could never fire at the boundary where the
                # deferred root repair actually needed it.
                old_max_iterations = int(self.max_iterations or 0)
                required_max_iterations = int(self.iteration or 0) + 2
                extends_ceiling = required_max_iterations > old_max_iterations
                fresh_headroom = extends_ceiling and (
                    prepass_signature
                    not in self.static_prepass_headroom_signatures_seen
                )
                if fresh_headroom:
                    self.static_prepass_headroom_signatures_seen.add(prepass_signature)
                    self.max_iterations = required_max_iterations
                if not extends_ceiling:
                    headroom_verdict = "static_prepass_iteration_headroom_not_needed"
                elif fresh_headroom:
                    headroom_verdict = "static_prepass_iteration_headroom_granted"
                else:
                    headroom_verdict = (
                        "static_prepass_iteration_headroom_already_granted"
                    )
                self._record_event(
                    {
                        "phase": "session_root_repair_frontier",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "prepass_headroom_signature": prepass_signature,
                        "old_max_iterations": old_max_iterations,
                        "max_iterations": int(self.max_iterations or 0),
                        "verdict": headroom_verdict,
                    }
                )
            if repair_first_yielded_to_competitor:
                # The forced repair owner already yielded once in this scan.
                # The first independently applicable static action is the
                # complete fairness quantum; it cannot yield again and replace
                # the parked conversation owner with a sibling role.
                return action
            should_yield = getattr(action, "should_yield_static_dispatch", None)
            if callable(should_yield) and should_yield(self):
                # Keep the live action as a guaranteed fallback. The remainder
                # of this exact scheduler scan applies every normal budget,
                # deferral, repair-policy, and applicability gate to possible
                # competitors; if none survive, formal work is not stranded.
                yielded_static_action = action
                self._clear_selected_work_item()
                continue
            return action
        if (
            yielded_frontier_action is not None
            and yielded_frontier_work_item is not None
        ):
            if self._set_selected_work_item(
                yielded_frontier_work_item,
                yielded_frontier_action.id,
            ):
                self._activate_selected_graph_ready_work_item(
                    yielded_frontier_work_item
                )
                self.selected_frontier_action_key = yielded_frontier_action_key
                return yielded_frontier_action
            self._clear_selected_work_item()
        if yielded_static_action is not None:
            return yielded_static_action
        if self.repair_policy_narrowing_required:
            self._increment_dossier_metric(
                "mini_session_repair_policy_narrowing_blocked",
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_policy_narrowing",
                    "iteration": self.iteration,
                    "reason": self.repair_policy_narrowing_reason,
                    "selected_work_item": dict(
                        self.repair_policy_narrowing_selected_work_record
                    ),
                    "verdict": "no_narrowing_candidate_blocked",
                }
            )
        self._clear_selected_work_item()
        self._activate_drained_answer_safe_terminal_provider_failure()
        return None

    def _scoped_repair_record_action(
        self,
        record: Dict[str, Any],
        *,
        context: str,
    ) -> Optional[Action]:
        """Return a non-conversation action for a concrete scoped repair record."""

        payload = dict(record or {})
        work_type = str(payload.get("work_type") or "").strip()
        if not work_type or work_type == "root_repair":
            return None
        for action_id in self._frontier_candidate_ids_for_work_item(payload):
            candidate_id = str(action_id or "").strip()
            if not candidate_id or candidate_id.startswith("conversation_turn"):
                continue
            action = self.registered_action(candidate_id)
            if action is None:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if not self._restore_selected_work_record(
                payload,
                action.id,
                context=context,
            ):
                continue
            if self._safe_is_applicable(action, context=context):
                return action
            self._clear_selected_work_item()
        return None

    def _repair_first_model_call_defer(
        self,
        action_id: str,
        *,
        work_item: Any = None,
    ) -> Optional[Dict[str, Any]]:
        """Return the live defer receipt that owns repair selection, if any."""

        clean_action_id = str(action_id or "").strip()
        if not clean_action_id:
            return None
        selected_work = work_item or self.selected_work_item
        if selected_work is not None:
            action_key = self._model_call_deferred_frontier_key_for_work_item(
                selected_work,
                clean_action_id,
            )
            if action_key is not None:
                return dict(
                    self.model_call_deferred_frontier_action_metadata.get(action_key)
                    or {}
                )
        if self._model_call_deferred_static_action_effective(clean_action_id):
            if selected_work is not None and not (
                self._model_call_deferred_static_action_blocks_work_item(
                    clean_action_id,
                    selected_work,
                )
            ):
                return None
            return dict(
                self.model_call_deferred_static_action_metadata.get(clean_action_id)
                or {}
            )
        return None

    def _defer_repair_first_conversation_if_owned(
        self,
        action_id: str,
        *,
        source: str,
        work_item: Any = None,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> bool:
        """Yield repair priority to the scheduler's durable retry ledger."""

        metadata = self._repair_first_model_call_defer(
            action_id,
            work_item=work_item,
        )
        if metadata is None:
            return False
        self._repair_first_deferred_action_ids.add(str(action_id or ""))
        selected_record = dict(
            selected_work_record
            if selected_work_record is not None
            else self.selected_work_item_record
        )
        self._record_event(
            {
                "phase": "session_repair_first",
                "iteration": self.iteration,
                "action_id": str(action_id or ""),
                "source": str(source or ""),
                "llm_failure_kind": str(metadata.get("llm_failure_kind") or ""),
                "infrastructure_retry_attempt": _nonnegative_metadata_int(
                    metadata,
                    "infrastructure_retry_attempt",
                ),
                "infrastructure_retry_ready_at": (
                    self._infrastructure_retry_ready_at(metadata)
                ),
                "selected_work_item": selected_record,
                "verdict": "conversation_turn_deferred",
            }
        )
        self._clear_selected_work_item()
        return True

    def _select_durable_progress_tool_continuation_action(
        self,
    ) -> Optional[Action]:
        """Run an already-advertised closing call before unrelated work."""

        continuation = dict(self.durable_progress_tool_continuation or {})
        if not continuation:
            return None
        identity = str(continuation.get("identity") or "").strip()
        action_id = str(continuation.get("action_id") or "").strip()
        selected_work = dict(
            continuation.get("selected_work_item_record") or {}
        )
        action = self.registered_action(action_id)
        owns_continuation = getattr(
            action,
            "owns_durable_progress_tool_continuation",
            None,
        )
        restore_continuation = getattr(
            action,
            "restore_durable_progress_tool_continuation",
            None,
        )
        current = False
        if identity and action is not None and callable(owns_continuation):
            try:
                current = bool(owns_continuation(identity, self))
            except Exception:
                current = False
        if (
            not current
            and identity
            and callable(restore_continuation)
            and isinstance(continuation.get("replay_payload"), Mapping)
        ):
            try:
                current = bool(
                    restore_continuation(
                        identity,
                        continuation["replay_payload"],
                        self,
                    )
                )
            except Exception:
                current = False
        if not current:
            self.durable_progress_tool_continuation = {}
            self._record_event(
                {
                    "phase": "session_durable_tool_continuation",
                    "iteration": int(self.iteration or 0),
                    "action_id": action_id,
                    "continuation_identity": identity,
                    "verdict": "stale_continuation_rejected",
                }
            )
            return None
        if selected_work:
            state = getattr(
                getattr(self, "conv", None),
                "_provider_call_quantum_state",
                {},
            ) or {}
            continuation_target = str(
                state.get("durable_progress_tool_continuation_target") or ""
            ).strip()
            selected_target = str(
                selected_work.get("exact_target_statement")
                or selected_work.get("target_statement")
                or ""
            ).strip()
            if (
                continuation_target
                and selected_target
                and continuation_target != selected_target
            ):
                self.durable_progress_tool_continuation = {}
                return None
            if not self._restore_selected_work_record(
                selected_work,
                action_id,
                context="durable_tool_continuation",
                metric_key=(
                    "mini_session_retired_durable_tool_continuation_suppressed"
                ),
            ):
                self.durable_progress_tool_continuation = {}
                return None
        budget = self.budgets.get(action_id)
        if budget is not None and budget.exhausted():
            self.durable_progress_tool_continuation = {}
            return None
        if not self._safe_is_applicable(
            action,
            context="durable_tool_continuation",
        ):
            self.durable_progress_tool_continuation = {}
            return None
        self._record_event(
            {
                "phase": "session_durable_tool_continuation",
                "iteration": int(self.iteration or 0),
                "action_id": action_id,
                "continuation_identity": identity,
                "selected_work_item": dict(self.selected_work_item_record),
                "verdict": "owned_continuation_selected",
            }
        )
        return action

    def _repair_first_conversation_action(self) -> Optional[Action]:
        """Prefer the next LLM repair turn before deterministic graph search."""

        ticket = self._active_repair_ticket()
        if ticket is not None:
            fallback_available = self._stagnation_fallback_action_available()
            unscoped_root_ticket = self._repair_ticket_is_unscoped_root_level(ticket)
            if (
                unscoped_root_ticket
                and self._static_action_available_before_root_repair()
            ):
                self._increment_dossier_metric(
                    "mini_session_unscoped_root_repair_tickets_yielded_to_static_prepass",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": ticket.ticket_id,
                        "target_id": ticket.target_id,
                        "route_id": str(getattr(ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(getattr(ticket, "work_type", "") or ""),
                        "verdict": "unscoped_root_repair_ticket_yielded_to_static_prepass",
                    }
                )
                self._exhaust_repair_ticket(
                    ticket,
                    reason="unscoped_root_repair_ticket_yielded_to_static_prepass",
                )
                return None
            if fallback_available and unscoped_root_ticket:
                self._increment_dossier_metric(
                    "mini_session_unscoped_root_repair_tickets_preempted_by_fallback",
                    1,
                )
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_preempted_by_fallback",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": ticket.ticket_id,
                        "target_id": ticket.target_id,
                        "route_id": str(getattr(ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(getattr(ticket, "work_type", "") or ""),
                        "stagnation_counter": int(self.stagnation_counter or 0),
                        "max_stagnation": int(self.max_stagnation or 0),
                        "verdict": "stagnation_fallback_preempted_unscoped_root_repair",
                    }
                )
                self._exhaust_repair_ticket(
                    ticket,
                    reason="stagnation_fallback_preempted_unscoped_root_repair",
                )
                return None
            if fallback_available:
                self._increment_dossier_metric(
                    "mini_session_scoped_repair_tickets_retained_after_fallback",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": ticket.ticket_id,
                        "target_id": ticket.target_id,
                        "route_id": str(getattr(ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(getattr(ticket, "work_type", "") or ""),
                        "stagnation_counter": int(self.stagnation_counter or 0),
                        "max_stagnation": int(self.max_stagnation or 0),
                        "verdict": "scoped_repair_ticket_retained_after_fallback",
                    }
                )
            scoped, scope_status = self._repair_scope_allows_forced_conversation(
                ticket=ticket,
            )
            if not scoped:
                scope_verdict = str(scope_status.get("verdict") or "")
                if scope_verdict != "unscoped_root_repair_yields_to_scoped_frontier":
                    self._suppress_unscoped_root_authoring(
                        "conversation_turn_prove",
                        context="repair_ticket",
                    )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": ticket.ticket_id,
                        "target_id": ticket.target_id,
                        "route_id": str(getattr(ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(getattr(ticket, "work_type", "") or ""),
                        "proof_attempt_id": str(
                            getattr(ticket, "proof_attempt_id", "") or ""
                        ),
                        "scope_status": dict(scope_status),
                        "verdict": "blocked_unscoped_root_authoring",
                    }
                )
                if scope_verdict == "route_replan_requires_materialized_obligation":
                    self._increment_dossier_metric(
                        "mini_session_repair_tickets_unserviceable_route_replan",
                        1,
                    )
                    self._exhaust_repair_ticket(
                        ticket,
                        reason="route_replan_requires_materialized_obligation",
                    )
                    return None
                self._record_unscoped_root_repair_replan(
                    ticket,
                    reason="unscoped_root_authoring_requires_selected_route",
                )
                self._exhaust_repair_ticket(
                    ticket,
                    reason="unscoped_root_authoring_requires_selected_route",
                )
                return None
            for action_id in self._conversation_action_ids_for_repair(
                ticket.source_action_id
            ):
                action = self.registered_action(action_id)
                if action is None:
                    continue
                ticket_record = self._selected_work_record_from_repair_ticket(
                    ticket,
                    action_id=action.id,
                )
                if self._defer_repair_first_conversation_if_owned(
                    action.id,
                    source="repair_ticket",
                    work_item=self._materialize_work_item_from_record(ticket_record),
                    selected_work_record=ticket_record,
                ):
                    return None
                if not self._restore_repair_ticket_selected_work(
                    ticket,
                    action_id=action.id,
                ):
                    self._exhaust_repair_ticket(
                        ticket,
                        reason="terminal_graph_target_repair_ticket_suppressed",
                    )
                    return None
                if self._defer_repair_first_conversation_if_owned(
                    action.id,
                    source="repair_ticket",
                ):
                    return None
                self._grant_repair_ticket_action_budget(action, ticket)
                if self._safe_is_applicable(action, context="repair_ticket"):
                    self._increment_dossier_metric(
                        "mini_session_repair_tickets_selected",
                        1,
                    )
                    self._repair_ticket_selected_id = ticket.ticket_id
                    self._record_event(
                        {
                            "phase": "session_repair_ticket",
                            "iteration": self.iteration,
                            "ticket_id": ticket.ticket_id,
                            "target_id": ticket.target_id,
                            "route_id": str(getattr(ticket, "route_id", "") or ""),
                            "obligation_id": str(
                                getattr(ticket, "obligation_id", "") or ""
                            ),
                            "work_type": str(getattr(ticket, "work_type", "") or ""),
                            "proof_attempt_id": str(
                                getattr(ticket, "proof_attempt_id", "") or ""
                            ),
                            "action_id": action.id,
                            "attempts_used": int(ticket.attempts_used or 0),
                            "next_attempt_number": int(ticket.attempts_used or 0) + 1,
                            "max_attempts": int(ticket.max_attempts or 0),
                            "verdict": "conversation_turn_forced",
                        }
                    )
                    return action
            self._increment_dossier_metric(
                "mini_session_repair_ticket_blocked_no_action",
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": ticket.ticket_id,
                    "target_id": ticket.target_id,
                    "route_id": str(getattr(ticket, "route_id", "") or ""),
                    "obligation_id": str(getattr(ticket, "obligation_id", "") or ""),
                    "work_type": str(getattr(ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(ticket, "proof_attempt_id", "") or ""
                    ),
                    "verdict": "blocked_no_conversation_action",
                }
            )
            self._exhaust_repair_ticket(
                ticket,
                reason="no_conversation_action_available",
            )
            return None

        local_remaining = int(self.local_repair_quota_remaining or 0)
        until = int(getattr(self, "repair_first_until_conversation_turn", 0) or 0)
        if local_remaining <= 0 and until <= 0:
            return None
        local_quota_record = dict(self.local_repair_quota_selected_work_record or {})
        if (
            (local_remaining > 0 or until > 0)
            and self._work_record_is_unscoped_root_level(local_quota_record)
            and self._stagnation_fallback_action_available()
        ):
            self._increment_dossier_metric(
                "mini_session_local_root_repair_quota_preempted_by_fallback",
                1,
            )
            self._record_event(
                {
                    "phase": "session_local_repair_quota",
                    "iteration": self.iteration,
                    "reason": str(self.local_repair_quota_reason or ""),
                    "failure_signature": str(
                        self.local_repair_quota_failure_signature or ""
                    ),
                    "quota_remaining": int(self.local_repair_quota_remaining or 0),
                    "stagnation_counter": int(self.stagnation_counter or 0),
                    "max_stagnation": int(self.max_stagnation or 0),
                    "selected_work_item": dict(local_quota_record),
                    "verdict": "stagnation_fallback_preempted_local_root_repair",
                }
            )
            self.local_repair_quota_remaining = 0
            self.repair_first_until_conversation_turn = 0
            self.repair_first_reason = ""
            self._clear_policy_repair_redirect_selected_work()
            self._clear_selected_work_item()
            return None
        if (
            local_remaining <= 0
            and int(getattr(self, "_conversation_turn_count", 0) or 0) >= until
        ):
            self.repair_first_until_conversation_turn = 0
            self.repair_first_reason = ""
            self._clear_policy_repair_redirect_selected_work()
            return None
        if local_remaining > 0 and local_quota_record:
            # The authoritative graph update can terminalize the exact target
            # after the action arms this quota but before the scheduler gets
            # its next turn.  Reassert the already-bounded repair authority at
            # selection time so restoration cannot silently fall back to the
            # root merely because those two state transitions were ordered
            # this way.
            repair_identity = str(
                self.local_repair_quota_failure_signature
                or local_quota_record.get("failure_signature")
                or ""
            ).strip()
            if (
                bool(local_quota_record.get("local_repair_quota_context"))
                and repair_identity
            ):
                self._ensure_graph_target_repair_pending_authority(
                    local_quota_record,
                    repair_identity=repair_identity,
                    context="local_repair_quota_select",
                )
            scoped_action = self._scoped_repair_record_action(
                local_quota_record,
                context="local_repair_quota_scoped_action",
            )
            if scoped_action is not None:
                self.local_repair_quota_remaining = 0
                self.repair_first_until_conversation_turn = 0
                self.repair_first_reason = ""
                self._clear_policy_repair_redirect_selected_work()
                self._increment_dossier_metric(
                    "mini_session_local_repair_quota_scoped_action_selected",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_local_repair_quota",
                        "iteration": self.iteration,
                        "action_id": scoped_action.id,
                        "reason": str(self.local_repair_quota_reason or ""),
                        "failure_signature": str(
                            self.local_repair_quota_failure_signature or ""
                        ),
                        "selected_work_item": dict(self.selected_work_item_record),
                        "verdict": "scoped_action_selected",
                    }
                )
                return scoped_action
        saved_policy_redirect_action_id = str(
            self.policy_repair_redirect_selected_action_id or ""
        ).strip()
        for action_id in self._conversation_action_ids_for_repair(
            saved_policy_redirect_action_id
        ):
            action = self.registered_action(action_id)
            if action is None:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            policy_redirect_present = (
                self.policy_repair_redirect_selected_work_item is not None
            )
            policy_redirect_record = dict(self.policy_repair_redirect_selected_record)
            deferred_work_item = self.policy_repair_redirect_selected_work_item
            deferred_work_record = policy_redirect_record
            if deferred_work_item is None and local_remaining > 0:
                deferred_work_record = dict(
                    self.local_repair_quota_selected_work_record
                )
                if deferred_work_record:
                    deferred_work_item = self._materialize_work_item_from_record(
                        deferred_work_record
                    )
            if deferred_work_item is not None and (
                self._defer_repair_first_conversation_if_owned(
                    action.id,
                    source="repair_first",
                    work_item=deferred_work_item,
                    selected_work_record=deferred_work_record,
                )
            ):
                return None
            restored_policy_redirect_work = (
                self._restore_policy_repair_redirect_selected_work(action.id)
            )
            restored_local_quota_work = False
            local_quota_restore_required = (
                not restored_policy_redirect_work
                and local_remaining > 0
                and bool(self.local_repair_quota_selected_work_record)
            )
            if (
                not restored_policy_redirect_work
                and local_remaining > 0
                and self.local_repair_quota_selected_work_record
            ):
                restored_local_quota_work = self._restore_selected_work_record(
                    self.local_repair_quota_selected_work_record,
                    action.id,
                    context="local_repair_quota",
                    metric_key=(
                        "mini_session_retired_graph_target_local_repair_suppressed"
                    ),
                )
            if policy_redirect_present and not restored_policy_redirect_work:
                redirect_remains_live = (
                    self.policy_repair_redirect_selected_work_item is not None
                )
                self._record_event(
                    {
                        "phase": "session_repair_first",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "until_conversation_turn": until,
                        "reason": str(getattr(self, "repair_first_reason", "") or ""),
                        "selected_work_item": policy_redirect_record,
                        "verdict": (
                            "policy_redirect_selected_work_role_incompatible"
                            if redirect_remains_live
                            else "policy_redirect_selected_work_retired"
                        ),
                    }
                )
                if redirect_remains_live:
                    # Preserve the exact work authority while trying the next
                    # compatible conversation action. The captured action is
                    # a preference, not a capability.
                    continue
                # The authoritative graph packet was retired or promoted.
                # End this repair-first lease instead of falling through to a
                # different conversation role with no selected-work scope.
                self.repair_first_until_conversation_turn = 0
                self.repair_first_reason = ""
                self.local_repair_quota_remaining = 0
                self.local_repair_quota_reason = ""
                self.local_repair_quota_failure_signature = ""
                self.local_repair_quota_selected_work_record = {}
                self._clear_selected_work_item()
                self._release_abandoned_local_repair_graph_authority(
                    local_quota_record,
                    reason="policy_redirect_selected_work_retired",
                )
                self._repair_first_scheduler_blocked = True
                return None
            if local_quota_restore_required and not restored_local_quota_work:
                self._record_event(
                    {
                        "phase": "session_local_repair_quota",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "reason": str(self.local_repair_quota_reason or ""),
                        "failure_signature": str(
                            self.local_repair_quota_failure_signature or ""
                        ),
                        "selected_work_item": dict(
                            self.local_repair_quota_selected_work_record
                        ),
                        "verdict": "selected_work_restore_failed",
                    }
                )
                self.local_repair_quota_remaining = 0
                self.repair_first_until_conversation_turn = 0
                self.repair_first_reason = ""
                self._clear_policy_repair_redirect_selected_work()
                self._clear_selected_work_item()
                self._release_abandoned_local_repair_graph_authority(
                    local_quota_record,
                    reason="selected_work_restore_failed",
                )
                self._repair_first_scheduler_blocked = True
                return None
            if not restored_policy_redirect_work and not restored_local_quota_work:
                self._clear_selected_work_item()
            if self._defer_repair_first_conversation_if_owned(
                action.id,
                source="repair_first",
            ):
                return None
            scoped, scope_status = self._repair_scope_allows_forced_conversation()
            if not scoped:
                if (
                    str(scope_status.get("verdict") or "")
                    != "unscoped_root_repair_yields_to_scoped_frontier"
                ):
                    self._suppress_unscoped_root_authoring(
                        action.id,
                        context="repair_first",
                    )
                self._record_event(
                    {
                        "phase": "session_repair_first",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "until_conversation_turn": until,
                        "conversation_turn_count": int(
                            getattr(self, "_conversation_turn_count", 0) or 0
                        ),
                        "reason": str(getattr(self, "repair_first_reason", "") or ""),
                        "scope_status": dict(scope_status),
                        "local_repair_quota_remaining": int(
                            self.local_repair_quota_remaining or 0
                        ),
                        "verdict": "blocked_unscoped_root_authoring",
                    }
                )
                self.local_repair_quota_remaining = 0
                self.repair_first_until_conversation_turn = 0
                self.repair_first_reason = ""
                self._clear_policy_repair_redirect_selected_work()
                self._clear_selected_work_item()
                self._release_abandoned_local_repair_graph_authority(
                    local_quota_record,
                    reason="blocked_unscoped_root_authoring",
                )
                return None
            if self._safe_is_applicable(action, context="repair_first"):
                local_forced = local_remaining > 0
                if local_forced:
                    self.local_repair_quota_remaining = max(
                        0,
                        int(self.local_repair_quota_remaining or 0) - 1,
                    )
                    self.local_repair_quota_used = (
                        int(self.local_repair_quota_used or 0) + 1
                    )
                    signature_key = (
                        str(
                            self.local_repair_quota_failure_signature
                            or self.local_repair_quota_reason
                            or "unknown"
                        ).strip()
                        or "unknown"
                    )
                    used_by_signature = getattr(
                        self,
                        "local_repair_quota_used_by_signature",
                        None,
                    )
                    if not isinstance(used_by_signature, dict):
                        used_by_signature = {}
                        self.local_repair_quota_used_by_signature = used_by_signature
                    used_by_signature[signature_key] = (
                        int(used_by_signature.get(signature_key, 0) or 0) + 1
                    )
                    self._increment_dossier_metric(
                        "mini_session_local_repair_turns_forced",
                        1,
                    )
                    self._record_event(
                        {
                            "phase": "session_local_repair_turn",
                            "iteration": self.iteration,
                            "action_id": action.id,
                            "quota_remaining": int(
                                self.local_repair_quota_remaining or 0
                            ),
                            "quota_used": int(self.local_repair_quota_used or 0),
                            "quota_reason": str(self.local_repair_quota_reason or ""),
                            "failure_signature": str(
                                self.local_repair_quota_failure_signature or ""
                            ),
                            "failure_signature_key": signature_key,
                            "quota_used_for_signature": int(
                                used_by_signature.get(signature_key, 0) or 0
                            ),
                            "verdict": "conversation_turn_forced",
                        }
                    )
                self._repair_first_selected_local_forced = local_forced
                self._repair_first_selected_signature_key = (
                    signature_key if local_forced else ""
                )
                self._record_event(
                    {
                        "phase": "session_repair_first",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "until_conversation_turn": until,
                        "conversation_turn_count": int(
                            getattr(self, "_conversation_turn_count", 0) or 0
                        ),
                        "reason": (
                            str(self.local_repair_quota_reason or "")
                            if local_forced
                            else str(getattr(self, "repair_first_reason", "") or "")
                        ),
                        "local_repair_quota_forced": local_forced,
                        "restored_policy_redirect_work": restored_policy_redirect_work,
                        "restored_local_quota_work": restored_local_quota_work,
                        "selected_work_item": dict(self.selected_work_item_record),
                        "local_repair_quota_remaining": int(
                            self.local_repair_quota_remaining or 0
                        ),
                        "verdict": "conversation_turn_forced",
                    }
                )
                return action
        self._record_event(
            {
                "phase": "session_repair_first",
                "iteration": self.iteration,
                "until_conversation_turn": until,
                "conversation_turn_count": int(
                    getattr(self, "_conversation_turn_count", 0) or 0
                ),
                "reason": str(getattr(self, "repair_first_reason", "") or ""),
                "local_repair_quota_remaining": int(
                    self.local_repair_quota_remaining or 0
                ),
                "verdict": "no_conversation_action_available",
            }
        )
        self.local_repair_quota_remaining = 0
        self.repair_first_until_conversation_turn = 0
        self.repair_first_reason = ""
        self._clear_policy_repair_redirect_selected_work()
        self._clear_selected_work_item()
        self._release_abandoned_local_repair_graph_authority(
            local_quota_record,
            reason="no_conversation_action_available",
        )
        return None

    def _root_repair_frontier_conversation_action(self) -> Optional[Action]:
        """Bind root_repair frontier work to an LLM root conversation turn."""

        if self.proof_state is None:
            return None
        if self._suppress_unscoped_root_authoring(
            "conversation_turn_prove",
            context="root_repair_frontier",
        ):
            return None
        nodes = getattr(self.proof_state, "nodes", None)
        if not isinstance(nodes, dict):
            return None
        frontier_items = self._work_frontier_items(offset=0)
        meaningful_non_root_work = any(
            str(self._work_item_field(item, "work_type", "") or "").strip()
            != "root_repair"
            and bool(self._frontier_candidate_ids_for_work_item(item))
            for item in frontier_items
        )
        if meaningful_non_root_work:
            return None
        self._root_repair_frontier_allowed = True
        for work_item in frontier_items:
            work_type = str(
                self._work_item_field(work_item, "work_type", "") or ""
            ).strip()
            if work_type != "root_repair":
                continue
            work_key = self._frontier_work_key(work_item)
            if (
                work_key in self.skipped_frontier_work_keys
                or work_key in self.consumed_frontier_work_keys
            ):
                continue
            action = self._map_work_item_to_action(work_item)
            if action is None:
                continue
            budget = self.budgets.get(action.id)
            if budget is not None and budget.exhausted():
                continue
            if not self._set_selected_work_item(work_item, action.id):
                work_key = self._frontier_work_key(work_item)
                if any(work_key):
                    self.skipped_frontier_work_keys.add(work_key)
                    self.skipped_frontier_action_keys.add(
                        self._frontier_action_key(work_item, action.id)
                    )
                continue
            self._activate_selected_graph_ready_work_item(work_item)
            if self._safe_is_applicable(action, context="root_repair_frontier"):
                self._record_event(
                    {
                        "phase": "session_root_repair_frontier",
                        "iteration": self.iteration,
                        "action_id": action.id,
                        "selected_work_item": dict(self.selected_work_item_record),
                        "verdict": "conversation_turn_selected",
                    }
                )
                return action
            self._clear_selected_work_item()
        return None

    def registered_action(self, action_id: str) -> Optional[Action]:
        """Return a registered action by id, ignoring exhausted budgets."""

        wanted = str(action_id or "")
        for action in self.actions:
            if action.id == wanted:
                return action
        return None

    def _is_graph_recursive_action(self, action: Any) -> bool:
        """Whether an action owns the shared graph-recursive pass pool."""

        if action is None:
            return False
        if isinstance(action, str):
            if action == "graph_recursive_decompose":
                return True
            action = self.registered_action(action)
            if action is None:
                return False
        return bool(
            str(getattr(action, "id", "") or "") == "graph_recursive_decompose"
            or str(getattr(action, "FRONTIER_ACTION_FAMILY", "") or "")
            == "graph_recursive_decompose"
        )

    def action_available(self, action_id: str) -> bool:
        """Whether an action is registered and its budget can still run."""

        action = self.registered_action(action_id)
        if action is None:
            return False
        budget = self.budgets.get(action.id)
        return not (budget is not None and budget.exhausted())

    def _next_scheduler_eligibility_time(self) -> float:
        """Earliest durable action wake time, or zero when none is scheduled."""

        now = time.time()
        ready_times: List[float] = []
        if self._shared_lean_capability_occupied():
            try:
                lean_waiting_frontier = any(
                    self._work_item_waits_for_shared_lean(item)
                    and self._frontier_work_key(item)
                    not in self.skipped_frontier_work_keys
                    for item in self._all_work_frontier_items(mutate=False)
                )
            except Exception:
                lean_waiting_frontier = False
            if (
                lean_waiting_frontier
                or self._has_waiting_lean_tool_infrastructure_retry()
            ):
                # Poll capability ownership without consuming or terminalizing
                # the mathematical frontier.  The owner itself controls when
                # the exact child work becomes executable again.
                ready_times.append(now + 1.0)
        for action in self.actions:
            action_id = str(getattr(action, "id", "") or "")
            if not action_id or not self.action_dispatchable(
                action_id,
                context="scheduler_wake",
            ):
                continue
            getter = getattr(action, "next_eligible_at", None)
            if not callable(getter):
                continue
            try:
                ready_at = float(getter(self) or 0.0)
            except Exception:
                _LOGGER.debug(
                    "Action %r eligibility-time probe failed",
                    action_id,
                    exc_info=True,
                )
                continue
            if ready_at > now:
                ready_times.append(ready_at)
        for action_id in self.model_call_deferred_static_action_ids:
            metadata = dict(
                self.model_call_deferred_static_action_metadata.get(action_id) or {}
            )
            retryable, _ = self._model_call_deferred_static_action_retryable(
                action_id
            )
            if (
                not retryable
                or not self.action_available(action_id)
                or not self._model_call_deferred_static_retry_entitled(
                    action_id,
                    metadata,
                )
            ):
                continue
            ready_at = self._provider_defer_ready_at(metadata)
            if self._persistent_infrastructure_defer(metadata):
                ready_at = max(
                    ready_at,
                    self._infrastructure_retry_ready_at(metadata),
                )
            if ready_at > now:
                ready_times.append(ready_at)
        for action_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
            )
            if not self._model_call_deferred_frontier_receipt_compatible(
                action_key,
                metadata,
            ):
                continue
            retryable, _ = self._model_call_deferred_frontier_action_retryable(
                action_key
            )
            action_id = str(metadata.get("action_id") or "").strip()
            if not action_id and action_key:
                action_id = str(action_key[-1] or "").strip()
            if (
                not retryable
                or not action_id
                or not self.action_available(action_id)
                or not self._model_call_deferred_frontier_retry_entitled(
                    action_key,
                    metadata,
                )
            ):
                continue
            ready_at = self._provider_defer_ready_at(metadata)
            if self._persistent_infrastructure_defer(metadata):
                ready_at = max(
                    ready_at,
                    self._infrastructure_retry_ready_at(metadata),
                )
            if ready_at > now:
                ready_times.append(ready_at)
        return min(ready_times, default=0.0)

    def _has_funded_persistent_infrastructure_retry(self) -> bool:
        """Whether a durable infrastructure wake still owns action budget."""

        for action_id in self.model_call_deferred_static_action_ids:
            metadata = dict(
                self.model_call_deferred_static_action_metadata.get(action_id) or {}
            )
            if self._persistent_infrastructure_defer(
                metadata
            ) and self.action_available(
                str(action_id or "")
            ) and self._model_call_deferred_static_receipt_compatible(
                str(action_id or ""),
                metadata,
            ):
                return True
        for action_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
            )
            if not self._model_call_deferred_frontier_receipt_compatible(
                action_key,
                metadata,
            ):
                continue
            action_id = str(metadata.get("action_id") or "").strip()
            if not action_id and action_key:
                action_id = str(action_key[-1] or "").strip()
            if (
                action_id
                and self._persistent_infrastructure_defer(metadata)
                and self.action_available(action_id)
            ):
                return True
        return False

    def _has_funded_retryable_model_call_defer(self) -> bool:
        """Whether an exact deferred model call still owns a bounded retry."""

        for action_id in self.model_call_deferred_static_action_ids:
            clean_action_id = str(action_id or "").strip()
            retryable, metadata = (
                self._model_call_deferred_static_action_retryable(
                    clean_action_id
                )
            )
            if (
                retryable
                and self.action_available(clean_action_id)
                and self._model_call_deferred_static_retry_entitled(
                    clean_action_id,
                    metadata,
                )
            ):
                return True
        for action_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(
                    action_key
                )
                or {}
            )
            if not self._model_call_deferred_frontier_receipt_compatible(
                action_key,
                metadata,
            ):
                continue
            action_id = str(metadata.get("action_id") or "").strip()
            if not action_id and action_key:
                action_id = str(action_key[-1] or "").strip()
            retryable, metadata = (
                self._model_call_deferred_frontier_action_retryable(
                    action_key
                )
            )
            if (
                retryable
                and action_id
                and self.action_available(action_id)
                and self._model_call_deferred_frontier_retry_entitled(
                    action_key,
                    metadata,
                )
            ):
                return True
        return False

    def action_dispatchable(
        self, action_id: str, *, context: str = "scheduler"
    ) -> bool:
        """Whether the scheduler can actually dispatch this action now.

        ``action_available`` intentionally answers the narrower registration
        and budget question. Scheduler-local policy, such as local
        micro-theory retrieval suppression, can still make an action
        non-dispatchable. This side-effect-free predicate lets action
        applicability gates reason about real scheduler competitors without
        emitting skip metrics/events during ``is_applicable()`` probes.
        """

        del context
        action_key = str(action_id or "").strip()
        if not self.action_available(action_key):
            return False
        return not self._local_micro_theory_action_would_skip(action_key)

    def _synchronize_statement_environment_for_dispatch(self) -> None:
        """Advance the dossier and future proof-state targets together.

        Existing proof-state nodes retain the environment in which they were
        created.  Only the state's creation cursor advances, so residuals
        emitted after a preamble extension cannot be mislabeled with the old
        environment or merged with an old same-surface target.
        """

        if self.dossier is None or self.conv is None:
            return
        environment_hash = text_hash(str(getattr(self.conv, "lean_preamble", "") or ""))
        previous_environment_hash = str(
            getattr(self.dossier, "current_lean_environment_hash", "") or ""
        ).strip()
        recorder = getattr(self.dossier, "record_lean_environment", None)
        if environment_hash != previous_environment_hash and callable(recorder):
            preamble_text = str(getattr(self.conv, "lean_preamble", "") or "")
            try:
                recorder(
                    environment_hash,
                    extends_environment_hash=previous_environment_hash,
                    environment_source_text=preamble_text,
                )
            except TypeError:
                # Same duck-typing allowance as below: a lightweight dossier
                # may predate the content-verified ancestry signature.
                recorder(
                    environment_hash,
                    extends_environment_hash=previous_environment_hash,
                )
        else:
            # Lightweight test/embedding dossiers may not implement the full
            # ancestry ledger.  Keep their observable current environment in
            # sync without assuming the method exists.
            self.dossier.current_lean_environment_hash = environment_hash
        if self.proof_state is not None:
            self.proof_state.statement_environment_hash = environment_hash

    async def run(self) -> Tuple[bool, Optional[str]]:
        planner_broker = self.planner_job_broker()
        if planner_broker is not None:
            planner_broker.bind_session_owner(self, asyncio.current_task())
        try:
            return await self._run_scheduler()
        finally:
            # Nested MiniSessions share their parent's broker. Their return is
            # only a scheduler quantum boundary; the final live session owner
            # performs cleanup, including on startup and cancellation exits.
            if planner_broker is not None:
                await planner_broker.release_session_owner(self)

    async def _run_scheduler(self) -> Tuple[bool, Optional[str]]:
        planner_broker = self.planner_job_broker()
        self._retire_terminal_ready_planner_jobs()
        if self._operator_cancelled_dispatch_reuse_fenced:
            self._record_event(
                {
                    "phase": "session_action_mutation_transaction",
                    "verdict": "operator_cancelled_dispatch_reuse_rejected",
                    "reason": str(self._operator_cancelled_dispatch_reuse_reason or ""),
                }
            )
            return False, None
        if self._dispatch_generation_recycle_required:
            self._resume_dispatch_generation()
        if self._dispatch_worker_poisoned:
            self._request_dispatch_generation_recycle(
                self._dispatch_worker_poison_reason or "legacy_dispatch_worker_poisoned"
            )
            self._resume_dispatch_generation()
        self.last_failure_reason = ""
        terminal_deadline_scope_ids: set[str] = set()
        # The governor covers the complete MiniSession lifetime, not
        # only the action loop. Start a fresh process-local tick before
        # helper seeding.
        self._run_governor_last_tick_monotonic = time.monotonic()
        self._pre_select_snapshot_required = True
        if self._run_governor_exhausted():
            return False, None
        try:
            await self._await_startup_under_run_governor(
                self._seed_same_problem_verified_helpers(),
                operation_label="mini_session_startup_helper_seeding",
            )
        except asyncio.TimeoutError:
            self._run_governor_exhausted()
            return False, None
        if self._dispatch_worker_poisoned:
            self._request_dispatch_generation_recycle(
                self._dispatch_worker_poison_reason or "legacy_dispatch_worker_poisoned"
            )
            self._resume_dispatch_generation()
        while not self._run_governor_exhausted() and (
            self.should_continue()
            or (
                not self._planner_terminal_authority_reason()
                and (
                    self._owned_planner_job_status("pending")
                    or self._owned_planner_job_status("ready")
                )
            )
            or self._owned_missing_planner_recovery_action() is not None
        ):
            self._retire_terminal_ready_planner_jobs()
            if self._planner_terminal_authority_reason():
                break
            normal_continuation = self.should_continue()
            ready_planner_action = self._owned_planner_job_action("ready")
            admitted_ready_planner_action = (
                None
                if self._proof_root_waiting_for_finalization()
                else ready_planner_action
            )
            missing_planner_action = self._owned_missing_planner_recovery_action()
            dispatchable_missing_planner_action = (
                missing_planner_action
                if missing_planner_action is not None
                and self._missing_planner_recovery_dispatch_ready(
                    missing_planner_action
                )
                else None
            )
            pending_planner_owned = self._owned_planner_job_status("pending")
            if (
                not normal_continuation
                and ready_planner_action is None
                and pending_planner_owned
                and planner_broker is not None
            ):
                self._record_event(
                    {
                        "phase": "session_planner_job",
                        "iteration": int(self.iteration or 0),
                        "verdict": "waiting_for_terminal_boundary_planner_job",
                    }
                )
                await self._wait_for_owned_planner_change(planner_broker)
                self._pre_select_snapshot_required = False
                continue
            if self._dispatch_generation_recycle_required:
                self._resume_dispatch_generation()
                continue
            if self._pending_isolated_dispatch_tails:
                live_tails = self._reap_isolated_dispatch_tails()
                if live_tails:
                    self._release_isolated_dispatch_tail_barrier(
                        reason="isolated_tail_does_not_block_dispatch",
                    )
                else:
                    self._pending_isolated_dispatch_tails = set()
                    self._dispatch_generation_late_rollback_snapshot = {}
            self._record_event(
                {
                    "phase": "session_iteration",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "applicable_action_count": self._applicable_action_count(),
                    "verdict": "iteration_advanced",
                }
            )
            if self._pre_select_snapshot_required:
                self._record_pre_select_snapshot()
            action_dispatch_id = ""
            usage_context: Dict[str, Any] = {}
            # A ready paid receipt is the least stale authority available.
            # Consume it before unrelated work; beyond ordinary continuation
            # it is the only action admitted for this one commit quantum.
            suppressed_ready_action_id = (
                str(getattr(ready_planner_action, "id", "") or "").strip()
                if admitted_ready_planner_action is None
                and ready_planner_action is not None
                else ""
            )
            if suppressed_ready_action_id:
                self._scheduler_transient_suppressed_action_ids.add(
                    suppressed_ready_action_id
                )
            try:
                action = (
                    admitted_ready_planner_action
                    or dispatchable_missing_planner_action
                    or (self.select_next_action() if normal_continuation else None)
                )
            finally:
                if suppressed_ready_action_id:
                    self._scheduler_transient_suppressed_action_ids.discard(
                        suppressed_ready_action_id
                    )
            if action is None and ready_planner_action is not None:
                # Canonical root closure gets the first selection opportunity,
                # but a solved proof-state root does not itself constitute
                # durable finalization. If no finalizer can actually dispatch,
                # consume the exact paid receipt instead of dropping it during
                # terminal broker cleanup.
                action = ready_planner_action
                self._record_event(
                    {
                        "phase": "session_planner_job",
                        "iteration": int(self.iteration or 0),
                        "action_id": str(
                            getattr(ready_planner_action, "id", "") or ""
                        ),
                        "verdict": (
                            "ready_planner_admitted_after_finalizer_unavailable"
                        ),
                    }
                )
            # Recheck at the publication boundary. A canonical finalizer or
            # another scheduler action may have established terminal authority
            # since loop admission; a late raw receipt must not outrank it.
            if (
                action is ready_planner_action
                and ready_planner_action is not None
                and self._planner_terminal_authority_reason()
            ):
                self._retire_terminal_ready_planner_jobs()
                continue
            if action is not None and (
                action is ready_planner_action
                or action is dispatchable_missing_planner_action
            ):
                # Broker-owned planner work is an unscoped continuation of
                # its exact job receipt. It bypasses ordinary frontier
                # selection, so any live selected item belongs to the action
                # that ran while the planner was pending and must not leak
                # into the resumed planner's outcome/defer bookkeeping.
                self._clear_selected_work_item()
            if action is not None:
                self._pre_select_snapshot_required = True
                # A later independent action owns the live state. Drop the
                # recycle snapshot so terminal drain cannot undo that work
                # when a detached tail finally settles.
                self._dispatch_generation_late_rollback_snapshot = {}
            if action is None:
                # Empty selects still mutate snapshotted scheduler sets.
                # Refresh the in-memory recycle cutpoint without emitting
                # the 17 KB turns.jsonl payload.
                try:
                    self._capture_pre_select_snapshot()
                except Exception:
                    pass
                if self._owned_planner_job_status("pending"):
                    self._record_event(
                        {
                            "phase": "session_planner_job",
                            "iteration": int(self.iteration or 0),
                            "verdict": "waiting_for_pending_planner_job",
                        }
                    )
                    await self._wait_for_owned_planner_change(planner_broker)
                    self._pre_select_snapshot_required = False
                    continue
                ready_at = self._next_scheduler_eligibility_time()
                if ready_at > time.time():
                    delay = max(0.0, ready_at - time.time())
                    governor_remaining = self._run_governor_remaining_s()
                    if governor_remaining is not None:
                        delay = min(delay, governor_remaining)
                    self.max_iterations = max(
                        int(self.max_iterations or 0),
                        int(self.iteration or 0) + 1,
                    )
                    self._record_event(
                        {
                            "phase": "session_scheduled_action_wait",
                            "iteration": int(self.iteration or 0),
                            "ready_at": ready_at,
                            "delay_s": delay,
                            "verdict": "waiting_for_durable_retry_eligibility",
                        }
                    )
                    await asyncio.sleep(delay)
                    self._pre_select_snapshot_required = False
                    continue
                if self._dispatch_generation_deferred_action_ids:
                    deferred_action_ids = sorted(
                        self._dispatch_generation_deferred_action_ids
                    )
                    # A generation incident must not hot-spin, but it also
                    # cannot permanently suppress the only viable lane.
                    now = time.monotonic()
                    delay = max(
                        0.0,
                        min(
                            float(
                                self._dispatch_generation_action_ready_monotonic.get(
                                    action_id,
                                    now + 0.05,
                                )
                            )
                            for action_id in deferred_action_ids
                        )
                        - now,
                    )
                    governor_remaining = self._run_governor_remaining_s()
                    if governor_remaining is not None:
                        delay = min(delay, max(0.0, governor_remaining))
                    self._record_event(
                        {
                            "phase": "session_dispatch_generation_backoff",
                            "deferred_action_ids": deferred_action_ids,
                            "delay_s": delay,
                            "verdict": "generation_rotation_wait",
                        }
                    )
                    if delay > 0.0:
                        await asyncio.sleep(delay)
                        self._pre_select_snapshot_required = False
                        continue
                    released_action_ids = (
                        self._release_ready_dispatch_generation_deferrals()
                    )
                    if released_action_ids:
                        self._record_event(
                            {
                                "phase": "session_dispatch_generation_backoff",
                                "released_action_ids": released_action_ids,
                                "verdict": "generation_rotation_ready",
                            }
                        )
                        self._pre_select_snapshot_required = True
                        continue
                    # Clock skew or a stale id: never busy-spin.
                    await asyncio.sleep(0.05)
                    self._pre_select_snapshot_required = False
                    continue
                if self._recover_from_no_applicable_action():
                    # Recovery mutates budgets, deferrals, and suppressors.
                    # The next select may dispatch; recycle restores
                    # ``_latest_pre_select_snapshot``, so re-arm it.
                    self._pre_select_snapshot_required = True
                    continue
                break
            if (
                self.selected_work_item_record
                and str(self.selected_work_item_action_id or "").strip()
                == str(action.id or "").strip()
                and self._selected_work_record_dispatch_blocked(
                    dict(self.selected_work_item_record),
                    str(action.id or ""),
                    context="pre_action_dispatch",
                )
            ):
                # This is the final saved-selection barrier. Frontier
                # projection and restore already apply the same read-only
                # predicate; rechecking immediately before dispatch closes a
                # race with graph reconciliation.
                self._clear_selected_work_item()
                continue
            dispatched_id = str(action.id or "")
            # Conversation exemptions must outlive the first committed turn.
            # Discarding them here re-armed leftover skipped root_repair /
            # route_replan suppression, so nested prove died after one
            # unsolved dispatch (Putnam 1977 A2 nested subgoal).
            if not (
                dispatched_id.startswith("conversation_turn")
                or self._is_unscoped_root_authoring_action(dispatched_id)
            ):
                self._dispatch_generation_release_suppressed_action_ids.discard(
                    dispatched_id
                )
            if not action_dispatch_id:
                action_dispatch_id = uuid.uuid4().hex
            terminal_deadline_scope_ids.add(action_dispatch_id)
            self._inflight_action_dispatch_id = action_dispatch_id
            usage_context = self._action_usage_context(
                action_id=action.id,
                action_dispatch_id=action_dispatch_id,
            )
            self._record_event(
                {
                    "phase": "session_action_selected",
                    "iteration": self.iteration,
                    "action_id": action.id,
                    "action_dispatch_id": action_dispatch_id,
                    **usage_context,
                    "selected_work_item": dict(self.selected_work_item_record),
                    "verdict": "action_selected",
                }
            )
            # A real action is dispatching: cost-governed continuations are
            # doing their job, so clear the no-action livelock counter.
            self.cost_governed_continuations_without_action = 0
            self.last_cost_governed_continuation_progress_signature = ""
            self._synchronize_statement_environment_for_dispatch()
            self._begin_action_progress_observation(action_id=action.id)
            # Actions run directly against live in-memory state. Only the two
            # terminal-authority scalars are retained for failed dispatches;
            # no serializability or restore admission can block mathematics.
            dispatch_snapshot = {
                "session_state": {
                    "root_finalized": bool(self.root_finalized),
                    "final_proof": self.final_proof,
                }
            }
            dispatch_stage = self._prepare_live_dispatch_stage(dispatch_snapshot)
            dispatch_session = dispatch_stage["session"]
            dispatch_action = dispatch_stage["actions"].get(str(action.id))
            if dispatch_action is None:
                raise RuntimeError(
                    f"live dispatch registry lacks selected action: {action.id}"
                )
            dispatch_stage_rollback_snapshot = dispatch_stage["rollback_snapshot"]
            dispatch_stage_authority_restored = False

            def restore_dispatch_stage_authority_once() -> bool:
                nonlocal dispatch_stage_authority_restored
                if dispatch_stage_authority_restored:
                    return False
                dispatch_stage_authority_restored = True
                dispatch_session._restore_failed_dispatch_authority(
                    snapshot=dispatch_stage_rollback_snapshot,
                )
                return True

            started = time.monotonic()
            dispatch_exception: Optional[BaseException] = None
            task_tracker = _OperationChildTaskTracker()
            session_provider_exposure_tracker = (
                dispatch_session._inflight_provider_exposure_tracker
                or ProviderDispatchExposureTracker()
            )
            inflight_provider_exposure_tracker = ProviderDispatchExposureTracker()
            inflight_provider_exposure_tracker.link_parent(
                session_provider_exposure_tracker
            )
            dispatch_session._inflight_provider_exposure_tracker = (
                session_provider_exposure_tracker
            )
            try:
                with (
                    bind_llm_usage_context(usage_context),
                    bind_provider_dispatch_exposure_tracker(
                        inflight_provider_exposure_tracker
                    ),
                    bind_deadline_operation_scope(
                        action_dispatch_id,
                        abort_on_detach=True,
                    ),
                ):
                    governor_remaining = self._run_governor_remaining_s()
                    operation_task = task_tracker.create_primary_task(
                        dispatch_action.run(dispatch_session),
                    )
                    outcome = await await_with_strict_deadline(
                        operation_task,
                        timeout_s=(
                            None
                            if governor_remaining is None
                            else max(0.001, governor_remaining)
                        ),
                        operation_label=(f"mini_session_run_governor_{action.id}"),
                    )
            except asyncio.CancelledError as cancellation:
                # Settle provider exposure before propagating operator
                # cancellation so late child work cannot publish mutation.
                try:
                    try:
                        cancellation_detachments = (
                            await self._settle_dispatch_scope_before_commit(
                                scope_id=action_dispatch_id,
                                snapshot=dispatch_stage_rollback_snapshot,
                                task_tracker=task_tracker,
                                allow_preapply_root_state_change=bool(
                                    getattr(
                                        action,
                                        "ALLOWS_PREAPPLY_ROOT_STATE_MUTATION",
                                        False,
                                    )
                                ),
                                operator_cancellation=True,
                            )
                        )
                        if cancellation_detachments > 0:
                            # Settlement already restored terminal authority.
                            # Carry that disposition into cancellation so hooks are
                            # not invoked a second time.
                            dispatch_stage_authority_restored = True
                    finally:
                        task_tracker.close()
                        dispatch_session._durabilize_inflight_provider_exposure()
                except BaseException as barrier_error:
                    if dispatch_session._dispatch_worker_poisoned:
                        self._dispatch_worker_poisoned = True
                        self._dispatch_worker_poison_reason = str(
                            dispatch_session._dispatch_worker_poison_reason or ""
                        )
                    setattr(
                        cancellation,
                        "_mini_cancellation_quiescence_failed",
                        True,
                    )
                    cancellation.add_note(
                        "action cancellation barrier failed: "
                        f"{type(barrier_error).__name__}: {barrier_error}"
                    )
                    # Operator cancellation is the primary terminal cause.
                    # Keep the quiescence incident typed and visible, but do
                    # not relabel an explicitly stopped run as a spontaneous
                    # infrastructure abort merely because detached provider
                    # work resisted the best-effort shutdown barrier.
                    raise cancellation from barrier_error
                self._accrue_run_governor_elapsed()
                try:
                    restore_dispatch_stage_authority_once()
                except BaseException:
                    raise
                raise
            except DispatchScopeDetached as exc:
                # A nested strict-deadline operation has already invalidated
                # this dispatch's mutation authority. This BaseException
                # bypassed action-local ``except Exception`` recovery; retain
                # it as a retryable transaction incident and proceed directly
                # to the quiescence/restore barrier below.
                dispatch_exception = exc
                cost = time.monotonic() - started
                outcome = MiniOutcome(
                    action_id=action.id,
                    solved=False,
                    proof=None,
                    helpers_added=(),
                    progress=False,
                    cost_seconds=cost,
                    metadata={
                        "dispatch_scope_detached": True,
                        "preserve_frontier_work": True,
                    },
                )
            except Exception as exc:  # noqa: BLE001 — every action exception is captured
                dispatch_exception = exc
                cost = time.monotonic() - started
                if isinstance(exc, asyncio.TimeoutError):
                    recover_reservation = getattr(
                        dispatch_action,
                        "_recover_inflight_reservation",
                        None,
                    )
                    if callable(recover_reservation):
                        recover_reservation(dispatch_session)
                    outcome = MiniOutcome(
                        action_id=action.id,
                        solved=False,
                        proof=None,
                        helpers_added=(),
                        progress=False,
                        cost_seconds=cost,
                        metadata={
                            "run_governor_cancelled_inflight_action": True,
                            "timed_out_action_publication_revoked": True,
                            "preserve_frontier_work": True,
                        },
                    )
                else:
                    outcome = MiniOutcome.from_exception(
                        action,
                        exc,
                        cost_seconds=cost,
                    )
                    _LOGGER.exception("MiniSession action %r raised", action.id)
            except BaseException:
                task_tracker.close()
                raise
            try:
                detached_dispatch_tasks = (
                    await self._settle_dispatch_scope_before_commit(
                        scope_id=action_dispatch_id,
                        snapshot=dispatch_stage_rollback_snapshot,
                        task_tracker=task_tracker,
                        allow_preapply_root_state_change=bool(
                            dispatch_exception is not None
                            or getattr(
                                action,
                                "ALLOWS_PREAPPLY_ROOT_STATE_MUTATION",
                                False,
                            )
                        ),
                    )
                )
            except BaseException:
                dispatch_session._durabilize_inflight_provider_exposure()
                if dispatch_session._dispatch_worker_poisoned:
                    self._dispatch_worker_poisoned = True
                    self._dispatch_worker_poison_reason = str(
                        dispatch_session._dispatch_worker_poison_reason or ""
                    )
                raise
            finally:
                task_tracker.close()
            if detached_dispatch_tasks > 0:
                # Settlement has restored the only protected live-dispatch
                # fields (terminal proof authority). Do not claim a full
                # mathematical rollback: actions run against live state.
                dispatch_stage_authority_restored = True
            if dispatch_session._dispatch_generation_recycle_required:
                self._inflight_action_dispatch_id = ""
                self._accrue_run_governor_elapsed()
                self._resume_dispatch_generation(failed_action_id=action.id)
                continue
            if dispatch_exception is not None:
                self._accrue_run_governor_elapsed()
                dispatch_session.run_governor_elapsed_s = max(
                    float(dispatch_session.run_governor_elapsed_s or 0.0),
                    float(self.run_governor_elapsed_s or 0.0),
                )
                dispatch_session._run_governor_last_tick_monotonic = time.monotonic()
                if detached_dispatch_tasks == 0:
                    try:
                        restore_dispatch_stage_authority_once()
                    except BaseException:
                        # The session is terminal below even if restoring its
                        # two scalar proof-authority fields was itself broken.
                        pass
                dispatch_session._terminalize_primary_dispatch_failure(
                    action=dispatch_action,
                    action_dispatch_id=action_dispatch_id,
                    error=dispatch_exception,
                    deadline_detached=isinstance(
                        dispatch_exception,
                        DispatchScopeDetached,
                    ),
                )
                self._inflight_action_dispatch_id = ""
                self._resume_dispatch_generation(failed_action_id=action.id)
                continue
            if self._dispatch_worker_poisoned:
                self._inflight_action_dispatch_id = ""
                self._accrue_run_governor_elapsed()
                self._request_dispatch_generation_recycle(
                    self._dispatch_worker_poison_reason
                    or "legacy_dispatch_worker_poisoned"
                )
                self._resume_dispatch_generation(failed_action_id=action.id)
                continue
            if detached_dispatch_tasks > 0:
                # Only cancellable boundary work (for example a timer that
                # never fired or result-only deadline bookkeeping) can reach
                # this path. Genuine action-owned live tasks poison the
                # session above. Preserve the action's mathematical receipt;
                # erasing helpers/progress after mutating live state creates a
                # split-brain scheduler view.
                metadata = {
                    **dict(outcome.metadata or {}),
                    "detached_task_count": detached_dispatch_tasks,
                    "settlement_boundary_work_cancelled": True,
                }
                outcome = replace(
                    outcome,
                    metadata=metadata,
                )
            hook_detachments = 0
            try:
                dispatch_session._inflight_action_dispatch_id = ""
                dispatch_session._stamp_outcome_dispatch_metadata(
                    outcome,
                    usage_context=usage_context,
                    action_dispatch_id=action_dispatch_id,
                )
                outcome = dispatch_session.apply(outcome)
                hook_detachments = await dispatch_session._run_outcome_applied_hook(
                    action=dispatch_action,
                    outcome=outcome,
                    scope_id=action_dispatch_id,
                )
                applied_provider_dispatches = _nonnegative_metadata_int(
                    outcome.metadata,
                    "provider_dispatches_started",
                )
                post_apply_dispatches = (
                    session_provider_exposure_tracker.provider_dispatches_started
                )
                if post_apply_dispatches > 0:
                    dispatch_session._accrue_provider_exposure(
                        {"provider_dispatches_started": (post_apply_dispatches)}
                    )
                    outcome.metadata["provider_dispatches_started"] = (
                        applied_provider_dispatches + post_apply_dispatches
                    )
                    dispatch_session.last_action_outcome_metadata[
                        "provider_dispatches_started"
                    ] = applied_provider_dispatches + post_apply_dispatches
                session_provider_exposure_tracker.settle_all_current_exposure()
                dispatch_session._inflight_provider_exposure_tracker = (
                    session_provider_exposure_tracker if hook_detachments > 0 else None
                )
                take_planner_launch = getattr(
                    dispatch_action,
                    "take_pending_planner_job_launch",
                    None,
                )
                if callable(take_planner_launch):
                    planner_launch = take_planner_launch()
                    if planner_launch is not None:
                        broker = dispatch_session.planner_job_broker()
                        launched = bool(
                            broker is not None and broker.launch(planner_launch)
                        )
                        dispatch_session._record_event(
                            {
                                "phase": "session_planner_job",
                                "action_id": str(outcome.action_id or ""),
                                "planner_job_id": planner_launch.identity.job_id,
                                "request_fingerprint": (
                                    planner_launch.identity.request_fingerprint
                                ),
                                "verdict": (
                                    "planner_job_launched"
                                    if launched
                                    else "planner_job_launch_deduplicated"
                                ),
                            }
                        )
                if hook_detachments > 0:
                    self._dispatch_generation_late_rollback_snapshot = dict(
                        dispatch_stage_rollback_snapshot
                    )
                    self._park_isolated_dispatch_tails(
                        dispatch_session._pending_isolated_dispatch_tails
                    )
                    restore_dispatch_stage_authority_once()
                # No action-owned work remains after the settlement barrier
                # and synchronous apply hook.
            except BaseException:
                self._accrue_run_governor_elapsed()
                if dispatch_session._dispatch_generation_recycle_required:
                    self._resume_dispatch_generation(failed_action_id=action.id)
                    continue
                if dispatch_session._dispatch_worker_poisoned:
                    self._dispatch_worker_poisoned = True
                    self._dispatch_worker_poison_reason = str(
                        dispatch_session._dispatch_worker_poison_reason or ""
                    )
                raise
            if dispatch_session._dispatch_generation_recycle_required:
                self._resume_dispatch_generation(failed_action_id=action.id)
                continue
            if hook_detachments > 0 or self._dispatch_worker_poisoned:
                self._resume_dispatch_generation(failed_action_id=action.id)
                continue
            completed_action_id = str(outcome.action_id or "").strip()
            self._dispatch_generation_deferred_action_ids.discard(completed_action_id)
            self._dispatch_generation_action_failure_counts.pop(
                completed_action_id,
                None,
            )
            self._dispatch_generation_action_ready_monotonic.pop(
                completed_action_id,
                None,
            )
            if outcome.solved:
                proof = self.final_proof or self._durable_final_proof()
                if self.root_finalized and proof:
                    self._retire_terminal_ready_planner_jobs()
                    await self._drain_abandoned_actions_before_terminal(
                        scope_ids=tuple(terminal_deadline_scope_ids),
                    )
                    self.final_proof = proof
                    return True, proof
                self._record_event(
                    {
                        "phase": "session_root_finalization",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "action_dispatch_id": action_dispatch_id,
                        "root_finalization_verdict": str(
                            (outcome.metadata or {}).get("root_finalization_verdict")
                            or ""
                        ),
                        "root_finalization_verification_status": dict(
                            (outcome.metadata or {}).get(
                                "root_finalization_verification_status"
                            )
                            or {}
                        ),
                        "verdict": "solved_outcome_not_finalized",
                    }
                )
        durable_proof = self._durable_final_proof()
        if durable_proof and self.root_finalized:
            self._retire_terminal_ready_planner_jobs()
            await self._drain_abandoned_actions_before_terminal(
                scope_ids=tuple(terminal_deadline_scope_ids),
            )
            self.final_proof = durable_proof
            return True, durable_proof
        await self._drain_abandoned_actions_before_terminal(
            scope_ids=tuple(terminal_deadline_scope_ids),
        )
        return False, None

    async def _seed_same_problem_verified_helpers(self) -> None:
        """Import prior same-problem verified helpers before scheduling."""

        if self._proof_cache_seed_attempted:
            return
        self._proof_cache_seed_attempted = True
        if (
            not self.proof_cache_seed_same_problem
            or self.proof_cache is None
            or self.dossier is None
            or self.conv is None
            or self.lean is None
            or str(self.scope or "") == "subgoal"
        ):
            return
        theorem_name = str(
            getattr(self.dossier, "cache_owner_theorem_name", "")
            or getattr(self.dossier, "theorem_name", "")
            or getattr(self.problem, "theorem_name", "")
            or ""
        ).strip()
        if not theorem_name:
            return
        try:
            from ensemble_prover.proof_state_executor import (
                seed_verified_helpers_from_same_problem_cache,
            )

            summary = await seed_verified_helpers_from_same_problem_cache(
                lean=self.lean,
                conv=self.conv,
                dossier=self.dossier,
                proof_state=self.proof_state,
                proof_cache=self.proof_cache,
                theorem_name=theorem_name,
                timeout_s=float(self.proof_cache_seed_timeout_s or 0.0),
                max_helpers=int(self.proof_cache_seed_max_helpers or 0),
            )
        except Exception as exc:
            self._increment_dossier_metric(
                "mini_proof_state_cache_seed_errors",
                1,
            )
            self._record_event(
                {
                    "phase": "proof_state_cache_seed",
                    "verdict": "cache_seed_exception",
                    "theorem_name": theorem_name,
                    "error_kind": type(exc).__name__,
                    "error": str(exc)[:240],
                }
            )
            return
        verdict = str(summary.get("verdict") or "")
        if verdict and verdict != "cache_seed_skipped":
            payload = dict(summary)
            records = list(payload.get("records") or [])
            if len(records) > 12:
                payload["records"] = records[:12]
                payload["records_truncated"] = len(records) - 12
            self._record_event(payload)
        self._sync_retrieval_verified_helpers()

    def _capture_pre_select_snapshot(self) -> Dict[str, Any]:
        """Refresh the in-memory recycle cutpoint without writing turns.jsonl."""

        from .replay import scheduler_snapshot

        snapshot = scheduler_snapshot(
            self,
            case_id=f"{self.scope}:iter:{int(self.iteration or 0)}",
            include_proof_state=True,
            compact_proof_state=True,
        )
        self._latest_pre_select_snapshot = copy.deepcopy(snapshot)
        return snapshot

    def _record_pre_select_snapshot(self) -> None:
        """Persist a compact scheduler replay cutpoint before action selection."""

        try:
            from .replay import _snapshot_has_nested_failure

            snapshot = self._capture_pre_select_snapshot()
            failed = _snapshot_has_nested_failure(snapshot)
            self._record_event(
                {
                    "phase": "session_pre_select_snapshot",
                    "iteration": self.iteration,
                    "snapshot": snapshot,
                    "verdict": (
                        "pre_select_snapshot_failed"
                        if failed
                        else "pre_select_snapshot_recorded"
                    ),
                }
            )
        except Exception as exc:  # noqa: BLE001 - observability must not perturb search
            self._record_event(
                {
                    "phase": "session_pre_select_snapshot",
                    "iteration": self.iteration,
                    "snapshot": {
                        "snapshot_status": "failed",
                        "error": f"{type(exc).__name__}: {exc}",
                    },
                    "verdict": "pre_select_snapshot_failed",
                }
            )

    def _stamp_outcome_dispatch_metadata(
        self,
        outcome: MiniOutcome,
        *,
        usage_context: Dict[str, Any],
        action_dispatch_id: str,
    ) -> None:
        """Reconcile scheduler ancestry with action-created descendants."""

        if not isinstance(outcome.metadata, dict):
            return
        inflight_provider_dispatches = _nonnegative_metadata_int(
            {
                "provider_dispatches_started": getattr(
                    self._inflight_provider_exposure_tracker,
                    "provider_dispatches_started",
                    0,
                )
            },
            "provider_dispatches_started",
        )
        if inflight_provider_dispatches > 0:
            outcome.metadata["provider_dispatches_started"] = max(
                _nonnegative_metadata_int(
                    outcome.metadata,
                    "provider_dispatches_started",
                ),
                inflight_provider_dispatches,
            )
        outcome.metadata["action_dispatch_id"] = str(action_dispatch_id or "")
        descendant_fields = (
            "proof_candidate_id",
            "lean_residual_id",
            "repair_ticket_id",
            "accepted_fact_id",
            "assembly_id",
        )
        try:
            outcome_lineage = ProofLineageEnvelope.from_metadata(outcome.metadata)
        except (TypeError, ValueError):
            outcome_lineage = ProofLineageEnvelope()
        descendant_changes = {
            field_name: getattr(outcome_lineage, field_name)
            for field_name in descendant_fields
            if getattr(outcome_lineage, field_name)
        }
        ticket = outcome.repair_ticket
        if ticket is not None:
            descendant_changes.update(
                {
                    field_name: value
                    for field_name, value in {
                        "proof_candidate_id": str(
                            getattr(ticket, "proof_candidate_id", "") or ""
                        ).strip(),
                        "lean_residual_id": str(
                            getattr(ticket, "lean_residual_id", "") or ""
                        ).strip(),
                        "repair_ticket_id": str(
                            getattr(ticket, "ticket_id", "") or ""
                        ).strip(),
                    }.items()
                    if value
                }
            )
        root_candidate = outcome.root_candidate
        if root_candidate is not None:
            try:
                candidate_lineage = ProofLineageEnvelope.from_metadata(
                    getattr(root_candidate, "metadata", {})
                )
            except (TypeError, ValueError):
                candidate_lineage = ProofLineageEnvelope()
            descendant_changes.update(
                {
                    field_name: getattr(candidate_lineage, field_name)
                    for field_name in descendant_fields
                    if getattr(candidate_lineage, field_name)
                }
            )
        if "proof_lineage" in usage_context:
            dispatch_lineage = ProofLineageEnvelope.from_record(
                usage_context["proof_lineage"]
            )
            lineage = dispatch_lineage.updated(**descendant_changes)
            stamped_metadata = lineage.merged_metadata(outcome.metadata)
        elif descendant_changes:
            lineage = ProofLineageEnvelope().updated(**descendant_changes)
            stamped_metadata = lineage.merged_metadata(outcome.metadata)
        else:
            outcome.metadata.pop("proof_lineage", None)
            for field_name in ProofLineageEnvelope.__dataclass_fields__:
                outcome.metadata.pop(field_name, None)
            return
        outcome.metadata.clear()
        outcome.metadata.update(stamped_metadata)

    async def dispatch_subaction(self, action_id: str) -> Optional[MiniOutcome]:
        """Invoke a registered action by id WITHOUT going through select_next_action.

        M4 invariant: subaction calls share budgets with top-level dispatch,
        consume time/invocation count, but do NOT bump
        ``self.iteration`` (only top-level select_next_action does) and
        do NOT advance stagnation tracking. This lets a host action
        invoke helper-only salvage mid-turn while the outer loop still
        schedules it directly when the frontier reports work.

        Returns the action's MiniOutcome, or None if:
        - no action with that id is registered, OR
        - the action is not applicable, OR
        - its budget is exhausted.
        """

        for action in self.actions:
            if action.id != action_id:
                continue
            budget = self.budgets.get(action_id)
            if budget is not None and budget.exhausted():
                self._record_event(
                    {
                        "phase": "session_subaction_outcome",
                        "action_id": action_id,
                        "host_iteration": self.iteration,
                        "verdict": "subaction_budget_exhausted",
                    }
                )
                return None
            saved_target = self.selected_work_item
            saved_action_id = self.selected_work_item_action_id
            saved_record = dict(self.selected_work_item_record)
            saved_inflight_provider_exposure_tracker = (
                self._inflight_provider_exposure_tracker
            )
            if saved_inflight_provider_exposure_tracker is None:
                saved_inflight_provider_exposure_tracker = (
                    ProviderDispatchExposureTracker()
                )
            provider_dispatches_started_before_subaction = _nonnegative_metadata_int(
                vars(self),
                "provider_dispatches_started_total",
            )
            subaction_inflight_provider_exposure_tracker = None
            action_dispatch_id = uuid.uuid4().hex
            host_usage_context = self._action_usage_context(
                action_id=action_id,
                action_dispatch_id=action_dispatch_id,
            )
            usage_context = host_usage_context
            self._clear_selected_work_item()
            try:
                if not self._safe_is_applicable(action, context="subaction"):
                    self._record_event(
                        {
                            "phase": "session_subaction_outcome",
                            "action_id": action_id,
                            "host_iteration": self.iteration,
                            "verdict": "subaction_not_applicable",
                        }
                    )
                    return None
                subaction_usage_context = self._action_usage_context(
                    action_id=action_id,
                    action_dispatch_id=action_dispatch_id,
                )
                if "proof_lineage" in subaction_usage_context:
                    subaction_lineage = ProofLineageEnvelope.from_record(
                        subaction_usage_context["proof_lineage"]
                    )
                    if "proof_lineage" in host_usage_context:
                        host_lineage = ProofLineageEnvelope.from_record(
                            host_usage_context["proof_lineage"]
                        )
                        if not subaction_lineage.parent_lineage_id:
                            subaction_lineage = subaction_lineage.updated(
                                parent_lineage_id=(
                                    host_lineage.strategy_lineage_id
                                    or host_lineage.route_id
                                )
                            )
                    subaction_usage_context["proof_lineage"] = (
                        subaction_lineage.to_record()
                    )
                    usage_context = subaction_usage_context
                started = time.monotonic()
                self._synchronize_statement_environment_for_dispatch()
                inflight_provider_exposure_tracker = ProviderDispatchExposureTracker()
                subaction_inflight_provider_exposure_tracker = (
                    inflight_provider_exposure_tracker
                )
                inflight_provider_exposure_tracker.link_parent(
                    saved_inflight_provider_exposure_tracker
                )
                self._inflight_provider_exposure_tracker = (
                    inflight_provider_exposure_tracker
                )
                try:
                    with (
                        bind_llm_usage_context(usage_context),
                        bind_provider_dispatch_exposure_tracker(
                            inflight_provider_exposure_tracker
                        ),
                    ):
                        outcome = await action.run(self)
                except Exception as exc:
                    cost = time.monotonic() - started
                    outcome = MiniOutcome.from_exception(
                        action,
                        exc,
                        cost_seconds=cost,
                    )
                self._stamp_outcome_dispatch_metadata(
                    outcome,
                    usage_context=usage_context,
                    action_dispatch_id=action_dispatch_id,
                )
                # Consume budget so subaction time counts against the cap;
                # iteration counter and stagnation are top-level concerns.
                if action_id in self.budgets:
                    if not bool((outcome.metadata or {}).get("preserve_action_budget")):
                        self.budgets[action_id].consume(outcome.cost_seconds)
                        if outcome.exception is not None:
                            self.budgets[action_id].mark_exhausted(
                                f"raised:{type(outcome.exception).__name__}"
                            )
                outcome, subaction_metadata = self._apply_subaction_bookkeeping(outcome)
                subaction_lineage_metadata = {
                    key: value
                    for key, value in dict(outcome.metadata or {}).items()
                    if key == "proof_lineage"
                    or key in ProofLineageEnvelope.__dataclass_fields__
                }
                self._record_event(
                    {
                        **{
                            key: value
                            for key, value in usage_context.items()
                            if key != "proof_lineage"
                        },
                        **subaction_lineage_metadata,
                        "phase": "session_subaction_outcome",
                        "action_id": outcome.action_id,
                        "action_dispatch_id": action_dispatch_id,
                        "host_iteration": self.iteration,
                        "solved": outcome.solved,
                        "action_reported_solved": subaction_metadata.get(
                            "action_reported_solved"
                        ),
                        "root_finalization_vetoed_outcome": subaction_metadata.get(
                            "root_finalization_vetoed_outcome"
                        ),
                        "progress": outcome.progress,
                        "helpers_added_count": len(outcome.helpers_added),
                        "cost_seconds": round(outcome.cost_seconds, 4),
                        "exception": str(outcome.exception)
                        if outcome.exception
                        else None,
                        "root_finalization_accepted": subaction_metadata.get(
                            "root_finalization_accepted"
                        ),
                        "repair_ticket_created": bool(
                            outcome.repair_ticket is not None
                        ),
                        "verdict": "subaction_outcome",
                    }
                )
                return outcome
            finally:
                if subaction_inflight_provider_exposure_tracker is not None:
                    accounted_during_subaction = max(
                        0,
                        _nonnegative_metadata_int(
                            vars(self),
                            "provider_dispatches_started_total",
                        )
                        - provider_dispatches_started_before_subaction,
                    )
                    subaction_inflight_provider_exposure_tracker.settle_forwarded_exposure(
                        already_accounted=accounted_during_subaction,
                    )
                self._inflight_provider_exposure_tracker = (
                    saved_inflight_provider_exposure_tracker
                )
                self.selected_work_item = saved_target
                self.selected_work_item_action_id = saved_action_id
                self.selected_work_item_record = saved_record
        # H5 fix (2026-05-08): a subaction id with no matching registered
        # action used to silently return None. Emit telemetry so a typo'd
        # id surfaces in JSONL post-mortem instead of becoming an
        # invisible no-op.
        self._record_event(
            {
                "phase": "session_subaction_outcome",
                "action_id": action_id,
                "host_iteration": self.iteration,
                "registered_action_ids": [a.id for a in self.actions],
                "verdict": "subaction_not_registered",
            }
        )
        return None

    def _action_usage_context(
        self,
        *,
        action_id: str,
        action_dispatch_id: str,
    ) -> Dict[str, Any]:
        """Return durable, request-safe lineage for one action dispatch."""

        selected = dict(self.selected_work_item_record or {})
        raw_graph_record = selected.get("graph_record")
        graph_record = (
            dict(raw_graph_record) if isinstance(raw_graph_record, dict) else {}
        )
        try:
            lineage = ProofLineageEnvelope.from_metadata(selected)
        except (TypeError, ValueError):
            lineage = ProofLineageEnvelope()
        try:
            graph_lineage = ProofLineageEnvelope.from_metadata(graph_record)
        except (TypeError, ValueError):
            graph_lineage = ProofLineageEnvelope()
        lineage = lineage.updated(
            **{
                field_name: (
                    getattr(lineage, field_name) or getattr(graph_lineage, field_name)
                )
                for field_name in lineage.__dataclass_fields__
            }
        )

        def identity_text(value: Any) -> str:
            return value.strip() if isinstance(value, str) else ""

        route_id = (
            lineage.route_id
            or identity_text(selected.get("route_id"))
            or identity_text(graph_record.get("route_id"))
        )
        if route_id and not lineage.route_id:
            lineage = lineage.updated(route_id=route_id)
        payload: Dict[str, Any] = {
            "action_dispatch_id": str(action_dispatch_id or ""),
            "action_id": str(action_id or ""),
            "session_scope": str(self.scope or ""),
        }
        lineage_record = lineage.to_record()
        if any(
            str(value or "").strip()
            for key, value in lineage_record.items()
            if key != "schema_version"
        ):
            payload["proof_lineage"] = lineage_record
        return payload

    def _apply_subaction_bookkeeping(
        self,
        outcome: MiniOutcome,
    ) -> Tuple[MiniOutcome, Dict[str, Any]]:
        """Apply MiniOutcome fields that must not depend on dispatch style.

        Subactions intentionally skip ``apply()`` because the host action owns
        the outer iteration and stagnation accounting. Root finalization and
        repair-ticket handling are part of the outcome contract, though, so
        they must be honored for nested dispatch too.
        """

        metadata = dict(outcome.metadata or {})
        _normalize_provider_blocked_failure_metadata(metadata)
        _normalize_provider_exposure_metadata(metadata)
        self._accrue_provider_exposure(metadata)
        root_finalization_metadata = self._apply_root_finalization(outcome)
        metadata.update(root_finalization_metadata)
        effective_solved = self._apply_effective_solved_gate(
            outcome,
            metadata,
            root_finalization_metadata,
        )
        effective_outcome = replace(
            outcome,
            solved=effective_solved,
            metadata=metadata,
        )
        helper_progress_metadata = helper_progress_metadata_for_accepted_helpers(
            self.dossier,
            outcome.helpers_added,
        )
        metadata.update(helper_progress_metadata)
        if isinstance(outcome.metadata, dict):
            outcome.metadata.update(metadata)
        self._apply_repair_ticket_bookkeeping(effective_outcome, metadata)
        self._discharge_repair_policy_narrowing_after_action(effective_outcome)
        self.last_action_outcome_metadata = metadata
        giveup_cluster = self.last_action_outcome_metadata.get("giveup_cluster")
        if giveup_cluster:
            self.last_giveup_cluster = str(giveup_cluster)
            self.last_giveup_match = str(
                self.last_action_outcome_metadata.get("giveup_match") or ""
            )
        self._update_local_micro_theory_after_outcome(effective_outcome, metadata)
        self._record_event(
            {
                "phase": "session_subaction_bookkeeping",
                "action_id": outcome.action_id,
                "host_iteration": self.iteration,
                "solved": effective_solved,
                "action_reported_solved": bool(outcome.solved),
                "root_finalization_vetoed_outcome": bool(
                    outcome.solved and not effective_solved
                ),
                "root_finalization_accepted": metadata.get(
                    "root_finalization_accepted"
                ),
                "repair_ticket_created": bool(outcome.repair_ticket is not None),
                "verdict": "subaction_bookkeeping_applied",
            }
        )
        return effective_outcome, metadata

    def _accrue_provider_exposure(self, metadata: Mapping[str, Any]) -> None:
        """Retain durable completed-call and concrete-dispatch exposure."""

        completed = _nonnegative_metadata_int(
            metadata,
            "provider_calls_completed",
        )
        dispatched = _nonnegative_metadata_int(
            metadata,
            "provider_dispatches_started",
        )
        if completed > 0:
            self.provider_calls_completed_total = (
                _nonnegative_metadata_int(
                    vars(self),
                    "provider_calls_completed_total",
                )
                + completed
            )
        if dispatched > 0:
            self.provider_dispatches_started_total = (
                _nonnegative_metadata_int(
                    vars(self),
                    "provider_dispatches_started_total",
                )
                + dispatched
            )

    def _durabilize_inflight_provider_exposure(self) -> int:
        """Charge and settle live dispatches not yet represented durably."""

        tracker = self._inflight_provider_exposure_tracker
        dispatched = _nonnegative_metadata_int(
            {
                "provider_dispatches_started": getattr(
                    tracker,
                    "provider_dispatches_started",
                    0,
                )
            },
            "provider_dispatches_started",
        )
        if dispatched > 0:
            self._accrue_provider_exposure({"provider_dispatches_started": dispatched})
        settle = getattr(tracker, "settle_all_current_exposure", None)
        if callable(settle):
            settle()
        return dispatched

    @staticmethod
    def _apply_effective_solved_gate(
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
        root_finalization_metadata: Dict[str, Any],
    ) -> bool:
        """Publish the one authoritative solved bit for every dispatch path."""

        # Every solved action is a root-closure claim. It is authoritative
        # only after the root gate explicitly accepts it; absence of gate
        # metadata must fail closed.
        effective_solved = bool(
            outcome.solved
            and root_finalization_metadata.get("root_finalization_accepted") is True
        )
        metadata["action_reported_solved"] = bool(outcome.solved)
        metadata["effective_solved"] = effective_solved
        metadata["root_finalization_vetoed_outcome"] = bool(
            outcome.solved and not effective_solved
        )
        return effective_solved

    def _root_candidate_from_outcome(
        self,
        outcome: MiniOutcome,
    ) -> Optional[RootFinalizationCandidate]:
        if outcome.root_candidate is not None:
            return outcome.root_candidate
        if not outcome.solved or not str(outcome.proof or "").strip():
            return None
        metadata = dict(outcome.metadata or {})
        if not any(
            key in metadata
            for key in (
                "replay_helpers",
                "helper_names",
                "dependency_helper_names",
                "route_id",
                "dependency_node_ids",
                "require_route_contract",
                "verification_certificate",
                "root_finalization_already_applied",
            )
        ):
            return None
        replay_helpers = tuple(
            str(item or "").strip()
            for item in list(metadata.get("replay_helpers") or ())
            if str(item or "").strip()
        )
        helper_names = tuple(
            str(item or "").strip()
            for item in list(metadata.get("helper_names") or ())
            if str(item or "").strip()
        )
        dependency_helper_names = tuple(
            str(item or "").strip()
            for item in list(metadata.get("dependency_helper_names") or ())
            if str(item or "").strip()
        )
        return RootFinalizationCandidate(
            proof=str(outcome.proof or ""),
            replay_helpers=replay_helpers,
            helper_names=helper_names,
            dependency_helper_names=dependency_helper_names,
            phase=str(
                metadata.get("phase")
                or metadata.get("role")
                or outcome.action_id
                or "root_finalization"
            ),
            turn_index=int(
                metadata.get("conv_turn_index_phase")
                or metadata.get("turn_index")
                or self.iteration
                or 0
            ),
            source_action_id=outcome.action_id,
            route_id=str(metadata.get("route_id") or ""),
            dependency_node_ids=tuple(
                str(item or "").strip()
                for item in list(metadata.get("dependency_node_ids") or ())
                if str(item or "").strip()
            ),
            target_statement=str(
                metadata.get("target_statement")
                or getattr(self.dossier, "root_statement", "")
                or getattr(getattr(self, "problem", None), "statement_type", "")
                or ""
            ),
            require_route_contract=bool(metadata.get("require_route_contract")),
            verification_certificate=dict(
                metadata.get("verification_certificate") or {}
            ),
            metadata={
                "session_iteration": int(self.iteration or 0),
                "outcome_metadata": metadata,
            },
        )

    def _clear_uncontracted_root_side_effects(
        self,
        *,
        candidate: RootFinalizationCandidate,
        action_id: str,
        contract_status: Dict[str, Any],
    ) -> None:
        """Undo root-solved side effects from pre-finalizer internal paths."""

        dossier = self.dossier
        raw_proof_text = str(candidate.proof or "").strip()
        artifact_proof_text = sanitize_lean_artifact_text(candidate.proof)
        preserves_prior_artifact = self._root_artifact_has_distinct_contract(candidate)
        cleared_dossier = False
        if dossier is not None and raw_proof_text and not preserves_prior_artifact:
            current = str(getattr(dossier, "final_proof", "") or "").strip()
            clearer = getattr(dossier, "clear_solved", None)
            if current in {raw_proof_text, artifact_proof_text} and callable(clearer):
                try:
                    clearer()
                    cleared_dossier = True
                except Exception:
                    cleared_dossier = False
        current_session_proof = str(self.final_proof or "").strip()
        if not preserves_prior_artifact and current_session_proof in {
            raw_proof_text,
            artifact_proof_text,
        }:
            self.final_proof = None
        proof_state = self.proof_state
        reconciled_proof_state = False
        reconciler = getattr(proof_state, "reconcile_with_dossier", None)
        if callable(reconciler):
            try:
                reconciler(dossier)
                reconciled_proof_state = True
            except Exception:
                reconciled_proof_state = False
        self._record_event(
            {
                "phase": "session_root_finalization",
                "iteration": self.iteration,
                "action_id": str(action_id or ""),
                "cleared_dossier_root": bool(cleared_dossier),
                "preserved_distinct_root_artifact": bool(preserves_prior_artifact),
                "reconciled_proof_state": bool(reconciled_proof_state),
                "route_contract_status": dict(contract_status),
                "verdict": "uncontracted_root_side_effects_cleared",
            }
        )

    def _root_artifact_has_distinct_contract(
        self,
        candidate: RootFinalizationCandidate,
    ) -> bool:
        """Whether a matching proof belongs to a different accepted commit.

        Proof text is not a transaction identity: two attempts can emit the
        same tactic while carrying different route obligations.  Preserve a
        prior artifact only when its durable certificate proves that it came
        through the canonical Lean gate and its root contract differs from the
        candidate being rejected.  Bare ``mark_solved`` artifacts therefore
        remain retractable.
        """

        dossier = self.dossier
        if dossier is None:
            return False
        certificate = getattr(dossier, "root_proof_certificate", None)
        if not isinstance(certificate, dict):
            return False
        current_proof = str(getattr(dossier, "final_proof", "") or "").strip()
        if not current_proof:
            return False
        artifact_hash = text_hash(current_proof)
        root_statement = str(getattr(dossier, "root_statement", "") or "").strip()
        root_hash = text_hash(root_statement)
        verification = certificate.get("verification_certificate")
        verification_status = certificate.get("verification_status")
        accepted_proof_hash = str(certificate.get("accepted_proof_hash") or "").strip()
        authoritative = bool(
            certificate.get("schema_version") == 1
            and str(certificate.get("theorem_name") or "").strip()
            == str(getattr(dossier, "theorem_name", "") or "").strip()
            and str(certificate.get("root_statement_hash") or "").strip() == root_hash
            and str(certificate.get("proof_hash") or "").strip() == artifact_hash
            and str(certificate.get("artifact_proof_hash") or "").strip()
            == artifact_hash
            and accepted_proof_hash
            and isinstance(verification, dict)
            and verification.get("accepted") is True
            and str(verification.get("verifier") or "").strip() == "lean"
            and str(verification.get("proof_hash") or "").strip() == accepted_proof_hash
            and str(verification.get("target_statement_hash") or "").strip()
            == root_hash
            and isinstance(verification_status, dict)
            and verification_status.get("ready") is True
            and str(verification_status.get("verdict") or "").strip()
            == "root_finalization_certificate_ready"
            and str(verification_status.get("proof_hash") or "").strip()
            == accepted_proof_hash
            and str(verification_status.get("verifier") or "").strip() == "lean"
        )
        if not authoritative:
            return False

        def _clean_sequence(value: Any) -> Tuple[str, ...]:
            return tuple(
                str(item or "").strip()
                for item in list(value or ())
                if str(item or "").strip()
            )

        def _clean_turn_index(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return -1

        persisted_contract = (
            str(certificate.get("source_action_id") or "").strip(),
            str(certificate.get("phase") or "").strip(),
            _clean_turn_index(certificate.get("turn_index")),
            bool(certificate.get("require_route_contract")),
            str(certificate.get("route_id") or "").strip(),
            _clean_sequence(certificate.get("dependency_node_ids")),
            _clean_sequence(certificate.get("dependency_helper_names")),
            _clean_sequence(certificate.get("candidate_helper_names")),
        )
        candidate_contract = (
            str(candidate.source_action_id or "").strip(),
            str(candidate.phase or "").strip(),
            _clean_turn_index(candidate.turn_index),
            bool(candidate.require_route_contract),
            str(candidate.route_id or "").strip(),
            _clean_sequence(candidate.dependency_node_ids),
            _clean_sequence(candidate.dependency_helper_names),
            _clean_sequence(candidate.helper_names),
        )
        if persisted_contract != candidate_contract:
            return True
        candidate_verification = dict(candidate.verification_certificate or {})
        return bool(
            candidate_verification
            and candidate_verification != dict(verification or {})
        )

    def _hydrate_root_candidate_from_existing_finalization(
        self,
        candidate: RootFinalizationCandidate,
    ) -> RootFinalizationCandidate:
        dossier = self.dossier
        if dossier is None:
            return candidate
        proof_text = str(candidate.proof or "").strip()
        artifact_proof_text = sanitize_lean_artifact_text(candidate.proof)
        if not proof_text:
            return candidate
        current_proof = str(getattr(dossier, "final_proof", "") or "").strip()
        if current_proof not in {proof_text, artifact_proof_text}:
            return candidate
        graph = getattr(dossier, "proof_graph", None)
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        root = (
            nodes.get(str(getattr(graph, "root_node_id", "") or "root"))
            if isinstance(nodes, dict)
            else None
        )
        metadata = dict(getattr(root, "metadata", {}) or {}) if root is not None else {}
        candidate_route_id = str(candidate.route_id or "").strip()
        stored_route_id = str(metadata.get("root_finalization_route_id") or "").strip()
        route_id = candidate_route_id or stored_route_id
        verification_certificate = dict(candidate.verification_certificate or {})
        existing_certificate = metadata.get(
            "root_finalization_verification_certificate"
        )
        if not verification_certificate and isinstance(existing_certificate, dict):
            verification_certificate = dict(existing_certificate)
        root_proof_certificate = dict(
            getattr(dossier, "root_proof_certificate", {}) or {}
        )
        persisted_verification_certificate = root_proof_certificate.get(
            "verification_certificate"
        )
        if not verification_certificate and isinstance(
            persisted_verification_certificate, dict
        ):
            verification_certificate = dict(persisted_verification_certificate)
        dependency_node_ids = tuple(
            str(item or "").strip()
            for item in list(
                candidate.dependency_node_ids
                or metadata.get("root_finalization_dependency_node_ids")
                or ()
            )
            if str(item or "").strip()
        )
        stored_helper_names = tuple(
            str(item or "").strip()
            for item in list(metadata.get("root_finalization_helper_names") or ())
            if str(item or "").strip()
        )
        stored_dependency_helper_names = tuple(
            str(item or "").strip()
            for item in list(
                metadata.get("root_finalization_dependency_helper_names")
                or metadata.get("final_support_helper_names")
                or ()
            )
            if str(item or "").strip()
        )
        helper_names = stored_helper_names or tuple(
            str(item or "").strip()
            for item in list(candidate.helper_names or ())
            if str(item or "").strip()
        )
        dependency_helper_names = stored_dependency_helper_names or tuple(
            str(item or "").strip()
            for item in list(candidate.dependency_helper_names or ())
            if str(item or "").strip()
        )
        replay_helpers = tuple(candidate.replay_helpers or ())
        stored_replay_helpers = tuple(
            str(block or "").strip()
            for block in list(getattr(dossier, "final_replay_helpers", []) or [])
            if str(block or "").strip()
        )
        if not replay_helpers and stored_replay_helpers:
            replay_helpers = stored_replay_helpers
        try:
            from ensemble_prover.proof_dossier import helper_decl_name
        except Exception:
            helper_decl_name = None  # type: ignore[assignment]
        if callable(helper_decl_name):
            if not helper_names and replay_helpers:
                helper_names = tuple(
                    name
                    for block in replay_helpers
                    for name in [helper_decl_name(block)]
                    if name
                )
            if helper_names:
                helper_name_set = set(helper_names)
                sources = list(replay_helpers) + list(stored_replay_helpers)
                verified_getter = getattr(dossier, "verified_helper_blocks", None)
                if callable(verified_getter):
                    try:
                        sources.extend(list(verified_getter() or ()))
                    except Exception:
                        pass
                filtered: list[str] = []
                seen: set[str] = set()
                for block in sources:
                    block_text = str(block or "").strip()
                    sanitized_block = sanitize_lean_artifact_text(block_text)
                    if not sanitized_block:
                        continue
                    name = str(
                        helper_decl_name(sanitized_block)
                        or helper_decl_name(block_text)
                        or ""
                    )
                    if name in helper_name_set:
                        dedupe_key = name or sanitized_block
                        if dedupe_key in seen:
                            continue
                        filtered.append(sanitized_block)
                        seen.add(dedupe_key)
                replay_helpers = tuple(filtered)
        stored_proof_is_artifact = current_proof == artifact_proof_text
        hydrated_proof_text = (
            artifact_proof_text if stored_proof_is_artifact else proof_text
        )
        hydrated_proof_hash = text_hash(hydrated_proof_text)
        root_certificate_proof_hash = str(
            root_proof_certificate.get("proof_hash") or ""
        ).strip()
        certificate_proof_hash = str(
            verification_certificate.get("proof_hash") or ""
        ).strip()
        certificate_helper_hashes = sorted(
            str(item or "")
            for item in list(verification_certificate.get("helper_source_hashes") or [])
        )
        artifact_helper_hashes = sorted(text_hash(block) for block in replay_helpers)
        helper_hash_mismatch = bool(
            artifact_helper_hashes
            and certificate_helper_hashes
            and certificate_helper_hashes != artifact_helper_hashes
        )
        helper_hash_missing = bool(
            artifact_helper_hashes
            and verification_certificate
            and "helper_source_hashes" not in verification_certificate
        )

        # Minting an accepted Lean certificate from a persisted artifact is
        # only safe when prior finalization already recorded authoritative
        # evidence. Bare ``mark_solved`` or an ``accepted: True`` stub without
        # a matching proof_hash must not be laundered into
        # ``root_finalization_accepted=True``.
        def _accepted_certificate_matches_proof(
            certificate: Any,
        ) -> bool:
            if not isinstance(certificate, dict):
                return False
            if certificate.get("accepted") is not True:
                return False
            cert_proof_hash = str(certificate.get("proof_hash") or "").strip()
            return bool(cert_proof_hash and cert_proof_hash == hydrated_proof_hash)

        has_authoritative_finalization_evidence = bool(
            _accepted_certificate_matches_proof(verification_certificate)
            or self._can_hydrate_direct_root_artifact_certificate(
                candidate=candidate,
                root_proof_certificate=root_proof_certificate,
                root_metadata=metadata,
                hydrated_proof_hash=hydrated_proof_hash,
                replay_helpers=replay_helpers,
                helper_names=helper_names,
                dependency_helper_names=dependency_helper_names,
            )
        )
        should_use_artifact_certificate = bool(
            root_certificate_proof_hash
            and root_certificate_proof_hash == hydrated_proof_hash
            and has_authoritative_finalization_evidence
            and (
                not verification_certificate
                or certificate_proof_hash != hydrated_proof_hash
                or helper_hash_mismatch
                or helper_hash_missing
                or bool(root_proof_certificate.get("artifact_proof_sanitized"))
                or bool(root_proof_certificate.get("artifact_replay_helpers_sanitized"))
            )
        )
        if should_use_artifact_certificate:
            verification_certificate = root_verification_certificate(
                accepted=True,
                proof=hydrated_proof_text,
                phase=str(candidate.phase or "existing_root_finalization"),
                turn_index=int(candidate.turn_index or self.iteration or 0),
                target_statement=str(
                    root_proof_certificate.get("root_statement")
                    or getattr(dossier, "root_statement", "")
                    or candidate.target_statement
                    or ""
                ),
                replay_helpers=replay_helpers,
                helper_names=helper_names,
                source="persisted_root_artifact",
                metadata={"hydrated_from_root_proof_certificate": True},
            )
        existing_status = metadata.get("root_finalization_contract_status")
        if not route_id and not verification_certificate and not replay_helpers:
            return candidate
        candidate_metadata = dict(candidate.metadata or {})
        candidate_metadata["hydrated_from_existing_root_finalization"] = True
        if isinstance(existing_status, dict):
            candidate_metadata.setdefault(
                "route_assembly_contract_status",
                dict(existing_status),
            )
        return replace(
            candidate,
            proof=hydrated_proof_text,
            route_id=route_id,
            dependency_node_ids=dependency_node_ids,
            replay_helpers=replay_helpers,
            helper_names=helper_names or candidate.helper_names,
            dependency_helper_names=dependency_helper_names,
            require_route_contract=bool(route_id)
            or bool(candidate.require_route_contract),
            verification_certificate=verification_certificate,
            metadata=candidate_metadata,
        )

    def _can_hydrate_direct_root_artifact_certificate(
        self,
        *,
        candidate: RootFinalizationCandidate,
        root_proof_certificate: Dict[str, Any],
        root_metadata: Dict[str, Any],
        hydrated_proof_hash: str,
        replay_helpers: Sequence[str] = (),
        helper_names: Sequence[str] = (),
        dependency_helper_names: Sequence[str] = (),
    ) -> bool:
        """Validate a durable direct-root raw-to-artifact receipt chain.

        ``ProofDossier.mark_solved`` always creates a root artifact certificate,
        so that outer certificate is not proof that Lean accepted anything.  A
        canonical finalization additionally embeds the accepted verifier receipt
        and binds its raw proof hash to the sanitized artifact hash.  Hydration
        may bridge those two proof representations only when that complete chain
        is present and no route/helper state is being reconstructed.
        """

        if not self._root_candidate_target_matches_dossier(candidate):
            return False
        artifact_hash = str(hydrated_proof_hash or "").strip()
        if not artifact_hash:
            return False
        schema_version = root_proof_certificate.get("schema_version")
        if type(schema_version) is not int or schema_version != 1:
            return False
        dossier_theorem_name = str(
            getattr(self.dossier, "theorem_name", "") or ""
        ).strip()
        if (
            not dossier_theorem_name
            or str(root_proof_certificate.get("theorem_name") or "").strip()
            != dossier_theorem_name
        ):
            return False
        if str(root_proof_certificate.get("proof_hash") or "").strip() != artifact_hash:
            return False
        if (
            str(root_proof_certificate.get("artifact_proof_hash") or "").strip()
            != artifact_hash
        ):
            return False
        dossier_root_statement = str(
            getattr(self.dossier, "root_statement", "") or ""
        ).strip()
        dossier_root_hash = text_hash(dossier_root_statement)
        certificate_root_hash = str(
            root_proof_certificate.get("root_statement_hash") or ""
        ).strip()
        if not dossier_root_statement or certificate_root_hash != dossier_root_hash:
            return False
        persisted_receipt = root_proof_certificate.get("verification_certificate")
        if not isinstance(persisted_receipt, dict):
            return False
        if persisted_receipt.get("accepted") is not True:
            return False
        if str(persisted_receipt.get("verifier") or "").strip() != "lean":
            return False
        accepted_proof_hash = str(
            root_proof_certificate.get("accepted_proof_hash") or ""
        ).strip()
        if (
            not accepted_proof_hash
            or str(persisted_receipt.get("proof_hash") or "").strip()
            != accepted_proof_hash
        ):
            return False
        if (
            str(persisted_receipt.get("target_statement_hash") or "").strip()
            != dossier_root_hash
        ):
            return False
        verification_status = root_proof_certificate.get("verification_status")
        if not isinstance(verification_status, dict):
            return False
        if verification_status.get("ready") is not True:
            return False
        if (
            str(verification_status.get("verdict") or "").strip()
            != "root_finalization_certificate_ready"
            or str(verification_status.get("proof_hash") or "").strip()
            != accepted_proof_hash
            or str(verification_status.get("verifier") or "").strip() != "lean"
        ):
            return False
        artifact_was_sanitized = root_proof_certificate.get("artifact_proof_sanitized")
        if not isinstance(artifact_was_sanitized, bool):
            return False
        source_proof_hash = str(
            root_proof_certificate.get("source_proof_hash") or ""
        ).strip()
        if artifact_was_sanitized:
            # Canonical finalization passes the already-sanitized proof to the
            # dossier, so older schema-v1 artifacts may omit source_proof_hash.
            # accepted_proof_hash is still authored by that transaction and is
            # bound to the embedded verifier receipt; when a source hash is
            # present it must agree as an additional consistency check.
            if accepted_proof_hash == artifact_hash:
                return False
            if source_proof_hash and source_proof_hash != accepted_proof_hash:
                return False
        elif accepted_proof_hash != artifact_hash:
            return False
        require_route_contract = root_proof_certificate.get("require_route_contract")
        if not isinstance(require_route_contract, bool) or require_route_contract:
            return False
        route_id = root_proof_certificate.get("route_id")
        if not isinstance(route_id, str) or route_id.strip():
            return False
        root_sequence_fields = (
            "dependency_node_ids",
            "dependency_helper_names",
            "candidate_helper_names",
            "replay_helpers",
            "replay_helper_names",
            "replay_helper_source_hashes",
            "support_helper_names",
        )
        for field_name in root_sequence_fields:
            payload = root_proof_certificate.get(field_name)
            if not isinstance(payload, list):
                return False
            if any(str(item or "").strip() for item in payload):
                return False
        replay_helper_count = root_proof_certificate.get("replay_helper_count")
        if type(replay_helper_count) is not int or replay_helper_count != 0:
            return False
        artifact_helpers_sanitized = root_proof_certificate.get(
            "artifact_replay_helpers_sanitized"
        )
        if artifact_helpers_sanitized is not False:
            return False
        if (
            bool(candidate.require_route_contract)
            or str(candidate.route_id or "").strip()
        ):
            return False
        candidate_route_dependencies = tuple(
            candidate.dependency_node_ids or ()
        ) + tuple(candidate.dependency_helper_names or ())
        if any(str(item or "").strip() for item in candidate_route_dependencies):
            return False
        helper_payloads = (
            candidate.replay_helpers,
            candidate.helper_names,
            candidate.dependency_helper_names,
            replay_helpers,
            helper_names,
            dependency_helper_names,
            root_metadata.get("root_finalization_helper_names") or (),
            root_metadata.get("root_finalization_dependency_helper_names") or (),
            root_metadata.get("final_support_helper_names") or (),
        )
        for payload in helper_payloads:
            if any(str(item or "").strip() for item in list(payload or ())):
                return False
        if self._root_authoring_contract_required():
            status = self._ready_root_authoring_contract_status()
            if self._root_assembly_route_context_exists(status):
                return False
            try:
                if int(status.get("checked_route_count") or 0) > 0:
                    return False
            except (TypeError, ValueError):
                return False
            verdict = str(status.get("verdict") or "").strip()
            if verdict and verdict != "missing_ready_root_assembly_contract":
                return False
        return True

    def _root_candidate_target_matches_dossier(
        self,
        candidate: RootFinalizationCandidate,
    ) -> bool:
        """Whether a candidate is trying to finalize this dossier's root."""

        target_statement = str(candidate.target_statement or "").strip()
        dossier_root_statement = str(
            getattr(self.dossier, "root_statement", "") or ""
        ).strip()
        if not target_statement or not dossier_root_statement:
            return True
        return text_hash(target_statement) == text_hash(dossier_root_statement)

    def _root_finalization_requires_route_contract(
        self,
        candidate: RootFinalizationCandidate,
    ) -> Tuple[bool, Dict[str, Any]]:
        """Whether this root candidate must finalize through a route contract."""

        if not self._root_authoring_contract_required():
            return False, {"verdict": "root_contract_not_required"}
        if (
            bool(candidate.require_route_contract)
            or str(candidate.route_id or "").strip()
        ):
            return True, {"verdict": "candidate_requires_route_contract"}
        has_route_dependencies = bool(
            candidate.dependency_helper_names or candidate.dependency_node_ids
        )
        status = self._ready_root_authoring_contract_status()
        if has_route_dependencies and self._root_assembly_route_context_exists(status):
            return True, {
                "verdict": "root_route_context_requires_selected_route",
                "ready_root_assembly_contract_status": dict(status),
            }
        if self._root_assembly_route_context_exists(status):
            return False, {
                "verdict": "direct_root_certificate_allowed_with_route_context",
                "ready_root_assembly_contract_status": dict(status),
            }
        return False, {
            "verdict": "root_finalization_allowed_without_route_context",
            "ready_root_assembly_contract_status": dict(status),
        }

    def _record_root_finalization_solved_event(
        self,
        *,
        outcome: MiniOutcome,
        candidate: RootFinalizationCandidate,
        result: Any,
    ) -> None:
        route_contract_status = dict(getattr(result, "route_contract_status", {}) or {})
        certificate = dict(getattr(self.dossier, "root_proof_certificate", {}) or {})
        durable_replay_helpers = [
            str(block or "").strip()
            for block in list(certificate.get("replay_helpers") or ())
            if str(block or "").strip()
        ]
        if not durable_replay_helpers:
            durable_replay_helpers = [
                str(block or "").strip()
                for block in list(
                    getattr(self.dossier, "final_replay_helpers", ()) or ()
                )
                if str(block or "").strip()
            ]
        if not durable_replay_helpers:
            durable_replay_helpers = list(
                sanitize_lean_artifact_texts(candidate.replay_helpers or ())
            )
        durable_helper_names = [
            str(name or "").strip()
            for name in list(certificate.get("replay_helper_names") or ())
            if str(name or "").strip()
        ]
        if not durable_helper_names:
            durable_helper_names = [
                str(name or "").strip()
                for name in list(candidate.helper_names or ())
                if str(name or "").strip()
            ]
        outcome_metadata = dict(getattr(outcome, "metadata", {}) or {})
        selected_work = dict(outcome_metadata.get("selected_work_item") or {})
        selected_graph = dict(selected_work.get("graph_record") or selected_work)
        candidate_lineage = ProofLineageEnvelope.from_metadata(
            dict(candidate.metadata or {})
        )
        selected_lineage = ProofLineageEnvelope.from_metadata(selected_graph)
        lineage = candidate_lineage.updated(
            **{
                field_name: (
                    getattr(candidate_lineage, field_name)
                    or getattr(selected_lineage, field_name)
                )
                for field_name in candidate_lineage.__dataclass_fields__
            }
        )
        route_id = str(
            candidate.route_id
            or lineage.route_id
            or selected_graph.get("route_id")
            or ""
        ).strip()
        target_assembly_ids = [
            str(value or "").strip()
            for value in list(outcome_metadata.get("target_assembly_ids") or ())
            if str(value or "").strip()
        ]
        assembly_id = str(
            lineage.assembly_id
            or selected_work.get("assembly_id")
            or (target_assembly_ids[0] if target_assembly_ids else "")
        ).strip()
        accepted_proof = str(getattr(result, "proof", "") or candidate.proof).strip()
        if not assembly_id:
            assembly_id = stable_identity(
                "assembly",
                route_id,
                candidate.phase,
                candidate.turn_index,
                text_hash(accepted_proof),
            )
        lineage = lineage.updated(
            route_id=route_id,
            assembly_id=assembly_id,
            # Acceptance authors a new, authoritative candidate identity for
            # the exact proof and root target that Lean certified. Incoming
            # candidate metadata is ancestry, never identity authority.
            proof_candidate_id=proof_candidate_identity(
                target_id=str(
                    getattr(
                        getattr(self.dossier, "proof_graph", None),
                        "root_node_id",
                        "root",
                    )
                    or "root"
                ),
                proof_hash=text_hash(accepted_proof),
            ),
            # A residual denotes failed Lean evidence. It may remain useful
            # as explicit repair ancestry, but an accepted root must not
            # inherit an arbitrary stale failure identity from model-authored
            # candidate metadata.
            lean_residual_id=(
                lineage.lean_residual_id if lineage.repair_ticket_id else ""
            ),
        )
        lineage_recorder = getattr(
            self.dossier,
            "record_proof_lineage_event",
            None,
        )
        if callable(lineage_recorder):
            lineage_recorder(
                event_type="root_assembly_accepted",
                envelope=lineage,
                phase=str(candidate.phase or "session_root_finalization"),
                verdict="solved",
                evidence_hash=text_hash(accepted_proof),
                details={
                    "action_id": str(outcome.action_id or ""),
                    "route_id": route_id,
                    "assembly_id": assembly_id,
                    "helper_names": durable_helper_names,
                },
            )
        self._record_event(
            {
                "phase": "session_root_solved",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "accepted": True,
                "verdict": "solved",
                "accepted_proof": accepted_proof,
                "replay_helpers": list(
                    sanitize_lean_artifact_texts(durable_replay_helpers)
                ),
                "helper_names": durable_helper_names,
                "dependency_helper_names": [
                    str(name or "").strip()
                    for name in list(
                        getattr(result, "helper_names", ())
                        or candidate.dependency_helper_names
                        or ()
                    )
                    if str(name or "").strip()
                ],
                "route_id": route_id,
                "assembly_id": assembly_id,
                "proof_lineage": lineage.to_record(),
                "dependency_node_ids": [
                    str(node_id or "").strip()
                    for node_id in list(candidate.dependency_node_ids or ())
                    if str(node_id or "").strip()
                ],
                "root_finalization_verdict": str(getattr(result, "verdict", "") or ""),
                "route_contract_status": route_contract_status,
            }
        )

    def _refresh_already_applied_root_artifacts(
        self,
        *,
        candidate: RootFinalizationCandidate,
        result: Any,
        route_contract_status: Dict[str, Any],
    ) -> bool:
        """Rewrite legacy already-applied root artifacts without new attempts."""

        dossier = self.dossier
        refresher = getattr(dossier, "rewrite_solved_artifact", None)
        if not callable(refresher):
            return False
        verification_certificate = dict(candidate.verification_certificate or {})
        dependency_helper_names = tuple(
            str(name or "").strip()
            for name in list(
                getattr(result, "helper_names", ())
                or candidate.dependency_helper_names
                or ()
            )
            if str(name or "").strip()
        )
        try:
            refresher(
                candidate.proof,
                replay_helpers=candidate.replay_helpers,
                support_helper_names=dependency_helper_names,
                root_certificate_metadata={
                    "phase": str(candidate.phase or ""),
                    "turn_index": int(candidate.turn_index or 0),
                    "source_action_id": str(candidate.source_action_id or ""),
                    "route_id": str(candidate.route_id or ""),
                    "dependency_node_ids": [
                        str(node_id or "").strip()
                        for node_id in list(candidate.dependency_node_ids or ())
                        if str(node_id or "").strip()
                    ],
                    "dependency_helper_names": list(dependency_helper_names),
                    "candidate_helper_names": [
                        str(name or "").strip()
                        for name in list(candidate.helper_names or ())
                        if str(name or "").strip()
                    ],
                    "require_route_contract": bool(candidate.require_route_contract),
                    "route_contract_status": dict(route_contract_status),
                    "verification_status": dict(
                        getattr(result, "verification_status", {}) or {}
                    ),
                    "verification_certificate": verification_certificate,
                    "already_applied_artifact_refresh": True,
                    **dict(candidate.metadata or {}),
                },
            )
            return True
        except Exception as exc:
            self._record_event(
                {
                    "phase": "session_root_finalization",
                    "iteration": self.iteration,
                    "action_id": str(candidate.source_action_id or ""),
                    "accepted": False,
                    "verdict": "already_applied_artifact_refresh_failed",
                    "exception_type": type(exc).__name__,
                }
            )
            return False

    def _apply_root_finalization(self, outcome: MiniOutcome) -> Dict[str, Any]:
        candidate = self._root_candidate_from_outcome(outcome)
        if candidate is None:
            if outcome.solved:
                has_proof = bool(str(outcome.proof or "").strip())
                verdict = (
                    "missing_root_finalization_candidate"
                    if has_proof
                    else "missing_root_finalization_proof"
                )
                # A later vetoed solved claim must not unfinalize a prior
                # accepted durable root solution (zombie non-terminal).
                self._clear_root_finalized_for_rejected_attempt()
                self._increment_dossier_metric(
                    "mini_root_finalization_bypass_blocked",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_root_finalization",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "accepted": False,
                        "verdict": verdict,
                    }
                )
                return {
                    "root_finalization_accepted": False,
                    "root_finalization_verdict": verdict,
                    "route_contract_verdict": "",
                }
            return {}
        if self.dossier is None:
            self._clear_root_finalized_for_rejected_attempt()
            return {
                "root_finalization_accepted": False,
                "root_finalization_verdict": "root_finalization_dossier_missing",
            }
        if not callable(getattr(self.dossier, "mark_solved", None)):
            self._clear_root_finalized_for_rejected_attempt()
            return {
                "root_finalization_accepted": False,
                "root_finalization_verdict": "root_finalization_dossier_api_missing",
            }
        candidate = self._hydrate_root_candidate_from_existing_finalization(candidate)
        candidate_raw_proof = str(candidate.proof or "").strip()
        candidate_artifact_proof = sanitize_lean_artifact_text(candidate.proof)
        already_recorded = str(
            getattr(self.dossier, "final_proof", "") or ""
        ).strip() in {
            candidate_raw_proof,
            candidate_artifact_proof,
        } and self._root_candidate_target_matches_dossier(candidate)
        already_finalized = bool(
            (outcome.metadata or {}).get("root_finalization_already_applied")
            or dict(candidate.metadata or {}).get("root_finalization_already_applied")
        )
        route_contract_required, route_requirement_status = (
            self._root_finalization_requires_route_contract(candidate)
        )
        if route_contract_required:
            route_id = str(candidate.route_id or "").strip()
            contract_status: Dict[str, Any] = {}
            if route_id:
                status_getter = getattr(
                    getattr(self.dossier, "proof_graph", None),
                    "route_assembly_contract_status",
                    None,
                )
                if callable(status_getter):
                    try:
                        contract_status = dict(
                            status_getter(
                                route_id,
                                target_statement=str(
                                    candidate.target_statement
                                    or getattr(self.dossier, "root_statement", "")
                                    or ""
                                ),
                            )
                            or {}
                        )
                    except Exception as exc:
                        contract_status = {
                            "ready": False,
                            "verdict": "route_assembly_contract_status_exception",
                            "route_id": route_id,
                            "exception_type": type(exc).__name__,
                        }
                else:
                    contract_status = {
                        "ready": False,
                        "verdict": "route_assembly_contract_status_api_missing",
                        "route_id": route_id,
                    }
            else:
                contract_status = {
                    "ready": False,
                    "verdict": "missing_required_root_route_contract",
                    "route_requirement_status": dict(route_requirement_status),
                }
            if not bool(contract_status.get("ready")) or not route_id:
                if already_recorded or already_finalized:
                    self._clear_uncontracted_root_side_effects(
                        candidate=candidate,
                        action_id=outcome.action_id,
                        contract_status=contract_status,
                    )
                self._clear_root_finalized_for_rejected_attempt()
                self._increment_root_finalization_rejection_metrics(
                    verdict=str(
                        contract_status.get("verdict")
                        or "missing_ready_root_assembly_contract"
                    ),
                    route_contract_status=contract_status,
                )
                self._record_event(
                    {
                        "phase": "session_root_finalization",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "accepted": False,
                        "verdict": str(
                            contract_status.get("verdict")
                            or "missing_ready_root_assembly_contract"
                        ),
                        "route_contract_status": dict(contract_status),
                    }
                )
                return {
                    "root_finalization_accepted": False,
                    "root_finalization_verdict": str(
                        contract_status.get("verdict")
                        or "missing_ready_root_assembly_contract"
                    ),
                    "route_contract_verdict": str(contract_status.get("verdict") or ""),
                }
            dependency_node_ids = tuple(
                str(node_id or "").strip()
                for node_id in list(
                    candidate.dependency_node_ids
                    or tuple(contract_status.get("dependency_node_ids") or ())
                    or tuple(contract_status.get("required_node_ids") or ())
                )
                if str(node_id or "").strip()
            )
            candidate = replace(
                candidate,
                route_id=route_id,
                dependency_node_ids=dependency_node_ids,
                require_route_contract=True,
                metadata={
                    **dict(candidate.metadata or {}),
                    "root_authoring_contract_gate": True,
                    "route_assembly_contract_status": dict(contract_status),
                },
            )
        if already_recorded and already_finalized:
            result = finalize_root_solution(
                dossier=self.dossier,
                proof_state=self.proof_state,
                proof=candidate.proof,
                replay_helpers=candidate.replay_helpers,
                helper_names=candidate.helper_names,
                phase=candidate.phase,
                turn_index=candidate.turn_index,
                source_action_id=candidate.source_action_id,
                route_id=candidate.route_id,
                dependency_node_ids=candidate.dependency_node_ids,
                dependency_helper_names=candidate.dependency_helper_names,
                target_statement=candidate.target_statement,
                require_route_contract=candidate.require_route_contract,
                verification_certificate=candidate.verification_certificate,
                require_verification_certificate=True,
                record_attempt=False,
                persist_solution=False,
                metadata=candidate.metadata,
            )
            route_contract_status = dict(result.route_contract_status or {})
            if not result.accepted:
                self._increment_root_finalization_rejection_metrics(
                    verdict=result.verdict,
                    route_contract_status=route_contract_status,
                    verification_status=dict(result.verification_status or {}),
                )
                self._clear_uncontracted_root_side_effects(
                    candidate=candidate,
                    action_id=outcome.action_id,
                    contract_status=route_contract_status,
                )
                # Decide whether a prior finalization survives only after the
                # rejected candidate's matching uncontracted side effects have
                # been removed. Otherwise the proof being rejected can make
                # itself look like a durable prior success.
                self._clear_root_finalized_for_rejected_attempt()
                self._record_event(
                    {
                        "phase": "session_root_finalization",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "accepted": False,
                        "verdict": result.verdict,
                        "helper_names": list(candidate.helper_names),
                        "route_contract_status": route_contract_status,
                        "verification_status": dict(result.verification_status or {}),
                    }
                )
                return {
                    "root_finalization_accepted": False,
                    "root_finalization_verdict": result.verdict,
                    "root_finalization_verification_status": dict(
                        result.verification_status or {}
                    ),
                    "route_contract_verdict": str(
                        route_contract_status.get("verdict") or ""
                    ),
                }
            self.final_proof = result.proof
            self._refresh_already_applied_root_artifacts(
                candidate=candidate,
                result=result,
                route_contract_status=route_contract_status,
            )
            self.root_finalized = True
            self._record_event(
                {
                    "phase": "session_root_finalization",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "accepted": True,
                    "verdict": "root_finalization_already_applied",
                    "helper_names": list(candidate.helper_names),
                    "route_contract_status": route_contract_status,
                }
            )
            self._record_root_finalization_solved_event(
                outcome=outcome,
                candidate=candidate,
                result=result,
            )
            return {
                "root_finalization_accepted": True,
                "root_finalization_verdict": "root_finalization_already_applied",
                "root_finalization_verification_status": dict(
                    result.verification_status or {}
                ),
                "route_contract_verdict": str(
                    route_contract_status.get("verdict") or ""
                ),
            }
        result = finalize_root_solution(
            dossier=self.dossier,
            proof_state=self.proof_state,
            proof=candidate.proof,
            replay_helpers=candidate.replay_helpers,
            helper_names=candidate.helper_names,
            phase=candidate.phase,
            turn_index=candidate.turn_index,
            source_action_id=candidate.source_action_id,
            route_id=candidate.route_id,
            dependency_node_ids=candidate.dependency_node_ids,
            dependency_helper_names=candidate.dependency_helper_names,
            target_statement=candidate.target_statement,
            require_route_contract=candidate.require_route_contract,
            verification_certificate=candidate.verification_certificate,
            require_verification_certificate=True,
            record_attempt=not already_recorded,
            metadata=candidate.metadata,
        )
        if result.accepted:
            self.final_proof = result.proof
            self.root_finalized = True
        else:
            self._clear_root_finalized_for_rejected_attempt()
        self._record_event(
            {
                "phase": "session_root_finalization",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "accepted": bool(result.accepted),
                "verdict": result.verdict,
                "helper_names": list(candidate.helper_names),
                "dependency_helper_names": list(result.helper_names),
                "route_contract_status": dict(result.route_contract_status),
                "verification_status": dict(result.verification_status or {}),
            }
        )
        if result.accepted:
            self._record_root_finalization_solved_event(
                outcome=outcome,
                candidate=candidate,
                result=result,
            )
        return {
            "root_finalization_accepted": bool(result.accepted),
            "root_finalization_verdict": result.verdict,
            "root_finalization_verification_status": dict(
                result.verification_status or {}
            ),
            "route_contract_verdict": str(
                result.route_contract_status.get("verdict") or ""
            ),
        }

    @staticmethod
    def _repair_ticket_policy_rejection_reason(metadata: Dict[str, Any]) -> str:
        """Return a non-Lean policy/self-check rejection reason, if present."""

        self_check_advisory = bool(metadata.get("repair_self_check_advisory"))

        non_policy_self_check_statuses = {
            "try_lean_infrastructure_error",
            "try_lean_malformed_arguments",
            "try_lean_preflight_error",
            # Durable prior-stub acceptance IS compliance: a later genuine
            # Lean failure on the same turn must own the repair ticket
            # instead of being reclassified as a self-check refusal.
            "accepted_durable",
        }
        if bool(metadata.get("policy_repair_redirect")):
            return str(
                metadata.get("policy_repair_redirect_reason")
                or metadata.get("rejection_reason")
                or "policy_repair_redirect"
            ).strip()
        candidate_values = [
            metadata.get("rejection_reason"),
            metadata.get("lean_error_type"),
            metadata.get("repair_self_check_status"),
            metadata.get("repair_self_check_missing_kind"),
            metadata.get("verdict"),
        ]
        for value in candidate_values:
            reason = str(value or "").strip()
            if not reason:
                continue
            if reason in non_policy_self_check_statuses:
                return ""
            if reason in {
                "reused_rejected_lean_fragment",
                "transient_goal_target_sorry_helper",
                "repair_requires_api_search",
                "giveup_policy_active_proof_redirect",
            }:
                return reason
            if reason.startswith("repair_self_check_"):
                if self_check_advisory:
                    continue
                return reason
            if reason in {
                "no_try_lean_call",
                "no_accepted_try_lean",
                "tool_budget_exhausted",
                "accepted_try_lean_mismatch",
                "proof_policy_rejected",
            }:
                if self_check_advisory:
                    continue
                return f"repair_self_check_{reason}"
        if bool(metadata.get("repair_self_check_budget_exhausted")):
            if self_check_advisory:
                return ""
            status = str(
                metadata.get("repair_self_check_status")
                or metadata.get("repair_self_check_missing_kind")
                or ""
            ).strip()
            if status in non_policy_self_check_statuses:
                return ""
            return "repair_self_check_tool_budget_exhausted"
        return ""

    def _authenticated_answer_safe_recheck_continuation_identity(
        self,
        outcome: MiniOutcome,
        metadata: Mapping[str, Any],
    ) -> str:
        """Return the exact live verifier identity owning this handoff."""

        if not (
            metadata.get("answer_safe_recheck_infrastructure")
            and metadata.get("answer_safe_recheck_pending")
            and metadata.get("primary_lean_check_accepted")
            and metadata.get("preserve_action_budget")
            and str(metadata.get("lean_verdict") or "").strip()
            == "lean_infra_error"
        ):
            return ""
        owner = self.registered_action(str(outcome.action_id or "").strip())
        validator = getattr(
            owner,
            "_validated_answer_safe_recheck_pending_state",
            None,
        )
        owns_recheck = getattr(owner, "has_answer_safe_recheck_work", None)
        identity_builder = getattr(
            owner,
            "_answer_safe_recheck_binding_identity",
            None,
        )
        owner_pending = getattr(owner, "_answer_safe_recheck_pending", None)
        session_pending = getattr(self, "answer_safe_recheck_pending", None)
        if (
            owner is None
            or not callable(validator)
            or not callable(owns_recheck)
            or not callable(identity_builder)
            or not isinstance(owner_pending, Mapping)
            or not isinstance(session_pending, Mapping)
        ):
            return ""
        try:
            validated_pending = validator(owner_pending)
            if not (
                owns_recheck()
                and isinstance(validated_pending, Mapping)
                and validated_pending
                and dict(validated_pending) == dict(session_pending)
            ):
                return ""
            execution_binding = validated_pending.get("execution_binding")
            if not isinstance(execution_binding, Mapping):
                return ""
            return str(identity_builder(execution_binding) or "").strip()
        except Exception:
            # An invalid or uninspectable verifier receipt cannot authorize a
            # free repair continuation.
            return ""

    def _activate_answer_safe_recheck_repair_ticket_binding(
        self,
        *,
        action_id: str,
        recheck_identity: str,
    ) -> bool:
        """Activate ticket authority only for its exact verifier dispatch."""

        ticket = self.pending_repair_ticket
        ticket_id = str(getattr(ticket, "ticket_id", "") or "").strip()
        metadata = getattr(ticket, "metadata", None)
        binding = (
            metadata.get("answer_safe_recheck_repair_ticket_binding")
            if isinstance(metadata, Mapping)
            else None
        )
        expected = {
            "schema_version": 1,
            "ticket_id": ticket_id,
            "action_id": str(action_id or "").strip(),
            "recheck_identity": str(recheck_identity or "").strip(),
        }
        if (
            not ticket_id
            or not isinstance(binding, Mapping)
            or dict(binding) != expected
        ):
            return False
        self._repair_ticket_selected_id = ticket_id
        return True

    def _apply_repair_ticket_bookkeeping(
        self,
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
    ) -> None:
        selected_id = str(getattr(self, "_repair_ticket_selected_id", "") or "")
        selected_ticket = self.pending_repair_ticket
        new_ticket = outcome.repair_ticket
        selected_terminal = False
        target_integrity_contaminated = bool(
            metadata.get("target_integrity_signals")
            or metadata.get("target_integrity_bypass_local_repair")
            or metadata.get("target_integrity_disable_proof_state_repair")
        )
        selected_ticket_id = str(
            getattr(selected_ticket, "ticket_id", "") or ""
        ).strip()
        if selected_id and selected_id != selected_ticket_id:
            # Selection authority belongs to one exact durable ticket.  A
            # replacement may have been promoted after dispatch; never charge
            # that replacement for the stale predecessor's outcome.
            self._repair_ticket_selected_id = ""
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "selected_ticket_id": selected_id,
                    "active_ticket_id": selected_ticket_id,
                    "verdict": "stale_repair_ticket_selection_cleared",
                }
            )
            if new_ticket is not None and not target_integrity_contaminated:
                self.register_repair_ticket(new_ticket)
            elif new_ticket is not None:
                self._increment_dossier_metric(
                    "mini_session_target_integrity_repair_tickets_suppressed",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": str(
                            getattr(new_ticket, "ticket_id", "") or ""
                        ),
                        "target_id": str(
                            getattr(new_ticket, "target_id", "") or ""
                        ),
                        "selected_ticket_id": selected_id,
                        "active_ticket_id": selected_ticket_id,
                        "target_integrity_signals": list(
                            metadata.get("target_integrity_signals") or []
                        ),
                        "verdict": (
                            "target_integrity_fresh_repair_ticket_suppressed"
                        ),
                    }
                )
            return
        advisory_without_artifact = bool(
            metadata.get("repair_self_check_advisory")
            and not metadata.get("repair_submission_has_executable_lean")
            and not outcome.solved
            and not outcome.progress
            and not outcome.helpers_added
            and str(metadata.get("rejection_reason") or "").strip()
            in {
                "",
                "no_main_proof",
                "giveup_no_proof_active_proof_redirect",
            }
            and not metadata.get("target_integrity_signals")
            and not metadata.get("target_integrity_bypass_local_repair")
            and not metadata.get("target_integrity_disable_proof_state_repair")
        )
        answer_safe_recheck_identity = (
            self._authenticated_answer_safe_recheck_continuation_identity(
                outcome, metadata
            )
        )
        selected_ticket_metadata = getattr(selected_ticket, "metadata", None)
        if answer_safe_recheck_identity:
            expected_recheck_binding = {
                "schema_version": 1,
                "ticket_id": selected_ticket_id,
                "action_id": str(outcome.action_id or "").strip(),
                "recheck_identity": answer_safe_recheck_identity,
            }
            existing_recheck_binding = (
                selected_ticket_metadata.get(
                    "answer_safe_recheck_repair_ticket_binding"
                )
                if isinstance(selected_ticket_metadata, dict)
                else None
            )
            if not isinstance(selected_ticket_metadata, dict) or (
                existing_recheck_binding is not None
                and (
                    not isinstance(existing_recheck_binding, Mapping)
                    or dict(existing_recheck_binding)
                    != expected_recheck_binding
                )
            ):
                # A selected verifier receipt may renew only its own exact
                # binding. Identity drift cannot rewrite ticket authority or
                # mint an unbounded sequence of free infrastructure handoffs.
                answer_safe_recheck_identity = ""
        answer_safe_recheck_continuation = bool(answer_safe_recheck_identity)
        independent_non_consuming_continuation = bool(
            metadata.get("non_consuming_repair_self_check_continuation")
            or metadata.get("non_consuming_repair_ticket_continuation")
            or metadata.get("graph_native_statement_typecheck_pending")
            or metadata.get("residual_goal_dispatch_quarantined")
            or metadata.get("residual_goal_reattestation_pending")
            or answer_safe_recheck_continuation
        )
        advisory_continuation_granted = False
        if (
            advisory_without_artifact
            and not independent_non_consuming_continuation
            and selected_id
            and selected_ticket is not None
        ):
            # A single malformed/self-check miss may retry for free, but the
            # allowance belongs to this durable ticket.  Recomputing it from
            # each advisory outcome recreated an unbounded forced-repair loop.
            ticket_metadata = getattr(selected_ticket, "metadata", None)
            if isinstance(ticket_metadata, dict):
                raw_continuation_count = ticket_metadata.get(
                    "repair_advisory_without_artifact_continuations",
                    0,
                )
                continuation_count = (
                    raw_continuation_count
                    if type(raw_continuation_count) is int
                    and raw_continuation_count in {0, 1}
                    else 1
                )
                advisory_continuation_granted = continuation_count < 1
                if advisory_continuation_granted:
                    ticket_metadata[
                        "repair_advisory_without_artifact_continuations"
                    ] = (continuation_count + 1)
        non_consuming_self_check = bool(
            metadata.get("non_consuming_repair_self_check_continuation")
            or advisory_continuation_granted
        )
        non_consuming_ticket_continuation = bool(
            non_consuming_self_check
            or independent_non_consuming_continuation
        )
        provider_quantum_ticket_continuation = bool(
            metadata.get("non_consuming_repair_ticket_continuation")
            and metadata.get("provider_call_quantum_exhausted")
        )
        if not selected_id or selected_ticket is None:
            if non_consuming_ticket_continuation:
                return
            policy_rejection_reason = self._repair_ticket_policy_rejection_reason(
                metadata
            )
            if (
                policy_rejection_reason.startswith("repair_self_check_")
                and (
                    new_ticket is None
                    or self._repair_ticket_is_unscoped_root_level(new_ticket)
                )
                and self._materialize_unselected_root_policy_miss(
                    outcome,
                    metadata,
                    reason=policy_rejection_reason,
                )
            ):
                if new_ticket is not None:
                    self._suppress_fresh_unscoped_root_repair_ticket(
                        new_ticket,
                        reason="unselected_root_policy_miss_redirected_to_scope",
                    )
                return
            if new_ticket is not None:
                self.register_repair_ticket(new_ticket)
            return
        current = self.pending_repair_ticket
        if current is not selected_ticket:
            self._repair_ticket_selected_id = ""
            if new_ticket is not None:
                self.register_repair_ticket(new_ticket)
            return
        selected_projection_invalidated = bool(
            metadata.get("selected_work_projection_invalidated")
        )
        zero_provider_projection_invalidation = bool(
            selected_projection_invalidated
            and metadata.get(
                "selected_work_projection_zero_provider",
                True,
            )
            # A projection may be retired at the same cutpoint that publishes
            # useful helper or structural work. Zero provider exposure remains
            # factual telemetry, but that durable delta is not a pure defer and
            # must retain its ordinary soft-progress accounting.
            and not outcome.progress
        )
        if zero_provider_projection_invalidation:
            ticket_metadata = getattr(selected_ticket, "metadata", None)
            if isinstance(ticket_metadata, dict):
                ticket_metadata.pop("prompt_injected_for_attempt", None)
            self._repair_ticket_selected_id = ""
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": selected_ticket.ticket_id,
                    "target_id": selected_ticket.target_id,
                    "attempts_used": int(selected_ticket.attempts_used or 0),
                    "max_attempts": int(selected_ticket.max_attempts or 0),
                    "verdict": "repair_turn_projection_invalidated_retained",
                }
            )
            if new_ticket is not None:
                self.register_repair_ticket(new_ticket)
            return
        if non_consuming_ticket_continuation:
            ticket_metadata = getattr(selected_ticket, "metadata", None)
            if answer_safe_recheck_continuation and isinstance(
                ticket_metadata,
                dict,
            ):
                ticket_metadata["answer_safe_recheck_repair_ticket_binding"] = {
                    "schema_version": 1,
                    "ticket_id": selected_ticket.ticket_id,
                    "action_id": str(outcome.action_id or "").strip(),
                    "recheck_identity": answer_safe_recheck_identity,
                }
            if not provider_quantum_ticket_continuation:
                if (
                    not answer_safe_recheck_continuation
                    and isinstance(ticket_metadata, dict)
                ):
                    ticket_metadata.pop("prompt_injected_for_attempt", None)
                self._repair_ticket_selected_id = ""
            self._increment_dossier_metric(
                (
                    "mini_session_repair_provider_quantum_continuations"
                    if provider_quantum_ticket_continuation
                    else "mini_session_repair_answer_safe_recheck_continuations"
                    if answer_safe_recheck_continuation
                    else "mini_session_repair_self_check_continuations"
                    if non_consuming_self_check
                    else "mini_session_repair_ticket_policy_continuations"
                ),
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": selected_ticket.ticket_id,
                    "target_id": selected_ticket.target_id,
                    "verdict": (
                        "repair_provider_quantum_continuation_retained"
                        if provider_quantum_ticket_continuation
                        else "repair_answer_safe_recheck_continuation_retained"
                        if answer_safe_recheck_continuation
                        else "repair_self_check_continuation_retained"
                        if non_consuming_self_check
                        else "repair_ticket_policy_continuation_retained"
                    ),
                }
            )
            return
        lean_rejected = str(metadata.get("lean_verdict") or "") == "lean_rejected"
        policy_rejection_reason = self._repair_ticket_policy_rejection_reason(metadata)
        api_grounding_policy_rejection = (
            policy_rejection_reason == "repair_requires_api_search"
        )
        self_check_policy_rejection = policy_rejection_reason.startswith(
            "repair_self_check_"
        )
        retryable_policy_rejection = (
            self_check_policy_rejection or api_grounding_policy_rejection
        )
        if self_check_policy_rejection and (
            bool(outcome.solved)
            or bool(outcome.progress)
            or bool(outcome.helpers_added)
        ):
            policy_rejection_reason = ""
            self_check_policy_rejection = False
        meaningful_repair_attempt = (
            lean_rejected
            or (bool(policy_rejection_reason) and not retryable_policy_rejection)
            or bool(outcome.solved)
            or bool(outcome.progress)
            or bool(outcome.helpers_added)
        )
        if meaningful_repair_attempt:
            selected_ticket.attempts_used = int(selected_ticket.attempts_used or 0) + 1
        if target_integrity_contaminated:
            self._exhaust_repair_ticket(
                selected_ticket,
                reason="target_integrity_contaminated_repair",
            )
            selected_terminal = True
            self._repair_ticket_selected_id = ""
            self._increment_dossier_metric(
                "mini_session_target_integrity_repair_tickets_contaminated",
                1,
            )
            self._record_event(
                {
                    "phase": "session_repair_ticket",
                    "iteration": self.iteration,
                    "ticket_id": selected_ticket.ticket_id,
                    "target_id": selected_ticket.target_id,
                    "route_id": str(getattr(selected_ticket, "route_id", "") or ""),
                    "obligation_id": str(
                        getattr(selected_ticket, "obligation_id", "") or ""
                    ),
                    "work_type": str(getattr(selected_ticket, "work_type", "") or ""),
                    "proof_attempt_id": str(
                        getattr(selected_ticket, "proof_attempt_id", "") or ""
                    ),
                    "target_integrity_signals": list(
                        metadata.get("target_integrity_signals") or []
                    ),
                    "verdict": "target_integrity_repair_ticket_contaminated",
                }
            )
            if new_ticket is not None:
                self._increment_dossier_metric(
                    "mini_session_target_integrity_repair_tickets_suppressed",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": str(getattr(new_ticket, "ticket_id", "") or ""),
                        "target_id": str(getattr(new_ticket, "target_id", "") or ""),
                        "route_id": str(getattr(new_ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(new_ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(getattr(new_ticket, "work_type", "") or ""),
                        "proof_attempt_id": str(
                            getattr(new_ticket, "proof_attempt_id", "") or ""
                        ),
                        "selected_ticket_id": selected_ticket.ticket_id,
                        "verdict": "target_integrity_fresh_repair_ticket_suppressed",
                    }
                )
            return
        if lean_rejected:
            redirected_to_scope = False
            if selected_ticket.exhausted:
                self._exhaust_repair_ticket(
                    selected_ticket,
                    reason="repair_turn_lean_rejected",
                )
                selected_terminal = True
                redirected_to_scope = (
                    self._redirect_unscoped_root_repair_ticket_to_scope(
                        selected_ticket,
                        reason="unscoped_root_repair_lean_rejected",
                    )
                )
            else:
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_retry_remaining",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": selected_ticket.ticket_id,
                        "target_id": selected_ticket.target_id,
                        "route_id": str(getattr(selected_ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(selected_ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(
                            getattr(selected_ticket, "work_type", "") or ""
                        ),
                        "proof_attempt_id": str(
                            getattr(selected_ticket, "proof_attempt_id", "") or ""
                        ),
                        "attempts_used": int(selected_ticket.attempts_used or 0),
                        "max_attempts": int(selected_ticket.max_attempts or 0),
                        "verdict": "repair_turn_rejected_retry_remaining",
                    }
                )
            self._repair_ticket_selected_id = ""
            if new_ticket is not None and selected_terminal:
                suppress_new_ticket = (
                    self._suppress_fresh_unscoped_root_repair_ticket(
                        new_ticket,
                        reason="selected_root_repair_redirected_to_scope",
                    )
                    if redirected_to_scope
                    else self._suppress_fresh_unscoped_root_repair_ticket(
                        new_ticket,
                        reason="selected_root_repair_requires_scope",
                        predecessor=selected_ticket,
                    )
                )
                if suppress_new_ticket:
                    new_ticket = None
            if new_ticket is not None and selected_terminal:
                self.register_repair_ticket(new_ticket)
            return
        if policy_rejection_reason:
            self._increment_dossier_metric(
                "mini_session_repair_tickets_policy_rejections_consumed",
                1,
            )
            if not retryable_policy_rejection:
                if selected_ticket.exhausted:
                    self._exhaust_repair_ticket(
                        selected_ticket,
                        reason=policy_rejection_reason,
                    )
                    selected_terminal = True
                else:
                    ticket_metadata = getattr(selected_ticket, "metadata", None)
                    if isinstance(ticket_metadata, dict):
                        ticket_metadata.pop("prompt_injected_for_attempt", None)
                    self._increment_dossier_metric(
                        "mini_session_repair_tickets_retry_remaining",
                        1,
                    )
                    self._record_event(
                        {
                            "phase": "session_repair_ticket",
                            "iteration": self.iteration,
                            "ticket_id": selected_ticket.ticket_id,
                            "target_id": selected_ticket.target_id,
                            "route_id": str(
                                getattr(selected_ticket, "route_id", "") or ""
                            ),
                            "obligation_id": str(
                                getattr(selected_ticket, "obligation_id", "") or ""
                            ),
                            "work_type": str(
                                getattr(selected_ticket, "work_type", "") or ""
                            ),
                            "proof_attempt_id": str(
                                getattr(selected_ticket, "proof_attempt_id", "") or ""
                            ),
                            "attempts_used": int(selected_ticket.attempts_used or 0),
                            "max_attempts": int(selected_ticket.max_attempts or 0),
                            "rejection_reason": policy_rejection_reason,
                            "verdict": "repair_turn_policy_rejected_retry_remaining",
                        }
                    )
                self._repair_ticket_selected_id = ""
                if new_ticket is not None and selected_terminal:
                    self.register_repair_ticket(new_ticket)
                return
            selected_ticket.policy_attempts_used = (
                int(getattr(selected_ticket, "policy_attempts_used", 0) or 0) + 1
            )
            redirected_to_scope = False
            max_policy_attempts = max(
                1,
                int(getattr(selected_ticket, "max_policy_attempts", 2) or 2),
            )
            if int(selected_ticket.policy_attempts_used or 0) >= max_policy_attempts:
                self._exhaust_repair_ticket(
                    selected_ticket,
                    reason=policy_rejection_reason,
                )
                redirected_to_scope = (
                    self._redirect_unscoped_root_repair_ticket_to_scope(
                        selected_ticket,
                        reason=policy_rejection_reason,
                    )
                )
                if not redirected_to_scope:
                    self._mark_repair_policy_narrowing_required(
                        selected_ticket,
                        reason=policy_rejection_reason,
                    )
                selected_terminal = True
            else:
                ticket_metadata = getattr(selected_ticket, "metadata", None)
                if isinstance(ticket_metadata, dict):
                    ticket_metadata.pop("prompt_injected_for_attempt", None)
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_retry_remaining",
                    1,
                )
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_policy_retries_remaining",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_repair_ticket",
                        "iteration": self.iteration,
                        "ticket_id": selected_ticket.ticket_id,
                        "target_id": selected_ticket.target_id,
                        "route_id": str(getattr(selected_ticket, "route_id", "") or ""),
                        "obligation_id": str(
                            getattr(selected_ticket, "obligation_id", "") or ""
                        ),
                        "work_type": str(
                            getattr(selected_ticket, "work_type", "") or ""
                        ),
                        "proof_attempt_id": str(
                            getattr(selected_ticket, "proof_attempt_id", "") or ""
                        ),
                        "attempts_used": int(selected_ticket.attempts_used or 0),
                        "max_attempts": int(selected_ticket.max_attempts or 0),
                        "policy_attempts_used": int(
                            selected_ticket.policy_attempts_used or 0
                        ),
                        "max_policy_attempts": max_policy_attempts,
                        "rejection_reason": policy_rejection_reason,
                        "verdict": "repair_turn_policy_rejected_retry_remaining",
                    }
                )
            self._repair_ticket_selected_id = ""
            if new_ticket is not None and selected_terminal:
                suppress_new_ticket = (
                    self._suppress_fresh_unscoped_root_repair_ticket(
                        new_ticket,
                        reason="repair_policy_narrowing_required",
                    )
                    if redirected_to_scope
                    else self._suppress_fresh_unscoped_root_repair_ticket(
                        new_ticket,
                        reason="repair_policy_terminal_requires_scope",
                    )
                )
                if suppress_new_ticket:
                    new_ticket = None
            if new_ticket is not None and selected_terminal:
                self.register_repair_ticket(new_ticket)
            return
        if not meaningful_repair_attempt and not bool(outcome.solved):
            selected_ticket.attempts_used = int(selected_ticket.attempts_used or 0) + 1
            self._increment_dossier_metric(
                "mini_session_repair_tickets_unresolved_attempts_consumed",
                1,
            )
            ticket_metadata = getattr(selected_ticket, "metadata", None)
            if isinstance(ticket_metadata, dict):
                ticket_metadata.pop("prompt_injected_for_attempt", None)
            unresolved_record = {
                "phase": "session_repair_ticket",
                "iteration": self.iteration,
                "ticket_id": selected_ticket.ticket_id,
                "target_id": selected_ticket.target_id,
                "route_id": str(getattr(selected_ticket, "route_id", "") or ""),
                "obligation_id": str(
                    getattr(selected_ticket, "obligation_id", "") or ""
                ),
                "work_type": str(getattr(selected_ticket, "work_type", "") or ""),
                "proof_attempt_id": str(
                    getattr(selected_ticket, "proof_attempt_id", "") or ""
                ),
                "attempts_used": int(selected_ticket.attempts_used or 0),
                "max_attempts": int(selected_ticket.max_attempts or 0),
                "outcome_verdict": str(metadata.get("verdict") or ""),
                "lean_verdict": str(metadata.get("lean_verdict") or ""),
                "rejection_reason": str(metadata.get("rejection_reason") or ""),
            }
            if selected_ticket.exhausted:
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_unresolved_exhausted",
                    1,
                )
                self._record_event(
                    {
                        **unresolved_record,
                        "reason": "repair_turn_unresolved",
                        "verdict": "repair_turn_unresolved_exhausted",
                    }
                )
                self._exhaust_repair_ticket(
                    selected_ticket,
                    reason="repair_turn_unresolved",
                )
            else:
                self._increment_dossier_metric(
                    "mini_session_repair_tickets_retry_remaining",
                    1,
                )
                self._record_event(
                    {
                        **unresolved_record,
                        "verdict": "repair_turn_unresolved_retry_remaining",
                    }
                )
            self._repair_ticket_selected_id = ""
            if new_ticket is not None:
                self.register_repair_ticket(new_ticket)
            return
        self._resolve_repair_ticket(selected_ticket, verdict="repair_turn_consumed")
        self._repair_ticket_selected_id = ""
        if new_ticket is not None:
            self.register_repair_ticket(new_ticket)

    def _publish_owned_verified_helpers_to_cache(self, *, action_id: str) -> None:
        """Synchronize helpers only after this session's dossier owns them.

        Recursive and graph actions may create helpers in transient child
        dossiers before filtering/merging them into this session's durable
        proof graph.  Publishing here makes that ownership transition the
        cache boundary rather than relying on every action to remember a
        bespoke cache write.
        """

        if self.proof_cache is None or self.dossier is None:
            return
        self._sync_retrieval_verified_helpers()
        try:
            from ensemble_prover.proof_state_cache import (
                publish_verified_dossier_helpers_to_cache,
            )

            conv = self.conv
            preamble = str(
                getattr(conv, "lean_preamble", "")
                or getattr(conv, "preamble", "")
                or ""
            )
            summary = publish_verified_dossier_helpers_to_cache(
                self.proof_cache,
                dossier=self.dossier,
                preamble=preamble,
                phase=f"session:{action_id}",
            )
        except Exception:
            # Cache persistence is advisory and must not invalidate a Lean
            # verified action.  The concrete cache records I/O failures via
            # its existing metric sink.
            return
        stored = int(summary.get("stored", 0) or 0)
        if stored <= 0:
            return
        self._increment_dossier_metric("mini_proof_state_cache_publications", stored)
        self._record_event(
            {
                "phase": "proof_state_cache_publish",
                "action_id": str(action_id or ""),
                "theorem_name": str(
                    getattr(self.dossier, "cache_owner_theorem_name", "")
                    or getattr(self.dossier, "theorem_name", "")
                    or ""
                ),
                "eligible_count": int(summary.get("eligible", 0) or 0),
                "stored_count": stored,
                "skipped_count": int(summary.get("skipped", 0) or 0),
                "verdict": "cache_helpers_published",
            }
        )

    def _sync_retrieval_verified_helpers(self) -> None:
        """Reflect current-dossier kernel checks into session-local retrieval."""

        mark_rechecked = getattr(
            self.searcher,
            "mark_verified_helper_rechecked",
            None,
        )
        if not callable(mark_rechecked) or self.dossier is None:
            return
        for helper in tuple(getattr(self.dossier, "verified_helpers", {}).values()):
            source = str(getattr(helper, "source", "") or "").strip()
            if source:
                mark_rechecked(text_hash(source))

    def _defer_optional_theory_bookkeeping(
        self,
        metadata: Dict[str, Any],
        *,
        operation: str,
        exc: Exception,
    ) -> None:
        """Record an advisory theory-persistence failure without losing math.

        Only ordinary ``Exception`` instances from explicit theory persistence
        calls reach this helper. External ``BaseException`` control flow is
        intentionally not intercepted.
        """

        failures = list(metadata.get("theory_bookkeeping_failures") or [])
        failure = {
            "operation": str(operation or ""),
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
        failures.append(failure)
        metadata["theory_bookkeeping_failures"] = failures
        metadata["theory_bookkeeping_deferred"] = True
        metadata["preserve_frontier_work"] = True
        self._record_event(
            {
                "phase": "session_theory_bookkeeping",
                "iteration": int(self.iteration or 0),
                "operation": failure["operation"],
                "error_type": failure["error_type"],
                "error": failure["error"],
                "verdict": "optional_theory_bookkeeping_deferred",
            }
        )

    def _mark_apply_transaction_failure(
        self,
        *,
        outcome: MiniOutcome,
        action_dispatch_id: str,
        error: BaseException,
        emit_event: bool = True,
    ) -> None:
        """Fence an ambiguous apply and request a fresh worker generation."""

        self._apply_transaction_failed = True
        if action_dispatch_id:
            try:
                self._failed_action_dispatch_ids.add(action_dispatch_id)
            except BaseException:
                pass
        try:
            error_type = type(error).__name__
        except BaseException:
            error_type = "BaseException"
        self._request_dispatch_generation_recycle("mini_apply_transaction_failure")
        try:
            error_message = str(error)
        except BaseException:
            error_message = "<message unavailable>"
        if emit_event:
            try:
                self._record_event(
                    {
                        "phase": "session_action_outcome_apply",
                        "iteration": int(self.iteration or 0),
                        "action_id": str(outcome.action_id or ""),
                        "action_dispatch_id": action_dispatch_id,
                        "error_type": error_type,
                        "error": error_message,
                        "generation_recycle_required": True,
                        "verdict": "outcome_apply_failed_generation_recycle",
                    }
                )
            except BaseException:
                pass

    def apply(self, outcome: MiniOutcome) -> MiniOutcome:
        """Cross-action bookkeeping (budgets, iteration, stagnation, recorder).

        Per architectural principle #2: actions return this outcome;
        ``apply`` is the central state-mutation seam for cross-cutting
        concerns. Direct mutations of dossier/proof_state/conv that are
        the action's PRIMARY work go through those objects' own APIs
        inside ``Action.run()`` (e.g. ``dossier.record_verified_helper``);
        ``apply`` covers the rest.

        Returns the effective outcome. ``MiniOutcome`` is frozen, so callers
        (especially ``run()`` and ``on_outcome_applied`` hooks) must use the
        returned object — the input's ``solved`` bit is not rewritten in place.
        """

        metadata = dict(outcome.metadata or {})
        action_dispatch_id = str(metadata.get("action_dispatch_id") or "").strip()
        if self._apply_transition_active:
            active_dispatch_id = next(
                iter(self._applying_action_dispatch_ids),
                "<unstamped>",
            )
            reentrant_error = RuntimeError(
                "reentrant action outcome application rejected while dispatch "
                f"{active_dispatch_id} is active"
            )
            # The callback that re-entered apply may itself be the event sink.
            # Do not recursively publish another failure event from this path.
            self._mark_apply_transaction_failure(
                outcome=outcome,
                action_dispatch_id=action_dispatch_id,
                error=reentrant_error,
                emit_event=False,
            )
            raise reentrant_error
        has_success_id = bool(
            action_dispatch_id
            and action_dispatch_id in self._applied_action_dispatch_ids
        )
        has_success_outcome = bool(
            action_dispatch_id
            and action_dispatch_id in self._applied_action_dispatch_outcomes
        )
        if has_success_id or has_success_outcome:
            if not (has_success_id and has_success_outcome):
                # A successful id without its effective receipt is an
                # impossible partial ledger state. Never guess whether the
                # input was already charged or which solved bit was accepted.
                ledger_error = RuntimeError(
                    "action outcome idempotency ledger is incomplete for "
                    f"dispatch {action_dispatch_id}"
                )
                self._mark_apply_transaction_failure(
                    outcome=outcome,
                    action_dispatch_id=action_dispatch_id,
                    error=ledger_error,
                )
                raise ledger_error
            effective = self._applied_action_dispatch_outcomes[action_dispatch_id]
            if (
                action_dispatch_id
                not in self._duplicate_action_dispatch_events_in_progress
            ):
                self._duplicate_action_dispatch_events_in_progress.add(
                    action_dispatch_id
                )
                try:
                    self._record_event(
                        {
                            "phase": "session_action_outcome_duplicate",
                            "iteration": int(self.iteration or 0),
                            "action_id": str(outcome.action_id or ""),
                            "action_dispatch_id": action_dispatch_id,
                            "verdict": "duplicate_dispatch_outcome_ignored",
                        }
                    )
                finally:
                    self._duplicate_action_dispatch_events_in_progress.discard(
                        action_dispatch_id
                    )
            return effective
        recursive_paid_observer = getattr(
            self,
            "_recursive_paid_no_artifact_observer",
            None,
        )
        if callable(recursive_paid_observer):
            try:
                recursive_paid_observer(outcome)
            except Exception:
                _LOGGER.debug(
                    "Recursive paid-lane observer failed",
                    exc_info=True,
                )
        if self._apply_transaction_failed or (
            action_dispatch_id in self._failed_action_dispatch_ids
        ):
            raise RuntimeError(
                "action outcome application previously failed for dispatch "
                f"{action_dispatch_id or '<unstamped>'}; session is poisoned"
            )
        if action_dispatch_id:
            # Reserve before the first synchronous recorder callback. A
            # callback can re-enter public apply(), so a post-transition
            # success tombstone is too late to enforce exactly-once mutation.
            self._applying_action_dispatch_ids.add(action_dispatch_id)
        self._apply_transition_active = True
        try:
            try:
                effective = self._apply_outcome_once(outcome)
            except BaseException as exc:
                self._mark_apply_transaction_failure(
                    outcome=outcome,
                    action_dispatch_id=action_dispatch_id,
                    error=exc,
                )
                raise
            if self._apply_transaction_failed:
                invalidated_error = RuntimeError(
                    "action outcome application was invalidated by a "
                    f"reentrant transition for dispatch {action_dispatch_id}"
                )
                self._mark_apply_transaction_failure(
                    outcome=outcome,
                    action_dispatch_id=action_dispatch_id,
                    error=invalidated_error,
                    emit_event=False,
                )
                raise invalidated_error
            if action_dispatch_id:
                # Publish both parts of the success ledger only after the
                # complete central transition returns. An exception leaves a
                # failed-id receipt and a poisoned session, never a success
                # tombstone.
                try:
                    self._applied_action_dispatch_outcomes[action_dispatch_id] = (
                        effective
                    )
                    self._applied_action_dispatch_ids.add(action_dispatch_id)
                except BaseException as exc:
                    try:
                        self._applied_action_dispatch_outcomes.pop(
                            action_dispatch_id,
                            None,
                        )
                        self._applied_action_dispatch_ids.discard(action_dispatch_id)
                    except BaseException:
                        pass
                    self._mark_apply_transaction_failure(
                        outcome=outcome,
                        action_dispatch_id=action_dispatch_id,
                        error=exc,
                    )
                    raise
                # Observe health only after the complete transition and its
                # exactly-once receipt are committed. Duplicate/cancelled
                # dispatches cannot advance this process-local streak.
                try:
                    self._observe_applied_falsification_backend_timeout(effective)
                except Exception:
                    # Health recovery is fail-open relative to proof authority;
                    # a bookkeeping defect cannot invalidate an already
                    # committed mathematical outcome.
                    _LOGGER.debug(
                        "Falsification backend-timeout observation failed",
                        exc_info=True,
                    )
            reconcile_helpers = getattr(
                self,
                "theory_verified_helper_reconcile_callback",
                None,
            )
            if callable(reconcile_helpers):
                self._theory_promotion_actions_since_reconcile += 1
                reconcile_interval = max(
                    1,
                    int(self.theory_promotion_reconcile_interval_actions or 1),
                )
                reconcile_due = bool(
                    effective.helpers_added
                    or effective.solved
                    or self._theory_promotion_actions_since_reconcile
                    >= reconcile_interval
                )
            else:
                reconcile_due = False
            if reconcile_due:
                try:
                    reconciliation_settled = reconcile_helpers()
                    if reconciliation_settled is not False:
                        # ``None`` remains success for legacy/custom callbacks.
                        self._theory_promotion_actions_since_reconcile = 0
                    else:
                        # A helper-triggered attempt can occur before the
                        # interval. Keep the counter due so backoff/failure is
                        # retried at the very next committed action boundary.
                        self._theory_promotion_actions_since_reconcile = max(
                            self._theory_promotion_actions_since_reconcile,
                            reconcile_interval,
                        )
                except Exception as exc:
                    # Promotion bookkeeping is outside proof authority. A
                    # failed receipt/tombstone write is retried at the next
                    # action boundary and during session finalization.
                    self._theory_promotion_actions_since_reconcile = max(
                        self._theory_promotion_actions_since_reconcile,
                        reconcile_interval,
                    )
                    try:
                        self._record_event(
                            {
                                "phase": "domain_theory_promotion_receipt",
                                "error": f"{type(exc).__name__}: {exc}",
                                "verdict": "helper_promotion_reconcile_deferred",
                            }
                        )
                    except Exception:
                        pass
            return effective
        finally:
            self._apply_transition_active = False
            if action_dispatch_id:
                self._applying_action_dispatch_ids.discard(action_dispatch_id)

    def _apply_outcome_once(self, outcome: MiniOutcome) -> MiniOutcome:
        """Apply one previously unseen action receipt."""

        action_reported_outcome = outcome
        metadata = dict(outcome.metadata or {})
        # Provider/account/capability failures are durable service blocks,
        # never implicit Mini termination authority. This also migrates old
        # terminal-shaped action receipts at their first application.
        _normalize_provider_blocked_failure_metadata(metadata)
        _normalize_provider_exposure_metadata(metadata)
        self._accrue_provider_exposure(metadata)
        # The action receipt is now durable. Remove its exact live-tracker
        # prefix immediately so a later hook failure/recycle cannot charge the
        # same physical dispatch twice. Any dispatch started by the apply hook
        # is added to this still-linked tracker afterward and remains visible
        # as a new delta.
        tracker = self._inflight_provider_exposure_tracker
        settle = getattr(tracker, "settle_all_current_exposure", None)
        if callable(settle):
            settle()
        selected_projection_invalidated = bool(
            metadata.get("selected_work_projection_invalidated")
        )
        zero_provider_projection_invalidation = bool(
            selected_projection_invalidated
            and metadata.get(
                "selected_work_projection_zero_provider",
                True,
            )
            and not outcome.progress
        )
        graph_statement_typecheck_pending = bool(
            metadata.get("graph_native_statement_typecheck_pending")
        )
        residual_dispatch_quarantined = bool(
            metadata.get("residual_goal_dispatch_quarantined")
        )
        residual_reattestation_pending = bool(
            metadata.get("residual_goal_reattestation_pending")
        )
        non_consuming_pre_provider_defer = bool(
            zero_provider_projection_invalidation
            or (
                metadata.get("zero_provider_failure")
                and metadata.get("paid_tool_infrastructure_disposition")
                != "infrastructure_after_launch"
            )
            or graph_statement_typecheck_pending
            or residual_dispatch_quarantined
            or residual_reattestation_pending
        )
        cooperative_provider_yield = bool(
            metadata.get("provider_call_quantum_exhausted")
            and metadata.get("llm_failure_kind")
            in {
                "llm_provider_quantum_exhausted",
                "provider_dispatch_attempt_limit_exhausted",
            }
            and metadata.get("llm_retryable")
        )
        post_provider_receipt_infrastructure_failure = bool(
            metadata.get("post_provider_receipt_infrastructure_failure")
        )
        settlement_retry_yield = bool(metadata.get("settlement_retry_yield"))
        if non_consuming_pre_provider_defer:
            # Both action-boundary prompt failures and tool-loop dispatch
            # failures, plus an inconclusive mandatory statement typecheck,
            # represent controller/infra work rather than a mathematical
            # repair attempt. Normalize the accounting contract centrally.
            metadata["preserve_action_budget"] = True
            metadata["refund_local_repair_quota"] = True
            metadata["iteration_neutral"] = True
            metadata["scheduler_neutral"] = True
            metadata["stagnation_neutral"] = True
            metadata["hard_pivot_neutral"] = True
        if self._persistent_infrastructure_defer(metadata):
            # Normalize every typed persistent outage at the scheduler seam.
            # Producers should set this flag for clarity, but a generic action
            # exception or legacy typed producer must not become terminal just
            # because it omitted the routing hint.
            metadata["defer_selected_frontier_action"] = True
            metadata["preserve_frontier_work"] = True
        # Snapshot the INCOMING progress flags before anything mutates
        # ``metadata``.  ``outcome`` is rebound below to an object carrying this
        # working dict, so a later ``outcome.metadata`` read observes our own
        # updates rather than what the action reported — and the progress
        # invariants below exist precisely to compare those two states.
        incoming_strong_progress = bool(metadata.get("strong_progress"))
        incoming_declares_strong_progress = "strong_progress" in metadata
        # Establish the authoritative solved state before *any* downstream
        # bookkeeping. A root candidate rejected by the finalization contract
        # must not resolve theory needs, clear deferred work, discharge repair
        # state, or earn any other solved-dependent transition.
        root_finalization_metadata = self._apply_root_finalization(outcome)
        metadata.update(root_finalization_metadata)
        effective_solved = self._apply_effective_solved_gate(
            outcome,
            metadata,
            root_finalization_metadata,
        )
        def queued_verifier_work_after_current_outcome() -> Tuple[
            bool,
            Optional[Action],
        ]:
            for candidate_action in self.actions:
                owns_recheck = getattr(
                    candidate_action,
                    "has_answer_safe_recheck_work",
                    None,
                )
                if not callable(owns_recheck):
                    continue
                exclude_active = bool(
                    str(getattr(candidate_action, "id", "") or "")
                    == str(outcome.action_id or "")
                    and metadata.get("answer_safe_recheck_verifier_only_retry")
                    and str(metadata.get("lean_verdict") or "")
                    not in {"", "lean_infra_error"}
                    and not metadata.get("answer_safe_recheck_pending")
                )
                try:
                    if owns_recheck(exclude_active=exclude_active):
                        return True, candidate_action
                except Exception:
                    # Fail closed: an uninspectable paid continuation remains
                    # stronger than a provider terminal receipt.
                    return True, candidate_action
            return False, None

        if (
            not effective_solved
            and not bool(
                metadata.get(
                    "recovered_finalizer_candidate_adjudication_pending"
                )
            )
            and not str(metadata.get("llm_failure_kind") or "").strip()
            and not bool(metadata.get("terminal_failure"))
            and str(
                metadata.get("recovered_finalizer_failure_kind") or ""
            ).strip()
        ):
            # Primary Lean acceptance is provisional for child work and root
            # candidates. Only canonical root finalization can make the
            # provider-side result irrelevant. Child progress and a vetoed
            # root retain their independent provider scheduling receipt.
            from .actions.conversation_turn import (
                _activated_recovered_finalizer_failure_metadata,
            )

            metadata.update(
                _activated_recovered_finalizer_failure_metadata(metadata)
            )
        if (
            not effective_solved
            and metadata.get("answer_safe_recheck_verifier_only_retry")
            and str(metadata.get("lean_verdict") or "")
            in {
                "lean_rejected",
                "lean_accepted",
                "graph_native_lean_accepted",
                "graph_native_formalization_accepted",
            }
            and not metadata.get("answer_safe_recheck_pending")
        ):
            verifier_work_remains, _owner = (
                queued_verifier_work_after_current_outcome()
            )
            if not verifier_work_remains:
                for action in self.actions:
                    take_terminal = getattr(
                        action,
                        "take_answer_safe_terminal_provider_failure",
                        None,
                    )
                    if not callable(take_terminal):
                        continue
                    held_terminal = dict(take_terminal() or {})
                    if held_terminal:
                        if str(metadata.get("lean_verdict") or "") in {
                            "lean_accepted",
                            "graph_native_lean_accepted",
                            "graph_native_formalization_accepted",
                        }:
                            # The original failing provider action already
                            # owns its exact scheduler defer.  Successful
                            # mathematics on another verifier lane consumes
                            # only the held global-stop authority; attributing
                            # the receipt to this outcome would pause the
                            # healthy action and reopen the failed one.
                            metadata[
                                "held_provider_terminal_cleared_after_verified_progress"
                            ] = True
                        else:
                            metadata.update(held_terminal)
                        break
        recovered_terminal_after_verified_candidate = bool(
            metadata.get("recovered_finalizer_provider_receipt_activated")
            and metadata.get("terminal_failure")
            and str(metadata.get("lean_verdict") or "")
            in {
                "lean_accepted",
                "graph_native_lean_accepted",
                "graph_native_formalization_accepted",
            }
        )
        terminal_provider_with_queued_recheck = False
        terminal_recheck_owner: Optional[Action] = None
        if (
            metadata.get("terminal_failure")
            and str(metadata.get("llm_failure_kind") or "").strip()
        ):
            (
                terminal_provider_with_queued_recheck,
                terminal_recheck_owner,
            ) = queued_verifier_work_after_current_outcome()
        if terminal_provider_with_queued_recheck:
            # Provider/account failure cannot revoke an older paid proof that
            # now needs only Lean. Retire this failed selected projection and
            # leave the conversation action available solely so the scheduler
            # can select and adjudicate its exact parked target.
            provider_terminal_reason = str(
                metadata.get("terminal_failure_reason")
                or metadata.get("llm_failure_kind")
                or "llm_provider_unavailable"
            ).strip()
            hold_terminal = getattr(
                terminal_recheck_owner,
                "hold_answer_safe_terminal_provider_failure",
                None,
            )
            if callable(hold_terminal):
                hold_terminal(metadata)
            metadata.update(
                {
                    "terminal_failure": False,
                    "terminal_failure_reason": "",
                    "llm_retryable": False,
                    "llm_failure_scope": "scoped",
                    "scoped_failure_reason": provider_terminal_reason,
                    "defer_selected_frontier_action": True,
                    "preserve_frontier_work": False,
                    "selected_work_projection_invalidated": True,
                    "recovered_finalizer_terminal_provider_only": True,
                    "provider_terminal_deferred_for_verifier_work": True,
                }
            )
        if recovered_terminal_after_verified_candidate:
            # Provider/account exhaustion is independent of mathematics that
            # Lean has already verified. Fence the affected provider-backed
            # action family, but leave deterministic graph/root closure able
            # to consume the accepted candidate. The paired selected target
            # is complete or awaiting canonical closure, so never resurrect
            # it as a failed model frontier item.
            recovered_terminal_reason = str(
                metadata.get("terminal_failure_reason")
                or metadata.get("recovered_finalizer_failure_reason")
                or "llm_provider_unavailable"
            ).strip()
            metadata.update(
                {
                    "terminal_failure": False,
                    "terminal_failure_reason": "",
                    "llm_retryable": False,
                    "llm_failure_scope": "scoped",
                    "scoped_failure_reason": recovered_terminal_reason,
                    "defer_selected_frontier_action": True,
                    "preserve_frontier_work": False,
                    "selected_work_projection_invalidated": True,
                    "recovered_finalizer_terminal_provider_only": True,
                }
            )
        outcome = replace(
            outcome,
            solved=effective_solved,
            metadata=metadata,
        )
        theory_library = getattr(self, "theory_library", None)
        selected_theory_need_id = str(
            (self.selected_work_item_record or {}).get("theory_need_id") or ""
        ).strip()
        if not selected_theory_need_id and self.selected_work_item is not None:
            selected_theory_need_id = str(
                self.theory_need_ids_by_frontier_key.get(
                    self._frontier_work_key(self.selected_work_item),
                    "",
                )
                or ""
            ).strip()
        if (
            self.selected_work_item is not None
            and theory_library is not None
            and selected_theory_need_id
        ):
            selected_theory_record = None
            try:
                selected_theory_record = theory_library.needs.get(
                    selected_theory_need_id
                )
            except Exception as exc:
                self._defer_optional_theory_bookkeeping(
                    metadata,
                    operation="need_get",
                    exc=exc,
                )
            offered_bundle_id = str(metadata.get("theory_bundle_id") or "").strip()
            if (
                outcome.action_id in {"domain_theory", "domain_theory_build"}
                and offered_bundle_id
                and offered_bundle_id in self.theory_imported_bundle_ids
            ):
                self.theory_consumer_bundle_ids_by_need_id[selected_theory_need_id] = (
                    tuple(self.theory_imported_bundle_ids)
                )
            if bool(metadata.get("theory_context_progress")):
                # New verified context changes the proof consumer's inputs.
                # Re-open every non-theory lane for this exact frontier item;
                # retrieval/build applicability still guards their own stages.
                for candidate_id in self._frontier_candidate_ids_for_work_item(
                    self.selected_work_item
                ):
                    if candidate_id in {"domain_theory", "domain_theory_build"}:
                        continue
                    action_key = self._frontier_action_key(
                        self.selected_work_item,
                        candidate_id,
                    )
                    self.consumed_frontier_action_keys.discard(action_key)
                    self.skipped_frontier_action_keys.discard(action_key)
                    self.model_call_deferred_frontier_action_keys.discard(action_key)
                    self.model_call_deferred_frontier_action_metadata.pop(
                        action_key,
                        None,
                    )
            elif outcome.action_id not in {"domain_theory", "domain_theory_build"}:
                consumer_accepted = bool(
                    outcome.solved
                    or str(metadata.get("lean_verdict") or "")
                    in {
                        "lean_accepted",
                        "graph_native_lean_accepted",
                        "graph_native_formalization_accepted",
                    }
                )
                consumer_bundle_ids = tuple(
                    self.theory_consumer_bundle_ids_by_need_id.get(
                        selected_theory_need_id,
                        (),
                    )
                    or ()
                )
                consumer_bundle_id = (
                    consumer_bundle_ids[-1] if consumer_bundle_ids else ""
                )
                consumer_closure_valid = False
                if consumer_bundle_ids and set(consumer_bundle_ids).issubset(
                    self.theory_imported_bundle_ids
                ):
                    try:
                        snapshot = theory_library.snapshot(consumer_bundle_ids)
                        snapshot_ids = {
                            str(item.get("bundle_id") or "").strip()
                            for item in snapshot
                            if isinstance(item, dict)
                        }
                        consumer_closure_valid = set(consumer_bundle_ids).issubset(
                            snapshot_ids
                        )
                    except Exception as exc:
                        metadata["theory_consumer_context_rejected"] = str(exc)
                        self._defer_optional_theory_bookkeeping(
                            metadata,
                            operation="context_snapshot",
                            exc=exc,
                        )
                        context_invalidated = False
                        if selected_theory_record is not None:
                            try:
                                selected_theory_record, context_invalidated = (
                                    theory_library.needs.invalidate_context(
                                        selected_theory_need_id,
                                        diagnostic=(
                                            "consumer_context_revalidation_failed:"
                                            f"{exc}"
                                        ),
                                        expected_record=selected_theory_record,
                                    )
                                )
                            except Exception as invalidation_exc:
                                self._defer_optional_theory_bookkeeping(
                                    metadata,
                                    operation="context_invalidation",
                                    exc=invalidation_exc,
                                )
                        if context_invalidated:
                            self.theory_attempted_need_ids.discard(
                                selected_theory_need_id,
                            )
                            self.theory_need_attempt_counts.pop(
                                selected_theory_need_id,
                                None,
                            )
                            metadata["preserve_frontier_work"] = True
                            metadata["consume_selected_frontier_action"] = True
                            build_key = self._frontier_action_key(
                                self.selected_work_item,
                                "domain_theory_build",
                            )
                            self.consumed_frontier_action_keys.discard(build_key)
                            self.skipped_frontier_action_keys.discard(build_key)
                if (
                    consumer_accepted
                    and selected_theory_record is not None
                    and consumer_bundle_id
                    and consumer_closure_valid
                ):
                    try:
                        theory_library.needs.record_outcome(
                            selected_theory_need_id,
                            status="resolved",
                            diagnostic=(
                                "verified_consumer_satisfied_with_theory_context"
                            ),
                            bundle_id=consumer_bundle_id,
                            bundle_ids=consumer_bundle_ids,
                            count_attempt=False,
                        )
                    except Exception as exc:
                        self._defer_optional_theory_bookkeeping(
                            metadata,
                            operation="consumer_resolution",
                            exc=exc,
                        )
                    else:
                        self.theory_attempted_need_ids.add(selected_theory_need_id)
                        metadata["theory_need_resolved"] = selected_theory_need_id
                elif (
                    selected_theory_record is not None
                    and selected_theory_record.status == "context_available"
                    and selected_theory_need_id not in self.theory_attempted_need_ids
                ):
                    build_action = self.registered_action("domain_theory_build")
                    max_attempts = int(
                        getattr(build_action, "max_attempts_per_need", 2) or 2
                    )
                    attempts = int(
                        self.theory_need_attempt_counts.get(
                            selected_theory_need_id,
                            0,
                        )
                    )
                    if build_action is not None and attempts < max_attempts:
                        # The verified bundle did not yet discharge its
                        # consumer. Keep the work and reopen the build stage
                        # for one bounded refinement candidate.
                        metadata["preserve_frontier_work"] = True
                        metadata["consume_selected_frontier_action"] = True
                        build_key = self._frontier_action_key(
                            self.selected_work_item,
                            "domain_theory_build",
                        )
                        self.consumed_frontier_action_keys.discard(build_key)
                        self.skipped_frontier_action_keys.discard(build_key)
        terminal_failure_reason = str(
            metadata.get("terminal_failure_reason") or ""
        ).strip()
        scoped_failure_reason = str(metadata.get("scoped_failure_reason") or "").strip()
        failure_scope = str(
            metadata.get("llm_failure_scope")
            or metadata.get("terminal_failure_scope")
            or ""
        ).strip()
        if not failure_scope:
            failure_scope = llm_failure_scope(
                terminal_failure_reason or scoped_failure_reason
            )
        if failure_scope == "scoped" and terminal_failure_reason:
            scoped_failure_reason = scoped_failure_reason or terminal_failure_reason
        terminal_failure = bool(
            metadata.get("terminal_failure") or terminal_failure_reason
        )
        global_terminal_failure = bool(terminal_failure and failure_scope != "scoped")
        if failure_scope:
            metadata["llm_failure_scope"] = failure_scope
        if scoped_failure_reason:
            metadata["scoped_failure_reason"] = scoped_failure_reason
            selected_projection_invalidated = bool(
                metadata.get("selected_work_projection_invalidated")
            )
            if not selected_projection_invalidated:
                metadata["preserve_frontier_work"] = True
                metadata["defer_selected_frontier_action"] = True
            self.last_failure_reason = scoped_failure_reason
            retry_deadline_fields = {
                str(key): value
                for key, value in metadata.items()
                if str(key).startswith("llm_retry_deadline_")
            }
            self._record_event(
                {
                    "phase": (
                        "session_scoped_controller_failure"
                        if selected_projection_invalidated
                        else "session_scoped_llm_failure"
                    ),
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": scoped_failure_reason,
                    "scope": failure_scope or "scoped",
                    "kind": str(
                        metadata.get("llm_failure_kind")
                        or metadata.get("terminal_failure_kind")
                        or scoped_failure_reason
                        or ""
                    ).strip(),
                    **retry_deadline_fields,
                    "provider_attempts": list(metadata.get("provider_attempts") or []),
                    "retry_count": int(metadata.get("retry_count") or 0),
                    "verdict": (
                        "scoped_controller_failure_recorded"
                        if selected_projection_invalidated
                        else "scoped_llm_failure_recorded"
                    ),
                }
            )
        metadata["terminal_failure"] = bool(global_terminal_failure)
        if global_terminal_failure:
            if not terminal_failure_reason:
                terminal_failure_reason = "terminal_failure"
            self.terminal_failure_reason = terminal_failure_reason
            self.terminal_failure_kind = str(
                metadata.get("llm_failure_kind")
                or metadata.get("terminal_failure_kind")
                or ""
            ).strip()
            self.last_failure_reason = terminal_failure_reason
            try:
                setattr(self.dossier, "session_failure_reason", terminal_failure_reason)
                if self.terminal_failure_kind:
                    setattr(
                        self.dossier,
                        "session_failure_kind",
                        self.terminal_failure_kind,
                    )
            except Exception:
                pass
            self._record_event(
                {
                    "phase": "session_terminal_failure",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": terminal_failure_reason,
                    "kind": self.terminal_failure_kind,
                    "verdict": "terminal_failure_recorded",
                }
            )
        budget = self.budgets.get(outcome.action_id)
        if budget is None:
            action = self.registered_action(outcome.action_id)
            budget = ActionBudget(
                max_invocations=1,
                max_total_seconds=0.0,
                scope=(
                    self._declared_action_budget_scope(action)
                    if action is not None
                    else "session"
                ),
            )
            self.budgets[outcome.action_id] = budget
        bounded_conversation_budget = bool(
            str(outcome.action_id or "").startswith("conversation_turn")
            and not bool(self.conversation_budget_topups_enabled)
        )
        answer_safe_recheck_pending = bool(metadata.get("answer_safe_recheck_pending"))
        counterexample_certification_infrastructure = bool(
            metadata.get("llm_failure_kind")
            == "certify_counterexample_infrastructure_error"
            and metadata.get("scoped_failure_reason") == "llm_network_error"
            and metadata.get("llm_retryable")
        )
        preserve_action_budget = (
            bool(
                metadata.get("preserve_action_budget")
                or metadata.get("policy_repair_redirect")
            )
            and (
                not bounded_conversation_budget
                or non_consuming_pre_provider_defer
                or answer_safe_recheck_pending
                or counterexample_certification_infrastructure
                or cooperative_provider_yield
                or post_provider_receipt_infrastructure_failure
                or settlement_retry_yield
            )
            and (
                outcome.exception is None
                or non_consuming_pre_provider_defer
                or post_provider_receipt_infrastructure_failure
            )
        )
        if preserve_action_budget:
            self._record_event(
                {
                    "phase": "session_action_budget_preserved",
                    "action_id": outcome.action_id,
                    "iteration": self.iteration,
                    "reason": str(
                        metadata.get("repair_redirect_reason")
                        or metadata.get("rejection_reason")
                        or ""
                    ),
                    "cost_seconds": round(outcome.cost_seconds, 4),
                    "verdict": "policy_repair_redirect_budget_preserved",
                }
            )
        else:
            budget.consume(outcome.cost_seconds)
        cleanup_continuation_identity = str(
            metadata.get("recursive_helper_cleanup_continuation_identity") or ""
        ).strip()
        cleanup_continuation_granted = bool(
            metadata.get("recursive_helper_cleanup_continuation_granted")
            and cleanup_continuation_identity
        )
        if cleanup_continuation_granted:
            action = self.registered_action(outcome.action_id)
            owns_continuation = getattr(
                action,
                "owns_cleanup_retry_continuation",
                None,
            )
            continuation_is_current = False
            if callable(owns_continuation):
                try:
                    continuation_is_current = bool(
                        owns_continuation(cleanup_continuation_identity)
                    )
                except Exception:
                    continuation_is_current = False
            if continuation_is_current:
                seen_cleanup_identities = (
                    self.recursive_helper_cleanup_continuation_identities
                )
                if cleanup_continuation_identity not in seen_cleanup_identities:
                    seen_cleanup_identities.add(cleanup_continuation_identity)
                    old_max_invocations = int(budget.max_invocations)
                    if (
                        budget.scope == "session"
                        and budget.max_invocations >= 0
                        and budget.invocations >= budget.max_invocations
                    ):
                        # One already-paid child frame may need one
                        # cleanup/replay dispatch after consuming the final
                        # configured action invocation. Extend the dispatcher
                        # quota; never refund the paid invocation or the node's
                        # mathematical attempt.
                        budget.max_invocations = int(budget.invocations) + 1
                    old_max_iterations = int(self.max_iterations or 0)
                    self.max_iterations = max(
                        old_max_iterations,
                        int(self.iteration or 0) + 2,
                    )
                    self._record_event(
                        {
                            "phase": "session_recursive_helper_cleanup_retry",
                            "iteration": int(self.iteration or 0),
                            "action_id": str(outcome.action_id or ""),
                            "continuation_identity": (cleanup_continuation_identity),
                            "old_max_invocations": old_max_invocations,
                            "max_invocations": int(budget.max_invocations),
                            "old_max_iterations": old_max_iterations,
                            "max_iterations": int(self.max_iterations or 0),
                            "paid_invocation_refunded": False,
                            "verdict": ("one_shot_continuation_headroom_granted"),
                        }
                    )
        verifier_continuation_identity = str(
            metadata.get("primary_verifier_continuation_identity") or ""
        ).strip()
        verifier_continuation_granted = bool(
            metadata.get("primary_verifier_continuation_granted")
            and verifier_continuation_identity
        )
        if verifier_continuation_granted:
            action = self.registered_action(outcome.action_id)
            owns_continuation = getattr(
                action,
                "owns_primary_verifier_retry_continuation",
                None,
            )
            continuation_is_current = False
            if callable(owns_continuation):
                try:
                    continuation_is_current = bool(
                        owns_continuation(verifier_continuation_identity)
                    )
                except Exception:
                    continuation_is_current = False
            if (
                continuation_is_current
                and verifier_continuation_identity
                not in self.primary_verifier_continuation_identities
            ):
                self.primary_verifier_continuation_identities.add(
                    verifier_continuation_identity
                )
                old_max_invocations = int(budget.max_invocations)
                if (
                    budget.scope == "session"
                    and budget.max_invocations >= 0
                    and budget.invocations >= budget.max_invocations
                ):
                    budget.max_invocations = int(budget.invocations) + 1
                old_max_iterations = int(self.max_iterations or 0)
                self.max_iterations = max(
                    old_max_iterations,
                    int(self.iteration or 0) + 2,
                )
                self._record_event(
                    {
                        "phase": "session_primary_verifier_retry",
                        "iteration": int(self.iteration or 0),
                        "action_id": str(outcome.action_id or ""),
                        "continuation_identity": verifier_continuation_identity,
                        "old_max_invocations": old_max_invocations,
                        "max_invocations": int(budget.max_invocations),
                        "old_max_iterations": old_max_iterations,
                        "max_iterations": int(self.max_iterations or 0),
                        "paid_invocation_refunded": False,
                        "verdict": "one_shot_continuation_headroom_granted",
                    }
                )
        paid_tool_continuation_identity = str(
            metadata.get("paid_tool_continuation_identity") or ""
        ).strip()
        paid_tool_continuation_granted = bool(
            metadata.get("paid_tool_continuation_granted")
            and paid_tool_continuation_identity
        )
        paid_tool_continuation_is_current = False
        if paid_tool_continuation_granted:
            action = self.registered_action(outcome.action_id)
            owns_continuation = getattr(
                action,
                "owns_paid_tool_retry_continuation",
                None,
            )
            if callable(owns_continuation):
                try:
                    paid_tool_continuation_is_current = bool(
                        owns_continuation(
                            paid_tool_continuation_identity,
                            self,
                        )
                    )
                except Exception:
                    paid_tool_continuation_is_current = False
        if (
            paid_tool_continuation_is_current
            and paid_tool_continuation_identity
            not in self.paid_tool_continuation_identities
        ):
            self.paid_tool_continuation_identities.add(paid_tool_continuation_identity)
            old_max_invocations = int(budget.max_invocations)
            if (
                budget.scope == "session"
                and budget.max_invocations >= 0
                and budget.invocations >= budget.max_invocations
            ):
                budget.max_invocations = int(budget.invocations) + 1
            old_max_iterations = int(self.max_iterations or 0)
            self.max_iterations = max(
                old_max_iterations,
                int(self.iteration or 0) + 2,
            )
            self._record_event(
                {
                    "phase": "session_paid_tool_retry",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(outcome.action_id or ""),
                    "continuation_identity": paid_tool_continuation_identity,
                    "old_max_invocations": old_max_invocations,
                    "max_invocations": int(budget.max_invocations),
                    "old_max_iterations": old_max_iterations,
                    "max_iterations": int(self.max_iterations or 0),
                    "paid_invocation_refunded": False,
                    "verdict": "one_shot_continuation_headroom_granted",
                }
            )
        durable_tool_continuation_identity = str(
            metadata.get("durable_progress_tool_continuation_identity") or ""
        ).strip()
        durable_tool_continuation_granted = bool(
            metadata.get("durable_progress_tool_continuation_granted")
            and durable_tool_continuation_identity
        )
        durable_tool_continuation_is_current = False
        action = self.registered_action(outcome.action_id)
        if durable_tool_continuation_granted and action is not None:
            owns_continuation = getattr(
                action,
                "owns_durable_progress_tool_continuation",
                None,
            )
            if callable(owns_continuation):
                try:
                    durable_tool_continuation_is_current = bool(
                        owns_continuation(
                            durable_tool_continuation_identity,
                            self,
                        )
                    )
                except Exception:
                    durable_tool_continuation_is_current = False
        if durable_tool_continuation_is_current:
            payload_reader = getattr(
                action,
                "durable_progress_tool_continuation_payload",
                None,
            )
            replay_payload: Dict[str, Any] = {}
            if callable(payload_reader):
                try:
                    replay_payload = dict(
                        payload_reader(
                            durable_tool_continuation_identity,
                            self,
                        )
                        or {}
                    )
                except Exception:
                    replay_payload = {}
            if not replay_payload:
                durable_tool_continuation_is_current = False
        if durable_tool_continuation_is_current:
            selected_work = dict(
                metadata.get(
                    "durable_progress_tool_continuation_selected_work"
                )
                or self.selected_work_item_record
                or {}
            )
            self.durable_progress_tool_continuation = {
                "identity": durable_tool_continuation_identity,
                "action_id": str(outcome.action_id or ""),
                "selected_work_item_record": selected_work,
                "replay_payload": copy.deepcopy(replay_payload),
            }
            if (
                durable_tool_continuation_identity
                not in self.durable_progress_tool_continuation_identities
            ):
                self.durable_progress_tool_continuation_identities.add(
                    durable_tool_continuation_identity
                )
                old_max_invocations = int(budget.max_invocations)
                if (
                    budget.scope == "session"
                    and budget.max_invocations >= 0
                    and budget.invocations >= budget.max_invocations
                ):
                    budget.max_invocations = int(budget.invocations) + 1
                old_max_iterations = int(self.max_iterations or 0)
                self.max_iterations = max(
                    old_max_iterations,
                    int(self.iteration or 0) + 2,
                )
                self._record_event(
                    {
                        "phase": "session_durable_tool_continuation",
                        "iteration": int(self.iteration or 0),
                        "action_id": str(outcome.action_id or ""),
                        "continuation_identity": (
                            durable_tool_continuation_identity
                        ),
                        "old_max_invocations": old_max_invocations,
                        "max_invocations": int(budget.max_invocations),
                        "old_max_iterations": old_max_iterations,
                        "max_iterations": int(self.max_iterations or 0),
                        "paid_invocation_refunded": False,
                        "verdict": "one_shot_continuation_headroom_granted",
                    }
                )
        elif durable_tool_continuation_granted:
            self.durable_progress_tool_continuation = {}
        if (
            outcome.exception is not None
            and not bool(metadata.get("selected_work_projection_invalidated"))
            and not (
                non_consuming_pre_provider_defer
                or self._persistent_infrastructure_defer(metadata)
            )
        ):
            budget.mark_exhausted(f"raised:{type(outcome.exception).__name__}")
        self._publish_owned_verified_helpers_to_cache(action_id=outcome.action_id)
        action_parent_progress = bool(metadata.get("parent_progress"))
        helper_progress_metadata = helper_progress_metadata_for_accepted_helpers(
            self.dossier,
            outcome.helpers_added,
        )
        metadata.update(helper_progress_metadata)
        if action_parent_progress and not outcome.helpers_added:
            metadata["parent_progress"] = True
        root_strong_progress = bool(
            root_finalization_metadata.get("root_finalization_accepted")
        )
        preexisting_strong_progress = incoming_strong_progress
        action_start_formal_evidence = set(
            self._action_start_frontier_formal_evidence or ()
        )
        action_end_formal_evidence = set(self._durable_formal_progress_evidence())
        fresh_action_formal_evidence = sorted(
            action_end_formal_evidence - action_start_formal_evidence
        )
        non_helper_parent_progress = bool(
            preexisting_strong_progress
            and not outcome.helpers_added
            and action_parent_progress
            and fresh_action_formal_evidence
        )
        non_helper_structural_strong = bool(
            preexisting_strong_progress
            and not outcome.helpers_added
            and fresh_action_formal_evidence
        )
        ledger_parent_progress = bool(
            helper_progress_metadata.get("parent_progress")
            or helper_progress_metadata.get("strong_progress")
        )
        final_strong_progress = bool(
            root_strong_progress
            or non_helper_structural_strong
            or ledger_parent_progress
        )
        if preexisting_strong_progress and not final_strong_progress:
            self._increment_dossier_metric(
                "mini_session_unverified_strong_progress_rejected",
                1,
            )
            self._record_event(
                {
                    "phase": "session_run_governor",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(outcome.action_id or ""),
                    "fresh_formal_evidence_count": len(fresh_action_formal_evidence),
                    "verdict": "unverified_strong_progress_rejected",
                }
            )
        if (
            preexisting_strong_progress
            and outcome.helpers_added
            and not final_strong_progress
        ):
            self._increment_dossier_metric(
                "mini_session_progress_invariant_false_strong_weak_helper",
                1,
            )
        if (
            ledger_parent_progress
            and incoming_declares_strong_progress
            and not preexisting_strong_progress
        ):
            self._increment_dossier_metric(
                "mini_session_progress_invariant_parent_progress_undercredited",
                1,
            )
        metadata["strong_progress"] = final_strong_progress
        selected_work_type = str(
            (self.selected_work_item_record or {}).get("work_type")
            or (
                self._work_item_field(self.selected_work_item, "work_type", "")
                if self.selected_work_item is not None
                else ""
            )
            or ""
        ).strip()
        selected_root_frontier_quantum = selected_work_type in {
            "root_repair",
            "assemble_route",
        }
        selected_scoped_frontier_quantum = bool(
            self.selected_work_item is not None
            and selected_work_type
            and not selected_root_frontier_quantum
        )
        previous_scoped_fairness_streak = int(
            self.scoped_frontier_quanta_since_root_authoring or 0
        )
        completed_root_fairness_quantum = bool(
            (
                selected_root_frontier_quantum
                or (
                    self.selected_work_item is None
                    and self._is_root_authoring_fairness_action(outcome.action_id)
                )
            )
            and outcome.exception is None
            and not preserve_action_budget
            and not bool(metadata.get("scheduler_neutral"))
            and not bool(metadata.get("iteration_neutral"))
            and not self._persistent_infrastructure_defer(metadata)
        )
        if final_strong_progress or completed_root_fairness_quantum:
            self.scoped_frontier_quanta_since_root_authoring = 0
        elif (
            selected_scoped_frontier_quantum
            and outcome.exception is None
            and not preserve_action_budget
            and not bool(metadata.get("scheduler_neutral"))
            and not bool(metadata.get("iteration_neutral"))
            and not self._persistent_infrastructure_defer(metadata)
        ):
            self.scoped_frontier_quanta_since_root_authoring = (
                previous_scoped_fairness_streak + 1
            )
        if previous_scoped_fairness_streak != int(
            self.scoped_frontier_quanta_since_root_authoring or 0
        ):
            self._record_event(
                {
                    "phase": "session_frontier_fairness",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(outcome.action_id or ""),
                    "selected_work_type": selected_work_type,
                    "previous_scoped_quanta": previous_scoped_fairness_streak,
                    "scoped_quanta_since_root_authoring": int(
                        self.scoped_frontier_quanta_since_root_authoring or 0
                    ),
                    "strong_progress": final_strong_progress,
                    "verdict": (
                        "scoped_quantum_accrued"
                        if int(self.scoped_frontier_quanta_since_root_authoring or 0)
                        > previous_scoped_fairness_streak
                        else "scoped_quantum_streak_reset"
                    ),
                }
            )
        self._accrue_run_governor_elapsed()
        if final_strong_progress:
            self.run_governor_last_strong_progress_elapsed_s = float(
                self.run_governor_elapsed_s or 0.0
            )
            self.run_governor_actions_since_strong_progress = 0
        else:
            self.run_governor_actions_since_strong_progress = max(
                0,
                int(self.run_governor_actions_since_strong_progress or 0) + 1,
            )
        if final_strong_progress:
            if root_strong_progress:
                metadata["strong_progress_reason"] = "root_finalization"
            elif ledger_parent_progress or non_helper_parent_progress:
                metadata["strong_progress_reason"] = "parent_progress"
            else:
                metadata["strong_progress_reason"] = "action_structural"
        elif metadata.get("theory_progress"):
            metadata["strong_progress_reason"] = "theory_progress_only"
        else:
            metadata["strong_progress_reason"] = "none"
        if final_strong_progress:
            self._record_event(
                {
                    "phase": "session_run_governor",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(outcome.action_id or ""),
                    "elapsed_s": float(self.run_governor_elapsed_s or 0.0),
                    "strong_progress_reason": str(
                        metadata.get("strong_progress_reason") or ""
                    ),
                    "verdict": "strong_progress_window_reset",
                }
            )
        paid_no_progress_action = bool(
            not final_strong_progress
            and outcome.exception is None
            and not preserve_action_budget
            and not bool(metadata.get("scheduler_neutral"))
            and not bool(metadata.get("iteration_neutral"))
            and not self._persistent_infrastructure_defer(metadata)
        )
        conversation_fresh_formal_evidence: Set[str] = set()
        if str(outcome.action_id or "").startswith("conversation_turn"):
            conversation_fresh_formal_evidence = set(
                self._durable_formal_progress_evidence()
            ) - set(self._action_start_frontier_formal_evidence or ())
        if final_strong_progress:
            self.identical_no_progress_actions = 0
            self.identical_no_progress_search_signature = ""
            self.identical_no_progress_action_families_seen.clear()
            self.no_progress_semantic_signature_counts.clear()
            self.no_progress_semantic_signature_order.clear()
            self.no_progress_semantic_signature_action_families.clear()
        elif paid_no_progress_action:
            before_signature = str(self._action_start_durable_progress_signature or "")
            after_signature = self._durable_search_progress_signature()
            unchanged = bool(
                before_signature
                and after_signature
                and before_signature == after_signature
            )
            recurrence_count = self.record_no_progress_semantic_signature(
                after_signature
            )
            action = self.registered_action(outcome.action_id)
            family = (
                self._no_progress_action_family(action)
                if action is not None
                else str(outcome.action_id or "").strip()
            )
            if family:
                self.identical_no_progress_action_families_seen.add(family)
                self._record_semantic_signature_action_family(
                    before_signature,
                    family,
                )
            metadata.update(
                {
                    "identical_no_progress_state_unchanged": unchanged,
                    "identical_no_progress_actions": int(
                        self.identical_no_progress_actions or 0
                    ),
                    "max_identical_no_progress_actions": int(
                        self.max_identical_no_progress_actions or 0
                    ),
                    "no_progress_semantic_signature_recurrence_count": (
                        recurrence_count
                    ),
                    "max_no_progress_semantic_signature_recurrences": int(
                        self.max_no_progress_semantic_signature_recurrences or 0
                    ),
                }
            )

        proof_work_attempt_recorded = bool(
            paid_no_progress_action
            and not outcome.progress
            and budget.scope == "proof_work"
            and bool(metadata.get("semantic_budget_step_consumed"))
            and self.selected_work_item is not None
            and not bool(
                dict(metadata.get("child_closure_execution_status") or {}).get(
                    "all_operations_deferred_before_launch"
                )
            )
        )
        if proof_work_attempt_recorded:
            attempt_identity = str(
                self._action_start_proof_work_semantic_identity or ""
            )
            if not attempt_identity:
                attempt_identity = self._proof_work_semantic_attempt_identity(
                    self.selected_work_item,
                    action_id=outcome.action_id,
                )
            attempt_count = self._record_proof_work_no_progress_attempt_identity(
                attempt_identity
            )
            self._action_start_proof_work_semantic_identity = ""
            if attempt_count > 0:
                attempt_limit = max(
                    0,
                    int(self.max_proof_work_no_progress_attempts or 0),
                )
                metadata.update(
                    {
                        "proof_work_no_progress_attempt_count": attempt_count,
                        "proof_work_no_progress_attempt_limit": attempt_limit,
                        "proof_work_semantic_attempt_exhausted": bool(
                            attempt_limit > 0 and attempt_count >= attempt_limit
                        ),
                    }
                )
                if attempt_limit > 0 and attempt_count >= attempt_limit:
                    self._record_event(
                        {
                            "phase": "session_proof_work_semantic_budget",
                            "iteration": int(self.iteration or 0),
                            "action_id": str(outcome.action_id or ""),
                            "selected_work_item": dict(
                                self.selected_work_item_record or {}
                            ),
                            "attempt_count": attempt_count,
                            "attempt_limit": attempt_limit,
                            "verdict": "unchanged_proof_contract_exhausted",
                        }
                    )
        observations = getattr(
            getattr(self, "dossier", None),
            "action_value_observations",
            None,
        )
        # Preparatory/instrumentation outcomes (FormalStateSearch rotation,
        # falsification probes, etc.) mark scheduler_neutral so they do not
        # advance stagnation. Budget-preserving controller redirects similarly
        # decline to consume the action quota (`preserve_action_budget` local
        # above). Both must stay out of empirical calibration: counting them
        # as attempts with zero root_progress poisons the success rate and can
        # starve the whole action lane under global root-value ranking.
        # Align calibration with budget consumption.
        calibrate_action_value = not (
            bool(metadata.get("scheduler_neutral")) or preserve_action_budget
        )
        if isinstance(observations, dict) and calibrate_action_value:
            action_observation = observations.setdefault(
                str(outcome.action_id or "unknown"),
                {
                    "attempts": 0.0,
                    "seconds": 0.0,
                    "root_progress": 0.0,
                    "verified_facts": 0.0,
                },
            )
            action_observation["attempts"] = (
                float(action_observation.get("attempts", 0.0) or 0.0) + 1.0
            )
            action_observation["seconds"] = float(
                action_observation.get("seconds", 0.0) or 0.0
            ) + max(0.0, float(outcome.cost_seconds or 0.0))
            if final_strong_progress:
                action_observation["root_progress"] = (
                    float(action_observation.get("root_progress", 0.0) or 0.0) + 1.0
                )
            calibrated_verified_helper_names = {
                str(name or "").strip()
                for name in (
                    *tuple(
                        helper_progress_metadata.get("theory_progress_helper_names", ())
                        or ()
                    ),
                    *tuple(
                        helper_progress_metadata.get("parent_progress_helper_names", ())
                        or ()
                    ),
                )
                if str(name or "").strip()
            }
            if calibrated_verified_helper_names:
                action_observation["verified_facts"] = float(
                    action_observation.get("verified_facts", 0.0) or 0.0
                ) + float(len(calibrated_verified_helper_names))
        if not global_terminal_failure:
            metadata["progress_continuation_granted"] = (
                self._grant_distinct_strong_progress_continuation(
                    action_id=outcome.action_id,
                    budget=budget,
                    strong_progress=final_strong_progress,
                    outcome=outcome,
                )
            )
            self._grant_frontier_progress_retry(
                outcome=outcome,
                metadata=metadata,
                budget=budget,
            )
        else:
            self._action_start_durable_progress_signature = ""
            self._action_start_frontier_formal_signature = ""
            self._action_start_frontier_formal_evidence = ()
            self._action_start_frontier_action_key = None
        conversation_attempt_identity = str(
            self._action_start_proof_work_semantic_identity or ""
        ).strip()
        conversation_static_root_identity = str(
            self._action_start_conversation_static_root_identity or ""
        ).strip()
        conversation_semantic_signature = str(
            metadata.get("semantic_no_progress_signature") or ""
        ).strip()
        completed_identical_conversation_wall = bool(
            str(outcome.action_id or "").startswith("conversation_turn")
            and paid_no_progress_action
            and not outcome.progress
            and not global_terminal_failure
            and conversation_attempt_identity
            and conversation_semantic_signature
            and len(conversation_semantic_signature) <= 128
            and metadata.get("semantic_no_progress_detected") is True
            and metadata.get("llm_response_recorded") is True
            and _nonnegative_metadata_int(metadata, "provider_calls_completed") > 0
            and not conversation_fresh_formal_evidence
            and not bool(metadata.get("frontier_progress_retry_granted"))
            and not bool(metadata.get("policy_repair_redirect"))
            and not bool(metadata.get("preserve_frontier_work"))
        )
        if completed_identical_conversation_wall:
            static_root_peak_before = self._proof_work_semantic_peak_attempt_count(
                conversation_static_root_identity
            )
            attempt_count = (
                self._record_conversation_semantic_no_progress_attempt_identity(
                    conversation_attempt_identity,
                    conversation_semantic_signature,
                )
            )
            self._record_conversation_static_root_attempt(
                exact_identity=conversation_attempt_identity,
                static_root_identity=conversation_static_root_identity,
                semantic_signature=conversation_semantic_signature,
                static_root_peak_before=static_root_peak_before,
            )
            if attempt_count > 0:
                attempt_limit = max(
                    0,
                    int(self.max_proof_work_no_progress_attempts or 0),
                )
                exhausted = bool(attempt_limit > 0 and attempt_count >= attempt_limit)
                metadata.update(
                    {
                        "conversation_semantic_no_progress_attempt_count": (
                            attempt_count
                        ),
                        "conversation_semantic_no_progress_attempt_limit": (
                            attempt_limit
                        ),
                        "conversation_semantic_no_progress_exhausted": exhausted,
                    }
                )
                self._record_event(
                    {
                        "phase": "session_conversation_semantic_repeat_budget",
                        "iteration": int(self.iteration or 0),
                        "action_id": str(outcome.action_id or ""),
                        "semantic_signature": conversation_semantic_signature,
                        "attempt_count": attempt_count,
                        "attempt_limit": attempt_limit,
                        "verdict": (
                            "identical_semantic_wall_exhausted"
                            if exhausted
                            else "identical_semantic_wall_recorded"
                        ),
                    }
                )
        self._action_start_proof_work_semantic_identity = ""
        self._action_start_conversation_static_root_identity = ""
        if str(outcome.action_id or "").startswith("conversation_turn"):
            self._action_start_frontier_formal_signature = ""
            self._action_start_frontier_formal_evidence = ()
            self._action_start_frontier_action_key = None
        if outcome.progress or root_strong_progress:
            if final_strong_progress:
                self._increment_dossier_metric(
                    "mini_session_strong_progress_outcomes", 1
                )
            else:
                self._increment_dossier_metric("mini_session_soft_progress_outcomes", 1)
                if metadata.get("theory_progress"):
                    self._increment_dossier_metric(
                        "mini_session_helper_progress_soft_weak_theory",
                        1,
                    )
                elif outcome.helpers_added:
                    self._increment_dossier_metric(
                        "mini_session_helper_progress_soft_alias",
                        1,
                    )
        if isinstance(outcome.metadata, dict):
            outcome.metadata.update(metadata)
        if isinstance(action_reported_outcome.metadata, dict):
            action_reported_outcome.metadata.update(metadata)
        self._apply_repair_ticket_bookkeeping(outcome, metadata)
        self.last_action_outcome_metadata = metadata
        giveup_cluster = self.last_action_outcome_metadata.get("giveup_cluster")
        if giveup_cluster:
            self.last_giveup_cluster = str(giveup_cluster)
            self.last_giveup_match = str(
                self.last_action_outcome_metadata.get("giveup_match") or ""
            )
        self._update_local_micro_theory_after_outcome(outcome, metadata)
        hard_pivot_triggered = self._maybe_trigger_hard_pivot(outcome)
        policy_repair_redirect = bool(metadata.get("policy_repair_redirect"))
        graph_policy_target_retired = False
        if policy_repair_redirect:
            graph_policy_reason = self._repair_ticket_policy_rejection_reason(metadata)
            graph_policy_target_retired = self._record_graph_policy_failure_observation(
                outcome,
                metadata,
                reason=graph_policy_reason,
            )
            if graph_policy_target_retired:
                metadata["preserve_frontier_work"] = False
                metadata["policy_repair_redirect"] = False
                metadata["graph_policy_target_retired"] = True
                if isinstance(outcome.metadata, dict):
                    outcome.metadata.update(
                        {
                            "preserve_frontier_work": False,
                            "policy_repair_redirect": False,
                            "graph_policy_target_retired": True,
                        }
                    )
                policy_repair_redirect = False
        local_repair_refunded = False
        if (
            bool(metadata.get("refund_local_repair_quota"))
            and (not bounded_conversation_budget or non_consuming_pre_provider_defer)
            and bool(getattr(self, "_repair_first_selected_local_forced", False))
        ):
            limit = max(0, int(self.local_repair_quota_limit or 0))
            self.local_repair_quota_remaining = min(
                limit,
                max(0, int(self.local_repair_quota_remaining or 0)) + 1,
            )
            self.local_repair_quota_used = max(
                0,
                int(self.local_repair_quota_used or 0) - 1,
            )
            signature_key = (
                str(getattr(self, "_repair_first_selected_signature_key", "") or "")
                or str(self.local_repair_quota_failure_signature or "")
                or str(self.local_repair_quota_reason or "")
                or "unknown"
            )
            used_by_signature = getattr(
                self,
                "local_repair_quota_used_by_signature",
                None,
            )
            if isinstance(used_by_signature, dict):
                used_by_signature[signature_key] = max(
                    0,
                    int(used_by_signature.get(signature_key, 0) or 0) - 1,
                )
            local_repair_refunded = True
            self._record_event(
                {
                    "phase": "session_local_repair_quota_refund",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": str(
                        metadata.get("repair_redirect_reason")
                        or metadata.get("rejection_reason")
                        or ""
                    ),
                    "failure_signature_key": signature_key,
                    "quota_remaining": int(self.local_repair_quota_remaining or 0),
                    "quota_used": int(self.local_repair_quota_used or 0),
                    "verdict": "policy_repair_redirect_quota_refunded",
                }
            )
        if bool(metadata.get("refund_conversation_phase_turn")) and (
            not bounded_conversation_budget
            or non_consuming_pre_provider_defer
            or counterexample_certification_infrastructure
            or cooperative_provider_yield
            or post_provider_receipt_infrastructure_failure
        ):
            role_key = str(metadata.get("role") or "").strip()
            if not role_key and self.conv is not None:
                role_key = str(getattr(self.conv, "role", "") or "").strip()
            counts = getattr(self, "_conversation_role_turn_counts", None)
            if role_key and isinstance(counts, dict):
                counts[role_key] = max(0, int(counts.get(role_key, 0) or 0) - 1)
                self._conversation_role_turn_counts = counts
                exposure_counts = getattr(
                    self,
                    "_conversation_role_turn_exposure_counts",
                    None,
                )
                if isinstance(exposure_counts, dict):
                    exposure_counts[role_key] = max(
                        0,
                        int(exposure_counts.get(role_key, 0) or 0) - 1,
                    )
                    self._conversation_role_turn_exposure_counts = exposure_counts
                self._record_event(
                    {
                        "phase": "session_conversation_phase_turn_refund",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "role": role_key,
                        "conversation_role_turn_count": int(
                            counts.get(role_key, 0) or 0
                        ),
                        "verdict": "policy_repair_redirect_phase_turn_refunded",
                    }
                )
        if bool(metadata.get("refund_conversation_absolute_turn")) and (
            not bounded_conversation_budget
            or non_consuming_pre_provider_defer
            or cooperative_provider_yield
            or post_provider_receipt_infrastructure_failure
        ):
            self._conversation_turn_count = max(
                0,
                int(getattr(self, "_conversation_turn_count", 0) or 0) - 1,
            )
            self._record_event(
                {
                    "phase": "session_conversation_absolute_turn_refund",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "conversation_turn_count": int(self._conversation_turn_count or 0),
                    "verdict": "controller_projection_turn_refunded",
                }
            )

        # H1: when stagnation has crossed the threshold and a registered
        # fallback action ran, mark fallback as attempted so the next
        # ``should_continue`` terminates cleanly.
        if (
            outcome.action_id in self.fallback_action_ids
            and self.stagnation_counter >= self.max_stagnation
            and not bool(metadata.get("recursive_pass_quantum_yield"))
        ):
            self.fallback_actions_attempted = True
        reserved_fallback_action_id = str(self.pending_fallback_action_id or "").strip()
        reservation_invalidated_by = ""
        if (
            reserved_fallback_action_id
            and outcome.action_id != reserved_fallback_action_id
        ):
            if final_strong_progress:
                reservation_invalidated_by = "strong_progress"
            elif bool(outcome.progress):
                reservation_invalidated_by = "progress"
            elif hard_pivot_triggered:
                reservation_invalidated_by = "hard_pivot"
            elif bool(metadata.get("frontier_progress_retry_granted")):
                reservation_invalidated_by = "frontier_progress_retry"
        if outcome.action_id == reserved_fallback_action_id:
            self.pending_fallback_action_id = ""
        elif reservation_invalidated_by:
            self.pending_fallback_action_id = ""
            self._increment_dossier_metric(
                "mini_session_reserved_fallback_released_after_intervening_progress",
                1,
            )
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reserved_fallback_action_id": reserved_fallback_action_id,
                    "reason": reservation_invalidated_by,
                    "verdict": "reserved_fallback_released_after_intervening_progress",
                }
            )

        def _deferred_retry_context_fields() -> Dict[str, Any]:
            fields = {
                key: metadata.get(key)
                for key in (
                    "llm_failure_tool_history_compacted",
                    "llm_failure_tool_history_compacted_messages",
                    "llm_failure_tool_history_compacted_tool_rounds",
                    "llm_failure_tool_history_compacted_chars",
                    "provider_call_quantum_exhausted",
                    "provider_finalizer_continuation_exhausted",
                    "provider_call_quantum_max_retries",
                    "provider_calls_completed",
                    "provider_dispatches_started",
                    "failed_provider_pre_generation_rejection",
                    "provider_call_elapsed_s",
                    "zero_provider_failure",
                    "provider_defer_fingerprint",
                    "provider_defer_ready_at",
                    "provider_defer_retry_after_s",
                    "recovered_finalizer_provider_receipt_activated",
                    "recursive_helper_zero_provider_backoff_identity",
                    "lean_tool_retry_runner_recycles",
                    "tool_repeat_detected",
                    "tool_repeat_action",
                    "tool_repeat_signature",
                )
                if metadata.get(key) not in (None, "")
            }
            fields["provider_retry_count"] = max(
                0,
                int(
                    metadata.get(
                        "provider_retry_count",
                        metadata.get("retry_count", 0),
                    )
                    or 0
                ),
            )
            return fields

        def _record_model_call_deferred_action() -> bool:
            action_id = str(outcome.action_id or "").strip()
            selected_item_for_defer = self.selected_work_item
            selected_record_for_defer = dict(
                self.selected_work_item_record or {}
            )
            if selected_item_for_defer is None:
                outcome_selected_record = metadata.get("selected_work_item")
                if isinstance(outcome_selected_record, Mapping):
                    selected_record_for_defer = dict(
                        outcome_selected_record
                    )
                    if selected_record_for_defer:
                        # A scheduler-owned provider receipt can finish after
                        # another action changed the transient selection. Use
                        # the action's durable structural record to register
                        # its retry without overwriting the live selection.
                        selected_item_for_defer = selected_record_for_defer
            if selected_item_for_defer is not None and action_id not in set(
                self._frontier_candidate_ids_for_work_item(
                    selected_item_for_defer
                )
            ):
                # A static/broker action may complete after another action's
                # frontier selection was left in the shared session. Keep the
                # retry as an action/family receipt, but never manufacture an
                # action-key that the frontier mapper cannot dispatch.
                self._increment_dossier_metric(
                    "mini_session_model_call_defer_foreign_selection_detached",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_model_call_deferred_frontier_action",
                        "iteration": self.iteration,
                        "action_id": action_id,
                        "selected_work_item": dict(selected_record_for_defer),
                        "verdict": "incompatible_selected_work_detached",
                    }
                )
                selected_item_for_defer = None
                selected_record_for_defer = {}
            provider_turn_lane_retired = bool(
                metadata.get("provider_turn_lane_retired")
            )
            provider_turn_lane_identity = str(
                metadata.get("provider_turn_lane_identity") or ""
            ).strip()
            defer_family = str(metadata.get("model_call_defer_family") or "").strip()
            provider_defer_fingerprint = str(
                metadata.get("provider_defer_fingerprint") or ""
            ).strip()
            provider_only_after_progress = bool(
                metadata.get("recovered_finalizer_provider_receipt_activated")
                and (
                    metadata.get("strong_progress")
                    or metadata.get(
                        "recovered_finalizer_terminal_provider_only"
                    )
                )
            )
            if provider_only_after_progress:
                # The selected mathematical child is already proved. Keep a
                # family/provider scheduler receipt without resurrecting that
                # completed frontier item.
                selected_item_for_defer = None
            family_action_ids: Set[str] = set()
            if not provider_turn_lane_retired:
                family_action_ids.update({
                    str(action.id or "").strip()
                    for action in self.actions
                    if str(action.id or "").strip()
                    and defer_family
                    and str(
                        getattr(action, "MODEL_CALL_DEFER_FAMILY", "") or ""
                    ).strip()
                    == defer_family
                })
                if action_id:
                    family_action_ids.add(action_id)
                if provider_defer_fingerprint:
                    family_action_ids.update(
                        str(action.id or "").strip()
                        for action in self.actions
                        if str(action.id or "").strip()
                        and self._action_provider_defer_fingerprints(action)
                        == {provider_defer_fingerprint}
                    )
            deferred_retry_context_fields = _deferred_retry_context_fields()
            selected_action_key = (
                self._frontier_action_key(
                    selected_item_for_defer,
                    outcome.action_id,
                )
                if selected_item_for_defer is not None
                else None
            )
            persistent_infrastructure_retry_fields: Dict[str, Any] = {}
            if self._persistent_infrastructure_defer(metadata):
                prior_records = [
                    dict(
                        self.model_call_deferred_static_action_metadata.get(
                            family_action_id
                        )
                        or {}
                    )
                    for family_action_id in family_action_ids
                ]
                if selected_action_key is not None:
                    prior_records.append(
                        dict(
                            self.model_call_deferred_frontier_action_metadata.get(
                                selected_action_key
                            )
                            or {}
                        )
                    )
                persistent_infrastructure_retry_fields = (
                    self._persistent_infrastructure_retry_fields(
                        *prior_records,
                        metadata,
                    )
                )
            registered = False
            if provider_turn_lane_retired and provider_turn_lane_identity:
                self.provider_turn_retired_lane_identities.add(
                    provider_turn_lane_identity
                )
                registered = True
            if family_action_ids:
                new_static_metadata = {
                    "action_id": action_id,
                    "deferred_iteration": int(self.iteration or 0),
                    "model_call_defer_family": defer_family,
                    "llm_failure_kind": str(
                        outcome.metadata.get("llm_failure_kind") or ""
                    ),
                    "llm_retryable": bool(outcome.metadata.get("llm_retryable")),
                    "scoped_failure_reason": scoped_failure_reason,
                    "llm_failure_scope": failure_scope,
                    "terminal_failure_reason": str(
                        outcome.metadata.get("terminal_failure_reason") or ""
                    ),
                    "provider_turn_lane_retired": provider_turn_lane_retired,
                    "provider_turn_lane_identity": provider_turn_lane_identity,
                    "recovered_finalizer_provider_receipt_activated": bool(
                        metadata.get(
                            "recovered_finalizer_provider_receipt_activated"
                        )
                    ),
                    **deferred_retry_context_fields,
                    **persistent_infrastructure_retry_fields,
                }
                if selected_record_for_defer:
                    # A completed model turn with no artifact is a result for
                    # one mathematical target, even though the paired static
                    # receipt also prevents the unscoped scheduler from
                    # immediately replaying the same action. Retain that
                    # target so a different frontier obligation is not
                    # mistaken for the failed turn.
                    new_static_metadata["selected_work_item_record"] = dict(
                        selected_record_for_defer
                    )
                for family_action_id in sorted(family_action_ids):
                    existing_static_metadata = dict(
                        self.model_call_deferred_static_action_metadata.get(
                            family_action_id
                        )
                        or {}
                    )
                    existing_static_retryable = (
                        self._model_call_deferred_metadata_retryable(
                            existing_static_metadata
                        )
                        if existing_static_metadata
                        else True
                    )
                    self.model_call_deferred_static_action_ids.add(family_action_id)
                    if existing_static_retryable:
                        family_metadata = dict(new_static_metadata)
                        family_metadata["action_id"] = family_action_id
                        self.model_call_deferred_static_action_metadata[
                            family_action_id
                        ] = family_metadata
                registered = True
            if selected_item_for_defer is not None:
                selected_key = self._frontier_work_key(selected_item_for_defer)
                assert selected_action_key is not None
                if any(selected_key):
                    self.consumed_frontier_action_keys.add(selected_action_key)
                    self.model_call_deferred_frontier_action_keys.add(
                        selected_action_key
                    )
                    self.model_call_deferred_frontier_action_metadata[
                        selected_action_key
                    ] = {
                        "action_id": action_id,
                        "deferred_iteration": int(self.iteration or 0),
                        # The exact frontier key deliberately includes
                        # evidence/context hashes. Recording a retryable
                        # diagnostic attempt can change those hashes before
                        # the retry wakes, even though the same mathematical
                        # obligation is still live. Retain its structural
                        # record so recovery can release the old defer receipt
                        # without treating diagnostic churn as new work.
                        "selected_work_item_record": dict(
                            selected_record_for_defer
                        ),
                        "llm_failure_kind": str(
                            outcome.metadata.get("llm_failure_kind") or ""
                        ),
                        "llm_retryable": bool(outcome.metadata.get("llm_retryable")),
                        "scoped_failure_reason": scoped_failure_reason,
                        "llm_failure_scope": failure_scope,
                        "terminal_failure_reason": str(
                            outcome.metadata.get("terminal_failure_reason") or ""
                        ),
                        "provider_turn_lane_retired": provider_turn_lane_retired,
                        "provider_turn_lane_identity": provider_turn_lane_identity,
                        "recovered_finalizer_provider_receipt_activated": bool(
                            metadata.get(
                                "recovered_finalizer_provider_receipt_activated"
                            )
                        ),
                        **deferred_retry_context_fields,
                        **persistent_infrastructure_retry_fields,
                    }
                    registered = True
            self._increment_dossier_metric(
                "mini_session_model_call_deferred_frontier_actions",
                1,
            )
            provider_retry_count = int(
                deferred_retry_context_fields.get("provider_retry_count") or 0
            )
            (
                max_scheduler_retries,
                scheduler_retries_unbounded,
            ) = self._model_call_deferred_frontier_retry_policy({
                **metadata,
                "action_id": action_id,
            })
            scheduler_retry_count = 0
            if selected_item_for_defer is not None and selected_action_key is not None:
                scheduler_retry_keys = self._frontier_progress_retry_keys(
                    selected_item_for_defer,
                    selected_action_key,
                )
                scheduler_retry_count = max(
                    (
                        int(
                            self.model_call_deferred_frontier_retry_counts.get(
                                retry_key,
                                0,
                            )
                            or 0
                        )
                        for retry_key in scheduler_retry_keys
                    ),
                    default=0,
                )
            retry_deadline_fields = {
                str(key): value
                for key, value in metadata.items()
                if str(key).startswith("llm_retry_deadline_")
            }
            self._record_event(
                {
                    "phase": "session_model_call_deferred_frontier_action",
                    "iteration": self.iteration,
                    "action_id": action_id,
                    "deferred_action_ids": sorted(family_action_ids),
                    "model_call_defer_family": defer_family,
                    "llm_failure_kind": str(
                        outcome.metadata.get("llm_failure_kind") or ""
                    ),
                    "scoped_failure_reason": scoped_failure_reason,
                    "llm_failure_scope": failure_scope,
                    **retry_deadline_fields,
                    **deferred_retry_context_fields,
                    **persistent_infrastructure_retry_fields,
                    "provider_attempts": list(metadata.get("provider_attempts") or []),
                    # Legacy field: provider/transport retries within this
                    # action. Keep it for compatibility and publish explicit
                    # domains beside it so RCA cannot confuse it with the
                    # scheduler's cross-action release ledger.
                    "retry_count": provider_retry_count,
                    "provider_retry_count": provider_retry_count,
                    "scheduler_retry_count": scheduler_retry_count,
                    "max_scheduler_retries": max_scheduler_retries,
                    "scheduler_retries_unbounded": scheduler_retries_unbounded,
                    "selected_work_item": dict(selected_record_for_defer),
                    "provider_turn_lane_retired": provider_turn_lane_retired,
                    "provider_turn_lane_identity": provider_turn_lane_identity,
                    "verdict": "selected_action_deferred",
                }
            )
            return registered

        model_call_deferred_action_registered = False
        semantic_recursive_fixed_point = str(
            metadata.get("recursive_fixed_point_reason") or ""
        ).strip() in {
            "recursive_planner_empty_fixed_point",
            "recursive_helper_only_fixed_point",
            "recursive_progress_fixed_point",
        }
        model_call_defer_authorized = bool(
            bool(metadata.get("defer_selected_frontier_action"))
            and (
                not bool(metadata.get("strong_progress"))
                or bool(
                    metadata.get(
                        "recovered_finalizer_provider_receipt_activated"
                    )
                )
            )
            and not bool(metadata.get("terminal_failure"))
            and not semantic_recursive_fixed_point
        )
        if model_call_defer_authorized:
            model_call_deferred_action_registered = _record_model_call_deferred_action()

        consumed_frontier_work = False
        if self._selected_route_authoring_rejection_progress(outcome):
            self._record_selected_route_authoring_failure(
                outcome,
                reason="lean_rejected_with_side_progress",
            )
        if outcome.progress:
            clear_model_call_deferred_state = bool(
                outcome.solved
                or (
                    metadata.get("strong_progress")
                    and not metadata.get(
                        "recovered_finalizer_provider_receipt_activated"
                    )
                )
                or metadata.get("clear_model_call_deferred_state")
            )
            model_call_deferred_state_present = bool(
                self.model_call_deferred_frontier_action_keys
                or self.model_call_deferred_frontier_action_metadata
                or self.model_call_deferred_frontier_retry_counts
                or self.model_call_deferred_static_action_ids
                or self.model_call_deferred_static_action_metadata
                or self.model_call_deferred_static_retry_counts
            )
            if clear_model_call_deferred_state:
                self.model_call_deferred_frontier_action_keys.clear()
                self.model_call_deferred_frontier_action_metadata.clear()
                self.model_call_deferred_frontier_retry_counts.clear()
                self.model_call_deferred_static_action_ids.clear()
                self.model_call_deferred_static_action_metadata.clear()
                self.model_call_deferred_static_retry_counts.clear()
            elif model_call_deferred_state_present:
                self._record_event(
                    {
                        "phase": "session_model_call_deferred_state",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "strong_progress": bool(metadata.get("strong_progress")),
                        "progress": True,
                        "verdict": "preserved_after_soft_progress",
                    }
                )
            (
                progress_materialization_action_keys,
                progress_materialization_logical_keys,
                progress_materialization_work_keys,
            ) = self._materialization_progress_frontier_keys(outcome)
            weak_selected_progress = bool(
                (outcome.metadata or {}).get("graph_route_assembled")
                and (outcome.metadata or {}).get("strong_progress") is False
            )
            if weak_selected_progress and self.selected_work_item is not None:
                selected_key = self._frontier_work_key(self.selected_work_item)
                selected_action_key = self._frontier_action_key(
                    self.selected_work_item,
                    outcome.action_id,
                )
                self.consumed_frontier_work_keys.discard(selected_key)
                self.consumed_frontier_action_keys.discard(selected_action_key)
                prior_pending_action_keys = set(
                    self.materialization_pending_frontier_action_keys
                )
                pending_action_keys = set(prior_pending_action_keys)
                pending_logical_keys = set(
                    self.materialization_pending_frontier_logical_keys
                )
                pending_action_keys.discard(selected_action_key)
                pending_action_keys.difference_update(
                    progress_materialization_action_keys
                )
                if progress_materialization_work_keys:
                    progress_materialization_work_prefixes = {
                        tuple(key[:4]) for key in progress_materialization_work_keys
                    }
                    pending_action_keys = {
                        key
                        for key in pending_action_keys
                        if tuple(key[:5]) not in progress_materialization_work_keys
                        and tuple(key[:4]) not in progress_materialization_work_prefixes
                    }
                pending_logical_keys.discard(
                    self._frontier_materialization_logical_key(self.selected_work_item)
                )
                pending_logical_keys.difference_update(
                    progress_materialization_logical_keys
                )
                self.materialization_pending_frontier_action_keys = pending_action_keys
                self.materialization_pending_frontier_logical_keys = (
                    pending_logical_keys
                )
                self._retain_materialization_pending_action_logical_keys()
                release_work_keys = set(progress_materialization_work_keys)
                release_action_keys = set(progress_materialization_action_keys)
                release_logical_keys = set(progress_materialization_logical_keys)
                if selected_key is not None:
                    release_work_keys.add(selected_key)
                if selected_action_key is not None:
                    release_action_keys.add(selected_action_key)
                selected_logical_key = self._frontier_materialization_logical_key(
                    self.selected_work_item
                )
                if any(selected_logical_key):
                    release_logical_keys.add(selected_logical_key)
                self._discard_skipped_frontier_keys_for_progress(
                    work_keys=release_work_keys,
                    action_keys=release_action_keys,
                    logical_keys=release_logical_keys,
                )
                self.skipped_frontier_action_keys.update(pending_action_keys)
            else:
                selected_key = None
                selected_action_key = None
                preserve_selected_action = bool(
                    (outcome.metadata or {}).get("preserve_selected_frontier_action")
                    and self.selected_work_item is not None
                )
                if preserve_selected_action:
                    selected_key = self._frontier_work_key(self.selected_work_item)
                    selected_action_key = self._frontier_action_key(
                        self.selected_work_item,
                        outcome.action_id,
                    )
                prior_pending_action_keys = set(
                    self.materialization_pending_frontier_action_keys
                )
                pending_action_keys = set(prior_pending_action_keys)
                pending_logical_keys = set(
                    self.materialization_pending_frontier_logical_keys
                )
                pending_action_keys.difference_update(
                    progress_materialization_action_keys
                )
                if progress_materialization_work_keys:
                    progress_materialization_work_prefixes = {
                        tuple(key[:4]) for key in progress_materialization_work_keys
                    }
                    pending_action_keys = {
                        key
                        for key in pending_action_keys
                        if tuple(key[:5]) not in progress_materialization_work_keys
                        and tuple(key[:4]) not in progress_materialization_work_prefixes
                    }
                pending_logical_keys.difference_update(
                    progress_materialization_logical_keys
                )
                selected_materialization_logical_key = (
                    self._frontier_materialization_logical_key(self.selected_work_item)
                    if self.selected_work_item is not None
                    else ("", "", "", "", "")
                )
                if any(selected_materialization_logical_key):
                    selected_materialization_action_key = self._frontier_action_key(
                        self.selected_work_item,
                        outcome.action_id,
                    )
                    pending_action_keys.discard(selected_materialization_action_key)
                    pending_logical_keys.discard(selected_materialization_logical_key)
                self.materialization_pending_frontier_action_keys = pending_action_keys
                self.materialization_pending_frontier_logical_keys = (
                    pending_logical_keys
                )
                self._retain_materialization_pending_action_logical_keys()
                release_work_keys = set(progress_materialization_work_keys)
                release_action_keys = set(progress_materialization_action_keys)
                release_logical_keys = set(progress_materialization_logical_keys)
                if selected_key is not None:
                    release_work_keys.add(selected_key)
                if selected_action_key is not None:
                    release_action_keys.add(selected_action_key)
                if any(selected_materialization_logical_key):
                    release_logical_keys.add(selected_materialization_logical_key)
                self._discard_skipped_frontier_keys_for_progress(
                    work_keys=release_work_keys,
                    action_keys=release_action_keys,
                    logical_keys=release_logical_keys,
                )
                self.skipped_frontier_action_keys.update(pending_action_keys)
                if preserve_selected_action and selected_action_key is not None:
                    self.consumed_frontier_action_keys.add(selected_action_key)
                    if selected_key is not None:
                        self.consumed_frontier_work_keys.discard(selected_key)
        elif self.selected_work_item is not None and bool(
            metadata.get("selected_work_projection_invalidated")
        ):
            stale_action_key = (
                self.selected_frontier_action_key
                or self._frontier_action_key(
                    self.selected_work_item,
                    outcome.action_id,
                )
            )
            if any(stale_action_key):
                # Retire only this exact action/projection generation. The
                # graph work itself remains live for a freshly projected
                # packet and for other applicable actions.
                self.consumed_frontier_action_keys.add(stale_action_key)
            self._increment_dossier_metric(
                "mini_session_selected_work_projection_invalidations",
                1,
            )
            self._record_event(
                {
                    "phase": "session_selected_work_projection_invalidated",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": str(metadata.get("scoped_failure_reason") or ""),
                    "selected_work_item": dict(self.selected_work_item_record),
                    "verdict": "fresh_projection_required",
                }
            )
        elif self.selected_work_item is not None and not bool(
            outcome.metadata.get("preserve_frontier_work")
        ):
            self._consume_selected_frontier_work(outcome)
            consumed_frontier_work = True
        elif self.selected_work_item is not None and bool(
            outcome.metadata.get("consume_selected_frontier_action")
        ):
            self.consumed_frontier_action_keys.add(
                self.selected_frontier_action_key
                or self._frontier_action_key(self.selected_work_item, outcome.action_id)
            )
        elif model_call_defer_authorized and not model_call_deferred_action_registered:
            _record_model_call_deferred_action()

        # Stagnation: any progress resets; same proof-state signature
        # advances counter; signature drift WITHOUT progress is also
        # stagnation-protective (the live-trace fix below).
        #
        # A frontier-first dispatch that
        # consumed a work-item but didn't make progress is NOT
        # stagnation — the consumed-work tracking is itself the search
        # advance signal. Each (node_id, work_type, ...) tuple gets
        # exactly one shot before being marked consumed; once all
        # frontier work is consumed, frontier-first returns nothing
        # and static-priority kicks in. Counting these as stagnation
        # killed sessions after a few dedup-driven no-ops, well before
        # conversation-turn budget exhaustion.
        #
        # The prior
        # all-stagnates-unless-signature-equal logic preserves a
        # critical safety guarantee — deterministic prepass actions
        # (premise_retrieval, tactic_close) mutate the graph each
        # iteration without setting ``outcome.progress`` (because they
        # didn't solve), so a strict "no progress = stagnation" rule
        # tripped termination before the LLM ever ran. Reverted to
        # signature-equality semantics: signature unchanged AND no
        # progress = stagnation; signature drift = soft progress signal.
        # The previous fix exempted ALL
        # frontier-consumed no-progress from stagnation — too liberal.
        # In the observed failure, several child closures ran in a row with
        # real Lean tactic work but no progress and no stagnation ticks because
        # each had a unique (node_id, work_type) key.
        #
        # Threshold: 1.0s. A frontier-consumed dispatch with cost < 1s
        # was a real no-op (is_applicable found nothing fresh, returned
        # immediately) — that's not stagnation. A dispatch with cost
        # ≥ 1s ran genuine work and failed — repeated such dispatches
        # IS stagnation, even if each consumes a different key.
        new_signature = (
            self._proof_state_signature() if self.proof_state is not None else None
        )
        signature_drift_without_progress = bool(
            not outcome.progress
            and new_signature is not None
            and self.last_proof_state_signature is not None
            and new_signature != self.last_proof_state_signature
        )
        is_noop_consumption = (
            consumed_frontier_work and (outcome.cost_seconds or 0.0) < 1.0
        )
        unverified_decomposition_only = bool(
            outcome.metadata.get("unverified_decomposition_created")
        ) and not bool(outcome.metadata.get("strong_progress"))
        quarantined_residual_diagnostics_only = bool(
            outcome.metadata.get("quarantined_residual_diagnostics_created")
        ) and not bool(outcome.metadata.get("strong_progress"))
        if hard_pivot_triggered:
            # A hard pivot is a deliberate controller-level route reset.  The
            # failing outcome that triggered it should not leave the dispatcher
            # in a hot stagnation state that immediately diverts the fresh
            # prompt into fallback machinery before the LLM can act on it.
            self.stagnation_counter = 0
            self.soft_progress_streak = 0
            self.last_proof_state_signature = new_signature
        elif bool(
            (metadata.get("scheduler_neutral") or metadata.get("stagnation_neutral"))
            and not policy_repair_redirect
        ):
            # Preparatory/instrumentation actions such as falsification may do
            # expensive bounded work without consuming a mathematical search
            # turn or manufacturing proof progress. Preserve the existing
            # stagnation state exactly; their own cursor fixed point controls
            # redispatch.
            self.last_proof_state_signature = new_signature
        elif bool(metadata.get("frontier_progress_retry_granted")):
            # This is not a proof-progress claim: it is one bounded repair
            # dispatch earned by a durable formal delta or a normalized Lean
            # diagnostic improvement.  Keep the global controller below its
            # fallback threshold long enough to run that exact retry.  The
            # per-action signature ledger, rather than global stagnation,
            # terminates repeated diagnostic states.
            threshold = max(0, int(self.max_stagnation or 0))
            self.stagnation_counter = (
                min(int(self.stagnation_counter or 0), threshold - 1)
                if threshold > 0
                else 0
            )
            self.soft_progress_streak = 0
            self.last_proof_state_signature = new_signature
        elif outcome.progress:
            if (
                self.policy_repair_redirect_selected_work_item is not None
                and str(outcome.action_id or "").strip()
                == str(self.policy_repair_redirect_selected_action_id or "").strip()
                and self.selected_work_item is not None
                and self._frontier_work_key(self.selected_work_item)
                == self._frontier_work_key(
                    self.policy_repair_redirect_selected_work_item
                )
            ):
                # A scheduler-yield continuation may retain the exact repair
                # frontier while a provider call is split into quanta. Once
                # that same owner publishes real progress, the redirect lease
                # is fulfilled even if another bounded continuation remains.
                # Keeping it would later resurrect already-advanced work.
                self._clear_policy_repair_redirect_selected_work()
            # Fix 3 (2026-05-22): under strict accounting, separate
            # root-impactful "strong" progress from accepted-helper "soft"
            # progress. Soft-only progress is tolerated up to
            # ``max_soft_progress_streak``; beyond that it ticks stagnation
            # so ``adaptive_recursive_fallback`` can fire instead of letting
            # a bogus-helper cascade reset the counter forever.
            metadata = outcome.metadata or {}
            strong_progress_signaled = bool(metadata.get("strong_progress"))
            if not self.strict_progress_accounting or strong_progress_signaled:
                self.stagnation_counter = 0
                self.soft_progress_streak = 0
                self.last_proof_state_signature = new_signature
            else:
                self.soft_progress_streak += 1
                self.last_proof_state_signature = new_signature
                if self.soft_progress_streak > self.max_soft_progress_streak:
                    self.stagnation_counter += 1
                    saturated_streak = self.soft_progress_streak
                    # HIGH-#9 fix (2026-05-22, adversarial review): reset the
                    # streak after each saturation tick so the counter
                    # re-arms instead of incrementing stagnation on every
                    # subsequent soft outcome. Without this, with default
                    # max_stagnation=3 and max_soft_progress_streak=4 the
                    # session terminates only 2 soft outcomes after the
                    # first saturation tick — far more aggressive than the
                    # field-name implies.
                    self.soft_progress_streak = 0
                    self._record_event(
                        {
                            "phase": "soft_progress_streak_saturated",
                            "soft_progress_streak": saturated_streak,
                            "max_soft_progress_streak": self.max_soft_progress_streak,
                            "stagnation_counter": self.stagnation_counter,
                            "action_id": outcome.action_id,
                            "verdict": "soft_progress_treated_as_stagnation",
                        }
                    )
        elif policy_repair_redirect:
            if bool(metadata.get("preserve_frontier_work")):
                self._capture_policy_repair_redirect_selected_work(outcome.action_id)
            min_next_iteration_budget = int(self.iteration or 0) + 2
            if int(self.max_iterations or 0) < min_next_iteration_budget:
                old_max_iterations = int(self.max_iterations or 0)
                self.max_iterations = min_next_iteration_budget
                self._record_event(
                    {
                        "phase": "session_policy_repair_redirect",
                        "iteration": self.iteration,
                        "action_id": outcome.action_id,
                        "old_max_iterations": old_max_iterations,
                        "max_iterations": int(self.max_iterations or 0),
                        "verdict": "iteration_guard_extended",
                    }
                )
            self.last_proof_state_signature = new_signature
            self._record_event(
                {
                    "phase": "session_policy_repair_redirect",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "reason": str(
                        metadata.get("repair_redirect_reason")
                        or metadata.get("rejection_reason")
                        or ""
                    ),
                    "preserve_action_budget": preserve_action_budget,
                    "local_repair_quota_refunded": local_repair_refunded,
                    "verdict": "non_stagnating_repair_redirect",
                }
            )
        elif unverified_decomposition_only or quarantined_residual_diagnostics_only:
            # Explicit decomposition evidence may add durable open work, but
            # zero-accepted proposals are not proof progress. This must win
            # even for fast frontier-selected work, otherwise the cheap
            # consumed-work exemption would still reset stagnation. Quarantined
            # failed-proof residuals are even weaker: they are diagnostic graph
            # drift, not schedulable decomposition, and should not reset root
            # repair stagnation either.
            self.stagnation_counter += 1
            self.last_proof_state_signature = new_signature
        elif is_noop_consumption:
            # Frontier-consumed no-op (cost < 1s): not stagnation.
            self.last_proof_state_signature = new_signature
        elif signature_drift_without_progress:
            self.stagnation_counter += 1
            self.soft_progress_streak = 0
            self.last_proof_state_signature = new_signature
            self._record_event(
                {
                    "phase": "signature_drift_without_progress",
                    "iteration": self.iteration,
                    "action_id": outcome.action_id,
                    "cost_seconds": float(outcome.cost_seconds or 0.0),
                    "stagnation_counter": self.stagnation_counter,
                    "verdict": "signature_drift_treated_as_stagnation",
                }
            )
        else:
            if (
                new_signature is not None
                and new_signature == self.last_proof_state_signature
            ):
                self.stagnation_counter += 1
            else:
                self.stagnation_counter = 0
                self.last_proof_state_signature = new_signature

        self._discharge_repair_policy_narrowing_after_action(outcome)

        # Some late scheduler branches enrich the local metadata after the
        # original post-action synchronization point. Publish the complete
        # authoritative record to the action-owned outcome before hooks and
        # the outer run loop inspect it.
        if isinstance(action_reported_outcome.metadata, dict):
            action_reported_outcome.metadata.update(metadata)

        if not effective_solved and not global_terminal_failure:
            self._reserve_semantic_budget_iteration_headroom(
                action_id=outcome.action_id,
                budget=budget,
                semantic_step_consumed=bool(
                    metadata.get("semantic_budget_step_consumed")
                ),
            )

        # Top-level iteration counter — incremented exactly once per
        # ``apply`` call. Subaction dispatch (M4) does NOT route through
        # ``apply``; it returns to its parent action's ``run`` body.
        if not bool(metadata.get("iteration_neutral")):
            self.iteration += 1
        self._bridge_support_reselection_keys.clear()

        record: Dict[str, Any] = {
            "phase": "session_action_outcome",
            "action_id": outcome.action_id,
            "action_dispatch_id": str(metadata.get("action_dispatch_id") or ""),
            "iteration": self.iteration,
            "solved": effective_solved,
            "action_reported_solved": bool(metadata.get("action_reported_solved")),
            "root_finalization_vetoed_outcome": bool(
                metadata.get("root_finalization_vetoed_outcome")
            ),
            "progress": outcome.progress,
            "helpers_added_count": len(outcome.helpers_added),
            "cost_seconds": round(outcome.cost_seconds, 4),
            "exception": str(outcome.exception) if outcome.exception else None,
            "selected_work_item": dict(self.selected_work_item_record),
            "strong_progress": (
                outcome.metadata.get("strong_progress")
                if "strong_progress" in outcome.metadata
                else None
            ),
            "unverified_decomposition_created": bool(
                outcome.metadata.get("unverified_decomposition_created")
            ),
            "schedulable_decomposition_created": bool(
                outcome.metadata.get("schedulable_decomposition_created")
            ),
            "quarantined_residual_diagnostics_created": bool(
                outcome.metadata.get("quarantined_residual_diagnostics_created")
            ),
            "hard_pivot_triggered": hard_pivot_triggered,
            "verdict": "outcome_applied",
        }
        if isinstance(metadata.get("proof_lineage"), dict):
            record["proof_lineage"] = dict(metadata["proof_lineage"])
        # R12.5: surface the absolute conversation-turn index for any
        # ConversationTurnAction outcome so post-mortem analysis can
        # disambiguate the always-1 inner-turn value recorded by
        # run_conversation(max_turns=1).
        absolute = (
            outcome.metadata.get("conv_turn_index_absolute")
            if outcome.metadata
            else None
        )
        if absolute is not None:
            record["conv_turn_absolute"] = int(absolute)
        # Surface action-specific Lean status on the generic session
        # heartbeat. The outer verdict intentionally remains
        # ``outcome_applied`` for compatibility, but live CLI readers need
        # the inner Lean result on the same line.
        for key in (
            "lean_verdict",
            "lean_error_type",
            "lean_elapsed_s",
            "lean_feedback_source",
            "llm_response_recorded",
            "llm_turn_elapsed_s",
            "max_tokens_override",
            "max_tokens_override_reason",
            "formalization_llm_request_timeout_s",
            "formalization_llm_turn_elapsed_s",
            "llm_turn_elapsed_budget_exhausted",
            "llm_turn_elapsed_budget_s",
            "request_timeout_override_s",
            "repair_self_check_required",
            "repair_self_check_attempted",
            "repair_self_check_accepted",
            "repair_self_check_status",
            "repair_self_check_missing_kind",
            "repair_self_check_compliant",
            "repair_self_check_evidence_source",
            "repair_self_check_budget_exhausted",
            "repair_self_check_helper_only_allowed",
            "repair_self_check_metric_counted",
            "unknown_identifier_api_search_bypassed_by_exact_self_check",
            "local_repair_target",
            "local_repair_quota_armed",
            "local_repair_quota_verdict",
            "local_repair_giveup_suppressed",
            "suppressed_giveup_cluster",
            "suppressed_giveup_match",
            "local_repair_diagnostics_included",
            "policy_repair_redirect",
            "repair_redirect_reason",
            "policy_repair_redirect_key",
            "policy_repair_redirect_count",
            "policy_repair_redirect_limit",
            "policy_repair_redirect_total_count",
            "policy_repair_redirect_global_limit",
            "preserve_action_budget",
            "preserve_frontier_work",
            "defer_selected_frontier_action",
            "selected_work_projection_invalidated",
            "try_skeleton_tool_calls",
            "try_skeleton_routes_banked",
            "compute_examples_protocol_attempts",
            "compute_examples_tool_calls",
            "compute_examples_successes",
            "compute_examples_malformed_calls",
            "assembly_contracts_added",
            "failure_residual_obligation_node_count",
            "failure_residual_replan_node_count",
            "route_contract_verdict",
            "root_finalization_accepted",
            "root_finalization_verdict",
            "root_finalization_verification_status",
            "stagnation_neutral",
            "hard_pivot_neutral",
            "terminal_failure",
            "terminal_failure_reason",
            "llm_failure_kind",
            "llm_retryable",
            "target_integrity_signals",
            "target_integrity_bypass_local_repair",
            "target_integrity_disable_proof_state_repair",
            "target_integrity_obligation_node_ids",
            "target_integrity_replan_node_ids",
            "target_integrity_adjudication_available",
            "target_integrity_adjudication_created",
            "target_integrity_adjudication_materialized",
            "target_integrity_adjudication_progress_suppressed",
            "premise_retrieval_enabled",
            "premise_retrieval_searcher_available",
            "premise_retrieval_top_k",
            "premise_retrieval_raw_hit_count",
            "premise_retrieval_filtered_hit_count",
            "premise_retrieval_failure_kind",
            "premise_local_micro_theory_candidate",
            "premise_zero_hit_policy",
            "premise_zero_hit_eligible",
            "premise_zero_hit_guard_reason",
            "premise_zero_hit_shadow_recommendation",
            "local_micro_theory_activated",
            "local_micro_theory_reason",
            "local_micro_theory_max_turns",
            "local_micro_theory_search_suppressed",
            "local_micro_theory_turns_used",
            "local_micro_theory_suppression_exhausted",
            "temperature_requested",
            "effective_temperature",
            "temperature_phase_key",
            "temperature_phase",
            "temperature_source",
            "temperature_reason",
            "sample_temperature",
            "temperature_sent",
            "temperature_provider_dropped",
            "temperature_provider_drop_reason",
            "reasoning_control_requested",
            "reasoning_control_decision",
            "reasoning_control_sent",
            "reasoning_control_required",
            "reasoning_capability_record",
            "formal_exit_reason",
            "formal_progress_improved",
            "formal_progress_reasons",
            "formal_rank_improved",
            "formal_no_improvement_quanta",
            "formal_no_improvement_limit",
            "formal_zero_yield_quanta",
            "formal_zero_yield_limit",
            "formal_context_zero_yield_stalled",
            "formal_context_stalled",
            "formal_provider_retry_pending",
            "formal_invocations",
            "formal_nodes_created",
            "formal_nodes_expanded",
            "formal_lean_checks",
            "formal_backtracks",
            "formal_value_estimates",
            "formal_diversity_pruned",
            "formal_bottleneck_count",
            "formal_root_unlocking_bottleneck_count",
            "formal_operation_timeouts",
            "formal_infrastructure_failures",
            "formal_completion_rejections",
            "formal_candidates_found",
            "tool_repeat_detected",
            "tool_repeat_action",
            "tool_repeat_signature",
            "llm_failure_tool_history_compacted",
            "llm_failure_tool_history_compacted_messages",
            "llm_failure_tool_history_compacted_tool_rounds",
            "llm_failure_tool_history_compacted_chars",
        ):
            value = outcome.metadata.get(key) if outcome.metadata else None
            if value not in (None, ""):
                record[key] = value
        self._record_event(record)
        self._repair_first_selected_local_forced = False
        self._repair_first_selected_signature_key = ""
        if not bool(
            metadata.get("non_consuming_repair_ticket_continuation")
            and metadata.get("provider_call_quantum_exhausted")
        ):
            self._repair_ticket_selected_id = ""
        if not bool(metadata.get("preserve_frontier_work")):
            self._clear_policy_repair_redirect_selected_work()
            self._clear_selected_work_item()
        return replace(
            outcome,
            solved=effective_solved,
            metadata=metadata,
        )

    def _preserve_durable_root_finalization(self) -> bool:
        """True when a prior accepted root solution must survive a later veto.

        The prior success must still be DURABLE, which means the dossier must
        still hold it.  ``_durable_final_proof`` falls back to
        ``self.final_proof``, and that field is only ever assigned, never
        cleared — so keying preservation on it alone made this permanently true
        after the first accept, and no rejection could ever withdraw
        finalization again.

        Worse, both rejection sites run this BEFORE
        ``_clear_uncontracted_root_side_effects`` retracts the proof, so the
        check saw state that was about to be thrown away and the session could
        report solved while the dossier held no proof at all.  Requiring the
        dossier's own solved artifacts closes both: after ``clear_solved`` they
        are gone, so a retracted root can no longer look preserved.
        """

        dossier = self.dossier
        # ``clear_solved`` nulls the dossier's proof, so its presence alone is
        # enough to tell "prior success still stands" from "just retracted".
        dossier_still_solved = bool(
            dossier is not None
            and str(getattr(dossier, "final_proof", "") or "").strip()
        )
        return bool(
            self.root_finalized and dossier_still_solved and self._durable_final_proof()
        )

    def _clear_root_finalized_for_rejected_attempt(self) -> None:
        """Clear finalization only when there is no durable prior success."""

        if self._preserve_durable_root_finalization():
            return
        self.root_finalized = False
        committed_iteration = int(self.iteration or 0) + 1
        if (
            self.dossier is None
            or self._durable_final_proof()
            or committed_iteration < int(self.max_iterations or 0)
        ):
            return
        metric_name = "mini_root_finalization_rejection_headroom_granted"
        raw_grants = getattr(self.dossier, "tool_metrics", {}).get(metric_name, 0)
        try:
            grants = int(raw_grants or 0)
        except (TypeError, ValueError):
            # Corrupt counters fail closed rather than minting unbounded
            # continuation budget.
            grants = 1
        if grants >= 1:
            return
        self._increment_dossier_metric(metric_name, 1)
        self.max_iterations = max(
            int(self.max_iterations or 0),
            committed_iteration + 1,
        )

    def _maybe_trigger_hard_pivot(self, outcome: MiniOutcome) -> bool:
        """Reset the LLM prompt when it repeats the same non-progress wall."""

        metadata = dict(outcome.metadata or {})
        if bool(metadata.get("hard_pivot_neutral")) or bool(
            metadata.get("policy_repair_redirect")
        ):
            return False
        signature = self._wall_signature_from_outcome(outcome)
        if not signature:
            if outcome.progress or outcome.solved:
                self.last_wall_signature = ""
                self.repeated_wall_count = 0
            return False

        if signature == self.last_wall_signature:
            self.repeated_wall_count += 1
        else:
            self.last_wall_signature = signature
            self.repeated_wall_count = 1

        threshold = max(2, int(self.hard_pivot_threshold or 2))
        if self.repeated_wall_count < threshold:
            return False
        if self.hard_pivot_count >= max(0, int(self.hard_pivot_max_per_session or 0)):
            return False
        if self.conv is None:
            return False

        discarded_messages = self._force_hard_pivot(
            signature=signature,
            metadata=metadata,
        )
        self.hard_pivot_count += 1
        self.repeated_wall_count = 0
        self.last_wall_signature = ""
        self._record_event(
            {
                "phase": "session_hard_pivot",
                "signature": signature,
                "discarded_messages": discarded_messages,
                "hard_pivot_count": self.hard_pivot_count,
                "verdict": "hard_pivot_applied",
            }
        )
        return True

    def _wall_signature_from_outcome(self, outcome: MiniOutcome) -> str:
        """Classify repeated dead ends that need a fresh prompt, not repair."""

        metadata = dict(outcome.metadata or {})
        if bool(metadata.get("stagnation_neutral")) or bool(
            metadata.get("policy_repair_redirect")
        ):
            return ""

        def scoped_signature(base: str) -> str:
            selected = dict(getattr(self, "selected_work_item_record", {}) or {})
            work_type = str(selected.get("work_type") or "").strip()
            if not work_type:
                return base
            target = (
                str(selected.get("target_hash") or "").strip()
                or str(selected.get("node_id") or "").strip()
            )
            if not target:
                return base
            return f"{base}|graph:{work_type}:{target}"

        if (
            outcome.solved
            or bool(metadata.get("strong_progress"))
            or (
                outcome.progress
                and not metadata.get("giveup_cluster")
                and not metadata.get("rejection_reason")
            )
        ):
            return ""

        repair_status = str(
            metadata.get("repair_self_check_status")
            or metadata.get("repair_self_check_missing_kind")
            or ""
        ).strip()

        cluster = str(metadata.get("giveup_cluster") or "").strip()
        if cluster:
            return scoped_signature(f"giveup:{cluster}")

        reason = str(metadata.get("rejection_reason") or "").strip()
        if reason in {
            "repair_self_check_missing",
            "repair_self_check_no_try_lean_call",
            "repair_self_check_tool_budget_exhausted",
            "known_answer_no_construction_collapse",
            "no_main_proof",
            "repackaged_transient_goal",
            "transient_goal_target_sorry_helper",
            "reused_rejected_lean_fragment",
        }:
            return scoped_signature(f"policy:{reason}")

        response = str(metadata.get("llm_response") or "").lower()
        if (
            "_solution" in response
            and "opaque" in response
            and any(
                phrase in response
                for phrase in (
                    "no way",
                    "cannot",
                    "can't",
                    "unprovable",
                    "not provable",
                    "no defining",
                    "no axioms",
                )
            )
        ):
            return scoped_signature("giveup:answer_opaque")

        if "missing bridge" in response and any(
            phrase in response
            for phrase in (
                "cannot proceed",
                "cannot complete",
                "can't complete",
                "stuck",
                "blocker",
            )
        ):
            return scoped_signature("strategy:unproved_intermediate_loop")

        lean_error = str(metadata.get("lean_error_type") or "").strip()
        lean_failure_signature = str(
            metadata.get("lean_failure_signature") or ""
        ).strip()
        if lean_error and lean_failure_signature:
            return scoped_signature(f"lean_wall:{lean_error}:{lean_failure_signature}")
        if lean_error and any(
            phrase in response
            for phrase in (
                "same failure",
                "cannot proceed",
                "cannot complete",
                "can't complete",
                "not derivable",
                "no valid next step",
            )
        ):
            return scoped_signature(f"lean_wall:{lean_error}")
        if repair_status == "no_accepted_try_lean":
            return scoped_signature("policy:repair_self_check_no_accepted_try_lean")
        return ""

    def _force_hard_pivot(self, *, signature: str, metadata: Dict[str, Any]) -> int:
        conv = self.conv
        if conv is None:
            return 0
        try:
            conv.ensure_bootstrap()
        except Exception:
            pass
        old_history = list(getattr(conv, "history", []) or [])
        initial_user = None
        for msg in old_history:
            if msg.get("role") == "user" and "Problem (natural language):" in str(
                msg.get("content", "") or ""
            ):
                initial_user = dict(msg)
                break
        if initial_user is None:
            try:
                initial_user = {
                    "role": "user",
                    "content": conv.initial_user_message(),
                }
            except Exception:
                initial_user = {"role": "user", "content": ""}

        stable_context = self._stable_context_messages_for_hard_pivot(old_history)
        pivot_message = self._hard_pivot_message(signature, metadata)
        conv.history = [
            initial_user,
            *stable_context,
            {"role": "user", "content": pivot_message},
        ]
        clear_repair = getattr(conv, "clear_repair_state", None)
        if callable(clear_repair):
            try:
                clear_repair()
            except Exception:
                pass
        self._clear_hard_pivot_transient_conversation_state(conv)
        return max(0, len(old_history) - len(conv.history))

    @staticmethod
    def _stable_context_messages_for_hard_pivot(
        history: List[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        """Keep durable context while dropping stale attempts/repair chatter."""

        stable_prefixes = (
            "Pre-retrieved Mathlib lemmas ranked by goal/strategy similarity",
            "Refiner phase begins.",
            "[prover handoff evidence]",
        )
        kept: List[Dict[str, Any]] = []
        seen: Set[str] = set()
        before_first_assistant = True
        for msg in history:
            role = msg.get("role")
            if role == "assistant":
                before_first_assistant = False
                continue
            if role != "user":
                continue
            content = str(msg.get("content", "") or "").strip()
            durable_setup_context = (
                before_first_assistant
                and content
                and "Problem (natural language):" not in content
                and not content.startswith("[hard pivot]")
                and not content.startswith("[history compaction]")
                and not content.startswith("Lean rejected")
                and "Primary error family:" not in content
            )
            if not (content.startswith(stable_prefixes) or durable_setup_context):
                continue
            if content in seen:
                continue
            seen.add(content)
            kept.append(dict(msg))
        return kept[-3:]

    @staticmethod
    def _clear_hard_pivot_transient_conversation_state(conv: Any) -> None:
        """Drop hidden response caches whose source transcript was discarded."""

        for attr in (
            "_last_llm_content",
            "_last_no_proof_llm_response",
            "_last_rejected_llm_response",
        ):
            try:
                setattr(conv, attr, "")
            except Exception:
                pass
        for attr in (
            "_no_proof_llm_responses",
            "_suppressed_assistant_handoff_evidence",
        ):
            try:
                setattr(conv, attr, [])
            except Exception:
                pass

    def _hard_pivot_message(self, signature: str, metadata: Dict[str, Any]) -> str:
        detail = str(metadata.get("giveup_match") or "").strip()
        if not detail:
            detail = str(metadata.get("rejection_reason") or "").strip()
        if not detail:
            detail = str(metadata.get("lean_error_type") or "").strip()
        detail = detail[:180]
        conv = self.conv
        scope = str(getattr(self, "scope", "") or "")
        proof_only = bool(
            conv is not None
            and not bool(getattr(conv, "allow_helper_decomposition", True))
        )
        selected = dict(getattr(self, "selected_work_item_record", {}) or {})
        selected_work_type = str(selected.get("work_type") or "").strip()
        selected_node_id = str(selected.get("node_id") or "").strip()
        selected_formalization_required = selected_work_type in {
            "formalize_claim",
            "formalize_missing_obligation",
            "mine_missing_obligation",
        } and bool(
            selected.get("formalization_required")
            or selected.get("materialization_required")
        )
        active_root_context = ""
        dossier = getattr(self, "dossier", None)
        renderer = getattr(dossier, "render_active_root_target_context", None)
        if callable(renderer):
            try:
                active_root_context = str(renderer() or "").strip()
            except Exception:
                active_root_context = ""
        scoped_target = bool(
            proof_only
            or scope in {"subgoal", "branch"}
            or (active_root_context and not selected_work_type)
        )

        lines = [
            "[hard pivot]",
            (f"The controller saw the same non-progress wall repeat: `{signature}`."),
        ]
        if detail:
            lines.append(f"Latest wall detail: `{detail}`.")
        if selected_work_type or selected_node_id:
            selected_bits = " ".join(
                part
                for part in (
                    f"work_type={selected_work_type}" if selected_work_type else "",
                    f"node_id={selected_node_id}" if selected_node_id else "",
                )
                if part
            )
            lines.append(f"Repeated graph task context: `{selected_bits}`.")
        if active_root_context:
            lines.append(active_root_context)
            if selected_work_type:
                lines.append(
                    "The graph-selected task must remain a bridge toward this "
                    "active root target; do not use it to prove an opposite "
                    "claim or to discharge the root by answer-placeholder "
                    "bookkeeping."
                )
        if scoped_target:
            lines.append(
                "Pick a materially different proof route for the same active Lean target. Do not change the target, argue for its negation, or switch back to the root problem unless the displayed target itself is the root."
            )
        elif selected_work_type:
            lines.append(
                "For the next graph-selected task, follow the displayed Lean target exactly. Do not prove an opposite claim, drift back to a stale graph target, or switch to the root theorem unless the displayed target is the root."
            )
        else:
            lines.append(
                "Pick a materially different proof route for the stated theorem. If a helper route was false or too brittle, abandon that helper route and prove the theorem another way; do not try to prove the negation of the theorem."
            )
        lines.extend(
            [
                "Treat the previous route, proof scripts, and repair comments as stale. Do not continue repairing the same failing line or repeating the same failure explanation.",
                "Examples: change the witness or construction, prove a smaller bridge first, test a disputed subclaim with Lean, or replace the brittle helper route with a direct assembly of already proved facts.",
            ]
        )
        if selected_formalization_required:
            lines.append(
                "Submit complete Lean `theorem` or `lemma` declarations for the graph formalization task. If an auxiliary helper is needed, put it before the final declaration; the final declaration must state the selected obligation or parent-anchored bridge and use the helper."
            )
        else:
            lines.append(
                "Submit one executable Lean proof attempt for the new route. Express the route through checked local `have`/`suffices` steps or fully proved helper declarations inside the Lean artifact, not through pre-proof bullets."
            )
        lines.append(
            "Do not use `sorry`, `admit`, holes, placeholder bridge facts, or commentary-only Lean blocks."
        )
        return "\n".join(lines)

    # ----- Private helpers --------------------------------------------

    def _proof_state_root_solved(self) -> bool:
        if self.proof_state is None:
            return False
        # The actual ProofSearchState API uses ``find_root_proof_node`` /
        # ``mark_root_proved`` / ``is_root_solved`` depending on phase.
        # Probe defensively to keep M0 working before the proof_state
        # surface is finalized for sessions.
        for attr in ("is_root_solved", "root_solved", "is_root_proved"):
            method = getattr(self.proof_state, attr, None)
            if callable(method):
                try:
                    return bool(method())
                except Exception:
                    continue
        # Fallback: check proof_graph root status if available.
        graph = (
            getattr(self.dossier, "proof_graph", None)
            if self.dossier is not None
            else None
        )
        if graph is not None:
            root_id = getattr(graph, "root_node_id", "root")
            node = graph.nodes.get(root_id) if hasattr(graph, "nodes") else None
            if node is not None and getattr(node, "status", "") == "proved":
                return bool(
                    getattr(self.dossier, "final_proof_hash", None)
                    or getattr(node, "proof_hash", "")
                )
        return False

    def _durable_final_proof(self) -> Optional[str]:
        proof = str(self.final_proof or "").strip()
        if proof:
            return self.final_proof
        dossier = self.dossier
        if dossier is not None:
            proof = str(getattr(dossier, "final_proof", "") or "").strip()
            if proof:
                return str(getattr(dossier, "final_proof", "") or "")
            graph = getattr(dossier, "proof_graph", None)
            if graph is not None:
                root_id = getattr(graph, "root_node_id", "root")
                node = graph.nodes.get(root_id) if hasattr(graph, "nodes") else None
                metadata = getattr(node, "metadata", {}) if node is not None else {}
                if isinstance(metadata, dict):
                    proof = str(metadata.get("final_proof") or "").strip()
                    if proof:
                        return str(metadata.get("final_proof") or "")
        return None

    @staticmethod
    def _progress_node_record(node: Any, *, fallback_id: str = "") -> Dict[str, Any]:
        """Return the mathematical/search structure of a node.

        Deliberately excludes timestamps, diagnostics, retry counters, and last
        attempt witnesses: those are durable telemetry, but changing them is
        not proof progress and therefore must not buy another search epoch.
        """

        metadata = getattr(node, "metadata", {}) or {}
        if not isinstance(metadata, dict):
            metadata = {}
        structural_metadata_keys = (
            "candidate_statement",
            "target_statement",
            "route_id",
            "obligation_id",
            "pending_adjudication",
            "certified_fact",
            "formalization_required",
            "materialization_required",
            "root_unlock_bottleneck",
            "schedulable",
            "residual_goal_quarantined",
        )
        return {
            "node_id": str(getattr(node, "node_id", "") or fallback_id),
            "kind": str(getattr(node, "kind", "") or ""),
            "target": str(
                getattr(node, "target", "") or getattr(node, "statement", "") or ""
            ),
            "status": str(getattr(node, "status", "") or ""),
            "action": str(getattr(node, "action", "") or ""),
            "proof": str(
                getattr(node, "proof", "") or getattr(node, "proof_hash", "") or ""
            ),
            "proved_helper_name": str(getattr(node, "proved_helper_name", "") or ""),
            "source_hash": str(getattr(node, "source_hash", "") or ""),
            "parent_node_id": str(getattr(node, "parent_node_id", "") or ""),
            "dependencies": sorted(
                str(item or "")
                for item in (
                    list(getattr(node, "dependencies", ()) or ())
                    + list(getattr(node, "support_names", ()) or ())
                    + list(getattr(node, "blocked_by_node_ids", ()) or ())
                )
                if str(item or "")
            ),
            "children": sorted(
                str(item or "")
                for item in (
                    list(getattr(node, "children", ()) or ())
                    + list(getattr(node, "child_node_ids", ()) or ())
                )
                if str(item or "")
            ),
            "metadata": {
                key: metadata[key]
                for key in structural_metadata_keys
                if key in metadata
                and isinstance(metadata[key], (str, int, float, bool, type(None)))
            },
        }

    def _durable_search_progress_signature(self) -> str:
        """Hash durable mathematical state, excluding retry-only telemetry."""

        proof_state_nodes: List[Dict[str, Any]] = []
        raw_proof_nodes = getattr(getattr(self, "proof_state", None), "nodes", None)
        if isinstance(raw_proof_nodes, dict):
            proof_state_nodes = [
                self._progress_node_record(node, fallback_id=str(node_id or ""))
                for node_id, node in sorted(
                    raw_proof_nodes.items(), key=lambda item: str(item[0])
                )
            ]

        dossier = getattr(self, "dossier", None)
        verified_helpers: List[Dict[str, str]] = []
        raw_helpers = getattr(dossier, "verified_helpers", None)
        if isinstance(raw_helpers, dict):
            for name, helper in sorted(
                raw_helpers.items(), key=lambda item: str(item[0])
            ):
                verified_helpers.append(
                    {
                        "name": str(name or ""),
                        "source_hash": str(
                            getattr(helper, "source_hash", "")
                            or text_hash(str(getattr(helper, "source", "") or ""))
                        ),
                    }
                )

        graph = getattr(dossier, "proof_graph", None)
        graph_nodes: List[Dict[str, Any]] = []
        raw_graph_nodes = getattr(graph, "nodes", None)
        if isinstance(raw_graph_nodes, dict):
            graph_nodes = [
                self._progress_node_record(node, fallback_id=str(node_id or ""))
                for node_id, node in sorted(
                    raw_graph_nodes.items(), key=lambda item: str(item[0])
                )
            ]
        graph_edges = sorted(
            (
                str(getattr(edge, "source", "") or ""),
                str(getattr(edge, "target", "") or ""),
                str(getattr(edge, "kind", "") or ""),
            )
            for edge in list(getattr(graph, "edges", ()) or ())
        )
        payload = {
            "proof_state_nodes": proof_state_nodes,
            "verified_helpers": verified_helpers,
            "graph_nodes": graph_nodes,
            "graph_edges": graph_edges,
            "theory_bundle_ids": sorted(
                str(item or "")
                for item in tuple(self.theory_imported_bundle_ids or ())
                if str(item or "")
            ),
            "root_finalized": bool(self.root_finalized),
            "final_proof_hash": str(getattr(dossier, "final_proof_hash", "") or ""),
            # Helper eviction moves the durable state BACKWARDS onto a
            # configuration this session has already seen.  Without a monotone
            # marker the two histories hash identically, the continuation guard
            # reads the post-repair state as "already visited", and the session
            # permanently forfeits its progress grant.  Supersession only ever
            # grows, so it distinguishes "reached this set by regression" from
            # "never left it" without weakening the repeat-state guard.
            "helper_eviction_generation": int(
                getattr(dossier, "verified_helper_eviction_generation", 0) or 0
            ),
        }
        encoded = json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _recursive_planner_frontier_signature(self) -> str:
        """Hash only stable inputs that can change recursive planning.

        The generic progress signature intentionally contains the
        complete proof graph because graph-native actions consume it.  The
        recursive planner does not: feeding that signature into its fixed
        point guard let arbitrary graph narration reopen an otherwise
        unchanged paid planner frontier.  Conversely, the old signature did
        did not identify the live provider or execution environment, so an
        intentional model/library drift could leave a stale fixed point
        suppressing the new environment.
        """

        def _stable_value(value: Any) -> Any:
            if value is None or isinstance(value, (str, int, float, bool)):
                return value
            if isinstance(value, dict):
                return {
                    str(key): _stable_value(item)
                    for key, item in sorted(
                        value.items(), key=lambda pair: str(pair[0])
                    )
                }
            if isinstance(value, (list, tuple, set, frozenset)):
                items = [_stable_value(item) for item in value]
                if isinstance(value, (set, frozenset)):
                    return sorted(
                        items,
                        key=lambda item: json.dumps(
                            item, sort_keys=True, separators=(",", ":")
                        ),
                    )
                return items
            return str(value)

        def _config_identity(cfg: Any) -> Dict[str, Any]:
            keys = (
                "name",
                "base_url",
                "model",
                "temperature",
                "top_p",
                "timeout_s",
                "request_timeout_s",
                "request_timeout_disabled",
                "llm_deadline_policy",
                "model_revision",
                "revision",
                "deployment_revision",
                "weights_hash",
                "model_hash",
                "reasoning_effort",
                "reasoning_control_required",
                "thinking_enabled",
                "max_tokens",
                "context_window",
            )
            identity: Dict[str, Any] = {}
            for key in keys:
                try:
                    value = getattr(cfg, key)
                except (AttributeError, RuntimeError):
                    continue
                identity[key] = _stable_value(value)
            return identity

        def _client_identity(client: Any) -> Dict[str, Any]:
            configs = getattr(client, "configs", None)
            if isinstance(configs, (list, tuple)) and configs:
                # ModelChain's public ``cfg`` is only its primary.  Fallbacks
                # are executable planner environments too: reconfiguring one
                # must reopen a fixed point even when the primary is unchanged.
                return {"model_chain": [_config_identity(config) for config in configs]}
            return _config_identity(getattr(client, "cfg", None))

        dossier = getattr(self, "dossier", None)
        # Hash the same proof-context projection the recursive driver passes to
        # the planner.  Raw dossier maps also contain advisory-negative and
        # answer-unsafe helpers that are deliberately invisible to that prompt;
        # letting those records affect this identity recreates graph-only churn
        # under a different name.
        helper_blocks_getter = getattr(dossier, "verified_helper_blocks", None)
        helper_blocks = (
            [str(item or "") for item in helper_blocks_getter()]
            if callable(helper_blocks_getter)
            else []
        )

        raw_proposed = getattr(dossier, "proposed_helpers", None)
        proposed_helpers = (
            list(raw_proposed.values())
            if isinstance(raw_proposed, dict)
            else list(raw_proposed or ())
            if isinstance(raw_proposed, (list, tuple))
            else []
        )
        # Reuse the planner's answer-safe rendering rather than maintaining a
        # subtly different projection.  The rendered text is precisely what a
        # model can observe (including truncation and redaction).
        from ensemble_prover.mini_recursive import (
            _invalidated_statement_reason_for_statement,
            _render_proposed_helpers_for_planner,
        )

        conv = getattr(self, "conv", None)
        suppress_solution_placeholders = bool(
            getattr(dossier, "suppress_solution_placeholders", True)
        )
        opaque_mode = bool(getattr(conv, "opaque_mode", True))
        allow_official_answer_visibility = bool(
            getattr(conv, "allow_official_answer_visibility", False)
        )
        visible_proposed_helpers: List[Any] = []
        all_invalidated_reasons = dict(
            getattr(dossier, "mini_recursive_invalidated_statement_reasons", {}) or {}
        )
        invalidation_provenance = dict(
            getattr(dossier, "mini_recursive_invalidation_provenance", {}) or {}
        )
        for proposed in proposed_helpers:
            proposal_environment_hash = str(
                getattr(proposed, "statement_environment_hash", "") or ""
            ).strip()
            invalidated_reasons = {
                key: reason
                for key, reason in all_invalidated_reasons.items()
                if proposal_environment_hash
                and str(
                    dict(invalidation_provenance.get(key) or {}).get(
                        "target_environment_hash"
                    )
                    or ""
                ).strip()
                == proposal_environment_hash
            }
            _key, invalid_reason = _invalidated_statement_reason_for_statement(
                str(getattr(proposed, "statement", "") or ""),
                invalidated_reasons,
                helpers=helper_blocks,
                suppress_solution_placeholders=suppress_solution_placeholders,
                opaque_mode=opaque_mode,
                allow_official_answer_visibility=allow_official_answer_visibility,
            )
            if not invalid_reason:
                visible_proposed_helpers.append(proposed)
        proposed_prompt = _render_proposed_helpers_for_planner(
            visible_proposed_helpers,
            suppress_solution_placeholders=suppress_solution_placeholders,
            opaque_mode=opaque_mode,
            allow_official_answer_visibility=allow_official_answer_visibility,
        )

        environment_hash = str(
            getattr(dossier, "current_lean_environment_hash", "") or ""
        )

        # The planner consumes conserved mathematical-strategy memory in
        # addition to formal helper state.  Hash that typed lifecycle directly
        # while leaving unrelated proof-graph narration outside the fixed
        # point identity.
        proof_idea_lifecycle = []
        for idea_id, idea in sorted(
            dict(getattr(dossier, "proof_ideas", {}) or {}).items(),
            key=lambda item: str(item[0]),
        ):
            to_record = getattr(idea, "to_record", None)
            if not callable(to_record):
                continue
            proof_idea_lifecycle.append(
                {
                    "proof_idea_id": str(idea_id or ""),
                    "record": _stable_value(to_record()),
                }
            )

        payload = {
            "theorem_name": str(
                getattr(getattr(self, "problem", None), "theorem_name", "") or ""
            ),
            "problem_text": str(
                getattr(getattr(self, "problem", None), "docstring", "") or ""
            ),
            "lean_signature": str(
                getattr(getattr(self, "conv", None), "lean_signature", "") or ""
            ),
            "root_statement_hash": text_hash(
                str(getattr(dossier, "root_statement", "") or "")
            ),
            "active_root_targets": _stable_value(
                tuple(getattr(dossier, "active_root_targets", ()) or ())
            ),
            "verified_helper_blocks": [text_hash(block) for block in helper_blocks],
            "proposed_helpers_prompt_hash": text_hash(proposed_prompt),
            "proof_idea_lifecycle": proof_idea_lifecycle,
            "theory_bundle_ids": sorted(
                str(item or "")
                for item in tuple(self.theory_imported_bundle_ids or ())
                if str(item or "")
            ),
            "theory_snapshot": _stable_value(tuple(self.theory_snapshot or ())),
            "theory_context_hash": str(
                getattr(getattr(self, "theory_context_pair", None), "snapshot_hash", "")
                or ""
            ),
            "models": {
                "prover": _client_identity(getattr(self, "prover_client", None)),
                "refiner": _client_identity(getattr(self, "refiner_client", None)),
            },
            "environment_hash": environment_hash,
            "recursive_action_configs": [
                _stable_value(vars(getattr(action, "config", None)))
                for action in tuple(getattr(self, "actions", ()) or ())
                if str(getattr(action, "id", "") or "")
                in {"recursive_controller", "adaptive_recursive_fallback"}
                and hasattr(getattr(action, "config", None), "__dict__")
            ],
            # The recursive controller prefers THIS signature over the generic
            # durable one, so the eviction generation has to be folded in here
            # too: without it a repair that evicts helpers lands back on the
            # frontier where the fixed point was declared and the action stays
            # permanently non-applicable.
            "helper_eviction_generation": int(
                getattr(dossier, "verified_helper_eviction_generation", 0) or 0
            ),
        }
        try:
            from ensemble_prover.mini_recursive import (
                _recursive_runtime_component_identity,
            )

            payload["live_lean_environment"] = _recursive_runtime_component_identity(
                getattr(self, "lean", None)
            )
        except Exception:
            # Identity construction must remain total for lightweight test and
            # third-party Lean adapters; the coordinator hash remains a
            # conservative fallback when no runtime identity is available.
            payload["live_lean_environment"] = {}
        encoded = json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _begin_action_progress_observation(self, *, action_id: str = "") -> None:
        signature = self._durable_search_progress_signature()
        self._action_start_durable_progress_signature = signature
        if signature:
            self.durable_progress_signatures_seen.add(signature)
        self._action_start_frontier_formal_signature = ""
        formal_evidence = self._durable_formal_progress_evidence()
        self._action_start_frontier_formal_evidence = formal_evidence
        self._action_start_frontier_formal_signature = text_hash(
            json.dumps(formal_evidence, separators=(",", ":"))
        )
        self._action_start_frontier_action_key = None
        self._action_start_proof_work_semantic_identity = ""
        self._action_start_conversation_static_root_identity = ""
        selected_action_id = str(
            action_id or self.selected_work_item_action_id or ""
        ).strip()
        if not selected_action_id:
            return
        semantic_work_item = (
            self.selected_work_item
            if self.selected_work_item is not None
            else self._conversation_semantic_work_item(selected_action_id)
            if selected_action_id.startswith("conversation_turn")
            else None
        )
        budget = self.budgets.get(selected_action_id)
        if semantic_work_item is not None and (
            (budget is not None and budget.scope == "proof_work")
            or selected_action_id.startswith("conversation_turn")
        ):
            self._action_start_proof_work_semantic_identity = (
                self._proof_work_semantic_attempt_identity(
                    semantic_work_item,
                    action_id=selected_action_id,
                )
            )
            if selected_action_id.startswith("conversation_turn"):
                self._action_start_conversation_static_root_identity = (
                    self._proof_work_semantic_attempt_identity(
                        semantic_work_item,
                        action_id=selected_action_id,
                        omit_root_cognition=True,
                    )
                )
        if self.selected_work_item is None:
            return
        action_key = self.selected_frontier_action_key
        if action_key is None:
            action_key = self._frontier_action_key(
                self.selected_work_item,
                selected_action_id,
            )
            self.selected_frontier_action_key = action_key
        if len(action_key) != 6 or not any(action_key):
            return
        self._action_start_frontier_action_key = tuple(action_key)

    def _durable_formal_progress_evidence(self) -> Tuple[str, ...]:
        """Return monotone kernel-facing evidence, excluding failed/open churn."""

        evidence: Set[str] = set()
        dossier = getattr(self, "dossier", None)
        helpers = getattr(dossier, "verified_helpers", None)
        if isinstance(helpers, dict):
            for name, helper in helpers.items():
                source = str(getattr(helper, "source", "") or "")
                source_hash = str(
                    getattr(helper, "source_hash", "")
                    or (text_hash(source) if source.strip() else "")
                ).strip()
                if source_hash:
                    evidence.add(f"helper:{name}:{source_hash}")

        for namespace, nodes in (
            ("proof_state", getattr(getattr(self, "proof_state", None), "nodes", None)),
            (
                "proof_graph",
                getattr(getattr(dossier, "proof_graph", None), "nodes", None),
            ),
        ):
            if not isinstance(nodes, dict):
                continue
            for node_id, node in nodes.items():
                if str(getattr(node, "status", "") or "") != "proved":
                    continue
                proof_identity = str(
                    getattr(node, "proof_hash", "")
                    or getattr(node, "source_hash", "")
                    or getattr(node, "proved_helper_name", "")
                    or getattr(node, "proof", "")
                ).strip()
                if not proof_identity:
                    continue
                evidence.add(f"{namespace}:{node_id}:{proof_identity}")
        for bundle_id in tuple(self.theory_imported_bundle_ids or ()):
            clean = str(bundle_id or "").strip()
            if clean:
                evidence.add(f"theory_bundle:{clean}")
        return tuple(sorted(evidence))

    def _grant_frontier_progress_retry(
        self,
        *,
        outcome: MiniOutcome,
        metadata: Dict[str, Any],
        budget: ActionBudget,
    ) -> bool:
        """Retain exact graph work once for each fresh progress receipt.

        ``MiniOutcome.progress`` is deliberately stronger than "the current
        Lean failure got closer".  A tool-enabled graph turn can therefore be
        mathematically unsolved while still producing either a new durable
        formal state or an explicitly normalized diagnostic improvement.  Do
        not throw that route away after its first useful failure, but also do
        not turn arbitrary failure churn into extra model calls.
        """

        if str(outcome.action_id or "").startswith("conversation_turn") and not bool(
            self.conversation_budget_topups_enabled
        ):
            metadata["frontier_progress_retry_granted"] = False
            metadata["frontier_progress_retry_suppressed_reason"] = (
                "bounded_conversation_budget"
            )
            return False

        start_formal = str(self._action_start_frontier_formal_signature or "")
        start_formal_evidence = set(self._action_start_frontier_formal_evidence or ())
        action_key = self._action_start_frontier_action_key
        self._action_start_frontier_formal_signature = ""
        self._action_start_frontier_formal_evidence = ()
        self._action_start_frontier_action_key = None
        if (
            action_key is None
            or self.selected_work_item is None
            or outcome.solved
            or outcome.progress
            or outcome.exception is not None
            or bool(metadata.get("terminal_failure"))
            or bool(metadata.get("preserve_frontier_work"))
            or bool(metadata.get("defer_selected_frontier_action"))
            or bool(metadata.get("policy_repair_redirect"))
            or bool(metadata.get("llm_retryable"))
        ):
            return False
        if (
            str(outcome.action_id or "").strip()
            != str(self.selected_work_item_action_id or "").strip()
        ):
            return False

        after_formal_evidence = set(self._durable_formal_progress_evidence())
        fresh_formal_evidence = sorted(after_formal_evidence - start_formal_evidence)
        after_formal = text_hash(
            json.dumps(
                sorted(after_formal_evidence),
                separators=(",", ":"),
            )
        )
        formal_changed = bool(
            start_formal
            and after_formal
            and after_formal != start_formal
            and fresh_formal_evidence
        )
        diagnostic_count = int(
            metadata.get("semantic_diagnostic_progress_count", 0) or 0
        )
        diagnostic_signature = str(
            metadata.get("semantic_diagnostic_best_signature") or ""
        ).strip()
        diagnostic_improved = bool(diagnostic_count > 0 and diagnostic_signature)
        if not formal_changed and not diagnostic_improved:
            return False

        progress_receipts: List[str] = []
        if formal_changed:
            progress_receipts.append(
                "formal:"
                + text_hash(
                    json.dumps(
                        {
                            "formal_signature": after_formal,
                            "fresh_formal_evidence": fresh_formal_evidence,
                        },
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=True,
                    )
                )
            )
        if diagnostic_improved:
            progress_receipts.append("diagnostic:" + text_hash(diagnostic_signature))
        progress_signature = text_hash(
            json.dumps(
                sorted(progress_receipts),
                separators=(",", ":"),
                ensure_ascii=True,
            )
        )
        exact_key = tuple(str(item or "") for item in action_key)
        retry_keys = self._frontier_progress_retry_keys(
            self.selected_work_item,
            exact_key,
        )
        retry_key = retry_keys[0]
        receipt_keys = [
            (*alias_key, receipt)
            for alias_key in retry_keys
            for receipt in progress_receipts
        ]
        primary_receipt_keys = [(*retry_key, receipt) for receipt in progress_receipts]
        retry_count = int(self.frontier_progress_retry_counts.get(retry_key, 0) or 0)
        retry_limit = max(0, int(self.max_frontier_progress_retries or 0))
        fresh_receipt_keys = [
            key
            for key in primary_receipt_keys
            if key not in self.frontier_progress_signatures_seen
        ]
        signature_fresh = bool(fresh_receipt_keys)
        self.frontier_progress_signatures_seen.update(receipt_keys)
        if not signature_fresh or retry_count >= retry_limit:
            metadata.update(
                {
                    "frontier_progress_retry_granted": False,
                    "frontier_progress_retry_stagnant": not signature_fresh,
                    "frontier_progress_retry_limit_reached": (
                        signature_fresh and retry_count >= retry_limit
                    ),
                    "frontier_progress_signature": progress_signature,
                    "frontier_progress_retry_count": retry_count,
                    "frontier_progress_retry_limit": retry_limit,
                }
            )
            self._increment_dossier_metric(
                (
                    "mini_session_frontier_progress_retry_stagnant"
                    if not signature_fresh
                    else "mini_session_frontier_progress_retry_limit_reached"
                ),
                1,
            )
            self._record_event(
                {
                    "phase": "session_frontier_progress_retry",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(outcome.action_id or ""),
                    "frontier_action_key": list(exact_key),
                    "frontier_progress_retry_key": list(retry_key),
                    "progress_signature": progress_signature,
                    "progress_receipts": list(progress_receipts),
                    "fresh_progress_receipt_count": len(fresh_receipt_keys),
                    "formal_progress": formal_changed,
                    "diagnostic_progress": diagnostic_improved,
                    "retry_count": retry_count,
                    "retry_limit": retry_limit,
                    "verdict": (
                        "progress_signature_stagnant"
                        if not signature_fresh
                        else "progress_retry_limit_reached"
                    ),
                }
            )
            return False

        for alias_key in retry_keys:
            self.frontier_progress_retry_counts[alias_key] = max(
                retry_count + 1,
                int(self.frontier_progress_retry_counts.get(alias_key, 0) or 0),
            )
            self.frontier_progress_grants_seen.add(
                (*alias_key, "grant:" + progress_signature)
            )
        # A selector can only have reached this exact action if it was live,
        # but branch replay or a context-hash transition may leave stale
        # suppressors.  Release only this exact selection identity.
        self.consumed_frontier_action_keys.discard(exact_key)
        self.skipped_frontier_action_keys.discard(exact_key)
        self.consumed_frontier_work_keys.discard(tuple(exact_key[:5]))
        self.skipped_frontier_work_keys.discard(tuple(exact_key[:5]))

        old_max_invocations = int(budget.max_invocations)
        invocation_granted = 0
        if (
            budget.scope == "session"
            and budget.max_invocations >= 0
            and budget.invocations >= budget.max_invocations
        ):
            budget.max_invocations = int(budget.invocations) + 1
            invocation_granted = max(
                0,
                int(budget.max_invocations) - old_max_invocations,
            )
        action = self.registered_action(outcome.action_id)
        seconds_granted = 0.0
        if (
            budget.max_total_seconds > 0
            and budget.total_seconds >= budget.max_total_seconds
        ):
            old_max_seconds = float(budget.max_total_seconds)
            estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
            budget.max_total_seconds = float(budget.total_seconds) + max(
                30.0,
                estimate,
            )
            seconds_granted = max(
                0.0,
                float(budget.max_total_seconds) - old_max_seconds,
            )
        prompt_turn_budget_granted = self._sync_conversation_prompt_budget(
            outcome.action_id,
            min_turn_budget=int(budget.invocations) + 1,
        )
        old_max_iterations = int(self.max_iterations or 0)
        self.max_iterations = max(
            old_max_iterations,
            int(self.iteration or 0) + 2,
        )
        self.fallback_actions_attempted = False
        metadata.update(
            {
                "preserve_frontier_work": True,
                "frontier_progress_retry_granted": True,
                "frontier_progress_signature": progress_signature,
                "frontier_progress_formal": formal_changed,
                "frontier_progress_diagnostic": diagnostic_improved,
                "frontier_progress_retry_count": retry_count + 1,
                "frontier_progress_retry_limit": retry_limit,
            }
        )
        self._increment_dossier_metric(
            "mini_session_frontier_progress_retries_granted",
            1,
        )
        self._record_event(
            {
                "phase": "session_frontier_progress_retry",
                "iteration": int(self.iteration or 0),
                "action_id": str(outcome.action_id or ""),
                "frontier_action_key": list(exact_key),
                "frontier_progress_retry_key": list(retry_key),
                "progress_signature": progress_signature,
                "progress_receipts": list(progress_receipts),
                "fresh_progress_receipt_count": len(fresh_receipt_keys),
                "formal_progress": formal_changed,
                "diagnostic_progress": diagnostic_improved,
                "retry_count": retry_count + 1,
                "retry_limit": retry_limit,
                "old_max_invocations": old_max_invocations,
                "max_invocations": int(budget.max_invocations),
                "invocation_granted": invocation_granted,
                "prompt_turn_budget_granted": prompt_turn_budget_granted,
                "cumulative_seconds_granted": round(seconds_granted, 6),
                "old_max_iterations": old_max_iterations,
                "max_iterations": int(self.max_iterations or 0),
                "verdict": "fresh_progress_retry_granted",
            }
        )
        return True

    def _grant_distinct_strong_progress_continuation(
        self,
        *,
        action_id: str,
        budget: ActionBudget,
        strong_progress: bool,
        outcome: MiniOutcome,
    ) -> bool:
        """Rearm local ceilings once for a new durable strong-progress state."""

        if str(action_id or "").startswith("conversation_turn") and not bool(
            self.conversation_budget_topups_enabled
        ):
            return False

        before = str(self._action_start_durable_progress_signature or "")
        self._action_start_durable_progress_signature = ""
        if (
            not strong_progress
            or not bool(outcome.progress)
            or bool(outcome.solved)
            or outcome.exception is not None
        ):
            return False
        after = self._durable_search_progress_signature()
        if (
            not after
            or after == before
            or after in self.durable_progress_signatures_seen
        ):
            self._record_event(
                {
                    "phase": "session_progress_continuation",
                    "iteration": int(self.iteration or 0),
                    "action_id": str(action_id or ""),
                    "durable_state_changed": bool(after and after != before),
                    "durable_state_seen": bool(
                        after and after in self.durable_progress_signatures_seen
                    ),
                    "verdict": "strong_progress_continuation_not_earned",
                }
            )
            return False

        old_max_invocations = int(budget.max_invocations)
        invocation_granted = 0
        action = self.registered_action(action_id)
        seconds_exhausted = bool(
            budget.max_total_seconds > 0
            and budget.total_seconds >= budget.max_total_seconds
        )
        seconds_granted = 0.0
        if seconds_exhausted:
            # Cumulative action time is scheduler accounting, not an
            # operation watchdog.  A distinct durable mathematical state
            # earns one more dispatch window; the action's provider/Lean/tool
            # calls retain their own hard per-operation deadlines.
            old_max_seconds = float(budget.max_total_seconds)
            estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
            continuation_window = max(30.0, estimate)
            budget.max_total_seconds = float(budget.total_seconds) + continuation_window
            seconds_granted = max(
                0.0,
                float(budget.max_total_seconds) - old_max_seconds,
            )

        self.durable_progress_signatures_seen.add(after)
        self.last_durable_progress_signature = after
        old_max_iterations = int(self.max_iterations or 0)
        min_next_iteration_budget = int(self.iteration or 0) + 2
        if old_max_iterations < min_next_iteration_budget:
            self.max_iterations = min_next_iteration_budget

        if (
            budget.scope == "session"
            and budget.max_invocations >= 0
            and budget.invocations >= budget.max_invocations
        ):
            budget.max_invocations = int(budget.invocations) + 1
            invocation_granted = max(
                0, int(budget.max_invocations) - old_max_invocations
            )

        named_recursive_pool_granted = 0
        recursive_pool_attr = str(
            getattr(action, "progress_continuation_pool_attr", "")
            or getattr(action, "budget_attr", "")
            or ""
        ).strip()
        if recursive_pool_attr and hasattr(self, recursive_pool_attr):
            old_recursive_pool = int(getattr(self, recursive_pool_attr, 0) or 0)
            if old_recursive_pool <= 0:
                setattr(self, recursive_pool_attr, old_recursive_pool + 1)
                named_recursive_pool_granted = 1

        limits_extended = bool(
            int(self.max_iterations or 0) > old_max_iterations
            or invocation_granted > 0
            or named_recursive_pool_granted > 0
            or seconds_granted > 0.0
        )
        if limits_extended:
            self.progress_continuation_grants += 1
            self._increment_dossier_metric(
                "mini_session_progress_continuation_grants",
                1,
            )
        self._record_event(
            {
                "phase": "session_progress_continuation",
                "iteration": int(self.iteration or 0),
                "action_id": str(action_id or ""),
                "durable_progress_signature": after,
                "old_max_iterations": old_max_iterations,
                "max_iterations": int(self.max_iterations or 0),
                "old_max_invocations": old_max_invocations,
                "max_invocations": int(budget.max_invocations),
                "invocation_granted": invocation_granted,
                "cumulative_seconds_granted": round(seconds_granted, 6),
                "recursive_pool_attr": recursive_pool_attr,
                "named_recursive_pool_granted": named_recursive_pool_granted,
                "cumulative_seconds_exhausted": seconds_exhausted,
                "verdict": (
                    "distinct_strong_progress_continuation_granted"
                    if limits_extended
                    else "distinct_strong_progress_recorded"
                ),
            }
        )
        return limits_extended

    def _proof_state_signature(self) -> Optional[str]:
        """SHA256-shortened signature over (node_count, proved_count, sorted open IDs).

        Cheap and stable. Used only for stagnation detection — false
        positives degrade gracefully (extra fallback firing).
        """

        if self.proof_state is None:
            return None
        nodes = getattr(self.proof_state, "nodes", None)
        if nodes is None:
            return None
        try:
            items = list(nodes.values())
        except Exception:
            return None
        node_count = len(items)
        proved_count = sum(1 for n in items if getattr(n, "status", "") == "proved")
        open_ids = sorted(
            getattr(n, "node_id", "")
            for n in items
            if getattr(n, "status", "") == "open"
        )
        assembly_parts = []
        for node in items:
            for group in list(getattr(node, "assembly_attempt_groups", ()) or ()):
                assembly_parts.append(
                    ":".join(
                        [
                            str(getattr(node, "node_id", "") or ""),
                            str(getattr(group, "assembly_id", "") or ""),
                            str(getattr(group, "status", "") or ""),
                            str(int(getattr(group, "attempt_count", 0) or 0)),
                            ",".join(
                                str(item or "")
                                for item in list(
                                    getattr(group, "last_attempt_witness", ()) or ()
                                )
                            ),
                            ",".join(
                                str(item or "")
                                for item in list(
                                    getattr(group, "child_node_ids", ()) or ()
                                )
                            ),
                        ]
                    )
                )
        root_node_id = str(getattr(self.proof_state, "root_node_id", "root") or "root")
        root = next(
            (
                node
                for node in items
                if str(getattr(node, "node_id", "") or "") == root_node_id
            ),
            None,
        )
        root_tactic_keys = (
            list(getattr(root, "root_tactic_attempted_context_keys", ()) or ())
            if root is not None
            else []
        )
        payload = "|".join(
            [
                str(node_count),
                str(proved_count),
                ",".join(open_ids),
                ";".join(sorted(assembly_parts)),
                ",".join(sorted(str(item or "") for item in root_tactic_keys)),
            ]
        )
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16]

    def _applicable_action_count(self) -> int:
        """Telemetry-only count of actions still allowed by budget.

        Some action ``is_applicable`` predicates inspect and update graph
        bookkeeping. The iteration heartbeat must not perturb scheduling state
        before ``select_next_action`` has chosen the real action.
        """

        return sum(
            1
            for action in self.actions
            if not (self.budgets.get(action.id) and self.budgets[action.id].exhausted())
        )

    def _safe_is_applicable(
        self,
        action: Action,
        *,
        context: str,
        predicate: Optional[Callable[[Any], bool]] = None,
    ) -> bool:
        """Run an action applicability predicate without killing the session."""

        action_id = str(getattr(action, "id", "") or "").strip()
        if action_id in self._scheduler_transient_suppressed_action_ids:
            return False
        if action_id in self._dispatch_generation_deferred_action_ids:
            ready_at = float(
                self._dispatch_generation_action_ready_monotonic.get(action_id, 0.0)
                or 0.0
            )
            if time.monotonic() < ready_at:
                return False
            self._dispatch_generation_deferred_action_ids.discard(action_id)
            self._dispatch_generation_action_ready_monotonic.pop(action_id, None)

        previous_probe_context = str(
            getattr(self, "_applicability_probe_context", "") or ""
        )
        self._applicability_probe_context = str(context or "")
        try:
            return bool(
                predicate(self) if predicate is not None else action.is_applicable(self)
            )
        except Exception as exc:
            # Ranking/quotation is an observational operation.  A broken
            # candidate probe must fail closed without manufacturing durable
            # telemetry for work that was never selected.
            if str(context or "").endswith("_probe"):
                _LOGGER.debug(
                    "Action %r read-only applicability probe raised",
                    str(getattr(action, "id", "") or ""),
                    exc_info=True,
                )
                return False
            self._record_event(
                {
                    "phase": "session_action_applicability",
                    "action_id": str(getattr(action, "id", "") or ""),
                    "context": str(context or ""),
                    "error": f"{type(exc).__name__}: {exc}",
                    "verdict": "applicability_exception",
                }
            )
            self._defer_selector_infrastructure(
                action_ids=(str(getattr(action, "id", "") or ""),),
                context=str(context or "applicability"),
                error=exc,
            )
            return False
        finally:
            self._applicability_probe_context = previous_probe_context

    def _defer_selector_infrastructure(
        self,
        *,
        action_ids: Sequence[str],
        context: str,
        error: BaseException,
    ) -> None:
        """Persist a timed, accounting-neutral selector retry receipt."""

        clean_ids = tuple(
            dict.fromkeys(
                str(action_id or "").strip()
                for action_id in action_ids
                if str(action_id or "").strip()
            )
        )
        for action_id in clean_ids:
            prior = dict(
                self.model_call_deferred_static_action_metadata.get(action_id) or {}
            )
            metadata = {
                "action_id": action_id,
                "llm_failure_scope": "scoped",
                "llm_failure_kind": "mini_action_infrastructure_exception",
                "scoped_failure_reason": "mini_selector_infrastructure_exception",
                "llm_retryable": True,
                "zero_provider_failure": True,
                "provider_calls_completed": 0,
                "preserve_frontier_work": True,
                "defer_selected_frontier_action": True,
                "preserve_action_budget": True,
                "iteration_neutral": True,
                "scheduler_neutral": True,
                "stagnation_neutral": True,
                "hard_pivot_neutral": True,
                "selector_infrastructure_context": str(context or ""),
                "selector_infrastructure_error": (f"{type(error).__name__}: {error}"),
                **self._persistent_infrastructure_retry_fields(prior),
            }
            self.model_call_deferred_static_action_ids.add(action_id)
            self.model_call_deferred_static_action_metadata[action_id] = metadata
            selected_record = dict(self.selected_work_item_record or {})
            if (
                selected_record
                and str(self.selected_work_item_action_id or "").strip() == action_id
            ):
                action_key = self._frontier_action_key(
                    self.selected_work_item,
                    action_id,
                )
                self.model_call_deferred_frontier_action_keys.add(action_key)
                self.model_call_deferred_frontier_action_metadata[action_key] = dict(
                    metadata
                )
        self._record_event(
            {
                "phase": "session_selector_infrastructure",
                "iteration": int(self.iteration or 0),
                "action_ids": list(clean_ids),
                "context": str(context or ""),
                "error_type": type(error).__name__,
                "error": str(error),
                "verdict": "selector_infrastructure_deferred_nonterminal",
            }
        )

    def _has_unresolved_search_work(self) -> bool:
        """Return whether the session still has root/graph work worth pursuing."""

        if self._proof_state_root_solved():
            return False

        proof_state = self.proof_state
        if proof_state is not None:
            nodes = getattr(proof_state, "nodes", None)
            if isinstance(nodes, dict):
                root_id = str(getattr(proof_state, "root_node_id", "root") or "root")
                root_node = nodes.get(root_id)
                if self._node_status_unresolved(root_node):
                    return True
                for node in nodes.values():
                    if self._node_status_unresolved(node):
                        return True
            else:
                # A proof_state without an inspectable node table is still
                # unresolved unless one of the solved probes above succeeded.
                return True

        graph = (
            getattr(self.dossier, "proof_graph", None)
            if self.dossier is not None
            else None
        )
        if graph is not None:
            nodes = getattr(graph, "nodes", None)
            if isinstance(nodes, dict):
                root_id = str(getattr(graph, "root_node_id", "root") or "root")
                root_node = nodes.get(root_id)
                if self._node_status_unresolved(root_node):
                    return True
                for node in nodes.values():
                    if self._node_status_unresolved(node):
                        return True
            else:
                return True

        return False

    @staticmethod
    def _node_status_unresolved(node: Any) -> bool:
        if node is None:
            return False
        metadata = getattr(node, "metadata", {}) or {}
        if isinstance(metadata, dict):
            if bool(metadata.get("residual_goal_quarantined")):
                return False
            if metadata.get("schedulable") is False:
                return False
            if bool(metadata.get("failed_proof_residual_quarantined")):
                return False
            action = str(metadata.get("action") or "").strip()
        else:
            action = ""
        if not action:
            action = str(getattr(node, "action", "") or "").strip()
        if action == "repair_failed_proof_residue":
            children = list(getattr(node, "children", []) or [])
            child_node_ids = list(getattr(node, "child_node_ids", []) or [])
            if not children and not child_node_ids:
                return False
        status = str(getattr(node, "status", "") or "").strip().lower()
        if not status:
            return True
        return status not in {
            "proved",
            "closed",
            "solved",
            "obsolete",
            "superseded",
            "failed",
            "rejected",
        }

    def _recover_from_no_applicable_action(self) -> bool:
        """Grant bounded continuation budget after a root-open dead selector."""

        self._reconcile_repair_policy_narrowing(trigger="no_applicable_recovery")
        if self.repair_policy_narrowing_required:
            if self._repair_policy_child_adaptive_fallback_available():
                self.last_failure_reason = ""
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "stagnation_counter": self.stagnation_counter,
                        "reason": "repair_policy_yielded_to_child_adaptive_fallback",
                        "selected_work_item": dict(
                            self.repair_policy_narrowing_selected_work_record
                        ),
                        "verdict": "repair_policy_yielded_to_child_adaptive_fallback",
                    }
                )
                return True
            if self._materialize_repair_policy_narrowing_scope():
                self.last_failure_reason = ""
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "stagnation_counter": self.stagnation_counter,
                        "reason": "repair_policy_narrowing_scope_materialized",
                        "selected_work_item": dict(
                            self.repair_policy_narrowing_selected_work_record
                        ),
                        "verdict": "repair_policy_scope_materialized",
                    }
                )
                return True
            if self._grant_cost_governed_continuation_budget(
                reason="repair_policy_narrowing_no_applicable",
            ):
                self.last_failure_reason = ""
                return True
            if self._renew_provider_lanes_instead_of_terminal(
                "repair_policy_narrowing_no_applicable"
            ):
                return True
            self.last_failure_reason = "repair_policy_narrowing_no_applicable"
            self._increment_dossier_metric(
                "mini_session_repair_policy_narrowing_no_recovery",
                1,
            )
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "reason": self.last_failure_reason,
                    "selected_work_item": dict(
                        self.repair_policy_narrowing_selected_work_record
                    ),
                    "verdict": "terminal_repair_policy_narrowing",
                }
            )
            return False

        if self._arm_available_fallback_after_no_applicable():
            return True

        reason = ""
        configured_action_ids = tuple(
            str(action_id or "").strip()
            for action_id in self.no_applicable_recovery_action_ids
            if str(action_id or "").strip()
        )
        if "graph_recursive_decompose" in configured_action_ids:
            configured_action_ids = tuple(
                dict.fromkeys(
                    (
                        *configured_action_ids,
                        *(
                            str(getattr(action, "id", "") or "")
                            for action in self.actions
                            if self._is_graph_recursive_action(action)
                        ),
                    )
                )
            )
        deferred_recovery_action_ids = self._model_call_deferred_recovery_action_ids()
        action_ids = tuple(
            dict.fromkeys((*configured_action_ids, *deferred_recovery_action_ids))
        )
        recovery_action_id_source = (
            "configured+model_call_deferred"
            if configured_action_ids and deferred_recovery_action_ids
            else "configured"
            if configured_action_ids
            else "model_call_deferred"
            if deferred_recovery_action_ids
            else ""
        )
        serviceable_action_ids: Set[str] = set()
        deferred_only_serviceable_action_ids: Set[str] = set()
        released_deferred_action_ids: Set[str] = set()

        def apply_materialization_pending_recovery() -> bool:
            materialization_release = (
                self._release_materialization_pending_recovery_suppressors(action_ids)
            )
            released_materialization_actions = int(
                materialization_release.get("released_action_keys", 0) or 0
            )
            if released_materialization_actions <= 0:
                return False
            self.no_applicable_recovery_count += 1
            self.fallback_actions_attempted = False
            self.stagnation_counter = 0
            self.soft_progress_streak = 0
            self.max_iterations = max(
                int(self.max_iterations or 0),
                int(self.iteration or 0) + 2,
            )
            self.expand_max_iterations_to_action_budgets(headroom=2)
            self.last_failure_reason = ""
            self._increment_dossier_metric(
                "mini_session_materialization_pending_recoveries",
                1,
            )
            self._increment_dossier_metric(
                "mini_session_materialization_pending_suppressors_released",
                released_materialization_actions,
            )
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "recovery_count": self.no_applicable_recovery_count,
                    "max_recoveries": self.max_no_applicable_recoveries,
                    "serviceable_action_ids": sorted(serviceable_action_ids),
                    "deferred_only_serviceable_action_ids": sorted(
                        deferred_only_serviceable_action_ids
                    ),
                    "released_deferred_action_ids": sorted(
                        released_deferred_action_ids
                    ),
                    "released_materialization_pending_action_keys": (
                        released_materialization_actions
                    ),
                    "released_materialization_pending_logical_keys": int(
                        materialization_release.get("released_logical_keys", 0) or 0
                    ),
                    "released_materialization_pending_action_ids": list(
                        materialization_release.get("released_action_ids") or []
                    ),
                    "budget_grants": dict(
                        materialization_release.get("budget_grants") or {}
                    ),
                    "recovery_action_id_source": recovery_action_id_source,
                    "deferred_static_action_ids": sorted(
                        str(action_id)
                        for action_id in self.model_call_deferred_static_action_ids
                        if str(action_id or "").strip()
                    ),
                    "deferred_frontier_action_count": len(
                        self.model_call_deferred_frontier_action_keys
                    ),
                    "max_iterations": self.max_iterations,
                    "verdict": "materialization_pending_suppression_released",
                }
            )
            return True

        funded_persistent_retry = self._has_funded_persistent_infrastructure_retry()
        if not self._has_unresolved_search_work() and not funded_persistent_retry:
            reason = "no_unresolved_work"
        else:
            serviceable_action_ids = (
                self._serviceable_no_applicable_recovery_action_ids(action_ids)
                if action_ids
                else set()
            )
            deferred_only_serviceable_action_ids = (
                self._deferred_only_no_applicable_recovery_action_ids(action_ids)
                if action_ids
                else set()
            )
            if deferred_only_serviceable_action_ids:
                # Reaching this method means the ordinary selector already
                # found no dispatchable action.  A separately "serviceable"
                # family may still be blocked by budget/narrowing and must not
                # prevent a retryable scoped failure from releasing its own
                # bounded recovery lane.  The per-action retry counters below
                # remain the loop bound.
                released_deferred_action_ids = (
                    self._release_retryable_deferred_no_applicable_recovery_action_ids(
                        action_ids,
                        reason="no_applicable_action:deferred_only_serviceable_work",
                    )
                )
                if released_deferred_action_ids:
                    serviceable_action_ids = (
                        self._serviceable_no_applicable_recovery_action_ids(action_ids)
                        if action_ids
                        else set()
                    )
                    serviceable_action_ids.update(released_deferred_action_ids)
                    deferred_only_serviceable_action_ids = (
                        self._deferred_only_no_applicable_recovery_action_ids(
                            action_ids
                        )
                        if action_ids
                        else set()
                    )
            if not serviceable_action_ids:
                reason = "no_serviceable_frontier_work"
            elif apply_materialization_pending_recovery():
                return True
            elif (
                self.no_applicable_recovery_count
                >= max(
                    0,
                    int(self.max_no_applicable_recoveries or 0),
                )
                and not released_deferred_action_ids
            ):
                # A model-defer release is independently bounded by its own
                # retry counter. Let it continue through the existing budget
                # grant/release path even when generic recovery is disabled.
                reason = "recovery_budget_exhausted"
            elif (
                int(self.no_applicable_recovery_budget_increment or 0) <= 0
                and not released_deferred_action_ids
            ):
                reason = "recovery_increment_not_configured"

        if reason:
            root_solved_without_finalization = bool(
                reason == "no_unresolved_work"
                and self._proof_state_root_solved()
                and not (self.root_finalized and self._durable_final_proof())
            )
            if (
                root_solved_without_finalization
                and self._grant_cost_governed_continuation_budget(
                    reason=f"no_applicable_action:{reason}",
                    action_ids=action_ids,
                    require_unresolved_work=not root_solved_without_finalization,
                )
            ):
                self.last_failure_reason = ""
                return True
            if (
                reason == "no_serviceable_frontier_work"
                and self._cost_budget_continuation_enabled()
            ):
                self._record_cost_governed_static_suppressed(
                    reason=f"no_applicable_action:{reason}",
                    suppression_reason=reason,
                )
            if deferred_only_serviceable_action_ids:
                self._increment_dossier_metric(
                    "mini_session_no_applicable_deferred_only_serviceable_work",
                    1,
                )
            if reason == "no_serviceable_frontier_work":
                if apply_materialization_pending_recovery():
                    return True
                released_action_id = self._release_action_local_transient_cooldown()
                if released_action_id:
                    self.fallback_actions_attempted = False
                    self.max_iterations = max(
                        int(self.max_iterations or 0),
                        int(self.iteration or 0) + 2,
                    )
                    self.last_failure_reason = ""
                    self._increment_dossier_metric(
                        "mini_session_action_local_cooldown_recoveries",
                        1,
                    )
                    self._record_event(
                        {
                            "phase": "session_no_applicable_recovery",
                            "iteration": self.iteration,
                            "action_id": released_action_id,
                            "recovery_count": self.no_applicable_recovery_count,
                            "max_iterations": self.max_iterations,
                            "verdict": ("action_local_transient_cooldown_released"),
                        }
                    )
                    return True
            if reason != "no_unresolved_work":
                # Renewal is the last recovery move, after deterministic
                # materialization and transient-cooldown releases.
                if self._renew_provider_lanes_instead_of_terminal(reason):
                    return True
            self.last_failure_reason = reason
            self._increment_dossier_metric("mini_session_no_applicable_terminal", 1)
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "recovery_count": self.no_applicable_recovery_count,
                    "max_recoveries": self.max_no_applicable_recoveries,
                    "serviceable_action_ids": sorted(serviceable_action_ids),
                    "deferred_only_serviceable_action_ids": sorted(
                        deferred_only_serviceable_action_ids
                    ),
                    "released_deferred_action_ids": sorted(
                        released_deferred_action_ids
                    ),
                    "recovery_action_id_source": recovery_action_id_source,
                    "deferred_static_action_ids": sorted(
                        str(action_id)
                        for action_id in self.model_call_deferred_static_action_ids
                        if str(action_id or "").strip()
                    ),
                    "deferred_frontier_action_count": len(
                        self.model_call_deferred_frontier_action_keys
                    ),
                    "reason": reason,
                    "verdict": "terminal_no_applicable_action",
                }
            )
            return False

        increment = max(1, int(self.no_applicable_recovery_budget_increment or 0))
        budget_grants: Dict[str, Dict[str, Any]] = {}
        total_granted = 0
        for action_id in action_ids:
            if action_id not in serviceable_action_ids:
                continue
            action = self.registered_action(action_id)
            budget = self.budgets.get(action_id)
            if action is None or budget is None:
                continue
            if action_id.startswith("conversation_turn") and not bool(
                self.conversation_budget_topups_enabled
            ):
                continue
            graph_pool_exhausted = False
            if self._is_graph_recursive_action(action):
                graph_pool_exhausted = (
                    hasattr(self, "graph_recursive_decompose_remaining")
                    and int(
                        getattr(self, "graph_recursive_decompose_remaining", 0) or 0
                    )
                    <= 0
                )
            recursive_pool_attr = ""
            recursive_pool_exhausted = False
            if action_id in {"recursive_controller", "adaptive_recursive_fallback"}:
                recursive_pool_attr = str(
                    getattr(action, "budget_attr", "") or ""
                ).strip()
                recursive_pool_exhausted = bool(
                    recursive_pool_attr
                    and hasattr(self, recursive_pool_attr)
                    and int(getattr(self, recursive_pool_attr, 0) or 0) <= 0
                )
            required_dispatch_budget_s = self._frontier_required_dispatch_budget_s(
                action,
                self.selected_work_item_record,
            )
            remaining_action_budget_s = (
                float(budget.max_total_seconds) - float(budget.total_seconds)
                if budget.scope in {"session", "proof_work"}
                and budget.max_total_seconds > 0.0
                else float("inf")
            )
            action_budget_underfunded = bool(
                required_dispatch_budget_s > 0.0
                and remaining_action_budget_s < required_dispatch_budget_s
            )
            if (
                not budget.exhausted()
                and not graph_pool_exhausted
                and not recursive_pool_exhausted
                and not action_budget_underfunded
            ):
                continue
            pool_granted = 0
            if graph_pool_exhausted:
                old_remaining = int(
                    getattr(self, "graph_recursive_decompose_remaining", 0) or 0
                )
                pool_granted = increment
                self.graph_recursive_decompose_remaining = old_remaining + pool_granted
            if recursive_pool_exhausted and recursive_pool_attr:
                old_remaining = int(getattr(self, recursive_pool_attr, 0) or 0)
                pool_granted += increment
                setattr(
                    self,
                    recursive_pool_attr,
                    old_remaining + increment,
                )
            if budget.max_invocations >= 0:
                old_max = int(budget.max_invocations)
                old_invocations = int(budget.invocations)
                new_max = max(old_max + increment, old_invocations + increment)
                granted = max(0, new_max - max(old_max, old_invocations))
                budget.max_invocations = new_max
            else:
                old_max = int(budget.max_invocations)
                old_invocations = int(budget.invocations)
                granted = 0
            seconds_granted = 0.0
            if budget.max_total_seconds > 0 and (
                budget.total_seconds >= budget.max_total_seconds
                or action_budget_underfunded
            ):
                old_seconds = float(budget.max_total_seconds)
                estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
                seconds_granted = max(
                    30.0,
                    float(increment) * max(1.0, estimate),
                    required_dispatch_budget_s,
                )
                budget.max_total_seconds = float(budget.total_seconds) + seconds_granted
                seconds_granted = max(
                    0.0, float(budget.max_total_seconds) - old_seconds
                )
            prompt_turn_budget_granted = self._sync_conversation_prompt_budget(
                action_id,
                min_turn_budget=(
                    int(budget.max_invocations) if budget.max_invocations >= 0 else 0
                ),
            )
            if (
                granted <= 0
                and seconds_granted <= 0
                and pool_granted <= 0
                and prompt_turn_budget_granted <= 0
            ):
                continue
            total_granted += int(max(granted, pool_granted, prompt_turn_budget_granted))
            budget_grants[action_id] = {
                "old_max_invocations": old_max,
                "new_max_invocations": int(budget.max_invocations),
                "invocations": old_invocations,
                "granted_invocations": int(granted),
                "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                "granted_internal_pool": int(pool_granted),
                "granted_seconds": round(seconds_granted, 4),
            }

        if not budget_grants and not serviceable_action_ids:
            if self._grant_cost_governed_continuation_budget(
                reason="no_applicable_action:no_registered_recovery_actions",
                action_ids=action_ids,
            ):
                self.last_failure_reason = ""
                return True
            self.last_failure_reason = "no_registered_recovery_actions"
            self._increment_dossier_metric("mini_session_no_applicable_terminal", 1)
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "recovery_count": self.no_applicable_recovery_count,
                    "max_recoveries": self.max_no_applicable_recoveries,
                    "serviceable_action_ids": sorted(serviceable_action_ids),
                    "deferred_only_serviceable_action_ids": sorted(
                        deferred_only_serviceable_action_ids
                    ),
                    "released_deferred_action_ids": sorted(
                        released_deferred_action_ids
                    ),
                    "recovery_action_id_source": recovery_action_id_source,
                    "deferred_static_action_ids": sorted(
                        str(action_id)
                        for action_id in self.model_call_deferred_static_action_ids
                        if str(action_id or "").strip()
                    ),
                    "deferred_frontier_action_count": len(
                        self.model_call_deferred_frontier_action_keys
                    ),
                    "reason": "no_registered_recovery_actions",
                    "verdict": "terminal_no_applicable_action",
                }
            )
            return False

        if not budget_grants:
            if released_deferred_action_ids:
                self.no_applicable_recovery_count += 1
                self.fallback_actions_attempted = False
                self.stagnation_counter = 0
                self.soft_progress_streak = 0
                self.max_iterations = max(
                    int(self.max_iterations or 0),
                    int(self.iteration or 0) + 2,
                )
                self.expand_max_iterations_to_action_budgets(headroom=2)
                self.last_failure_reason = ""
                self._increment_dossier_metric(
                    "mini_session_no_applicable_recoveries",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "stagnation_counter": self.stagnation_counter,
                        "recovery_count": self.no_applicable_recovery_count,
                        "max_recoveries": self.max_no_applicable_recoveries,
                        "serviceable_action_ids": sorted(serviceable_action_ids),
                        "deferred_only_serviceable_action_ids": sorted(
                            deferred_only_serviceable_action_ids
                        ),
                        "released_deferred_action_ids": sorted(
                            released_deferred_action_ids
                        ),
                        "recovery_action_id_source": recovery_action_id_source,
                        "deferred_static_action_ids": sorted(
                            str(action_id)
                            for action_id in self.model_call_deferred_static_action_ids
                            if str(action_id or "").strip()
                        ),
                        "deferred_frontier_action_count": len(
                            self.model_call_deferred_frontier_action_keys
                        ),
                        "max_iterations": self.max_iterations,
                        "verdict": "model_call_deferred_action_released",
                    }
                )
                return True
            if apply_materialization_pending_recovery():
                return True
            suppression_release = (
                self._release_stale_no_applicable_recovery_suppressors(action_ids)
                if serviceable_action_ids
                else {
                    "released_work_keys": 0,
                    "released_action_keys": 0,
                    "released_action_ids": [],
                }
            )
            released_suppressors = int(
                suppression_release.get("released_work_keys", 0) or 0
            ) + int(suppression_release.get("released_action_keys", 0) or 0)
            if released_suppressors > 0:
                self.no_applicable_recovery_count += 1
                self.fallback_actions_attempted = False
                self.stagnation_counter = 0
                self.soft_progress_streak = 0
                self.max_iterations = max(
                    int(self.max_iterations or 0),
                    int(self.iteration or 0) + 2,
                )
                self.expand_max_iterations_to_action_budgets(headroom=2)
                self.last_failure_reason = ""
                self._increment_dossier_metric(
                    "mini_session_no_applicable_suppression_recoveries",
                    1,
                )
                self._increment_dossier_metric(
                    "mini_session_no_applicable_stale_suppressors_released",
                    released_suppressors,
                )
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "stagnation_counter": self.stagnation_counter,
                        "recovery_count": self.no_applicable_recovery_count,
                        "max_recoveries": self.max_no_applicable_recoveries,
                        "serviceable_action_ids": sorted(serviceable_action_ids),
                        "deferred_only_serviceable_action_ids": sorted(
                            deferred_only_serviceable_action_ids
                        ),
                        "released_deferred_action_ids": sorted(
                            released_deferred_action_ids
                        ),
                        "released_suppression_action_ids": list(
                            suppression_release.get("released_action_ids") or []
                        ),
                        "released_skipped_frontier_work_keys": int(
                            suppression_release.get("released_work_keys", 0) or 0
                        ),
                        "released_skipped_frontier_action_keys": int(
                            suppression_release.get("released_action_keys", 0) or 0
                        ),
                        "recovery_action_id_source": recovery_action_id_source,
                        "deferred_static_action_ids": sorted(
                            str(action_id)
                            for action_id in self.model_call_deferred_static_action_ids
                            if str(action_id or "").strip()
                        ),
                        "deferred_frontier_action_count": len(
                            self.model_call_deferred_frontier_action_keys
                        ),
                        "max_iterations": self.max_iterations,
                        "verdict": "stale_frontier_suppression_released",
                    }
                )
                return True
            funded_serviceable_conversation_ids = {
                action_id
                for action_id in serviceable_action_ids
                if action_id.startswith("conversation_turn")
                and action_id not in deferred_only_serviceable_action_ids
                and self.registered_action(action_id) is not None
                and self.budgets.get(action_id) is not None
                and not self.budgets[action_id].exhausted()
                and action_id
                not in self._dispatch_generation_release_suppressed_action_ids
            }
            if (
                funded_serviceable_conversation_ids
                and self.no_applicable_recovery_count
                < max(0, int(self.max_no_applicable_recoveries or 0))
            ):
                # The recovery probe just proved these actions applicable for
                # live frontier work, and their ordinary budgets need no
                # top-up. Reaching this branch therefore means only the
                # selector's static suppression view disagreed. Grant one
                # existing one-shot conversation exemption; do not mint a
                # turn or delete exact provider-lane retirement receipts.
                self._dispatch_generation_release_suppressed_action_ids.update(
                    funded_serviceable_conversation_ids
                )
                self.no_applicable_recovery_count += 1
                self.fallback_actions_attempted = False
                self.stagnation_counter = 0
                self.soft_progress_streak = 0
                self.max_iterations = max(
                    int(self.max_iterations or 0),
                    int(self.iteration or 0) + 2,
                )
                self.last_failure_reason = ""
                self._increment_dossier_metric(
                    "mini_session_no_applicable_serviceable_conversation_reanchors",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "recovery_count": self.no_applicable_recovery_count,
                        "max_recoveries": self.max_no_applicable_recoveries,
                        "serviceable_action_ids": sorted(
                            funded_serviceable_conversation_ids
                        ),
                        "verdict": "serviceable_conversation_reanchored",
                    }
                )
                return True
            if (
                self._repair_first_scheduler_blocked
                and serviceable_action_ids
                and self.no_applicable_recovery_count
                < max(0, int(self.max_no_applicable_recoveries or 0))
            ):
                # A live session may contain a terminal graph target plus a
                # now-unserviceable quota that promised its repair. A
                # single bounded selector re-anchor lets the remaining live
                # graph/recursive lanes run without inventing budget or
                # replaying the stale target.
                self.no_applicable_recovery_count += 1
                self._repair_first_scheduler_blocked = False
                self.max_iterations = max(
                    int(self.max_iterations or 0),
                    int(self.iteration or 0) + 2,
                )
                self.last_failure_reason = ""
                self._increment_dossier_metric(
                    "mini_session_no_applicable_repair_restore_reanchors",
                    1,
                )
                self._record_event(
                    {
                        "phase": "session_no_applicable_recovery",
                        "iteration": self.iteration,
                        "recovery_count": self.no_applicable_recovery_count,
                        "max_recoveries": self.max_no_applicable_recoveries,
                        "serviceable_action_ids": sorted(serviceable_action_ids),
                        "verdict": "repair_restore_failure_selector_reanchored",
                    }
                )
                return True
            if self._renew_provider_lanes_instead_of_terminal(
                "no_recovery_budget_granted"
            ):
                return True
            self.last_failure_reason = "no_recovery_budget_granted"
            self._increment_dossier_metric("mini_session_no_applicable_terminal", 1)
            self._record_event(
                {
                    "phase": "session_no_applicable_recovery",
                    "iteration": self.iteration,
                    "stagnation_counter": self.stagnation_counter,
                    "recovery_count": self.no_applicable_recovery_count,
                    "max_recoveries": self.max_no_applicable_recoveries,
                    "serviceable_action_ids": sorted(serviceable_action_ids),
                    "deferred_only_serviceable_action_ids": sorted(
                        deferred_only_serviceable_action_ids
                    ),
                    "released_deferred_action_ids": sorted(
                        released_deferred_action_ids
                    ),
                    "recovery_action_id_source": recovery_action_id_source,
                    "deferred_static_action_ids": sorted(
                        str(action_id)
                        for action_id in self.model_call_deferred_static_action_ids
                        if str(action_id or "").strip()
                    ),
                    "deferred_frontier_action_count": len(
                        self.model_call_deferred_frontier_action_keys
                    ),
                    "reason": self.last_failure_reason,
                    "verdict": "terminal_no_applicable_action",
                }
            )
            return False

        self.no_applicable_recovery_count += 1
        self.fallback_actions_attempted = False
        self.stagnation_counter = 0
        self.soft_progress_streak = 0
        self.consumed_frontier_work_keys.clear()
        self.skipped_frontier_work_keys.clear()
        self.consumed_frontier_action_keys.clear()
        self.skipped_frontier_action_keys.clear()
        self.materialization_pending_frontier_action_keys.clear()
        self.materialization_pending_frontier_logical_keys.clear()
        self.materialization_pending_frontier_action_logical_keys.clear()
        recovery_units = max(1, int(total_granted or 0))
        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + recovery_units + 2,
        )
        self.expand_max_iterations_to_action_budgets(headroom=max(5, increment + 2))
        self._increment_dossier_metric("mini_session_no_applicable_recoveries", 1)
        self._increment_dossier_metric(
            "mini_session_no_applicable_budget_granted",
            total_granted,
        )
        self._record_event(
            {
                "phase": "session_no_applicable_recovery",
                "iteration": self.iteration,
                "stagnation_counter": self.stagnation_counter,
                "recovery_count": self.no_applicable_recovery_count,
                "max_recoveries": self.max_no_applicable_recoveries,
                "budget_increment": increment,
                "budget_grants": budget_grants,
                "budget_granted_total": total_granted,
                "serviceable_action_ids": sorted(serviceable_action_ids),
                "deferred_only_serviceable_action_ids": sorted(
                    deferred_only_serviceable_action_ids
                ),
                "released_deferred_action_ids": sorted(released_deferred_action_ids),
                "recovery_action_id_source": recovery_action_id_source,
                "max_iterations": self.max_iterations,
                "verdict": "continuation_budget_granted",
            }
        )
        return True

    def _release_action_local_transient_cooldown(self) -> str:
        """Release a funded action-local delay after an empty scheduler pass."""

        for action in list(self.actions or ()):
            action_id = str(getattr(action, "id", "") or "").strip()
            release = getattr(
                action,
                "release_transient_no_applicable_cooldown",
                None,
            )
            if not action_id or not callable(release):
                continue
            budget = self.budgets.get(action_id)
            if budget is None or budget.exhausted():
                continue
            if not self.action_dispatchable(
                action_id,
                context="action_local_transient_cooldown_recovery",
            ):
                continue
            try:
                released = bool(release(self))
            except Exception:
                continue
            if not released:
                continue
            if self._safe_is_applicable(
                action,
                context="action_local_transient_cooldown_recovery",
            ):
                return action_id
        return ""

    def _increment_dossier_metric(self, key: str, amount: int = 1) -> None:
        if int(getattr(self, "_suppress_dossier_metric_recording", 0) or 0) > 0:
            return
        increment = getattr(self.dossier, "increment_tool_metric", None)
        if not callable(increment):
            return
        try:
            increment(str(key or ""), int(amount or 0))
        except Exception:
            return

    def _increment_root_finalization_rejection_metrics(
        self,
        *,
        verdict: str = "",
        route_contract_status: Optional[Dict[str, Any]] = None,
        verification_status: Optional[Dict[str, Any]] = None,
    ) -> None:
        """Mirror canonical finalizer rejection metrics for session preflights."""

        self._increment_dossier_metric("mini_root_finalization_blocked", 1)
        certificate_verdict = str(
            (verification_status or {}).get("verdict") or ""
        ).strip()
        if certificate_verdict and not bool((verification_status or {}).get("ready")):
            if certificate_verdict == "root_finalization_target_mismatch":
                self._increment_dossier_metric(
                    "mini_root_finalization_target_mismatch",
                    1,
                )
                return
            self._increment_dossier_metric(
                (
                    "mini_root_finalization_missing_certificate"
                    if certificate_verdict
                    == "root_finalization_missing_verification_certificate"
                    else "mini_root_finalization_certificate_rejected"
                ),
                1,
            )
            return
        contract_verdict = str(
            (route_contract_status or {}).get("verdict") or verdict or ""
        ).strip()
        if contract_verdict in {
            "route_candidate_helper_support_mismatch",
            "route_candidate_missing_declared_helper_support",
        }:
            self._increment_dossier_metric(
                "mini_root_finalization_support_mismatch",
                1,
            )
        elif contract_verdict:
            self._increment_dossier_metric(
                "mini_root_finalization_route_contract_not_ready",
                1,
            )

    @staticmethod
    def _work_frontier_accepts_offset(getter: Any) -> bool:
        if not callable(getter):
            return False
        try:
            parameters = inspect.signature(getter).parameters
        except (TypeError, ValueError):
            return False
        return "offset" in parameters

    def _refresh_route_tactic_failure_suppression(self, graph: Any) -> None:
        """Reopen route-root tactic work when the tactic context has changed."""

        if graph is None or self.dossier is None:
            return
        action = self.registered_action("graph_route_assembly")
        if action is None:
            return
        nodes = getattr(graph, "nodes", {}) or {}
        if not isinstance(nodes, dict):
            return
        try:
            from ensemble_prover.proof_graph import graph_text_hash
            from ensemble_prover.proof_state_executor import _root_tactic_context_key
        except Exception:
            return
        problem = getattr(self, "problem", None)
        goal_statement = str(
            getattr(problem, "statement_type", "")
            or getattr(self.dossier, "root_statement", "")
            or ""
        )
        preamble = (
            self.acceptance_preamble()
            if hasattr(self, "acceptance_preamble")
            else str(getattr(getattr(self, "conv", None), "preamble", "") or "")
        )
        route_ready = getattr(action, "_route_ready", None)
        route_helper_names = getattr(action, "_route_helper_names", None)
        route_dependency_signature = getattr(
            action, "_route_dependency_signature", None
        )
        if not (
            callable(route_ready)
            and callable(route_helper_names)
            and callable(route_dependency_signature)
        ):
            return
        for route in list(nodes.values()):
            if getattr(route, "kind", "") != "strategy_route":
                continue
            metadata = getattr(route, "metadata", None)
            if not isinstance(metadata, dict):
                continue
            failed_hash = str(
                metadata.get("route_root_tactic_failed_hash") or ""
            ).strip()
            if not failed_hash:
                continue
            route_id = str(getattr(route, "node_id", "") or "").strip()
            if not route_id:
                continue
            signature_hash_getter = getattr(
                graph, "route_dependency_signature_hash", None
            )
            if callable(signature_hash_getter):
                try:
                    current_signature_hash = str(
                        signature_hash_getter(route_id) or ""
                    ).strip()
                except Exception:
                    current_signature_hash = ""
            else:
                current_signature_hash = ""
            stored_signature_hash = str(
                metadata.get("route_root_tactic_failed_signature_hash") or ""
            ).strip()
            if (
                stored_signature_hash
                and current_signature_hash != stored_signature_hash
            ):
                metadata.pop("route_root_tactic_failed_hash", None)
                metadata.pop("route_root_tactic_failed_signature_hash", None)
                metadata.pop("route_root_tactic_deferred_hash", None)
                metadata.pop("route_root_tactic_continued_hash", None)
                metadata.pop("route_root_tactic_continuation_hash", None)
                metadata.pop("route_root_tactic_suppressed_proofs", None)
                metadata.pop("route_root_tactic_suppressed_proof_records", None)
                metadata.pop("route_root_tactic_suppressed_count", None)
                metadata.pop("route_root_tactic_last_attempt_count", None)
                metadata.pop("route_root_tactic_last_candidate_count", None)
                metadata.pop("route_root_tactic_timeout_continuation_hash", None)
                continue
            try:
                ready, deps = route_ready(graph, route_id)
            except Exception:
                continue
            if not ready:
                continue
            try:
                helper_names = route_helper_names(graph, deps, self.dossier)
            except Exception:
                helper_names = []
            if not helper_names:
                continue
            route_helper_blocks = getattr(action, "_route_helper_blocks", None)
            if not callable(route_helper_blocks):
                continue
            try:
                helper_blocks = route_helper_blocks(self.dossier, helper_names)
            except Exception:
                helper_blocks = []
            root_tactic_context_key = _root_tactic_context_key(
                goal_statement=goal_statement,
                preamble=preamble,
                helpers=helper_blocks,
                timeout_s=float(getattr(action, "root_tactic_timeout_s", 0.0) or 0.0),
                max_candidates=int(
                    getattr(action, "root_tactic_max_candidates", 0) or 0
                ),
            )
            try:
                dependency_signature = route_dependency_signature(
                    graph,
                    deps,
                    route_id=route_id,
                )
            except Exception:
                dependency_signature = []
            current_failed_hash = graph_text_hash(
                json.dumps(
                    {
                        "route_id": route_id,
                        "dependency_node_ids": list(deps),
                        "dependency_signature": dependency_signature,
                        "root_tactic_context_key": root_tactic_context_key,
                    },
                    sort_keys=True,
                )
            )
            if current_failed_hash != failed_hash:
                metadata.pop("route_root_tactic_failed_hash", None)
                metadata.pop("route_root_tactic_failed_signature_hash", None)
                metadata.pop("route_root_tactic_deferred_hash", None)
                metadata.pop("route_root_tactic_continued_hash", None)
                metadata.pop("route_root_tactic_continuation_hash", None)
                metadata.pop("route_root_tactic_suppressed_proofs", None)
                metadata.pop("route_root_tactic_suppressed_proof_records", None)
                metadata.pop("route_root_tactic_suppressed_count", None)
                metadata.pop("route_root_tactic_last_attempt_count", None)
                metadata.pop("route_root_tactic_last_candidate_count", None)
                metadata.pop("route_root_tactic_timeout_continuation_hash", None)

    def _recover_live_failed_root_frontier(self, graph: Any) -> bool:
        """Reopen a failed root when the containing session is still live.

        Older live state may contain the pre-fix feedback loop where a
        ``frontier_work_no_progress`` attempt failed ``proof_state:root`` and
        graph hydration then failed the local root.  A session that has not
        finalized or declared a terminal failure still intends to search, so
        that state is scheduler exhaustion rather than a proof of mathematical
        impossibility.  Reopen only the root and release only root-scoped
        scheduler suppressors; durable failed routes and child evidence remain.
        """

        proof_state = self.proof_state
        if proof_state is None or graph is None:
            return False
        if str(self.terminal_failure_reason or "").strip():
            return False
        if self.root_finalized and self._durable_final_proof():
            return False
        root_id = str(getattr(proof_state, "root_node_id", "") or "").strip()
        nodes = getattr(proof_state, "nodes", {}) or {}
        root = nodes.get(root_id)
        graph_nodes = getattr(graph, "nodes", {}) or {}
        projection = graph_nodes.get(f"proof_state:{root_id}")
        local_root_failed = (
            root is not None and str(getattr(root, "status", "") or "") == "failed"
        )
        projection_root_failed = (
            projection is not None
            and str(getattr(projection, "status", "") or "") == "failed"
        )
        # The graph projection can observe a scheduler failure before that
        # status reaches local proof state. Treat either mirror as evidence of
        # the same recoverable state and repair it atomically.
        if root is None or not (local_root_failed or projection_root_failed):
            return False
        graph_root = graph_nodes.get(str(getattr(graph, "root_node_id", "") or ""))
        if (
            graph_root is not None
            and str(getattr(graph_root, "status", "") or "") == "proved"
            and self._durable_final_proof()
        ):
            return False
        reopener = getattr(proof_state, "reopen_node", None)
        if not callable(reopener) or not reopener(
            root_id,
            reason="live session regenerated failed root frontier",
            phase="mini_session_frontier_recovery",
            turn_index=int(self.iteration or 0),
        ):
            return False

        # A regenerated work item has the same stable frontier key as its
        # predecessor. Remove only keys whose local node id is
        # the root so the scheduler can actually dispatch the rebuilt item.
        released: Dict[str, int] = {}
        for attr in (
            "consumed_frontier_work_keys",
            "skipped_frontier_work_keys",
            "consumed_frontier_action_keys",
            "skipped_frontier_action_keys",
            "materialization_pending_frontier_action_keys",
        ):
            values = set(getattr(self, attr, set()) or set())
            kept = {
                key
                for key in values
                if not isinstance(key, tuple)
                or not key
                or str(key[0] or "").strip() != root_id
            }
            released[attr] = len(values) - len(kept)
            setattr(self, attr, kept)
        selected_node_id = str(
            (self.selected_work_item_record or {}).get("node_id") or ""
        ).strip()
        if selected_node_id == root_id:
            self._clear_selected_work_item()

        # Budget skips reduce priority and describe a consumed scheduling
        # epoch.  Failed-route memory lives in graph attempts, so resetting
        # this root-local counter does not discard mathematical evidence.
        previous_budget_skips = int(getattr(root, "budget_skips", 0) or 0)
        root.budget_skips = 0
        priority = getattr(proof_state, "_priority", None)
        if callable(priority):
            try:
                root.priority = priority(root)
            except Exception:
                pass
        try:
            proof_state.sync_to_graph(
                self.dossier,
                phase="mini_session_frontier_recovery",
                turn_index=int(self.iteration or 0),
            )
        except Exception:
            # Local state is authoritative and already reopened.  Repair the
            # two status mirrors directly so the immediately following
            # work_frontier query cannot suppress the regenerated root.  The
            # next ordinary sync reconstructs the full projection metadata.
            if projection is not None:
                projection.status = "open"
            if graph_root is not None and not self._durable_final_proof():
                graph_root.status = "open"
        self._increment_dossier_metric(
            "mini_session_failed_root_frontiers_regenerated",
            1,
        )
        self._record_event(
            {
                "phase": "graph_frontier_recovery",
                "iteration": self.iteration,
                "node_id": root_id,
                "previous_budget_skips": previous_budget_skips,
                "released_root_scheduler_suppressors": sum(released.values()),
                "released_by_kind": released,
                "verdict": "failed_root_frontier_regenerated",
            }
        )
        return True

    def _work_frontier_items(
        self,
        *,
        offset: int = 0,
        mutate: bool = True,
        max_items_override: int = 0,
    ) -> List[Any]:
        if self.proof_state is None:
            return []
        getter = getattr(self.proof_state, "work_frontier", None)
        if not callable(getter):
            return []
        offset = max(0, int(offset or 0))
        offset_supported = self._work_frontier_accepts_offset(getter)
        if offset > 0 and not offset_supported:
            return []
        graph = (
            getattr(self.dossier, "proof_graph", None)
            if self.dossier is not None
            else None
        )
        root_frontier_recovered = False
        if mutate:
            self._refresh_route_tactic_failure_suppression(graph)
            root_frontier_recovered = self._recover_live_failed_root_frontier(graph)
        refresher = getattr(self.proof_state, "refresh_graph_readiness", None)
        if (
            mutate
            and not root_frontier_recovered
            and callable(refresher)
            and graph is not None
        ):
            try:
                refresh_records = refresher(
                    graph,
                    phase="mini_session_select",
                    turn_index=int(self.iteration or 0),
                )
                if refresh_records:
                    self._record_event(
                        {
                            "phase": "graph_frontier_refresh",
                            "iteration": self.iteration,
                            "refresh_records": list(refresh_records),
                            "verdict": "graph_refresh_applied",
                        }
                    )
                    try:
                        self.proof_state.sync_to_graph(
                            self.dossier,
                            phase="mini_session_select",
                            turn_index=int(self.iteration or 0),
                        )
                    except Exception:
                        pass
            except Exception:
                self._record_event(
                    {
                        "phase": "graph_frontier_refresh",
                        "iteration": self.iteration,
                        "verdict": "graph_refresh_failed",
                    }
                )
        recursive_helper_action = self.registered_action("recursive_helper_prover")
        recursive_helper_registered = (
            self.action_available("recursive_helper_prover")
            and recursive_helper_action is not None
        )
        promoter = getattr(self.proof_state, "promote_trusted_graph_obligations", None)
        if (
            mutate
            and offset == 0
            and recursive_helper_registered
            and callable(promoter)
            and graph is not None
        ):
            try:
                promotion_record = promoter(
                    graph,
                    phase="mini_session_select",
                    turn_index=int(self.iteration or 0),
                    max_promotions=16,
                )
                promoted_count = int(promotion_record.get("promoted_count", 0) or 0)
                reused_count = int(promotion_record.get("reused_count", 0) or 0)
                reconciled_count = int(
                    promotion_record.get("reconciled_count", 0) or 0
                )
                skip_changed_count = int(
                    promotion_record.get("skip_changed_count", 0) or 0
                )
                skip_count = sum(
                    int(value or 0)
                    for key, value in promotion_record.items()
                    if str(key).startswith("skipped_") and str(key).endswith("_count")
                )
                if promoted_count or reused_count:
                    self._record_event(
                        {
                            "phase": "graph_obligation_promotion",
                            "iteration": self.iteration,
                            "verdict": "graph_obligation_promotion_applied",
                            "promoted_count": promoted_count,
                            "reused_count": reused_count,
                            "reconciled_count": reconciled_count,
                            "skip_count": skip_count,
                            "skip_changed_count": skip_changed_count,
                            "promotion_record": dict(promotion_record),
                        }
                    )
                elif reconciled_count or skip_changed_count:
                    self._record_event(
                        {
                            "phase": "graph_obligation_promotion",
                            "iteration": self.iteration,
                            "verdict": (
                                "graph_obligation_promotion_skips_reconciled"
                            ),
                            "promoted_count": 0,
                            "reused_count": 0,
                            "reconciled_count": reconciled_count,
                            "skip_count": skip_count,
                            "skip_changed_count": skip_changed_count,
                            "promotion_record": dict(promotion_record),
                        }
                    )
                if promoted_count:
                    self._increment_dossier_metric(
                        "mini_session_graph_obligations_promoted_to_child_goals",
                        promoted_count,
                    )
                if reused_count:
                    self._increment_dossier_metric(
                        "mini_session_graph_obligations_reused_proof_state_child_goals",
                        reused_count,
                    )
                if (
                    promoted_count
                    or reused_count
                    or reconciled_count
                    or skip_changed_count
                ):
                    try:
                        self.proof_state.sync_to_graph(
                            self.dossier,
                            phase="graph_obligation_promotion",
                            turn_index=int(self.iteration or 0),
                        )
                    except Exception:
                        pass
            except Exception:
                self._record_event(
                    {
                        "phase": "graph_obligation_promotion",
                        "iteration": self.iteration,
                        "verdict": "graph_obligation_promotion_failed",
                    }
                )
        # Proof-state promotion and semantic graph coalescing can add derived
        # route consumers after the planner's lifecycle record was authored.
        # Repair those exact occurrences before work_frontier seals cognition
        # coordinates; doing this after packet generation only manufactures a
        # stale generation and strands the still-live mathematical work.
        consumer_reconciler = getattr(
            self.dossier,
            "reconcile_proof_idea_graph_consumers",
            None,
        )
        if mutate and callable(consumer_reconciler):
            try:
                repaired_consumers = int(consumer_reconciler() or 0)
                if repaired_consumers:
                    self._record_event(
                        {
                            "phase": "proof_idea_graph_consumer_reconciliation",
                            "iteration": self.iteration,
                            "repaired_consumers": repaired_consumers,
                            "verdict": "derived_consumers_registered",
                        }
                    )
            except Exception:
                self._record_event(
                    {
                        "phase": "proof_idea_graph_consumer_reconciliation",
                        "iteration": self.iteration,
                        "verdict": "consumer_reconciliation_failed_closed",
                    }
                )
        if mutate:
            self._residual_dispatch_cache_ready = False
            self._residual_dispatch_required_ids.clear()
            self._residual_dispatch_authorized_ids.clear()
            self._residual_dispatch_persisted_authorized_ids.clear()
            try:
                from ensemble_prover.proof_state_executor import (
                    ensure_current_helper_acceptance_retries,
                    ensure_current_typed_residual_attestation_retries,
                    proof_state_current_residual_route_context_hashes,
                )

                scheduled_reattestations = (
                    ensure_current_typed_residual_attestation_retries(
                        conv=self.conv,
                        dossier=self.dossier,
                        lean=self.lean,
                        proof_state=self.proof_state,
                    )
                )
                rearmed_helper_acceptances = ensure_current_helper_acceptance_retries(
                    conv=self.conv,
                    dossier=self.dossier,
                    proof_state=self.proof_state,
                )
                if rearmed_helper_acceptances:
                    self._record_event(
                        {
                            "phase": "helper_acceptance_currentness",
                            "iteration": self.iteration,
                            "node_ids": list(rearmed_helper_acceptances),
                            "verdict": "helper_acceptance_rearmed",
                        }
                    )
                if scheduled_reattestations:
                    self._record_event(
                        {
                            "phase": "typed_residual_currentness",
                            "iteration": self.iteration,
                            "parent_node_ids": list(scheduled_reattestations),
                            "verdict": "residual_reattestation_scheduled",
                        }
                    )
                route_contexts = proof_state_current_residual_route_context_hashes(
                    conv=self.conv,
                    dossier=self.dossier,
                    lean=self.lean,
                    proof_state=self.proof_state,
                )
                (
                    required_ids,
                    authorized_ids,
                    _current_route_validity,
                ) = self.proof_state._residual_goal_attestation_validation(  # noqa: SLF001
                    route_elaboration_context_hashes=route_contexts,
                )
                (
                    _persisted_required_ids,
                    persisted_authorized_ids,
                    _persisted_route_validity,
                ) = self.proof_state._residual_goal_attestation_validation()  # noqa: SLF001
                self._residual_dispatch_required_ids.update(required_ids)
                self._residual_dispatch_authorized_ids.update(authorized_ids)
                self._residual_dispatch_persisted_authorized_ids.update(
                    persisted_authorized_ids
                )
                self._residual_dispatch_cache_ready = True
            except Exception:
                # Dispatch still fails closed through the current-context
                # receipt check below; inability to schedule the deterministic
                # replay must never make a stale child provider-executable.
                self._record_event(
                    {
                        "phase": "typed_residual_currentness",
                        "iteration": self.iteration,
                        "verdict": "residual_reattestation_schedule_failed",
                    }
                )
        include_child_llm = False
        if recursive_helper_registered:
            recursive_probe = (
                getattr(recursive_helper_action, "frontier_is_applicable_probe", None)
                if not mutate
                else None
            )
            include_child_llm = (
                self._safe_is_applicable(
                    recursive_helper_action,
                    context=(
                        "frontier_child_llm_gate"
                        if mutate
                        else "frontier_child_llm_probe"
                    ),
                    predicate=(recursive_probe if callable(recursive_probe) else None),
                )
                if mutate or callable(recursive_probe)
                else False
            )
        recursive_attempt_cap = int(
            getattr(recursive_helper_action, "max_attempts_per_node", 0) or 0
        )
        recursive_giveup_cap = int(
            getattr(recursive_helper_action, "max_giveups_per_cluster_per_node", 0) or 0
        )
        frontier_seen = len(
            getattr(self, "consumed_frontier_work_keys", set()) or set()
        ) + len(getattr(self, "skipped_frontier_work_keys", set()) or set())
        frontier_seen += len(
            getattr(self, "consumed_frontier_action_keys", set()) or set()
        ) + len(getattr(self, "skipped_frontier_action_keys", set()) or set())
        retrieval_needed_node_ids: List[str] = []
        retrieval_context_stamps: Dict[str, str] = {}
        retrieval_available = False
        decl_application_context_hashes: Dict[str, str] = {}
        retrieval_action = self.registered_action("proof_state_retrieval")
        if retrieval_action is not None:
            helper_blocks: List[str] = []
            helper_getter = getattr(
                self.dossier,
                (
                    "verified_helper_blocks"
                    if mutate
                    else "verified_helper_blocks_snapshot"
                ),
                None,
            )
            if callable(helper_getter):
                try:
                    helper_blocks = list(helper_getter() or ())
                except Exception:
                    helper_blocks = []
            retrieval_available = bool(self.searcher is not None or helper_blocks)
            try:
                from ensemble_prover.proof_state_scheduler import (
                    _proof_state_node_needs_retrieval,
                    _proof_state_node_retrieval_signature_for_context,
                )

                from ensemble_prover.proof_state import (
                    PROOF_STATE_DECL_EXECUTION_POLICY_VERSION,
                )

                retrieval_max_results = int(
                    getattr(retrieval_action, "max_results", 0) or 0
                )
                for node in getattr(self.proof_state, "nodes", {}).values():
                    if (
                        getattr(node, "kind", "") != "child_goal"
                        or getattr(node, "status", "") != "open"
                        or bool(getattr(node, "falsified", False))
                        or not _proof_state_node_needs_retrieval(
                            self.searcher,
                            node,
                            max_results=retrieval_max_results,
                            local_helper_blocks=helper_blocks,
                        )
                    ):
                        continue
                    node_id = str(node.node_id)
                    _query, desired_signature = (
                        _proof_state_node_retrieval_signature_for_context(
                            self.searcher,
                            node,
                            max_results=retrieval_max_results,
                            local_helper_blocks=helper_blocks,
                        )
                    )
                    stamp_payload = (
                        f"{desired_signature}\0"
                        f"{PROOF_STATE_DECL_EXECUTION_POLICY_VERSION}"
                    )
                    retrieval_needed_node_ids.append(node_id)
                    retrieval_context_stamps[node_id] = hashlib.sha256(
                        stamp_payload.encode("utf-8", "replace")
                    ).hexdigest()
            except Exception:
                # The ordinary never-attempted path remains available inside
                # ProofSearchState. Context refresh fails closed here rather
                # than manufacturing a retrieval generation from partial data.
                retrieval_needed_node_ids = []
                retrieval_context_stamps = {}
        try:
            from ensemble_prover.proof_state_executor import (
                proof_state_decl_application_context_hash,
            )

            decl_context_hash = proof_state_decl_application_context_hash(
                self.conv,
                self.dossier,
            )
            if decl_context_hash:
                decl_application_context_hashes = {
                    str(node.node_id): decl_context_hash
                    for node in getattr(self.proof_state, "nodes", {}).values()
                    if getattr(node, "kind", "") == "child_goal"
                    and getattr(node, "status", "") == "open"
                }
        except Exception:
            # Exact-context invalidation is a retry grant. If its identity
            # cannot be computed, preserve existing anti-replay memory.
            decl_application_context_hashes = {}
        frontier_window = max(
            16,
            min(
                4096,
                max(
                    4 + 2 * frontier_seen,
                    int(max_items_override or 0),
                ),
            ),
        )
        base_kwargs = {
            "max_items": frontier_window,
            "graph": graph,
            "mutate": mutate,
            "include_child_llm_prove": include_child_llm,
            "max_recursive_attempts_per_node": recursive_attempt_cap,
            "max_recursive_giveups_per_cluster_per_node": recursive_giveup_cap,
            "retrieval_needed_node_ids": retrieval_needed_node_ids,
            "retrieval_context_stamps": retrieval_context_stamps,
            "retrieval_available": retrieval_available,
            "decl_application_context_hashes": (decl_application_context_hashes),
        }
        if offset_supported:
            base_kwargs["offset"] = offset
        try:
            frontier_parameters = inspect.signature(getter).parameters
        except (TypeError, ValueError):
            frontier_parameters = {}
        accepts_arbitrary_keywords = any(
            parameter.kind == inspect.Parameter.VAR_KEYWORD
            for parameter in frontier_parameters.values()
        )
        if (
            not mutate
            and not accepts_arbitrary_keywords
            and "mutate" not in frontier_parameters
        ):
            # Unknown frontier implementations have no read-authority
            # contract. Quotation must fail closed instead of invoking one.
            return []
        call_kwargs = (
            base_kwargs
            if accepts_arbitrary_keywords
            else {
                key: value
                for key, value in base_kwargs.items()
                if key in frontier_parameters
            }
        )
        try:
            items = getter(**call_kwargs)
        except TypeError:
            if not mutate:
                # A frontier provider that does not explicitly implement the
                # observational protocol is not safe to call from quotation.
                return []
            fallback_calls: List[Dict[str, Any]] = []
            if offset_supported:
                fallback_calls.extend(
                    [
                        {
                            "max_items": frontier_window,
                            "offset": offset,
                            "graph": graph,
                        },
                        {"max_items": frontier_window, "offset": offset},
                    ]
                )
            if offset == 0:
                fallback_calls.extend(
                    [
                        {"max_items": frontier_window, "graph": graph},
                        {"max_items": frontier_window},
                        {},
                    ]
                )
            for kwargs in fallback_calls:
                try:
                    items = getter(**kwargs)
                    break
                except TypeError:
                    continue
                except Exception:
                    if mutate:
                        self._record_event(
                            {
                                "phase": "graph_work_frontier",
                                "iteration": self.iteration,
                                "verdict": "graph_frontier_failed",
                            }
                        )
                    return []
            else:
                if mutate:
                    self._record_event(
                        {
                            "phase": "graph_work_frontier",
                            "iteration": self.iteration,
                            "verdict": "graph_frontier_failed",
                        }
                    )
                return []
        except Exception:
            if mutate:
                self._record_event(
                    {
                        "phase": "graph_work_frontier",
                        "iteration": self.iteration,
                        "verdict": "graph_frontier_failed",
                    }
                )
            return []
        return list(items or [])

    def _rank_frontier_items_for_dispatch(self, items: List[Any]) -> List[Any]:
        """Rank by expected root unlock per measured second.

        Ready assembly is always first.  Every eighth scheduler iteration keeps
        the existing order among non-assembly work as a bounded exploration
        reserve; all other iterations compare lanes globally instead of letting
        static work-type order dominate root value.
        """

        ordered = list(items or [])
        if not ordered:
            return ordered
        exploration_interval = 8
        exploration = (
            int(self.iteration or 0) % exploration_interval == exploration_interval - 1
        )

        dossier = getattr(self, "dossier", None)
        observations = dict(getattr(dossier, "action_value_observations", {}) or {})
        graph = getattr(dossier, "proof_graph", None)
        graph_nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        graph_edges = (
            list(getattr(graph, "edges", ()) or ()) if graph is not None else []
        )
        action_dispatch_order: Dict[int, Tuple[str, int]] = {}
        target_counts: Dict[str, int] = {}
        for item in ordered:
            target = str(self._work_item_field(item, "target_hash", "") or "").strip()
            if target:
                target_counts[target] = target_counts.get(target, 0) + 1

        def annotate(item: Any, payload: Dict[str, Any]) -> None:
            graph_record = self._work_item_field(item, "graph_record", None)
            if isinstance(graph_record, dict):
                graph_record["root_value_scheduler"] = dict(payload)
            elif isinstance(item, dict):
                item["root_value_scheduler"] = dict(payload)

        def rank(item: Any, stable_index: int) -> Tuple[float, int]:
            work_type = str(self._work_item_field(item, "work_type", "") or "").strip()
            if work_type in {"assembly", "assemble_route"}:
                annotate(
                    item,
                    {
                        "schema_version": 1,
                        "mode": "exploration" if exploration else "root_value",
                        "action_id": "",
                        "root_consumer_id": str(
                            self._work_item_field(item, "assembly_id", "") or ""
                        ),
                        "open_and_siblings": 0,
                        "expected_root_unlock": 1.0,
                        "expected_cost_s": 0.0,
                        "utility": 1_000_000.0,
                    },
                )
                return (-1_000_000.0, stable_index)
            # Price the action that dispatch would actually select.  Looking
            # only at the first registered candidate underprices work when a
            # cheap graph shortcut is inapplicable and the mapper falls
            # through to an expensive model call; it also misses theory
            # actions inserted for formalization-required items.
            action = self._quote_work_item_action(item)
            action_id = str(getattr(action, "id", "") or "")
            record = self._work_item_field(item, "graph_record", None)
            if record is None and isinstance(item, dict):
                record = item
            record = dict(record or {}) if isinstance(record, dict) else {}
            route_id = str(record.get("route_id") or "").strip()
            route_open_siblings = 0
            if route_id and isinstance(graph_nodes, dict):
                route_open_siblings = sum(
                    1
                    for edge in graph_edges
                    if edge.source == route_id
                    and str(edge.kind or "").startswith("route_")
                    and str(getattr(graph_nodes.get(edge.target), "status", "") or "")
                    != "proved"
                )
            try:
                priority = float(self._work_item_field(item, "priority", 0.0) or 0.0)
            except (TypeError, ValueError):
                priority = 0.0
            root_unlock = max(0.05, min(1.5, priority / 100.0))
            if route_id:
                root_unlock += 0.35
                root_unlock += 0.3 / max(1, route_open_siblings)
            root_unlock += {
                "materialize_replay_source": 0.7,
                "route_replan": 0.45,
                "prove_claim_variant": 0.4,
                "formalize_claim": 0.35,
                "formalize_missing_obligation": 0.35,
                "mine_missing_obligation": 0.25,
                "retrieval": 0.18,
                "decl_probe": 0.22,
                "tactic_swarm": 0.2,
                "formal_state_expand": 0.16,
                "child_llm_prove": 0.12,
                "root_repair": 0.1,
            }.get(work_type, 0.1)
            observed = dict(observations.get(action_id) or {})
            attempts = max(0.0, float(observed.get("attempts", 0.0) or 0.0))
            successes = max(
                0.0,
                float(observed.get("root_progress", 0.0) or 0.0),
            )
            measured_seconds = max(
                0.0,
                float(observed.get("seconds", 0.0) or 0.0),
            )
            success_rate = (successes + 1.0) / (attempts + 2.0)
            fallback_cost = max(
                0.05,
                float(getattr(action, "cost_estimate_s", 10.0) or 10.0),
            )
            expected_cost = (
                measured_seconds / attempts
                if attempts >= 2.0 and measured_seconds > 0.0
                else fallback_cost
            )
            if expected_cost >= 20.0 and not route_id:
                root_unlock *= 0.3
            target = str(self._work_item_field(item, "target_hash", "") or "").strip()
            duplicate_penalty = max(1, target_counts.get(target, 1))
            utility = (
                root_unlock
                * (0.5 + success_rate)
                / max(0.25, expected_cost**0.5)
                / duplicate_penalty
            )
            if action is None:
                utility = 0.0
            rank_hook = getattr(action, "frontier_dispatch_rank_probe", None)
            action_dispatch_rank = 0
            if callable(rank_hook):
                try:
                    action_dispatch_rank = int(rank_hook(self, item) or 0)
                except Exception:
                    action_dispatch_rank = 0
                action_dispatch_order[id(item)] = (
                    action_id,
                    action_dispatch_rank,
                )
            annotate(
                item,
                {
                    "schema_version": 1,
                    "mode": "exploration" if exploration else "root_value",
                    "action_id": action_id,
                    "root_consumer_id": route_id,
                    "open_and_siblings": route_open_siblings,
                    "expected_root_unlock": round(root_unlock, 6),
                    "expected_cost_s": round(expected_cost, 6),
                    "empirical_success_rate": round(success_rate, 6),
                    "semantic_duplicate_count": duplicate_penalty,
                    "action_dispatch_rank": action_dispatch_rank,
                    "utility": round(utility, 9),
                },
            )
            return (-utility, stable_index)

        ranked = [
            item
            for _score, _stable, item in sorted(
                (
                    (*rank(item, stable_index), item)
                    for stable_index, item in enumerate(ordered)
                ),
                key=lambda entry: (entry[0], entry[1]),
            )
        ]
        # Root value ranks lanes globally. Within the slots already awarded to
        # one action, preserve that action's own bounded-fairness contract
        # lexicographically; a tiny cross-lane utility nudge can otherwise
        # starve lower-priority live contexts forever.
        action_positions: Dict[str, List[int]] = {}
        for position, item in enumerate(ranked):
            action_id, _dispatch_rank = action_dispatch_order.get(
                id(item),
                ("", 0),
            )
            if action_id:
                action_positions.setdefault(action_id, []).append(position)
        for action_id, positions in action_positions.items():
            if len(positions) < 2:
                continue
            action_items = [ranked[position] for position in positions]
            ranked_action_items = sorted(
                enumerate(action_items),
                key=lambda indexed_item: (
                    action_dispatch_order.get(
                        id(indexed_item[1]),
                        (action_id, 0),
                    )[1],
                    indexed_item[0],
                ),
            )
            for position, (_stable_index, item) in zip(
                positions,
                ranked_action_items,
            ):
                ranked[position] = item
        if not exploration:

            def durable_retry_count(value: Any) -> int:
                if isinstance(value, bool):
                    return 0
                try:
                    return max(0, int(value or 0))
                except (TypeError, ValueError):
                    return 0

            def deferred_verifier_retry(item: Any) -> bool:
                work_type = str(
                    self._work_item_field(item, "work_type", "") or ""
                ).strip()
                if work_type not in {
                    "residual_goal_extraction",
                    "decl_probe",
                    "tactic_swarm",
                    "helper_acceptance",
                }:
                    return False
                proof_state = getattr(self, "proof_state", None)
                nodes = (
                    getattr(proof_state, "nodes", {}) if proof_state is not None else {}
                )
                node_id = str(self._work_item_field(item, "node_id", "") or "").strip()
                node = nodes.get(node_id) if isinstance(nodes, dict) else None
                if work_type == "residual_goal_extraction":
                    pending = dict(
                        getattr(
                            node,
                            "pending_residual_goal_extraction",
                            {},
                        )
                        or {}
                    )
                    return durable_retry_count(pending.get("retry_count")) > 0
                pending = dict(getattr(node, "pending_helper_acceptance", {}) or {})
                return bool(
                    str(pending.get("helper_block") or "").strip()
                    and str(pending.get("target_hash") or "")
                    == text_hash(str(getattr(node, "target", "") or ""))
                    and durable_retry_count(pending.get("attempt_count")) > 0
                )

            deferred = [item for item in ranked if deferred_verifier_retry(item)]
            if deferred and not any(
                str(self._work_item_field(item, "work_type", "") or "").strip()
                in {"assembly", "assemble_route"}
                for item in ranked
            ):
                # A paid verifier-only replay is immediate once. After that
                # exact request defers, guarantee one different executable
                # lane gets the next scheduling opportunity. Merely lowering
                # ProofSearchState's static work order is insufficient: the
                # cross-action utility rank can otherwise retry a 300-second
                # verifier operation for seven iterations before exploration.
                alternate = next(
                    (
                        item
                        for item in ranked
                        if item not in deferred
                        and str(
                            self._work_item_field(item, "work_type", "") or ""
                        ).strip()
                        not in {"residual_goal_extraction", "root_repair"}
                        and self._quote_work_item_action(item) is not None
                    ),
                    None,
                )
                if alternate is not None:
                    ranked = [
                        alternate,
                        *deferred,
                        *[
                            item
                            for item in ranked
                            if item is not alternate and item not in deferred
                        ],
                    ]
            return ranked
        # Exploration must never starve a Lean-ready root assembly. Preserve
        # the frontier's prior order only within the two safety classes.
        return [
            *[
                item
                for item in ordered
                if str(self._work_item_field(item, "work_type", "") or "").strip()
                in {"assembly", "assemble_route"}
            ],
            *[
                item
                for item in ordered
                if str(self._work_item_field(item, "work_type", "") or "").strip()
                not in {"assembly", "assemble_route"}
            ],
        ]

    def _retire_unserviceable_frontier_prefix(
        self,
        items: Sequence[Any],
        *,
        winner: Any,
    ) -> None:
        """Preserve suppression bookkeeping when global ranking jumps ahead.

        Only structurally unmappable work is retired here. Applicability,
        context identity, and selected-work binding are action-owned and may
        mutate state, so a mere ranking jump must never invoke their dispatch
        paths. Temporarily unavailable or probe-opaque work remains live.
        """

        for item in items:
            if item is winner:
                break
            work_key = self._frontier_work_key(item, probe=True)
            if work_key in self.skipped_frontier_work_keys:
                continue
            if not self._frontier_candidate_ids_for_work_item(item):
                if any(work_key):
                    self.skipped_frontier_work_keys.add(work_key)
                continue
            action = self._quote_work_item_action(item)
            if action is None:
                continue
            applicability_probe = getattr(
                action,
                "frontier_is_applicable_probe",
                None,
            )
            if not callable(applicability_probe):
                continue
            saved_target = self.selected_work_item
            saved_action_id = self.selected_work_item_action_id
            saved_record = dict(self.selected_work_item_record)
            try:
                candidate_record = self._work_item_to_record(item)
                candidate_record["mapped_action_id"] = action.id
                self.selected_work_item = item
                self.selected_work_item_action_id = action.id
                self.selected_work_item_record = candidate_record
                applicable = self._safe_is_applicable(
                    action,
                    context="global_frontier_prefix_probe",
                    predicate=applicability_probe,
                )
                if not applicable:
                    action_key = self._frontier_action_key(
                        item,
                        action.id,
                        probe=True,
                    )
                    if any(action_key):
                        self.skipped_frontier_action_keys.add(action_key)
            finally:
                self.selected_work_item = saved_target
                self.selected_work_item_action_id = saved_action_id
                self.selected_work_item_record = saved_record

    def _all_work_frontier_items(
        self,
        *,
        mutate: bool = False,
        page_limit: int = 40,
    ) -> List[Any]:
        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        items: List[Any] = []
        try:
            parameters = inspect.signature(getter).parameters
        except (TypeError, ValueError):
            parameters = {}
        production_frontier = (
            self.proof_state.__class__.__module__ == "ensemble_prover.proof_state"
            and self.proof_state.__class__.__name__ == "ProofSearchState"
            and "max_items" in parameters
            and "mutate" in parameters
        )
        if production_frontier:
            # The production frontier sorts globally before slicing, so one
            # authoritative projection reconciles graph state once. Preserve
            # the former page-one early stop when ready assembly is present;
            # its winner is absolute and downstream callers historically saw
            # only that first 256-item page.
            projection_limit = min(
                4096,
                max(1, int(page_limit or 1)) * 256,
            )
            projected = self._work_frontier_items(
                offset=0,
                mutate=mutate,
                max_items_override=projection_limit,
            )[:projection_limit]
            if any(
                str(self._work_item_field(item, "work_type", "") or "").strip()
                in {"assembly", "assemble_route"}
                for item in projected
            ):
                return projected[:256]
            return projected
        if not mutate:
            # A global observational census needs one frozen frontier, not a
            # fresh deep-copied/reconciled graph per page. The production
            # ProofSearchState accepts an explicit limit and returns a stable
            # slice; extension frontiers without that contract retain the
            # compatibility fallback below.
            if "max_items" in parameters and "mutate" in parameters:
                return self._work_frontier_items(
                    offset=0,
                    mutate=False,
                    max_items_override=4096,
                )[:4096]
        if not offset_supported:
            # Offset-less frontiers expose only a growing prefix.  Gather that
            # prefix geometrically so global value ranking does not regress
            # the legacy deep-frontier sweep.  A ready assembly is an
            # absolute winner, so stop as soon as one enters the prefix.
            frontier_window = 16
            for page_index in range(max(1, int(page_limit or 1))):
                page_items = self._work_frontier_items(
                    offset=0,
                    mutate=mutate and page_index == 0,
                    max_items_override=frontier_window,
                )
                items = page_items
                if not page_items or len(page_items) < frontier_window:
                    break
                if any(
                    str(self._work_item_field(item, "work_type", "") or "").strip()
                    in {"assembly", "assemble_route"}
                    for item in page_items
                ):
                    break
                if frontier_window >= 4096:
                    break
                frontier_window = min(4096, 4 + 2 * frontier_window)
            return items
        frontier_offset = 0
        for _page in range(max(1, int(page_limit or 1))):
            page_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=mutate and frontier_offset == 0,
                max_items_override=256,
            )
            if not page_items:
                break
            items.extend(page_items)
            if any(
                str(self._work_item_field(item, "work_type", "") or "").strip()
                in {"assembly", "assemble_route"}
                for item in page_items
            ):
                break
            if len(items) >= 4096:
                items = items[:4096]
                break
            if not offset_supported:
                break
            frontier_offset += len(page_items)
        return items

    @staticmethod
    def _work_item_field(work_item: Any, key: str, default: Any = "") -> Any:
        if isinstance(work_item, dict):
            return work_item.get(key, default)
        return getattr(work_item, key, default)

    def _frontier_work_key(
        self,
        work_item: Any,
        *,
        probe: bool = False,
    ) -> Tuple[str, str, str, str, str]:
        if work_item is None:
            return ("", "", "", "", "")
        node_id = str(self._work_item_field(work_item, "node_id", "") or "").strip()
        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        target_hash = str(
            self._work_item_field(work_item, "target_hash", "") or ""
        ).strip()
        assembly_id = str(
            self._work_item_field(work_item, "assembly_id", "") or ""
        ).strip()
        version_parts = {
            "source": str(self._work_item_field(work_item, "source", "") or ""),
            "graph_node_id": str(
                self._work_item_field(work_item, "graph_node_id", "") or ""
            ),
            "action": str(self._work_item_field(work_item, "action", "") or ""),
            "evidence_hash": str(
                self._work_item_field(work_item, "evidence_hash", "") or ""
            ),
            "retrieval_signature": str(
                self._work_item_field(work_item, "retrieval_signature", "") or ""
            ),
            "retrieval_context_stamp": str(
                self._work_item_field(work_item, "retrieval_context_stamp", "") or ""
            ),
            "retrieved_decl_names_hash": str(
                self._work_item_field(work_item, "retrieved_decl_names_hash", "") or ""
            ),
            "decl_application_pending_hash": str(
                self._work_item_field(
                    work_item,
                    "decl_application_pending_hash",
                    "",
                )
                or ""
            ),
            "helper_acceptance_request_hash": str(
                self._work_item_field(
                    work_item,
                    "helper_acceptance_request_hash",
                    "",
                )
                or ""
            ),
            "decl_application_signature": str(
                self._work_item_field(
                    work_item,
                    "decl_application_signature",
                    "",
                )
                or ""
            ),
            "residual_attestation_hash": str(
                self._work_item_field(
                    work_item,
                    "residual_attestation_hash",
                    "",
                )
                or ""
            ),
            "proof_stub_hash": str(
                self._work_item_field(work_item, "proof_stub_hash", "") or ""
            ),
            "assembly_witness_hash": str(
                self._work_item_field(work_item, "assembly_witness_hash", "") or ""
            ),
            "assembly_group_status": str(
                self._work_item_field(work_item, "assembly_group_status", "") or ""
            ),
            "dependencies": list(
                self._work_item_field(work_item, "dependencies", ()) or ()
            ),
            "child_state_node_ids": list(
                self._work_item_field(work_item, "child_state_node_ids", ()) or ()
            ),
            "unblocked_by_graph": bool(
                self._work_item_field(work_item, "unblocked_by_graph", False)
            ),
            "reopened_by_new_evidence": bool(
                self._work_item_field(work_item, "reopened_by_new_evidence", False)
            ),
        }
        for key in (
            "execution_proposition_identity",
            "execution_target_sha256",
            "target_id",
        ):
            value = str(self._work_item_field(work_item, key, "") or "").strip()
            if value:
                version_parts[key] = value
        target_statement = str(
            self._work_item_field(work_item, "exact_target_statement", "")
            or self._work_item_field(work_item, "target_statement", "")
            or ""
        ).strip()
        if target_statement:
            version_parts["target_statement_hash"] = text_hash(
                " ".join(target_statement.split())
            )
        stable_child_work = work_type in {
            "retrieval",
            "decl_probe",
            "tactic_swarm",
        }
        if stable_child_work:
            # Selection currentness includes the global proof-graph revision
            # and projection turn. Those coordinates validate a cognition
            # packet, but they are not executable work identity: recording an
            # unrelated graph attempt must not make an identical deterministic
            # child probe runnable again. Stable scope/environment fields below
            # still reopen the lane when its actual execution context changes.
            for key in (
                "cognition_scope_digest",
                "execution_scope_digest",
                "execution_environment_hash",
                "execution_helper_context_hash",
                "execution_contract_identity",
                "execution_proposition_identity",
            ):
                version_parts[key] = str(
                    self._work_item_field(work_item, key, "") or ""
                )
        else:
            for key in (
                "cognition_currentness_digest",
                "execution_currentness_digest",
            ):
                version_parts[key] = str(
                    self._work_item_field(work_item, key, "") or ""
                )
        graph_record = self._work_item_field(work_item, "graph_record", None)
        if graph_record is None and isinstance(work_item, dict):
            graph_record = work_item
        if isinstance(graph_record, dict):
            for key in (
                "route_id",
                "claim_id",
                "variant_id",
                "obligation_id",
                "replan_id",
                "target_id",
            ):
                if key in graph_record:
                    if key == "target_id" and version_parts.get(key):
                        continue
                    version_parts[key] = graph_record.get(key)
            graph_target_statement = str(
                graph_record.get("exact_target_statement")
                or graph_record.get("target_statement")
                or ""
            ).strip()
            if graph_target_statement and not version_parts.get(
                "target_statement_hash"
            ):
                version_parts["target_statement_hash"] = text_hash(
                    " ".join(graph_target_statement.split())
                )
            for key in (
                "route_missing_assembly_bridge_signature_hash",
                "route_missing_assembly_bridge_rescue_generation",
            ):
                if key in graph_record:
                    version_parts[key] = graph_record.get(key)
            graph = getattr(getattr(self, "dossier", None), "proof_graph", None)
            graph_nodes = getattr(graph, "nodes", {}) if graph is not None else {}
            route_id = str(graph_record.get("route_id") or "").strip()
            if isinstance(graph_nodes, dict) and route_id:
                version_parts["route_dependency_signature"] = (
                    self._route_dependency_signature(graph, route_id)
                )
                route_context_key = self._route_root_tactic_frontier_context_key(
                    graph,
                    route_id,
                    mutate=not probe,
                )
                if route_context_key:
                    version_parts["route_root_tactic_context_key"] = route_context_key
            obligation_id = str(graph_record.get("obligation_id") or "").strip()
            if isinstance(graph_nodes, dict) and obligation_id:
                obligation = graph_nodes.get(obligation_id)
                if obligation is not None:
                    version_parts["obligation_status"] = str(
                        getattr(obligation, "status", "") or ""
                    )
                    version_parts["obligation_source_hash"] = str(
                        getattr(obligation, "source_hash", "") or ""
                    )
                    version_parts["obligation_proof_hash"] = str(
                        getattr(obligation, "proof_hash", "") or ""
                    )
        version = hashlib.sha256(
            repr(sorted(version_parts.items())).encode("utf-8", errors="replace")
        ).hexdigest()[:16]
        return (node_id, work_type, target_hash, assembly_id, version)

    def _frontier_materialization_logical_key(
        self,
        work_item: Any,
    ) -> Tuple[str, str, str, str, str]:
        """Stable identity for empty formalization/materialization work."""

        if work_item is None:
            return ("", "", "", "", "")
        graph_record = self._work_item_field(work_item, "graph_record", None)
        if graph_record is None and isinstance(work_item, dict):
            graph_record = work_item
        record = dict(graph_record or {}) if isinstance(graph_record, dict) else {}

        def field(name: str) -> Any:
            value = self._work_item_field(work_item, name, "")
            if value in ("", None) and record:
                value = record.get(name, "")
            return value

        work_type = str(field("work_type") or "").strip()
        if work_type not in {
            "formalize_claim",
            "formalize_missing_obligation",
            "mine_missing_obligation",
        }:
            return ("", "", "", "", "")
        target_statement = str(field("target_statement") or "").strip()
        pending = bool(
            field("formalization_statement_pending")
            or field("materialization_required")
            or field("formalization_required")
        )
        if not pending:
            return ("", "", "", "", "")
        if target_statement and graph_statement_is_executable(target_statement):
            return ("", "", "", "", "")
        route_id = str(field("route_id") or "").strip()
        target_hash = str(field("target_hash") or "").strip()
        formalization_obligation_key = str(
            field("formalization_obligation_key") or ""
        ).strip()
        if formalization_obligation_key:
            target_key = f"formalization:{formalization_obligation_key}"
        else:
            seed_text = str(
                field("materialization_seed")
                or field("obligation_reason")
                or target_statement
                or field("decomposition_request_statement")
                or ""
            ).strip()
            empty_statement_hash = hashlib.sha256(b"").hexdigest()[:16]
            if seed_text:
                target_key = hashlib.sha256(
                    seed_text.encode("utf-8", errors="replace")
                ).hexdigest()[:16]
            elif target_hash and target_hash != empty_statement_hash:
                target_key = target_hash
            else:
                node_identity = str(
                    field("obligation_id")
                    or field("claim_id")
                    or field("graph_node_id")
                    or field("node_id")
                    or ""
                ).strip()
                target_key = f"node:{node_identity}" if node_identity else ""
        rescue_freshness = ""
        if bool(field("route_missing_assembly_bridge_rescue")):
            rescue_freshness = ":".join(
                [
                    str(
                        field("route_missing_assembly_bridge_signature_hash") or ""
                    ).strip(),
                    str(
                        field("route_missing_assembly_bridge_rescue_generation") or 0
                    ).strip(),
                ]
            )
            if rescue_freshness == ":":
                rescue_freshness = ""
        parent_text = str(
            field("formalization_bridge_parent_statement")
            or field("parent_repair_target_statement")
            or field("materialization_parent_statement")
            or ""
        ).strip()
        parent_key = (
            hashlib.sha256(parent_text.encode("utf-8", errors="replace")).hexdigest()[
                :16
            ]
            if parent_text
            else ""
        )
        bridge_contract = str(field("formalization_bridge_contract") or "").strip()
        if rescue_freshness:
            bridge_contract = (
                f"{bridge_contract}|route_missing_assembly_bridge:{rescue_freshness}"
            )
        route_component = "" if (target_key or parent_key) else route_id
        if not (target_key or parent_key or route_component):
            return ("", "", "", "", "")
        return (
            "empty_formalization_materialization",
            route_component,
            target_key,
            parent_key,
            bridge_contract,
        )

    def _materialization_progress_frontier_keys(
        self,
        outcome: MiniOutcome,
    ) -> Tuple[
        Set[Tuple[str, str, str, str, str, str]],
        Set[Tuple[str, str, str, str, str]],
        Set[Tuple[str, str, str, str, str]],
    ]:
        """Return materialization suppression keys cleared by progress metadata."""

        metadata = dict(getattr(outcome, "metadata", {}) or {})
        records: List[Dict[str, Any]] = []
        for value in (
            metadata.get("selected_graph_work"),
            metadata.get("graph_native_selected_work"),
        ):
            if isinstance(value, dict):
                records.append(dict(value))
        contract = metadata.get("graph_native_formalization_contract")
        if isinstance(contract, dict):
            selected = contract.get("selected_graph_work")
            if isinstance(selected, dict):
                records.append(dict(selected))
        action_keys: Set[Tuple[str, str, str, str, str, str]] = set()
        logical_keys: Set[Tuple[str, str, str, str, str]] = set()
        work_keys: Set[Tuple[str, str, str, str, str]] = set()
        for record in records:
            work_key = self._frontier_work_key(record)
            if any(work_key):
                work_keys.add(work_key)
            logical_key = self._frontier_materialization_logical_key(record)
            if any(logical_key):
                logical_keys.add(logical_key)
            action_key = self._frontier_action_key(record, outcome.action_id)
            if any(action_key):
                action_keys.add(action_key)
        return action_keys, logical_keys, work_keys

    def _discard_skipped_frontier_keys_for_progress(
        self,
        *,
        work_keys: Iterable[Tuple[str, str, str, str, str]] = (),
        action_keys: Iterable[Tuple[str, str, str, str, str, str]] = (),
        logical_keys: Iterable[Tuple[str, str, str, str, str]] = (),
    ) -> None:
        """Release skip suppressors only for frontier work touched by progress."""

        clean_work_keys = {
            tuple(key)
            for key in list(work_keys or ())
            if isinstance(key, tuple) and any(key)
        }
        clean_action_keys = {
            tuple(key)
            for key in list(action_keys or ())
            if isinstance(key, tuple) and any(key)
        }
        clean_logical_keys = {
            tuple(key)
            for key in list(logical_keys or ())
            if isinstance(key, tuple) and any(key)
        }
        for action_key, logical_key in list(
            self.materialization_pending_frontier_action_logical_keys.items()
        ):
            if tuple(logical_key) in clean_logical_keys:
                clean_action_keys.add(tuple(action_key))
                clean_work_keys.add(tuple(action_key[:5]))

        if clean_action_keys:
            self.skipped_frontier_action_keys.difference_update(clean_action_keys)
            clean_work_keys.update(tuple(key[:5]) for key in clean_action_keys if key)
        if clean_work_keys:
            work_prefixes = {tuple(key[:4]) for key in clean_work_keys}
            self.skipped_frontier_work_keys = {
                key
                for key in self.skipped_frontier_work_keys
                if tuple(key) not in clean_work_keys
                and tuple(key[:4]) not in work_prefixes
            }
            self.skipped_frontier_action_keys = {
                key
                for key in self.skipped_frontier_action_keys
                if tuple(key[:5]) not in clean_work_keys
                and tuple(key[:4]) not in work_prefixes
            }
        if clean_logical_keys:
            self.materialization_pending_no_applicable_recovery_logical_keys.difference_update(
                clean_logical_keys
            )
            for logical_key in clean_logical_keys:
                self.materialization_pending_no_applicable_recovery_counts.pop(
                    logical_key,
                    None,
                )

    def _route_root_tactic_frontier_context_key(
        self,
        graph: Any,
        route_id: str,
        *,
        mutate: bool = True,
    ) -> str:
        route = str(route_id or "").strip()
        if not route or self.dossier is None:
            return ""
        action = self.registered_action("graph_route_assembly")
        if action is None:
            return ""
        route_ready = getattr(action, "_route_ready", None)
        route_helper_names = getattr(action, "_route_helper_names", None)
        route_helper_blocks = getattr(action, "_route_helper_blocks", None)
        if not (
            callable(route_ready)
            and callable(route_helper_names)
            and callable(route_helper_blocks)
        ):
            return ""
        try:
            ready, deps = route_ready(graph, route, mutate=mutate)
        except Exception:
            return ""
        if not ready:
            return ""
        try:
            helper_names = route_helper_names(graph, deps, self.dossier)
        except Exception:
            helper_names = []
        if not helper_names:
            return ""
        try:
            helper_blocks = route_helper_blocks(
                self.dossier,
                helper_names,
                refresh_quality=mutate,
            )
        except Exception:
            helper_blocks = []
        try:
            from ensemble_prover.proof_state_executor import _root_tactic_context_key
        except Exception:
            return ""
        problem = getattr(self, "problem", None)
        goal_statement = str(
            getattr(problem, "statement_type", "")
            or getattr(self.dossier, "root_statement", "")
            or ""
        )
        preamble = (
            self.acceptance_preamble()
            if hasattr(self, "acceptance_preamble")
            else str(getattr(getattr(self, "conv", None), "preamble", "") or "")
        )
        return _root_tactic_context_key(
            goal_statement=goal_statement,
            preamble=preamble,
            helpers=helper_blocks,
            timeout_s=float(getattr(action, "root_tactic_timeout_s", 0.0) or 0.0),
            max_candidates=int(getattr(action, "root_tactic_max_candidates", 0) or 0),
        )

    @staticmethod
    def _route_dependency_signature(
        graph: Any, route_id: str
    ) -> Tuple[Tuple[str, ...], ...]:
        """Stable key material for a route's current certified dependencies."""

        route = str(route_id or "").strip()
        if not route:
            return ()
        signature_getter = getattr(graph, "route_dependency_signature", None)
        if callable(signature_getter):
            try:
                signature = list(signature_getter(route) or [])
                return tuple(
                    sorted(json.dumps(item, sort_keys=True) for item in signature)
                )
            except Exception:
                pass
        outgoing = getattr(graph, "outgoing", None)
        graph_nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if not callable(outgoing) or not isinstance(graph_nodes, dict):
            return ()
        parts: List[Tuple[str, ...]] = []
        try:
            edges = list(outgoing(route))
        except Exception:
            return ()
        for edge in edges:
            kind = str(getattr(edge, "kind", "") or "")
            if kind not in {"route_requires", "route_blocked_by", "route_replan"}:
                continue
            target_id = str(getattr(edge, "target", "") or "")
            target = graph_nodes.get(target_id)
            metadata = dict(getattr(target, "metadata", {}) or {}) if target else {}
            parts.append(
                (
                    kind,
                    target_id,
                    str(getattr(target, "kind", "") or "") if target else "",
                    str(getattr(target, "status", "") or "") if target else "",
                    str(getattr(target, "source_hash", "") or "") if target else "",
                    str(getattr(target, "proof_hash", "") or "") if target else "",
                    str(metadata.get("proposal_revision") or ""),
                    str(metadata.get("verified_helper_source_hash") or ""),
                    str(metadata.get("assembled_route_proof_hash") or ""),
                )
            )
        return tuple(sorted(parts))

    def _frontier_action_key(
        self,
        work_item: Any,
        action_id: str,
        *,
        probe: bool = False,
    ) -> Tuple[str, str, str, str, str, str]:
        action_key = str(action_id or "")
        action = self.registered_action(action_key)
        context_hook = getattr(
            action,
            "frontier_context_hash_probe" if probe else "frontier_context_hash",
            None,
        )
        if callable(context_hook):
            try:
                try:
                    raw_context_hash = context_hook(self, work_item)
                except TypeError:
                    raw_context_hash = context_hook(self)
                context_hash = str(raw_context_hash or "").strip()
            except Exception:
                context_hash = ""
            if context_hash:
                action_key = f"{action_key}:context={context_hash}"
        return (*self._frontier_work_key(work_item, probe=probe), action_key)

    def _frontier_progress_retry_keys(
        self,
        work_item: Any,
        exact_action_key: Tuple[str, str, str, str, str, str],
    ) -> Tuple[Tuple[str, str, str, str, str, str], ...]:
        """Return retry aliases stable across graph-currentness churn.

        The ordinary frontier key deliberately includes volatile evidence and
        graph revision material so a selector can reject stale work. Retry
        allowance is different: only a changed Lean execution environment may
        reopen it, otherwise failed-node churn can manufacture model calls.
        """

        exact = tuple(str(item or "") for item in exact_action_key)
        if len(exact) != 6:
            return (("", "", "", "", "", ""),)
        graph_record = self._work_item_field(work_item, "graph_record", None)
        if graph_record is None and isinstance(work_item, dict):
            graph_record = work_item
        record = dict(graph_record or {}) if isinstance(graph_record, dict) else {}
        serialized_work = self._work_item_to_record(work_item)

        def semantic_field(name: str) -> Any:
            value = self._work_item_field(work_item, name, "")
            if value in ("", None) and record:
                value = record.get(name, "")
            if value in ("", None):
                for layer in selected_work_mapping_layers(serialized_work):
                    value = layer.get(name, "")
                    if value not in ("", None):
                        break
            return value

        # Retry allowance is keyed only by the executable Lean contract.  In
        # particular, model-authored proof stubs, assembly witnesses,
        # retrieval packets, and route graph receipts are progress evidence,
        # not a new right to buy another model call.  Those volatile values
        # remain in ``exact_action_key`` for selector currentness, but cannot
        # reset this cap.
        execution_context: Dict[str, Any] = {}
        execution_contract_identity = semantic_field("execution_contract_identity")
        if execution_contract_identity not in ("", None, (), [], {}):
            execution_context["execution_contract_identity"] = (
                execution_contract_identity
            )
        conv = getattr(self, "conv", None)
        prompt_preamble = str(getattr(conv, "preamble", "") or "")
        lean_preamble = str(getattr(conv, "lean_preamble", "") or prompt_preamble)
        execution_context["model_prompt_preamble_hash"] = text_hash(prompt_preamble)
        execution_context["session_goal_hash"] = text_hash(
            str(getattr(conv, "goal_statement", "") or "")
        )
        target_record = dict(serialized_work or record)
        for key in (
            "exact_target_statement",
            "target_statement",
            "execution_proposition_identity",
            "execution_target_sha256",
            "target_hash",
            "target_id",
        ):
            value = semantic_field(key)
            if value not in ("", None, (), [], {}):
                target_record[key] = value
        target_aliases = list(self._model_call_deferred_target_aliases(target_record))
        semantic_target_available = bool(target_aliases)
        structural_identity = (
            ("", "")
            if semantic_target_available
            else self._model_call_deferred_structural_identity(target_record)
        )
        if not target_aliases:
            fallback_statement = str(
                getattr(conv, "goal_statement", "")
                or getattr(getattr(self, "problem", None), "statement_type", "")
                or getattr(self.dossier, "root_statement", "")
                or ""
            )
            target_aliases.append(
                (
                    "target_statement",
                    " ".join(fallback_statement.split()),
                )
            )
        helper_blocks: Tuple[str, ...] = ()
        helper_getter = getattr(self.dossier, "verified_helper_blocks", None)
        if callable(helper_getter):
            try:
                helper_blocks = tuple(
                    str(block or "")
                    for block in list(helper_getter(refresh_quality=False) or ())
                )
            except TypeError:
                try:
                    helper_blocks = tuple(
                        str(block or "") for block in list(helper_getter() or ())
                    )
                except Exception:
                    helper_blocks = ()
            except Exception:
                helper_blocks = ()
        fallback_helper_hashes = sorted(
            text_hash(block) for block in helper_blocks if block.strip()
        )
        explicit_helper_context = semantic_field("execution_helper_context_hash")
        execution_context["effective_helper_context"] = (
            explicit_helper_context
            if explicit_helper_context not in ("", None, (), [], {})
            else fallback_helper_hashes
        )
        fallback_environment_hash = text_hash(lean_preamble)
        explicit_environment_hash = semantic_field("execution_environment_hash")
        execution_context["effective_environment_hash"] = (
            explicit_environment_hash
            if explicit_environment_hash not in ("", None, (), [], {})
            else fallback_environment_hash
        )
        lean_capability = _dispatch_capability_identity(getattr(self, "lean", None))
        execution_context["lean_capability_generation"] = (
            "none"
            if lean_capability is None
            else (
                f"{type(lean_capability).__module__}."
                f"{type(lean_capability).__qualname__}:"
                f"{id(lean_capability)}"
            )
        )
        execution_hash = hashlib.sha256(
            json.dumps(
                execution_context,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                default=str,
            ).encode("utf-8")
        ).hexdigest()[:16]
        base_action_id = exact[5].split(":context=", 1)[0]
        scope_component = (
            "semantic"
            if semantic_target_available
            else ("structural" if any(structural_identity) else "fallback")
        )
        return tuple(
            (
                scope_component,
                exact[1],
                text_hash(
                    json.dumps(
                        {
                            "target_alias": target_alias,
                            "structural_identity": structural_identity,
                        },
                        separators=(",", ":"),
                        ensure_ascii=True,
                    )
                ),
                "",
                execution_hash,
                base_action_id,
            )
            for target_alias in target_aliases
        )

    def _frontier_progress_retry_key(
        self,
        work_item: Any,
        exact_action_key: Tuple[str, str, str, str, str, str],
    ) -> Tuple[str, str, str, str, str, str]:
        return self._frontier_progress_retry_keys(work_item, exact_action_key)[0]

    def _proof_work_semantic_attempt_identity(
        self,
        work_item: Any,
        *,
        action_id: str,
        omit_root_cognition: bool = False,
    ) -> str:
        """Return a durable retry identity for one executable proof contract."""

        if work_item is None:
            return ""

        def field(name: str, default: Any = "") -> Any:
            return self._work_item_field(work_item, name, default)

        work_type = str(field("work_type") or "").strip()
        target_identity = str(
            field("execution_target_sha256")
            or field("target_hash")
            or text_hash(
                str(field("exact_target_statement") or field("target_statement") or "")
            )
        ).strip()
        if not work_type or not target_identity:
            return ""
        action_key = str(action_id or "").strip()
        action = self.registered_action(action_key)
        portfolio_hook = getattr(action, "proof_work_portfolio_identity", None)
        portfolio: Any = None
        if callable(portfolio_hook):
            try:
                portfolio = portfolio_hook(self, work_item)
            except Exception:
                portfolio = None
        if portfolio in (None, "", (), [], {}):
            if work_type == "decl_probe":
                pending_names = field("decl_application_pending_names", ())
                if isinstance(pending_names, str):
                    pending_names = [pending_names]
                portfolio = {
                    "retrieved_decl_names_hash": str(
                        field("retrieved_decl_names_hash") or ""
                    ),
                    "decl_application_pending_hash": str(
                        field("decl_application_pending_hash") or ""
                    ),
                    "decl_application_pending_names": sorted(
                        {
                            str(item or "").strip()
                            for item in list(pending_names or ())
                            if str(item or "").strip()
                        }
                    ),
                    "decl_application_signature": str(
                        field("decl_application_signature") or ""
                    ),
                }
            elif work_type == "tactic_swarm":
                portfolio = {
                    "tactic_portfolio_hash": str(field("tactic_portfolio_hash") or ""),
                    "proof_stub_hash": str(field("proof_stub_hash") or ""),
                }
            else:
                portfolio = {
                    "helper_acceptance_request_hash": str(
                        field("helper_acceptance_request_hash") or ""
                    ),
                    "residual_attestation_hash": str(
                        field("residual_attestation_hash") or ""
                    ),
                    "proof_stub_hash": str(field("proof_stub_hash") or ""),
                }
        payload = {
            "schema_version": 1,
            "action_id": action_key,
            "work_type": work_type,
            "target_identity": target_identity,
            "execution_environment_hash": str(
                field("execution_environment_hash") or ""
            ),
            "execution_helper_context_hash": str(
                field("execution_helper_context_hash") or ""
            ),
            "execution_contract_identity": str(
                field("execution_contract_identity") or ""
            ),
            "execution_proposition_identity": str(
                field("execution_proposition_identity") or ""
            ),
            "proof_idea_identity": {
                "proof_idea_id": str(field("proof_idea_id") or ""),
                "cognition_scope_digest": str(field("cognition_scope_digest") or ""),
                "primary_consumer_binding_id": str(
                    field("primary_consumer_binding_id") or ""
                ),
            },
            "portfolio": portfolio,
        }
        is_root_conversation = bool(
            action_key.startswith("conversation_turn")
            and work_type == "root_repair"
            and str(field("node_id") or "root").strip() == "root"
        )
        if is_root_conversation:
            dossier = getattr(self, "dossier", None)
            conv = getattr(self, "conv", None)
            root_target = str(
                field("exact_target_statement")
                or field("target_statement")
                or getattr(conv, "goal_statement", "")
                or getattr(dossier, "root_statement", "")
                or getattr(getattr(self, "problem", None), "statement_type", "")
                or ""
            ).strip()
            if root_target:
                target_identity = hashlib.sha256(
                    root_target.encode("utf-8")
                ).hexdigest()
            if conv is not None:
                runtime_environment = text_hash(
                    str(
                        getattr(conv, "lean_preamble", "")
                        or getattr(conv, "preamble", "")
                        or ""
                    )
                )
            else:
                runtime_environment = str(
                    getattr(dossier, "current_lean_environment_hash", "") or ""
                ).strip()
            formal_evidence = self._durable_formal_progress_evidence()
            payload.update(
                {
                    "target_identity": target_identity,
                    "execution_environment_hash": runtime_environment,
                    "execution_helper_context_hash": text_hash(
                        json.dumps(
                            list(formal_evidence),
                            separators=(",", ":"),
                        )
                    ),
                    "execution_contract_identity": target_identity,
                    "execution_proposition_identity": target_identity,
                }
            )
            if omit_root_cognition:
                payload["proof_idea_identity"] = {
                    "proof_idea_id": "",
                    "cognition_scope_digest": "",
                    "primary_consumer_binding_id": "",
                }
        # Full SHA-256 keys are fixed-width durable authority. Procedural graph
        # node ids are intentionally absent: aliases of the same executable
        # contract must share the cap.
        return hashlib.sha256(
            json.dumps(
                payload,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                default=str,
            ).encode("utf-8")
        ).hexdigest()

    def _conversation_semantic_work_item(self, action_id: str) -> Any:
        """Return selected work or a stable synthetic root conversation item."""

        if self.selected_work_item is not None:
            return self.selected_work_item
        dossier = getattr(self, "dossier", None)
        conv = getattr(self, "conv", None)
        problem = getattr(self, "problem", None)
        target = str(
            getattr(conv, "goal_statement", "")
            or getattr(dossier, "root_statement", "")
            or getattr(problem, "statement_type", "")
            or ""
        ).strip()
        if not target:
            return None
        evidence = self._durable_formal_progress_evidence()
        environment = str(
            getattr(dossier, "current_lean_environment_hash", "") or ""
        ).strip()
        if not environment:
            environment = text_hash(
                str(
                    getattr(conv, "lean_preamble", "")
                    or getattr(conv, "preamble", "")
                    or ""
                )
            )
        return {
            "node_id": "root",
            "work_type": "root_repair",
            "action": str(action_id or ""),
            "source": "static_root",
            "graph_record": {},
            "target_hash": text_hash(target),
            "exact_target_statement": target,
            "execution_environment_hash": environment,
            "execution_helper_context_hash": text_hash(
                json.dumps(list(evidence), separators=(",", ":"))
            ),
            "execution_contract_identity": text_hash(target),
            "execution_proposition_identity": text_hash(target),
        }

    def _prune_proof_work_no_progress_attempt_counts(self) -> None:
        limit = min(
            _MAX_DURABLE_SEMANTIC_LEDGER_IDENTITIES,
            max(1, int(self.max_proof_work_no_progress_identities or 0)),
        )
        counts = self.proof_work_no_progress_attempt_counts
        peaks = self.proof_work_no_progress_peak_attempt_counts
        signatures = self.proof_work_no_progress_last_signatures
        signature_history = self.proof_work_no_progress_signature_history
        aliases_by_base = self.proof_work_root_alias_identities_by_base
        closed_aliases = self.proof_work_closed_root_alias_identities
        for key in list(counts):
            value = counts.get(key)
            if (
                not isinstance(key, str)
                or len(key) > 64
                or isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
            ):
                counts.pop(key, None)
                peaks.pop(key, None)
                signatures.pop(key, None)
                signature_history.pop(key, None)
        for key in list(peaks):
            value = peaks.get(key)
            if (
                key not in counts
                or isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
            ):
                peaks.pop(key, None)
        for base in list(aliases_by_base):
            aliases = aliases_by_base.get(base)
            if base not in counts or not isinstance(aliases, list):
                aliases_by_base.pop(base, None)
                continue
            bounded_aliases = [
                str(alias or "").strip()
                for alias in aliases[:limit]
                if str(alias or "").strip() in counts
                and str(alias or "").strip() != base
            ]
            if bounded_aliases:
                aliases_by_base[base] = list(dict.fromkeys(bounded_aliases))
            else:
                aliases_by_base.pop(base, None)
        self.proof_work_closed_root_alias_identities = {
            str(alias or "").strip(): 1
            for alias, closed in dict(closed_aliases or {}).items()
            if str(alias or "").strip() in counts and int(closed or 0) > 0
        }
        for key in list(signatures):
            signature = signatures.get(key)
            if (
                key not in counts
                or not isinstance(signature, str)
                or len(signature) > 128
            ):
                signatures.pop(key, None)
        for key in list(signature_history):
            history = signature_history.get(key)
            if (
                key not in counts
                or not isinstance(history, list)
                or len(history) > 32
                or any(
                    not isinstance(item, str) or not item or len(item) > 128
                    for item in list(history or ())
                )
            ):
                signature_history.pop(key, None)
        order = [
            str(identity or "").strip()
            for identity in list(self.proof_work_no_progress_attempt_order or ())
            if str(identity or "").strip() in counts
        ]
        order = list(dict.fromkeys(order))
        for identity in counts:
            if identity not in order:
                order.append(identity)
        while len(order) > limit:
            evicted = order.pop(0)
            counts.pop(evicted, None)
            peaks.pop(evicted, None)
            signatures.pop(evicted, None)
            signature_history.pop(evicted, None)
            aliases_by_base.pop(evicted, None)
            self.proof_work_closed_root_alias_identities.pop(evicted, None)
            for base in list(aliases_by_base):
                aliases_by_base[base] = [
                    alias for alias in aliases_by_base[base] if alias != evicted
                ]
                if not aliases_by_base[base]:
                    aliases_by_base.pop(base, None)
        self.proof_work_no_progress_attempt_order = order

    def _touch_proof_work_no_progress_identity(self, identity: str) -> None:
        clean = str(identity or "").strip()
        if clean not in self.proof_work_no_progress_attempt_counts:
            return
        self.proof_work_no_progress_attempt_order = [
            item for item in self.proof_work_no_progress_attempt_order if item != clean
        ]
        self.proof_work_no_progress_attempt_order.append(clean)

    def proof_work_semantic_attempt_exhausted(
        self,
        work_item: Any,
        *,
        action_id: str,
        touch: bool = True,
    ) -> bool:
        """Whether the unchanged proof contract used all paid retry quanta."""

        limit = max(0, int(self.max_proof_work_no_progress_attempts or 0))
        if limit <= 0:
            return False
        self._prune_proof_work_no_progress_attempt_counts()
        identity = self._proof_work_semantic_attempt_identity(
            work_item,
            action_id=action_id,
        )
        if not identity:
            return False
        exact_peak_count = self._proof_work_semantic_peak_attempt_count(identity)
        exhausted = bool(
            exact_peak_count >= limit
            or identity in self.proof_work_closed_root_alias_identities
        )
        static_root_identity = self._proof_work_semantic_attempt_identity(
            work_item,
            action_id=action_id,
            omit_root_cognition=True,
        )
        if touch and identity in self.proof_work_no_progress_attempt_counts:
            self._touch_proof_work_no_progress_identity(identity)
        if (
            touch
            and static_root_identity != identity
            and static_root_identity in self.proof_work_no_progress_attempt_counts
        ):
            self._touch_proof_work_no_progress_identity(static_root_identity)
        return exhausted

    def _proof_work_semantic_peak_attempt_count(self, identity: str) -> int:
        """Return the largest repeated wall count retained for an identity."""

        clean = str(identity or "").strip()
        if not clean:
            return 0
        current = max(
            0,
            int(self.proof_work_no_progress_attempt_counts.get(clean, 0) or 0),
        )
        durable_peak = max(
            0,
            int(self.proof_work_no_progress_peak_attempt_counts.get(clean, 0) or 0),
        )
        history = tuple(self.proof_work_no_progress_signature_history.get(clean) or ())
        if not history:
            return max(current, durable_peak)
        return max(
            current,
            durable_peak,
            max(
                sum(item == signature for item in history) for signature in set(history)
            ),
        )

    def record_proof_work_no_progress_attempt(
        self,
        work_item: Any,
        *,
        action_id: str,
    ) -> int:
        """Consume one retry of the unchanged proof contract and return count."""

        identity = self._proof_work_semantic_attempt_identity(
            work_item,
            action_id=action_id,
        )
        return self._record_proof_work_no_progress_attempt_identity(identity)

    def record_conversation_semantic_no_progress_attempt(
        self,
        work_item: Any,
        *,
        action_id: str,
        semantic_signature: str,
    ) -> int:
        """Count one exact completed semantic wall for a conversation lane."""

        signature = str(semantic_signature or "").strip()
        if not signature or len(signature) > 128:
            return 0
        identity = self._proof_work_semantic_attempt_identity(
            work_item,
            action_id=action_id,
        )
        static_root_identity = self._proof_work_semantic_attempt_identity(
            work_item,
            action_id=action_id,
            omit_root_cognition=True,
        )
        static_root_peak_before = self._proof_work_semantic_peak_attempt_count(
            static_root_identity
        )
        count = self._record_conversation_semantic_no_progress_attempt_identity(
            identity,
            signature,
        )
        self._record_conversation_static_root_attempt(
            exact_identity=identity,
            static_root_identity=static_root_identity,
            semantic_signature=signature,
            static_root_peak_before=static_root_peak_before,
        )
        return count

    def _record_conversation_static_root_attempt(
        self,
        *,
        exact_identity: str,
        static_root_identity: str,
        semantic_signature: str,
        static_root_peak_before: int,
    ) -> None:
        """Charge one paid selected-root wall to its static fallback alias."""

        exact = str(exact_identity or "").strip()
        static = str(static_root_identity or "").strip()
        signature = str(semantic_signature or "").strip()
        if not exact or not static or not signature or len(signature) > 128:
            return
        if static != exact:
            self._record_conversation_semantic_no_progress_attempt_identity(
                static,
                signature,
            )
            aliases = self.proof_work_root_alias_identities_by_base.setdefault(
                static,
                [],
            )
            if exact not in aliases:
                aliases.append(exact)
        limit = max(0, int(self.max_proof_work_no_progress_attempts or 0))
        static_peak_after = self._proof_work_semantic_peak_attempt_count(static)
        if (
            limit > 0
            and max(0, int(static_root_peak_before or 0)) < limit
            and static_peak_after >= limit
        ):
            for alias in (
                self.proof_work_root_alias_identities_by_base.get(static) or ()
            ):
                self.proof_work_closed_root_alias_identities[alias] = 1
        if limit > 0 and self._proof_work_semantic_peak_attempt_count(exact) >= limit:
            self.proof_work_closed_root_alias_identities[exact] = 1

    def _record_conversation_semantic_no_progress_attempt_identity(
        self,
        identity: str,
        semantic_signature: str,
    ) -> int:
        """Record from the immutable pre-dispatch execution identity."""

        identity = str(identity or "").strip()
        signature = str(semantic_signature or "").strip()
        if not identity or not signature or len(signature) > 128:
            return 0
        self._prune_proof_work_no_progress_attempt_counts()
        history = list(
            self.proof_work_no_progress_signature_history.get(identity) or ()
        )
        prior_occurrences = sum(item == signature for item in history)
        self.proof_work_no_progress_attempt_counts[identity] = prior_occurrences
        count = self._record_proof_work_no_progress_attempt_identity(identity)
        if count > 0:
            self.proof_work_no_progress_last_signatures[identity] = signature
            history.append(signature)
            self.proof_work_no_progress_signature_history[identity] = history[-32:]
        return count

    def _record_proof_work_no_progress_attempt_identity(
        self,
        identity: str,
    ) -> int:
        """Consume a pre-dispatch proof identity without post-run state drift."""

        identity = str(identity or "").strip()
        if not identity:
            return 0
        self._prune_proof_work_no_progress_attempt_counts()
        identity_limit = min(
            _MAX_DURABLE_SEMANTIC_LEDGER_IDENTITIES,
            max(1, int(self.max_proof_work_no_progress_identities or 0)),
        )
        if identity not in self.proof_work_no_progress_attempt_counts:
            while len(self.proof_work_no_progress_attempt_counts) >= identity_limit:
                evicted = self.proof_work_no_progress_attempt_order.pop(0)
                self.proof_work_no_progress_attempt_counts.pop(evicted, None)
                self.proof_work_no_progress_peak_attempt_counts.pop(
                    evicted,
                    None,
                )
                self.proof_work_no_progress_last_signatures.pop(evicted, None)
                self.proof_work_no_progress_signature_history.pop(evicted, None)
                self.proof_work_root_alias_identities_by_base.pop(evicted, None)
                self.proof_work_closed_root_alias_identities.pop(evicted, None)
                for base in list(self.proof_work_root_alias_identities_by_base):
                    self.proof_work_root_alias_identities_by_base[base] = [
                        alias
                        for alias in self.proof_work_root_alias_identities_by_base[base]
                        if alias != evicted
                    ]
                    if not self.proof_work_root_alias_identities_by_base[base]:
                        self.proof_work_root_alias_identities_by_base.pop(base, None)
            self.proof_work_no_progress_attempt_order.append(identity)
        else:
            self._touch_proof_work_no_progress_identity(identity)
        count = (
            max(
                0,
                int(self.proof_work_no_progress_attempt_counts.get(identity, 0) or 0),
            )
            + 1
        )
        self.proof_work_no_progress_attempt_counts[identity] = count
        self.proof_work_no_progress_peak_attempt_counts[identity] = max(
            count,
            int(self.proof_work_no_progress_peak_attempt_counts.get(identity, 0) or 0),
        )
        return count

    def _frontier_candidate_ids_for_work_type(self, work_type: str) -> List[str]:
        work_type = str(work_type or "")
        if work_type == "assembly":
            return ["inter_turn_assembly"]
        if work_type == "lemma_dag_decomposition":
            return ["lemma_dag_decompose"]
        if work_type == "child_llm_prove":
            return ["recursive_helper_prover"]
        if work_type == "retrieval":
            return ["proof_state_retrieval"]
        if work_type in {
            "decl_probe",
            "tactic_swarm",
            "residual_goal_extraction",
            "helper_acceptance",
        }:
            return ["child_closure"]
        if work_type == "formal_state_expand":
            return ["formal_state_search"]
        if work_type == "assemble_route":
            return [
                "graph_route_assembly",
                "conversation_turn_prove",
                "conversation_turn_refine",
            ]
        if work_type in {"mine_missing_obligation", "route_replan"}:
            recursive_ids = [
                str(action.id)
                for _index, action in sorted(
                    enumerate(self.actions),
                    key=lambda item: (
                        int(getattr(item[1], "priority", 100) or 100),
                        item[0],
                    ),
                )
                if str(getattr(action, "FRONTIER_ACTION_FAMILY", "") or "")
                == "graph_recursive_decompose"
                and work_type in set(getattr(action, "WORK_TYPES", ()) or ())
                and str(getattr(action, "id", "") or "")
            ]
            if "graph_recursive_decompose" not in recursive_ids:
                recursive_ids.append("graph_recursive_decompose")
            return [
                *dict.fromkeys(recursive_ids),
                "graph_native_shortcut",
                "conversation_turn_prove",
            ]
        if work_type == "target_integrity_adjudication":
            return ["conversation_turn_prove"]
        if work_type in {
            "formalize_claim",
            "prove_claim_variant",
        }:
            return ["graph_native_shortcut", "conversation_turn_prove"]
        if work_type == "materialize_replay_source":
            return ["conversation_turn_prove"]
        if work_type == "formalize_missing_obligation":
            return ["conversation_turn_prove"]
        if work_type == "root_repair":
            # Root-repair is itself a formal-state bottleneck.  Keeping formal
            # search exclusive to ``formal_state_expand`` made the feature
            # unreachable when ordinary ``try_lean`` attempts failed without
            # first materializing a child node.  The action remains fail-closed
            # through its own applicability/context checks and runs one bounded
            # quantum before conversational regeneration. The
            # existing outer cheap-tactic prepass remains independently owned;
            # do not duplicate it as typed frontier work (parallel sampling
            # would otherwise multiply that prepass per child).
            return [
                "formal_state_search",
                "conversation_turn_prove",
                "conversation_turn_refine",
            ]
        return []

    @staticmethod
    def _selected_work_target_resource_kind(record: Mapping[str, Any]) -> str:
        """Return the typed execution resource carried by selected work.

        This deliberately separates a mathematical statement from a
        procedural materialization seed.  Actions which require an executable
        proposition must never reinterpret a seed-only record as unscoped
        permission to work on the session root.
        """

        payload = dict(record or {})
        target = str(
            payload.get("exact_target_statement")
            or payload.get("target_statement")
            or ""
        ).strip()
        if target and graph_statement_is_executable(target):
            return "executable_statement"
        if str(payload.get("materialization_seed") or "").strip():
            return "materialization_seed"
        work_type = str(payload.get("work_type") or "").strip()
        if (
            work_type == "assemble_route"
            and str(
                payload.get("route_id") or payload.get("graph_node_id") or ""
            ).strip()
        ):
            return "route"
        if (
            work_type
            in {
                "assembly",
                "retrieval",
                "decl_probe",
                "tactic_swarm",
                "residual_goal_extraction",
                "helper_acceptance",
                "formal_state_expand",
                "child_llm_prove",
                "lemma_dag_decomposition",
            }
            and str(payload.get("node_id") or "").strip()
        ):
            return "proof_state_node"
        if work_type == "root_repair":
            return "root"
        return "missing"

    def _frontier_candidate_ids_for_work_item(self, work_item: Any) -> List[str]:
        """Return the one authoritative action capability list for work.

        Mapping, restoration, narrowing and recovery all consume this method.
        Keeping the resource check here prevents the former split-brain where
        the normal frontier mapped seed-only formalization to conversation but
        the static narrowing loop restored it onto every registered action.
        """

        record = self._work_item_to_record(work_item)
        work_type = str(record.get("work_type") or "").strip()
        candidate_ids = list(self._frontier_candidate_ids_for_work_type(work_type))
        resource_kind = self._selected_work_target_resource_kind(record)
        if resource_kind == "missing" and self._frontier_item_executable_statement(
            work_item,
            for_capability=True,
        ):
            # Some persisted/frontier records intentionally carry only a
            # graph node identity.  Resolve their proposition from the live
            # graph before assigning action ownership; this is still an exact
            # typed resource, not permission to fall back to the root.
            resource_kind = "executable_statement"
        if bool(record.get("formalization_required")) and resource_kind == (
            "executable_statement"
        ):
            candidate_ids = [
                "domain_theory",
                *candidate_ids,
                "domain_theory_build",
            ]
        # Conversation is the only current action with an explicit
        # materialization-seed contract.  Other actions require a proposition,
        # proof-state node, route, or root and therefore fail closed.
        if resource_kind == "materialization_seed":
            candidate_ids = [
                action_id
                for action_id in candidate_ids
                if str(action_id).startswith("conversation_turn")
            ]
        return list(dict.fromkeys(candidate_ids))

    def _selected_work_action_compatible(
        self,
        action_id: str,
        record: Mapping[str, Any],
    ) -> bool:
        payload = dict(record or {})
        if not payload or not str(payload.get("work_type") or "").strip():
            return False
        clean_action_id = str(action_id or "").strip()
        if not clean_action_id:
            return False
        return clean_action_id in self._frontier_candidate_ids_for_work_item(payload)

    def _assemble_route_authoring_ready(
        self,
        work_item: Any,
        *,
        mutate: bool = True,
    ) -> bool:
        """Whether a route may fall through to an LLM-authored root assembly."""

        work_type = str(self._work_item_field(work_item, "work_type", "") or "")
        if work_type != "assemble_route":
            return False
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return False
        raw_graph_record = self._work_item_field(work_item, "graph_record", None)
        if raw_graph_record is None and isinstance(work_item, dict):
            raw_graph_record = work_item
        graph_record = (
            dict(raw_graph_record or {}) if isinstance(raw_graph_record, dict) else {}
        )
        record = {
            **graph_record,
            **self._work_item_to_record(work_item),
        }
        route_id = str(
            record.get("route_id")
            or record.get("graph_node_id")
            or record.get("node_id")
            or ""
        ).strip()
        route = nodes.get(route_id)
        if route is None or str(getattr(route, "kind", "") or "") != "strategy_route":
            return False
        if str(getattr(route, "status", "") or "") in {"rejected", "failed"}:
            return False
        metadata = getattr(route, "metadata", None)
        if not isinstance(metadata, dict):
            return False
        if metadata.get("route_retired") or metadata.get(
            "route_dependency_contradicted"
        ):
            return False
        contract_status_getter = getattr(graph, "route_assembly_contract_status", None)
        if not callable(contract_status_getter):
            return False
        problem = getattr(self, "problem", None)
        target_statement = str(
            getattr(dossier, "root_statement", "")
            or getattr(problem, "statement_type", "")
            or ""
        ).strip()
        try:
            contract_status = dict(
                contract_status_getter(
                    route_id,
                    target_statement=target_statement,
                    mutate=mutate,
                )
                or {}
            )
        except Exception:
            return False
        if not bool(contract_status.get("ready")):
            return False
        try:
            from ensemble_prover.mini_session.actions.graph_route_assembly import (
                GraphRouteAssemblyAction,
            )

            has_replayable_bridge = (
                GraphRouteAssemblyAction._route_has_replayable_bridge(contract_status)
            )
        except Exception:
            has_replayable_bridge = bool(
                contract_status.get("deterministic_ready")
                or contract_status.get("assembly_bridge_node_ids")
                or contract_status.get("selected_branch_frame_ids")
            )
        authoring_helper_names: List[str] = []
        if not has_replayable_bridge and bool(contract_status.get("authoring_ready")):
            try:
                authoring_helper_names = GraphRouteAssemblyAction._route_helper_names(
                    graph,
                    [
                        str(node_id or "").strip()
                        for node_id in list(
                            contract_status.get("dependency_node_ids") or []
                        )
                        if str(node_id or "").strip()
                    ],
                    dossier,
                )
            except Exception:
                authoring_helper_names = []
        if not has_replayable_bridge and not authoring_helper_names:
            return False
        signature_getter = getattr(graph, "route_dependency_signature_hash", None)
        if not callable(signature_getter):
            return False
        try:
            current_signature_hash = str(signature_getter(route_id) or "").strip()
        except Exception:
            return False
        if not current_signature_hash:
            return False
        failed_signature_hash = str(
            metadata.get("route_root_assembly_author_failed_signature_hash") or ""
        ).strip()
        if failed_signature_hash and failed_signature_hash == current_signature_hash:
            return False
        ready_signature_hash = str(
            metadata.get("route_root_tactic_authoring_ready_signature_hash") or ""
        ).strip()
        ready_hash = str(
            metadata.get("route_root_tactic_authoring_ready_hash") or ""
        ).strip()
        return bool(ready_hash and ready_signature_hash == current_signature_hash)

    def _frontier_candidate_available_for_work_item(
        self,
        work_item: Any,
        action_id: str,
        *,
        ignore_budget: bool = False,
        mutate: bool = True,
    ) -> bool:
        if not self._selected_work_action_compatible(
            action_id,
            self._work_item_to_record(work_item),
        ):
            return False
        work_type = str(self._work_item_field(work_item, "work_type", "") or "")
        if str(action_id or "") == "child_closure":
            # A retained result-only tail legitimately keeps the shared Lean
            # lock to prevent unsafe overlap.  While it does, deterministic
            # child work is not executable and must not suppress independent
            # root authoring.  The item remains durable and becomes available
            # again immediately when the real owner releases the capability.
            if self._work_item_waits_for_shared_lean(work_item):
                return False
        action = self.registered_action(action_id)
        if action is None:
            return False
        budget = self.budgets.get(action.id)
        if not ignore_budget and budget is not None and budget.exhausted():
            return False
        if work_type == "route_replan":
            serviceable, _status = self._route_replan_serviceability_status(
                self._work_item_to_record(work_item)
            )
            if not serviceable:
                return False
        if (
            work_type == "assemble_route"
            and str(action_id or "").startswith("conversation_turn")
            and not self._assemble_route_authoring_ready(work_item, mutate=mutate)
        ):
            return False
        if (
            work_type == "root_repair"
            and str(action_id or "").startswith("conversation_turn")
            and not self._unscoped_root_authoring_allowed(mutate=mutate)[0]
        ):
            return False
        if (
            str(action_id or "").startswith("conversation_turn")
            and work_type == "target_integrity_adjudication"
            and self._frontier_item_targets_dossier_graph_node(work_item)
            and not self._frontier_item_executable_statement(work_item)
        ):
            return False
        if (
            str(action_id or "").startswith("conversation_turn")
            and work_type
            in {
                "formalize_claim",
                "formalize_missing_obligation",
                "prove_claim_variant",
                "mine_missing_obligation",
                "route_replan",
                "target_integrity_adjudication",
                "materialize_replay_source",
            }
            and not bool(
                self._work_item_field(
                    work_item,
                    "formalization_required",
                    False,
                )
            )
            and not self._frontier_item_executable_statement(work_item)
        ):
            return False
        return True

    def _frontier_candidate_serviceable_for_recovery(
        self,
        work_item: Any,
        action_id: str,
        *,
        ignore_model_call_deferred: bool = False,
    ) -> bool:
        if (
            not ignore_model_call_deferred
            and self._frontier_action_key(work_item, action_id)
            in self.model_call_deferred_frontier_action_keys
        ):
            return False
        if not self._frontier_candidate_available_for_work_item(
            work_item,
            action_id,
            ignore_budget=True,
        ):
            return False
        action = self.registered_action(action_id)
        if action is None:
            return False
        saved_target = self.selected_work_item
        saved_action_id = self.selected_work_item_action_id
        saved_record = dict(self.selected_work_item_record)
        missing = object()
        saved_graph_remaining = getattr(
            self,
            "graph_recursive_decompose_remaining",
            missing,
        )
        recursive_pool_attr = str(getattr(action, "budget_attr", "") or "").strip()
        saved_recursive_remaining = (
            getattr(self, recursive_pool_attr, missing)
            if recursive_pool_attr
            else missing
        )
        budget = self.budgets.get(action_id)
        saved_max_total_seconds = (
            float(budget.max_total_seconds) if budget is not None else None
        )
        self._suppress_dossier_metric_recording += 1
        try:
            if not self._set_selected_work_item(work_item, action.id):
                return False
            # Some deterministic actions require a full operation quantum even
            # while their cumulative budget is numerically live. Recovery
            # probes temporarily fund that exact threshold so the selector can
            # distinguish underfunding from genuinely inapplicable work. The
            # bounded recovery grant below performs the durable top-up.
            required_budget_s = self._frontier_required_dispatch_budget_s(
                action,
                work_item,
            )
            if (
                budget is not None
                and budget.scope in {"session", "proof_work"}
                and budget.max_total_seconds > 0.0
                and required_budget_s > 0.0
                and budget.max_total_seconds - budget.total_seconds < required_budget_s
            ):
                budget.max_total_seconds = (
                    float(budget.total_seconds) + required_budget_s
                )
            if self._is_graph_recursive_action(action):
                current = int(
                    getattr(self, "graph_recursive_decompose_remaining", 0) or 0
                )
                self.graph_recursive_decompose_remaining = max(1, current)
            if recursive_pool_attr:
                current = int(getattr(self, recursive_pool_attr, 0) or 0)
                setattr(self, recursive_pool_attr, max(1, current))
            return self._safe_is_applicable(
                action,
                context="no_applicable_recovery_probe",
            )
        finally:
            self._suppress_dossier_metric_recording = max(
                0,
                int(self._suppress_dossier_metric_recording or 0) - 1,
            )
            self.selected_work_item = saved_target
            self.selected_work_item_action_id = saved_action_id
            self.selected_work_item_record = saved_record
            if budget is not None and saved_max_total_seconds is not None:
                budget.max_total_seconds = saved_max_total_seconds
            if saved_graph_remaining is missing:
                try:
                    delattr(self, "graph_recursive_decompose_remaining")
                except AttributeError:
                    pass
            else:
                self.graph_recursive_decompose_remaining = saved_graph_remaining
            if recursive_pool_attr:
                if saved_recursive_remaining is missing:
                    try:
                        delattr(self, recursive_pool_attr)
                    except AttributeError:
                        pass
                else:
                    setattr(
                        self,
                        recursive_pool_attr,
                        saved_recursive_remaining,
                    )

    def _frontier_required_dispatch_budget_s(
        self,
        action: Any,
        work_item: Any,
    ) -> float:
        getter = getattr(action, "required_dispatch_budget_s", None)
        if not callable(getter):
            return 0.0
        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        try:
            try:
                parameters = inspect.signature(getter).parameters
            except (TypeError, ValueError):
                parameters = {}
            accepts_session = "session" in parameters or any(
                parameter.kind is inspect.Parameter.VAR_KEYWORD
                for parameter in parameters.values()
            )
            if accepts_session:
                required = getter(work_type, session=self)
            else:
                # Third-party/legacy actions implement the original
                # one-argument scheduler quotation contract.
                required = getter(work_type)
            return max(0.0, float(required or 0.0))
        except (TypeError, ValueError):
            return 0.0

    def _serviceable_no_applicable_recovery_action_ids(
        self,
        action_ids: Sequence[str],
        *,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> Set[str]:
        wanted = {
            str(action_id or "").strip()
            for action_id in action_ids
            if str(action_id or "").strip()
        }
        if not wanted:
            return set()
        scoped_record = dict(selected_work_record or {})
        found: Set[str] = set()
        for route_work_item in self._ready_root_route_assembly_work_items():
            if scoped_record and not self._frontier_work_item_matches_record(
                route_work_item,
                scoped_record,
            ):
                continue
            for candidate_id in self._ready_root_route_drain_candidate_ids(
                route_work_item,
                ignore_budget=True,
            ):
                if candidate_id not in wanted or candidate_id in found:
                    continue
                if self._frontier_candidate_serviceable_for_recovery(
                    route_work_item,
                    candidate_id,
                ):
                    found.add(candidate_id)
                    if found == wanted:
                        return found
        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        frontier_offset = 0
        for _frontier_page in range(40):
            frontier_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=False,
            )
            if not frontier_items:
                break
            for work_item in frontier_items:
                if scoped_record and not self._frontier_work_item_matches_record(
                    work_item,
                    scoped_record,
                ):
                    continue
                work_type = str(self._work_item_field(work_item, "work_type", "") or "")
                if not work_type:
                    continue
                for candidate_id in self._frontier_candidate_ids_for_work_item(
                    work_item
                ):
                    if candidate_id not in wanted or candidate_id in found:
                        continue
                    if self._frontier_candidate_serviceable_for_recovery(
                        work_item,
                        candidate_id,
                    ):
                        found.add(candidate_id)
                        if found == wanted:
                            return found
            if not offset_supported:
                break
            frontier_offset += len(frontier_items)
        return found

    def _deferred_only_no_applicable_recovery_action_ids(
        self,
        action_ids: Sequence[str],
        *,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> Set[str]:
        """Return actions that would be serviceable except for model-call deferral."""

        wanted = {
            str(action_id or "").strip()
            for action_id in action_ids
            if str(action_id or "").strip()
        }
        if not wanted:
            return set()
        self._unretire_wall_exhausted_provider_lanes()
        scoped_record = dict(selected_work_record or {})
        found: Set[str] = set()
        if not scoped_record:
            for action_id in wanted:
                if action_id not in self.model_call_deferred_static_action_ids:
                    continue
                retryable, metadata = self._model_call_deferred_static_action_retryable(
                    action_id
                )
                selector_retry = bool(
                    str(metadata.get("scoped_failure_reason") or "").strip()
                    == "mini_selector_infrastructure_exception"
                )
                if retryable and (
                    selector_retry
                    or self._active_repair_lane_owns_action(
                        action_id,
                        metadata,
                    )
                    or self._static_action_serviceable_for_recovery(
                        action_id,
                        ignore_model_call_deferred=True,
                    )
                ):
                    found.add(action_id)
                    if found == wanted:
                        return found
        for route_work_item in self._ready_root_route_assembly_work_items():
            if scoped_record and not self._frontier_work_item_matches_record(
                route_work_item,
                scoped_record,
            ):
                continue
            for candidate_id in self._ready_root_route_drain_candidate_ids(
                route_work_item,
                ignore_budget=True,
            ):
                if candidate_id not in wanted or candidate_id in found:
                    continue
                action_key = self._model_call_deferred_frontier_key_for_work_item(
                    route_work_item,
                    candidate_id,
                )
                if action_key is None:
                    continue
                if self._frontier_candidate_serviceable_for_recovery(
                    route_work_item,
                    candidate_id,
                    ignore_model_call_deferred=True,
                ):
                    found.add(candidate_id)
                    if found == wanted:
                        return found
        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        frontier_offset = 0
        for _frontier_page in range(40):
            frontier_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=False,
            )
            if not frontier_items:
                break
            for work_item in frontier_items:
                if scoped_record and not self._frontier_work_item_matches_record(
                    work_item,
                    scoped_record,
                ):
                    continue
                work_type = str(self._work_item_field(work_item, "work_type", "") or "")
                if not work_type:
                    continue
                for candidate_id in self._frontier_candidate_ids_for_work_item(
                    work_item
                ):
                    if candidate_id not in wanted or candidate_id in found:
                        continue
                    action_key = self._model_call_deferred_frontier_key_for_work_item(
                        work_item,
                        candidate_id,
                    )
                    if action_key is None:
                        continue
                    if self._frontier_candidate_serviceable_for_recovery(
                        work_item,
                        candidate_id,
                        ignore_model_call_deferred=True,
                    ):
                        found.add(candidate_id)
                        if found == wanted:
                            return found
            if not offset_supported:
                break
            frontier_offset += len(frontier_items)
        return found

    def _release_stale_no_applicable_recovery_suppressors(
        self,
        action_ids: Sequence[str],
    ) -> Dict[str, Any]:
        """Release retryable skip-only frontier suppressors for live work.

        Recovery probes intentionally ignore action budgets so they can find
        work that would become dispatchable after a bounded top-up. If the
        probed action is already budget-serviceable, a previous skip marker can
        be the only thing preventing dispatch. Release only skip markers here;
        consumed action keys stay terminal until new evidence/budget arrives.
        """

        wanted = {
            str(action_id or "").strip()
            for action_id in action_ids
            if str(action_id or "").strip()
        }
        if not wanted or (
            not self.skipped_frontier_work_keys
            and not self.skipped_frontier_action_keys
        ):
            return {
                "released_work_keys": 0,
                "released_action_keys": 0,
                "released_action_ids": [],
            }

        released_work_keys: Set[Tuple[str, str, str, str, str]] = set()
        released_action_keys: Set[Tuple[str, str, str, str, str, str]] = set()
        released_action_ids: Set[str] = set()

        def consider_candidate(work_item: Any, candidate_id: str) -> None:
            action_id = str(candidate_id or "").strip()
            if not action_id or action_id not in wanted:
                return
            work_key = self._frontier_work_key(work_item)
            action_key = self._frontier_action_key(work_item, action_id)
            if action_key in self.consumed_frontier_action_keys:
                return
            if (
                work_key not in self.skipped_frontier_work_keys
                and action_key not in self.skipped_frontier_action_keys
            ):
                return
            if not self._frontier_candidate_serviceable_for_recovery(
                work_item,
                action_id,
            ):
                return
            if work_key in self.skipped_frontier_work_keys:
                self.skipped_frontier_work_keys.discard(work_key)
                released_work_keys.add(work_key)
            if action_key in self.skipped_frontier_action_keys:
                self.skipped_frontier_action_keys.discard(action_key)
                released_action_keys.add(action_key)
            released_action_ids.add(action_id)

        for route_work_item in self._ready_root_route_assembly_work_items():
            for candidate_id in self._ready_root_route_drain_candidate_ids(
                route_work_item,
                ignore_budget=True,
            ):
                consider_candidate(route_work_item, candidate_id)

        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        frontier_offset = 0
        for _frontier_page in range(40):
            frontier_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=False,
            )
            if not frontier_items:
                break
            for work_item in frontier_items:
                work_type = str(self._work_item_field(work_item, "work_type", "") or "")
                if not work_type:
                    continue
                for candidate_id in self._frontier_candidate_ids_for_work_item(
                    work_item
                ):
                    consider_candidate(work_item, candidate_id)
            if not offset_supported:
                break
            frontier_offset += len(frontier_items)

        return {
            "released_work_keys": len(released_work_keys),
            "released_action_keys": len(released_action_keys),
            "released_action_ids": sorted(released_action_ids),
        }

    def _retain_materialization_pending_action_logical_keys(self) -> None:
        pending_action_keys = set(
            getattr(self, "materialization_pending_frontier_action_keys", set())
            or set()
        )
        pending_logical_keys = set(
            getattr(self, "materialization_pending_frontier_logical_keys", set())
            or set()
        )
        if not pending_action_keys or not pending_logical_keys:
            self.materialization_pending_frontier_action_logical_keys.clear()
            return
        current = dict(
            getattr(
                self,
                "materialization_pending_frontier_action_logical_keys",
                {},
            )
            or {}
        )
        self.materialization_pending_frontier_action_logical_keys = {
            action_key: logical_key
            for action_key, logical_key in current.items()
            if action_key in pending_action_keys and logical_key in pending_logical_keys
        }

    def _release_materialization_pending_recovery_suppressors(
        self,
        action_ids: Sequence[str],
    ) -> Dict[str, Any]:
        """Release one-shot suppressors for pending formalization materialization."""

        pending_logical_keys = set(
            getattr(self, "materialization_pending_frontier_logical_keys", set())
            or set()
        )
        pending_action_keys = set(
            getattr(self, "materialization_pending_frontier_action_keys", set())
            or set()
        )
        pending_action_logical_keys = dict(
            getattr(
                self,
                "materialization_pending_frontier_action_logical_keys",
                {},
            )
            or {}
        )
        wanted_action_ids = {
            str(action_id or "").strip()
            for action_id in action_ids
            if str(action_id or "").strip()
        }
        if not pending_logical_keys or not pending_action_keys:
            return {
                "released_action_keys": 0,
                "released_action_ids": [],
                "released_logical_keys": 0,
                "budget_grants": {},
            }
        if not wanted_action_ids:
            return {
                "released_action_keys": 0,
                "released_action_ids": [],
                "released_logical_keys": 0,
                "budget_grants": {},
            }
        legacy_recovered_logical_keys = set(
            getattr(
                self,
                "materialization_pending_no_applicable_recovery_logical_keys",
                set(),
            )
            or set()
        )
        recovery_counts = dict(
            getattr(
                self,
                "materialization_pending_no_applicable_recovery_counts",
                {},
            )
            or {}
        )
        for logical_key in legacy_recovered_logical_keys:
            recovery_counts.setdefault(logical_key, 1)
        max_recoveries = max(
            1,
            int(self.max_materialization_pending_no_applicable_recoveries or 1),
        )
        eligible_logical_keys = {
            logical_key
            for logical_key in pending_logical_keys
            if int(recovery_counts.get(logical_key, 0) or 0) < max_recoveries
        }
        if not eligible_logical_keys:
            return {
                "released_action_keys": 0,
                "released_action_ids": [],
                "released_logical_keys": 0,
                "budget_grants": {},
            }
        released_action_keys: Set[Tuple[str, str, str, str, str, str]] = set()
        released_work_keys: Set[Tuple[str, str, str, str, str]] = set()
        released_action_ids: Set[str] = set()
        released_logical_keys: Set[Tuple[str, str, str, str, str]] = set()
        budget_grants: Dict[str, Dict[str, Any]] = {}
        for action_key in pending_action_keys:
            logical_key = pending_action_logical_keys.get(action_key)
            if logical_key not in eligible_logical_keys:
                continue
            action_id = str(action_key[-1] if action_key else "" or "").strip()
            if action_id not in wanted_action_ids:
                continue
            action = self.registered_action(action_id)
            if action is None:
                continue
            if action_id.startswith("conversation_turn") and not bool(
                self.conversation_budget_topups_enabled
            ):
                continue
            self.skipped_frontier_action_keys.discard(action_key)
            work_key = tuple(action_key[:5])
            if work_key in self.skipped_frontier_work_keys:
                self.skipped_frontier_work_keys.discard(work_key)
                released_work_keys.add(work_key)
            released_action_keys.add(action_key)
            released_action_ids.add(action_id)
            released_logical_keys.add(logical_key)
            budget = self.budgets.get(action_id)
            if budget is None or not budget.exhausted():
                continue
            old_max = int(budget.max_invocations)
            old_invocations = int(budget.invocations)
            budget.max_invocations = max(old_max + 1, old_invocations + 1)
            granted_seconds = 0.0
            if (
                budget.max_total_seconds > 0
                and budget.total_seconds >= budget.max_total_seconds
            ):
                estimate = float(getattr(action, "cost_estimate_s", 0.0) or 0.0)
                granted_seconds = max(30.0, max(1.0, estimate))
                budget.max_total_seconds = float(budget.total_seconds) + granted_seconds
            prompt_turn_budget_granted = self._sync_conversation_prompt_budget(
                action_id,
                min_turn_budget=int(budget.max_invocations),
            )
            budget_grants[action_id] = {
                "old_max_invocations": old_max,
                "new_max_invocations": int(budget.max_invocations),
                "invocations": old_invocations,
                "granted_invocations": max(
                    0,
                    int(budget.max_invocations) - max(old_max, old_invocations),
                ),
                "granted_prompt_turn_budget": int(prompt_turn_budget_granted),
                "granted_seconds": round(granted_seconds, 4),
            }
        if not released_action_keys:
            return {
                "released_action_keys": 0,
                "released_action_ids": [],
                "released_work_keys": 0,
                "released_logical_keys": 0,
                "budget_grants": {},
            }
        self.materialization_pending_no_applicable_recovery_logical_keys.update(
            released_logical_keys
        )
        for logical_key in released_logical_keys:
            self.materialization_pending_no_applicable_recovery_counts[logical_key] = (
                int(recovery_counts.get(logical_key, 0) or 0) + 1
            )
        self.materialization_pending_frontier_action_keys.difference_update(
            released_action_keys
        )
        self.materialization_pending_frontier_logical_keys.difference_update(
            released_logical_keys
        )
        self._retain_materialization_pending_action_logical_keys()
        return {
            "released_action_keys": len(released_action_keys),
            "released_action_ids": sorted(released_action_ids),
            "released_work_keys": len(released_work_keys),
            "released_logical_keys": len(released_logical_keys),
            "budget_grants": budget_grants,
        }

    def _model_call_deferred_metadata_retryable(
        self,
        metadata: Dict[str, Any],
    ) -> bool:
        kind = str(metadata.get("llm_failure_kind") or "").strip()
        scoped_reason = str(metadata.get("scoped_failure_reason") or "").strip()
        scope = str(metadata.get("llm_failure_scope") or "").strip()
        retryable = bool(metadata.get("llm_retryable"))
        terminal_reason = str(metadata.get("terminal_failure_reason") or "").strip()
        if terminal_reason:
            return False
        if (
            bool(metadata.get("recovered_finalizer_provider_receipt_activated"))
            and retryable
            and scope == "scoped"
        ):
            # This provider segment failed after an earlier segment completed;
            # aggregate zero-provider classification is intentionally false.
            # The typed recovered receipt still owns one bounded release.
            return True
        if scope == "scoped" and scoped_reason in {
            "recursive_contract_identity_infrastructure_unknown",
            "recursive_contract_identity_service_unavailable",
        }:
            # These controller yields carry a durable, monotonically bounded
            # identity-service counter rather than an LLM transport retry bit.
            # Release the deferred action once so the driver can publish its
            # second, charged service-exhausted result in this same session.
            return True
        if kind == "llm_turn_elapsed_budget_exhausted" and retryable:
            return True
        if kind == "provider_dispatch_attempt_limit_exhausted" and retryable:
            # The conversation deliberately yielded after one provider
            # request plus one transport retry.  Release the exact deferred
            # action through the ordinary bounded recovery lane so other
            # mathematical routes receive a scheduler quantum first.
            return True
        if kind == "llm_provider_quantum_exhausted" and retryable:
            return True
        if kind in _RETRYABLE_FINAL_NO_TOOLS_FAILURE_KINDS and retryable:
            # The provider completed a paid turn but returned no usable proof
            # artifact. The producer explicitly classifies these protocol
            # outcomes as retryable; release only through the existing bounded
            # deferred-action ledger so another proof family receives a
            # scheduler quantum first.
            return True
        if (
            kind == "llm_provider_cumulative_wall_exhausted"
            or scoped_reason == "llm_provider_cumulative_wall_exhausted"
        ):
            # This exact target/environment lane spent its absolute wall
            # lease. Releasing it cannot dispatch more provider work because
            # the persisted lease is already exhausted; only a new lane
            # identity created by durable formal evidence may run again.
            return False
        if kind == "mini_reasoning_capability_unavailable" and retryable:
            # Capability discovery is a pre-provider admission check.  A
            # transient catalog outage must rotate through the same bounded
            # deferred-action recovery lane as transport infrastructure; if
            # this is the only proof lane, no-applicable recovery releases it
            # instead of converting the safe yield into a terminal session.
            return True
        if (
            kind == "lean_verifier_infrastructure_unavailable"
            and retryable
            and scope == "scoped"
        ):
            return True
        if (
            kind == "recursive_helper_zero_provider_failure"
            and retryable
            and scope == "scoped"
            and scoped_reason == "recursive_helper_zero_provider_failure"
        ):
            # A recursive child failed before any provider response.  Its
            # mathematical reservation is refunded (or, for a resumed frame,
            # retained), while the exact frontier/action identity is deferred
            # through the ordinary bounded recovery ledger so another action
            # receives a scheduler quantum first.
            return True
        if (
            kind == "graph_statement_typecheck_inconclusive"
            and retryable
            and scope == "scoped"
        ):
            # Mandatory pre-provider Lean validation is infrastructure work,
            # not a failed mathematical turn. The ordinary deferred-action
            # recovery gives the exact target a bounded later retry after
            # other proof families have had a chance to run.
            return True
        if (
            kind == "recursive_target_typecheck_inconclusive"
            and retryable
            and scope == "scoped"
        ):
            # Same policy for generated proof-state children: never call a
            # provider before elaboration, but retain bounded recovery after
            # the scheduler explores other deterministic work.
            return True
        if (
            scoped_reason == "llm_retry_deadline_exhausted"
            and retryable
            and scope == "scoped"
        ):
            # The retry bit here means a later scheduler quantum, not another
            # attempt inside the already-exhausted composite call.  Release
            # it only through the existing bounded no-applicable recovery,
            # after other proof families have been given their turns.
            return True
        if kind in {
            "llm_cost_budget_reserved_capacity",
            "llm_cost_budget_request_capacity",
            "llm_cost_budget_retry_capacity",
            "llm_cost_budget_exhausted",
            "llm_cost_budget_unknown_pricing",
        }:
            return False
        if self._persistent_infrastructure_defer(metadata):
            return True
        if scoped_reason == "llm_network_error" and (
            retryable or kind in {"transient", "transport"}
        ):
            return True
        if kind == "rate_limit" and retryable and scope == "scoped":
            return True
        if kind.startswith("http_") and retryable and scope == "scoped":
            return True
        return False

    def _action_provider_defer_fingerprints(self, action: Any) -> Set[str]:
        """Return exact serving lanes an action can use for its next call.

        An action with a genuinely different alternative remains schedulable;
        the shared cooldown is not a provider-global or model-family tombstone.
        """

        clients: List[Any] = []
        direct_client = getattr(action, "client", None)
        if direct_client is not None:
            clients.append(direct_client)
        else:
            action_id = str(getattr(action, "id", "") or "").strip()
            defer_family = str(
                getattr(action, "MODEL_CALL_DEFER_FAMILY", "") or ""
            ).strip()
            if action_id == "conversation_turn_refine":
                clients.append(self.refiner_client or self.prover_client)
            elif action_id.startswith("conversation_turn_"):
                clients.append(self.prover_client)
            elif defer_family == "recursive_planner":
                clients.append(self.prover_client)
        fingerprints = {
            provider_serving_fingerprint(client)
            for client in clients
            if client is not None
        }
        return {fingerprint for fingerprint in fingerprints if fingerprint}

    @staticmethod
    def _persistent_infrastructure_defer(metadata: Dict[str, Any]) -> bool:
        """Whether a deferred action is waiting on retryable infrastructure."""

        if not bool(metadata.get("llm_retryable")):
            return False
        if str(metadata.get("terminal_failure_reason") or "").strip():
            return False
        kind = str(metadata.get("llm_failure_kind") or "").strip()
        scoped_reason = str(metadata.get("scoped_failure_reason") or "").strip()
        permanent_kinds = {
            "llm_cost_budget_reserved_capacity",
            "llm_cost_budget_request_capacity",
            "llm_cost_budget_retry_capacity",
            "llm_cost_budget_exhausted",
            "llm_cost_budget_unknown_pricing",
            "invalid_request",
            "configuration_error",
            "config_error",
        }
        permanent_reasons = {
            "llm_cost_budget_exhausted",
            "llm_cost_budget_unknown_pricing",
            "invalid_provider_configuration",
        }
        permanent_kind_token = any(
            token in kind for token in ("configuration", "config")
        )
        if (
            kind in permanent_kinds
            or scoped_reason in permanent_reasons
            or permanent_kind_token
        ):
            return False
        provider_calls_completed = _nonnegative_metadata_int(
            metadata,
            "provider_calls_completed",
        )
        provider_dispatches_started = _nonnegative_metadata_int(
            metadata,
            "provider_dispatches_started",
        )
        cooperative_provider_yield = bool(
            (
                provider_calls_completed > 0
                or metadata.get("provider_finalizer_continuation_exhausted")
            )
            and metadata.get("provider_call_quantum_exhausted")
            and kind
            in {
                "llm_provider_quantum_exhausted",
                "provider_dispatch_attempt_limit_exhausted",
            }
        )
        try:
            provider_defer_ready_at = float(
                metadata.get("provider_defer_ready_at", 0.0) or 0.0
            )
        except (TypeError, ValueError, OverflowError):
            provider_defer_ready_at = 0.0
        failed_dispatch_pre_generation_rejection = bool(
            metadata.get("failed_provider_pre_generation_rejection")
            and kind in {"rate_limit", "http_429"}
            and str(metadata.get("provider_defer_fingerprint") or "").strip()
            and math.isfinite(provider_defer_ready_at)
            and provider_defer_ready_at > 0.0
        )
        zero_provider_failure = bool(
            provider_calls_completed == 0
            and (
                provider_dispatches_started == 0
                or bool(
                    str(metadata.get("provider_defer_fingerprint") or "").strip()
                )
            )
            and (
                metadata.get("zero_provider_failure")
                or (
                    "provider_calls_completed" in metadata
                    and not cooperative_provider_yield
                )
            )
        )
        if (
            kind in _PROVIDER_BLOCKED_FAILURE_KINDS
            or scoped_reason in _PROVIDER_BLOCKED_FAILURE_REASONS
        ):
            return zero_provider_failure
        if failed_dispatch_pre_generation_rejection:
            # Classify the request that actually failed, rather than the
            # cumulative action. Earlier successful tool rounds remain paid,
            # while this authenticated pre-generation refusal retains its
            # provider-scoped wait/retry ownership.
            return True
        if kind in {
            "mini_reasoning_capability_unavailable",
            "lean_verifier_infrastructure_unavailable",
            "lean_tool_infrastructure_retry_pending",
            "mini_action_infrastructure_exception",
        }:
            return True
        if kind in {
            "recursive_helper_zero_provider_failure",
            "graph_statement_typecheck_inconclusive",
            "recursive_target_typecheck_inconclusive",
        }:
            return zero_provider_failure
        if (
            kind == "provider_dispatch_attempt_limit_exhausted"
            and zero_provider_failure
            and not cooperative_provider_yield
        ):
            return True
        # A dispatch the provider never answered evaluated nothing. Whether
        # the request never left (``zero_provider_failure``) or left and timed
        # out before any provider call completed, the model did not see this
        # proof state, so the receipt waits on infrastructure and must not be
        # charged against the bounded semantic retry count for that state.
        # Charging it let a refused transport retry consume both scheduler
        # retries and terminate a run with live work.
        provider_never_answered = bool(
            provider_calls_completed == 0
            and provider_dispatches_started > 0
            and not cooperative_provider_yield
        )
        if provider_never_answered and (
            kind
            in {
                "provider_dispatch_attempt_limit_exhausted",
                "transient",
                "transport",
                "llm_network_error",
                "llm_provider_quantum_exhausted",
                "llm_retry_deadline_exhausted",
            }
            or scoped_reason
            in {"llm_network_error", "llm_retry_deadline_exhausted"}
        ):
            return True
        if not zero_provider_failure:
            return False
        if kind in {
            "transient",
            "transport",
            "rate_limit",
            "llm_network_error",
        }:
            return True
        if kind.startswith("http_"):
            return kind in {
                "http_408",
                "http_409",
                "http_425",
                "http_429",
                "http_500",
                "http_502",
                "http_503",
                "http_504",
            }
        return kind == "llm_retry_deadline_exhausted" or scoped_reason in {
            "llm_network_error",
            "llm_retry_deadline_exhausted",
        }

    def _model_call_deferred_frontier_retry_policy(
        self,
        metadata: Dict[str, Any],
    ) -> Tuple[int, bool]:
        """Return the effective cap and whether infrastructure bypasses it."""

        max_retries = max(
            0,
            int(self.max_model_call_deferred_frontier_retries or 0),
        )
        action_id = str(metadata.get("action_id") or "").strip()
        if self._active_repair_lane_capacity_retryable(action_id, metadata):
            max_retries = max(max_retries, 2)
        if self._recovered_provider_receipt_retry_floor(metadata):
            max_retries = max(max_retries, 1)
        if bool(metadata.get("provider_call_quantum_exhausted")) and (
            _nonnegative_metadata_int(metadata, "provider_calls_completed") > 0
            or bool(metadata.get("provider_finalizer_continuation_exhausted"))
        ):
            max_retries = max(
                max_retries,
                _nonnegative_metadata_int(
                    metadata,
                    "provider_call_quantum_max_retries",
                ),
            )
        return max_retries, self._persistent_infrastructure_defer(metadata)

    @staticmethod
    def _recovered_provider_receipt_retry_floor(
        metadata: Mapping[str, Any],
    ) -> bool:
        return bool(
            metadata.get("recovered_finalizer_provider_receipt_activated")
            or str(metadata.get("provider_defer_fingerprint") or "").strip()
        )

    @staticmethod
    def _provider_defer_receipt_is_ready(metadata: Mapping[str, Any]) -> bool:
        if not str(metadata.get("provider_defer_fingerprint") or "").strip():
            return True
        try:
            ready_at = float(metadata.get("provider_defer_ready_at", 0.0) or 0.0)
        except (TypeError, ValueError, OverflowError):
            return False
        if ready_at <= 0.0:
            return True
        return bool(
            math.isfinite(ready_at)
            and ready_at <= time.time()
        )

    @staticmethod
    def _provider_defer_ready_at(metadata: Mapping[str, Any]) -> float:
        """Return a finite authenticated provider wake time, or zero."""

        if not str(metadata.get("provider_defer_fingerprint") or "").strip():
            return 0.0
        try:
            ready_at = float(metadata.get("provider_defer_ready_at", 0.0) or 0.0)
        except (TypeError, ValueError, OverflowError):
            return 0.0
        return ready_at if math.isfinite(ready_at) and ready_at > 0.0 else 0.0

    def _model_call_deferred_static_retry_limit(
        self,
        action_id: str,
        metadata: Mapping[str, Any],
    ) -> int:
        """Return the bounded release count for one static provider receipt."""

        max_retries = max(
            0,
            int(self.max_model_call_deferred_static_retries or 0),
        )
        if str(metadata.get("provider_defer_fingerprint") or "").strip():
            max_retries = max(max_retries, 1)
        if self._recovered_provider_receipt_retry_floor(metadata):
            max_retries = max(max_retries, 1)
        if self._active_repair_lane_capacity_retryable(action_id, metadata):
            max_retries = max(max_retries, 2)
        if bool(metadata.get("provider_call_quantum_exhausted")) and (
            _nonnegative_metadata_int(metadata, "provider_calls_completed") > 0
            or bool(metadata.get("provider_finalizer_continuation_exhausted"))
        ):
            max_retries = max(
                max_retries,
                _nonnegative_metadata_int(
                    metadata,
                    "provider_call_quantum_max_retries",
                ),
            )
        return max_retries

    def _model_call_deferred_static_retry_entitled(
        self,
        action_id: str,
        metadata: Mapping[str, Any],
    ) -> bool:
        if self._persistent_infrastructure_defer(dict(metadata)):
            return True
        retry_identities = self._model_call_deferred_static_retry_identities(
            action_id
        )
        prior_retries = max(
            (
                int(
                    self.model_call_deferred_static_retry_counts.get(identity, 0)
                    or 0
                )
                for identity in retry_identities
            ),
            default=0,
        )
        return prior_retries < self._model_call_deferred_static_retry_limit(
            action_id,
            metadata,
        )

    def _model_call_deferred_frontier_retry_entitled(
        self,
        action_key: Tuple[str, ...],
        metadata: Mapping[str, Any],
    ) -> bool:
        max_retries, unbounded = self._model_call_deferred_frontier_retry_policy(
            dict(metadata)
        )
        if unbounded:
            return True
        stored_record = dict(metadata.get("selected_work_item_record") or {})
        retry_keys = self._frontier_progress_retry_keys(
            stored_record or None,
            action_key,
        )
        prior_retries = max(
            (
                int(
                    self.model_call_deferred_frontier_retry_counts.get(key, 0)
                    or 0
                )
                for key in retry_keys
            ),
            default=0,
        )
        return prior_retries < max_retries

    @staticmethod
    def _infrastructure_retry_ready_at(metadata: Dict[str, Any]) -> float:
        try:
            ready_at = float(metadata.get("infrastructure_retry_ready_at", 0.0) or 0.0)
        except (TypeError, ValueError):
            return 0.0
        return ready_at if math.isfinite(ready_at) and ready_at > 0.0 else 0.0

    def _persistent_infrastructure_retry_fields(
        self,
        *existing_metadata: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Create the next durable exponential-backoff receipt."""

        prior_attempt = 0
        provider_ready_at = 0.0
        provider_retry_after_s = 0.0
        for record in existing_metadata:
            if not isinstance(record, dict):
                continue
            try:
                prior_attempt = max(
                    prior_attempt,
                    int(record.get("infrastructure_retry_attempt", 0) or 0),
                )
            except (TypeError, ValueError, OverflowError):
                pass
            try:
                candidate_ready_at = float(
                    record.get("provider_defer_ready_at", 0.0) or 0.0
                )
                if math.isfinite(candidate_ready_at):
                    provider_ready_at = max(provider_ready_at, candidate_ready_at)
            except (TypeError, ValueError, OverflowError):
                pass
            try:
                candidate_retry_after_s = float(
                    record.get("provider_defer_retry_after_s", 0.0) or 0.0
                )
                if math.isfinite(candidate_retry_after_s):
                    provider_retry_after_s = max(
                        provider_retry_after_s,
                        candidate_retry_after_s,
                    )
            except (TypeError, ValueError, OverflowError):
                pass
        attempt = prior_attempt + 1
        base_s = max(0.001, float(self.persistent_infrastructure_retry_base_s or 0.0))
        max_s = max(base_s, float(self.persistent_infrastructure_retry_max_s or 0.0))
        exponent = min(30, max(0, attempt - 1))
        delay_s = max(
            min(max_s, base_s * float(2**exponent)),
            provider_retry_after_s,
        )
        ready_at = max(time.time() + delay_s, provider_ready_at)
        return {
            "persistent_infrastructure_retry": True,
            "infrastructure_retry_attempt": attempt,
            "infrastructure_retry_delay_s": delay_s,
            "infrastructure_retry_ready_at": ready_at,
        }

    def _persistent_infrastructure_retry_is_ready(
        self,
        metadata: Dict[str, Any],
    ) -> bool:
        if not self._persistent_infrastructure_defer(metadata):
            return True
        if self._infrastructure_retry_ready_at(metadata) > time.time():
            return False
        if self._lean_capability_blocks_infrastructure_retry(metadata):
            return False
        return True

    def _iter_model_call_deferred_metadata(self) -> Iterable[Dict[str, Any]]:
        for action_id in self.model_call_deferred_static_action_ids:
            metadata = dict(
                self.model_call_deferred_static_action_metadata.get(action_id) or {}
            )
            if self._model_call_deferred_static_receipt_compatible(
                str(action_id or ""),
                metadata,
            ):
                yield metadata
        for action_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
            )
            if self._model_call_deferred_frontier_receipt_compatible(
                action_key,
                metadata,
            ):
                yield metadata

    def _has_waiting_lean_tool_infrastructure_retry(self) -> bool:
        """Return whether an unresolved Lean-tool replay is parked.

        Backoff controls when the exact tool may replay. It does not justify
        retaining a poisoned Lean generation: once a late tail blocks a
        parked replay, recycling immediately makes the eventual replay viable.
        """

        for metadata in self._iter_model_call_deferred_metadata():
            if not self._persistent_infrastructure_defer(metadata):
                continue
            kind = str(metadata.get("llm_failure_kind") or "").strip()
            if kind in _LEAN_TOOL_INFRASTRUCTURE_RETRY_KINDS:
                return True
        return False

    def _lean_tool_retry_runner_recycles(self, metadata: Mapping[str, Any]) -> int:
        try:
            return max(0, int(metadata.get("lean_tool_retry_runner_recycles") or 0))
        except (TypeError, ValueError):
            return 0

    def _has_waiting_lean_tool_retry_requiring_recycle(self) -> bool:
        """Whether a parked Lean replay still authorizes one generation unstick.

        Recycle once to shed a poisoned tail. After that, poll occupancy and
        replay the exact receipt when the lock is free. Further swaps would
        kill a warming environment without dropping the paid lookup.
        """

        for metadata in self._iter_model_call_deferred_metadata():
            if not self._persistent_infrastructure_defer(metadata):
                continue
            kind = str(metadata.get("llm_failure_kind") or "").strip()
            if kind not in _LEAN_TOOL_INFRASTRUCTURE_RETRY_KINDS:
                continue
            if self._lean_tool_retry_runner_recycles(metadata) >= 1:
                continue
            return True
        return False

    def _record_lean_tool_retry_recycle(self) -> None:
        """Count the one unstick recycle against parked Lean-tool receipts."""

        for store in (
            self.model_call_deferred_static_action_metadata,
            self.model_call_deferred_frontier_action_metadata,
        ):
            for metadata in store.values():
                if not isinstance(metadata, dict):
                    continue
                if not self._persistent_infrastructure_defer(metadata):
                    continue
                kind = str(metadata.get("llm_failure_kind") or "").strip()
                if kind not in _LEAN_TOOL_INFRASTRUCTURE_RETRY_KINDS:
                    continue
                metadata["lean_tool_retry_runner_recycles"] = (
                    self._lean_tool_retry_runner_recycles(metadata) + 1
                )

    def _lean_capability_blocks_infrastructure_retry(
        self,
        metadata: Dict[str, Any],
    ) -> bool:
        kind = str(metadata.get("llm_failure_kind") or "").strip()
        if kind not in _LEAN_TOOL_INFRASTRUCTURE_RETRY_KINDS:
            return False
        try:
            return self._shared_lean_capability_occupied()
        except Exception:
            # A failed health probe cannot authorize another Lean dispatch.
            return True

    def _model_call_deferred_frontier_action_retryable(
        self,
        action_key: Tuple[str, str, str, str, str, str],
    ) -> Tuple[bool, Dict[str, Any]]:
        metadata = dict(
            self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
        )
        action_id = str(metadata.get("action_id") or "").strip()
        if not action_id and action_key:
            action_id = str(action_key[-1] or "").strip()
        if not self._model_call_deferred_frontier_receipt_compatible(
            action_key,
            metadata,
        ):
            return False, metadata
        if (
            str(metadata.get("llm_failure_kind") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
            or str(metadata.get("scoped_failure_reason") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
        ):
            return False, metadata
        return (
            self._model_call_deferred_metadata_retryable(metadata)
            or self._active_repair_lane_capacity_retryable(action_id, metadata)
        ), metadata

    @staticmethod
    def _wall_exhausted_receipt(metadata: Mapping[str, Any]) -> bool:
        return (
            str(metadata.get("llm_failure_kind") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
            or str(metadata.get("scoped_failure_reason") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
        )

    def _renew_provider_lanes_instead_of_terminal(self, reason: str) -> bool:
        """Renew retired lanes at a recovery exit that would end the session.

        Every terminal exit of no-applicable recovery is covered, not only
        ``no_serviceable_frontier_work``: the Aug 29 lane-retirement deaths
        left through ``no_recovery_budget_granted`` with the recovery probe
        still listing the retired conversations as serviceable. A renewed lane
        is ordinary selectable work again; this is not a recovery grant, mints
        no turn, and leaves the bounded recovery counter untouched.
        """

        renewed = self._renew_starved_provider_lane_leases(exit_reason=reason)
        if not renewed:
            return False
        self.fallback_actions_attempted = False
        self.max_iterations = max(
            int(self.max_iterations or 0),
            int(self.iteration or 0) + 2,
        )
        self.last_failure_reason = ""
        return True

    def _renew_starved_provider_lane_leases(self, *, exit_reason: str = "") -> Set[str]:
        """Re-open wall-exhausted provider lanes when nothing else can run.

        Exhausting a lane's cumulative provider wall lease retires it from
        *immediate* redispatch so alternate frontier work receives the
        scheduler first. That is the lease's whole purpose; it was never a
        session terminal, and the run's wall-clock and cost governors own
        the decision to stop. When the recovery scan finds no serviceable
        work at all, the retirement would end the session instead. Grant
        every retired lane a fresh lease, drop the spent receipts that the
        release predicates refuse, and let the ordinary selector dispatch the
        lane again. Returns the renewed lane identities.
        """

        retired = {
            str(identity or "").strip()
            for identity in self.provider_turn_retired_lane_identities
            if str(identity or "").strip()
        }
        if not retired:
            return set()
        renewed_action_ids: List[str] = []
        for action in self.actions:
            renew = getattr(action, "renew_provider_lane_lease", None)
            if not callable(renew):
                continue
            try:
                if renew(self, retired):
                    renewed_action_ids.append(str(getattr(action, "id", "") or ""))
            except Exception:
                _LOGGER.debug(
                    "provider lane lease renewal failed for %r",
                    getattr(action, "id", ""),
                    exc_info=True,
                )
        def spent_receipt_for_renewed_lane(metadata: Mapping[str, Any]) -> bool:
            # Only receipts attributed to a lane being renewed (or too old to
            # carry a lane stamp) are spent; a wall receipt owned by a lane
            # that is still retired elsewhere is not this renewal's to drop.
            if not self._wall_exhausted_receipt(metadata):
                return False
            identity = str(metadata.get("provider_turn_lane_identity") or "").strip()
            return not identity or identity in retired

        dropped_receipt_action_ids: List[str] = []
        for action_id in sorted(self.model_call_deferred_static_action_ids):
            metadata = dict(
                self.model_call_deferred_static_action_metadata.get(action_id) or {}
            )
            if not spent_receipt_for_renewed_lane(metadata):
                continue
            self.model_call_deferred_static_action_ids.discard(action_id)
            self.model_call_deferred_static_action_metadata.pop(action_id, None)
            dropped_receipt_action_ids.append(str(action_id))
        for action_key in list(self.model_call_deferred_frontier_action_keys):
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
            )
            if not spent_receipt_for_renewed_lane(metadata):
                continue
            action_id = str(
                metadata.get("action_id") or (action_key[-1] if action_key else "")
            ).strip()
            self.model_call_deferred_frontier_action_keys.discard(action_key)
            self.model_call_deferred_frontier_action_metadata.pop(action_key, None)
            self.consumed_frontier_action_keys.discard(action_key)
            self.skipped_frontier_action_keys.discard(action_key)
            work_record = metadata.get("selected_work_item_record")
            if isinstance(work_record, Mapping) and work_record:
                try:
                    self.skipped_frontier_work_keys.discard(
                        self._frontier_work_key(dict(work_record))
                    )
                except Exception:
                    _LOGGER.debug(
                        "renewal could not resolve frontier work key for %r",
                        action_id,
                        exc_info=True,
                    )
            if action_id:
                # Same bookkeeping as an ordinary frontier release: a paired
                # static guard is cleared only when its own ledger allows.
                self._clear_paired_model_call_deferred_static_guard(
                    action_id,
                    reason="provider_lane_lease_renewed",
                )
            dropped_receipt_action_ids.append(action_id)
        self.provider_turn_retired_lane_identities.difference_update(retired)
        self._increment_dossier_metric(
            "mini_session_provider_lane_lease_renewals",
            len(retired),
        )
        self._record_event(
            {
                "phase": "session_no_applicable_recovery",
                "iteration": self.iteration,
                "stagnation_counter": self.stagnation_counter,
                "recovery_count": self.no_applicable_recovery_count,
                "max_recoveries": self.max_no_applicable_recoveries,
                "recovery_exit_reason": str(exit_reason or ""),
                "renewed_lane_identities": sorted(retired),
                "renewed_action_ids": sorted(dict.fromkeys(renewed_action_ids)),
                "dropped_receipt_action_ids": sorted(
                    dict.fromkeys(dropped_receipt_action_ids)
                ),
                "verdict": "provider_lane_lease_renewed",
            }
        )
        return retired

    def _unretire_wall_exhausted_provider_lanes(self) -> None:
        """Retain exhausted exact-lane receipts across recovery scans.

        Kept as a compatibility seam for callers/tests. A changed target or
        durable formal environment computes a different lane identity and is
        therefore runnable without deleting the spent receipt.
        """

        return None

    def _model_call_deferred_frontier_key_for_work_item(
        self,
        work_item: Any,
        action_id: str,
    ) -> Optional[Tuple[str, str, str, str, str, str]]:
        """Resolve a defer receipt across retry-induced frontier hash churn."""

        current_key = self._frontier_action_key(work_item, action_id)
        if current_key in self.model_call_deferred_frontier_action_keys:
            return current_key
        clean_action_id = str(action_id or "").strip()
        matches = []
        for stored_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(stored_key) or {}
            )
            if str(metadata.get("action_id") or "").strip() != clean_action_id:
                continue
            stored_record = dict(metadata.get("selected_work_item_record") or {})
            if stored_record and self._frontier_work_item_matches_record(
                work_item,
                stored_record,
            ):
                matches.append(stored_key)
        return matches[0] if len(matches) == 1 else None

    @staticmethod
    def _model_call_deferred_target_identity_value(
        record: Mapping[str, Any],
        key: str,
    ) -> str:
        for layer in selected_work_mapping_layers(record):
            value = str(layer.get(key) or "").strip()
            if not value:
                continue
            if key in {"exact_target_statement", "target_statement"}:
                value = " ".join(value.split())
            return value
        return ""

    @staticmethod
    def _model_call_deferred_work_type(record: Mapping[str, Any]) -> str:
        for layer in selected_work_mapping_layers(record):
            work_type = str(layer.get("work_type") or "").strip()
            if work_type:
                return work_type
        return ""

    @staticmethod
    def _model_call_deferred_structural_identity(
        record: Mapping[str, Any],
    ) -> Tuple[str, str]:
        work_type = MiniSession._model_call_deferred_work_type(record)
        keys = (
            "replan_id",
            "obligation_id",
            "claim_id",
            "variant_id",
            "route_id",
            "assembly_id",
            "graph_node_id",
            "node_id",
        )
        for key in keys:
            if work_type == "root_repair" and key in {
                "graph_node_id",
                "node_id",
            }:
                continue
            for layer in selected_work_mapping_layers(record):
                value = str(layer.get(key) or "").strip()
                if value:
                    return key, value
        return "", ""

    def _model_call_deferred_target_identity(
        self,
        record: Mapping[str, Any],
    ) -> Tuple[str, str]:
        aliases = self._model_call_deferred_target_aliases(record)
        return aliases[0] if aliases else ("", "")

    def _model_call_deferred_target_aliases(
        self,
        record: Mapping[str, Any],
    ) -> Tuple[Tuple[str, str], ...]:
        aliases: List[Tuple[str, str]] = []
        for key, canonical_key in (
            (
                "execution_proposition_identity",
                "execution_proposition_identity",
            ),
            ("execution_target_sha256", "execution_target_sha256"),
            ("exact_target_statement", "target_statement"),
            ("target_statement", "target_statement"),
            ("target_hash", "target_hash"),
            ("target_id", "target_id"),
        ):
            value = self._model_call_deferred_target_identity_value(record, key)
            alias = (canonical_key, value)
            if value and alias not in aliases:
                aliases.append(alias)
        return tuple(aliases)

    def _model_call_deferred_work_item_target_match(
        self,
        work_item: Any,
        stored_record: Mapping[str, Any],
    ) -> Optional[bool]:
        """Compare the strongest semantic target identity shared by records."""

        candidate_record = self._work_item_to_record(work_item)
        stored_structural = self._model_call_deferred_structural_identity(stored_record)
        candidate_structural = self._model_call_deferred_structural_identity(
            candidate_record
        )
        for keys in (
            ("execution_proposition_identity",),
            ("execution_target_sha256",),
            ("exact_target_statement", "target_statement"),
            ("target_hash",),
            ("target_id",),
        ):
            stored_values = {
                self._model_call_deferred_target_identity_value(
                    stored_record,
                    key,
                )
                for key in keys
            } - {""}
            candidate_values = {
                self._model_call_deferred_target_identity_value(
                    candidate_record,
                    key,
                )
                for key in keys
            } - {""}
            if stored_values and candidate_values:
                return bool(stored_values & candidate_values)
        structural_compared = bool(
            any(stored_structural)
            and any(candidate_structural)
            and stored_structural[0] == candidate_structural[0]
        )
        if structural_compared and stored_structural != candidate_structural:
            return False
        return True if structural_compared else None

    def _model_call_deferred_static_action_blocks_work_item(
        self,
        action_id: str,
        work_item: Any,
    ) -> bool:
        """Return whether a family defer receipt applies to this target.

        Infrastructure failures remain action-family wide. By contrast, a
        paid turn that completed with an empty final response only says that
        the selected mathematical target should take a bounded cooldown. It
        must not suppress a distinct target that has never been attempted.
        """

        clean = str(action_id or "").strip()
        if not self._model_call_deferred_static_action_effective(clean):
            return False
        metadata = dict(
            self.model_call_deferred_static_action_metadata.get(clean) or {}
        )
        if str(metadata.get("llm_failure_kind") or "").strip() not in (
            _RETRYABLE_FINAL_NO_TOOLS_FAILURE_KINDS
        ):
            return True
        stored_record = dict(metadata.get("selected_work_item_record") or {})
        if not stored_record or work_item is None:
            # Legacy receipts lack enough information to prove that a new
            # target is distinct, so retain their conservative family guard.
            return True
        # Delegate through the full record matcher so a semantically equal
        # proposition attached to a different operation (for example
        # root_repair versus prove_claim_variant) is not conflated.
        return self._frontier_work_item_matches_record(work_item, stored_record)

    def _model_call_deferred_static_action_effective(
        self,
        action_id: str,
    ) -> bool:
        """Whether a stored static defer still owns current mathematical work."""

        clean = str(action_id or "").strip()
        if clean not in self.model_call_deferred_static_action_ids:
            return False
        metadata = dict(
            self.model_call_deferred_static_action_metadata.get(clean) or {}
        )
        return self._model_call_deferred_static_receipt_compatible(
            clean,
            metadata,
        )

    def _model_call_deferred_static_action_retryable(
        self,
        action_id: str,
    ) -> Tuple[bool, Dict[str, Any]]:
        clean = str(action_id or "").strip()
        metadata = dict(
            self.model_call_deferred_static_action_metadata.get(clean) or {}
        )
        if not self._model_call_deferred_static_receipt_compatible(
            clean,
            metadata,
        ):
            return False, metadata
        if (
            str(metadata.get("llm_failure_kind") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
            or str(metadata.get("scoped_failure_reason") or "").strip()
            == "llm_provider_cumulative_wall_exhausted"
        ):
            return False, metadata
        return (
            self._model_call_deferred_metadata_retryable(metadata)
            or self._active_repair_lane_capacity_retryable(clean, metadata)
        ), metadata

    def _active_repair_lane_owns_action(
        self,
        action_id: str,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> bool:
        """Whether an exact pending repair owns this conversation action."""

        clean = str(action_id or "").strip()
        if not clean:
            return False
        ticket = self.pending_repair_ticket
        if (
            ticket is None
            or not str(getattr(ticket, "proof", "") or "").strip()
            or bool(getattr(ticket, "exhausted", False))
        ):
            return False
        if clean not in {
            str(candidate or "").strip()
            for candidate in self._conversation_action_ids_for_repair(
                str(getattr(ticket, "source_action_id", "") or "")
            )
            if str(candidate or "").strip()
        }:
            return False
        stored_record = dict((metadata or {}).get("selected_work_item_record") or {})
        if not stored_record:
            return True
        ticket_record = self._selected_work_record_from_repair_ticket(
            ticket,
            action_id=clean,
        )
        return bool(
            ticket_record
            and self._frontier_work_item_matches_record(
                ticket_record,
                stored_record,
            )
        )

    def _active_repair_lane_capacity_retryable(
        self,
        action_id: str,
        metadata: Mapping[str, Any],
    ) -> bool:
        """Give a lone repair one bounded retry after transient capacity."""

        if not self._active_repair_lane_owns_action(action_id, metadata):
            return False
        if str(metadata.get("terminal_failure_reason") or "").strip():
            return False
        return str(metadata.get("llm_failure_kind") or "").strip() in {
            "llm_cost_budget_reserved_capacity",
            "llm_cost_budget_request_capacity",
            "llm_cost_budget_retry_capacity",
        }

    def _model_call_deferred_static_retry_identity(self, action_id: str) -> str:
        return self._model_call_deferred_static_retry_identities(action_id)[0]

    def _model_call_deferred_static_retry_identities(
        self,
        action_id: str,
    ) -> Tuple[str, ...]:
        clean = str(action_id or "").strip()
        metadata = dict(
            self.model_call_deferred_static_action_metadata.get(clean) or {}
        )
        selected_record = dict(metadata.get("selected_work_item_record") or {})
        selected_work_type = self._model_call_deferred_work_type(selected_record)
        retry_keys = self._frontier_progress_retry_keys(
            selected_record or None,
            ("static", selected_work_type, "", "", "", clean),
        )
        return tuple(
            "semantic:"
            + hashlib.sha256(
                json.dumps(
                    retry_key,
                    separators=(",", ":"),
                    ensure_ascii=True,
                ).encode("utf-8")
            ).hexdigest()
            for retry_key in retry_keys
        )

    def _migrate_model_call_deferred_static_retry_count(
        self,
        action_id: str,
    ) -> tuple[str, int]:
        clean = str(action_id or "").strip()
        retry_identities = self._model_call_deferred_static_retry_identities(clean)
        retry_identity = retry_identities[0]
        prior_retries = max(
            int(self.model_call_deferred_static_retry_counts.get(clean, 0) or 0),
            int(
                self.model_call_deferred_static_retry_counts.get(
                    retry_identity,
                    0,
                )
                or 0
            ),
        )
        if prior_retries > 0:
            for alias_identity in retry_identities:
                self.model_call_deferred_static_retry_counts[alias_identity] = max(
                    prior_retries,
                    int(
                        self.model_call_deferred_static_retry_counts.get(
                            alias_identity,
                            0,
                        )
                        or 0
                    ),
                )
        if retry_identity != clean:
            self.model_call_deferred_static_retry_counts.pop(clean, None)
        return retry_identity, prior_retries

    def _model_call_deferred_recovery_action_ids(self) -> Tuple[str, ...]:
        action_ids: Set[str] = {
            str(action_id or "").strip()
            for action_id in self.model_call_deferred_static_action_ids
            if str(action_id or "").strip()
            and self._model_call_deferred_static_receipt_compatible(
                str(action_id or "").strip(),
                dict(
                    self.model_call_deferred_static_action_metadata.get(
                        action_id
                    )
                    or {}
                ),
            )
        }
        for action_key in self.model_call_deferred_frontier_action_keys:
            metadata = dict(
                self.model_call_deferred_frontier_action_metadata.get(action_key) or {}
            )
            if not self._model_call_deferred_frontier_receipt_compatible(
                action_key,
                metadata,
            ):
                continue
            action_id = str(metadata.get("action_id") or "").strip()
            if not action_id and action_key:
                action_id = str(action_key[-1] or "").strip()
            if action_id:
                action_ids.add(action_id)
        return tuple(sorted(action_ids))

    def _model_call_deferred_static_receipt_compatible(
        self,
        action_id: str,
        metadata: Mapping[str, Any],
    ) -> bool:
        """Whether scoped static metadata still names current target work."""

        selected_record = metadata.get("selected_work_item_record")
        if not isinstance(selected_record, Mapping) or not selected_record:
            return True
        record = dict(selected_record)
        return self._model_call_deferred_frontier_receipt_compatible(
            self._frontier_action_key(record, action_id, probe=True),
            metadata,
        )

    def _model_call_deferred_frontier_receipt_compatible(
        self,
        action_key: Tuple[str, str, str, str, str, str],
        metadata: Mapping[str, Any],
    ) -> bool:
        """Whether a restored frontier receipt names a dispatchable mapping."""

        action_id = str(metadata.get("action_id") or "").strip()
        if not action_id and action_key:
            action_id = str(action_key[-1] or "").strip()
        selected_record = metadata.get("selected_work_item_record")
        if not action_id:
            return False
        record = (
            dict(selected_record)
            if isinstance(selected_record, Mapping)
            else {}
        )
        if record and action_id not in set(
            self._frontier_candidate_ids_for_work_item(record)
        ):
            return False
        work_type = (
            self._model_call_deferred_work_type(record)
            if record
            else str(action_key[1] if len(action_key) > 1 else "").strip()
        )
        if record and work_type == "root_repair":
            root_work = self._conversation_semantic_work_item(action_id)
            if root_work is not None and self._frontier_work_item_matches_record(
                root_work,
                record,
            ):
                return True
        structural_target_requires_selected_authority = False
        if record:
            liveness = self.selected_work_graph_liveness_status(
                record,
                mutate=False,
            )
            if not bool(liveness.get("live", True)):
                return False
            primary_target_ids: Set[str] = set()
            for layer in selected_work_mapping_layers(record):
                _target_work_type, target_id = (
                    self._graph_repair_record_target_key(dict(layer))
                )
                if target_id:
                    primary_target_ids.add(target_id)
                    break
            dossier = getattr(self, "dossier", None)
            graph = (
                getattr(dossier, "proof_graph", None)
                if dossier is not None
                else None
            )
            graph_nodes = getattr(graph, "nodes", {}) if graph is not None else {}
            if primary_target_ids and isinstance(graph_nodes, dict) and any(
                target_id in graph_nodes for target_id in primary_target_ids
            ):
                return True
            proof_nodes = getattr(
                getattr(self, "proof_state", None),
                "nodes",
                {},
            )
            if isinstance(proof_nodes, dict):
                terminal_statuses = {
                    "closed",
                    "failed",
                    "obsolete",
                    "proved",
                    "rejected",
                    "solved",
                    "superseded",
                }
                for target_id in primary_target_ids:
                    node = proof_nodes.get(target_id)
                    if node is None:
                        continue
                    status = str(
                        self._work_item_field(node, "status", "") or ""
                    ).strip()
                    return status not in terminal_statuses
            if primary_target_ids and (
                graph is not None or getattr(self, "proof_state", None) is not None
            ):
                return False
            if primary_target_ids:
                structural_target_requires_selected_authority = True
        selected_item = getattr(self, "selected_work_item", None)
        if selected_item is not None:
            try:
                selected_action_compatible = action_id in (
                    self._frontier_candidate_ids_for_work_item(selected_item)
                )
                selected_matches = (
                    self._frontier_work_item_matches_record(
                        selected_item,
                        record,
                    )
                    if record
                    else self._frontier_action_key(
                        selected_item,
                        action_id,
                        probe=True,
                    )
                    == action_key
                )
            except Exception:
                selected_action_compatible = False
                selected_matches = False
            if selected_action_compatible and selected_matches:
                return True
        if structural_target_requires_selected_authority:
            return False
        try:
            candidates: List[Any] = []
            candidates.extend(
                self._ready_root_route_assembly_work_items(mutate=False)
            )
            candidates.extend(self._all_work_frontier_items(mutate=False))
            if not record and work_type == "root_repair":
                root_work = self._conversation_semantic_work_item(action_id)
                if root_work is not None:
                    candidates.append(root_work)
            for work_item in candidates:
                if action_id not in self._frontier_candidate_ids_for_work_item(
                    work_item
                ):
                    continue
                if record:
                    if self._frontier_work_item_matches_record(
                        work_item,
                        record,
                    ):
                        return True
                elif (
                    self._frontier_action_key(
                        work_item,
                        action_id,
                        probe=True,
                    )
                    == action_key
                ):
                    return True
        except Exception:
            return False
        if not record:
            # Legacy snapshots predate the structural record. Their tuple is
            # authoritative only when exact current work reproduces it.
            return False
        return False

    def _release_model_call_deferred_frontier_action(
        self,
        work_item: Any,
        action_id: str,
        *,
        reason: str,
    ) -> bool:
        current_action_key = self._frontier_action_key(work_item, action_id)
        action_key = self._model_call_deferred_frontier_key_for_work_item(
            work_item,
            action_id,
        )
        if action_key is None:
            return False
        retryable, metadata = self._model_call_deferred_frontier_action_retryable(
            action_key
        )
        if not retryable:
            return False
        if not self._provider_defer_receipt_is_ready(metadata):
            return False
        (
            max_retries,
            persistent_infrastructure_retry,
        ) = self._model_call_deferred_frontier_retry_policy(
            metadata,
        )
        if (
            persistent_infrastructure_retry
            and not self._persistent_infrastructure_retry_is_ready(metadata)
        ):
            return False
        retry_keys = self._frontier_progress_retry_keys(work_item, action_key)
        retry_key = retry_keys[0]
        exact_key_retries = 0
        if retry_key != action_key:
            exact_key_retries = int(
                self.model_call_deferred_frontier_retry_counts.get(action_key, 0) or 0
            )
        prior_retries = max(
            exact_key_retries,
            int(self.model_call_deferred_frontier_retry_counts.get(retry_key, 0) or 0),
        )
        if retry_key != action_key:
            if prior_retries > 0:
                for alias_key in retry_keys:
                    self.model_call_deferred_frontier_retry_counts[alias_key] = max(
                        prior_retries,
                        int(
                            self.model_call_deferred_frontier_retry_counts.get(
                                alias_key,
                                0,
                            )
                            or 0
                        ),
                    )
            self.model_call_deferred_frontier_retry_counts.pop(action_key, None)
        if not persistent_infrastructure_retry and prior_retries >= max_retries:
            return False
        if not self._frontier_candidate_serviceable_for_recovery(
            work_item,
            action_id,
            ignore_model_call_deferred=True,
        ):
            return False
        released_retry_count = prior_retries
        if not persistent_infrastructure_retry:
            released_retry_count += 1
            for alias_key in retry_keys:
                self.model_call_deferred_frontier_retry_counts[alias_key] = max(
                    released_retry_count,
                    int(
                        self.model_call_deferred_frontier_retry_counts.get(
                            alias_key,
                            0,
                        )
                        or 0
                    ),
                )
        self.model_call_deferred_frontier_action_keys.discard(action_key)
        if not persistent_infrastructure_retry:
            self.model_call_deferred_frontier_action_metadata.pop(
                action_key,
                None,
            )
        self.skipped_frontier_work_keys.discard(self._frontier_work_key(work_item))
        self.consumed_frontier_action_keys.discard(action_key)
        self.skipped_frontier_action_keys.discard(action_key)
        self.consumed_frontier_action_keys.discard(current_action_key)
        self.skipped_frontier_action_keys.discard(current_action_key)
        self._clear_paired_model_call_deferred_static_guard(
            action_id,
            reason=reason,
        )
        self._increment_dossier_metric(
            "mini_session_model_call_deferred_frontier_retry_releases",
            1,
        )
        self._record_event(
            {
                "phase": "session_model_call_deferred_frontier_action",
                "iteration": self.iteration,
                "action_id": str(action_id or ""),
                "reason": str(reason or ""),
                "retry_identity": list(retry_key),
                "retry_count": released_retry_count,
                "max_retries": max_retries,
                "provider_retry_count": int(
                    metadata.get(
                        "provider_retry_count",
                        metadata.get("retry_count", 0),
                    )
                    or 0
                ),
                "scheduler_retry_count": released_retry_count,
                "max_scheduler_retries": max_retries,
                "scheduler_retries_unbounded": persistent_infrastructure_retry,
                "llm_failure_kind": str(metadata.get("llm_failure_kind") or ""),
                "scoped_failure_reason": str(
                    metadata.get("scoped_failure_reason") or ""
                ),
                "llm_failure_scope": str(metadata.get("llm_failure_scope") or ""),
                "selected_work_item": self._work_item_to_record(work_item),
                "verdict": "deferred_action_retry_released",
            }
        )
        return True

    def _clear_paired_model_call_deferred_static_guard(
        self,
        action_id: str,
        *,
        reason: str,
    ) -> bool:
        clean = str(action_id or "").strip()
        if clean not in self.model_call_deferred_static_action_ids:
            return False
        retry_identity, prior_retries = (
            self._migrate_model_call_deferred_static_retry_count(clean)
        )
        retryable, metadata = self._model_call_deferred_static_action_retryable(clean)
        if not retryable:
            return False
        if not self._provider_defer_receipt_is_ready(metadata):
            return False
        persistent_infrastructure_retry = self._persistent_infrastructure_defer(
            metadata
        )
        if (
            persistent_infrastructure_retry
            and not self._persistent_infrastructure_retry_is_ready(metadata)
        ):
            return False
        max_retries = max(0, int(self.max_model_call_deferred_static_retries or 0))
        if str(metadata.get("provider_defer_fingerprint") or "").strip():
            max_retries = max(max_retries, 1)
        if self._recovered_provider_receipt_retry_floor(metadata):
            max_retries = max(max_retries, 1)
        if self._active_repair_lane_capacity_retryable(clean, metadata):
            max_retries = max(max_retries, 2)
        if bool(metadata.get("provider_call_quantum_exhausted")) and (
            _nonnegative_metadata_int(metadata, "provider_calls_completed") > 0
            or bool(metadata.get("provider_finalizer_continuation_exhausted"))
        ):
            max_retries = max(
                max_retries,
                _nonnegative_metadata_int(
                    metadata,
                    "provider_call_quantum_max_retries",
                ),
            )
        if not persistent_infrastructure_retry and prior_retries >= max_retries:
            return False
        self.model_call_deferred_static_action_ids.discard(clean)
        if not persistent_infrastructure_retry:
            self.model_call_deferred_static_action_metadata.pop(clean, None)
        self._record_event(
            {
                "phase": "session_model_call_deferred_static_action",
                "iteration": self.iteration,
                "action_id": clean,
                "reason": str(reason or ""),
                "retry_identity": retry_identity,
                "retry_count": prior_retries,
                "max_retries": max_retries,
                "provider_retry_count": int(
                    metadata.get(
                        "provider_retry_count",
                        metadata.get("retry_count", 0),
                    )
                    or 0
                ),
                "scheduler_retry_count": prior_retries,
                "max_scheduler_retries": max_retries,
                "scheduler_retries_unbounded": persistent_infrastructure_retry,
                "llm_failure_kind": str(metadata.get("llm_failure_kind") or ""),
                "scoped_failure_reason": str(
                    metadata.get("scoped_failure_reason") or ""
                ),
                "llm_failure_scope": str(metadata.get("llm_failure_scope") or ""),
                "verdict": "paired_frontier_static_guard_cleared",
            }
        )
        return True

    def _static_action_serviceable_for_recovery(
        self,
        action_id: str,
        *,
        ignore_model_call_deferred: bool = False,
    ) -> bool:
        clean = str(action_id or "").strip()
        if not clean:
            return False
        effective_defer = self._model_call_deferred_static_action_effective(clean)
        if not ignore_model_call_deferred and effective_defer:
            return False
        action = self.registered_action(clean)
        if action is None:
            return False
        saved_target = self.selected_work_item
        saved_action_id = self.selected_work_item_action_id
        saved_record = dict(self.selected_work_item_record)
        removed_static_defer = False
        try:
            self._clear_selected_work_item()
            if ignore_model_call_deferred and effective_defer:
                self.model_call_deferred_static_action_ids.discard(clean)
                removed_static_defer = True
            self._suppress_dossier_metric_recording += 1
            try:
                return self._safe_is_applicable(
                    action,
                    context="no_applicable_static_recovery_probe",
                )
            finally:
                self._suppress_dossier_metric_recording = max(
                    0,
                    int(self._suppress_dossier_metric_recording or 0) - 1,
                )
        finally:
            if removed_static_defer:
                self.model_call_deferred_static_action_ids.add(clean)
            self.selected_work_item = saved_target
            self.selected_work_item_action_id = saved_action_id
            self.selected_work_item_record = saved_record

    def _release_model_call_deferred_static_action(
        self,
        action_id: str,
        *,
        reason: str,
        require_serviceable: bool = True,
    ) -> bool:
        clean = str(action_id or "").strip()
        if clean not in self.model_call_deferred_static_action_ids:
            return False
        retryable, metadata = self._model_call_deferred_static_action_retryable(clean)
        if not retryable:
            return False
        if not self._provider_defer_receipt_is_ready(metadata):
            return False
        persistent_infrastructure_retry = self._persistent_infrastructure_defer(
            metadata
        )
        if (
            persistent_infrastructure_retry
            and not self._persistent_infrastructure_retry_is_ready(metadata)
        ):
            return False
        retry_identity, prior_retries = (
            self._migrate_model_call_deferred_static_retry_count(clean)
        )
        max_retries = self._model_call_deferred_static_retry_limit(
            clean,
            metadata,
        )
        if not persistent_infrastructure_retry and prior_retries >= max_retries:
            return False
        selector_retry = bool(
            str(metadata.get("scoped_failure_reason") or "").strip()
            == "mini_selector_infrastructure_exception"
        )
        if (
            require_serviceable
            and not selector_retry
            and not self._active_repair_lane_owns_action(clean, metadata)
            and not self._static_action_serviceable_for_recovery(
                clean,
                ignore_model_call_deferred=True,
            )
        ):
            return False
        released_retry_count = prior_retries
        if not persistent_infrastructure_retry:
            released_retry_count += 1
            for alias_identity in self._model_call_deferred_static_retry_identities(
                clean
            ):
                self.model_call_deferred_static_retry_counts[alias_identity] = max(
                    released_retry_count,
                    int(
                        self.model_call_deferred_static_retry_counts.get(
                            alias_identity,
                            0,
                        )
                        or 0
                    ),
                )
        self.model_call_deferred_static_action_ids.discard(clean)
        self._increment_dossier_metric(
            "mini_session_model_call_deferred_static_retry_releases",
            1,
        )
        self._record_event(
            {
                "phase": "session_model_call_deferred_static_action",
                "iteration": self.iteration,
                "action_id": clean,
                "reason": str(reason or ""),
                "retry_identity": retry_identity,
                "retry_count": released_retry_count,
                "max_retries": max_retries,
                "provider_retry_count": int(
                    metadata.get(
                        "provider_retry_count",
                        metadata.get("retry_count", 0),
                    )
                    or 0
                ),
                "scheduler_retry_count": released_retry_count,
                "max_scheduler_retries": max_retries,
                "scheduler_retries_unbounded": persistent_infrastructure_retry,
                "llm_failure_kind": str(metadata.get("llm_failure_kind") or ""),
                "scoped_failure_reason": str(
                    metadata.get("scoped_failure_reason") or ""
                ),
                "llm_failure_scope": str(metadata.get("llm_failure_scope") or ""),
                "verdict": "deferred_static_action_retry_released",
            }
        )
        return True

    def _release_retryable_deferred_no_applicable_recovery_action_ids(
        self,
        action_ids: Sequence[str],
        *,
        selected_work_record: Optional[Dict[str, Any]] = None,
        reason: str = "",
    ) -> Set[str]:
        wanted = {
            str(action_id or "").strip()
            for action_id in action_ids
            if str(action_id or "").strip()
        }
        if not wanted:
            return set()
        scoped_record = dict(selected_work_record or {})
        released: Set[str] = set()

        def consider_work_item(work_item: Any) -> None:
            if scoped_record and not self._frontier_work_item_matches_record(
                work_item,
                scoped_record,
            ):
                return
            work_type = str(self._work_item_field(work_item, "work_type", "") or "")
            if not work_type:
                return
            for candidate_id in self._frontier_candidate_ids_for_work_item(work_item):
                if candidate_id not in wanted or candidate_id in released:
                    continue
                if self._release_model_call_deferred_frontier_action(
                    work_item,
                    candidate_id,
                    reason=reason,
                ):
                    released.add(candidate_id)

        for route_work_item in self._ready_root_route_assembly_work_items():
            consider_work_item(route_work_item)
            if released == wanted:
                return released
        getter = getattr(self.proof_state, "work_frontier", None)
        offset_supported = self._work_frontier_accepts_offset(getter)
        frontier_offset = 0
        for _frontier_page in range(40):
            frontier_items = self._work_frontier_items(
                offset=frontier_offset,
                mutate=False,
            )
            if not frontier_items:
                break
            for work_item in frontier_items:
                consider_work_item(work_item)
                if released == wanted:
                    return released
            if not offset_supported:
                break
            frontier_offset += len(frontier_items)
        if not scoped_record:
            paired_frontier_action_ids = {
                str(
                    (
                        self.model_call_deferred_frontier_action_metadata.get(key) or {}
                    ).get("action_id")
                    or (key[-1] if key else "")
                    or ""
                ).strip()
                for key in self.model_call_deferred_frontier_action_keys
            }
            for action_id in sorted(wanted - released - paired_frontier_action_ids):
                if self._release_model_call_deferred_static_action(
                    action_id,
                    reason=reason,
                ):
                    released.add(action_id)
        return released

    def _release_matured_model_call_deferred_after_static_quantum(self) -> Set[str]:
        """Resume bounded model work after another action receives one quantum."""

        current_iteration = int(self.iteration or 0)
        matured_action_ids: Set[str] = set()
        for metadata in self._iter_model_call_deferred_metadata():
            if not self._model_call_deferred_metadata_retryable(metadata):
                continue
            try:
                deferred_iteration = int(metadata.get("deferred_iteration"))
            except (TypeError, ValueError, OverflowError):
                continue
            # apply() advances once after recording the defer. Requiring a
            # second advance guarantees that at least one other real action
            # received a scheduler quantum before the model lane is resumed.
            if current_iteration < deferred_iteration + 2:
                continue
            action_id = str(metadata.get("action_id") or "").strip()
            if action_id:
                matured_action_ids.add(action_id)
        if not matured_action_ids:
            return set()
        released = self._release_retryable_deferred_no_applicable_recovery_action_ids(
            sorted(matured_action_ids),
            reason="post_defer_static_quantum",
        )
        self._dispatch_generation_release_suppressed_action_ids.update(
            action_id
            for action_id in released
            if action_id.startswith("conversation_turn")
        )
        return released

    def _has_serviceable_no_applicable_recovery_work(
        self,
        action_ids: Sequence[str],
        *,
        selected_work_record: Optional[Dict[str, Any]] = None,
    ) -> bool:
        return bool(
            self._serviceable_no_applicable_recovery_action_ids(
                action_ids,
                selected_work_record=selected_work_record,
            )
        )

    def _frontier_work_item_matches_record(
        self,
        work_item: Any,
        record: Dict[str, Any],
    ) -> bool:
        candidate_record = self._work_item_to_record(work_item)
        scoped_record = dict(record or {})
        if not scoped_record:
            return True
        record_work_type = self._model_call_deferred_work_type(scoped_record)
        candidate_work_type = self._model_call_deferred_work_type(candidate_record)
        if (
            record_work_type
            and candidate_work_type
            and record_work_type != candidate_work_type
        ):
            return False
        target_match = self._model_call_deferred_work_item_target_match(
            work_item,
            scoped_record,
        )
        if target_match is not None:
            return target_match
        id_keys = (
            "node_id",
            "graph_node_id",
            "obligation_id",
            "claim_id",
            "variant_id",
            "replan_id",
            "route_id",
            "target_id",
        )
        for key in id_keys:
            record_ids = {
                str(layer.get(key) or "").strip()
                for layer in selected_work_mapping_layers(scoped_record)
                if str(layer.get(key) or "").strip()
            }
            candidate_ids = {
                str(layer.get(key) or "").strip()
                for layer in selected_work_mapping_layers(candidate_record)
                if str(layer.get(key) or "").strip()
            }
            if record_ids and candidate_ids:
                return bool(record_ids & candidate_ids)
        materialized_record = self._materialize_work_item_from_record(scoped_record)
        record_key = self._frontier_work_key(materialized_record)
        candidate_key = self._frontier_work_key(work_item)
        if any(record_key) and any(candidate_key):
            return record_key == candidate_key
        return True

    def _frontier_has_later_candidate(
        self,
        work_item: Any,
        action_id: str,
    ) -> bool:
        work_type = str(self._work_item_field(work_item, "work_type", "") or "")
        candidate_ids = self._frontier_candidate_ids_for_work_item(work_item)
        if work_type == "assemble_route" and str(action_id or "").startswith(
            "conversation_turn"
        ):
            return False
        try:
            current_index = candidate_ids.index(str(action_id or ""))
        except ValueError:
            return False
        return any(
            self._frontier_candidate_available_for_work_item(work_item, candidate_id)
            for candidate_id in candidate_ids[current_index + 1 :]
        )

    def _frontier_has_later_candidate_id(
        self,
        work_item: Any,
        action_id: str,
    ) -> bool:
        work_type = str(self._work_item_field(work_item, "work_type", "") or "")
        if work_type not in {
            "route_replan",
            "mine_missing_obligation",
            "formalize_missing_obligation",
            "formalize_claim",
            "prove_claim_variant",
        }:
            return False
        candidate_ids = self._frontier_candidate_ids_for_work_item(work_item)
        try:
            current_index = candidate_ids.index(str(action_id or ""))
        except ValueError:
            return False
        return current_index + 1 < len(candidate_ids)

    def _record_selected_route_authoring_failure(
        self,
        outcome: MiniOutcome,
        *,
        reason: str = "",
    ) -> Tuple[bool, str]:
        record = dict(getattr(self, "selected_work_item_record", {}) or {})
        work_type = str(record.get("work_type") or "").strip()
        if work_type != "assemble_route":
            return False, ""
        action_id = str(outcome.action_id or "").strip()
        if not action_id.startswith("conversation_turn"):
            return False, ""
        graph = (
            getattr(self.dossier, "proof_graph", None)
            if self.dossier is not None
            else None
        )
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if graph is None or not isinstance(nodes, dict):
            return False, ""
        graph_record = getattr(self.selected_work_item, "graph_record", None)
        if not isinstance(graph_record, dict):
            graph_record = dict(record.get("graph_record") or {})
        target_id = ""
        for route_field in ("route_id", "graph_node_id", "node_id"):
            candidate = str(
                graph_record.get(route_field) or record.get(route_field) or ""
            ).strip()
            if candidate:
                target_id = candidate
                break
        if not target_id:
            return False, ""
        route_node = nodes.get(target_id)
        metadata = (
            getattr(route_node, "metadata", None) if route_node is not None else None
        )
        signature_getter = getattr(graph, "route_dependency_signature_hash", None)
        if (
            route_node is None
            or not isinstance(metadata, dict)
            or not callable(signature_getter)
        ):
            return False, ""
        try:
            current_signature_hash = str(signature_getter(target_id) or "").strip()
        except Exception:
            current_signature_hash = ""
        if not current_signature_hash:
            return False, ""
        if (
            str(metadata.get("route_root_assembly_author_failed_signature_hash") or "")
            == current_signature_hash
        ):
            ensure_orphans = getattr(
                graph,
                "_ensure_orphaned_route_missing_assembly_bridge_rescues",
                None,
            )
            if callable(ensure_orphans):
                try:
                    ensure_orphans()
                except Exception:
                    pass
            try:
                outcome.metadata.update(
                    {
                        "route_authoring_failed_recorded": True,
                        "route_authoring_failed_signature_hash": current_signature_hash,
                        "route_authoring_failure_rescue_obligation_id": str(
                            metadata.get(
                                "route_missing_assembly_bridge_rescue_obligation_id"
                            )
                            or ""
                        ),
                        "route_authoring_failure_rescue_replan_id": str(
                            metadata.get(
                                "route_missing_assembly_bridge_rescue_replan_id"
                            )
                            or ""
                        ),
                        "graph_work_consumed_verdict": (
                            "route_authoring_failed_rescue_already_current"
                        ),
                        "graph_work_consumed_error_type": (
                            "route_authoring_lean_rejected"
                        ),
                    }
                )
            except Exception:
                pass
            return True, current_signature_hash
        try:
            failed_hash = graph_text_hash(
                json.dumps(
                    {
                        "route_id": target_id,
                        "action_id": action_id,
                        "dependency_signature_hash": current_signature_hash,
                    },
                    sort_keys=True,
                )
            )
        except Exception:
            failed_hash = current_signature_hash
        metadata["route_root_assembly_author_failed_hash"] = failed_hash
        metadata["route_root_assembly_author_failed_signature_hash"] = (
            current_signature_hash
        )
        metadata.pop("route_root_tactic_authoring_ready_hash", None)
        metadata.pop("route_root_tactic_authoring_ready_signature_hash", None)
        try:
            route_node.status = "open"
        except Exception:
            pass
        try:
            self._increment_dossier_metric(
                "mini_session_graph_route_authoring_failed",
                1,
            )
        except Exception:
            pass
        try:
            graph.record_attempt(
                target_id,
                phase="graph_route_authoring_failed",
                turn_index=int(self.iteration or 0),
                proof="",
                verdict="route_authoring_failed_recorded",
                error_type="route_authoring_lean_rejected",
                metadata={
                    "action_id": action_id,
                    "work_type": work_type,
                    "selected_work_item": record,
                    "reason": str(reason or ""),
                    "dependency_signature_hash": current_signature_hash,
                    "outcome_progress": bool(outcome.progress),
                    "outcome_solved": bool(outcome.solved),
                    "lean_verdict": str(
                        (outcome.metadata or {}).get("lean_verdict") or ""
                    ),
                    "lean_error_type": str(
                        (outcome.metadata or {}).get("lean_error_type") or ""
                    ),
                },
            )
        except Exception:
            pass
        rescue_id = ""
        rescue_replan_id = ""
        try:
            contract_getter = getattr(graph, "route_assembly_contract_status", None)
            ensure_rescue = getattr(
                graph,
                "ensure_route_missing_assembly_bridge_rescue",
                None,
            )
            if callable(contract_getter) and callable(ensure_rescue):
                contract_status = contract_getter(
                    target_id,
                    target_statement=str(
                        getattr(self.dossier, "root_statement", "") or ""
                    ),
                )
                rescue = ensure_rescue(
                    target_id,
                    contract_status,
                    signature_hash=current_signature_hash,
                    phase="graph_route_authoring_failed",
                    turn_index=int(self.iteration or 0),
                    allow_deterministic_ready=True,
                )
                rescue_id = str(getattr(rescue, "node_id", "") or "")
                rescue_replan_id = str(
                    metadata.get("route_missing_assembly_bridge_rescue_replan_id") or ""
                )
        except Exception:
            rescue_id = ""
            rescue_replan_id = ""
        self._record_event(
            {
                "phase": "graph_route_authoring_failed",
                "iteration": self.iteration,
                "action_id": action_id,
                "selected_work_item": record,
                "route_id": target_id,
                "route_authoring_failed_signature_hash": current_signature_hash,
                "route_authoring_failure_rescue_obligation_id": rescue_id,
                "route_authoring_failure_rescue_replan_id": rescue_replan_id,
                "reason": str(reason or ""),
                "verdict": "route_authoring_failed_recorded",
            }
        )
        try:
            outcome.metadata["route_authoring_failed_recorded"] = True
            outcome.metadata["route_authoring_failed_signature_hash"] = (
                current_signature_hash
            )
            outcome.metadata["route_authoring_failure_rescue_obligation_id"] = rescue_id
            outcome.metadata["route_authoring_failure_rescue_replan_id"] = (
                rescue_replan_id
            )
            outcome.metadata["graph_work_consumed_verdict"] = (
                "route_authoring_failed_rescue_materialized"
            )
            outcome.metadata["graph_work_consumed_error_type"] = (
                "route_authoring_lean_rejected"
            )
        except Exception:
            pass
        return True, current_signature_hash

    def _selected_route_authoring_rejection_progress(
        self, outcome: MiniOutcome
    ) -> bool:
        if outcome.solved:
            return False
        action_id = str(outcome.action_id or "").strip()
        if not action_id.startswith("conversation_turn"):
            return False
        record = dict(getattr(self, "selected_work_item_record", {}) or {})
        if str(record.get("work_type") or "").strip() != "assemble_route":
            return False
        metadata = outcome.metadata or {}
        if bool(metadata.get("llm_retryable")) or bool(
            metadata.get("defer_selected_frontier_action")
        ):
            return False
        return bool(
            str(metadata.get("lean_verdict") or "").strip() == "lean_rejected"
            or str(metadata.get("verdict") or "").strip() == "lean_rejected"
            or str(metadata.get("lean_error_type") or "").strip()
            or str(metadata.get("lean_failure_signature") or "").strip()
            or str(metadata.get("feedback_source") or "").strip()
        )

    def _consume_selected_frontier_work(self, outcome: MiniOutcome) -> None:
        captured_action_key = self.selected_frontier_action_key
        if (
            captured_action_key is not None
            and len(captured_action_key) == 6
            and str(self.selected_work_item_action_id or "").strip()
            == str(outcome.action_id or "").strip()
        ):
            action_key = tuple(captured_action_key)
            key = tuple(action_key[:5])
        else:
            key = self._frontier_work_key(self.selected_work_item)
            action_key = self._frontier_action_key(
                self.selected_work_item,
                outcome.action_id,
            )
        if not any(key):
            return
        record = dict(self.selected_work_item_record)
        work_type_for_consumption = str(record.get("work_type") or key[1] or "").strip()
        outcome_metadata = dict(outcome.metadata or {})
        repair_pending, repair_pending_identity = (
            self._bounded_repair_pending_for_graph_work(record)
        )
        if not repair_pending:
            self._release_stale_graph_target_repair_pending_authority(record)
        formalization_declaration_work_types = {
            "formalize_missing_obligation",
            "formalize_claim",
            "mine_missing_obligation",
        }
        formalization_declaration_retry_required = bool(
            work_type_for_consumption in formalization_declaration_work_types
            and (
                outcome_metadata.get("formalization_declaration_retry_required")
                or outcome_metadata.get("lean_error_type")
                == "formalization_requires_declaration"
                or outcome_metadata.get("rejection_reason")
                == "formalization_requires_declaration"
            )
        )
        materialization_pending = bool(
            work_type_for_consumption in formalization_declaration_work_types
            and (
                record.get("formalization_statement_pending")
                or record.get("materialization_required")
                or record.get("formalization_required")
            )
            and not str(record.get("target_statement") or "").strip()
            and not bool(outcome.progress)
            and not bool(outcome.solved)
            and not formalization_declaration_retry_required
        )
        materialization_reselected_same_action = False
        materialization_logical_key = self._frontier_materialization_logical_key(
            self.selected_work_item
        )
        if materialization_pending:
            materialization_reselected_same_action = (
                action_key in self.materialization_pending_frontier_action_keys
                or action_key in self.skipped_frontier_action_keys
            )
            self.materialization_pending_frontier_action_keys.add(action_key)
            if any(materialization_logical_key):
                self.materialization_pending_frontier_logical_keys.add(
                    materialization_logical_key
                )
                self.materialization_pending_frontier_action_logical_keys[
                    action_key
                ] = materialization_logical_key
            self.skipped_frontier_action_keys.add(action_key)
            self._increment_dossier_metric(
                "mini_session_materialization_pending_escalated",
                1,
            )
            if materialization_reselected_same_action:
                self._increment_dossier_metric(
                    "mini_session_materialization_pending_reselected_same_action",
                    1,
                )
            if bool(getattr(self, "repair_policy_narrowing_required", False)):
                self._increment_dossier_metric(
                    "mini_session_repair_policy_narrowing_materialization_escalated",
                    1,
                )
                if materialization_reselected_same_action:
                    self._increment_dossier_metric(
                        "mini_session_repair_policy_narrowing_reselected_same_work",
                        1,
                    )
        has_later_available_candidate = self._frontier_has_later_candidate(
            self.selected_work_item,
            outcome.action_id,
        )
        has_later_candidate = has_later_available_candidate or (
            self._frontier_has_later_candidate_id(
                self.selected_work_item,
                outcome.action_id,
            )
        )
        transient_retrieval_backoff = False
        if (
            outcome.action_id == "proof_state_retrieval"
            and self.proof_state is not None
        ):
            retrieval_node_id = str(record.get("node_id") or key[0] or "").strip()
            retrieval_node = self.proof_state.nodes.get(retrieval_node_id)
            transient_retrieval_backoff = bool(
                retrieval_node is not None
                and getattr(retrieval_node, "retrieval_error_transient", False)
            )
        if (
            not materialization_pending
            and not formalization_declaration_retry_required
            and not repair_pending
            and not transient_retrieval_backoff
        ):
            self.consumed_frontier_action_keys.add(action_key)
        if (
            not has_later_candidate
            and not materialization_pending
            and not formalization_declaration_retry_required
            and not repair_pending
            and not transient_retrieval_backoff
        ):
            self.consumed_frontier_work_keys.add(key)
        reason = (
            f"{outcome.action_id}: raised {type(outcome.exception).__name__}"
            if outcome.exception is not None
            else f"{outcome.action_id}: no progress"
        )
        node_id = str(record.get("node_id") or key[0] or "").strip()
        if (
            node_id
            and self.proof_state is not None
            and not has_later_candidate
            and not materialization_pending
            and not formalization_declaration_retry_required
            and not transient_retrieval_backoff
        ):
            budget_skip = getattr(self.proof_state, "record_budget_skip", None)
            if callable(budget_skip):
                try:
                    budget_skip(node_id=node_id, reason=reason)
                except Exception:
                    pass
        graph_record = getattr(self.selected_work_item, "graph_record", None)
        if not isinstance(graph_record, dict):
            graph_record = dict(record.get("graph_record") or {})
        graph = (
            getattr(self.dossier, "proof_graph", None)
            if self.dossier is not None
            else None
        )
        route_authoring_failed = False
        route_authoring_failed_signature_hash = ""
        if graph is not None and isinstance(graph_record, dict):
            work_type = str(record.get("work_type") or key[1] or "").strip()
            target_id = ""
            for field in (
                "replan_id",
                "obligation_id",
                "variant_id",
                "claim_id",
                "route_id",
                "graph_node_id",
                "node_id",
            ):
                if work_type == "route_replan" and field not in {
                    "replan_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "mine_missing_obligation" and field not in {
                    "obligation_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "prove_claim_variant" and field not in {
                    "variant_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "formalize_claim" and field not in {
                    "claim_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "formalize_missing_obligation" and field not in {
                    "obligation_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "target_integrity_adjudication" and field not in {
                    "obligation_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                if work_type == "assemble_route" and field not in {
                    "route_id",
                    "graph_node_id",
                    "node_id",
                }:
                    continue
                candidate = str(
                    graph_record.get(field) or record.get(field) or ""
                ).strip()
                if candidate:
                    target_id = candidate
                    break
            if target_id and target_id in getattr(graph, "nodes", {}):
                try:
                    if repair_pending:
                        self._retain_terminal_graph_target_for_bounded_repair(
                            record,
                            repair_identity=repair_pending_identity,
                            context="graph_work_consumed",
                        )
                    banked_names = [
                        str(item or "").strip()
                        for item in list(
                            (outcome.metadata or {}).get("banked_proposed_helpers")
                            or []
                        )
                        if str(item or "").strip()
                    ]
                    spawned_claim_ids = []
                    if banked_names and hasattr(graph, "nodes_by_kind"):
                        for claim_node in graph.nodes_by_kind("proposed_claim"):
                            if callable(
                                getattr(graph, "is_superseded_tombstone", None)
                            ):
                                try:
                                    if graph.is_superseded_tombstone(claim_node):
                                        continue
                                except Exception:
                                    pass
                            claim_metadata = dict(
                                getattr(claim_node, "metadata", {}) or {}
                            )
                            if claim_metadata.get(
                                "proposal_invalidated"
                            ) or claim_metadata.get("proposal_superseded"):
                                continue
                            if str(getattr(claim_node, "status", "") or "") in {
                                "failed",
                                "proved",
                                "rejected",
                            }:
                                continue
                            proposed_name = str(
                                claim_metadata.get("proposed_helper_name")
                                or getattr(claim_node, "name", "")
                                or ""
                            ).strip()
                            if proposed_name in banked_names:
                                spawned_claim_ids.append(claim_node.node_id)
                    attempt_metadata = {
                        "action_id": outcome.action_id,
                        "work_type": work_type,
                        "selected_work_item": record,
                        "reason": reason,
                        "banked_proposed_helpers": list(banked_names),
                        "later_frontier_candidate_available": (
                            has_later_available_candidate
                        ),
                        "later_frontier_candidate_pending": has_later_candidate,
                    }
                    if spawned_claim_ids:
                        graph.record_attempt(
                            target_id,
                            phase="graph_work_consumed",
                            turn_index=int(self.iteration or 0),
                            proof="",
                            verdict="frontier_work_spawned_proposals",
                            error_type="waiting_on_spawned_proposals",
                            metadata=attempt_metadata,
                        )
                        for claim_id in spawned_claim_ids:
                            graph.add_edge(
                                target_id,
                                claim_id,
                                "replan_spawned_claim",
                            )
                        graph.mark_node_blocked(
                            target_id,
                            reason="waiting on spawned proposed claim",
                            blocker_node_ids=spawned_claim_ids,
                        )
                    else:
                        custom_verdict = str(
                            outcome.metadata.get("graph_work_consumed_verdict") or ""
                        ).strip()
                        custom_error_type = str(
                            outcome.metadata.get("graph_work_consumed_error_type") or ""
                        ).strip()
                        if repair_pending:
                            custom_verdict = "repair_pending"
                            custom_error_type = (
                                custom_error_type
                                or str(outcome_metadata.get("lean_error_type") or "")
                                or "repair_pending"
                            )
                            attempt_metadata["repair_pending"] = True
                            attempt_metadata["repair_pending_identity"] = (
                                repair_pending_identity
                            )
                            attempt_metadata["frontier_action_retained_for_retry"] = (
                                True
                            )
                        if formalization_declaration_retry_required:
                            custom_verdict = (
                                custom_verdict
                                or "formalization_declaration_retry_required"
                            )
                            custom_error_type = (
                                custom_error_type
                                or "formalization_requires_declaration"
                            )
                            attempt_metadata[
                                "formalization_declaration_retry_required"
                            ] = True
                            attempt_metadata["frontier_action_retained_for_retry"] = (
                                True
                            )
                            try:
                                self._increment_dossier_metric(
                                    "mini_session_formalization_declaration_retries",
                                    1,
                                )
                            except Exception:
                                pass
                        if materialization_pending:
                            custom_verdict = (
                                custom_verdict
                                or "formalization_materialization_pending"
                            )
                            custom_error_type = (
                                custom_error_type
                                or "formalization_materialization_pending"
                            )
                            attempt_metadata["materialization_ticket_retained"] = True
                            attempt_metadata[
                                "materialization_pending_action_skipped"
                            ] = True
                            attempt_metadata[
                                "materialization_pending_reselected_same_action"
                            ] = materialization_reselected_same_action
                            attempt_metadata["repair_policy_narrowing_required"] = bool(
                                getattr(
                                    self,
                                    "repair_policy_narrowing_required",
                                    False,
                                )
                            )
                            try:
                                self._increment_dossier_metric(
                                    "mini_session_materialization_tickets_retained",
                                    1,
                                )
                            except Exception:
                                pass
                        verdict = (
                            "graph_work_exception"
                            if outcome.exception is not None
                            else custom_verdict or "frontier_work_no_progress"
                        )
                        error_type = custom_error_type or "frontier_work_no_progress"
                        if has_later_candidate:
                            verdict = (
                                "frontier_action_exception"
                                if outcome.exception is not None
                                else custom_verdict or "frontier_action_no_progress"
                            )
                            error_type = (
                                custom_error_type or "frontier_action_no_progress"
                            )
                        graph.record_attempt(
                            target_id,
                            phase="graph_work_consumed",
                            turn_index=int(self.iteration or 0),
                            proof="",
                            verdict=verdict,
                            error_type=error_type,
                            metadata=attempt_metadata,
                        )
                        if (
                            work_type == "assemble_route"
                            and outcome.action_id.startswith("conversation_turn")
                            and not outcome.metadata.get(
                                "route_authoring_failed_recorded"
                            )
                        ):
                            route_node = graph.nodes.get(target_id)
                            metadata = (
                                getattr(route_node, "metadata", None)
                                if route_node is not None
                                else None
                            )
                            signature_getter = getattr(
                                graph,
                                "route_dependency_signature_hash",
                                None,
                            )
                            if isinstance(metadata, dict) and callable(
                                signature_getter
                            ):
                                try:
                                    current_signature_hash = str(
                                        signature_getter(target_id) or ""
                                    ).strip()
                                except Exception:
                                    current_signature_hash = ""
                                if current_signature_hash:
                                    try:
                                        from ensemble_prover.proof_graph import (
                                            graph_text_hash,
                                        )

                                        failed_hash = graph_text_hash(
                                            json.dumps(
                                                {
                                                    "route_id": target_id,
                                                    "action_id": outcome.action_id,
                                                    "dependency_signature_hash": (
                                                        current_signature_hash
                                                    ),
                                                },
                                                sort_keys=True,
                                            )
                                        )
                                    except Exception:
                                        failed_hash = current_signature_hash
                                    metadata[
                                        "route_root_assembly_author_failed_hash"
                                    ] = failed_hash
                                    metadata[
                                        "route_root_assembly_author_failed_signature_hash"
                                    ] = current_signature_hash
                                    route_authoring_failed = True
                                    route_authoring_failed_signature_hash = (
                                        current_signature_hash
                                    )
                                    try:
                                        route_node.status = "open"
                                    except Exception:
                                        pass
                                    metadata.pop(
                                        "route_root_tactic_authoring_ready_hash",
                                        None,
                                    )
                                    metadata.pop(
                                        "route_root_tactic_authoring_ready_signature_hash",
                                        None,
                                    )
                                    self._increment_dossier_metric(
                                        "mini_session_graph_route_authoring_failed",
                                        1,
                                    )
                except Exception:
                    pass
        self._record_event(
            {
                "phase": "graph_work_consumed",
                "iteration": self.iteration,
                "action_id": outcome.action_id,
                "selected_work_item": record,
                "consumed_key": list(key),
                "reason": reason,
                "route_authoring_failed": bool(route_authoring_failed),
                "route_authoring_failed_signature_hash": (
                    route_authoring_failed_signature_hash
                ),
                "route_root_tactic_authoring_suppressed": bool(
                    outcome.metadata.get("route_root_tactic_authoring_suppressed")
                ),
                "route_root_tactic_authoring_suppressed_reason": str(
                    outcome.metadata.get(
                        "route_root_tactic_authoring_suppressed_reason"
                    )
                    or ""
                ),
                "materialization_pending_action_skipped": bool(materialization_pending),
                "formalization_declaration_retry_required": bool(
                    formalization_declaration_retry_required
                ),
                "frontier_action_retained_for_retry": bool(
                    formalization_declaration_retry_required or repair_pending
                ),
                "repair_pending": bool(repair_pending),
                "repair_pending_identity": repair_pending_identity,
                "materialization_pending_reselected_same_action": (
                    materialization_reselected_same_action
                ),
                "repair_policy_narrowing_required": bool(
                    getattr(self, "repair_policy_narrowing_required", False)
                ),
                "verdict": str(
                    outcome.metadata.get("graph_work_consumed_verdict")
                    or (
                        "repair_pending"
                        if repair_pending
                        else "formalization_materialization_pending"
                        if materialization_pending
                        else "frontier_work_no_progress"
                    )
                ),
            }
        )

    def selected_work_item_for(
        self,
        action_id: str,
        *,
        work_types: Tuple[str, ...] = (),
    ) -> Optional[Any]:
        """Return the scheduler-selected target for this action, if any.

        Actions use this instead of peeking at ``selected_work_item``
        directly so a stale target for a different action cannot leak
        into static-priority dispatch or subaction dispatch.
        """

        if str(action_id or "") != self.selected_work_item_action_id:
            return None
        item = self.selected_work_item
        if item is None:
            return None
        if work_types:
            work_type = str(self._work_item_field(item, "work_type", "") or "")
            if work_type not in set(work_types):
                return None
        return item

    def selected_work_item_node_ids(
        self,
        action_id: str,
        *,
        work_types: Tuple[str, ...] = (),
    ) -> Tuple[str, ...]:
        item = self.selected_work_item_for(action_id, work_types=work_types)
        if item is None:
            return ()
        node_id = str(self._work_item_field(item, "node_id", "") or "").strip()
        return (node_id,) if node_id else ()

    def selected_work_item_work_types(
        self,
        action_id: str,
        *,
        work_types: Tuple[str, ...] = (),
    ) -> Tuple[str, ...]:
        item = self.selected_work_item_for(action_id, work_types=work_types)
        if item is None:
            return ()
        work_type = str(self._work_item_field(item, "work_type", "") or "").strip()
        return (work_type,) if work_type else ()

    def _work_item_to_record(self, work_item: Any) -> Dict[str, Any]:
        if work_item is None:
            return {}
        if isinstance(work_item, dict):
            return self._sanitize_selected_work_record_answer_aliases(work_item)
        to_record = getattr(work_item, "to_record", None)
        if callable(to_record):
            try:
                try:
                    serializer_parameters = inspect.signature(to_record).parameters
                except (TypeError, ValueError):
                    serializer_parameters = {}
                serializer_accepts_visibility = bool(
                    "official_answer_visible_to_llm" in serializer_parameters
                    or any(
                        parameter.kind is inspect.Parameter.VAR_KEYWORD
                        for parameter in serializer_parameters.values()
                    )
                )
                if serializer_accepts_visibility:
                    official_answer_visible = (
                        self._effective_official_answer_visibility()
                    )
                    record = to_record(
                        suppress_solution_placeholders=(not official_answer_visible),
                        official_answer_visible_to_llm=(official_answer_visible),
                    )
                else:
                    record = to_record()
            except Exception:
                record = {}
            if isinstance(record, dict):
                return self._sanitize_selected_work_record_answer_aliases(record)
        out: Dict[str, Any] = {}
        for key in (
            "node_id",
            "work_type",
            "action",
            "priority",
            "target_hash",
            "blocker",
            "dependencies",
            "source",
            "graph_node_id",
            "assembly_id",
            "child_state_node_ids",
            "unblocked_by_graph",
            "reopened_by_new_evidence",
            "evidence_hash",
            "retrieval_signature",
            "retrieval_context_stamp",
            "retrieved_decl_names_hash",
            "decl_application_pending_hash",
            "helper_acceptance_request_hash",
            "decl_application_signature",
            "proof_stub_hash",
            "assembly_witness_hash",
            "assembly_group_status",
            "projection_turn_index",
            "target_statement",
            "execution_scope_schema_version",
            "execution_scope_id",
            "execution_scope_digest",
            "execution_target_sha256",
            "execution_target_available",
            "execution_materialization_seed_sha256",
            "execution_target_graph_node_id",
            "execution_environment_hash",
            "execution_contract_identity",
            "execution_proposition_identity",
            "execution_helper_context_hash",
            "execution_scope",
            "execution_currentness_digest",
            "exact_target_statement",
            "consumer_bindings",
            "primary_consumer_binding",
            "cognition_scope_digest",
            "cognition_currentness_digest",
            "obligation_reason",
            "source_phase",
            "missing_dependency",
            "formalization_required",
            "materialization_parent_statement",
            "bridge_relevance_required",
            "forbidden_materialization_fragments",
            "rejected_root_error_type",
            "rejected_root_unknown_identifier",
            "graph_record",
        ):
            if hasattr(work_item, key):
                value = getattr(work_item, key)
                if isinstance(value, tuple):
                    value = list(value)
                out[key] = value
        return self._sanitize_selected_work_record_answer_aliases(out)

    def _stamp_selected_work_graph_revision(
        self,
        record: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Bind a freshly selected cognition packet to the current graph."""

        payload = copy.deepcopy(dict(record or {}))
        dossier = getattr(self, "dossier", None)
        revision_getter = getattr(dossier, "proof_idea_graph_revision", None)
        explicit_cognition = selected_work_has_explicit_cognition(payload)

        def recursive_execution_scope() -> Dict[str, Any]:
            for layer in selected_work_mapping_layers(payload):
                raw_scope = layer.get("execution_scope")
                if isinstance(raw_scope, Mapping):
                    return dict(raw_scope)
            return {}

        def unpinned_cognition(reason: str) -> Dict[str, Any]:
            if not explicit_cognition:
                return dict(record or {})
            marker = "proof-graph-context:unavailable"
            execution_scope = recursive_execution_scope()
            execution_scope["graph_revision"] = marker
            payload["execution_scope"] = execution_scope
            payload["proof_idea_graph_revision"] = marker
            payload["cognition_graph_revision_unavailable"] = True
            payload["cognition_graph_revision_failure_reason"] = str(
                reason or "unavailable"
            )[:240]
            return payload

        if not callable(revision_getter):
            return unpinned_cognition("revision_getter_unavailable")
        layers = selected_work_mapping_layers(payload)
        raw_bindings = [
            dict(item)
            for layer in layers
            for item in list(layer.get("consumer_bindings") or [])
            if isinstance(item, Mapping)
        ]
        raw_bindings = list(
            {
                json.dumps(
                    item,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                    default=str,
                ): item
                for item in raw_bindings
            }.values()
        )
        raw_primaries = [
            dict(value)
            for layer in layers
            for value in (layer.get("primary_consumer_binding"),)
            if isinstance(value, Mapping)
        ]
        unique_primaries = {
            json.dumps(
                item,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                default=str,
            )
            for item in raw_primaries
        }
        if len(unique_primaries) > 1:
            raise ValueError(
                "selected work contains conflicting primary consumer bindings"
            )
        raw_primary = raw_primaries[0] if raw_primaries else None
        if isinstance(raw_primary, Mapping) and not raw_bindings:
            raw_bindings = [dict(raw_primary)]
        primary_binding_ids = {
            str(layer.get("primary_consumer_binding_id") or "").strip()
            for layer in layers
            if str(layer.get("primary_consumer_binding_id") or "").strip()
        }
        if len(primary_binding_ids) > 1:
            raise ValueError("selected work contains conflicting primary binding IDs")
        primary_binding_id = next(iter(primary_binding_ids), "") or (
            str(raw_primary.get("consumer_binding_id") or "").strip()
            if isinstance(raw_primary, Mapping)
            else ""
        )
        ideas = dict(getattr(dossier, "proof_ideas", {}) or {})
        enriched_bindings: List[Dict[str, Any]] = []
        enriched_primary: Dict[str, Any] = {}
        primary_match_count = 0
        for raw_binding in raw_bindings:
            binding = dict(raw_binding)
            if not isinstance(binding.get("proof_lineage"), Mapping):
                enriched_bindings.append(binding)
                if isinstance(raw_primary, Mapping) and binding == dict(raw_primary):
                    primary_match_count += 1
                    enriched_primary = binding
                continue
            old_binding_id = str(binding.get("consumer_binding_id") or "").strip()
            try:
                lineage = ProofLineageEnvelope.from_metadata(binding)
            except (TypeError, ValueError):
                lineage = ProofLineageEnvelope()
            idea = ideas.get(lineage.proof_idea_id)
            branches = tuple(getattr(idea, "branch_provenance", ()) or ())
            known_branch_ids = {
                str(getattr(branch, "branch_id", "") or "").strip()
                for branch in branches
                if str(getattr(branch, "branch_id", "") or "").strip()
            }
            branch_id = str(binding.get("branch_id") or "").strip()
            explicitly_global = bool(
                str(binding.get("branch_scope") or "").strip() == "global"
                or binding.get("global_lifecycle_scope") is True
            )
            if lineage.proof_idea_id and idea is None:
                raise ValueError("selected cognition proof idea is stale")
            if not branch_id and idea is not None and not explicitly_global:
                if len(known_branch_ids) != 1:
                    raise ValueError("selected cognition has no unique branch binding")
                branch_id = next(iter(known_branch_ids))
                binding["branch_id"] = branch_id
            if branch_id and idea is not None and branch_id not in known_branch_ids:
                raise ValueError("selected cognition branch is stale")
            if not str(binding.get("reason") or "").strip() and idea is not None:
                rationale = ""
                for intent in tuple(getattr(idea, "claim_intents", ()) or ()):
                    if str(getattr(intent, "claim_id", "") or "") == lineage.claim_id:
                        rationale = str(getattr(intent, "rationale", "") or "").strip()
                        break
                binding["reason"] = (
                    rationale or str(getattr(idea, "strategy", "") or "").strip()
                )
            identity_payload = {
                "proof_lineage": dict(binding.get("proof_lineage") or {}),
                "branch_id": str(binding.get("branch_id") or ""),
                "reason": str(binding.get("reason") or ""),
                "graph_node_id": str(binding.get("graph_node_id") or ""),
            }
            binding["consumer_binding_id"] = (
                "consumer-binding:"
                + hashlib.sha256(
                    json.dumps(
                        identity_payload,
                        sort_keys=True,
                        separators=(",", ":"),
                        ensure_ascii=False,
                    ).encode("utf-8")
                ).hexdigest()
            )
            enriched_bindings.append(binding)
            is_primary = bool(
                isinstance(raw_primary, Mapping)
                and (
                    (old_binding_id and old_binding_id == primary_binding_id)
                    or raw_binding == dict(raw_primary)
                )
            )
            if is_primary:
                primary_match_count += 1
                enriched_primary = binding
        if enriched_bindings:
            if isinstance(raw_primary, Mapping) and primary_match_count != 1:
                raise ValueError(
                    "selected primary cognition is not a unique consumer binding"
                )
            if not isinstance(raw_primary, Mapping) and len(enriched_bindings) != 1:
                raise ValueError(
                    "selected cognition has multiple consumers and no primary binding"
                )
            enriched_bindings.sort(
                key=lambda item: json.dumps(
                    item,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                )
            )
            payload["consumer_bindings"] = enriched_bindings
            payload["primary_consumer_binding"] = (
                enriched_primary or enriched_bindings[0]
            )
            for layer in selected_work_mapping_layers(payload):
                if not isinstance(layer, dict):
                    continue
                if "consumer_bindings" in layer:
                    layer["consumer_bindings"] = copy.deepcopy(enriched_bindings)
                if "primary_consumer_binding" in layer:
                    layer["primary_consumer_binding"] = copy.deepcopy(
                        payload["primary_consumer_binding"]
                    )
                if "primary_consumer_binding_id" in layer:
                    layer["primary_consumer_binding_id"] = str(
                        payload["primary_consumer_binding"].get("consumer_binding_id")
                        or ""
                    )
            cognition_identity = {
                "schema_version": 1,
                "consumer_bindings": enriched_bindings,
                "primary_consumer_binding_id": str(
                    payload["primary_consumer_binding"].get("consumer_binding_id") or ""
                ),
            }
            payload["cognition_scope_digest"] = hashlib.sha256(
                json.dumps(
                    cognition_identity,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                ).encode("utf-8")
            ).hexdigest()
        # Fingerprint the packet only after canonical cognition enrichment.
        # Branch inference and consumer-binding identity are revision inputs;
        # stamping their pre-enrichment digest would make a fresh packet fail
        # its first exact-context resolution as already stale.
        try:
            try:
                graph_revision = str(revision_getter(payload) or "").strip()
            except TypeError:
                graph_revision = str(revision_getter() or "").strip()
        except Exception as exc:
            return unpinned_cognition(f"revision_getter_error:{type(exc).__name__}")
        if not graph_revision:
            return unpinned_cognition("revision_getter_returned_empty")
        execution_scope = recursive_execution_scope()
        execution_scope.update(
            {
                "target_statement": str(
                    execution_scope.get("target_statement")
                    or payload.get("exact_target_statement")
                    or payload.get("target_statement")
                    or ""
                ),
                "statement_identity": str(
                    execution_scope.get("statement_identity")
                    or payload.get("execution_proposition_identity")
                    or payload.get("execution_contract_identity")
                    or payload.get("statement_identity")
                    or ""
                ),
                "environment_hash": str(
                    execution_scope.get("environment_hash")
                    or payload.get("execution_environment_hash")
                    or payload.get("statement_environment_hash")
                    or ""
                ),
                "helper_context_hash": str(
                    execution_scope.get("helper_context_hash")
                    or payload.get("execution_helper_context_hash")
                    or payload.get("helper_context_hash")
                    or ""
                ),
                "graph_revision": graph_revision,
            }
        )
        payload["execution_scope"] = execution_scope
        payload["proof_idea_graph_revision"] = graph_revision

        def currentness_digest(scope_digest_key: str) -> str:
            value = {
                scope_digest_key: str(payload.get(scope_digest_key) or ""),
                "graph_revision": graph_revision,
                "projection_turn_index": int(payload.get("projection_turn_index") or 0),
                "evidence_hash": str(payload.get("evidence_hash") or ""),
                "reopened_by_new_evidence": bool(
                    payload.get("reopened_by_new_evidence")
                ),
            }
            return hashlib.sha256(
                json.dumps(
                    value,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                ).encode("utf-8")
            ).hexdigest()

        payload["execution_currentness_digest"] = currentness_digest(
            "execution_scope_digest",
        )
        payload["cognition_currentness_digest"] = currentness_digest(
            "cognition_scope_digest",
        )
        return payload

    @staticmethod
    def _sanitize_selected_work_record_answer_aliases(
        record: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Migrate generated prompt aliases out of executable work fields.

        Older scheduler records can contain ``solution_ref_hidden_*`` even
        though the proof graph still owns the original
        Lean statement.  Such aliases are display artifacts, never Lean
        declarations.  Blank only executable statement fields so target
        selection can recover from the raw graph under the current visibility
        policy; retain prose fields for ordinary answer-safe rendering.
        """

        payload = dict(record or {})
        generated_alias_removed = False
        executable_fields = (
            "target_statement",
            "exact_target_statement",
            "graph_native_goal_statement",
            "selected_target_statement",
            "repair_goal_statement",
        )

        def sanitize_mapping(value: Dict[str, Any]) -> Dict[str, Any]:
            nonlocal generated_alias_removed
            nested = dict(value or {})
            for executable_field in executable_fields:
                text = str(nested.get(executable_field) or "")
                if text and _GENERATED_SOLUTION_REF_ALIAS_RE.search(text):
                    nested[executable_field] = ""
                    generated_alias_removed = True
            execution_scope = nested.get("execution_scope")
            if isinstance(execution_scope, dict):
                safe_scope = dict(execution_scope)
                scope_target = str(safe_scope.get("target_statement") or "")
                if scope_target and _GENERATED_SOLUTION_REF_ALIAS_RE.search(
                    scope_target
                ):
                    safe_scope["target_statement"] = ""
                    generated_alias_removed = True
                nested["execution_scope"] = safe_scope
            return nested

        payload = sanitize_mapping(payload)
        for nested_field in ("graph_record", "selected_work_item"):
            nested_value = payload.get(nested_field)
            if isinstance(nested_value, dict):
                payload[nested_field] = sanitize_mapping(nested_value)
        if generated_alias_removed:
            payload["target_statement_answer_redacted"] = True
            payload["generated_answer_alias_migrated"] = True
        return payload

    def _set_selected_work_item(self, work_item: Any, action_id: str) -> bool:
        try:
            record = self._stamp_selected_work_graph_revision(
                self._work_item_to_record(work_item)
            )
        except (TypeError, ValueError, AttributeError) as exc:
            # Stale cognition between frontier quotation and dispatch must not
            # abort select_next_action().  Drop this item and let the session
            # choose another piece of work.
            self._record_event(
                {
                    "phase": "selected_work_stamp",
                    "iteration": self.iteration,
                    "action_id": str(action_id or ""),
                    "verdict": "selected_work_graph_revision_invalidated",
                    "projection_error_type": type(exc).__name__,
                    "projection_error": str(exc)[:240],
                }
            )
            self._clear_selected_work_item()
            return False
        selected_action_id = str(action_id or "")
        record["mapped_action_id"] = selected_action_id
        if not self._selected_work_action_compatible(
            selected_action_id,
            record,
        ):
            self._record_event(
                {
                    "phase": "selected_work_capability",
                    "iteration": self.iteration,
                    "action_id": selected_action_id,
                    "work_type": str(record.get("work_type") or ""),
                    "target_resource_kind": (
                        self._selected_work_target_resource_kind(record)
                    ),
                    "context": "frontier_selection",
                    "verdict": "selected_work_action_incompatible",
                }
            )
            self._clear_selected_work_item()
            return False
        if self._selected_work_targets_terminal_graph_work(
            record,
            context="frontier_selection",
            metric_key="mini_session_retired_graph_target_frontier_suppressed",
        ):
            self._clear_selected_work_item()
            return False
        if self._selected_work_record_dispatch_blocked(
            record,
            selected_action_id,
            context="frontier_selection",
        ):
            self._clear_selected_work_item()
            return False
        self.selected_work_item = work_item
        self.selected_work_item_action_id = selected_action_id
        record["mapped_action_id"] = self.selected_work_item_action_id
        self.selected_work_item_record = record
        if (
            record.get("formalization_bridge_support_recorded")
            and record.get("formalization_bridge_parent_work_missing")
            and not record.get("formalization_bridge_parent_work_materialized")
        ):
            node_id = str(
                record.get("node_id")
                or record.get("graph_node_id")
                or record.get("obligation_id")
                or ""
            ).strip()
            reselection_key = (
                str(int(getattr(self, "iteration", 0) or 0)),
                node_id,
                str(record.get("work_type") or ""),
            )
            if reselection_key not in self._bridge_support_reselection_keys:
                self._bridge_support_reselection_keys.add(reselection_key)
                self._increment_dossier_metric(
                    "mini_session_graph_formalization_bridge_support_reselected_without_parent_work",
                    1,
                )
                self._record_event(
                    {
                        "phase": "graph_native_formalization",
                        "iteration": self.iteration,
                        "action_id": self.selected_work_item_action_id,
                        "selected_work_item": dict(record),
                        "node_id": node_id,
                        "work_type": str(record.get("work_type") or ""),
                        "formalization_bridge_parent_work_missing": True,
                        "verdict": (
                            "graph_native_formalization_bridge_support_"
                            "reselected_without_parent_work"
                        ),
                    }
                )
        return True

    def _materialize_work_item_from_record(
        self,
        record: Dict[str, Any],
    ) -> Optional[Any]:
        """Create the scheduler's first-class work item shape from a record."""

        payload = self._sanitize_selected_work_record_answer_aliases(record)
        work_type = str(payload.get("work_type") or "").strip()
        if not work_type:
            return None
        node_id = str(
            payload.get("node_id")
            or payload.get("graph_node_id")
            or payload.get("obligation_id")
            or payload.get("replan_id")
            or payload.get("claim_id")
            or payload.get("variant_id")
            or payload.get("route_id")
            or payload.get("target_id")
            or ""
        ).strip()
        if not node_id:
            node_id = work_type
        graph_record = dict(payload.get("graph_record") or {})
        for key, value in payload.items():
            graph_record.setdefault(key, value)

        def clean_tuple(value: Any) -> Tuple[str, ...]:
            if isinstance(value, str):
                values = [value]
            else:
                try:
                    values = list(value or [])
                except Exception:
                    values = []
            return tuple(
                text for text in (str(item or "").strip() for item in values) if text
            )

        try:
            from ensemble_prover.proof_state import ProofStateWorkItem
        except Exception:
            return payload
        return ProofStateWorkItem(
            node_id=node_id,
            work_type=work_type,
            action=str(payload.get("action") or work_type),
            priority=float(payload.get("priority", 0.0) or 0.0),
            target_hash=str(payload.get("target_hash") or ""),
            blocker=str(payload.get("blocker") or ""),
            dependencies=clean_tuple(payload.get("dependencies")),
            source=str(payload.get("source") or "scheduler_record"),
            graph_node_id=str(payload.get("graph_node_id") or node_id),
            assembly_id=str(payload.get("assembly_id") or ""),
            child_state_node_ids=clean_tuple(payload.get("child_state_node_ids")),
            unblocked_by_graph=bool(payload.get("unblocked_by_graph")),
            reopened_by_new_evidence=bool(payload.get("reopened_by_new_evidence")),
            evidence_hash=str(payload.get("evidence_hash") or ""),
            retrieval_signature=str(payload.get("retrieval_signature") or ""),
            retrieval_context_stamp=str(payload.get("retrieval_context_stamp") or ""),
            retrieved_decl_names_hash=str(
                payload.get("retrieved_decl_names_hash") or ""
            ),
            decl_application_pending_hash=str(
                payload.get("decl_application_pending_hash") or ""
            ),
            helper_acceptance_request_hash=str(
                payload.get("helper_acceptance_request_hash") or ""
            ),
            decl_application_signature=str(
                payload.get("decl_application_signature") or ""
            ),
            proof_stub_hash=str(payload.get("proof_stub_hash") or ""),
            assembly_witness_hash=str(payload.get("assembly_witness_hash") or ""),
            assembly_group_status=str(payload.get("assembly_group_status") or ""),
            projection_turn_index=int(payload.get("projection_turn_index") or 0),
            target_statement=str(payload.get("target_statement") or ""),
            execution_scope_schema_version=int(
                payload.get("execution_scope_schema_version") or 1
            ),
            execution_scope_id=str(payload.get("execution_scope_id") or ""),
            execution_scope_digest=str(payload.get("execution_scope_digest") or ""),
            execution_target_sha256=str(payload.get("execution_target_sha256") or ""),
            execution_target_available=bool(payload.get("execution_target_available")),
            execution_materialization_seed_sha256=str(
                payload.get("execution_materialization_seed_sha256") or ""
            ),
            execution_target_graph_node_id=str(
                payload.get("execution_target_graph_node_id") or ""
            ),
            execution_environment_hash=str(
                payload.get("execution_environment_hash") or ""
            ),
            execution_contract_identity=str(
                payload.get("execution_contract_identity") or ""
            ),
            execution_proposition_identity=str(
                payload.get("execution_proposition_identity") or ""
            ),
            execution_helper_context_hash=str(
                payload.get("execution_helper_context_hash") or ""
            ),
            execution_currentness_digest=str(
                payload.get("execution_currentness_digest") or ""
            ),
            exact_target_statement=str(
                payload.get("exact_target_statement")
                or payload.get("target_statement")
                or ""
            ),
            consumer_bindings=tuple(
                dict(item)
                for item in list(payload.get("consumer_bindings") or [])
                if isinstance(item, Mapping)
            ),
            primary_consumer_binding=dict(
                payload.get("primary_consumer_binding") or {}
            ),
            cognition_scope_digest=str(payload.get("cognition_scope_digest") or ""),
            cognition_currentness_digest=str(
                payload.get("cognition_currentness_digest") or ""
            ),
            obligation_reason=str(payload.get("obligation_reason") or ""),
            source_phase=str(payload.get("source_phase") or ""),
            missing_dependency=str(payload.get("missing_dependency") or ""),
            formalization_required=bool(payload.get("formalization_required")),
            graph_record=graph_record,
        )

    def _restore_selected_work_record(
        self,
        record: Dict[str, Any],
        action_id: str,
        *,
        context: str = "restore_selected_work",
        metric_key: str = "",
        liveness_record: Optional[Dict[str, Any]] = None,
        bypass_dispatch_blocked: bool = False,
    ) -> bool:
        payload = self._sanitize_selected_work_record_answer_aliases(record)
        if not payload:
            return False
        payload = self._refresh_restored_selected_work_cognition(payload)
        selected_action_id = str(action_id or "")
        if selected_action_id and not self._selected_work_action_compatible(
            selected_action_id,
            payload,
        ):
            self._record_event(
                {
                    "phase": "selected_work_capability",
                    "iteration": self.iteration,
                    "action_id": selected_action_id,
                    "work_type": str(payload.get("work_type") or ""),
                    "target_resource_kind": (
                        self._selected_work_target_resource_kind(payload)
                    ),
                    "context": str(context or ""),
                    "verdict": "selected_work_action_incompatible",
                }
            )
            self._clear_selected_work_item()
            return False
        if selected_action_id:
            payload["mapped_action_id"] = selected_action_id
        if self._selected_work_targets_terminal_graph_work(
            dict(liveness_record or payload),
            context=context,
            metric_key=metric_key,
        ):
            self._clear_selected_work_item()
            return False
        if (
            not bypass_dispatch_blocked
            and self._selected_work_record_dispatch_blocked(
                payload,
                selected_action_id,
                context=context,
            )
        ):
            self._clear_selected_work_item()
            return False
        self.selected_work_item = self._materialize_work_item_from_record(payload)
        self.selected_work_item_action_id = selected_action_id
        self.selected_work_item_record = payload
        return True

    def _refresh_restored_selected_work_cognition(
        self,
        record: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Rebind an exact saved cognition packet after graph maintenance.

        Clearing only the revision is safe because exact resolution still
        validates the environment, target, statement identity, proof idea,
        branch, and consumer coordinates.  If any of those changed, the old
        packet is returned and the normal prompt freshness gate fails closed.
        """

        payload = dict(record or {})
        explicit_cognition = selected_work_has_explicit_cognition(payload)
        if not explicit_cognition:
            return payload
        dossier = getattr(self, "dossier", None)
        resolver = getattr(dossier, "resolve_proof_idea_context", None)
        if not callable(resolver):
            return payload
        candidate = copy.deepcopy(payload)
        for layer in selected_work_mapping_layers(candidate):
            if not isinstance(layer, dict):
                continue
            layer.pop("graph_revision", None)
            layer.pop("proof_idea_graph_revision", None)
            execution_scope = layer.get("execution_scope")
            if isinstance(execution_scope, Mapping):
                clean_scope = dict(execution_scope)
                clean_scope["graph_revision"] = ""
                layer["execution_scope"] = clean_scope
        try:
            resolution = resolver(candidate, policy="exact_selected")
        except Exception:
            return payload
        if str(getattr(resolution, "status", "") or "") != "resolved":
            return payload
        try:
            refreshed = self._stamp_selected_work_graph_revision(candidate)
        except (TypeError, ValueError, AttributeError):
            return payload
        return refreshed

    def _capture_policy_repair_redirect_selected_work(self, action_id: str) -> None:
        if self.selected_work_item is None:
            self._clear_policy_repair_redirect_selected_work()
            return
        self.policy_repair_redirect_selected_work_item = self.selected_work_item
        self.policy_repair_redirect_selected_action_id = str(
            action_id or self.selected_work_item_action_id or ""
        )
        record = dict(self.selected_work_item_record)
        if self.policy_repair_redirect_selected_action_id:
            record["mapped_action_id"] = self.policy_repair_redirect_selected_action_id
        self.policy_repair_redirect_selected_record = record

    def _restore_policy_repair_redirect_selected_work(self, action_id: str) -> bool:
        if self.policy_repair_redirect_selected_work_item is None:
            return False
        wanted_action_id = str(action_id or "").strip()
        record = dict(self.policy_repair_redirect_selected_record)
        selected_action_id = (
            wanted_action_id
            or str(self.policy_repair_redirect_selected_action_id or "").strip()
        )
        restored = self._restore_selected_work_record(
            record,
            context="policy_repair_redirect",
            metric_key="mini_session_retired_graph_target_policy_redirect_suppressed",
            action_id=selected_action_id,
        )
        if not restored:
            liveness = self.selected_work_graph_liveness_status(record)
            if not bool(liveness.get("live", False)):
                # A different conversation role may own the same live work,
                # but no role may revive a retired/promoted graph packet.
                self._clear_policy_repair_redirect_selected_work()
            self._clear_selected_work_item()
            return False
        # Persist the refreshed packet and rematerialized work item as the
        # redirect authority too, so a second forced turn cannot resurrect the
        # pre-maintenance graph revision from the original capture.
        self.policy_repair_redirect_selected_work_item = self.selected_work_item
        self.policy_repair_redirect_selected_action_id = selected_action_id
        self.policy_repair_redirect_selected_record = dict(
            self.selected_work_item_record
        )
        return True

    def _clear_policy_repair_redirect_selected_work(self) -> None:
        self.policy_repair_redirect_selected_work_item = None
        self.policy_repair_redirect_selected_action_id = ""
        self.policy_repair_redirect_selected_record = {}

    def _activate_selected_graph_ready_work_item(self, work_item: Any) -> None:
        """Reconcile graph-ready selected work before action applicability.

        ``refresh_graph_readiness`` is best effort. If it failed earlier in
        the selection pass, a graph frontier item may still carry the causal
        proof that a blocked/rejected node is ready. Apply that single-node
        fact before action gates re-check local status.
        """

        if self.proof_state is None or work_item is None:
            return
        graph_ready = bool(
            self._work_item_field(work_item, "unblocked_by_graph", False)
        ) or bool(self._work_item_field(work_item, "reopened_by_new_evidence", False))
        if not graph_ready:
            return
        node_id = str(self._work_item_field(work_item, "node_id", "") or "").strip()
        node = getattr(self.proof_state, "nodes", {}).get(node_id)
        if node is None:
            return
        status = str(getattr(node, "status", "") or "")
        if status not in {"blocked", "rejected"}:
            return
        if status in {"failed", "proved", "obsolete"}:
            return
        try:
            node.status = "open"
            node.blocker = (
                "graph selected work unblocked"
                if bool(self._work_item_field(work_item, "unblocked_by_graph", False))
                else "graph selected work has new evidence"
            )
            priority = getattr(self.proof_state, "_priority", None)
            if callable(priority):
                node.priority = priority(node)
            refresh = getattr(
                self.proof_state, "_refresh_priorities_for_neighbors", None
            )
            if callable(refresh):
                refresh(node_id)
            record_transition = getattr(self.proof_state, "record_transition", None)
            if callable(record_transition):
                record_transition(
                    node_id=node_id,
                    source="proof_graph",
                    error_type="graph_selected_work_reopened",
                    action=str(getattr(node, "action", "") or ""),
                    blocker=str(getattr(node, "blocker", "") or ""),
                    phase="mini_session_select",
                    turn_index=int(self.iteration or 0),
                    payload=dict(self._work_item_to_record(work_item)),
                )
            self._record_event(
                {
                    "phase": "graph_selected_work_activation",
                    "iteration": self.iteration,
                    "node_id": node_id,
                    "work_type": str(
                        self._work_item_field(work_item, "work_type", "") or ""
                    ),
                    "previous_status": status,
                    "verdict": "selected_work_reopened",
                }
            )
        except Exception:
            self._record_event(
                {
                    "phase": "graph_selected_work_activation",
                    "iteration": self.iteration,
                    "node_id": node_id,
                    "verdict": "selected_work_activation_failed",
                }
            )

    def _clear_selected_work_item(self) -> None:
        self.selected_work_item = None
        self.selected_work_item_action_id = ""
        self.selected_work_item_record = {}
        self.selected_frontier_action_key = None

    def _frontier_item_executable_statement(
        self,
        work_item: Any,
        *,
        for_capability: bool = False,
    ) -> str:
        """Return the exact executable graph statement carried by work.

        Ordinary fallback additionally requires a live, already-materialized
        target. Capability resolution asks only whether the exact graph-bound
        resource is a proposition; terminality and materialization remain
        independent dispatch gates.
        """

        work_type = str(self._work_item_field(work_item, "work_type", "") or "").strip()
        if work_type not in {
            "formalize_claim",
            "formalize_missing_obligation",
            "prove_claim_variant",
            "mine_missing_obligation",
            "route_replan",
            "target_integrity_adjudication",
            "materialize_replay_source",
        }:
            return ""
        try:
            from ensemble_prover.proof_graph import (
                graph_node_frontier_promoted_to_proof_state,
                graph_node_frontier_quarantined,
                graph_statement_is_executable,
            )
            from ensemble_prover.proof_dossier import is_answer_unsafe_statement_text
        except Exception:
            return ""
        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if not isinstance(nodes, dict):
            return ""
        root_statement = str(getattr(dossier, "root_statement", "") or "").strip()

        def root_equivalent(statement: str) -> bool:
            if self._answer_visible_solution_statement_allowed(statement):
                return False
            active_targets = self._active_root_target_statements_for_equivalence()
            return bool(
                root_statement
                and graph_statement_root_equivalent(
                    statement,
                    root_statement,
                    active_target_statements=active_targets,
                )
            )

        inline_record = dict(work_item) if isinstance(work_item, dict) else {}
        inline_graph_record = (
            dict(inline_record.get("graph_record") or {})
            if isinstance(inline_record.get("graph_record"), dict)
            else {}
        )
        graph_record = dict(getattr(work_item, "graph_record", None) or {})
        record = {
            **inline_record,
            **inline_graph_record,
            **graph_record,
            **dict(getattr(work_item, "to_record", lambda: {})() or {}),
        }
        target_integrity_root_equiv_allowed = bool(
            record.get("target_integrity_adjudication")
            and record.get("allow_root_equivalent_target_integrity_adjudication")
        )
        if (
            bool(record.get("formalization_required"))
            and work_type not in {"route_replan", "target_integrity_adjudication"}
            and not for_capability
        ):
            return ""
        if work_type == "route_replan":
            obligation_id = str(record.get("obligation_id") or "").strip()
            if not obligation_id:
                replan_id = str(
                    record.get("replan_id")
                    or record.get("graph_node_id")
                    or record.get("node_id")
                    or ""
                ).strip()
                replan_node = nodes.get(replan_id) if replan_id else None
                replan_metadata = (
                    dict(getattr(replan_node, "metadata", {}) or {})
                    if replan_node is not None
                    else {}
                )
                obligation_id = str(
                    replan_metadata.get("obligation_id")
                    or replan_metadata.get("resolved_by_obligation_id")
                    or ""
                ).strip()
            obligation = nodes.get(obligation_id) if obligation_id else None
            if obligation is None:
                return ""
            replan_id = str(
                record.get("replan_id")
                or record.get("graph_node_id")
                or record.get("node_id")
                or ""
            ).strip()
            replan_node = nodes.get(replan_id) if replan_id else None
            if replan_node is not None:
                replan_quarantined = getattr(
                    graph,
                    "replan_queue_item_frontier_quarantined",
                    None,
                )
                if callable(replan_quarantined) and replan_quarantined(replan_node):
                    return ""
                replan_promoted = getattr(
                    graph,
                    "replan_queue_item_frontier_promoted_to_proof_state",
                    None,
                )
                if callable(replan_promoted) and replan_promoted(replan_node):
                    return ""
            if graph_node_frontier_quarantined(
                obligation
            ) or graph_node_frontier_promoted_to_proof_state(obligation):
                return ""
            obligation_metadata = dict(getattr(obligation, "metadata", {}) or {})
            if obligation_metadata.get("formalization_required"):
                return ""
            statement = str(getattr(obligation, "statement", "") or "").strip()
            if is_answer_unsafe_statement_text(
                statement,
                suppress_solution_placeholders=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "suppress_solution_placeholders",
                        True,
                    )
                ),
                opaque_mode=bool(
                    getattr(getattr(self, "conv", None), "opaque_mode", True)
                ),
                allow_official_answer_visibility=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "allow_official_answer_visibility",
                        False,
                    )
                ),
                official_answer_payload_present=getattr(
                    getattr(self, "conv", None),
                    "official_answer_payload_present",
                    getattr(
                        getattr(self, "dossier", None),
                        "official_answer_payload_present",
                        None,
                    ),
                ),
            ):
                return ""
            if root_equivalent(statement):
                return ""
            return statement if graph_statement_is_executable(statement) else ""
        field_order_by_work_type = {
            "formalize_claim": ("claim_id", "graph_node_id", "node_id"),
            "formalize_missing_obligation": (
                "obligation_id",
                "graph_node_id",
                "node_id",
            ),
            "prove_claim_variant": ("variant_id", "graph_node_id", "node_id"),
            "mine_missing_obligation": ("obligation_id", "graph_node_id", "node_id"),
            "route_replan": ("obligation_id", "replan_id", "graph_node_id", "node_id"),
            "target_integrity_adjudication": (
                "obligation_id",
                "graph_node_id",
                "node_id",
            ),
            "materialize_replay_source": ("graph_node_id", "node_id"),
        }
        for node_field in field_order_by_work_type.get(work_type, ()):
            node_id = str(record.get(node_field) or "").strip()
            if not node_id:
                continue
            node = nodes.get(node_id)
            if node is None:
                continue
            if not for_capability and (
                graph_node_frontier_quarantined(node)
                or graph_node_frontier_promoted_to_proof_state(node)
            ):
                continue
            statement = str(getattr(node, "statement", "") or "").strip()
            if is_answer_unsafe_statement_text(
                statement,
                suppress_solution_placeholders=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "suppress_solution_placeholders",
                        True,
                    )
                ),
                opaque_mode=bool(
                    getattr(getattr(self, "conv", None), "opaque_mode", True)
                ),
                allow_official_answer_visibility=bool(
                    getattr(
                        getattr(self, "conv", None),
                        "allow_official_answer_visibility",
                        False,
                    )
                ),
                official_answer_payload_present=getattr(
                    getattr(self, "conv", None),
                    "official_answer_payload_present",
                    getattr(
                        getattr(self, "dossier", None),
                        "official_answer_payload_present",
                        None,
                    ),
                ),
            ):
                continue
            node_metadata = dict(getattr(node, "metadata", {}) or {})
            materialization_root_equiv_allowed = bool(
                work_type == "materialize_replay_source"
                and node_metadata.get("needs_replay_materialization")
            )
            if (
                root_equivalent(statement)
                and not target_integrity_root_equiv_allowed
                and not materialization_root_equiv_allowed
            ):
                continue
            if graph_statement_is_executable(statement):
                return statement
        return ""

    def _frontier_item_targets_dossier_graph_node(self, work_item: Any) -> bool:
        """Return whether a frontier item references this dossier's proof graph."""

        dossier = getattr(self, "dossier", None)
        graph = getattr(dossier, "proof_graph", None) if dossier is not None else None
        nodes = getattr(graph, "nodes", {}) if graph is not None else {}
        if not isinstance(nodes, dict):
            return False
        inline_record = dict(work_item) if isinstance(work_item, dict) else {}
        inline_graph_record = (
            dict(inline_record.get("graph_record") or {})
            if isinstance(inline_record.get("graph_record"), dict)
            else {}
        )
        graph_record = dict(getattr(work_item, "graph_record", None) or {})
        record = {
            **inline_record,
            **inline_graph_record,
            **graph_record,
            **dict(getattr(work_item, "to_record", lambda: {})() or {}),
        }
        for node_field in (
            "obligation_id",
            "graph_node_id",
            "node_id",
            "claim_id",
            "variant_id",
            "replan_id",
            "target_id",
        ):
            node_id = str(record.get(node_field) or "").strip()
            if node_id and node_id in nodes:
                return True
        return False

    def _quote_work_item_action(self, work_item: Any) -> Optional[Action]:
        """Return the action dispatch would choose without changing state.

        This is the scheduler's quotation boundary: ranking may inspect every
        frontier candidate, including candidates that never run.  All mapper
        hooks below receive an explicit probe mode so quotation cannot emit
        durable events, consume keys, initialize action budgets, or reconcile
        proof state.
        """

        return self._map_work_item_to_action(work_item, probe=True)

    def _map_work_item_to_action(
        self,
        work_item: Any,
        *,
        probe: bool = False,
    ) -> Optional[Action]:
        """Map a typed work-frontier item to a registered Action.

        M4 wiring: ``ProofStateWorkItem.work_type`` selects the action class:
        - ``assembly`` → ``InterTurnAssemblyAction``
        - ``lemma_dag_decomposition`` → ``LemmaDagDecomposeAction``
        - ``child_llm_prove`` → ``RecursiveHelperProverAction``
        - ``retrieval`` → ``ProofStateRetrievalAction`` when registered
        - ``decl_probe`` / ``tactic_swarm`` → ``ChildClosureAction``
        - ``root_repair`` → conversation turn against the active root.

        Returns the FIRST registered action whose ``id`` matches and whose
        budget is not exhausted. Returns None if no matching action is
        registered or all candidates are out of budget. ``probe=True`` is a
        read-only quotation used only for ranking; normal dispatch keeps the
        existing cleanup and telemetry behavior.
        """

        work_type = str(self._work_item_field(work_item, "work_type", "") or "")
        if not work_type:
            return None
        if self.repair_policy_narrowing_required and work_type == "root_repair":
            return None

        candidate_ids = self._frontier_candidate_ids_for_work_item(work_item)
        if work_type == "route_replan":
            serviceable, serviceability_status = (
                self._route_replan_serviceability_status(
                    self._work_item_to_record(work_item)
                )
            )
            if not serviceable:
                if not probe:
                    self._increment_dossier_metric(
                        "mini_session_route_replan_unserviceable_skipped",
                        1,
                    )
                    self._record_event(
                        {
                            "phase": "graph_work_frontier",
                            "iteration": self.iteration,
                            "node_id": str(
                                self._work_item_field(work_item, "node_id", "") or ""
                            ),
                            "work_type": work_type,
                            "route_replan_status": dict(serviceability_status),
                            "verdict": "route_replan_unserviceable_skipped",
                        }
                    )
                return None
        if work_type in {
            "mine_missing_obligation",
            "route_replan",
        }:
            # Path B fix (2026-05-18): obligation/replan work types are first
            # offered to graph_recursive_decompose, which invokes
            # ``run_mini_recursive_attempt`` on the obligation's smaller
            # statement. Falls through to graph_native_shortcut (helper-match
            # closure) and conversation_turn_prove (LLM) when the recursive
            # decomposer is unavailable (budget exhausted, depth cap,
            # ancestor cycle, etc.).
            pass
        elif work_type == "root_repair":
            if not bool(getattr(self, "_root_repair_frontier_allowed", False)):
                return None
            route_bound_root_repair = self._root_fairness_frontier_item_is_route_bound(
                work_item
            )
            if probe and not route_bound_root_repair:
                root_authoring_allowed, _status = self._unscoped_root_authoring_allowed(
                    mutate=False
                )
                if not root_authoring_allowed:
                    return None
            elif not route_bound_root_repair and self._suppress_unscoped_root_authoring(
                "conversation_turn_prove",
                context="root_repair_frontier",
            ):
                return None
        elif not candidate_ids:
            return None

        materialization_logical_key = self._frontier_materialization_logical_key(
            work_item
        )
        if (
            any(materialization_logical_key)
            and materialization_logical_key
            in self.materialization_pending_frontier_logical_keys
        ):
            return None

        for candidate_id in candidate_ids:
            if (
                candidate_id == "child_closure"
                and not self._frontier_candidate_available_for_work_item(
                    work_item,
                    candidate_id,
                    mutate=not probe,
                )
            ):
                continue
            action_key = self._frontier_action_key(
                work_item,
                candidate_id,
                probe=probe,
            )
            if (
                action_key in self.consumed_frontier_action_keys
                or action_key in self.skipped_frontier_action_keys
                or action_key in self.model_call_deferred_frontier_action_keys
                # A retryable provider/verifier deferral applies to the
                # action family, not merely the versioned projection that
                # happened to dispatch it.  Proof-state reconciliation can
                # otherwise emit a fresh work-item version immediately and
                # re-enter the same zero-cost failing lane forever.
                or self._model_call_deferred_static_action_blocks_work_item(
                    candidate_id,
                    work_item,
                )
            ):
                continue
            for action in self.actions:
                if action.id != candidate_id:
                    continue
                budget = self.budgets.get(action.id)
                if budget is not None and budget.exhausted():
                    continue
                if action.id in {
                    "domain_theory",
                    "domain_theory_build",
                    "graph_native_shortcut",
                    "graph_recursive_decompose",
                } or bool(getattr(action, "SELECTED_FRONTIER_PRECHECK", False)):
                    # These actions decide is_applicable based on session
                    # state coupled with the candidate work item; pre-check
                    # under a saved-selection scope so a non-applicable
                    # candidate doesn't accidentally pre-claim the work_item
                    # for static-priority fallback dispatch.
                    saved_target = self.selected_work_item
                    saved_action_id = self.selected_work_item_action_id
                    saved_record = dict(self.selected_work_item_record)
                    try:
                        if probe:
                            candidate_record = self._work_item_to_record(work_item)
                            candidate_record["mapped_action_id"] = action.id
                            terminal = (
                                self._selected_work_targets_terminal_graph_work_probe(
                                    candidate_record
                                )
                            )
                            dispatch_blocked = bool(
                                self._selected_work_record_dispatch_block_reason(
                                    candidate_record,
                                    action.id,
                                )
                            )
                            if terminal or dispatch_blocked:
                                continue
                            self.selected_work_item = work_item
                            self.selected_work_item_action_id = action.id
                            self.selected_work_item_record = candidate_record
                        elif not self._set_selected_work_item(work_item, action.id):
                            if any(self._frontier_work_key(work_item)) and not probe:
                                self.skipped_frontier_action_keys.add(action_key)
                            continue
                        applicability_probe = (
                            getattr(action, "frontier_is_applicable_probe", None)
                            if probe
                            else None
                        )
                        if probe and not callable(applicability_probe):
                            # An arbitrary Action.is_applicable method is
                            # mutation-capable by protocol. Only actions that
                            # explicitly implement the observational hook may
                            # participate in scheduler quotation.
                            continue
                        if not self._safe_is_applicable(
                            action,
                            context=(
                                "frontier_candidate_probe"
                                if probe
                                else "frontier_candidate"
                            ),
                            predicate=(
                                applicability_probe
                                if callable(applicability_probe)
                                else None
                            ),
                        ):
                            continue
                    finally:
                        self.selected_work_item = saved_target
                        self.selected_work_item_action_id = saved_action_id
                        self.selected_work_item_record = saved_record
                if (
                    action.id.startswith("conversation_turn")
                    and work_type == "target_integrity_adjudication"
                    and self._frontier_item_targets_dossier_graph_node(work_item)
                    and not self._frontier_item_executable_statement(work_item)
                ):
                    continue
                if (
                    action.id.startswith("conversation_turn")
                    and work_type == "assemble_route"
                    and not self._assemble_route_authoring_ready(
                        work_item,
                        mutate=not probe,
                    )
                ):
                    continue
                if (
                    action.id.startswith("conversation_turn")
                    and work_type
                    in {
                        "formalize_claim",
                        "formalize_missing_obligation",
                        "prove_claim_variant",
                        "mine_missing_obligation",
                        "route_replan",
                        "materialize_replay_source",
                    }
                    and not bool(
                        self._work_item_field(
                            work_item,
                            "formalization_required",
                            False,
                        )
                    )
                    and not self._frontier_item_executable_statement(work_item)
                ):
                    continue
                return action
        return None

    def _record_event(self, record: Dict[str, Any]) -> None:
        """Centralized recorder write — adds session metadata + invokes hook."""

        record = dict(record)
        record.setdefault("session_scope", self.scope)
        record.setdefault("session_activation_id", self.session_activation_id)
        action_dispatch_id = str(self._inflight_action_dispatch_id or "").strip()
        if action_dispatch_id:
            record.setdefault("action_dispatch_id", action_dispatch_id)
        isolated_buffer = getattr(
            self,
            "_isolated_dispatch_event_buffer",
            None,
        )
        if type(isolated_buffer) is list:
            isolated_buffer.append(record)
            return
        recorder = self.recorder
        if recorder is not None and hasattr(recorder, "record_turn"):
            try:
                recorder.record_turn(record)
            except Exception:
                _LOGGER.exception("MiniSession recorder.record_turn raised")
        on_event = self.on_event
        if on_event is not None:
            try:
                on_event(record)
            except Exception:
                _LOGGER.exception("MiniSession on_event raised")
